app.get("/api/notifications", (req, res) => {
  if (!db.notifications) db.notifications = [];
  const { category, severity, unreadOnly, since, limit } = req.query;
  let items = [...db.notifications];
  if (category && category !== "all") {
    items = items.filter(n => n.category === category);
  }
  if (severity && severity !== "all") {
    items = items.filter(n => n.severity === severity);
  }
  if (unreadOnly === "true") {
    items = items.filter(n => !n.read);
  }
  if (since) {
    const sinceDate = new Date(since);
    if (!isNaN(sinceDate.getTime())) {
      items = items.filter(n => new Date(n.createdAt || n.timestamp || 0) >= sinceDate);
    }
  }
  const unreadCount = db.notifications.filter(n => !n.read).length;
  const total = items.length;
  if (limit && Number(limit) > 0) {
    items = items.slice(0, Number(limit));
  }
  res.json({ notifications: items, unreadCount, total });
});

app.get("/api/system/db-status", async (req, res) => {
  let pgStatus = "disconnected";
  let pgError = null;
  let lastSaved = null;
  let directProbe = null;

  const poolStats = pgPool
    ? {
        totalCount: pgPool.totalCount,
        idleCount: pgPool.idleCount,
        waitingCount: pgPool.waitingCount
      }
    : null;

  if (pgPool) {
    if (isPgSaving && lastPersistInfo?.timestamp) {
      pgStatus = "connected";
      lastSaved = lastPersistInfo.timestamp;
    } else {
      try {
        const q = await pgPool.query("SELECT key, updated_at FROM system_store WHERE key = 'db_state'");
        pgStatus = "connected";
        if (q.rows && q.rows[0]) {
          lastSaved = q.rows[0].updated_at;
        }
        if (!pgHydratedSuccessfully && !activeLoadDatabasePromise) {
          loadDatabase().catch(() => {});
        }
      } catch (err) {
        pgStatus = "error";
        pgError = err.message;
      }
    }
  }

  res.json({
    databaseType: pgPool ? "PostgreSQL Cloud (Blindado)" : "Local JSON (Efêmero)",
    pgHost: getMaskedPgHost(),
    pgStatus,
    pgError,
    directProbe,
    poolStats,
    pgHydratedSuccessfully,
    isHydrating: Boolean(activeLoadDatabasePromise),
    lastHydrationError,
    lastPersistInfo,
    lastSaved,
    dbStats: {
      reservationsCount: db.reservations?.length || 0,
      cleaningRequestsCount: db.cleaningRequests?.length || 0,
      flatsCount: db.flats?.length || 0,
      usersCount: db.users?.length || 0,
      notificationsCount: db.notifications?.length || 0
    },
    topCollectionsKB: req.query.breakdown === "1"
      ? Object.entries(db || {})
          .map(([k, v]) => {
            try {
              const kb = Math.round(Buffer.byteLength(JSON.stringify(v) || "", "utf8") / 1024);
              const count = Array.isArray(v) ? v.length : (v && typeof v === "object" ? Object.keys(v).length : 1);
              return { key: k, kb, count };
            } catch {
              return { key: k, kb: 0, count: 0 };
            }
          })
          .filter(x => x.kb > 0)
          .sort((a, b) => b.kb - a.kb)
          .slice(0, 30)
      : undefined
  });
});

