export function getDefaultModulesForRole(role) {
  const normRole = (role || "").toLowerCase().trim();
  switch (normRole) {
    case "dev":
      return [...ALL_CANONICAL_MODULES];
    case "admin":
      return [...OPERATIONAL_MODULES];
    case "anserve_gestor":
      return ["/anserve", "/frigobar-notas", "/frigobar-reposicao"];
    case "anserve_faturamento":
      return ["/frigobar-notas"];
    case "anserve_repositora":
      return ["/frigobar-reposicao"];
    case "recepcao":
    case "reception":
      return [...RECEPCAO_DEFAULT_MODULES];
    case "camareira":
    default:
      return [...CAMAREIRA_DEFAULT_MODULES];
  }
}

