export function ensureSystemUsers(database) {
  if (!database) return false;
  if (!database.users || !Array.isArray(database.users)) {
    database.users = [...defaultUsers];
    return true;
  }

  let changed = false;

  // 1. Migração do usuário 'admin' existente para role: 'dev' (preservando senha existente)
  const adminUser = database.users.find(u => u.username && u.username.toLowerCase() === "admin");
  if (adminUser) {
    if (adminUser.role !== "dev") {
      adminUser.role = "dev";
      adminUser.allowedModules = getDefaultModulesForRole("dev");
      changed = true;
    }
  } else {
    database.users.unshift({
      id: 1,
      username: "admin",
      role: "dev",
      allowedModules: getDefaultModulesForRole("dev"),
      passwordHash: hashPassword("admin123")
    });
    changed = true;
  }

  // 2. Criação/Garantia do usuário 'gestor' (Administração CorpFlats) com role: 'admin'
  const gestorUser = database.users.find(u => u.username && u.username.toLowerCase() === "gestor");
  if (!gestorUser) {
    const maxId = database.users.length > 0 ? Math.max(...database.users.map(u => Number(u.id) || 0)) : 0;
    database.users.push({
      id: Math.max(5, maxId + 1),
      username: "gestor",
      name: "Administração CorpFlats",
      role: "admin",
      passwordHash: hashPassword("admin123"),
      active: true,
      whatsapp: "5522997124021",
      phone: "5522997124021",
      password_updated_at: new Date().toISOString()
    });
    changed = true;
  } else {
    if (gestorUser.role !== "admin") {
      gestorUser.role = "admin";
      changed = true;
    }
    if (!gestorUser.name) {
      gestorUser.name = "Administração CorpFlats";
      changed = true;
    }
  }

  // 3. Garantia do usuário da recepção Soho e fnrhInternalAuditLogs
  const receptionUser = database.users.find(u => u.username && u.username.toLowerCase() === "soho@promenade.com.br");
  if (!receptionUser) {
    const defaultRecPass = process.env.RECEPTION_DEFAULT_PASSWORD || crypto.randomBytes(16).toString("hex");
    database.users.push({
      id: 4,
      username: "Soho@promenade.com.br",
      name: "Recepção Soho",
      role: "recepcao",
      passwordHash: hashPassword(defaultRecPass),
      must_change_password: true,
      password_updated_at: new Date().toISOString()
    });
    changed = true;
  }
  if (!Array.isArray(database.fnrhInternalAuditLogs)) {
    database.fnrhInternalAuditLogs = [];
  }

  // 4. Garantia dos usuários operacionais da Anserve (Repositora e Supervisão)
  const repositoraUser = database.users.find(u => u.username && u.username.toLowerCase() === "repositora");
  if (!repositoraUser) {
    const maxId = database.users.length > 0 ? Math.max(...database.users.map(u => Number(u.id) || 0)) : 0;
    database.users.push({
      id: Math.max(10, maxId + 1),
      username: "repositora",
      name: "Repositora Anserve",
      role: "anserve_repositora",
      allowedModules: getDefaultModulesForRole("anserve_repositora"),
      passwordHash: hashPassword("1234"),
      active: true,
      whatsapp: "5522997124021",
      phone: "5522997124021"
    });
    changed = true;
  }
  const anserveGestorUser = database.users.find(u => u.username && u.username.toLowerCase() === "anserve_gestor");
  if (!anserveGestorUser) {
    const maxId = database.users.length > 0 ? Math.max(...database.users.map(u => Number(u.id) || 0)) : 0;
    database.users.push({
      id: Math.max(11, maxId + 1),
      username: "anserve_gestor",
      name: "Supervisão Anserve",
      role: "anserve_gestor",
      allowedModules: getDefaultModulesForRole("anserve_gestor"),
      passwordHash: hashPassword("anserve123"),
      active: true,
      whatsapp: "5522997124021",
      phone: "5522997124021"
    });
    changed = true;
  }

  // 5. Garantia de allowedModules para todos os usuários da base + migração automática dos módulos de Frigobar/Anserve
  for (const u of database.users) {
    if (!Array.isArray(u.allowedModules)) {
      u.allowedModules = getDefaultModulesForRole(u.role);
      changed = true;
    } else if (u.role === "dev" || u.role === "admin") {
      for (const reqMod of ["/frigobar", "/anserve", "/frigobar-reposicao", "/frigobar-gestao"]) {
        if (!u.allowedModules.includes(reqMod)) {
          u.allowedModules.push(reqMod);
          changed = true;
        }
      }
    } else if (u.role === "anserve_gestor") {
      for (const reqMod of ["/anserve", "/frigobar-reposicao", "/frigobar-gestao"]) {
        if (!u.allowedModules.includes(reqMod)) {
          u.allowedModules.push(reqMod);
          changed = true;
        }
      }
    } else if (u.role === "anserve_repositora") {
      if (!u.allowedModules.includes("/frigobar-reposicao")) {
        u.allowedModules.push("/frigobar-reposicao");
        changed = true;
      }
    }
  }

  return changed;
}

