export function seedInitialFaqItems(dbInstance) {
  if (!dbInstance) return false;
  if (!Array.isArray(dbInstance.faqItems)) {
    dbInstance.faqItems = [];
  }
  const seeds = getOfficialFaqSeed();
  if (dbInstance.faqItems.length === 0) {
    dbInstance.faqItems = seeds.map(s => ({ ...s }));
    return true;
  }
  let modified = false;
  for (const s of seeds) {
    const existing = dbInstance.faqItems.find(item => item.id === s.id);
    if (!existing) {
      dbInstance.faqItems.push({ ...s });
      modified = true;
    } else if (
      (s.id === "faq-agua-frigobar" && (existing.answer?.includes("vazio") || existing.answer?.includes("Não disponibilizamos água"))) ||
      (s.id === "faq-regras-pets" && (existing.answer?.includes("1 cachorro") || existing.answer?.includes("por dia") || existing.answer?.includes("diária") || existing.answer?.includes("R$ 80"))) ||
      (s.id === "faq-approval-jacuzzi-aquecida" && (
        existing.question?.toLowerCase().includes("piscina") ||
        (existing.answer?.toLowerCase().includes("piscina") && !existing.answer?.toLowerCase().includes("não temos piscina") && !existing.answer?.toLowerCase().includes("não possui piscina"))
      )) ||
      (s.id === "faq-cafe-quarto" && (existing.answer?.includes("06:30") || existing.answer?.includes("07:00"))) ||
      (s.id === "faq-regras-visitas" && Array.isArray(existing.variations) && existing.variations.some(v => String(v).includes("piscina")))
    ) {
      existing.question = s.question;
      existing.answer = s.answer;
      existing.keywords = s.keywords;
      existing.variations = s.variations;
      modified = true;
    }
  }
  return modified;
}

let isUniversalIntegrityDirty = true;
let lastUniversalIntegrityTimestamp = 0;
const UNIVERSAL_INTEGRITY_COOLDOWN_MS = 30000;

export function markUniversalIntegrityDirty() {
  isUniversalIntegrityDirty = true;
}

export function reconcileUniversalIntegrity(incomingState = null) {
  const force = arguments.length > 1 ? Boolean(arguments[1]) : false;
  const isDirty = (typeof isUniversalIntegrityDirty !== "undefined") ? isUniversalIntegrityDirty : true;
  const lastTs = (typeof lastUniversalIntegrityTimestamp !== "undefined") ? lastUniversalIntegrityTimestamp : 0;
  const now = Date.now();
  if (!incomingState && !force && !isDirty && (now - lastTs < UNIVERSAL_INTEGRITY_COOLDOWN_MS)) {
    return false;
  }

  if (!db.flats) db.flats = [];
  if (!db.reservations) db.reservations = [];
  if (!db.cleaningRequests) db.cleaningRequests = [];
  if (!db.guests) db.guests = [];
  if (!db.faqItems) db.faqItems = [];
  let changed = false;

  // 1. União Bidirecional Não-Destrutiva (Merge de Nuvem PostgreSQL e Disco Local)
  if (incomingState && typeof incomingState === "object") {
    // 1.1 Flats
    if (Array.isArray(incomingState.flats) && incomingState.flats.length > 0) {
      incomingState.flats.forEach(incFlat => {
        const existing = db.flats.find(f => String(f.number) === String(incFlat.number) || f.id === incFlat.id);
        if (!existing) {
          db.flats.push({ ...incFlat });
          changed = true;
        } else if (incFlat.isActive !== undefined && existing.isActive === undefined) {
          existing.isActive = incFlat.isActive;
        }
      });
    }

    // 1.2 Hóspedes
    if (Array.isArray(incomingState.guests)) {
      incomingState.guests.forEach(incGuest => {
        const existing = db.guests.find(g =>
          g.id === incGuest.id ||
          (g.guestCode && incGuest.guestCode && g.guestCode === incGuest.guestCode) ||
          (g.document && incGuest.document && g.document.replace(/\D/g, '') === incGuest.document.replace(/\D/g, ''))
        );
        if (!existing) {
          db.guests.push({ ...incGuest });
          changed = true;
        }
      });
    }

    // 1.3 Reservas (União estrita e NÃO-DESTRUTIVA para TODOS os flats)
    // Regra de Ouro Anti-Perda: NUNCA fundir ou sobrescrever reservas apenas por coincidência de flat e datas!
    // Coincidência de quarto e datas representa conflito/overbooking real, NUNCA a mesma reserva.
    if (Array.isArray(incomingState.reservations)) {
      incomingState.reservations.forEach(incRes => {
        const existingIdx = db.reservations.findIndex(r => {
          if (r.id && incRes.id && Number(r.id) === Number(incRes.id)) return true;
          if (r.code && incRes.code && r.code.toUpperCase() === incRes.code.toUpperCase()) return true;
          return false;
        });
        if (existingIdx === -1) {
          db.reservations.push({ ...incRes });
          changed = true;
        } else {
          const existing = db.reservations[existingIdx];
          const incDate = incRes.updatedAt || incRes.createdAt || "";
          const curDate = existing.updatedAt || existing.createdAt || "";
          const existingGuest = (existing.guestName || "").trim().toLowerCase();
          const incGuest = (incRes.guestName || "").trim().toLowerCase();

          // Se os nomes dos hóspedes forem incompatíveis e ambos existirem, blindagem total: NÃO sobrescrever!
          if (existingGuest && incGuest && existingGuest !== incGuest && Number(existing.id) !== Number(incRes.id)) {
            return;
          }

          if (incDate > curDate) {
            // Preserva alterações operacionais em tempo real feitas em produção (datas e status)
            const savedCheckin = existing.checkinDate;
            const savedCheckout = existing.checkoutDate;
            const savedStatus = existing.status;
            const merged = { ...existing, ...incRes };
            if (savedCheckin && savedCheckout) {
              merged.checkinDate = savedCheckin;
              merged.checkoutDate = savedCheckout;
              merged.status = savedStatus || merged.status;
            }
            if (!merged.guestName && existing.guestName) merged.guestName = existing.guestName;
            if (!merged.guestPhone && existing.guestPhone) merged.guestPhone = existing.guestPhone;
            if (!merged.guestDocument && existing.guestDocument) merged.guestDocument = existing.guestDocument;
            db.reservations[existingIdx] = merged;
            changed = true;
          }
        }
      });
    }

    // 1.4 Limpezas (União estrita para TODOS os flats)
    if (Array.isArray(incomingState.cleaningRequests)) {
      const validFlatNumsMerge = new Set((db.flats || []).map(f => String(f.number)).filter(Boolean));
      const validFlatIdsMerge = new Set((db.flats || []).map(f => Number(f.id)).filter(Boolean));
      incomingState.cleaningRequests.forEach(incReq => {
        if (!incReq || String(incReq.flatNumber) === "502" || incReq.flatId === 9) return;
        if (incReq.source === "service_order" && (!incReq.serviceOrderId || String(incReq.requestDate || "") <= "2026-10-15")) return;
        if (validFlatNumsMerge.size > 0) {
          const isRealFlat = (incReq.flatNumber && validFlatNumsMerge.has(String(incReq.flatNumber))) || (incReq.flatId && validFlatIdsMerge.has(Number(incReq.flatId)));
          if (!isRealFlat) return;
        }
        const incIsInst = Boolean(incReq.isInstructionOnly || incReq.source === "manual_instruction" || incReq.type === "instruction" || incReq.type === "bed_adjustment_only" || incReq.isBedAdjustmentOnly);
        const existingIdx = db.cleaningRequests.findIndex(c => {
          if (c.id && incReq.id && Number(c.id) === Number(incReq.id)) return true;
          const cIsInst = Boolean(c.isInstructionOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only" || c.isBedAdjustmentOnly);
          if (incIsInst !== cIsInst) return false;
          if (incIsInst) return false; // Instruções são sempre cartões avulsos independentes
          return (String(c.flatNumber) === String(incReq.flatNumber) && c.requestDate === incReq.requestDate);
        });
        if (existingIdx === -1) {
          db.cleaningRequests.push({ ...incReq });
          changed = true;
        } else {
          const cur = db.cleaningRequests[existingIdx];
          const incDate = incReq.updatedAt || incReq.createdAt || "";
          const curDate = cur.updatedAt || cur.createdAt || "";
          const curIsDeleted = Boolean(cur.isDeleted || cur.status === "deleted");
          const incIsDeleted = Boolean(incReq.isDeleted || incReq.status === "deleted");
          const curRevertedAfterIncClean = Boolean(
            cur.status === "dirty" &&
            cur.revertedToDirtyAt &&
            (!incReq.completedAt || cur.revertedToDirtyAt >= incReq.completedAt)
          );
          const incRevertedAfterCurClean = Boolean(
            incReq.status === "dirty" &&
            incReq.revertedToDirtyAt &&
            (!cur.completedAt || incReq.revertedToDirtyAt >= cur.completedAt)
          );
          if (curIsDeleted && !incIsDeleted) {
            const delAt = cur.deletedAt || curDate;
            if (incDate && delAt && incDate > delAt) {
              db.cleaningRequests[existingIdx] = { ...cur, ...incReq, isDeleted: false };
              delete db.cleaningRequests[existingIdx].deletedAt;
              delete db.cleaningRequests[existingIdx].deletedBy;
              delete db.cleaningRequests[existingIdx].deletedReservationId;
              changed = true;
            }
          } else if (curRevertedAfterIncClean) {
            // Preserva a devolução manual mais recente (status: "dirty") sobre estado anterior "clean"
          } else if (
            incRevertedAfterCurClean ||
            (incIsDeleted && !curIsDeleted && (!curDate || (incReq.deletedAt || incDate) >= curDate)) ||
            (incReq.status === "clean" && cur.status !== "clean") ||
            (incReq.status === "no_show" && cur.status !== "no_show") ||
            (incReq.status === "extended" && cur.status !== "extended") ||
            (incReq.assignedUserId && !cur.assignedUserId) ||
            (incDate > curDate)
          ) {
            db.cleaningRequests[existingIdx] = { ...cur, ...incReq };
            changed = true;
          }
        }
      });
    }

    // 1.5 Pedidos de Café da Manhã & Tarefas Preventivas
    if (Array.isArray(incomingState.breakfastOrders)) {
      incomingState.breakfastOrders.forEach(incOrder => {
        const existing = (db.breakfastOrders || []).find(o => o.id === incOrder.id);
        if (!existing) {
          if (!db.breakfastOrders) db.breakfastOrders = [];
          db.breakfastOrders.push({ ...incOrder });
          changed = true;
        }
      });
    }

    // 1.6 Pagamentos de Camareiras e Conta Corrente (Não-Destrutivo)
    if (Array.isArray(incomingState.maidPayments) && incomingState.maidPayments.length > 0) {
      if (!db.maidPayments) db.maidPayments = [];
      incomingState.maidPayments.forEach(incPay => {
        if (!db.maidPayments.some(p => p.id === incPay.id)) {
          db.maidPayments.push({ ...incPay });
          changed = true;
        }
      });
    }

    if (Array.isArray(incomingState.maidStatementEntries) && incomingState.maidStatementEntries.length > 0) {
      if (!db.maidStatementEntries) db.maidStatementEntries = [];
      incomingState.maidStatementEntries.forEach(incEntry => {
        if (!db.maidStatementEntries.some(e => e.id === incEntry.id)) {
          db.maidStatementEntries.push({ ...incEntry });
          changed = true;
        }
      });
    }

    // 1.7 Achados e Perdidos (Não-Destrutivo)
    if (Array.isArray(incomingState.lostAndFound) && incomingState.lostAndFound.length > 0) {
      if (!db.lostAndFound) db.lostAndFound = [];
      incomingState.lostAndFound.forEach(incItem => {
        if (!db.lostAndFound.some(i => i.id === incItem.id)) {
          db.lostAndFound.push({ ...incItem });
          changed = true;
        }
      });
    }

    // 1.8 Empresas Parceiras (PJ) (Não-Destrutivo)
    if (Array.isArray(incomingState.companies) && incomingState.companies.length > 0) {
      if (!db.companies) db.companies = [];
      incomingState.companies.forEach(incComp => {
        const cleanIncCnpj = (incComp.cnpj || "").replace(/\D/g, "");
        const existing = db.companies.find(c =>
          (c.id && incComp.id && Number(c.id) === Number(incComp.id)) ||
          (cleanIncCnpj && cleanIncCnpj.length >= 8 && (c.cnpj || "").replace(/\D/g, "") === cleanIncCnpj) ||
          (c.corporateName && incComp.corporateName && c.corporateName.trim().toLowerCase() === incComp.corporateName.trim().toLowerCase())
        );
        if (!existing) {
          db.companies.push({ ...incComp });
          changed = true;
        } else {
          const incDate = incComp.updatedAt || incComp.createdAt || "";
          const curDate = existing.updatedAt || existing.createdAt || "";
          if (incDate > curDate) {
            Object.assign(existing, incComp);
            changed = true;
          }
        }
      });
    }

    // 1.8b Agências de Viagens e Turismo (PJ / B2B) (Não-Destrutivo)
    if (Array.isArray(incomingState.agencies) && incomingState.agencies.length > 0) {
      if (!db.agencies) db.agencies = [];
      incomingState.agencies.forEach(incAg => {
        const cleanIncCnpj = (incAg.cnpj || "").replace(/\D/g, "");
        const existing = db.agencies.find(a =>
          (a.id && incAg.id && Number(a.id) === Number(incAg.id)) ||
          (cleanIncCnpj && cleanIncCnpj.length >= 8 && (a.cnpj || "").replace(/\D/g, "") === cleanIncCnpj) ||
          (a.corporateName && incAg.corporateName && a.corporateName.trim().toLowerCase() === incAg.corporateName.trim().toLowerCase()) ||
          (a.tradeName && incAg.tradeName && a.tradeName.trim().toLowerCase() === incAg.tradeName.trim().toLowerCase())
        );
        if (!existing) {
          db.agencies.push({ ...incAg });
          changed = true;
        } else {
          const incDate = incAg.updatedAt || incAg.createdAt || "";
          const curDate = existing.updatedAt || existing.createdAt || "";
          if (incDate > curDate) {
            Object.assign(existing, incAg);
            changed = true;
          }
        }
      });
    }

    if (ensureB2bSeedData(db)) {
      changed = true;
    }

    // 1.9 Histórico de WhatsApp (Não-Destrutivo / Blindado contra perdas em deploy)
    if (Array.isArray(incomingState.whatsappHistory) && incomingState.whatsappHistory.length > 0) {
      if (!db.whatsappHistory) db.whatsappHistory = [];
      incomingState.whatsappHistory.forEach(incItem => {
        const exists = db.whatsappHistory.some(h =>
          (h.id && incItem.id && h.id === incItem.id) ||
          (h.reservationCode && incItem.reservationCode && h.reservationCode === incItem.reservationCode && h.triggerEvent === incItem.triggerEvent && h.sentAt === incItem.sentAt) ||
          (h.message && incItem.message && h.message === incItem.message && h.sentAt === incItem.sentAt)
        );
        if (!exists) {
          db.whatsappHistory.push({ ...incItem });
          changed = true;
        }
      });
    }

    // 1.10 Fila de WhatsApp (Não-Destrutivo)
    if (Array.isArray(incomingState.whatsappQueue) && incomingState.whatsappQueue.length > 0) {
      if (!db.whatsappQueue) db.whatsappQueue = [];
      incomingState.whatsappQueue.forEach(incQ => {
        const exists = db.whatsappQueue.some(q =>
          (q.id && incQ.id && q.id === incQ.id) ||
          (q.reservationCode && incQ.reservationCode && q.reservationCode === incQ.reservationCode && q.triggerEvent === incQ.triggerEvent)
        );
        if (!exists) {
          db.whatsappQueue.push({ ...incQ });
          changed = true;
        }
      });
    }

    // 1.11 Conversas do Chat de WhatsApp (Não-Destrutivo)
    if (Array.isArray(incomingState.whatsappConversations) && incomingState.whatsappConversations.length > 0) {
      if (!db.whatsappConversations) db.whatsappConversations = [];
      incomingState.whatsappConversations.forEach(incConv => {
        const cleanIncPhone = String(incConv.phone || "").replace(/\D/g, "");
        const existingConv = db.whatsappConversations.find(c => {
          const cPhone = String(c.phone || "").replace(/\D/g, "");
          return (c.id && incConv.id && c.id === incConv.id) || (cleanIncPhone && cPhone && (cleanIncPhone === cPhone || cleanIncPhone.endsWith(cPhone) || cPhone.endsWith(cleanIncPhone)));
        });
        if (!existingConv) {
          db.whatsappConversations.push({ ...incConv });
          changed = true;
        } else if (Array.isArray(incConv.messages) && incConv.messages.length > 0) {
          if (!Array.isArray(existingConv.messages)) existingConv.messages = [];
          incConv.messages.forEach(incMsg => {
            const msgExists = existingConv.messages.some(m =>
              (m.id && incMsg.id && m.id === incMsg.id) ||
              (m.messageId && incMsg.messageId && m.messageId === incMsg.messageId) ||
              (m.timestamp === incMsg.timestamp && m.text === incMsg.text)
            );
            if (!msgExists) {
              existingConv.messages.push(incMsg);
              changed = true;
            }
          });
        }
      });
    }

    // 1.12 Base de Conhecimento e FAQ (União não-destrutiva por ID com resolução por data)
    if (Array.isArray(incomingState.faqItems) && incomingState.faqItems.length > 0) {
      if (!db.faqItems) db.faqItems = [];
      incomingState.faqItems.forEach(incFaq => {
        if (!incFaq || !incFaq.id) return;
        const existingIdx = db.faqItems.findIndex(f => f.id === incFaq.id);
        if (existingIdx === -1) {
          db.faqItems.push({ ...incFaq });
          changed = true;
        } else {
          const existing = db.faqItems[existingIdx];
          const incDate = incFaq.updatedAt || incFaq.createdAt || "";
          const curDate = existing.updatedAt || existing.createdAt || "";
          if (incDate > curDate) {
            db.faqItems[existingIdx] = { ...existing, ...incFaq };
            changed = true;
          }
        }
      });
    }

    // 1.13 Ordens de Serviço (União não-destrutiva por Ordem e por Apartamento)
    if (Array.isArray(incomingState.serviceOrders) && incomingState.serviceOrders.length > 0) {
      if (!db.serviceOrders) db.serviceOrders = [];
      const deletedOrderIds = new Set(Array.isArray(db._deletedServiceOrderIds) ? db._deletedServiceOrderIds.map(String) : []);
      const flatStatusRank = { pending: 0, in_progress: 1, done: 2 };
      incomingState.serviceOrders.forEach(incOrder => {
        if (!incOrder || !incOrder.id) return;
        if (deletedOrderIds.has(String(incOrder.id))) return;
        const existingIdx = db.serviceOrders.findIndex(o => o.id === incOrder.id || o.token === incOrder.token);
        if (existingIdx === -1) {
          db.serviceOrders.push({ ...incOrder });
          changed = true;
        } else {
          const existing = db.serviceOrders[existingIdx];
          const incDate = incOrder.updatedAt || incOrder.createdAt || "";
          const curDate = existing.updatedAt || existing.createdAt || "";
          const mergedFlats = Array.isArray(existing.flats) ? existing.flats.map(f => ({ ...f })) : [];
          if (Array.isArray(incOrder.flats)) {
            for (const incF of incOrder.flats) {
              const eIdx = mergedFlats.findIndex(
                ef => Number(ef.flatId) === Number(incF.flatId) || String(ef.flatNumber) === String(incF.flatNumber)
              );
              if (eIdx === -1) {
                mergedFlats.push({ ...incF });
                changed = true;
              } else {
                const curF = mergedFlats[eIdx];
                const curRank = flatStatusRank[curF.status] ?? 0;
                const incRank = flatStatusRank[incF.status] ?? 0;
                const curActivityAt = [curF.finishedAt, curF.startedAt, curF.resetAt, curF.returnedAt, curF.forceReleasedUpdatedAt].filter(Boolean).sort().pop() || "";
                const incActivityAt = [incF.finishedAt, incF.startedAt, incF.resetAt, incF.returnedAt, incF.forceReleasedUpdatedAt].filter(Boolean).sort().pop() || "";
                const curResetOrReturnAt = [curF.resetAt, curF.returnedAt].filter(Boolean).sort().pop() || "";
                const incResetOrReturnAt = [incF.resetAt, incF.returnedAt].filter(Boolean).sort().pop() || "";
                const curExecAt = [curF.finishedAt, curF.startedAt].filter(Boolean).sort().pop() || "";
                const incExecAt = [incF.finishedAt, incF.startedAt].filter(Boolean).sort().pop() || "";
                const curResetIsNewer = Boolean(
                  (curResetOrReturnAt && (!incExecAt || curResetOrReturnAt > incExecAt) && (!incResetOrReturnAt || curResetOrReturnAt >= incResetOrReturnAt)) ||
                  (curF.status === "pending" && incF.status === "in_progress" && !incF.finishedAt && curF.workerNotifiedAvailableAt && incF.startedAt && curF.workerNotifiedAvailableAt > incF.startedAt) ||
                  (curF.status === "in_progress" && curF.startedAt && incF.finishedAt && curF.startedAt > incF.finishedAt)
                );
                const incResetIsNewer = Boolean(
                  (incResetOrReturnAt && (!curExecAt || incResetOrReturnAt > curExecAt) && (!curResetOrReturnAt || incResetOrReturnAt > curResetOrReturnAt)) ||
                  (incF.status === "pending" && curF.status === "in_progress" && !curF.finishedAt && incF.workerNotifiedAvailableAt && curF.startedAt && incF.workerNotifiedAvailableAt > curF.startedAt) ||
                  (incF.status === "in_progress" && incF.startedAt && curF.finishedAt && incF.startedAt > curF.finishedAt)
                );

                if (incResetIsNewer) {
                  const nextF = { ...curF, ...incF };
                  if (nextF.status === "pending") {
                    nextF.startedAt = null;
                    nextF.finishedAt = null;
                    nextF.resetAt = incF.resetAt || incF.workerNotifiedAvailableAt || curF.resetAt || null;
                    nextF.estimatedFinishAt = null;
                    nextF.workerName = null;
                    nextF.workerCpf = null;
                    nextF.entryRequested = Boolean(incF.entryRequested);
                    nextF.entryRequestedAt = incF.entryRequested ? (incF.entryRequestedAt || null) : null;
                    nextF.delayNotified = false;
                    nextF.forceReleased = false;
                    nextF.forceReleasedDate = null;
                    nextF.forceReleasedScenario = null;
                    if (incF.resetAt && (!incF.workerNotifiedAvailableAt || incF.workerNotifiedAvailableAt <= incF.resetAt)) {
                      nextF.workerNotifiedAvailable = false;
                      nextF.workerNotifiedAvailableAt = null;
                    }
                  }
                  mergedFlats[eIdx] = nextF;
                  changed = true;
                } else if (curResetIsNewer) {
                  if (curF.status === "pending") {
                    if (!curF.resetAt && curF.workerNotifiedAvailableAt && !curF.returnedAt) {
                      curF.resetAt = curF.workerNotifiedAvailableAt;
                      changed = true;
                    }
                    if (curF.startedAt || curF.estimatedFinishAt || curF.workerName || curF.workerCpf || curF.delayNotified || curF.forceReleased) {
                      curF.startedAt = null;
                      curF.finishedAt = null;
                      curF.estimatedFinishAt = null;
                      curF.workerName = null;
                      curF.workerCpf = null;
                      curF.delayNotified = false;
                      curF.forceReleased = false;
                      curF.forceReleasedDate = null;
                      curF.forceReleasedScenario = null;
                      changed = true;
                    }
                    if (curF.resetAt && curF.workerNotifiedAvailableAt && curF.workerNotifiedAvailableAt <= curF.resetAt) {
                      curF.workerNotifiedAvailable = false;
                      curF.workerNotifiedAvailableAt = null;
                      changed = true;
                    }
                  }
                } else {
                  if (incRank > curRank) {
                    mergedFlats[eIdx] = { ...curF, ...incF };
                    changed = true;
                  } else if (incRank === curRank && (incActivityAt > curActivityAt || incDate > curDate)) {
                    mergedFlats[eIdx] = { ...curF, ...incF };
                    changed = true;
                  }
                }

                // Preserva forceReleased somente se foi liberado explicitamente hoje (> 2026-11-06T18:00:00.000Z) para o cenário atual
                const targetF = mergedFlats[eIdx];
                const latestResetOrReturn = [targetF.resetAt, targetF.returnedAt].filter(Boolean).sort().pop() || "";
                const curForceAt = curF.forceReleasedUpdatedAt || "";
                const incForceAt = incF.forceReleasedUpdatedAt || "";
                if (curForceAt || incForceAt) {
                  const winForceSource = curForceAt >= incForceAt ? curF : incF;
                  const winForceAt = winForceSource.forceReleasedUpdatedAt || "";
                  if (
                    targetF.status === "pending" &&
                    winForceSource.forceReleased === true &&
                    winForceAt > "2026-11-06T18:00:00.000Z" &&
                    winForceSource.forceReleasedDate === getTodayStr() &&
                    winForceSource.forceReleasedScenario &&
                    (!latestResetOrReturn || winForceAt > latestResetOrReturn)
                  ) {
                    targetF.forceReleased = true;
                    targetF.forceReleasedUpdatedAt = winForceAt;
                    targetF.forceReleasedDate = winForceSource.forceReleasedDate;
                    targetF.forceReleasedScenario = winForceSource.forceReleasedScenario;
                    targetF.forceReleasedBy = winForceSource.forceReleasedBy || null;
                  } else if (targetF.forceReleased) {
                    targetF.forceReleased = false;
                    targetF.forceReleasedDate = null;
                    targetF.forceReleasedScenario = null;
                    changed = true;
                  }
                } else if (targetF.forceReleased) {
                  targetF.forceReleased = false;
                  targetF.forceReleasedDate = null;
                  targetF.forceReleasedScenario = null;
                  changed = true;
                }

                // Preserva fotos, fotos pré-enviadas e observações caso uma das fontes seja mais rica
                if (targetF.status === "done") {
                  const richPhotos = (Array.isArray(targetF.photos) && targetF.photos.length > 0)
                    ? targetF.photos
                    : ((Array.isArray(curF.photos) && curF.photos.length > 0) ? curF.photos : (Array.isArray(incF.photos) ? incF.photos : []));
                  if (richPhotos.length > 0 && (!Array.isArray(targetF.photos) || targetF.photos.length === 0)) {
                    targetF.photos = [...richPhotos];
                    changed = true;
                  }
                  if (!targetF.observations && (curF.observations || incF.observations)) {
                    targetF.observations = curF.observations || incF.observations;
                    changed = true;
                  }
                  if (targetF.needsCleaning === null || targetF.needsCleaning === undefined) {
                    if (typeof curF.needsCleaning === "boolean") targetF.needsCleaning = curF.needsCleaning;
                    else if (typeof incF.needsCleaning === "boolean") targetF.needsCleaning = incF.needsCleaning;
                  }
                  if (targetF.wasCleanWhenStarted === null || targetF.wasCleanWhenStarted === undefined) {
                    if (typeof curF.wasCleanWhenStarted === "boolean") targetF.wasCleanWhenStarted = curF.wasCleanWhenStarted;
                    else if (typeof incF.wasCleanWhenStarted === "boolean") targetF.wasCleanWhenStarted = incF.wasCleanWhenStarted;
                  }
                }
                if (Array.isArray(incF.uploadedPhotos) && incF.uploadedPhotos.length > 0) {
                  const existingUp = Array.isArray(targetF.uploadedPhotos) ? targetF.uploadedPhotos : [];
                  const combinedUp = Array.from(new Set([...existingUp, ...incF.uploadedPhotos]));
                  if (combinedUp.length !== existingUp.length) {
                    targetF.uploadedPhotos = combinedUp;
                    changed = true;
                  }
                }
                if (
                  incF.workerNotifiedAvailable &&
                  !targetF.workerNotifiedAvailable &&
                  !curResetIsNewer &&
                  !incResetIsNewer &&
                  (!latestResetOrReturn || (incF.workerNotifiedAvailableAt && incF.workerNotifiedAvailableAt > latestResetOrReturn))
                ) {
                  targetF.workerNotifiedAvailable = true;
                  targetF.workerNotifiedAvailableAt = incF.workerNotifiedAvailableAt || targetF.workerNotifiedAvailableAt;
                  targetF.workerLastNotifiedPhone = incF.workerLastNotifiedPhone || targetF.workerLastNotifiedPhone;
                  changed = true;
                }
              }
            }
          }
          if (incDate > curDate) {
            db.serviceOrders[existingIdx] = { ...existing, ...incOrder, flats: mergedFlats };
            changed = true;
          } else {
            existing.flats = mergedFlats;
          }
        }
      });
    }

    // 1.14 Prestadores de Serviço (União não-destrutiva)
    if (Array.isArray(incomingState.serviceWorkers) && incomingState.serviceWorkers.length > 0) {
      if (!db.serviceWorkers) db.serviceWorkers = [];
      incomingState.serviceWorkers.forEach(incWorker => {
        if (!incWorker || !incWorker.id) return;
        const existingIdx = db.serviceWorkers.findIndex(w => w.id === incWorker.id || (w.token && w.token === incWorker.token));
        if (existingIdx === -1) {
          db.serviceWorkers.push({ ...incWorker });
          changed = true;
        } else {
          const existing = db.serviceWorkers[existingIdx];
          const incDate = incWorker.registeredAt || "";
          const curDate = existing.registeredAt || "";
          if (incDate > curDate) {
            db.serviceWorkers[existingIdx] = { ...existing, ...incWorker };
            changed = true;
          }
        }
      });
    }

    // 1.15 Diário dos Flats e Catálogo de Serviços (União não-destrutiva)
    if (Array.isArray(incomingState.flatDiaryEntries) && incomingState.flatDiaryEntries.length > 0) {
      if (!Array.isArray(db.flatDiaryEntries)) db.flatDiaryEntries = [];
      incomingState.flatDiaryEntries.forEach(incEntry => {
        if (!incEntry || !incEntry.id) return;
        const existingIdx = db.flatDiaryEntries.findIndex(e => String(e.id) === String(incEntry.id));
        if (existingIdx === -1) {
          db.flatDiaryEntries.push({ ...incEntry });
          changed = true;
        } else {
          const existing = db.flatDiaryEntries[existingIdx];
          const incDate = incEntry.updatedAt || incEntry.createdAt || "";
          const curDate = existing.updatedAt || existing.createdAt || "";
          if (incDate > curDate) {
            db.flatDiaryEntries[existingIdx] = { ...existing, ...incEntry };
            changed = true;
          }
        }
      });
    }

    if (Array.isArray(incomingState.serviceCatalog) && incomingState.serviceCatalog.length > 0) {
      if (!Array.isArray(db.serviceCatalog)) db.serviceCatalog = [];
      incomingState.serviceCatalog.forEach(incCat => {
        if (!incCat || !incCat.id) return;
        const existingIdx = db.serviceCatalog.findIndex(c => String(c.id) === String(incCat.id));
        if (existingIdx === -1) {
          db.serviceCatalog.push({ ...incCat });
          changed = true;
        }
      });
    }

    // 1.X Minibar Orders (db.minibarOrders)
    if (Array.isArray(incomingState.minibarOrders) && incomingState.minibarOrders.length > 0) {
      if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
      incomingState.minibarOrders.forEach(incOrder => {
        if (!incOrder || !incOrder.id) return;
        const existingIdx = db.minibarOrders.findIndex(o => String(o.id) === String(incOrder.id));
        if (existingIdx === -1) {
          db.minibarOrders.push({ ...incOrder });
          changed = true;
        } else {
          const cur = db.minibarOrders[existingIdx];
          const incDate = incOrder.updatedAt || incOrder.paidAt || incOrder.createdAt || "";
          const curDate = cur.updatedAt || cur.paidAt || cur.createdAt || "";
          if (incDate > curDate || (incOrder.paymentStatus === "pago" && cur.paymentStatus !== "pago") || (incOrder.invoice?.status === "anexada" && cur.invoice?.status !== "anexada")) {
            db.minibarOrders[existingIdx] = { ...cur, ...incOrder };
            changed = true;
          }
        }
      });
    }

    // 1.Y Minibar Inspections (db.minibarInspections)
    if (Array.isArray(incomingState.minibarInspections) && incomingState.minibarInspections.length > 0) {
      if (!Array.isArray(db.minibarInspections)) db.minibarInspections = [];
      incomingState.minibarInspections.forEach(incInsp => {
        if (!incInsp || !incInsp.id) return;
        const existingIdx = db.minibarInspections.findIndex(i => String(i.id) === String(incInsp.id));
        if (existingIdx === -1) {
          db.minibarInspections.push({ ...incInsp });
          changed = true;
        } else {
          const cur = db.minibarInspections[existingIdx];
          const incDate = incInsp.updatedAt || incInsp.inspectedAt || incInsp.createdAt || "";
          const curDate = cur.updatedAt || cur.inspectedAt || cur.createdAt || "";
          if (incDate > curDate) {
            db.minibarInspections[existingIdx] = { ...cur, ...incInsp };
            changed = true;
          }
        }
      });
    }

    // 1.Z Minibar Products, Stock and Settings
    if (Array.isArray(incomingState.minibarProducts) && incomingState.minibarProducts.length > 0) {
      if (!Array.isArray(db.minibarProducts) || db.minibarProducts.length === 0) {
        db.minibarProducts = incomingState.minibarProducts;
        changed = true;
      }
    }
    if (incomingState.minibarDefaultStock && typeof incomingState.minibarDefaultStock === "object") {
      if (!db.minibarDefaultStock) {
        db.minibarDefaultStock = incomingState.minibarDefaultStock;
        changed = true;
      }
    }
    if (incomingState.minibarSettings && typeof incomingState.minibarSettings === "object") {
      if (!db.minibarSettings) {
        db.minibarSettings = incomingState.minibarSettings;
        changed = true;
      }
    }

    // 1.W Boletos Faturados Banco Inter (db.boletos)
    if (Array.isArray(incomingState.boletos) && incomingState.boletos.length > 0) {
      if (!Array.isArray(db.boletos)) db.boletos = [];
      incomingState.boletos.forEach(incBol => {
        if (!incBol || !incBol.id) return;
        const existingIdx = db.boletos.findIndex(b => String(b.id) === String(incBol.id) || (b.code && incBol.code && b.code === incBol.code));
        if (existingIdx === -1) {
          db.boletos.push({ ...incBol });
          changed = true;
        } else {
          const cur = db.boletos[existingIdx];
          const incDate = incBol.updatedAt || incBol.paidAt || incBol.createdAt || "";
          const curDate = cur.updatedAt || cur.paidAt || cur.createdAt || "";
          if (incDate > curDate || (incBol.status === "pago" && cur.status !== "pago") || (incBol.status === "cancelado" && cur.status !== "cancelado")) {
            db.boletos[existingIdx] = { ...cur, ...incBol };
            changed = true;
          }
        }
      });
    }
  }

  if (ensureB2bSeedData(db)) {
    changed = true;
  }

  // 1.99 Auto-cura universal de Ordens de Serviço (so_1791912503911_wzey5: Flat 313 resetado após início de teste em 14/10 e purga de forceReleased residual)
  if (Array.isArray(db.serviceOrders)) {
    for (const ord of db.serviceOrders) {
      if (!ord || !Array.isArray(ord.flats)) continue;
      for (const fl of ord.flats) {
        if (!fl) continue;
        // Purga integral de forceReleased: filtros da OS nunca podem ser ignorados
        if (fl.forceReleased) {
          fl.forceReleased = false;
          fl.forceReleasedDate = null;
          fl.forceReleasedScenario = null;
          changed = true;
        }
        // Se resetAt é mais recente que workerNotifiedAvailableAt em flat pendente, limpa notificação anterior ao reset
        if (fl.status === "pending" && fl.resetAt && fl.workerNotifiedAvailableAt && fl.workerNotifiedAvailableAt <= fl.resetAt) {
          fl.workerNotifiedAvailable = false;
          fl.workerNotifiedAvailableAt = null;
          changed = true;
        }
      }
    }
    const acOrder = db.serviceOrders.find(o => o && o.id === "so_1791912503911_wzey5");
    if (acOrder && Array.isArray(acOrder.flats)) {
      const f313 = acOrder.flats.find(f => Number(f.flatId) === 7 || String(f.flatNumber) === "313");
      if (
        f313 &&
        f313.status !== "done" &&
        (
          (f313.startedAt && f313.startedAt <= "2026-10-15T00:00:00.000Z") ||
          (f313.entryRequested && f313.entryRequestedAt && f313.entryRequestedAt <= "2026-10-15T00:00:00.000Z") ||
          (f313.status === "in_progress" && !f313.finishedAt && f313.workerNotifiedAvailableAt && (!f313.startedAt || f313.workerNotifiedAvailableAt > f313.startedAt))
        )
      ) {
        const healedResetAt = (f313.workerNotifiedAvailableAt && f313.workerNotifiedAvailableAt > "2026-10-15T00:00:00.000Z")
          ? f313.workerNotifiedAvailableAt
          : (f313.resetAt && f313.resetAt > "2026-10-15T00:00:00.000Z" ? f313.resetAt : "2026-10-15T00:00:00.000Z");
        f313.status = "pending";
        f313.startedAt = null;
        f313.finishedAt = null;
        f313.resetAt = healedResetAt;
        f313.estimatedFinishAt = null;
        f313.workerName = null;
        f313.workerCpf = null;
        f313.entryRequested = false;
        f313.entryRequestedAt = null;
        f313.delayNotified = false;
        f313.forceReleased = false;
        try {
          if (typeof syncServiceOrderRoomBlocks === "function") {
            syncServiceOrderRoomBlocks(acOrder, false, db);
          }
        } catch (_) {}
        changed = true;
      }
    }
  }

  // 2. Normalização Universal e Purga Definitiva de Flats Inválidos (Flat 502)
  const flatsBeforeCount = db.flats.length;
  db.flats = (db.flats || []).filter(flat => String(flat.number) !== "502" && flat.id !== 9);
  if (db.flats.length !== flatsBeforeCount) changed = true;

  const validFlatNumsPurge = new Set((db.flats || []).map(f => String(f.number)).filter(Boolean));
  const validFlatIdsPurge = new Set((db.flats || []).map(f => Number(f.id)).filter(Boolean));
  const cleanReqsBefore = (db.cleaningRequests || []).length;
  db.cleaningRequests = (db.cleaningRequests || []).filter(c => {
    if (!c || String(c.flatNumber) === "502" || c.flatId === 9 || c.source === "checkin") return false;
    if (c.source === "service_order" && (!c.serviceOrderId || String(c.requestDate || "") <= "2026-10-15")) return false;
    if (validFlatNumsPurge.size > 0) {
      const isRealFlat = (c.flatNumber && validFlatNumsPurge.has(String(c.flatNumber))) || (c.flatId && validFlatIdsPurge.has(Number(c.flatId)));
      if (!isRealFlat) return false;
    }
    return true;
  });
  if (db.cleaningRequests.length !== cleanReqsBefore) changed = true;

  db.flats.forEach(flat => {
    if (flat.isActive === undefined) {
      flat.isActive = true;
      changed = true;
    }
  });

  // 2.5. Autocorreção e desvinculação de fichas de hóspedes contaminadas entre pessoas distintas (ex: Flat 215 Leonardo vs Francine)
  if (healContaminatedGuestAndReservationLinks(db)) {
    changed = true;
  }

  // 2.6. Autocorreção de pré-reservas expiradas que possam ter sido marcadas como completed/checkoutDone
  if (typeof sweepExpiredPreReservations === "function" && sweepExpiredPreReservations(db, null) > 0) {
    changed = true;
  }

  // 3. Auditoria Universal de Integridade de Reservas em TODOS os Flats
  const todayStr = getTodayStr ? getTodayStr() : new Date().toISOString().substring(0, 10);
  const activeFlatsMap = new Map();
  db.flats.forEach(f => {
    activeFlatsMap.set(String(f.number), f);
    activeFlatsMap.set(Number(f.id), f);
  });

  db.reservations.forEach(r => {
    const flat = activeFlatsMap.get(String(r.flatNumber)) || activeFlatsMap.get(Number(r.flatId));
    if (flat) {
      if (!r.flatId || r.flatId !== flat.id) {
        r.flatId = flat.id;
        changed = true;
      }
      if (!r.flatNumber || String(r.flatNumber) !== String(flat.number)) {
        r.flatNumber = String(flat.number);
        changed = true;
      }
    }

    // Flat 408: Felipe Junqueira checkout oficial é 2026-09-30 (stayover em 29/09)
    if (r.code === "RES-408-0294" || (String(r.flatNumber) === "408" && r.guestName && r.guestName.toLowerCase().includes("felipe junqueira"))) {
      if (r.checkoutDate !== "2026-09-30") {
        r.checkoutDate = "2026-09-30";
        changed = true;
      }
    }

    // Saneamento de assinatura herdada do CRM em reserva onde o hóspede nunca assinou a ficha da própria reserva
    if (!r.fnhrCompleted && !r.preCheckinCompleted && !r.hasPreCheckin && !r.checkedInAt && !r.fnrhSignedAt && !r.fnrhDocumentUuid && Array.isArray(r.guests)) {
      r.guests.forEach(g => {
        if (g && g.signatureUrl && !g.hasCompletedCheckin && !g.checkinCompletedAt && !g.fnrhSignedAt && !g.fnrhDocumentUuid) {
          delete g.signatureUrl;
          changed = true;
        }
      });
    }

    // Saneamento de re-assinatura indevida: apenas reservas ativas que já realizaram check-in digital nesta reserva podem exigir re-assinatura
    if (r.needsReSignature || (Array.isArray(r.guests) && r.guests.some(g => g && g.needsReSignature))) {
      const isStayClosed = Boolean(r.checkoutDone || r.earlyCheckout || r.status === "completed" || r.status === "checked_out" || r.status === "cancelada" || r.status === "cancelled");
      const isSyntheticTestRes = Number(r.id) >= 7000 && Number(r.id) <= 9999;
      if (isPreReservationBlocked(r) || isStayClosed || (!hasReservationCompletedAnyCheckin(r) && !r.hadCompletedCheckinBefore && !r.reSignatureUrl && !isSyntheticTestRes)) {
        if (r.needsReSignature) {
          r.needsReSignature = false;
          delete r.reSignatureReason;
          changed = true;
        }
        if (Array.isArray(r.guests)) {
          r.guests.forEach(g => {
            if (g && g.needsReSignature) {
              g.needsReSignature = false;
              changed = true;
            }
          });
        }
      }
    }

    // Sincronização de Taxa de Limpeza (cleaningFee <-> charges) e recomposição de totalAmount caso tenha ficado apenas com as diárias
    if (r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "expirada") {
      if (!Array.isArray(r.charges)) r.charges = [];
      const hasCleaningCharge = r.charges.some(c => c && c.type === "cleaning" && Number(c.amount) > 0);
      if (!hasCleaningCharge && Number(r.cleaningFee) > 0) {
        r.charges.push({
          id: `charge_cleaning_${r.id || Date.now()}`,
          type: "cleaning",
          title: "Taxa de Limpeza",
          amount: Number(r.cleaningFee)
        });
        changed = true;
      } else if (hasCleaningCharge && !(Number(r.cleaningFee) > 0)) {
        r.cleaningFee = r.charges
          .filter(c => c && c.type === "cleaning")
          .reduce((acc, c) => acc + (Number(c.amount) || 0), 0);
        changed = true;
      }

      const recNights = (r.checkinDate && r.checkoutDate)
        ? Math.max(1, Math.round((new Date(r.checkoutDate + "T12:00:00Z").getTime() - new Date(r.checkinDate + "T12:00:00Z").getTime()) / (1000 * 60 * 60 * 24)))
        : 1;

      // Correção específica para reserva ativa da Karolina no Flat 905 (ou reservas sem café cuja taxa foi perdida ao alterar de 1 para 3 diárias)
      const isKarolina905 = (String(r.flatNumber) === "905" || Number(r.flatId) === 9) && /[ck]arolina/i.test(String(r.guestName || r.guests?.[0]?.name || ""));
      if (isKarolina905 && !r.includeBreakfast) {
        const unitRate = (Array.isArray(r.dailyRates) && r.dailyRates.length > 0)
          ? (Number(r.dailyRates[0].rate ?? r.dailyRates[0].amount) || Number(r.dailyRate) || 0)
          : (Number(r.dailyRate) || 0);
        if (!r.earlyCheckout && r.checkinDate && unitRate > 0 && (!Array.isArray(r.dailyRates) || r.dailyRates.length !== recNights)) {
          const dStart = new Date(r.checkinDate + "T12:00:00Z");
          const rebuiltRates = [];
          for (let i = 0; i < recNights; i++) {
            const curD = new Date(dStart.getTime() + i * 86400000).toISOString().slice(0, 10);
            const existingD = Array.isArray(r.dailyRates) ? r.dailyRates.find(x => x && x.date === curD) : null;
            rebuiltRates.push({
              date: curD,
              rate: existingD && Number(existingD.rate ?? existingD.amount) > 0 ? Number(existingD.rate ?? existingD.amount) : unitRate,
              channel: (existingD && existingD.channel) || r.channel || "whatsapp"
            });
          }
          r.dailyRates = rebuiltRates;
          changed = true;
        }
        if (!r.charges.some(c => c && c.type === "cleaning" && Number(c.amount) > 0)) {
          let inferredCleanFee = Number(db.siteConfig?.ratePlans?.room_only?.cleaningFeeAmount ?? 70) || 70;
          if (unitRate > 0 && Array.isArray(r.auditLogs)) {
            for (const log of r.auditLogs) {
              for (const ch of (log?.changes || [])) {
                if (ch?.field === "totalAmount") {
                  for (const rawV of [ch.oldValue, ch.newValue]) {
                    const m = String(rawV || "").match(/(\d+(?:[.,]\d{1,2})?)/);
                    if (m) {
                      const numV = parseFloat(m[1].replace(",", "."));
                      const diff1 = Math.round((numV - unitRate) * 100) / 100;
                      if (diff1 >= 30 && diff1 <= 150) {
                        inferredCleanFee = diff1;
                      }
                    }
                  }
                }
              }
            }
          }
          r.cleaningFee = inferredCleanFee;
          r.charges.push({
            id: `charge_cleaning_${r.id || Date.now()}`,
            type: "cleaning",
            title: "Taxa de Limpeza",
            amount: inferredCleanFee
          });
          changed = true;
        }
      }

      const recChargesSum = r.charges.reduce((acc, c) => acc + (Number(c?.amount) || 0), 0);
      const recRatesSum = Array.isArray(r.dailyRates) && r.dailyRates.length > 0
        ? r.dailyRates.reduce((acc, d) => acc + (Number(d?.rate ?? d?.amount) || 0), 0)
        : (Number(r.dailyRate) > 0 ? Math.round(Number(r.dailyRate) * recNights * 100) / 100 : 0);
      const curTot = Number(r.totalAmount) || 0;
      if (!r.earlyCheckout && recChargesSum > 0 && recRatesSum > 0 && Math.abs(curTot - recRatesSum) < 0.05) {
        r.totalAmount = Math.round((recRatesSum + recChargesSum) * 100) / 100;
        changed = true;
      }
    }

    // Sincronização do valor de Cartão (+5%) e payloads PIX/Mercado Pago quando houver saldo pendente
    const resTotalAmt = Number(r.totalAmount) || 0;
    if (resTotalAmt > 0) {
      const expectedCardTot = computeCardAmountFromPix(resTotalAmt);
      if (Number(r.cardTotalAmount) !== expectedCardTot) {
        r.cardTotalAmount = expectedCardTot;
        changed = true;
      }
    }
    if (r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "expirada") {
      const rChanLower = String(r.channel || "").toLowerCase();
      const isB2bRec = rChanLower.includes("b2b") || Boolean(r.agencyId || r.b2bReservationNumber);
      const isOtaRec = rChanLower.includes("booking") || rChanLower.includes("airbnb");
      const hasOtaPartialExtension = !isB2bRec && (r.paymentStatus === "sinal_pago" || r.paymentStatus === "parcial") && Number(r.paidAmount || 0) > 0 && Number(r.paidAmount || 0) < resTotalAmt - 0.01;
      const isResPaid = !isUnverifiedPreReservation(r) && !hasOtaPartialExtension && (r.paymentStatus === "pago_total" || r.paymentStatus === "pago" || (Number(r.paidAmount) >= resTotalAmt && resTotalAmt > 0));
      const pendingAmt = Math.max(0, Math.round((resTotalAmt - (Number(r.paidAmount) || 0)) * 100) / 100);
      if (!isB2bRec && (!isOtaRec || hasOtaPartialExtension) && !isResPaid && pendingAmt > 0) {
        if (!r.pixCopiaECola || isPixPayloadStaleForAmount(r, pendingAmt)) {
          const cleanTxId = String(r.code || `RES${r.id || ""}`).replace(/[^a-zA-Z0-9]/g, "").substring(0, 25);
          r.pixTxId = cleanTxId || r.pixTxId;
          r.pixCopiaECola = generateStaticPixPayload({
            pixKey: db.settings?.interConfig?.pixKey || DEFAULT_INTER_CONFIG.pixKey || "47964813000165",
            amount: pendingAmt,
            merchantName: "CORPFLATS LTDA",
            merchantCity: "CAMPOS DOS GOYTACAZES",
            txid: cleanTxId || "***"
          });
          r.pixChargedAmount = pendingAmt;
          changed = true;
        }
        const expectedCardPending = computeCardAmountFromPix(pendingAmt);
        if (r.mpInitPoint && (!r.mpChargedAmount || Math.abs(Number(r.mpChargedAmount) - expectedCardPending) > 0.01)) {
          r.mpInitPoint = null;
          r.mpPreferenceId = null;
          r.mpChargedAmount = null;
          changed = true;
        }
      }
    }

    // Sincronização geral de preferências de quarto (camas/colchão/recado) da reserva com a solicitação de limpeza do dia do check-in
    if (
      r.status !== "cancelada" &&
      r.status !== "cancelled" &&
      r.status !== "cancelado" &&
      r.status !== "expirada" &&
      r.status !== "pre_reserva" &&
      r.status !== "pendente" &&
      r.status !== "no_show" &&
      r.checkinDate
    ) {
      const isTwin = Boolean(r.twinBeds || r.bedType === "2 Solteiro" || r.bedType === "twin");
      const isMattress = Boolean(r.extraMattress);
      const note = (r.specialRequests || r.notes || "").trim();
      const validNote = (note && !note.includes("Limpeza de check-out gerada automaticamente") && note.toLowerCase() !== "teste") ? note : null;

      const cleanReq = (db.cleaningRequests || []).find(c =>
        (String(c.flatNumber) === String(r.flatNumber) || (r.flatId && c.flatId === r.flatId)) &&
        c.requestDate === r.checkinDate &&
        !c.isInstructionOnly &&
        c.source !== "manual_instruction"
      );
      if (cleanReq) {
        cleanReq.autoReservationCode = r.code;
        cleanReq.autoReservationId = r.id;
        if (!cleanReq.manualTwinBeds && cleanReq.twinBeds !== isTwin) {
          cleanReq.twinBeds = isTwin;
          changed = true;
        }
        if (!cleanReq.manualExtraMattress && cleanReq.extraMattress !== isMattress) {
          cleanReq.extraMattress = isMattress;
          changed = true;
        }
        if (!cleanReq.manualAdminNote) {
          let expectedNote = validNote;
          if (!expectedNote && (cleanReq.twinBeds || cleanReq.extraMattress)) {
            const parts = [];
            if (cleanReq.twinBeds) parts.push("Separar as camas, colocar como 2 solteiras");
            if (cleanReq.extraMattress) parts.push("Colocar 1 colchão extra");
            expectedNote = parts.join(" • ");
          }
          if (cleanReq.adminNote !== expectedNote) {
            cleanReq.adminNote = expectedNote;
            cleanReq.pendingObservation = expectedNote;
            changed = true;
          }
        }
        if (cleanReq.arrivingGuest !== (r.guestName || r.title)) {
          cleanReq.arrivingGuest = r.guestName || r.title;
          changed = true;
        }
      }
    }

    // 4. Garantir que para TODO checkout de QUALQUER flat, exista a solicitação de limpeza correspondente
    if (
      r.status !== "cancelada" &&
      r.status !== "cancelled" &&
      r.status !== "cancelado" &&
      r.status !== "expirada" &&
      r.status !== "pre_reserva" &&
      r.status !== "pendente" &&
      r.status !== "no_show" &&
      r.checkoutDate &&
      r.flatNumber
    ) {
      const checkoutDate = r.checkoutDate;
      const hasCleaning = db.cleaningRequests.some(c =>
        (String(c.flatNumber) === String(r.flatNumber) || c.flatId === r.flatId) &&
        (c.requestDate === checkoutDate || c.effectiveDate === checkoutDate)
      );

      if (!hasCleaning) {
        // Se o checkout é no passado e o flat já possui uma limpeza "clean" entre a data de checkout e hoje (ou próximo check-in), NÃO criar limpeza dirty retroativa duplicada
        if (checkoutDate < todayStr) {
          const nextReservation = (db.reservations || [])
            .filter(otherR =>
              (String(otherR.flatNumber) === String(r.flatNumber) || (r.flatId && otherR.flatId === r.flatId)) &&
              otherR.status !== "cancelada" && otherR.status !== "cancelled" && otherR.status !== "cancelado" &&
              otherR.status !== "expirada" && otherR.status !== "pre_reserva" && otherR.status !== "pendente" && otherR.status !== "no_show" &&
              otherR.checkinDate && otherR.checkinDate >= checkoutDate &&
              otherR.id !== r.id && (otherR.code ? otherR.code !== r.code : true)
            )
            .sort((a, b) => (a.checkinDate || "").localeCompare(b.checkinDate || ""))[0];

          const nextCheckinDate = nextReservation ? nextReservation.checkinDate : null;

          const hasCleanBetween = (db.cleaningRequests || []).some(c => {
            if (String(c.flatNumber) !== String(r.flatNumber) && (!r.flatId || c.flatId !== r.flatId)) return false;
            const cDate = c.requestDate || c.effectiveDate;
            if (!cDate || cDate < checkoutDate) return false;
            const isManualAdminDeleteForSameCheckout =
              cDate === checkoutDate &&
              (c.status === "deleted" || c.isDeleted) &&
              c.deletedBy !== "pre_reservation_expired" &&
              c.deletedBy !== "reservation_cancelled" &&
              c.deletedBy !== "auto_orphan_checkout_cleanup" &&
              (!c.deletedReservationId || Number(c.deletedReservationId) === Number(r.id)) &&
              (!r.createdAt || !c.deletedAt || c.deletedAt >= r.createdAt);
            const isResolvedCleanOrDeleted = c.status === "clean" || isManualAdminDeleteForSameCheckout;
            if (!isResolvedCleanOrDeleted) return false;
            if (cDate <= todayStr) return true;
            if (nextCheckinDate && cDate <= nextCheckinDate) return true;
            return false;
          });

          if (hasCleanBetween) {
            return;
          }
        }

        const sevenDaysAgo = typeof getOffsetDateStr === "function" ? getOffsetDateStr(-7) : "2026-09-20";
        const isOldPastCheckout = checkoutDate < sevenDaysAgo;
        let maxCleanId = 0;
        for (const c of db.cleaningRequests) {
          const cid = Number(c.id) || 0;
          if (cid > maxCleanId) maxCleanId = cid;
        }

        db.cleaningRequests.push({
          id: maxCleanId + 1,
          flatId: r.flatId || (flat ? flat.id : null),
          flatNumber: String(r.flatNumber),
          requestDate: checkoutDate,
          effectiveDate: checkoutDate,
          source: "checkout",
          status: isOldPastCheckout ? "clean" : "dirty",
          assignedUserId: null,
          assignedUsername: null,
          assignedUserName: null,
          isVacant: false,
          isVacantExplicitlySet: false,
          isPriority: false,
          isExtended: false,
          twinBeds: Boolean(r.twinBeds),
          extraMattress: Boolean(r.extraMattress),
          adminNote: `Limpeza de check-out gerada automaticamente para o Flat ${r.flatNumber} (Reserva ${r.code || r.id})`,
          leavingGuest: r.guestName || "Hóspede",
          arrivingGuest: null,
          pendingObservation: null,
          willCleanAt: `${checkoutDate}T13:00:00.000Z`,
          createdAt: `${checkoutDate}T08:00:00.000Z`,
          updatedAt: `${checkoutDate}T13:00:00.000Z`
        });
        changed = true;
        console.log(`[Universal Integrity] Limpeza de checkout criada automaticamente para o Flat ${r.flatNumber} na data ${checkoutDate} (status: ${isOldPastCheckout ? "clean" : "dirty"})`);
      }
    }
  });

  // Reconcilia propostas pendentes de pré-reserva (Sofia WhatsApp) caso alguma esteja apenas com a soma das diárias sem a taxa de limpeza
  for (const p of (db.pendingPreReservationProposals || [])) {
    if (!p || p.status !== "pending_manager") continue;
    if (p.includeBreakfast) continue;
    const isKarolinaProp = (String(p.flatNumber) === "905" || Number(p.flatId) === 9) && /[ck]arolina/i.test(String(p.guestName || ""));
    if (isKarolinaProp && !(Number(p.cleaningFee) > 0)) {
      p.cleaningFee = Number(db.siteConfig?.ratePlans?.room_only?.cleaningFeeAmount ?? 70) || 70;
      changed = true;
    }
    const pNights = Math.max(1, Number(p.nights) || 1);
    const pDaily = Number(p.dailyRate) || 0;
    const pClean = Number(p.cleaningFee) || 0;
    const pTot = Number(p.totalAmount) || 0;
    if (pClean > 0 && pDaily > 0 && Math.abs(pTot - pDaily * pNights) < 0.05) {
      p.totalAmount = Math.round((pDaily * pNights + pClean) * 100) / 100;
      changed = true;
    }
  }

  // Limpeza de instruções automáticas obsoletas:
  // Se a solicitação não for manual e não houver reserva ativa com check-in nessa data/quarto, limpa preferências
  for (const c of (db.cleaningRequests || [])) {
    if (!c || c.isInstructionOnly || c.source === "manual_instruction" || c.source === "manual") continue;
    const fNum = String(c.flatNumber || (db.flats.find(f => f.id === c.flatId)?.number || ""));
    const activeArrivingRes = (db.reservations || []).find(r =>
      r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
      String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || "")) === fNum &&
      r.checkinDate === c.requestDate
    );
    if (!activeArrivingRes) {
      if (!c.manualTwinBeds && c.twinBeds) {
        c.twinBeds = false;
        changed = true;
      }
      if (!c.manualExtraMattress && c.extraMattress) {
        c.extraMattress = false;
        changed = true;
      }
      if (!c.manualAdminNote && c.adminNote) {
        if (c.autoReservationCode ||
            c.adminNote.includes("Separar as camas") ||
            c.adminNote.includes("2 solteiras") ||
            c.adminNote.includes("colchão extra") ||
            c.adminNote.includes("Limpeza de check-out gerada automaticamente")) {
          c.adminNote = null;
          c.pendingObservation = null;
          changed = true;
        }
      }
      if (c.arrivingGuest) {
        c.arrivingGuest = null;
        changed = true;
      }
      c.autoReservationCode = null;
      c.autoReservationId = null;
    }
  }

  // Cancelamento definitivo da reserva B2B-25078591 (Fernanda Oliveira - Flat 408 em 03/11) excluída pelo gestor
  for (const r of (db.reservations || [])) {
    if (
      (r.code === "B2B-25078591" || String(r.b2bReservationNumber) === "25078591") &&
      r.status !== "cancelada" &&
      r.status !== "cancelled" &&
      !r.checkedInAt
    ) {
      r.status = "cancelada";
      r.updatedAt = new Date().toISOString();
      if (!Array.isArray(db.deletedB2bSeeds)) db.deletedB2bSeeds = [];
      if (!db.deletedB2bSeeds.includes("25078591")) db.deletedB2bSeeds.push("25078591");
      if (!db.deletedB2bSeeds.includes("B2B-25078591")) db.deletedB2bSeeds.push("B2B-25078591");
      changed = true;
    }
  }

  // Descarte automático de cards de limpeza de check-out órfãos (quando a reserva de saída foi cancelada, expirada, no_show ou remarcada):
  for (const c of (db.cleaningRequests || [])) {
    if (!c || c.isDeleted || c.status === "deleted" || c.status === "clean") continue;
    const isInst = Boolean(c.isInstructionOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only" || c.isBedAdjustmentOnly);
    if (isInst) continue;
    if (c.source !== "checkout" || c.isVacantExplicitlySet || c.markedByAdmin || c.revertedToDirtyAt) continue;
    const fNum = String(c.flatNumber || (db.flats.find(f => f.id === c.flatId)?.number || ""));
    if (fNum === "509" && c.requestDate === "2026-10-28") continue;

    const hasActiveCheckout = (db.reservations || []).some(r =>
      r.status !== "cancelada" &&
      r.status !== "cancelado" &&
      r.status !== "cancelled" &&
      r.status !== "expirada" &&
      r.status !== "pre_reserva" &&
      r.status !== "pendente" &&
      r.status !== "no_show" &&
      String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || "")) === fNum &&
      (r.checkoutDate === c.requestDate || r.earlyCheckoutDate === c.requestDate)
    );
    if (!hasActiveCheckout) {
      const hasCancelledOrMovedCheckout = (db.reservations || []).some(r => {
        const rFlat = String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || ""));
        const isCanc = r.status === "cancelada" || r.status === "cancelado" || r.status === "cancelled" || r.status === "no_show" || r.status === "expirada" || r.status === "pre_reserva";
        if (isCanc && rFlat === fNum && (r.checkoutDate === c.requestDate || r.earlyCheckoutDate === c.requestDate)) return true;
        if (c.leavingGuest && r.guestName && r.guestName.trim().toLowerCase() === c.leavingGuest.trim().toLowerCase()) {
          if (isCanc || rFlat !== fNum || (r.checkoutDate !== c.requestDate && r.earlyCheckoutDate !== c.requestDate)) return true;
        }
        return false;
      });
      if (hasCancelledOrMovedCheckout) {
        const nowIso = new Date().toISOString();
        c.isDeleted = true;
        c.status = "deleted";
        c.deletedAt = nowIso;
        c.deletedBy = "auto_orphan_checkout_cleanup";
        c.updatedAt = nowIso;
        changed = true;
        console.log(`[Universal Integrity] Descartando automaticamente card de check-out órfão do Flat ${fNum} em ${c.requestDate} (${c.leavingGuest || "sem hóspede"})`);
      }
    }
  }

  // Auto-correção: Se uma limpeza de checkout recente (últimos 7 dias) foi gerada automaticamente como "clean"
  // sem ter sido realizada por nenhuma camareira (sem assignedUserId e sem completedAt, como o Flat 408 da Danielle), ela deve ser "dirty"!
  const recentWindow = typeof getOffsetDateStr === "function" ? getOffsetDateStr(-7) : "2026-09-20";
  (db.cleaningRequests || []).forEach(c => {
    // IMMUNITY GUARDS: Nunca reverter marcações manuais do administrador, limpezas canônicas ou registros com responsável/conclusão
    if (
      c.markedByAdmin === true ||
      c.isCanonical === true ||
      c.source === "admin_manual" ||
      c.source === "manual" ||
      c.addedBy === "admin" ||
      Boolean(c.completedAt) ||
      Boolean(c.assignedUserId)
    ) {
      return;
    }

    if (
      c.source === "checkout" &&
      c.status === "clean" &&
      !c.assignedUserId &&
      !c.completedAt &&
      c.requestDate >= recentWindow &&
      c.adminNote && c.adminNote.includes("Limpeza de check-out gerada automaticamente")
    ) {
      c.status = "dirty";
      c.durationMinutes = null;
      changed = true;
      console.log(`[Universal Integrity] Corrigindo limpeza não realizada do Flat ${c.flatNumber} em ${c.requestDate} de clean para dirty`);
    }
  });

  // Regra Universal de Integridade Temporal (Todos os 19 flats):
  // Uma limpeza de check-out com data futura (requestDate > todayStr) ou cuja data de conclusão
  // seja anterior à data da solicitação (completedAt.substring(0, 10) < requestDate)
  // é uma anomalia cronológica impossível (o hóspede ainda está hospedado e não fez checkout).
  (db.cleaningRequests || []).forEach(c => {
    const isInst = Boolean(c.isInstructionOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only" || c.isBedAdjustmentOnly);
    if (isInst) return;
    if (c.source === "admin_manual" || c.source === "manual" || c.markedByAdmin === true) return;

    const completedDate = c.completedAt ? String(c.completedAt).substring(0, 10) : null;
    const isFutureCheckoutCleaning = Boolean(c.requestDate && c.requestDate > todayStr);
    const isCompletedBeforeRequest = Boolean(completedDate && c.requestDate && completedDate < c.requestDate);

    if (c.status === "clean" && (isFutureCheckoutCleaning || isCompletedBeforeRequest)) {
      c.status = "dirty";
      c.assignedUserId = null;
      c.assignedUsername = null;
      c.assignedUserName = null;
      c.completedAt = null;
      c.cleaningStartedAt = null;
      c.durationMinutes = null;
      c.effectiveDate = c.requestDate;
      c.executionDate = c.requestDate;
      changed = true;
      console.log(`[Universal Integrity] Corrigindo limpeza anômala futura/retroativa do Flat ${c.flatNumber} em ${c.requestDate} para dirty`);
    }
  });

  // Purga defensiva: remove solicitações duplicadas não limpas de instrução geradas indevidamente por rotinas legadas
  const cleanReqsBeforeInst = (db.cleaningRequests || []).length;
  db.cleaningRequests = (db.cleaningRequests || []).filter(c => {
    const isBedInst = Boolean(c.isBedAdjustmentOnly || c.type === "bed_adjustment_only" || (c.source === "manual_instruction" && c.instructionText === "Separar as camas, colocar como 2 solteiras"));
    if (isBedInst && (String(c.flatNumber) === "113" || String(c.flatNumber) === "114")) {
      if (c.status !== "clean") return false;
    }
    return true;
  });
  if (db.cleaningRequests.length !== cleanReqsBeforeInst) changed = true;

  // Migração defensiva: Qualquer limpeza em "pending" que aguarda higienização deve ser "dirty"
  (db.cleaningRequests || []).forEach(c => {
    if (c.status === "pending") {
      c.status = "dirty";
      changed = true;
    }
  });

  // Deduplicação defensiva de créditos de diárias de camareiras (a partir de 25/09)
  if (Array.isArray(db.maidStatementEntries)) {
    const seenCredits = new Set();
    const origLen = db.maidStatementEntries.length;
    db.maidStatementEntries = db.maidStatementEntries.filter(e => {
      if (e.entryType !== "credit" || !e.entryDate || e.entryDate < "2026-09-25") return true;
      const key = `${e.userId}___${e.entryDate}___${e.description}`;
      if (seenCredits.has(key)) return false;
      seenCredits.add(key);
      return true;
    });
    if (db.maidStatementEntries.length !== origLen) changed = true;
  }

  // Saneamento e Correção de Integridade dos Check-outs (Flats 408, 509 e 1004)
  (db.cleaningRequests || []).forEach(c => {
    // Flat 408: Felipe Junqueira checkout é 30/09, não deve ter limpeza de checkout no dia 29/09
    if (String(c.flatNumber) === "408") {
      if (c.requestDate === "2026-09-29" && c.leavingGuest && c.leavingGuest.toLowerCase().includes("felipe")) {
        c.requestDate = "2026-09-30";
        c.effectiveDate = "2026-09-30";
        c.willCleanAt = "2026-09-30T13:00:00.000Z";
        changed = true;
      }
      if (c.requestDate === "2026-09-30") {
        if (c.willCleanAt && c.willCleanAt.startsWith("2026-09-29")) {
          c.willCleanAt = "2026-09-30T13:00:00.000Z";
          c.effectiveDate = "2026-09-30";
          changed = true;
        }
      }
      // Danielle (27/09): quarto entregue limpo para Felipe entrar dia 28/09
      if (c.requestDate === "2026-09-27" && c.status === "dirty") {
        c.status = "clean";
        c.completedAt = c.completedAt || "2026-09-27T15:00:00.000Z";
        changed = true;
      }
    }


    // Flat 1004: Check-out de 29/09 (Roselene) não foi limpo por Cris; é dirty aguardando camareira
    if (String(c.flatNumber) === "1004" && c.requestDate === "2026-09-29") {
      if (c.status === "clean" && (c.assignedUsername === "Cris" || c.assignedUserId === 2 || !c.completedAt || (c.completedAt && c.completedAt.startsWith("2026-09-28")))) {
        c.status = "dirty";
        c.assignedUserId = null;
        c.assignedUsername = null;
        c.assignedUserName = null;
        c.completedAt = null;
        c.cleaningStartedAt = null;
        c.durationMinutes = null;
        changed = true;
      }
    }
  });

  // Regularização automática de preventivas das camareiras anteriores a hoje
  if (regularizeHousekeepingPreventiveTasks()) {
    changed = true;
  }

  if (typeof isUniversalIntegrityDirty !== "undefined") isUniversalIntegrityDirty = false;
  if (typeof lastUniversalIntegrityTimestamp !== "undefined") lastUniversalIntegrityTimestamp = Date.now();

  return changed;
}

// Alias de retrocompatibilidade
function ensureRestoredSeptReservations() {
  return reconcileUniversalIntegrity();
}

// ── Helpers de Tarefas Preventivas & Periodicidade (Dias de Locação vs Dias Corridos) ──

export function getFlatOccupiedDays(flatId, flatNumber, sinceDateStr, upToDateStr, candidateReservations = null) {
  const reservations = Array.isArray(candidateReservations) ? candidateReservations : (db.reservations || []).filter(r => 
    (Number(r.flatId) === Number(flatId) || String(r.flatNumber) === String(flatNumber)) &&
    r.status !== 'cancelada' && r.status !== 'cancelado' && r.status !== 'cancelled'
  );

  const occupiedDates = new Set();
  for (const r of reservations) {
    if (!r.checkinDate || !r.checkoutDate) continue;
    let cur = new Date(r.checkinDate + 'T12:00:00Z');
    const end = new Date(r.checkoutDate + 'T12:00:00Z');
    while (cur < end) {
      const dStr = cur.toISOString().substring(0, 10);
      if (dStr >= sinceDateStr && dStr < upToDateStr) {
        occupiedDates.add(dStr);
      }
      cur.setUTCDate(cur.getUTCDate() + 1);
    }
  }
  return occupiedDates.size;
}

export function computePeriodicTaskStatus(task, flat, referenceDateStr, context = null) {
  const flatId = Number(flat.id || flat.flatId);
  const flatNumber = String(flat.number || flat.flatNumber);
  const periodDays = Number(task.periodDays) || 1;
  const periodType = task.periodType || "calendar_days";

  let lastExec = null;
  if (context?.latestExecutionMap) {
    lastExec = context.latestExecutionMap.get(`${task.id}_${flatId}`) || null;
  } else {
    const executions = (db.periodicExecutions || []).filter(e => 
      Number(e.periodicTaskId) === Number(task.id) && Number(e.flatId) === flatId
    );
    executions.sort((a, b) => new Date(b.executedAt).getTime() - new Date(a.executedAt).getTime());
    lastExec = executions[0] || null;
  }

  let sinceDateStr;
  if (lastExec) {
    sinceDateStr = getExecutionDateStr(lastExec.executedAt);
  } else {
    sinceDateStr = task.firstDueDate || (task.createdAt ? getExecutionDateStr(task.createdAt) : referenceDateStr);
  }

  let nextDueAt = null;
  let isDue = false;
  let daysOverdue = 0;
  let currentOccupiedDays = 0;

  const flatResList = context?.reservationsByFlat
    ? (context.reservationsByFlat.get(flatId) || (flatNumber ? context.reservationsByFlat.get(flatNumber) : null) || [])
    : null;

  if (periodType === "occupied_days") {
    currentOccupiedDays = getFlatOccupiedDays(flatId, flatNumber, sinceDateStr, referenceDateStr, flatResList);
    if (currentOccupiedDays >= periodDays) {
      isDue = true;
      daysOverdue = currentOccupiedDays - periodDays;
      nextDueAt = referenceDateStr;
    } else {
      isDue = false;
      const remainingOccupied = periodDays - currentOccupiedDays;
      daysOverdue = -remainingOccupied;

      let needed = remainingOccupied;
      const futureReservations = (flatResList || (db.reservations || []).filter(r => 
          (Number(r.flatId) === flatId || (flatNumber && String(r.flatNumber) === flatNumber)) &&
          r.status !== 'cancelada' && r.status !== 'cancelado' && r.status !== 'cancelled'
        ))
        .filter(r => r.checkoutDate > referenceDateStr)
        .sort((a, b) => a.checkinDate.localeCompare(b.checkinDate));

      for (const r of futureReservations) {
        let cur = new Date(Math.max(new Date(r.checkinDate + 'T12:00:00Z').getTime(), new Date(referenceDateStr + 'T12:00:00Z').getTime()));
        const end = new Date(r.checkoutDate + 'T12:00:00Z');
        while (cur < end && needed > 0) {
          needed--;
          if (needed === 0) {
            nextDueAt = cur.toISOString().substring(0, 10);
            break;
          }
          cur.setUTCDate(cur.getUTCDate() + 1);
        }
        if (needed === 0) break;
      }
    }
  } else {
    // calendar_days
    nextDueAt = addDaysToDateStr(sinceDateStr, periodDays);
    daysOverdue = calcDaysDiff(referenceDateStr, nextDueAt);
    isDue = (nextDueAt <= referenceDateStr);
  }

  return {
    id: task.id,
    taskId: task.id,
    name: task.name,
    taskName: task.name,
    description: task.description,
    taskDescription: task.description,
    flatId: flatId,
    flatNumber: flatNumber,
    periodDays: periodDays,
    periodType: periodType,
    firstDueDate: task.firstDueDate || null,
    assignToHousekeeping: task.assignToHousekeeping !== false,
    lastExecutedAt: lastExec ? lastExec.executedAt : null,
    nextDueAt: nextDueAt,
    isDue: isDue,
    daysOverdue: daysOverdue,
    currentOccupiedDays: periodType === "occupied_days" ? currentOccupiedDays : undefined,
    remainingOccupiedDays: periodType === "occupied_days" ? Math.max(0, periodDays - currentOccupiedDays) : undefined,
  };
}

let lastRegularizeHousekeepingDate = null;

export function regularizeHousekeepingPreventiveTasks(force = false) {
  const todayStr = getTodayStr();
  if (!force && lastRegularizeHousekeepingDate === todayStr) {
    return false;
  }
  const yesterdayStr = addDaysToDateStr(todayStr, -1);
  let changed = false;

  if (!Array.isArray(db.periodicExecutions)) db.periodicExecutions = [];
  const housekeepingTasks = (db.periodicTasks || []).filter(t => t.isActive && t.assignToHousekeeping !== false);
  const activeFlats = (db.flats || []).filter(f => f.isActive !== false && String(f.number) !== "502" && f.id !== 9);

  // O(1) Indexing: Map de última execução por task + flat
  const latestExecutionMap = new Map();
  for (const e of db.periodicExecutions) {
    if (!e) continue;
    const key = `${e.periodicTaskId}_${e.flatId}`;
    const existing = latestExecutionMap.get(key);
    if (!existing || new Date(e.executedAt).getTime() > new Date(existing.executedAt).getTime()) {
      latestExecutionMap.set(key, e);
    }
  }

  // O(1) Indexing: Map de reservas ativas por flatId e flatNumber
  const reservationsByFlat = new Map();
  for (const r of (db.reservations || [])) {
    if (!r || r.status === 'cancelada' || r.status === 'cancelado' || r.status === 'cancelled') continue;
    const fId = Number(r.flatId);
    const fNum = String(r.flatNumber || "");
    if (fId) {
      if (!reservationsByFlat.has(fId)) reservationsByFlat.set(fId, []);
      reservationsByFlat.get(fId).push(r);
    }
    if (fNum) {
      if (!reservationsByFlat.has(fNum)) reservationsByFlat.set(fNum, []);
      reservationsByFlat.get(fNum).push(r);
    }
  }

  const context = { latestExecutionMap, reservationsByFlat };
  let nextId = db.periodicExecutions.length > 0 ? Math.max(...db.periodicExecutions.map(e => e.id)) + 1 : 1;

  for (const flat of activeFlats) {
    for (const t of housekeepingTasks) {
      if (Array.isArray(t.flatIds) && t.flatIds.length > 0 && !t.flatIds.map(Number).includes(Number(flat.id))) {
        continue;
      }

      const status = computePeriodicTaskStatus(t, flat, todayStr, context);
      let shouldRegularize = false;
      if (status.periodType === "occupied_days") {
        if (status.isDue) {
          shouldRegularize = true;
        }
      } else {
        if (status.nextDueAt && status.nextDueAt < todayStr) {
          shouldRegularize = true;
        }
      }

      if (shouldRegularize) {
        db.periodicExecutions.push({
          id: nextId++,
          periodicTaskId: Number(t.id),
          flatId: Number(flat.id),
          executedByUserId: 1,
          executedAt: `${yesterdayStr}T23:59:00.000Z`,
          notes: "Concluído na regularização de preventivas pendentes (limpeza de backlog)",
          createdAt: new Date().toISOString()
        });
        changed = true;
      }
    }
  }

  lastRegularizeHousekeepingDate = todayStr;
  return changed;
}

export function sanitizePeriodicTasks() {
  if (!Array.isArray(db.periodicTasks)) db.periodicTasks = [];
  let changed = false;
  for (const t of db.periodicTasks) {
    if (!t.periodType) {
      const nameLower = (t.name || "").toLowerCase();
      if (nameLower.includes("filtro") || nameLower.includes("ar-condicionado") || nameLower.includes("edredom") || nameLower.includes("box") || nameLower.includes("colchão") || nameLower.includes("pia")) {
        t.periodType = "occupied_days";
      } else {
        t.periodType = "calendar_days";
      }
      changed = true;
    }
  }
  return changed;
}

// Blindagem e Persistência Garantida dos Dados das Camareiras (Cris e Grazi)
export function sanitizeMaidUsers() {
  if (!Array.isArray(db.users)) db.users = [];

  let changed = false;

  // 1. Cris (id: 2) - Telefone/WhatsApp: 22988486446 | Chave PIX: 22988486446
  let cris = db.users.find(u => u.id === 2 || (u.username && u.username.toLowerCase() === "cris"));
  if (!cris) {
    cris = {
      id: 2,
      username: "Cris",
      role: "camareira",
      contractType: "prestador",
      passwordHash: hashPassword("1234")
    };
    db.users.push(cris);
    changed = true;
  }
  if (!cris.name || cris.name !== "Cris") { cris.name = "Cris"; changed = true; }
  if (cris.phone !== "22988486446") { cris.phone = "22988486446"; changed = true; }
  if (cris.whatsapp !== "5522988486446") { cris.whatsapp = "5522988486446"; changed = true; }
  if (cris.pixKey !== "22988486446") { cris.pixKey = "22988486446"; changed = true; }
  if (cris.role !== "camareira") { cris.role = "camareira"; changed = true; }
  if (cris.contractType !== "prestador") { cris.contractType = "prestador"; changed = true; }
  if (cris.active !== true) { cris.active = true; changed = true; }

  // 2. Grazi (id: 3) - Telefone/WhatsApp: 22999106204 | Chave PIX (CPF): 12977795766
  let grazi = db.users.find(u => u.id === 3 || (u.username && u.username.toLowerCase() === "grazi"));
  if (!grazi) {
    grazi = {
      id: 3,
      username: "Grazi",
      role: "camareira",
      contractType: "prestador",
      passwordHash: hashPassword("1234")
    };
    db.users.push(grazi);
    changed = true;
  }
  if (!grazi.name || grazi.name !== "Grazi") { grazi.name = "Grazi"; changed = true; }
  if (grazi.phone !== "22999106204") { grazi.phone = "22999106204"; changed = true; }
  if (grazi.whatsapp !== "5522999106204") { grazi.whatsapp = "5522999106204"; changed = true; }
  if (grazi.pixKey !== "12977795766") { grazi.pixKey = "12977795766"; changed = true; }
  if (grazi.role !== "camareira") { grazi.role = "camareira"; changed = true; }
  if (grazi.contractType !== "prestador") { grazi.contractType = "prestador"; changed = true; }
  if (grazi.active !== true) { grazi.active = true; changed = true; }

  // 3. Garante que os números das camareiras estejam no testAllowedPhones da zapiConfig e allowMaidsInTestMode seja true
  if (db.zapiConfig) {
    const existingAllowed = String(db.zapiConfig.testAllowedPhones || "");
    const numbersToAdd = ["22988486446", "22999106204"];
    let newAllowed = existingAllowed;
    for (const num of numbersToAdd) {
      if (!newAllowed.includes(num)) {
        newAllowed = (newAllowed ? newAllowed + ", " : "") + num;
        changed = true;
      }
    }
    if (newAllowed !== existingAllowed) {
      db.zapiConfig.testAllowedPhones = newAllowed;
    }
    if (db.zapiConfig.allowMaidsInTestMode !== true) {
      db.zapiConfig.allowMaidsInTestMode = true;
      changed = true;
    }
  }

  if (changed) {
    try {
      saveDatabase();
      console.log("[Sanitize Maids] Dados, telefones e contractType: 'prestador' de Cris e Grazi blindados e sincronizados com sucesso.");
    } catch (_) {}
  }
  return changed;
}

