// ── Reservation Audit Log Engine ─────────────────────────────────────────────
function addReservationAuditLog(reservation, {
  action = "updated",
  actor = null,
  source = "PMS Calendário",
  description = "",
  changes = []
} = {}) {
  if (!reservation) return null;
  if (!reservation.auditLogs) reservation.auditLogs = [];

  const now = new Date().toISOString();
  const entryId = `audit_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

  const normalizedActor = {
    id: actor?.id || null,
    name: actor?.name || actor?.username || "Sistema",
    role: actor?.role || (actor?.name ? "user" : "system"),
    type: actor?.type || (actor?.role === "guest" ? "guest" : (actor?.name && actor?.name !== "Sistema" ? "user" : "system"))
  };

  const entry = {
    id: entryId,
    timestamp: now,
    action,
    actor: normalizedActor,
    source: source || "PMS Calendário",
    description: description || "Atualização da reserva",
    changes: Array.isArray(changes) ? changes : []
  };

  reservation.auditLogs.unshift(entry);
  reservation.lastModifiedBy = {
    timestamp: now,
    actor: normalizedActor,
    source: entry.source
  };

  try {
    logAuditEvent({
      level: action === "cancelled" ? "warning" : "info",
      category: "reservation",
      action: `RESERVATION_${String(action).toUpperCase()}`,
      actor: normalizedActor,
      source: entry.source,
      details: {
        reservationId: reservation.id,
        reservationCode: reservation.code,
        flatId: reservation.flatId,
        flatNumber: reservation.flatNumber,
        guestId: reservation.guestId,
        guestName: reservation.guestName,
        guestPhone: reservation.guestPhone || reservation.guests?.[0]?.phone || null,
        guestEmail: reservation.guestEmail || reservation.guests?.[0]?.email || null,
        guestDocument: reservation.guestDocument || reservation.guests?.[0]?.cpf || null,
        guestCount: reservation.guestCount || (Array.isArray(reservation.guests) ? reservation.guests.length : 1),
        guests: reservation.guests || null,
        requesterType: reservation.requesterType || (reservation.companyName || reservation.companyId ? "company" : (reservation.requesterInfo ? "other_person" : "guest")),
        requesterInfo: reservation.requesterInfo || null,
        companyId: reservation.companyId || null,
        companyName: reservation.companyName || null,
        checkinDate: reservation.checkinDate,
        checkoutDate: reservation.checkoutDate,
        checkinTime: reservation.checkinTime,
        checkoutTime: reservation.checkoutTime,
        status: reservation.status,
        channel: reservation.channel,
        paymentMethod: reservation.paymentMethod,
        dailyRate: reservation.dailyRate,
        dailyRates: reservation.dailyRates || null,
        payments: reservation.payments || null,
        charges: reservation.charges || null,
        cleaningFee: reservation.cleaningFee ?? null,
        totalAmount: reservation.totalAmount,
        paidAmount: reservation.paidAmount,
        paymentStatus: reservation.paymentStatus,
        includeBreakfast: reservation.includeBreakfast,
        isMonthlyGuest: reservation.isMonthlyGuest,
        clientType: reservation.clientType,
        roomReadySentDate: reservation.roomReadySentDate || null,
        roomReadySentAt: reservation.roomReadySentAt || null,
        morningEmailSentDate: reservation.morningEmailSentDate || null,
        morningEmailSentAt: reservation.morningEmailSentAt || null,
        fnhrCompleted: Boolean(reservation.fnhrCompleted),
        preCheckinCompleted: Boolean(reservation.preCheckinCompleted),
        needsReSignature: Boolean(reservation.needsReSignature),
        checkedInAt: reservation.checkedInAt || null,
        checkoutDone: Boolean(reservation.checkoutDone),
        docPhotoUrl: reservation.docPhotoUrl || null,
        signatureUrl: reservation.signatureUrl || null,
        r2Url: reservation.r2Url || null,
        fnrhDocumentUuid: reservation.fnrhDocumentUuid || null,
        fnrhPdfUrl: reservation.fnrhPdfUrl || null,
        fnrhDownloadUrl: reservation.fnrhDownloadUrl || null,
        fnrhSha256Hash: reservation.fnrhSha256Hash || null,
        fnrhVerifyUrl: reservation.fnrhVerifyUrl || null,
        fnrhSignedAt: reservation.fnrhSignedAt || null,
        fnrhAuditTrail: reservation.fnrhAuditTrail || null,
        vehicle: reservation.vehicle || null,
        aiVerification: reservation.aiVerification || null,
        aiDocInspection: reservation.aiDocInspection || null,
        estimatedArrivalTime: reservation.estimatedArrivalTime || null,
        description: entry.description,
        changes: entry.changes
      }
    });
  } catch {}

  return entry;
}

function ensureReservationAuditLogs(reservation) {
  if (!reservation) return reservation;
  if (reservation.auditLogs && reservation.auditLogs.length > 0) return reservation;

  reservation.auditLogs = [];

  // 1. Log sintético de criação inicial
  const createdTimestamp = reservation.createdAt || new Date().toISOString();
  const channel = (reservation.channel || "").toLowerCase();
  let defaultCreator = "PMS / Recepção";
  let defaultSource = "PMS Calendário";
  let creatorType = "user";

  if (channel === "site" || channel === "site_direto") {
    defaultCreator = reservation.guestName || "Hóspede (Online)";
    defaultSource = "Site CorpFlats (Motor de Reservas)";
    creatorType = "guest";
  } else if (channel === "booking") {
    defaultCreator = "Canal Booking.com";
    defaultSource = "Booking.com Sync";
    creatorType = "system";
  } else if (channel === "airbnb") {
    defaultCreator = "Canal Airbnb";
    defaultSource = "Airbnb Sync";
    creatorType = "system";
  } else if (channel === "whatsapp") {
    defaultCreator = "Atendimento WhatsApp";
    defaultSource = "WhatsApp / Direta";
    creatorType = "user";
  }

  const creatorName = reservation.createdBy?.userName || reservation.createdBy?.name || defaultCreator;
  const creatorSource = reservation.createdBy?.source || defaultSource;

  reservation.auditLogs.push({
    id: `audit_init_${reservation.id || Date.now()}`,
    timestamp: createdTimestamp,
    action: "created",
    actor: {
      id: reservation.createdBy?.userId || null,
      name: creatorName,
      role: reservation.createdBy?.role || (creatorType === "guest" ? "guest" : "admin"),
      type: creatorType
    },
    source: creatorSource,
    description: "Reserva criada no sistema",
    changes: [
      { field: "flatNumber", label: "Apartamento", oldValue: null, newValue: `Flat ${reservation.flatNumber || reservation.flatId}` },
      { field: "dates", label: "Período da Estadia", oldValue: null, newValue: `${reservation.checkinDate} a ${reservation.checkoutDate}` },
      { field: "guestName", label: "Hóspede Titular", oldValue: null, newValue: reservation.guestName || "Não informado" },
      { field: "channel", label: "Canal", oldValue: null, newValue: reservation.channel || "direta" },
      ...(reservation.totalAmount ? [{ field: "totalAmount", label: "Valor Total", oldValue: null, newValue: `R$ ${Number(reservation.totalAmount).toFixed(2)}` }] : [])
    ]
  });

  // 2. Histórico de modificações anterior (ex: autoatendimento)
  if (Array.isArray(reservation.modificationHistory)) {
    for (const mod of reservation.modificationHistory) {
      reservation.auditLogs.unshift({
        id: `audit_mod_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        timestamp: mod.modifiedAt || new Date().toISOString(),
        action: "portal_modify",
        actor: {
          id: null,
          name: reservation.guestName || "Hóspede",
          role: "guest",
          type: "guest"
        },
        source: "Portal do Hóspede (Autoatendimento)",
        description: mod.reason || "Alteração de datas pelo portal do hóspede",
        changes: [
          ...(mod.oldCheckin !== mod.newCheckin || mod.oldCheckout !== mod.newCheckout ? [
            { field: "dates", label: "Período", oldValue: `${mod.oldCheckin} a ${mod.oldCheckout}`, newValue: `${mod.newCheckin} a ${mod.newCheckout}` }
          ] : []),
          ...(mod.oldGuests !== mod.newGuests ? [
            { field: "guestCount", label: "Qtd. Hóspedes", oldValue: String(mod.oldGuests), newValue: String(mod.newGuests) }
          ] : []),
          ...(mod.additionalAmountToPay ? [
            { field: "additionalAmountToPay", label: "Acréscimo a Pagar", oldValue: null, newValue: `+R$ ${Number(mod.additionalAmountToPay).toFixed(2)}` }
          ] : [])
        ]
      });
    }
  }

  // 3. Status de Check-in ou Check-out
  if (reservation.actualCheckinAt) {
    reservation.auditLogs.unshift({
      id: `audit_chk_${reservation.id || Date.now()}_in`,
      timestamp: reservation.actualCheckinAt,
      action: "checkin",
      actor: { id: null, name: "Recepção / Portaria", role: "reception", type: "user" },
      source: "Recepção / Portaria",
      description: "Entrada (Check-in) registrada na portaria",
      changes: [{ field: "status", label: "Status da Reserva", oldValue: "Confirmada", newValue: "Hospedado (In House)" }]
    });
  }

  if (reservation.actualCheckoutAt) {
    reservation.auditLogs.unshift({
      id: `audit_chk_${reservation.id || Date.now()}_out`,
      timestamp: reservation.actualCheckoutAt,
      action: "checkout",
      actor: { id: null, name: "Recepção / Portaria", role: "reception", type: "user" },
      source: "Recepção / Portaria",
      description: "Saída (Check-out) registrada",
      changes: [{ field: "status", label: "Status da Reserva", oldValue: "Hospedado", newValue: "Concluída (Completed)" }]
    });
  }

  if (reservation.status === "cancelada" || reservation.status === "CANCELLED") {
    reservation.auditLogs.unshift({
      id: `audit_cancel_${reservation.id || Date.now()}`,
      timestamp: reservation.updatedAt || new Date().toISOString(),
      action: "cancelled",
      actor: { id: null, name: "Recepção / PMS", role: "admin", type: "user" },
      source: "PMS Calendário",
      description: "Reserva cancelada",
      changes: [{ field: "status", label: "Status da Reserva", oldValue: "Confirmada", newValue: "Cancelada" }]
    });
  }

  return reservation;
}

export function diffReservationFields(oldRes, newBody, flatsList = []) {
  const changes = [];

  const FIELD_MAP = {
    checkinDate: "Data de Entrada (Check-in)",
    checkoutDate: "Data de Saída (Check-out)",
    guestName: "Hóspede Titular",
    guestPhone: "WhatsApp / Telefone",
    guestEmail: "E-mail do Hóspede",
    channel: "Canal de Origem",
    paymentMethod: "Forma de Pagamento",
    dailyRate: "Valor da Diária",
    totalAmount: "Valor Total",
    paidAmount: "Valor Pago",
    paymentStatus: "Status do Pagamento",
    status: "Status da Reserva",
    adults: "Adultos",
    children: "Crianças",
    guestCount: "Total de Hóspedes",
    notes: "Observações Gerais",
    receptionNotes: "Aviso para a Portaria / Recepção",
    earlyCheckinAuthorized: "Autorização de Early Check-in",
    autoEmitInvoice: "Auto-Emissão de Nota Fiscal (NFS-e)",
    prefersHighFloor: "Preferência por Andar Alto",
    twinBeds: "Configuração: 2 Camas de Solteiro",
    extraMattress: "Configuração: Colchão Extra",
    includeBreakfast: "Café da Manhã Incluso",
    specialRequests: "Pedidos Especiais",
    isMonthlyGuest: "Cliente Mensalista",
    requesterType: "Tipo de Solicitante",
    companyName: "Empresa Solicitante",
    companyId: "ID da Empresa",
    guestDocument: "CPF / Documento do Hóspede",
    clientType: "Perfil do Cliente"
  };

  // Transferência de Apartamento
  if (newBody.flatId !== undefined && Number(newBody.flatId) !== Number(oldRes.flatId)) {
    const oldFlatNum = oldRes.flatNumber || flatsList.find(f => f.id === Number(oldRes.flatId))?.number || oldRes.flatId;
    const newFlatNum = flatsList.find(f => f.id === Number(newBody.flatId))?.number || newBody.flatId;
    changes.push({
      field: "flatNumber",
      label: "Acomodação / Quarto",
      oldValue: `Flat ${oldFlatNum}`,
      newValue: `Flat ${newFlatNum}`
    });
  } else if (newBody.flatNumber !== undefined && String(newBody.flatNumber).trim() !== String(oldRes.flatNumber || "").trim()) {
    changes.push({
      field: "flatNumber",
      label: "Acomodação / Quarto",
      oldValue: `Flat ${oldRes.flatNumber}`,
      newValue: `Flat ${newBody.flatNumber}`
    });
  }

  // Veículo / Placa
  const oldPlate = oldRes.vehicle?.plate;
  const newPlate = newBody.vehicle?.plate || newBody.vehiclePlate;
  if (newPlate !== undefined) {
    const cleanOld = String(oldPlate || "").toUpperCase().trim();
    const cleanNew = String(newPlate || "").toUpperCase().trim();
    if (cleanNew && cleanNew !== cleanOld) {
      changes.push({
        field: "vehiclePlate",
        label: "Veículo / Garagem",
        oldValue: cleanOld ? `Placa ${cleanOld}` : "(sem veículo)",
        newValue: `Placa ${cleanNew}`
      });
    }
  }

  const PAYMENT_STATUS_LABELS = {
    pago_total: "Confirmado / Pago (100%)",
    pago: "Confirmado / Pago (100%)",
    sinal_pago: "Pago Parcialmente (Saldo de diária adicional em aberto)",
    parcial: "Pago Parcialmente (Saldo de diária adicional em aberto)",
    pendente: "Aguardando Pagamento",
    isento: "Cortesia / Isento",
    faturado: "Faturado Corporativo"
  };

  const oldChanLower = String(oldRes?.channel || newBody?.channel || "").toLowerCase();
  const isOldOta = (oldChanLower.includes("booking") || oldChanLower.includes("airbnb")) &&
    oldRes?.paymentCollect !== "Property" && !oldRes?.collectAtCheckin;
  const hasOldPartialPending = (oldRes?.paymentStatus === "sinal_pago" || oldRes?.paymentStatus === "parcial") &&
    Number(oldRes?.paidAmount) > 0 &&
    Number(oldRes?.paidAmount) < Number(oldRes?.totalAmount || 0) - 0.01;
  const wasOldEffectivelyPaidTotal =
    (isOldOta && !hasOldPartialPending) ||
    oldRes?.paymentStatus === "pago_total" ||
    oldRes?.paymentStatus === "pago" ||
    (Number(oldRes?.paidAmount || 0) >= Number(oldRes?.totalAmount || 0) - 0.01 && Number(oldRes?.totalAmount || 0) > 0);

  for (const [key, label] of Object.entries(FIELD_MAP)) {
    if (newBody[key] === undefined) continue;

    let oldVal = oldRes[key];
    let newVal = newBody[key];

    if (typeof oldVal === "boolean" || typeof newVal === "boolean") {
      if (Boolean(oldVal) !== Boolean(newVal)) {
        changes.push({
          field: key,
          label,
          oldValue: Boolean(oldVal) ? "Sim" : "Não",
          newValue: Boolean(newVal) ? "Sim" : "Não"
        });
      }
    } else if (key === "dailyRate" || key === "totalAmount" || key === "paidAmount") {
      let numOld = Number(oldVal) || 0;
      const numNew = Number(newVal) || 0;
      if (key === "paidAmount" && numOld === 0 && wasOldEffectivelyPaidTotal && Number(oldRes?.totalAmount) > 0) {
        numOld = Number(oldRes.totalAmount);
      }
      if (Math.abs(numOld - numNew) > 0.01) {
        changes.push({
          field: key,
          label,
          oldValue: `R$ ${numOld.toFixed(2).replace(".", ",")}`,
          newValue: `R$ ${numNew.toFixed(2).replace(".", ",")}`
        });
      }
    } else if (key === "paymentStatus") {
      const rawOldSt = String(oldVal || "").trim();
      const rawNewSt = String(newVal || "").trim();
      const normOldSt = wasOldEffectivelyPaidTotal
        ? "pago_total"
        : (rawOldSt === "pago" ? "pago_total" : (rawOldSt === "parcial" ? "sinal_pago" : (rawOldSt || "pendente")));
      const normNewSt = rawNewSt === "pago"
        ? "pago_total"
        : (rawNewSt === "parcial" ? "sinal_pago" : (rawNewSt || "pendente"));
      if (normOldSt !== normNewSt) {
        changes.push({
          field: key,
          label,
          oldValue: PAYMENT_STATUS_LABELS[normOldSt] || rawOldSt || "(vazio)",
          newValue: PAYMENT_STATUS_LABELS[normNewSt] || rawNewSt || "(vazio)"
        });
      }
    } else if (key === "adults" || key === "children" || key === "guestCount") {
      const numOld = Number(oldVal) || 0;
      const numNew = Number(newVal) || 0;
      if (numOld !== numNew) {
        changes.push({
          field: key,
          label,
          oldValue: String(numOld),
          newValue: String(numNew)
        });
      }
    } else {
      const strOld = String(oldVal || "").trim();
      const strNew = String(newVal || "").trim();
      if (strOld !== strNew) {
        changes.push({
          field: key,
          label,
          oldValue: strOld || "(vazio)",
          newValue: strNew || "(vazio)"
        });
      }
    }
  }

  // Detalhamento individual de diárias (dailyRates)
  if (Array.isArray(newBody.dailyRates)) {
    const oldRates = Array.isArray(oldRes.dailyRates) ? oldRes.dailyRates : [];
    const summarizeRates = (rates) => rates.map(d => `${d.date}: R$ ${Number(d.rate || 0).toFixed(2).replace(".", ",")} (${d.channel || 'whatsapp'})`).join(", ");
    const oldSummary = summarizeRates(oldRates);
    const newSummary = summarizeRates(newBody.dailyRates);
    if (oldSummary !== newSummary && (oldRates.length > 0 || newBody.dailyRates.length > 0)) {
      changes.push({
        field: "dailyRates",
        label: "Detalhamento das Diárias",
        oldValue: oldSummary || "(tarifa única)",
        newValue: newSummary
      });
    }
  }

  // Detalhamento de pagamentos efetuados (payments)
  if (Array.isArray(newBody.payments)) {
    const oldPayments = Array.isArray(oldRes.payments) ? oldRes.payments : [];
    const summarizePayments = (pays) => pays.map(p => `R$ ${Number(p.amount || 0).toFixed(2).replace(".", ",")} via ${p.method || 'pix'}`).join(", ");
    const oldSumm = summarizePayments(oldPayments);
    const newSumm = summarizePayments(newBody.payments);
    if (oldSumm !== newSumm && (oldPayments.length > 0 || newBody.payments.length > 0)) {
      changes.push({
        field: "payments",
        label: "Lançamentos de Pagamento",
        oldValue: oldSumm || "(nenhum)",
        newValue: newSumm
      });
    }
  }

  return changes;
}

// ── Campos de Reserva Voltados ao Hóspede (Exclui notas internas de recepção) ─
export const GUEST_FACING_RESERVATION_FIELDS = new Set([
  "flatNumber",
  "checkinDate",
  "checkoutDate",
  "checkinTime",
  "checkoutTime",
  "guestCount",
  "adults",
  "children",
  "totalAmount",
  "paidAmount",
  "paymentStatus",
  "includeBreakfast",
  "guestName",
  "twinBeds",
  "extraMattress",
  "prefersHighFloor",
  "vehiclePlate",
  "specialRequests"
]);

export function filterGuestFacingDiffs(diffs = []) {
  if (!Array.isArray(diffs)) return [];
  return diffs.filter(d => GUEST_FACING_RESERVATION_FIELDS.has(d.field));
}

// ── Helpers de Veículo ───────────────────────────────────────────────────────
// Mescla dados do veículo: campos novos não-vazios prevalecem; campos vazios preservam
// o valor anterior apenas quando a placa é a mesma (placa nova = veículo novo, não herda dados).
export function mergeVehicleData(oldVehicle, input) {
  const plate = String(input?.plate || "").toUpperCase().trim();
  if (!plate) return null;
  const oldPlate = String(oldVehicle?.plate || "").toUpperCase().trim();
  const samePlate = Boolean(oldPlate) && oldPlate === plate;
  const pick = (k) => {
    const v = String(input?.[k] ?? "").trim();
    return v || (samePlate ? String(oldVehicle?.[k] || "").trim() : "");
  };
  return { plate, brand: pick("brand"), model: pick("model"), color: pick("color") };
}

export function getVehicleSignature(v) {
  if (!v) return "";
  return ["plate", "brand", "model", "color"]
    .map(k => String(v[k] || "").trim().toUpperCase())
    .join("|");
}

export function vehicleDetailsDiffer(a, b) {
  return getVehicleSignature(a) !== getVehicleSignature(b);
}

// Recupera e consome veículo pré-informado via WhatsApp antes da criação da reserva (identificável pelo telefone)
export function consumePendingVehicleForPhone(dbInstance, rawPhone) {
  try {
    const activeDb = dbInstance || (typeof db !== "undefined" ? db : null);
    if (!activeDb || !rawPhone) return null;
    const digits = String(rawPhone).replace(/\D/g, "");
    if (digits.length < 8) return null;
    const suffix = digits.slice(-8);

    let foundVehicle = null;

    if (Array.isArray(activeDb.whatsappConversations)) {
      for (const conv of activeDb.whatsappConversations) {
        const cDigits = String(conv?.phone || "").replace(/\D/g, "");
        if (cDigits.length >= 8 && cDigits.slice(-8) === suffix && conv.pendingVehicle?.plate) {
          foundVehicle = {
            plate: String(conv.pendingVehicle.plate).toUpperCase().trim(),
            brand: String(conv.pendingVehicle.brand || "").trim(),
            model: String(conv.pendingVehicle.model || "").trim(),
            color: String(conv.pendingVehicle.color || "").trim(),
            updatedAt: conv.pendingVehicle.updatedAt || new Date().toISOString()
          };
          conv.lastConsumedVehicle = { ...foundVehicle };
          delete conv.pendingVehicle;
          break;
        }
      }
    }

    if (!foundVehicle && Array.isArray(activeDb.guests)) {
      for (const g of activeDb.guests) {
        const gDigits = String(g?.phone || "").replace(/\D/g, "");
        if (gDigits.length >= 8 && gDigits.slice(-8) === suffix && g.pendingVehicle?.plate) {
          foundVehicle = {
            plate: String(g.pendingVehicle.plate).toUpperCase().trim(),
            brand: String(g.pendingVehicle.brand || "").trim(),
            model: String(g.pendingVehicle.model || "").trim(),
            color: String(g.pendingVehicle.color || "").trim(),
            updatedAt: g.pendingVehicle.updatedAt || new Date().toISOString()
          };
          g.vehicle = { ...foundVehicle };
          delete g.pendingVehicle;
          break;
        }
      }
    }

    return foundVehicle;
  } catch (err) {
    console.warn("[consumePendingVehicleForPhone] Aviso:", err.message);
    return null;
  }
}
globalThis.consumePendingVehicleForPhone = consumePendingVehicleForPhone;

// ── Serviço de Notificação & Autorização Automática de Garagem ───────────────
export function triggerGarageEmailNotification(db, saveDatabase, reservation, vehicleInput = null, options = {}) {
  try {
    if (!reservation) return null;

    const vehicle = vehicleInput || reservation.vehicle;
    if (!vehicle || !vehicle.plate) {
      return null;
    }

    const cleanPlate = String(vehicle.plate).toUpperCase().trim();
    if (!cleanPlate) return null;

    // Normaliza os dados do veículo (sem apagar marca/modelo/cor já salvos para a mesma placa)
    const merged = mergeVehicleData(reservation.vehicle, vehicle);
    const vehicleData = {
      ...merged,
      updatedAt: vehicle.updatedAt || new Date().toISOString()
    };
    const previousPlate = String(reservation.vehicle?.plate || "").toUpperCase().trim();
    reservation.vehicle = { ...(previousPlate === cleanPlate ? (reservation.vehicle || {}) : {}), ...vehicleData };

    // Regra de Pré-Reserva Estrita:
    // Não disparar e-mail de garagem para uma pré-reserva ainda aguardando pagamento.
    if (typeof isPreReservationBlocked === "function" && isPreReservationBlocked(reservation) && !options.force) {
      if (typeof saveDatabase === "function") saveDatabase();
      console.log(`[GarageService ⏳] Liberação de garagem retida para placa ${cleanPlate}: a reserva ${reservation.code || reservation.id} é uma pré-reserva aguardando pagamento.`);
      return {
        success: true,
        deferred: true,
        reason: "pre_reservation_unpaid",
        plate: cleanPlate,
        checkinDate: reservation.checkinDate
      };
    }

    // Regra de Comunicação Estrita:
    // Não disparar e-mail de reservas criadas ou alteradas para datas futuras para a garagem.
    // Apenas se a reserva for para o dia de hoje (ou estadias correntes).
    // Reservas futuras sempre aguardam o dia do check-in (rotina matinal das 07:00) para envio do e-mail.
    if (isReservationForFuture(reservation) && !options.forceImmediate) {
      if (typeof saveDatabase === "function") saveDatabase();
      console.log(`[GarageService ℹ️] Liberação de garagem retida para placa ${cleanPlate}: a reserva ${reservation.code || reservation.id} é para data futura (${reservation.checkinDate}). O e-mail para a garagem será enviado pontualmente no dia do check-in.`);
      return {
        success: true,
        deferred: true,
        reason: "future_reservation",
        plate: cleanPlate,
        checkinDate: reservation.checkinDate
      };
    }

    // Evita duplicatas idênticas (mesma placa E mesmos marca/modelo/cor), a não ser que forçado explicitamente
    // ou quando reenviado porque os gatilhos já haviam sido disparados antes da adição/atualização.
    const force = Boolean(options.force || options.retriggerIfAlreadySent);
    const currentSignature = getVehicleSignature(vehicleData);
    const lastSignature = reservation.vehicle?.lastNotifiedSignature
      ?? (reservation.vehicle?.lastNotifiedPlate ? `${String(reservation.vehicle.lastNotifiedPlate).toUpperCase().trim()}|||` : "");
    if (!force && reservation.vehicle?.garageNotifiedAt && lastSignature === currentSignature) {
      console.log(`[GarageService] Notificação já enviada para placa ${cleanPlate} da reserva ${reservation.code || reservation.id}. Ignorando duplicata.`);
      return null;
    }

    const flat = (db.flats || []).find(f => f.id === Number(reservation.flatId) || String(f.number) === String(reservation.flatNumber));
    const rawFlat = flat?.number || reservation.flatNumber || "113";
    const cleanFlat = String(rawFlat).replace(/^flat\s*/i, "").trim();
    const flatNum = cleanFlat || "113";
    const guestName = reservation.guestName || "Hóspede CorpFlats";

    // Destinatário: Garagem Promenade Soho (apenas para a garagem: promenadesoho@pfbestacionamentos.com.br)
    const garageEmail = options.recipientEmail || db.settings?.garageEmail || process.env.GARAGE_EMAIL || "promenadesoho@pfbestacionamentos.com.br";

    // Renderiza template oficial CorpFlats com número do Flat no assunto do e-mail
    const { subject, bodyHtml } = renderGarageAuthorizationEmail({
      reservation,
      flat,
      vehicle: vehicleData,
      settings: db.settings
    });

    // Disparo imediato e assíncrono via Nodemailer SMTP CorpFlats (exclusivo para a garagem)
    globalThis.sendEmailAsync = sendEmailAsync;
    const commLog = sendEmailAsync({
      db,
      saveDatabase,
      reservationId: reservation.code || reservation.id,
      recipient: garageEmail,
      subject,
      bodyHtml,
      type: "email",
      direction: "outbound",
      metadata: {
        trigger: options.trigger || "garage_authorization",
        flatNumber: flatNum,
        guestName,
        plate: cleanPlate,
        vehicleBrand: vehicleData.brand,
        vehicleModel: vehicleData.model,
        garageEmail
      }
    });

    // Caso os gatilhos da recepção já tivessem sido disparados anteriormente para esta reserva,
    // reenvia também o aviso de atualização à recepção com os dados do veículo adicionados.
    if (options.retriggerReceptionIfAlreadyNotified && typeof hasReceptionReceivedReservation === "function" && hasReceptionReceivedReservation(reservation, db)) {
      try {
        const receptionEmail = flat?.receptionEmail || db.settings?.receptionEmail || db.settings?.buildingEmail || process.env.RECEPTION_EMAIL || "soho@promenade.com.br";
        const newVehStr = `${cleanPlate}${[vehicleData.brand, vehicleData.model, vehicleData.color].filter(Boolean).length ? ` (${[vehicleData.brand, vehicleData.model, vehicleData.color].filter(Boolean).join(" / ")})` : ""}`;
        const changes = [
          {
            field: "vehiclePlate",
            label: "Veículo / Garagem Adicionado",
            oldValue: previousPlate && previousPlate !== cleanPlate ? `Placa ${previousPlate}` : "(atualização de veículo)",
            newValue: `Placa ${newVehStr}`
          }
        ];
        const { subject: recSubject, bodyHtml: recBodyHtml } = renderReservationUpdateEmail({
          reservation,
          flat,
          changes,
          settings: db.settings
        });
        sendEmailAsync({
          db,
          saveDatabase,
          reservationId: reservation.code || reservation.id,
          recipient: receptionEmail,
          subject: recSubject,
          bodyHtml: recBodyHtml,
          type: "email",
          direction: "outbound",
          metadata: {
            trigger: "vehicle_added_after_reception_trigger",
            flatNumber: flatNum,
            guestName,
            plate: cleanPlate,
            changes
          }
        });
      } catch (recErr) {
        console.warn("[GarageService] Aviso ao reenviar atualização de veículo para a recepção:", recErr.message);
      }
    }

    // Registra ou atualiza histórico em db.garageAuthorizations
    if (!db.garageAuthorizations) db.garageAuthorizations = [];
    const checkinStr = reservation.checkinDate || new Date().toISOString().slice(0, 10);
    const checkoutStr = reservation.checkoutDate || new Date(Date.now() + 86400000).toISOString().slice(0, 10);

    const authRecord = {
      id: Date.now(),
      plate: cleanPlate,
      brand: vehicleData.brand,
      model: vehicleData.model,
      color: vehicleData.color,
      guestName,
      flatNumber: String(flatNum),
      checkinDate: checkinStr,
      checkoutDate: checkoutStr,
      sentAt: new Date().toISOString(),
      recipientEmail: garageEmail,
      status: "autorizado",
      reservationCode: reservation.code || reservation.reservationCode || String(reservation.id)
    };
    db.garageAuthorizations.unshift(authRecord);

    // Notificação interna para a administração e painel
    if (db.notifications) {
      db.notifications.unshift({
        id: Date.now(),
        type: "garagem",
        title: `Veículo Autorizado: ${cleanPlate} (Flat ${flatNum})`,
        message: `Flat ${flatNum} • ${guestName} (${[vehicleData.brand, vehicleData.model].filter(Boolean).join(" ") || 'Carro'}) - Enviado para ${garageEmail}`,
        read: false,
        createdAt: new Date().toISOString()
      });
    }

    // Carimbo de envio na reserva
    reservation.vehicle.garageNotifiedAt = new Date().toISOString();
    reservation.vehicle.lastNotifiedPlate = cleanPlate;
    reservation.vehicle.lastNotifiedSignature = currentSignature;

    // Registro na trilha de auditoria da reserva
    if (typeof addReservationAuditLog === "function") {
      addReservationAuditLog(reservation, {
        action: "vehicle_authorized",
        actor: {
          id: options.actorId || null,
          name: options.actorName || "Sistema de Garagem CorpFlats",
          role: options.actorRole || "system",
          type: "system"
        },
        source: options.source || "Automação de Garagem",
        description: `Liberação de garagem enviada para ${garageEmail} (Placa ${cleanPlate})`,
        changes: [
          { field: "vehicle", label: "Autorização de Garagem", oldValue: null, newValue: `${cleanPlate} (${[vehicleData.brand, vehicleData.model].filter(Boolean).join(" ")})` }
        ]
      });
    }

    if (typeof saveDatabase === "function") saveDatabase();
    console.log(`[GarageService] ✓ Liberação de garagem enviada para ${garageEmail} - Placa ${cleanPlate}, Flat ${flatNum}`);
    return { success: true, authRecord, commLog };
  } catch (err) {
    console.error("[GarageService] Erro ao disparar autorização de garagem:", err);
    return null;
  }
}

