app.get("/api/auth/me", (req, res) => {
  const user = getAuthUser(req);
  if (!user) {
    res.clearCookie("auth_session", { path: "/" });
    res.clearCookie(AUTH_COOKIE_NAME, { path: "/" });
    return res.status(401).json({ error: "Não autenticado" });
  }
  res.json(user);
});

app.post("/api/auth/login", (req, res) => {
  const { username, password } = req.body || {};
  if (!username || !password) {
    return res.status(400).json({ error: "Informe usuário e senha." });
  }

  const found = db.users.find(u => u.username.toLowerCase() === username.trim().toLowerCase());
  if (!found) {
    return res.status(401).json({ error: "Usuário não encontrado." });
  }

  const isValid = verifyPassword(password, found.passwordHash);
  if (!isValid) {
    return res.status(401).json({ error: "Senha incorreta." });
  }

  const isRepositoraShift = found.role === "anserve_repositora";
  const shiftDate = isRepositoraShift ? getBrasiliaNow().date : undefined;
  const userPayload = {
    id: found.id,
    username: found.username,
    role: found.role,
    ...(shiftDate ? { shiftDate } : {}),
    v: AUTH_SESSION_VERSION
  };
  const token = createAuthToken(userPayload);
  res.cookie(AUTH_COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: isRepositoraShift ? 18 * 60 * 60 * 1000 : 30 * 24 * 60 * 60 * 1000 // Turno diário para repositora; 30 dias para demais perfis
  });
  const mustChange = !!found.must_change_password;
  const expired = typeof isPasswordExpired === "function" ? isPasswordExpired(found) : false;

  found.lastLoginAt = new Date().toISOString();
  if (found.role === "anserve_repositora") {
    sendRestockerWorkWhatsappCheckoutSummary(db, saveDatabase, {
      triggerType: "first_login",
      actorName: found.name || found.username
    }).catch(err => {
      console.warn("[Restocker 1st Login Summary Error]:", err?.message || err);
    });
  }

  res.json({
    id: found.id,
    username: found.username,
    role: found.role,
    name: found.name || found.username,
    ...(shiftDate ? { shiftDate } : {}),
    allowedModules: resolveEffectiveAllowedModules(found),
    mustChangePassword: mustChange,
    passwordExpired: expired
  });
});

app.post("/api/auth/logout", (req, res) => {
  if (req.body?.pushEndpoint) {
    try {
      removePushSubscription(db, saveDatabase, req.body.pushEndpoint);
    } catch {}
  }
  res.clearCookie("auth_session", { path: "/" });
  res.clearCookie(AUTH_COOKIE_NAME, { path: "/" });
  res.json({ success: true });
});

// Self Change Password
app.post("/api/auth/change-password", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth) return res.status(401).json({ error: "Não autenticado." });
  const { currentPassword, newPassword } = req.body || {};

  if (!currentPassword || !newPassword) {
    return res.status(400).json({ error: "Informe a senha atual e a nova senha." });
  }
  if (String(newPassword).length < 4) {
    return res.status(400).json({ error: "A nova senha deve ter no mínimo 4 caracteres." });
  }

  const user = db.users.find(u => u.id === userAuth.id);
  if (!user) return res.status(404).json({ error: "Usuário não encontrado." });

  if (!verifyPassword(currentPassword, user.passwordHash)) {
    return res.status(400).json({ error: "Senha atual incorreta." });
  }

  user.passwordHash = hashPassword(newPassword);
  saveDatabase();
  res.json({ success: true, message: "Senha alterada com sucesso!" });
});

