async function sendNewUserWelcomeCredentialsWhatsApp(userObj, plainPassword) {
  try {
    if (!userObj) return { sent: false, reason: "no_user" };
    const targetPhone = cleanWhatsAppPhone(userObj.whatsapp || userObj.phone || "");
    if (!targetPhone) return { sent: false, reason: "no_phone" };

    const serverBaseUrl = (process.env.SERVER_BASE_URL || db.settings?.baseUrl || "https://corpflats.com.br").replace(/\/+$/, "");
    const roleMap = {
      anserve_repositora: {
        label: "Repositora de Frigobar (Anserve)",
        url: `${serverBaseUrl}/frigobar-reposicao`
      },
      anserve_faturamento: {
        label: "Emissão de Notas Fiscais — Frigobar (Anserve)",
        url: `${serverBaseUrl}/frigobar-notas`
      },
      anserve_gestor: {
        label: "Gestor / Supervisor Anserve",
        url: `${serverBaseUrl}/frigobar-gestao`
      },
      camareira: {
        label: "Governança / Camareira",
        url: `${serverBaseUrl}/login`
      },
      recepcao: {
        label: "Recepção / Atendimento",
        url: `${serverBaseUrl}/login`
      },
      admin: {
        label: "Administração CorpFlats",
        url: `${serverBaseUrl}/login`
      },
      dev: {
        label: "Desenvolvedor / Diretoria",
        url: `${serverBaseUrl}/login`
      }
    };

    const roleInfo = roleMap[userObj.role] || {
      label: userObj.role || "Colaborador",
      url: `${serverBaseUrl}/login`
    };

    const pinLine =
      userObj.role === "anserve_repositora" || userObj.pin
        ? `\n🔢 *PIN Rápido (Celular):* ${userObj.pin || db.minibarSettings?.anservePin || "1234"}`
        : "";

    const welcomeMsg =
      `🎉 *Olá, ${userObj.name || userObj.username}! Bem-vindo(a) ao Sistema CorpFlats!*\n\n` +
      `Seu cadastro de acesso foi criado com sucesso. Confira abaixo suas credenciais e o link direto para entrar:\n\n` +
      `👤 *Perfil:* ${roleInfo.label}\n` +
      `🔗 *Link de Acesso:* ${roleInfo.url}\n` +
      `🔑 *Login (Usuário):* ${userObj.username}\n` +
      `🔒 *Senha Inicial:* ${plainPassword}${pinLine}\n\n` +
      `💡 _Salve este link nos favoritos do seu celular para acessar rapidamente no dia a dia!_`;

    const zapiConfig = db.settings?.zapiConfig || db.zapiConfig || {};
    const sendRes = await sendZapiMessage(zapiConfig, {
      phone: targetPhone,
      message: welcomeMsg,
      channelId: "service_providers",
      recipientRole: "staff",
      triggerEvent: "user_welcome_credentials",
      bypassTestMode: true,
      db
    });

    return { sent: true, phone: targetPhone, result: sendRes };
  } catch (err) {
    console.warn("[sendNewUserWelcomeCredentialsWhatsApp Error]:", err?.message || err);
    return { sent: false, error: err?.message };
  }
}

app.post("/api/admin/users", async (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) return res.status(403).json({ error: "Acesso negado." });
  const { username, password, role = "camareira", name, whatsapp, phone, pixKey, pin, allowedModules } = req.body || {};

  if (!username || !password) {
    return res.status(400).json({ error: "Nome de usuário e senha são obrigatórios." });
  }
  if (db.users.some(u => u.username.toLowerCase() === username.trim().toLowerCase())) {
    return res.status(409).json({ error: "Já existe um usuário com esse nome." });
  }

  // Apenas quem é dev pode criar outro dev
  let targetRole = role;
  if (targetRole === "dev" && userAuth.role !== "dev") {
    return res.status(403).json({ error: "Apenas desenvolvedores podem cadastrar usuários com perfil dev." });
  }
  const allowedRoles = ["dev", "admin", "recepcao", "camareira", "anserve_repositora", "anserve_gestor"];
  if (!allowedRoles.includes(targetRole)) {
    targetRole = "camareira";
  }

  // Tratamento de allowedModules (R2)
  let finalAllowedModules;
  if (Array.isArray(allowedModules)) {
    finalAllowedModules = Array.from(new Set(
      allowedModules
        .map(m => typeof m === "string" ? canonicalizeRoute(m.trim()) : "")
        .filter(m => ALL_CANONICAL_MODULES.includes(m))
    ));
    if (userAuth.role !== "dev") {
      finalAllowedModules = finalAllowedModules.filter(m => !DEV_ONLY_MODULES.includes(m));
    }
  } else {
    finalAllowedModules = getDefaultModulesForRole(targetRole);
  }

  const cleanPh = cleanWhatsAppPhone(whatsapp || phone || "");
  const newUser = {
    id: db.users.length > 0 ? Math.max(...db.users.map(u => u.id)) + 1 : 1,
    username: username.trim(),
    name: (name || username).trim(),
    role: targetRole,
    whatsapp: cleanPh,
    phone: cleanPh,
    pixKey: (pixKey || "").trim(),
    pin: pin ? String(pin).trim() : "",
    active: true,
    allowedModules: finalAllowedModules,
    passwordHash: hashPassword(password),
    password_updated_at: new Date().toISOString()
  };

  db.users.push(newUser);
  saveDatabase();

  // Envia automaticamente no WhatsApp do novo usuário o link de acesso, login, senha inicial e PIN
  let whatsappWelcomeSent = false;
  if (cleanPh) {
    const wRes = await sendNewUserWelcomeCredentialsWhatsApp(newUser, String(password).trim());
    whatsappWelcomeSent = Boolean(wRes?.sent);
  }

  res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    name: newUser.name,
    role: newUser.role,
    whatsapp: newUser.whatsapp,
    pixKey: newUser.pixKey,
    pin: newUser.pin,
    active: newUser.active,
    allowedModules: newUser.allowedModules,
    whatsappWelcomeSent
  });
});

app.patch("/api/admin/users/:id", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) return res.status(403).json({ error: "Acesso negado." });
  const id = Number(req.params.id);
  const user = (db.users || []).find(u => u.id === id);
  if (!user) return res.status(404).json({ error: "Usuário não encontrado." });

  // Apenas dev pode alterar dados de usuário dev
  if (user.role === "dev" && userAuth.role !== "dev") {
    return res.status(403).json({ error: "Apenas desenvolvedores podem alterar contas de desenvolvedor." });
  }

  const { name, username, role, whatsapp, phone, pixKey, pin, active, allowedModules } = req.body || {};

  if (username !== undefined && username.trim()) {
    const existing = db.users.find(u => u.id !== id && u.username.toLowerCase() === username.trim().toLowerCase());
    if (existing) return res.status(409).json({ error: "Já existe outro usuário com esse login." });
    user.username = username.trim();
  }
  if (name !== undefined) user.name = String(name).trim();

  let roleChanged = false;
  if (role !== undefined) {
    if (role === "dev" && userAuth.role !== "dev") {
      return res.status(403).json({ error: "Apenas desenvolvedores podem promover usuários a dev." });
    }
    const allowedRoles = ["dev", "admin", "camareira", "recepcao", "anserve_repositora", "anserve_gestor"];
    if (allowedRoles.includes(role)) {
      if (user.role !== role) {
        roleChanged = true;
        user.role = role;
      }
    }
  }

  // R2: Tratamento e persistência de allowedModules com segurança devOnly
  if (allowedModules !== undefined && Array.isArray(allowedModules)) {
    let sanitized = Array.from(new Set(
      allowedModules
        .map(m => typeof m === "string" ? canonicalizeRoute(m.trim()) : "")
        .filter(m => ALL_CANONICAL_MODULES.includes(m))
    ));
    if (userAuth.role !== "dev") {
      sanitized = sanitized.filter(m => !DEV_ONLY_MODULES.includes(m));
    }
    user.allowedModules = sanitized;
  } else if (roleChanged) {
    user.allowedModules = getDefaultModulesForRole(user.role);
  } else if (userAuth.role !== "dev" && Array.isArray(user.allowedModules)) {
    // Se não-dev está atualizando o usuário e o usuário já tinha módulos salvos, remove devOnly
    user.allowedModules = user.allowedModules.filter(m => !DEV_ONLY_MODULES.includes(m));
  }

  if (whatsapp !== undefined || phone !== undefined) {
    const cleanPh = cleanWhatsAppPhone(whatsapp || phone || "");
    user.whatsapp = cleanPh;
    user.phone = cleanPh;
  }
  if (pixKey !== undefined) user.pixKey = String(pixKey).trim();
  if (pin !== undefined) user.pin = String(pin).trim();
  if (active !== undefined) user.active = Boolean(active);

  saveDatabase();
  res.json({
    success: true,
    user: {
      id: user.id,
      username: user.username,
      name: user.name || user.username,
      role: user.role,
      whatsapp: user.whatsapp || "",
      phone: user.phone || "",
      pixKey: user.pixKey || "",
      pin: user.pin || "",
      active: user.active !== false,
      allowedModules: Array.isArray(user.allowedModules) ? user.allowedModules : getDefaultModulesForRole(user.role)
    }
  });
});

const handleResetPassword = (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) return res.status(403).json({ error: "Acesso negado." });
  const id = Number(req.params.id);
  const { newPassword } = req.body || {};

  if (!newPassword || String(newPassword).length < 4) {
    return res.status(400).json({ error: "A nova senha deve ter no mínimo 4 caracteres." });
  }

  const user = db.users.find(u => u.id === id);
  if (!user) return res.status(404).json({ error: "Usuário não encontrado." });

  // Apenas dev pode alterar senhas de contas dev
  if (user.role === "dev" && userAuth.role !== "dev") {
    return res.status(403).json({ error: "Apenas desenvolvedores podem alterar senhas de contas de desenvolvedor." });
  }

  user.passwordHash = hashPassword(newPassword);
  user.password_updated_at = new Date().toISOString();
  saveDatabase();
  res.json({ success: true, message: `Senha do usuário ${user.username} redefinida com sucesso!` });
};

