// ── Public Guest Checkout Context & Endpoints ──────────────────────────────
app.get("/api/public/checkout/context", (req, res) => {
  const code = (req.query.code || req.query.res || req.query.r || "").trim();
  if (!code) {
    return res.status(400).json({ error: "Código da reserva não informado." });
  }

  if (!db.reservations) db.reservations = [];
  const r = findReservationByLocatorOrContact(code);
  if (!r) {
    return res.status(404).json({ error: "Reserva não encontrada no sistema. Verifique o link ou procure a administração." });
  }

  const rawFlatNum = r.flatNumber ? String(r.flatNumber) : "";
  const flat = (db.flats || []).find(f => (rawFlatNum && (f.number === rawFlatNum || f.number.replace(/\D/g, "") === rawFlatNum.replace(/\D/g, ""))) || f.id === r.flatId);
  const resolvedFlatNum = flat ? flat.number : (rawFlatNum || "Flat");

  const nowBrl = getBrasiliaNow();
  const todayStr = nowBrl.date;

  const isAlreadyCheckedOut = Boolean(
    r.actualCheckoutAt ||
    r.status === "completed" ||
    r.status === "checked_out" ||
    (flat && !flat.isOccupied && (db.cleaningRequests || []).some(c => c.flatId === flat.id && c.requestDate === todayStr && c.isVacant))
  );

  const guestName = (r.guestName || r.guests?.[0]?.name || "Hóspede").trim();
  const firstName = guestName.split(" ")[0];

  res.json({
    success: true,
    reservation: {
      id: r.id,
      code: r.code || code,
      guestName,
      firstName,
      flatNumber: resolvedFlatNum,
      checkinDate: r.checkinDate,
      checkoutDate: r.checkoutDate,
      checkoutTime: r.checkoutTime || db.settings?.checkoutTime || "12:00",
      isAlreadyCheckedOut
    },
    flat: {
      number: resolvedFlatNum,
      isOccupied: flat ? flat.isOccupied : false
    }
  });
});

app.post("/api/public/checkout", async (req, res) => {
  let rawNum = String(req.body?.flatNumber || "").replace(/\D/g, "").trim();
  const code = String(req.body?.code || req.body?.res || req.body?.reservationCode || "").trim();
  let foundRes = null;

  if (code) {
    if (!db.reservations) db.reservations = [];
    foundRes = findReservationByLocatorOrContact(code);
    if (foundRes && !rawNum && foundRes.flatNumber) {
      rawNum = String(foundRes.flatNumber).replace(/\D/g, "").trim();
    }
  }

  if (!rawNum && !foundRes) {
    return res.status(400).json({ error: "Por favor, informe o código da reserva ou o número do apartamento." });
  }

  const flat = (db.flats || []).find(f =>
    (rawNum && (f.number === rawNum || f.number.replace(/\D/g, "") === rawNum)) ||
    (foundRes && (f.id === foundRes.flatId || (foundRes.flatNumber && f.number === String(foundRes.flatNumber))))
  );

  if (!flat) {
    return res.status(404).json({ error: `Apartamento ${rawNum || ""} não encontrado. Por favor, verifique o número ou contate a administração.` });
  }

  const todayStr = getTodayStr();
  let existing = db.cleaningRequests.find(r =>
    (r.flatId === flat.id || String(r.flatNumber) === String(flat.number)) &&
    r.requestDate === todayStr &&
    !r.isInstructionOnly &&
    r.source !== "manual_instruction" &&
    r.type !== "bed_adjustment_only" &&
    r.type !== "instruction"
  );

  const guestDisplayName = foundRes?.guestName || "Hóspede";
  const now = new Date().toISOString();
  if (existing) {
    if (existing.isDeleted || existing.status === "deleted") {
      existing.isDeleted = false;
      existing.status = "dirty";
      existing.completedAt = null;
      existing.cleaningStartedAt = null;
      existing.willCleanAt = null;
      delete existing.deletedAt;
      delete existing.deletedBy;
      delete existing.deletedReservationId;
    }
    existing.isVacant = true; // Confirma quarto desocupado via link
    existing.isVacantExplicitlySet = true;
    existing.vacantSource = "guest_checkout";
    existing.vacantSetAt = now;
    existing.leavingGuest = existing.leavingGuest || guestDisplayName;
    if (existing.pendingObservation) {
      existing.pendingObservation = sanitizeCardNote(existing.pendingObservation);
    }
    existing.updatedAt = now;
  } else {
    existing = {
      id: db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => r.id)) + 1 : 1,
      flatId: flat.id,
      flatNumber: flat.number,
      requestDate: todayStr,
      source: "guest_checkout",
      status: "dirty",
      assignedUserId: null,
      isVacant: true, // Já saiu via link
      isVacantExplicitlySet: true,
      vacantSource: "guest_checkout",
      vacantSetAt: now,
      isPriority: false, // Prioridade manual exclusiva do admin
      leavingGuest: guestDisplayName,
      arrivingGuest: null,
      pendingObservation: null, // Sem nota redundante; status "Desocupado" é exibido no badge visual
      willCleanAt: null,
      cleaningStartedAt: null,
      completedAt: null,
      createdAt: now,
      updatedAt: now,
    };
    db.cleaningRequests.unshift(existing);
  }

  flat.isOccupied = false;
  flat.updatedAt = now;

  const nowBrl = getBrasiliaNow();
  const timeStr = nowBrl.timeStr;

  // Atualizar a reserva identificada por código ou a reserva ativa/em andamento neste flat (incluindo Check-out Antecipado)
  const matchingResList = foundRes
    ? [foundRes]
    : findCheckoutTargetReservationsForFlat(db, flat.id, flat.number, todayStr);
  let anyEarlyCheckout = false;
  for (const r of matchingResList) {
    const earlyRes = await applyReservationCheckoutAndEarlyRelease(db, saveDatabase, r, {
      source: "link_digital",
      actorName: r.guestName || guestDisplayName,
      nowIso: now,
      todayStr,
      timeStr
    });
    if (earlyRes?.isEarlyCheckout) anyEarlyCheckout = true;

    // Dispara WhatsApp de check-out com desduplicação
    await triggerCheckoutWhatsApp(db, saveDatabase, r, "link_digital").catch(e => {
      console.warn("[Digital Checkout WhatsApp Trigger Error]:", e.message);
    });
  }

  // Cancela qualquer lembrete pendente de check-out ou estadia na fila (WhatsApp e E-mail) para este flat
  cancelPendingStayRemindersForCheckout(db, saveDatabase, {
    flatId: flat.id,
    flatNumber: flat.number,
    reason: "Cancelado: check-out realizado via link digital"
  });

  // Reconciliar pedidos de café da manhã complementares (para hoje antes do horário ou futuros caso check-out antecipado):
  if (!db.breakfastOrders) db.breakfastOrders = [];
  db.breakfastOrders.forEach(o => {
    const isMatch = String(o.roomNumber) === String(flat.number) || matchingResList.some(mr => mr.code === o.reservationCode || mr.id === o.reservationId);
    const orderDeliveryTime = o.deliveryTime || "08:00";
    const isTodayTarget = o.date === todayStr && (isTimeBefore(timeStr, orderDeliveryTime) || o.status === "pending");
    const isFutureTarget = anyEarlyCheckout && o.date > todayStr;
    if (isMatch && (isTodayTarget || isFutureTarget) && o.status !== "cancelled" && o.status !== "ready" && o.status !== "delivered") {
      o.status = "cancelled";
      o.manuallyReactivated = false;
      o.cancelledByCheckout = true;
      o.checkoutWarningInfo = {
        isEarlyCheckout: anyEarlyCheckout,
        reportedBy: "Hóspede via Link Digital",
        checkoutDate: todayStr,
        checkoutTime: timeStr,
        updatedAt: now
      };
      o.cancelReason = anyEarlyCheckout
        ? `Early check-out (Check-out antecipado): Hóspede informou saída via Link Digital às ${timeStr}. ⚠️ Confira se o check-out foi realmente feito antes de preparar o café!`
        : `Early check-out: Hóspede desocupou o quarto e saiu às ${timeStr} antes do horário do café (${orderDeliveryTime}). ⚠️ Confira se o check-out foi realmente feito antes de preparar o café!`;
    }
  });

  saveDatabase();

  // Trigger Notification for Checkout
  createNotification({
    category: "checkout",
    title: anyEarlyCheckout
      ? `⚡ Check-out Antecipado - Apt ${flat.number}`
      : `🚪 Check-out Realizado - Apt ${flat.number}`,
    message: anyEarlyCheckout
      ? `Saída antecipada de ${matchingResList[0]?.guestName || guestDisplayName} (Apt ${flat.number}) via Link Digital. Datas liberadas no calendário e quarto pronto para limpeza.`
      : `Saída do hóspede ${guestDisplayName} (Apt ${flat.number}) registrada. Quarto desocupado e pronto para limpeza.`,
    severity: anyEarlyCheckout ? "warning" : "info",
    metadata: { flatId: flat.id, flatNumber: flat.number, guestName: matchingResList[0]?.guestName || guestDisplayName, code: foundRes?.code || matchingResList[0]?.code, isEarlyCheckout: anyEarlyCheckout },
    targetUrl: anyEarlyCheckout ? "/reservas" : "/dashboard"
  });

  res.json({
    success: true,
    flatNumber: flat.number,
    guestName: guestDisplayName,
    message: "Check-out confirmado com sucesso!"
  });
});

// ── Service Orders Helper Functions ──────────────────────────────────────────
function getFlatServiceInProgress(flatId, flatNumber) {
  if (!Array.isArray(db.serviceOrders)) return null;
  const fId = Number(flatId);
  const fNum = String(flatNumber || "");
  let fallbackMatch = null;
  for (const order of db.serviceOrders) {
    if (order.status !== "active") continue;
    if (!Array.isArray(order.flats)) continue;
    const inProgFlat = order.flats.find(f =>
      f.status === "in_progress" &&
      (Number(f.flatId) === fId || (fNum && String(f.flatNumber) === fNum))
    );
    if (inProgFlat) {
      const allowSimul = Boolean(order.allowSimultaneousCleaning);
      const match = {
        serviceTitle: order.title,
        workerName: inProgFlat.workerName || "Prestador Externo",
        serviceOrderId: order.id,
        allowSimultaneousCleaning: allowSimul,
        blocksCleaning: !allowSimul
      };
      if (!allowSimul) return match;
      if (!fallbackMatch) fallbackMatch = match;
    }
  }
  return fallbackMatch;
}

function getFlatRealtimeStatus(flatId, flatNumber, dateStr = getTodayStr(), precomputedRequests = null) {
  const fId = Number(flatId);
  const fNum = String(flatNumber || "").trim();
  const fNumDigits = fNum.replace(/\D/g, "");
  const targetDate = String(dateStr || getTodayStr()).substring(0, 10);

  const matchesTargetFlat = (obj) => {
    if (!obj) return false;
    if (fId && Number(obj.flatId) === fId) return true;
    const objFlatNum = String(obj.flatNumber || "").trim();
    if (fNum && objFlatNum === fNum) return true;
    if (fNumDigits && objFlatNum.replace(/\D/g, "") === fNumDigits) return true;
    return false;
  };

  // 1. Ocupação em tempo real (Reservas ativas cobrindo a data de referência)
  const activeRes = (db.reservations || []).filter(r => {
    if (!matchesTargetFlat(r)) return false;
    const st = String(r.status || "").toLowerCase().trim();
    if (st === "cancelada" || st === "cancelado" || st === "cancelled" || st === "no_show" || st === "expirada") return false;
    if (typeof isPreReservationBlocked === "function" && isPreReservationBlocked(r)) return false;
    return true;
  });

  const isResCheckedOut = (r) => {
    if (!r) return false;
    const st = String(r.status || "").toLowerCase().trim();
    return Boolean(st === "checked_out" || st === "completed" || r.checkoutDone || r.earlyCheckout || r.actualCheckoutAt);
  };

  const stayoverRes = activeRes.find(r => {
    const ci = String(r.checkinDate || "").substring(0, 10);
    const co = String(r.checkoutDate || "").substring(0, 10);
    return ci && co && ci < targetDate && co > targetDate && !isResCheckedOut(r);
  });

  const checkinTodayRes = activeRes.find(r => {
    const ci = String(r.checkinDate || "").substring(0, 10);
    const co = String(r.checkoutDate || "").substring(0, 10);
    return ci === targetDate && (!co || co >= targetDate) && !isResCheckedOut(r);
  });

  const checkinSt = String(checkinTodayRes?.status || "").toLowerCase().trim();
  const isCheckedIn = Boolean(
    checkinTodayRes && (
      checkinSt === "checked_in" ||
      checkinSt === "checkin" ||
      checkinSt === "hospedado" ||
      checkinSt === "in_house" ||
      checkinTodayRes.checkinDone ||
      checkinTodayRes.checkedInAt ||
      checkinTodayRes.keyDelivered ||
      checkinTodayRes.accessLiberated
    )
  );

  const checkoutTodayRes =
    activeRes.find(r => String(r.checkoutDate || "").substring(0, 10) === targetDate && !isResCheckedOut(r)) ||
    activeRes.find(r => String(r.checkoutDate || "").substring(0, 10) === targetDate);
  const isCheckedOut = isResCheckedOut(checkoutTodayRes);

  const isOccupied = Boolean(stayoverRes || isCheckedIn || (checkoutTodayRes && !isCheckedOut));
  const currentGuest = stayoverRes ? (stayoverRes.guestName || stayoverRes.title) :
                       (checkoutTodayRes && !isCheckedOut) ? (checkoutTodayRes.guestName || checkoutTodayRes.title) :
                       isCheckedIn ? (checkinTodayRes.guestName || checkinTodayRes.title) :
                       checkinTodayRes ? (checkinTodayRes.guestName || checkinTodayRes.title) : null;
  const expectedArrival = checkinTodayRes ? (checkinTodayRes.estimatedArrivalTime || checkinTodayRes.arrivalTime || checkinTodayRes.eta || checkinTodayRes.checkinTime || "14:00") : null;

  // 2. Status de Higienização em Tempo Real (Apenas data consultada ou checkout recente)
  const dailyRequests = Array.isArray(precomputedRequests) ? precomputedRequests : (typeof getRequestsForDate === "function" ? getRequestsForDate(targetDate) : (db.cleaningRequests || []));
  const isCleaningCandidate = (c) =>
    matchesTargetFlat(c) &&
    !c.isDeleted &&
    c.status !== "deleted" &&
    !c.isInstructionOnly &&
    c.source !== "manual_instruction" &&
    c.type !== "instruction" &&
    c.type !== "bed_adjustment_only";

  const todayReq = dailyRequests.find(isCleaningCandidate);

  const directCandidates = (db.cleaningRequests || []).filter(c =>
    isCleaningCandidate(c) &&
    (String(c.requestDate || "").substring(0, 10) === targetDate || String(c.effectiveDate || "").substring(0, 10) === targetDate)
  );
  // Prioriza faxina em andamento, depois pendente/suja mais recente, depois concluída
  directCandidates.sort((a, b) => {
    const stA = a.cleaningRequest?.status || a.status;
    const stB = b.cleaningRequest?.status || b.status;
    const rank = (s) => (s === "in_progress" || s === "cleaning_now") ? 3 : (s === "dirty" || s === "pending" || s === "will_clean" || s === "pending_issue") ? 2 : 1;
    const rDiff = rank(stB) - rank(stA);
    if (rDiff !== 0) return rDiff;
    const tsA = a.updatedAt || a.createdAt || "";
    const tsB = b.updatedAt || b.createdAt || "";
    return tsB.localeCompare(tsA);
  });
  const directTodayReq = directCandidates[0] || null;

  // Se houver faxina ativamente em andamento no banco direto, prioriza sobre card cacheado
  const reqToEvaluate =
    (directTodayReq && (directTodayReq.status === "in_progress" || directTodayReq.status === "cleaning_now"))
      ? directTodayReq
      : (todayReq || directTodayReq);

  let isDirty = false;
  let cleaningStatus = "clean"; // "clean" | "dirty" | "in_progress"

  if (reqToEvaluate) {
    const st = reqToEvaluate.cleaningRequest?.status || reqToEvaluate.status;
    if (st === "deleted" || Boolean(reqToEvaluate.isDeleted)) {
      isDirty = false;
      cleaningStatus = "clean";
    } else if (st === "in_progress" || st === "cleaning_now") {
      isDirty = true;
      cleaningStatus = "in_progress";
    } else if (st === "dirty" || st === "pending" || st === "will_clean" || st === "pending_issue") {
      isDirty = true;
      cleaningStatus = "dirty";
    } else if (st === "clean" || st === "inspected" || Boolean(reqToEvaluate.completedAt)) {
      isDirty = false;
      cleaningStatus = "clean";
    }
  } else if (checkoutTodayRes) {
    if (isCheckedOut) {
      isDirty = true;
      cleaningStatus = "dirty";
    } else {
      isDirty = false;
      cleaningStatus = "clean";
    }
  } else {
    // Checkout recente (ontem) que ainda não teve faxina concluída
    const yesterdayStr = typeof getOffsetDateStr === "function" ? getOffsetDateStr(-1) : "";
    const recentCheckoutRes = yesterdayStr ? activeRes.find(r => String(r.checkoutDate || "").substring(0, 10) === yesterdayStr) : null;
    if (recentCheckoutRes) {
      const hasActiveDirtyYesterday = (db.cleaningRequests || []).some(c =>
        matchesTargetFlat(c) &&
        !c.isDeleted &&
        c.status !== "deleted" &&
        !c.isInstructionOnly &&
        c.source !== "manual_instruction" &&
        c.type !== "instruction" &&
        c.type !== "bed_adjustment_only" &&
        String(c.requestDate || "").substring(0, 10) === yesterdayStr &&
        c.status !== "clean" &&
        c.status !== "inspected" &&
        !c.completedAt
      );
      const recentClean = (db.cleaningRequests || []).find(c => {
        if (!matchesTargetFlat(c)) return false;
        if (c.isInstructionOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only") return false;
        const cReqDate = String(c.requestDate || "").substring(0, 10);
        const cEffDate = String(c.effectiveDate || "").substring(0, 10);
        if (cReqDate < yesterdayStr && cEffDate < yesterdayStr) return false;
        if (c.status === "clean" || c.status === "inspected" || Boolean(c.completedAt)) return true;
        if (
          !hasActiveDirtyYesterday &&
          cReqDate === yesterdayStr &&
          (c.status === "deleted" || Boolean(c.isDeleted)) &&
          c.deletedBy !== "pre_reservation_expired" &&
          c.deletedBy !== "reservation_cancelled" &&
          c.deletedBy !== "auto_orphan_checkout_cleanup"
        ) {
          return true;
        }
        return false;
      });
      if (!recentClean) {
        isDirty = true;
        cleaningStatus = "dirty";
      }
    }
  }

  return {
    isOccupied,
    isDirty,
    cleaningStatus,
    occupancyStatus: isOccupied ? "occupied" : "vacant",
    currentGuest: currentGuest || null,
    hasCheckinToday: Boolean(checkinTodayRes),
    expectedArrival,
    hasCheckoutToday: Boolean(checkoutTodayRes),
    isCheckedOut,
    isCheckedIn
  };
}

function isFlatDirty(flatId, flatNumber, dateStr = getTodayStr()) {
  const realtime = getFlatRealtimeStatus(flatId, flatNumber, dateStr);
  return Boolean(realtime.isDirty);
}

const OPERATIONAL_SCENARIOS = {
  vago_limpo: {
    id: "vago_limpo",
    label: "Vago & Limpo",
    icon: "🟢",
    description: "Apartamento vago, limpo e sem previsão de check-in para hoje.",
    defaultAllowed: true,
    warning: null,
    blockReason: "serviço não permite apartamentos limpos e vagos."
  },
  vago_sujo: {
    id: "vago_sujo",
    label: "Vago & Sujo",
    icon: "🧹",
    description: "Pós-checkout já concluído ou vago sujo, sem check-in hoje.",
    defaultAllowed: true,
    warning: null,
    blockReason: "serviço não permite apartamentos sujos."
  },
  checkin_hoje_limpo: {
    id: "checkin_hoje_limpo",
    label: "Check-in Hoje (Limpo)",
    icon: "🔵",
    description: "Quarto limpo e preparado aguardando a chegada do hóspede hoje.",
    defaultAllowed: false,
    warning: "Hóspede previsto para chegar hoje. Verifique se o serviço não atrasará a entrada.",
    blockReason: "quarto limpo aguardando check-in hoje não autorizado para este serviço."
  },
  checkin_hoje_sujo: {
    id: "checkin_hoje_sujo",
    label: "Check-in Hoje (Sujo)",
    icon: "🟡",
    description: "Hóspede chega hoje, mas quarto ainda está sujo aguardando faxina.",
    defaultAllowed: false,
    warning: "Hóspede chega hoje e o quarto ainda aguarda limpeza de camareira.",
    blockReason: "quarto com check-in hoje não autorizado para este serviço."
  },
  em_limpeza: {
    id: "em_limpeza",
    label: "Em Limpeza no Momento",
    icon: "🧽",
    description: "Camareira executando a faxina no apartamento agora.",
    defaultAllowed: false,
    warning: "Camareira em atendimento no apartamento no momento.",
    blockReason: "aguardando camareira finalizar a faxina."
  },
  stayover: {
    id: "stayover",
    label: "Hóspede em Estadia",
    icon: "🔴",
    description: "Hóspede ativo que dormiu ontem e continua hospedado.",
    defaultAllowed: false,
    warning: "⚠️ Hóspede no quarto. Bater na porta antes de entrar e verificar se foi comunicado.",
    hasGuestInside: true,
    blockReason: "hóspede no quarto não autorizado para este serviço."
  },
  checkout_pendente: {
    id: "checkout_pendente",
    label: "Check-out Hoje Pendente",
    icon: "🟠",
    description: "Hóspede com saída prevista para hoje que ainda não desocupou.",
    defaultAllowed: false,
    warning: "⚠️ Hóspede no quarto aguardando check-out. Bater na porta antes de entrar.",
    hasGuestInside: true,
    blockReason: "aguardando saída do hóspede (check-out hoje pendente)."
  }
};

const DEFAULT_ALLOWED_ROOM_STATUSES = ["vago_limpo", "vago_sujo"];
const VALID_ROOM_STATUSES = Object.keys(OPERATIONAL_SCENARIOS);

function getFlatOperationalScenario(flatId, flatNumber, dateStr = getTodayStr()) {
  const realtime = getFlatRealtimeStatus(flatId, flatNumber, dateStr);

  if (realtime.cleaningStatus === "in_progress") {
    return "em_limpeza";
  }
  if (realtime.hasCheckoutToday && !realtime.isCheckedOut) {
    return "checkout_pendente";
  }
  if (realtime.isOccupied || realtime.isCheckedIn) {
    return "stayover";
  }
  if (realtime.hasCheckinToday) {
    return realtime.isDirty ? "checkin_hoje_sujo" : "checkin_hoje_limpo";
  }
  return realtime.isDirty ? "vago_sujo" : "vago_limpo";
}

function getAllowedRoomStatuses(order) {
  if (Array.isArray(order?.allowedRoomStatuses)) {
    return order.allowedRoomStatuses.filter(s => VALID_ROOM_STATUSES.includes(s));
  }
  if (order?.cleanFlatMode === "always") {
    return ["vago_limpo", "vago_sujo", "checkin_hoje_limpo", "checkin_hoje_sujo"];
  }
  if (order?.cleanFlatMode === "never") {
    return ["vago_sujo"];
  }
  return [...DEFAULT_ALLOWED_ROOM_STATUSES];
}

function getEffectiveForceReleased(order, flat, scenario, realtime, todayStr = getTodayStr()) {
  if (!flat || flat.status !== "pending" || !flat.forceReleased) return false;
  const sc = scenario || (flat ? getFlatOperationalScenario(flat.flatId, flat.flatNumber, todayStr) : "vago_limpo");
  const updatedAt = flat.forceReleasedUpdatedAt || "";
  const latestResetOrRet = [flat.resetAt, flat.returnedAt].filter(Boolean).sort().pop() || "";

  // Só é válido se foi liberado explicitamente após 2026-11-06T18:00:00.000Z, na data de hoje, para o exato cenário operacional atual, e não houve reset/devolução posterior
  const isValid =
    updatedAt > "2026-11-06T18:00:00.000Z" &&
    flat.forceReleasedDate === todayStr &&
    flat.forceReleasedScenario === sc &&
    (!latestResetOrRet || updatedAt > latestResetOrRet);

  if (!isValid) {
    flat.forceReleased = false;
    flat.forceReleasedDate = null;
    flat.forceReleasedScenario = null;
    return false;
  }
  return true;
}

function evaluateServiceFlatFilter(order, flat, scenario, realtime, todayStr = getTodayStr()) {
  const allowedStatuses = getAllowedRoomStatuses(order);
  const rt = realtime || (flat ? getFlatRealtimeStatus(flat.flatId, flat.flatNumber, todayStr) : null);
  const sc = scenario || (flat ? getFlatOperationalScenario(flat.flatId, flat.flatNumber, todayStr) : "vago_limpo");
  const scenarioInfo = OPERATIONAL_SCENARIOS[sc] || {};
  const forceReleased = getEffectiveForceReleased(order, flat, sc, rt, todayStr);

  const hasPendingCheckoutGuest = Boolean(rt && rt.hasCheckoutToday && !rt.isCheckedOut);
  const hasStayoverGuest = Boolean(rt && (rt.isOccupied || rt.isCheckedIn) && !hasPendingCheckoutGuest);

  const allowedLabels = allowedStatuses.map(id => OPERATIONAL_SCENARIOS[id]?.label || id).join(", ") || "Nenhum";
  const violations = [];
  let blockReason = null;

  // 1. Trava de Hóspede com Check-out Hoje Pendente
  if (hasPendingCheckoutGuest && !allowedStatuses.includes("checkout_pendente")) {
    const reason = `Bloqueado: ${OPERATIONAL_SCENARIOS.checkout_pendente.blockReason}`;
    if (!blockReason) blockReason = reason;
    violations.push(`Há hóspede no flat com saída (check-out) pendente hoje${rt?.currentGuest ? ` (${rt.currentGuest})` : ""}, e o filtro da OS não permite "Check-out Hoje Pendente".`);
  }

  // 2. Trava de Hóspede em Estadia (Stayover ou Check-in já realizado hoje)
  if (hasStayoverGuest && !allowedStatuses.includes("stayover")) {
    const reason = `Bloqueado: ${OPERATIONAL_SCENARIOS.stayover.blockReason}`;
    if (!blockReason) blockReason = reason;
    violations.push(`Há hóspede em estadia no flat no momento${rt?.currentGuest ? ` (${rt.currentGuest})` : ""}, e o filtro da OS não permite "Hóspede em Estadia".`);
  }

  // 3. Trava de Camareira em Limpeza no Momento
  if (rt && rt.cleaningStatus === "in_progress" && !allowedStatuses.includes("em_limpeza")) {
    const reason = `Bloqueado: ${OPERATIONAL_SCENARIOS.em_limpeza.blockReason}`;
    if (!blockReason) blockReason = reason;
    violations.push(`A camareira está executando limpeza neste flat agora, e o filtro da OS não permite "Em Limpeza no Momento".`);
  }

  // 4. Trava de Check-in Hoje (quando não há hóspede ainda no quarto)
  if (rt && rt.hasCheckinToday && !hasPendingCheckoutGuest && !hasStayoverGuest && sc !== "em_limpeza") {
    const neededCheckinScenario = rt.isDirty ? "checkin_hoje_sujo" : "checkin_hoje_limpo";
    if (!allowedStatuses.includes(neededCheckinScenario)) {
      const reason = `Bloqueado: ${OPERATIONAL_SCENARIOS[neededCheckinScenario].blockReason}`;
      if (!blockReason) blockReason = reason;
      violations.push(`Há previsão de chegada de hóspede hoje (${rt.expectedArrival || "14:00"}), e o filtro da OS não permite "${OPERATIONAL_SCENARIOS[neededCheckinScenario].label}".`);
    }
  }

  // 5. Trava estrita do cenário operacional atual na lista allowedRoomStatuses
  if (!allowedStatuses.includes(sc)) {
    const reason = `Bloqueado: ${scenarioInfo.blockReason || "status não autorizado para este serviço."}`;
    if (!blockReason) blockReason = reason;
    const msg = `O apartamento está no status "${scenarioInfo.label || sc}", mas o filtro da OS só permite: ${allowedLabels}.`;
    if (!violations.includes(msg)) violations.push(msg);
  }

  // 6. Trava de cleanFlatMode ("never" ou "priority") para apartamentos limpos
  const isDirty = rt ? Boolean(rt.isDirty) : (flat ? isFlatDirty(flat.flatId, flat.flatNumber, todayStr) : false);
  const cleanFlatMode = order?.cleanFlatMode || (Array.isArray(order?.allowedRoomStatuses) ? "always" : "priority");
  if (!isDirty) {
    if (cleanFlatMode === "never") {
      const reason = "Bloqueado: este serviço não permite intervenção em apartamentos limpos.";
      if (!blockReason) blockReason = reason;
      violations.push("O apartamento está limpo, e a regra de limpeza desta OS bloqueia intervenção em flats limpos.");
    } else if (cleanFlatMode === "priority" && flat) {
      const otherDirty = (order?.flats || []).some(otherF => {
        if (!otherF || Number(otherF.flatId) === Number(flat.flatId) || otherF.status === "done") return false;
        if (!isFlatDirty(otherF.flatId, otherF.flatNumber, todayStr)) return false;
        const otherScenario = getFlatOperationalScenario(otherF.flatId, otherF.flatNumber, todayStr);
        return allowedStatuses.includes(otherScenario);
      });
      if (otherDirty) {
        const reason = "Bloqueado: existem outros apartamentos deste serviço com check-out ou pendência de limpeza. Priorize os apartamentos sujos primeiro.";
        if (!blockReason) blockReason = reason;
        violations.push("O apartamento está limpo e existem outros flats sujos disponíveis nesta OS que devem ser priorizados primeiro.");
      }
    }
  }

  const filterAllowed = violations.length === 0 && !blockReason;
  const allowed = filterAllowed || forceReleased;

  return {
    filterAllowed,
    forceReleased,
    allowed,
    scenario: sc,
    blockReason: filterAllowed ? null : blockReason,
    violations
  };
}

function isServiceFlatStatusAllowed(order, flat, scenario, realtime, todayStr = getTodayStr()) {
  return evaluateServiceFlatFilter(order, flat, scenario, realtime, todayStr).allowed;
}

function formatServiceDuration(startIso, endIso) {
  if (!startIso || !endIso) return "0 min";
  const start = new Date(startIso).getTime();
  const end = new Date(endIso).getTime();
  const diffMs = Math.max(0, end - start);
  const totalMins = Math.round(diffMs / 60000);
  const hours = Math.floor(totalMins / 60);
  const mins = totalMins % 60;
  if (hours > 0 && mins > 0) return `${hours}h ${mins}min`;
  if (hours > 0) return `${hours}h`;
  return `${mins}min`;
}

function formatDateTimeShort(isoStr) {
  if (!isoStr) return "";
  try {
    const d = new Date(isoStr);
    return d.toLocaleString("pt-BR", {
      timeZone: "America/Sao_Paulo",
      day: "2-digit",
      month: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    });
  } catch {
    return isoStr;
  }
}

async function dispatchServiceNotifications(action, order, flat, worker, extraData = {}) {
  try {
    const timeFormatter = new Intl.DateTimeFormat("pt-BR", {
      timeZone: "America/Sao_Paulo",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    });
    const nowTimeStr = timeFormatter.format(new Date());

    const workerName = (worker?.mainWorker?.name || flat.workerName || "Prestador").trim();
    const workerCpf = worker?.mainWorker?.cpf || flat.workerCpf || "";
    const collaboratorsList = Array.isArray(worker?.collaborators) ? worker.collaborators : [];
    const collabsStr = collaboratorsList.length > 0
      ? collaboratorsList.map(c => `${c.name}${c.cpf ? ` (CPF: ${c.cpf})` : ""}`).join(", ")
      : "Nenhum (profissional individual)";

    const vehicle = worker?.vehicle || extraData?.vehicle;
    const vehicleStr = vehicle?.needsGarage
      ? `SIM 🚗 — Placa: ${vehicle.plate || "Não informada"} | Modelo/Cor: ${vehicle.modelColor || "Não informado"}`
      : "Não necessita de garagem";

    const todayStr = getTodayStr();
    const realtime = getFlatRealtimeStatus(flat.flatId, flat.flatNumber, todayStr);
    const scenario = getFlatOperationalScenario(flat.flatId, flat.flatNumber, todayStr);
    const isGuestInside = scenario === "stayover" || scenario === "checkout_pendente" || Boolean(realtime.isOccupied) || Boolean(extraData?.hasGuestInside);

    let message = "";
    if (action === "entry_request") {
      const guestWarningLine = isGuestInside
        ? "⚠️ *ATENÇÃO: Quarto ocupado por hóspede. Verificar comunicação prévia antes de liberar o acesso.*"
        : null;

      message = [
        `🔑 *Solicitação de Liberação de Entrada* — ${order.title}`,
        `🏠 Flat *${flat.flatNumber}*`,
        guestWarningLine,
        `👤 Prestador: ${workerName}${workerCpf ? ` · CPF: ${workerCpf}` : ""}`,
        `👥 Ajudante(s): ${collabsStr}`,
        `🚗 Garagem/Veículo: ${vehicleStr}`,
        `⏰ Horário: ${nowTimeStr}`,
        `➡️ *Ação para Recepção:* Favor liberar o acesso / cartão ao flat ${flat.flatNumber} para o profissional.`
      ].filter(Boolean).join("\n");
    } else if (action === "start") {
      const estFinishStr = flat.estimatedFinishAt
        ? formatDateTimeShort(flat.estimatedFinishAt)
        : (order.estimatedDurationHours ? `${order.estimatedDurationHours}h` : "2h");
      const guestWarningLine = isGuestInside
        ? "⚠️ *ATENÇÃO: Quarto ocupado por hóspede. Verificar comunicação prévia antes de liberar o acesso e bater na porta antes de entrar.*"
        : null;

      message = [
        `🔧 *Serviço iniciado* — ${order.title}`,
        `🏠 Flat *${flat.flatNumber}* | Prestador: ${workerName}${workerCpf ? ` · CPF: ${workerCpf}` : ""}`,
        guestWarningLine,
        `⏰ Início: ${nowTimeStr} · Previsão de término: ${estFinishStr}`,
        `➡️ Cartão de acesso liberado ao flat ${flat.flatNumber}`
      ].filter(Boolean).join("\n");
    } else if (action === "delay" || action === "overdue_alert") {
      const estFinishStr = flat.estimatedFinishAt ? formatDateTimeShort(flat.estimatedFinishAt) : "--:--";
      const isOverdue = action === "overdue_alert";
      message = [
        isOverdue ? `⚠️ *Alerta: Serviço com Previsão Expirada* — ${order.title}` : `⏱️ *Previsão de Término Atualizada* — ${order.title}`,
        `🏠 Flat *${flat.flatNumber}* | Prestador: ${workerName}${workerCpf ? ` · CPF: ${workerCpf}` : ""}`,
        `⏰ ${isOverdue ? "Previsão expirada em:" : "Nova previsão de término:"} ${estFinishStr}`,
        extraData?.reason ? `📝 Motivo: "${extraData.reason}"` : "",
        `➡️ Status: Em andamento no flat ${flat.flatNumber}.`
      ].filter(Boolean).join("\n");
    } else if (action === "flat_returned") {
      const prevStageLabel = extraData?.returnedFromStatus === "in_progress"
        ? "Serviço já iniciado (em andamento)"
        : "Após solicitar liberação de entrada";
      const accessedLabel = extraData?.accessedRoom ? "SIM (entrou no quarto)" : "NÃO (não chegou a entrar)";
      const cleaningLabel = extraData?.accessedRoom
        ? (extraData?.needsCleaning ? "SIM (card de conferência/limpeza gerado para a camareira)" : "NÃO (quarto mantido limpo/intacto)")
        : "Não aplicável (não acessou o quarto)";

      message = [
        `↩️ *Flat Devolvido pelo Prestador (Sem Execução)* — ${order.title}`,
        `🏠 Flat *${flat.flatNumber}* | Prestador: ${workerName}${workerCpf ? ` · CPF: ${workerCpf}` : ""}`,
        `📌 Etapa em que devolveu: ${prevStageLabel}`,
        `🚪 Acessou o quarto: *${accessedLabel}*`,
        `🧹 Precisa de limpeza/conferência: *${cleaningLabel}*`,
        extraData?.reason ? `📝 Motivo/Obs: "${extraData.reason}"` : `📝 Motivo/Obs: Não informado`,
        `⏰ Horário: ${nowTimeStr}`,
        `✅ Bloqueio removido e flat retornado para pendente.`
      ].filter(Boolean).join("\n");
    } else {
      const startTimeStr = flat.startedAt ? timeFormatter.format(new Date(flat.startedAt)) : "--:--";
      const finishTimeStr = flat.finishedAt ? timeFormatter.format(new Date(flat.finishedAt)) : nowTimeStr;
      const durationStr = formatServiceDuration(flat.startedAt, flat.finishedAt);
      const cleaningStr = flat.needsCleaning === true ? "Sim" : (flat.needsCleaning === false ? "Não" : "N.A.");
      const obsStr = flat.observations ? `"${flat.observations}"` : '"Nenhuma"';
      const photosCount = Array.isArray(flat.photos) ? flat.photos.length : 0;

      message = [
        `✅ *Serviço finalizado* — ${order.title}`,
        `🏠 Flat *${flat.flatNumber}* | Prestador: ${workerName}`,
        `⏰ ${startTimeStr} → ${finishTimeStr} (${durationStr})`,
        `🧹 Precisa camareira: *${cleaningStr}*`,
        `📝 Obs: ${obsStr}`,
        `📷 ${photosCount} foto(s)${photosCount > 0 ? " (enviadas abaixo)" : " disponíveis no sistema"}`
      ].join("\n");
    }

    // 0. Notificação Interna e Registro no Audit Log Imediatos (Sem bloqueio por I/O de rede externa)
    try {
      const notifTitle = action === "entry_request" ? `🔑 Solicitação de Entrada - Flat ${flat.flatNumber}` :
                         action === "start" ? `🔧 Serviço iniciado - Flat ${flat.flatNumber}` :
                         action === "finish" ? `✅ Serviço finalizado - Flat ${flat.flatNumber}` :
                         action === "flat_returned" ? `↩️ Flat devolvido (sem execução) - Flat ${flat.flatNumber}` :
                         action === "overdue_alert" ? `⚠️ Previsão expirada - Flat ${flat.flatNumber}` :
                         `⏱️ Previsão atualizada - Flat ${flat.flatNumber}`;
      createNotification({
        category: "service_order",
        title: notifTitle,
        message: action === "flat_returned"
          ? `${order.title}: ${workerName} devolveu o Flat ${flat.flatNumber} sem executar (${extraData?.accessedRoom ? (extraData?.needsCleaning ? "Acessou • Precisa limpeza" : "Acessou • Não precisa limpeza") : "Não acessou o quarto"})`
          : `${order.title}: ${workerName} no Flat ${flat.flatNumber}`,
        severity: (action === "overdue_alert" || action === "flat_returned") ? "warning" : "info",
        metadata: {
          serviceOrderId: order.id,
          flatId: flat.flatId,
          flatNumber: flat.flatNumber,
          action,
          startedAt: flat.startedAt || null,
          finishedAt: flat.finishedAt || null,
          estimatedFinishAt: flat.estimatedFinishAt || null,
          workerName: flat.workerName || workerName || null,
          workerCpf: flat.workerCpf || workerCpf || null,
          observations: flat.observations || extraData?.reason || null,
          photos: Array.isArray(flat.photos) ? flat.photos : [],
          needsCleaning: typeof flat.needsCleaning === "boolean" ? flat.needsCleaning : (typeof extraData?.needsCleaning === "boolean" ? extraData.needsCleaning : null),
          wasCleanWhenStarted: typeof flat.wasCleanWhenStarted === "boolean" ? flat.wasCleanWhenStarted : null,
          entryRequested: Boolean(flat.entryRequested),
          entryRequestedAt: flat.entryRequestedAt || null,
          returnedAt: flat.returnedAt || null,
          returnedFromStatus: extraData?.returnedFromStatus || null,
          accessedRoom: typeof extraData?.accessedRoom === "boolean" ? extraData.accessedRoom : null
        },
        targetUrl: `/servicos`
      });
    } catch (notifErr) {
      console.warn("[ServiceOrder] Falha ao registrar notificação interna:", notifErr?.message || notifErr);
    }

    // 1. WhatsApp Admin (5522998505276)
    const adminPhone = "5522998505276";
    const rawReceptionPhone = db.settings?.receptionPhone || db.settings?.receptionWhatsApp || db.siteConfig?.branding?.whatsapp || db.users?.find(u => u.role === "recepcao")?.whatsapp || db.settings?.adminWhatsApp || "5522997124021";
    const cleanReceptionPhone = cleanWhatsAppPhone ? cleanWhatsAppPhone(rawReceptionPhone) : String(rawReceptionPhone).replace(/\D/g, "");

    const targetPhones = new Set();
    const targetEmails = new Set();

    const normalizeEvents = (evts) => {
      if (!Array.isArray(evts)) return [];
      return evts.map(e => String(e).toLowerCase().trim());
    };

    const hasEvent = (evts, ev) => {
      const list = normalizeEvents(evts);
      if (list.includes("all") || list.includes("todos")) return true;
      if (ev === "entry_request") return list.includes("entry_request") || list.includes("solicitacao_entrada") || list.includes("liberacao");
      if (ev === "start") return list.includes("start") || list.includes("inicio");
      if (ev === "finish") return list.includes("finish") || list.includes("fim") || list.includes("finalizacao");
      if (ev === "delay" || ev === "overdue_alert") {
        return list.includes("delay") || list.includes("atraso") || list.includes("previsao") || list.includes("start") || list.includes("inicio") || list.includes("finish") || list.includes("fim") || list.includes("finalizacao");
      }
      return false;
    };

    if (action === "flat_returned") {
      // Regra de Negócio: Na devolução de flat sem execução, notifica APENAS o Miller (Admin) via WhatsApp
      targetPhones.add(adminPhone);
    } else if (Array.isArray(order.notificationRecipients) && order.notificationRecipients.length > 0) {
      for (const rec of order.notificationRecipients) {
        if (!rec || rec.enabled === false) continue;
        let shouldNotify = hasEvent(rec.events, action);
        // Se for notificação de liberação de entrada e o destinatário for da garagem, apenas envia se o prestador informou uso de garagem
        if (action === "entry_request" && (rec.role === "garage" || /garagem/i.test(rec.name))) {
          if (!vehicle?.needsGarage && !rec.events?.includes("all")) {
            shouldNotify = false;
          }
        }
        if (shouldNotify) {
          const cp = cleanWhatsAppPhone ? cleanWhatsAppPhone(rec.phone) : String(rec.phone || "").replace(/\D/g, "");
          if (cp) targetPhones.add(cp);
          if (rec.email && String(rec.email).includes("@")) targetEmails.add(rec.email.trim());
        }
      }
    } else {
      // Default fallback routing:
      if (action === "entry_request") {
        if (cleanReceptionPhone) targetPhones.add(cleanReceptionPhone);
      } else {
        targetPhones.add(adminPhone);
        if (cleanReceptionPhone) targetPhones.add(cleanReceptionPhone);
      }
      const receptionEmail = db.settings?.receptionEmail || db.settings?.buildingEmail || process.env.RECEPTION_EMAIL || "soho@promenade.com.br";
      if (receptionEmail) targetEmails.add(receptionEmail);
    }

    // 1b. Notificar o prestador de serviço diretamente se o serviço estiver atrasado / previsão expirada (Requirement 4)
    if (action === "overdue_alert") {
      const workerPhone = worker?.mainWorker?.phone || flat.workerPhone || order.workerPhone;
      const cleanWp = workerPhone ? (cleanWhatsAppPhone ? cleanWhatsAppPhone(workerPhone) : String(workerPhone).replace(/\D/g, "")) : null;
      if (cleanWp && typeof sendZapiMessage === "function") {
        const estFinishStr = flat.estimatedFinishAt ? formatDateTimeShort(flat.estimatedFinishAt) : "--:--";
        const serverBaseUrl = process.env.SERVER_BASE_URL || process.env.APP_BASE_URL || db.settings?.serverBaseUrl || db.siteConfig?.branding?.siteUrl || db.zapiConfig?.publicOrigin || "https://corpflats.com.br";
        const portalUrl = `${serverBaseUrl.replace(/\/+$/, "")}/servico/${order.token}`;
        const workerPromptMsg = [
          `⚠️ *Aviso de Previsão de Serviço* — Flat *${flat.flatNumber}*`,
          `Olá, ${workerName}! O serviço *${order.title}* no Flat ${flat.flatNumber} estava previsto para finalizar às *${estFinishStr}* e consta em andamento.`,
          `Caso precise de mais tempo, por favor acesse o link abaixo para atualizar a nova previsão de término:`,
          `🔗 ${portalUrl}`
        ].join("\n");
        sendZapiMessage(db.zapiConfig, {
          phone: cleanWp,
          message: workerPromptMsg,
          channelId: "service_providers",
          recipientRole: "service_worker",
          triggerEvent: "service_order_overdue_alert",
          db
        }).then(waRes => {
          if (!db.whatsappHistory) db.whatsappHistory = [];
          db.whatsappHistory.push({
            id: `svc_overdue_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
            guestName: workerName || "Prestador",
            guestPhone: cleanWp,
            triggerEvent: "service_order_overdue_alert",
            message: workerPromptMsg,
            sentAt: new Date().toISOString(),
            status: waRes?.success ? "sent" : "failed",
            method: waRes?.simulated ? "simulated" : "zapi",
            error: waRes?.error || null
          });
        }).catch(err => console.warn(`[ServiceOrder] WhatsApp overdue prompt to worker ${cleanWp} failed:`, err.message));
      }
    }

    if (typeof sendZapiMessage === "function") {
      for (const phone of targetPhones) {
        sendZapiMessage(db.zapiConfig, {
          phone,
          message,
          channelId: "reception",
          recipientRole: "reception",
          triggerEvent: `service_order_${action}`,
          db
        }).then(waRes => {
          if (!db.whatsappHistory) db.whatsappHistory = [];
          db.whatsappHistory.push({
            id: `svc_${action}_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
            guestName: `Ordem de Serviço (${order.title})`,
            guestPhone: phone,
            triggerEvent: `service_order_${action}`,
            message,
            sentAt: new Date().toISOString(),
            status: waRes?.success ? "sent" : "failed",
            method: waRes?.simulated ? "simulated" : "zapi",
            error: waRes?.error || null
          });
        }).catch(err => console.warn(`[ServiceOrder] WhatsApp to ${phone} failed:`, err.message));
      }
    }

    // 2b. Enviar fotos via WhatsApp (somente na finalização)
    if (action === "finish" && Array.isArray(flat.photos) && flat.photos.length > 0) {
      const zapiCfg = db.zapiConfig;
      const instanceId = zapiCfg?.instanceId?.trim();
      const token = zapiCfg?.token?.trim();
      const clientToken = zapiCfg?.clientToken?.trim();
      const baseUrl = (zapiCfg?.baseUrl || "https://api.z-api.io").replace(/\/+$/, "");
      const sendImageToPhone = async (phone, photoUrl, caption) => {
        if (!phone) return;
        const policy = evaluateZapiChannelPolicy(zapiCfg, {
          channelId: "reception",
          phone,
          message: caption || "",
          db
        });
        if (!policy.allowed) return;
        if (!instanceId || !token) return;
        const url = `${baseUrl}/instances/${instanceId}/token/${token}/send-image`;
        const headers = { "Content-Type": "application/json" };
        if (clientToken) headers["Client-Token"] = clientToken;
        try {
          await fetch(url, {
            method: "POST",
            headers,
            body: JSON.stringify({
              phone: policy.targetPhone || phone,
              image: photoUrl,
              caption: policy.finalMessage || caption || ""
            })
          });
        } catch (imgErr) {
          console.warn(`[ServiceOrder] Falha ao enviar foto ${photoUrl} via WhatsApp para ${policy.targetPhone || phone}:`, imgErr.message);
        }
      };

      const serverBaseUrl = process.env.SERVER_BASE_URL || process.env.APP_BASE_URL || db.settings?.serverBaseUrl || db.siteConfig?.branding?.siteUrl || db.zapiConfig?.publicOrigin || "";
      for (let i = 0; i < flat.photos.length; i++) {
        const rawUrl = flat.photos[i];
        const photoUrl = rawUrl && rawUrl.startsWith("http") ? rawUrl : (serverBaseUrl ? `${serverBaseUrl.replace(/\/+$/, "")}${rawUrl}` : rawUrl);
        const caption = `📷 Flat ${flat.flatNumber} – ${order.title} (${i + 1}/${flat.photos.length})`;
        if (photoUrl) {
          for (const phone of targetPhones) {
            await sendImageToPhone(phone, photoUrl, caption);
          }
        }
      }
    }

    // 3. Email Reception / Destinatários
    if (targetEmails.size > 0 && typeof sendEmailAsync === "function") {
      const actionName = action === "start" ? "Iniciado" : action === "finish" ? "Finalizado" : action === "entry_request" ? "Solicitação de Entrada" : "Aviso de Previsão";
      const subject = `[CorpFlats] Serviço ${actionName} - Flat ${flat.flatNumber} (${order.title})`;
      const bodyHtml = `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; color: #1e293b; line-height: 1.5;">
          <h2 style="color: ${action === "start" ? "#0284c7" : action === "finish" ? "#16a34a" : "#d97706"};">
            ${action === "start" ? "🔧 Serviço Externo Iniciado" : action === "finish" ? "✅ Serviço Externo Finalizado" : action === "entry_request" ? "🔑 Solicitação de Entrada no Flat" : "⏱️ Atualização de Previsão"}
          </h2>
          <p><strong>Serviço:</strong> ${order.title}</p>
          <p><strong>Apartamento:</strong> Flat ${flat.flatNumber}</p>
          <p><strong>Prestador:</strong> ${workerName}${workerCpf ? ` (CPF: ${workerCpf})` : ""}</p>
          ${action === "entry_request" ? `
            <p><strong>Ajudantes:</strong> ${collabsStr}</p>
            <p><strong>Garagem:</strong> ${vehicleStr}</p>
            <div style="background-color: #fef3c7; padding: 12px; border-left: 4px solid #d97706; margin-top: 15px; border-radius: 4px;">
              ➡️ <strong>Ação para Recepção/Portaria:</strong> Favor autorizar entrada e liberar cartão de acesso para o Flat ${flat.flatNumber}.
            </div>
          ` : action === "start" ? `
            <p><strong>Início:</strong> ${nowTimeStr}</p>
            <p><strong>Previsão de Término:</strong> ${flat.estimatedFinishAt ? formatDateTimeShort(flat.estimatedFinishAt) : `${order.estimatedDurationHours || 2}h`}</p>
            <div style="background-color: #f0f9ff; padding: 12px; border-left: 4px solid #0284c7; margin-top: 15px; border-radius: 4px;">
              ➡️ <strong>Ação para Recepção:</strong> Favor liberar o cartão de acesso para o prestador ao Flat ${flat.flatNumber}.
            </div>
          ` : action === "finish" ? `
            <p><strong>Duração:</strong> ${formatServiceDuration(flat.startedAt, flat.finishedAt)}</p>
            <p><strong>Precisa de Camareira:</strong> ${flat.needsCleaning === true ? "Sim" : (flat.needsCleaning === false ? "Não" : "N.A.")}</p>
            <p><strong>Observações:</strong> ${flat.observations || "Nenhuma observação informada."}</p>
            <p><strong>Fotos Anexadas:</strong> ${Array.isArray(flat.photos) ? flat.photos.length : 0}</p>
          ` : `
            <p><strong>Previsão de Término:</strong> ${flat.estimatedFinishAt ? formatDateTimeShort(flat.estimatedFinishAt) : "--:--"}</p>
            ${extraData?.reason ? `<p><strong>Motivo:</strong> ${extraData.reason}</p>` : ""}
          `}
          <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 20px 0;" />
          <p style="font-size: 12px; color: #64748b;">Notificação enviada automaticamente pelo sistema CorpFlats Guest-Flow-Manager.</p>
        </div>
      `;

      for (const email of targetEmails) {
        try {
          sendEmailAsync({
            db,
            saveDatabase,
            reservationId: "0",
            recipient: email,
            to: email,
            subject,
            emailSubject: subject,
            bodyHtml,
            html: bodyHtml,
            emailHtml: bodyHtml,
            metadata: {
              category: "service_order",
              serviceOrderId: order.id,
              flatNumber: flat.flatNumber,
              flatId: flat.flatId,
              action
            }
          });
        } catch (emailErr) {
          console.warn(`[SERVICE-ORDERS] Erro ao enviar email para ${email}:`, emailErr?.message || emailErr);
        }
      }
    }
  } catch (err) {
    console.error("[ServiceOrder] Error dispatching notifications:", err);
  }
}

function checkAndNotifyAvailableServiceFlats(targetOrderId = null, options = {}) {
  try {
    if (pgPool && !pgHydratedSuccessfully) return [];
    if (!Array.isArray(db.serviceOrders)) return [];
    if (!Array.isArray(db.serviceWorkers)) db.serviceWorkers = [];
    const todayStr = getTodayStr();
    const nowIso = new Date().toISOString();
    const nowMs = Date.now();
    let updated = false;
    const notificationsSent = [];

    for (const order of db.serviceOrders) {
      if (order.status !== "active") continue;
      if (targetOrderId && String(order.id) !== String(targetOrderId) && String(order.token) !== String(targetOrderId)) continue;

      const worker = db.serviceWorkers.find(
        w => (w.token === order.token || w.serviceOrderId === order.id)
      );
      const rawPhone = worker?.mainWorker?.phone || order.workerPhone || "";
      const cleanWp = rawPhone ? (cleanWhatsAppPhone ? cleanWhatsAppPhone(rawPhone) : String(rawPhone).replace(/\D/g, "")) : "";
      if (!cleanWp || cleanWp.length < 10) continue;

      const workerName = (worker?.mainWorker?.name || order.workerName || "Prestador").trim();
      const serverBaseUrl = process.env.SERVER_BASE_URL || process.env.APP_BASE_URL || db.settings?.serverBaseUrl || db.siteConfig?.branding?.siteUrl || db.zapiConfig?.publicOrigin || "https://corpflats.com.br";
      const portalUrl = `${serverBaseUrl.replace(/\/+$/, "")}/servico/${order.token}`;

      const flats = Array.isArray(order.flats) ? order.flats : [];
      const maxSimul = Number(order.maxSimultaneousFlats) || 2;
      const inProgressCount = flats.filter(f => f.status === "in_progress").length;
      const maxPerDay = Number(order.maxFlatsPerDay) || 4;
      const doneTodayCount = flats.filter(
        f => f.status === "done" && f.finishedAt && getExecutionDateStr(f.finishedAt) === todayStr
      ).length;

      const allowedStatuses = getAllowedRoomStatuses(order);
      const cleanFlatMode = order.cleanFlatMode || "priority";

      const hasOtherAllowedDirtyFlat = (currentFlatId) => {
        return flats.some(otherF => {
          if (Number(otherF.flatId) === Number(currentFlatId) || otherF.status === "done") return false;
          if (!isFlatDirty(otherF.flatId, otherF.flatNumber, todayStr)) return false;
          const otherScenario = getFlatOperationalScenario(otherF.flatId, otherF.flatNumber, todayStr);
          return allowedStatuses.includes(otherScenario);
        });
      };

      const newlyAvailableFlats = [];

      for (const flat of flats) {
        if (flat.status !== "pending") continue;

        const realtime = getFlatRealtimeStatus(flat.flatId, flat.flatNumber, todayStr);
        const scenario = getFlatOperationalScenario(flat.flatId, flat.flatNumber, todayStr);
        const filterEval = evaluateServiceFlatFilter(order, flat, scenario, realtime, todayStr);
        const isRoomCriteriaMet = filterEval.allowed;

        if (!isRoomCriteriaMet) {
          if (flat.workerNotifiedAvailable) {
            flat.workerNotifiedAvailable = false;
            updated = true;
          }
          continue;
        }

        // Respeita limites operacionais (simultâneos e diário) antes de disparar o aviso
        if (inProgressCount >= maxSimul || doneTodayCount >= maxPerDay) {
          continue;
        }

        if (!flat.workerNotifiedAvailable) {
          const lastNotifiedMs = flat.workerNotifiedAvailableAt ? new Date(flat.workerNotifiedAvailableAt).getTime() : 0;
          if (!options?.onWorkerRegistered && lastNotifiedMs && (nowMs - lastNotifiedMs) < 5 * 60 * 1000 && flat.workerLastNotifiedPhone === cleanWp) {
            flat.workerNotifiedAvailable = true;
            updated = true;
            continue;
          }

          flat.workerNotifiedAvailable = true;
          flat.workerNotifiedAvailableAt = nowIso;
          flat.workerLastNotifiedPhone = cleanWp;
          updated = true;

          const realtime = getFlatRealtimeStatus(flat.flatId, flat.flatNumber, todayStr);
          const scenarioInfo = OPERATIONAL_SCENARIOS[scenario] || {};
          newlyAvailableFlats.push({
            flat,
            scenario,
            scenarioLabel: scenarioInfo.label || scenario,
            scenarioIcon: scenarioInfo.icon || "🏠",
            hasCheckinToday: realtime.hasCheckinToday,
            expectedArrival: realtime.expectedArrival || (realtime.hasCheckinToday ? "14:00" : null)
          });
        }
      }

      if (newlyAvailableFlats.length > 0) {
        order.lastRegistrationWelcomePhone = cleanWp;
        updated = true;

        const flatLines = newlyAvailableFlats.map(item => {
          const forceBadge = item.flat.forceReleased ? " _(🔓 Liberado pela Administração)_" : "";
          const arrivalNote = item.hasCheckinToday ? ` · Entrada prevista: ${item.expectedArrival || "14:00"}` : "";
          return `• *Flat ${item.flat.flatNumber}* — ${item.scenarioIcon} ${item.scenarioLabel}${forceBadge}${arrivalNote}`;
        });

        const msgText = [
          `🔔 *Quarto(s) Disponível(is) para Serviço* — *${order.title}*`,
          `Olá, *${workerName}*!`,
          newlyAvailableFlats.length === 1
            ? `O seguinte apartamento está liberado para execução do serviço conforme os critérios da ordem:`
            : `Os seguintes apartamentos estão liberados para execução do serviço conforme os critérios da ordem:`,
          ...flatLines,
          ``,
          `🔗 Acesse o portal para solicitar entrada na recepção e iniciar:`,
          portalUrl
        ].join("\n");

        notificationsSent.push({
          orderId: order.id,
          token: order.token,
          workerPhone: cleanWp,
          workerName,
          flats: newlyAvailableFlats.map(i => i.flat.flatNumber),
          message: msgText
        });

        try {
          createNotification({
            category: "service_order",
            title: `🔔 Quarto(s) liberado(s) para o prestador (${newlyAvailableFlats.map(i => `Flat ${i.flat.flatNumber}`).join(", ")})`,
            message: `${order.title}: WhatsApp enviado para ${workerName} (${cleanWp})`,
            severity: "info",
            metadata: {
              serviceOrderId: order.id,
              workerPhone: cleanWp,
              flats: newlyAvailableFlats.map(i => i.flat.flatNumber),
              action: "worker_room_available"
            },
            targetUrl: `/servicos`
          });
        } catch (_) {}

        if (typeof sendZapiMessage === "function") {
          sendZapiMessage(db.zapiConfig, {
            phone: cleanWp,
            message: msgText,
            channelId: "service_providers",
            recipientRole: "service_worker",
            triggerEvent: "service_order_room_available",
            db
          }).then(waRes => {
            if (!db.whatsappHistory) db.whatsappHistory = [];
            db.whatsappHistory.push({
              id: `svc_avail_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
              guestName: workerName,
              guestPhone: cleanWp,
              triggerEvent: "service_order_room_available",
              message: msgText,
              sentAt: new Date().toISOString(),
              status: waRes?.success ? "sent" : "failed",
              method: waRes?.simulated ? "simulated" : "zapi",
              error: waRes?.error || null
            });
          }).catch(err => console.warn(`[ServiceOrder] WhatsApp room available to worker ${cleanWp} failed:`, err.message));
        }
      } else if (options?.onWorkerRegistered && order.lastRegistrationWelcomePhone !== cleanWp) {
        const pendingFlats = flats.filter(f => f.status === "pending");
        if (pendingFlats.length > 0) {
          order.lastRegistrationWelcomePhone = cleanWp;
          updated = true;

          const pendingNumbers = pendingFlats.map(f => `Flat ${f.flatNumber}`).join(", ");
          const welcomeMsg = [
            `🔧 *Ordem de Serviço Vinculada* — *${order.title}*`,
            `Olá, *${workerName}*! Seu cadastro e WhatsApp foram vinculados com sucesso a esta Ordem de Serviço no *CorpFlats*.`,
            ``,
            `📋 *Apartamentos programados (${pendingFlats.length}):* ${pendingNumbers}`,
            `⏳ Assim que um apartamento atingir o critério de liberação para execução, você receberá uma notificação automática aqui no WhatsApp.`,
            ``,
            `🔗 *Link do seu Portal de Serviço:*`,
            portalUrl
          ].join("\n");

          notificationsSent.push({
            orderId: order.id,
            token: order.token,
            workerPhone: cleanWp,
            workerName,
            flats: pendingFlats.map(f => f.flatNumber),
            message: welcomeMsg,
            type: "registration_welcome"
          });

          if (typeof sendZapiMessage === "function") {
            sendZapiMessage(db.zapiConfig, {
              phone: cleanWp,
              message: welcomeMsg,
              channelId: "service_providers",
              recipientRole: "service_worker",
              triggerEvent: "service_order_worker_registered",
              db
            }).then(waRes => {
              if (!db.whatsappHistory) db.whatsappHistory = [];
              db.whatsappHistory.push({
                id: `svc_reg_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
                guestName: workerName,
                guestPhone: cleanWp,
                triggerEvent: "service_order_worker_registered",
                message: welcomeMsg,
                sentAt: new Date().toISOString(),
                status: waRes?.success ? "sent" : "failed",
                method: waRes?.simulated ? "simulated" : "zapi",
                error: waRes?.error || null
              });
            }).catch(err => console.warn(`[ServiceOrder] WhatsApp registration welcome to worker ${cleanWp} failed:`, err.message));
          }
        }
      }
    }

    if (updated) {
      saveDatabase("check_available_service_flats");
    }
    if (typeof checkAndNotifyHandymanAvailableFlats === "function") {
      try {
        const hmNotifs = checkAndNotifyHandymanAvailableFlats();
        if (Array.isArray(hmNotifs) && hmNotifs.length > 0) {
          notificationsSent.push(...hmNotifs);
        }
      } catch (_) {}
    }
    return notificationsSent;
  } catch (err) {
    console.warn("[ServiceOrder] Erro ao verificar disponibilidade de quartos para prestador:", err?.message || err);
    return [];
  }
}

function checkOverdueServiceFlats() {
  try {
    if (pgPool && !pgHydratedSuccessfully) return;
    if (!Array.isArray(db.serviceOrders)) return;
    const now = new Date();
    let updated = false;

    for (const order of db.serviceOrders) {
      if (order.status !== "active") continue;
      for (const flat of (order.flats || [])) {
        if (flat.status === "in_progress" && flat.estimatedFinishAt && !flat.delayNotified) {
          const estDate = new Date(flat.estimatedFinishAt);
          if (!Number.isNaN(estDate.getTime()) && estDate.getTime() < now.getTime()) {
            flat.delayNotified = true;
            updated = true;
            // Trava de sanidade temporal: se a previsão já expirou há mais de 24h, apenas marca delayNotified=true
            // e persiste silenciosamente sem disparar alertas retroativos de dias/semanas anteriores no WhatsApp.
            if (now.getTime() - estDate.getTime() <= 24 * 3600 * 1000) {
              const worker = (db.serviceWorkers || []).find(w => w.token === order.token || w.serviceOrderId === order.id);
              dispatchServiceNotifications("overdue_alert", order, flat, worker);
            }
          }
        }
      }
    }
    if (updated) {
      saveDatabase("check_overdue_service_flats");
    }
    checkAndNotifyAvailableServiceFlats();
  } catch (err) {
    console.warn("[ServiceOrder] Erro ao verificar atrasos de serviço:", err?.message || err);
  }
}

// ── Flats Endpoints ─────────────────────────────────────────────────────────
app.get("/api/flats", (req, res) => {
  res.set("Cache-Control", "no-store, no-cache, must-revalidate");
  if (isUniversalIntegrityDirty && reconcileUniversalIntegrity()) {
    setImmediate(() => saveDatabase("integrity_reconciled"));
  }
  const todayStr = getTodayStr();
  const precomputedRequests = typeof getRequestsForDate === "function" ? getRequestsForDate(todayStr) : (db.cleaningRequests || []);
  const activeFlats = (db.flats || []).filter(f => f.isActive !== false).map(flat => {
    const realtime = getFlatRealtimeStatus(flat.id, flat.number, todayStr, precomputedRequests);
    flat.isOccupied = realtime.isOccupied;
    return {
      ...flat,
      serviceInProgress: getFlatServiceInProgress(flat.id, flat.number),
      isOccupied: realtime.isOccupied,
      isDirty: realtime.isDirty,
      cleaningStatus: realtime.cleaningStatus,
      occupancyStatus: realtime.occupancyStatus,
      currentGuest: realtime.currentGuest,
      hasCheckinToday: realtime.hasCheckinToday,
      hasCheckoutToday: realtime.hasCheckoutToday
    };
  });
  triggerBackgroundSync();
  res.json(activeFlats);
});

app.post("/api/flats", (req, res) => {
  const { number } = req.body;
  if (!number || !String(number).trim()) return res.status(400).json({ error: "Número do flat é obrigatório" });
  const existing = db.flats.find(f => f.number === String(number).trim());
  if (existing) return res.status(409).json({ error: "Apartamento já cadastrado" });

  const newFlat = {
    id: db.flats.length > 0 ? Math.max(...db.flats.map(f => f.id)) + 1 : 1,
    number: String(number).trim(),
    buildingName: (req.body.buildingName || db.settings?.buildingName || "Edifício Soho Residence Service").trim(),
    receptionEmail: (req.body.receptionEmail || "").trim(),
    colIndex: -1,
    colName: `Apt ${number}`,
    isOccupied: false,
    updatedAt: new Date().toISOString(),
  };
  db.flats.push(newFlat);
  saveDatabase();
  res.status(201).json(newFlat);
});

app.put("/api/flats/:id", (req, res) => {
  const id = Number(req.params.id);
  const flat = db.flats.find(f => f.id === id);
  if (!flat) return res.status(404).json({ error: "Flat não encontrado" });
  if (req.body.number) flat.number = String(req.body.number).trim();
  if (req.body.buildingName !== undefined) flat.buildingName = String(req.body.buildingName).trim();
  if (req.body.receptionEmail !== undefined) flat.receptionEmail = String(req.body.receptionEmail).trim();
  if (typeof req.body.isOccupied === "boolean") flat.isOccupied = req.body.isOccupied;
  flat.updatedAt = new Date().toISOString();
  saveDatabase();
  res.json(flat);
});

app.delete("/api/flats/:id", (req, res) => {
  const id = Number(req.params.id);
  db.flats = db.flats.filter(f => f.id !== id);
  saveDatabase();
  res.json({ success: true });
});

app.patch("/api/flats/:id", (req, res) => {
  const f = db.flats.find(x => x.id === Number(req.params.id));
  if (!f) return res.status(404).json({ error: "Flat não encontrado" });
  if (typeof req.body.isOccupied === "boolean") {
    const now = new Date().toISOString();
    f.isOccupied = req.body.isOccupied;
    f.updatedAt = now;

    const todayStr = getTodayStr ? getTodayStr() : now.substring(0, 10);
    const cleanReq = (db.cleaningRequests || []).find(c =>
      (c.flatId === f.id || String(c.flatNumber) === String(f.number)) &&
      (c.requestDate === todayStr || c.effectiveDate === todayStr)
    );
    if (cleanReq) {
      cleanReq.isVacant = !req.body.isOccupied;
      cleanReq.isVacantExplicitlySet = true;
      cleanReq.vacantSource = "manual_card";
      cleanReq.vacantSetAt = now;
      cleanReq.updatedAt = now;
    }

    const authUser = getAuthUser(req);
    const checkoutRes = (db.reservations || []).find(r =>
      r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
      (r.flatId === f.id || String(r.flatNumber) === String(f.number)) &&
      (r.checkoutDate === todayStr || r.earlyCheckoutDate === todayStr)
    );
    if (checkoutRes) {
      if (!req.body.isOccupied) {
        applyReservationCheckoutAndEarlyRelease(db, saveDatabase, checkoutRes, {
          source: "manual_card",
          actorName: authUser?.name || authUser?.username || "Governança / Card",
          nowIso: now,
          todayStr
        }).catch(e => console.warn("[Flat Vacancy Checkout Error]:", e?.message));
        cancelPendingStayRemindersForCheckout(db, null, {
          reservation: checkoutRes,
          flatId: f.id,
          flatNumber: f.number,
          reason: "Cancelado: flat marcado como desocupado"
        });
        triggerCheckoutWhatsApp(db, saveDatabase, checkoutRes, "manual_card").catch(e => {
          console.warn("[Flat Vacancy Checkout Trigger Error]:", e.message);
        });
      } else {
        undoReservationCheckoutAndRestoreStay(db, checkoutRes, {
          actorUser: authUser,
          source: "Governança / Card Ocupado",
          nowIso: now,
          todayStr
        });
      }
      checkoutRes.updatedAt = now;
    } else if (!req.body.isOccupied) {
      cancelPendingStayRemindersForCheckout(db, null, {
        flatId: f.id,
        flatNumber: f.number,
        reason: "Cancelado: flat marcado como desocupado"
      });
    }
  }
  saveDatabase();
  res.json(f);
});

// ── Atualização de Tags, Particularidades e Ficha Técnica do Flat ───────────
app.put("/api/flats/:id/tags", (req, res) => {
  const id = Number(req.params.id);
  const flat = (db.flats || []).find(f => f.id === id);
  if (!flat) return res.status(404).json({ error: "Flat não encontrado" });

  const { tags, airConditionerType, bedType, hasMicrowave, features, notes, technicalSheet } = req.body;

  if (Array.isArray(tags)) flat.tags = tags;
  if (airConditionerType !== undefined) flat.airConditionerType = airConditionerType;
  if (bedType !== undefined) flat.bedType = bedType;
  if (hasMicrowave !== undefined) flat.hasMicrowave = Boolean(hasMicrowave);
  if (Array.isArray(features)) flat.features = features;
  if (notes !== undefined) flat.notes = notes;
  if (technicalSheet && typeof technicalSheet === "object") {
    flat.technicalSheet = {
      ...(flat.technicalSheet || {}),
      ...technicalSheet
    };
  }
  flat.updatedAt = new Date().toISOString();

  saveDatabase();
  console.log(`[Flats] Particularidades e Ficha Técnica do Apt ${flat.number} atualizadas: ${(flat.tags || []).join(", ") || "Sem tags"}`);
  res.json({ success: true, flat });
});

// ── Acknowledge Extended Stay ("Ciente") Endpoint ───────────────────────────
app.post("/api/cleaning/assignments/:requestId/acknowledge-extended", (req, res) => {
  const reqId = Number(req.params.requestId);
  db.cleaningRequests = db.cleaningRequests.filter(r => r.id !== reqId);
  saveDatabase();
  res.json({ success: true, message: "Aviso de extensão dispensado com sucesso." });
});

// ── Mark Flat as Extended Stay (Hóspede Estendeu / Stayover) ───────────────
app.post("/api/cleaning/assignments/:requestId/mark-extended", (req, res) => {
  const reqId = Number(req.params.requestId);
  const { flatNumber, flatId, reservationId, newCheckoutDate, additionalAmount, notes, forceConflict } = req.body || {};
  let item = db.cleaningRequests.find(r => r.id === reqId);
  if (!item && flatNumber) {
    item = db.cleaningRequests.find(r => String(r.flatNumber) === String(flatNumber) && r.status !== "clean");
  }

  const targetFlat = (db.flats || []).find(f => (flatNumber && String(f.number) === String(flatNumber)) || (flatId && f.id === Number(flatId)) || (item && f.id === item.flatId));
  const targetFlatNumber = targetFlat ? targetFlat.number : (flatNumber || (item ? item.flatNumber : ""));
  const targetFlatId = targetFlat ? targetFlat.id : (item ? item.flatId : null);

  if (!item && !targetFlatNumber) {
    return res.status(404).json({ error: "Solicitação de limpeza ou apartamento não encontrado." });
  }

  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) {
    return res.status(403).json({ error: "Apenas administradores podem prorrogar estadia de hóspede." });
  }
  const now = new Date().toISOString();
  const requestDate = item?.requestDate || req.body.requestDate || getTodayStr();

  // 1. Localizar a reserva correspondente no flat
  let targetRes = null;
  if (reservationId) {
    targetRes = (db.reservations || []).find(r => (r.id === Number(reservationId) || r.code === reservationId) && r.status !== "cancelada" && r.status !== "cancelado");
  }
  if (!targetRes && targetFlatNumber) {
    targetRes = (db.reservations || []).find(r =>
      (String(r.flatNumber) === String(targetFlatNumber) || (targetFlatId && r.flatId === targetFlatId)) &&
      r.status !== "cancelada" && r.status !== "cancelado" &&
      r.checkoutDate === requestDate
    );
  }
  if (!targetRes && item?.leavingGuest) {
    const lg = String(item.leavingGuest).toLowerCase().trim();
    targetRes = (db.reservations || []).find(r =>
      (String(r.flatNumber) === String(targetFlatNumber) || (targetFlatId && r.flatId === targetFlatId)) &&
      r.status !== "cancelada" && r.status !== "cancelado" &&
      r.guestName && (r.guestName.toLowerCase().trim() === lg || r.guestName.toLowerCase().includes(lg) || lg.includes(r.guestName.toLowerCase().trim()))
    );
  }
  if (!targetRes && targetFlatNumber) {
    const today = getTodayStr();
    targetRes = (db.reservations || []).find(r =>
      (String(r.flatNumber) === String(targetFlatNumber) || (targetFlatId && r.flatId === targetFlatId)) &&
      r.status !== "cancelada" && r.status !== "cancelado" &&
      r.checkinDate <= today && r.checkoutDate >= today
    );
  }
  if (!targetRes && targetFlatNumber) {
    const notCancelled = (db.reservations || [])
      .filter(r => (String(r.flatNumber) === String(targetFlatNumber) || (targetFlatId && r.flatId === targetFlatId)) && r.status !== "cancelada" && r.status !== "cancelado")
      .sort((a, b) => (b.checkoutDate || "").localeCompare(a.checkoutDate || ""));
    targetRes = notCancelled[0] || null;
  }

  // 2. Se informou nova data de check-out, validar e atualizar a reserva
  const addAmount = Math.max(0, parseFloat(additionalAmount) || 0);

  if (targetRes && newCheckoutDate) {
    if (newCheckoutDate <= targetRes.checkinDate) {
      return res.status(400).json({
        error: `A nova data de check-out (${newCheckoutDate}) deve ser posterior à data de check-in (${targetRes.checkinDate}).`
      });
    }

    const oldCheckout = targetRes.checkoutDate;

    // Verificar se há reservas conflitantes no mesmo flat
    if (newCheckoutDate > oldCheckout) {
      const conflictRes = (db.reservations || []).find(other => {
        if (other.id === targetRes.id || other.status === "cancelada" || other.status === "cancelado") return false;
        const otherFlat = String(other.flatNumber || (db.flats.find(f => f.id === other.flatId)?.number || ""));
        if (otherFlat !== String(targetFlatNumber)) return false;
        return (oldCheckout < other.checkoutDate) && (newCheckoutDate > other.checkinDate);
      });

      if (conflictRes && !forceConflict) {
        return res.status(409).json({
          error: `Conflito de agenda: O Flat ${targetFlatNumber} já possui reserva para ${conflictRes.guestName || 'outro hóspede'} (Check-in: ${conflictRes.checkinDate}, Check-out: ${conflictRes.checkoutDate}).`,
          hasConflict: true,
          conflictingReservation: {
            id: conflictRes.id,
            guestName: conflictRes.guestName,
            checkinDate: conflictRes.checkinDate,
            checkoutDate: conflictRes.checkoutDate
          }
        });
      }
    }

    // Atualiza a reserva
    const oldTotal = Number(targetRes.totalAmount || targetRes.price || 0);
    const newTotal = oldTotal + addAmount;
    targetRes.checkoutDate = newCheckoutDate;
    targetRes.totalAmount = newTotal;

    // Se houve acréscimo financeiro, atualiza status de pagamento
    if (addAmount > 0) {
      const currentPaid = Number(targetRes.paidAmount || 0);
      if (currentPaid < newTotal) {
        targetRes.paymentStatus = currentPaid > 0 ? "pago_parcial" : "pendente";
      }
    }

    // Histórico e anotações
    const extLogText = `Extensão de estadia para ${newCheckoutDate}${addAmount > 0 ? ` (+R$ ${addAmount.toFixed(2)})` : ""}${notes ? ` - Obs: ${notes}` : ""}`;
    targetRes.notes = targetRes.notes
      ? `${targetRes.notes}\n[${now.substring(0, 10)} ${now.substring(11, 16)}] ${extLogText}`
      : `[${now.substring(0, 10)} ${now.substring(11, 16)}] ${extLogText}`;

    // Incrementar sequência do calendário (RFC 5546)
    targetRes.calendarSequence = (targetRes.calendarSequence || 0) + 1;

    // Registrar log de auditoria da reserva
    ensureReservationAuditLogs(targetRes);
    addReservationAuditLog(targetRes, {
      action: "stay_extended",
      actor: userAuth ? { id: userAuth.id, name: userAuth.name || userAuth.username, role: userAuth.role } : { name: "Governança / Limpeza", role: "admin" },
      source: "Painel de Limpeza (Hóspede Estendeu)",
      description: extLogText,
      changes: [
        { field: "checkoutDate", label: "Data de Saída (Check-out)", oldValue: oldCheckout, newValue: newCheckoutDate },
        ...(addAmount > 0 ? [{ field: "totalAmount", label: "Valor Total", oldValue: `R$ ${oldTotal.toFixed(2)}`, newValue: `R$ ${newTotal.toFixed(2)} (+R$ ${addAmount.toFixed(2)})` }] : [])
      ]
    });

    // Sincronizar pedidos de café da manhã (se houver)
    if (db.breakfastOrders && oldCheckout !== newCheckoutDate) {
      db.breakfastOrders.forEach(o => {
        if ((o.reservationCode && (o.reservationCode === targetRes.code || o.reservationCode === targetRes.reservationCode)) || o.reservationId === targetRes.id || (String(o.roomNumber) === String(targetFlatNumber))) {
          if (o.date >= targetRes.checkinDate && o.date <= targetRes.checkoutDate && o.status === "cancelled" && o.cancelReason?.includes("antecipou")) {
            o.status = "pending";
            o.cancelReason = null;
          }
        }
      });
    }

    // Assegurar solicitação de limpeza na nova data de check-out
    if (!db.cleaningRequests) db.cleaningRequests = [];
    const hasFutureCleaning = db.cleaningRequests.some(c =>
      (String(c.flatNumber) === String(targetFlatNumber) || (targetFlatId && c.flatId === targetFlatId)) &&
      c.requestDate === newCheckoutDate
    );
    if (!hasFutureCleaning) {
      const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(x => Number(x.id) || 0)) : 0;
      db.cleaningRequests.unshift({
        id: maxId + 1,
        flatId: targetFlatId || targetRes.flatId,
        flatNumber: targetFlatNumber,
        requestDate: newCheckoutDate,
        source: "checkout",
        status: "dirty",
        assignedUserId: null,
        assignedUsername: null,
        isVacant: false,
        isPriority: false,
        leavingGuest: targetRes.guestName,
        arrivingGuest: null,
        adminNote: null,
        createdAt: now,
        updatedAt: now
      });
    }
  }

  // 3. Atualizar as solicitações de limpeza pendentes da data consultada para status "extended"
  const extendedNote = newCheckoutDate
    ? `Hóspede estendeu até ${newCheckoutDate}${addAmount > 0 ? ` (+R$ ${addAmount.toFixed(2)})` : ""}${notes ? ` - ${notes}` : ""}`
    : (notes || "Hóspede estendeu a estadia");

  let updatedCount = 0;
  if (db.cleaningRequests) {
    for (const r of db.cleaningRequests) {
      if ((String(r.flatNumber) === String(targetFlatNumber) || (targetFlatId && r.flatId === targetFlatId)) && r.status !== "clean" && (!item || r.requestDate === requestDate)) {
        r.status = "extended";
        r.isExtended = true;
        r.isVacant = false;
        r.pendingObservation = extendedNote;
        r.updatedAt = now;
        updatedCount++;
      }
    }
  }

  // Se não havia item em db.cleaningRequests (foi sintetizado no checkouts), cria o registro persistido
  if (updatedCount === 0 && targetFlatNumber) {
    const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) : 0;
    db.cleaningRequests.unshift({
      id: maxId + 1,
      flatId: targetFlatId || (targetRes ? targetRes.flatId : null),
      flatNumber: targetFlatNumber,
      requestDate: requestDate,
      source: "checkout",
      status: "extended",
      isExtended: true,
      isVacant: false,
      leavingGuest: targetRes?.guestName || item?.leavingGuest || null,
      arrivingGuest: item?.arrivingGuest || null,
      pendingObservation: extendedNote,
      createdAt: now,
      updatedAt: now
    });
  }

  saveDatabase();

  logAuditEvent({
    level: "info",
    category: "cleaning",
    action: "STAY_EXTENDED",
    actor: { name: userAuth ? (userAuth.name || userAuth.username) : "Sistema", role: userAuth?.role || "admin" },
    details: {
      flatNumber: targetFlatNumber,
      newCheckoutDate: newCheckoutDate || null,
      additionalAmount: addAmount,
      reservationId: targetRes?.id || null,
      guestName: targetRes?.guestName || null,
      notes: extendedNote
    },
    source: "cleaning_dashboard"
  });

  res.json({
    success: true,
    message: targetRes
      ? `Flat ${targetFlatNumber} estendido até ${newCheckoutDate || 'nova data'} com sucesso. Reserva de ${targetRes.guestName} atualizada (+R$ ${addAmount.toFixed(2)}).`
      : `Flat ${targetFlatNumber} marcado como estadia estendida com sucesso.`,
    reservation: targetRes,
    newCheckoutDate,
    additionalAmount: addAmount
  });
});

// ── Admin Instructions & Room Setup Endpoint (Admin Only) ───────────────────
app.patch("/api/cleaning/requests/:requestId/admin-instructions", (req, res) => {
  const reqId = Number(req.params.requestId);
  const { twinBeds, adminNote, extraMattress, isPaidCleaning, flatId, flatNumber, requestDate } = req.body || {};

  const item = findOrUpsertCleaningRequest(reqId, flatNumber, flatId, requestDate);
  if (!item) return res.status(404).json({ error: "Apartamento ou solicitação de limpeza não encontrada." });

  item.isManualInstruction = true;
  if (typeof twinBeds === "boolean") {
    item.twinBeds = twinBeds;
    item.manualTwinBeds = true;
  }
  if (typeof extraMattress === "boolean") {
    item.extraMattress = extraMattress;
    item.manualExtraMattress = true;
  }
  if (typeof isPaidCleaning === "boolean") {
    item.isPaidCleaning = isPaidCleaning;
  }
  const targetDate = requestDate || item.requestDate || getTodayStr();
  if (adminNote !== undefined) {
    item.adminNote = adminNote ? String(adminNote).trim() : null;
    if (item.status !== "pending_issue") {
      item.pendingObservation = item.adminNote;
    }
    item.manualAdminNote = true;

    // Se a observação veio carregada de um card pendente de dia anterior, sincroniza também nos registros anteriores não limpos do mesmo flat
    for (const priorReq of (db.cleaningRequests || [])) {
      if (
        priorReq.id !== item.id &&
        !priorReq.isDeleted &&
        priorReq.status !== "deleted" &&
        priorReq.status !== "clean" &&
        (Number(priorReq.flatId) === Number(item.flatId) || String(priorReq.flatNumber) === String(item.flatNumber)) &&
        priorReq.requestDate &&
        priorReq.requestDate < targetDate &&
        (priorReq.manualAdminNote || priorReq.isManualInstruction)
      ) {
        priorReq.adminNote = item.adminNote;
        if (priorReq.status !== "pending_issue") {
          priorReq.pendingObservation = item.adminNote;
        }
        priorReq.updatedAt = new Date().toISOString();
      }
    }
  }
  item.updatedAt = new Date().toISOString();

  if (typeof isPaidCleaning === "boolean" && item.assignedUserId) {
    syncMaidCredits(item.assignedUserId);
  }
  if (typeof invalidateRequestsForDateCache === "function") {
    invalidateRequestsForDateCache();
  }

  // Sincroniza apenas camas/colchão na reserva correspondente (NUNCA sobrescreve specialRequests/notes da reserva com observação descartável do card)
  const relatedRes = (db.reservations || []).find(r =>
    (Number(r.flatId) === Number(item.flatId) || String(r.flatNumber) === String(item.flatNumber)) &&
    r.status !== "cancelada" && r.status !== "cancelado" &&
    (r.checkinDate === targetDate || (r.checkinDate <= targetDate && r.checkoutDate >= targetDate))
  );
  if (relatedRes && (typeof twinBeds === "boolean" || typeof extraMattress === "boolean")) {
    if (typeof twinBeds === "boolean") {
      relatedRes.twinBeds = twinBeds;
      if (!twinBeds && (relatedRes.bedType === "2 Solteiro" || relatedRes.bedType === "twin")) {
        relatedRes.bedType = "1 Casal";
      } else if (twinBeds && (!relatedRes.bedType || relatedRes.bedType === "1 Casal")) {
        relatedRes.bedType = "2 Solteiro";
      }
    }
    if (typeof extraMattress === "boolean") {
      relatedRes.extraMattress = extraMattress;
    }
    relatedRes.updatedAt = new Date().toISOString();
  }

  saveDatabase();

  res.json({ success: true, request: item });
});

// ── Cleaners List Endpoint ──────────────────────────────────────────────────
app.get("/api/cleaners", (req, res) => {
  sanitizeMaidUsers();
  const cleaners = (db.users || [])
    .filter(u => u.role === "camareira" || u.role === "cleaner" || u.role === "admin" || u.role === "dev")
    .map(u => ({
      id: u.id,
      username: u.username,
      name: u.name || u.username,
      role: u.role === "camareira" || u.role === "cleaner" ? "camareira" : u.role,
      whatsapp: u.whatsapp || u.phone || "",
      phone: u.phone || u.whatsapp || "",
      pixKey: u.pixKey || "",
      active: u.active !== false
    }));
  res.json(cleaners);
});

// ── Manual Cleaning Request ─────────────────────────────────────────────────
app.post("/api/cleaning/requests/manual", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) {
    return res.status(403).json({ error: "Apenas administradores podem lançar solicitações manuais de limpeza." });
  }
  const {
    flatId,
    requestDate = getTodayStr(),
    isPriority = false,
    markAsClean = false,
    assignedUserId = null,
    observation = null,
    twinBeds = false,
    adminNote = null,
    requestType = "cleaning", // "cleaning" | "instruction"
    instructionText = null,
    isPaidCleaning = null, // for instruction: default false, for cleaning: default true
    isBedAdjustmentOnly = false
  } = req.body;

  const flat = db.flats.find(f => f.id === Number(flatId) || String(f.number) === String(flatId));
  if (!flat) return res.status(404).json({ error: "Apartamento não encontrado" });

  const isInstruction = requestType === "instruction" || isBedAdjustmentOnly;
  const isPaid = typeof isPaidCleaning === "boolean" ? isPaidCleaning : (isInstruction ? false : true);
  const resolvedTwinBeds = Boolean(twinBeds || (isInstruction && isBedAdjustmentOnly));
  const noteText = (instructionText || adminNote || observation || "").trim() || (resolvedTwinBeds ? "Separar as camas, colocar como 2 solteiras" : null);

  const assignedUser = assignedUserId ? db.users.find(u => u.id === Number(assignedUserId)) : null;
  const nowIso = new Date().toISOString();
  const completedDateIso = requestDate ? new Date(`${requestDate}T12:00:00.000Z`).toISOString() : nowIso;

  let existing = db.cleaningRequests.find(r => {
    const isSameFlat = (r.flatId === flat.id || String(r.flatNumber) === String(flat.number));
    if (!isSameFlat || r.requestDate !== requestDate) return false;
    const rIsInst = Boolean(r.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only");
    return isInstruction ? rIsInst : !rIsInst;
  });

  if (existing) {
    existing.isDeleted = false;
    delete existing.deletedAt;
    delete existing.deletedBy;
    delete existing.deletedReservationId;
    existing.source = isInstruction ? "manual_instruction" : "manual";
    existing.type = isInstruction ? (resolvedTwinBeds ? "bed_adjustment_only" : "instruction") : "cleaning";
    existing.isInstructionOnly = isInstruction;
    existing.isBedAdjustmentOnly = isInstruction && resolvedTwinBeds;
    existing.isPaidCleaning = isPaid;
    existing.instructionText = isInstruction ? noteText : null;
    existing.isExtended = false;
    existing.isPriority = markAsClean
      ? false
      : (typeof isPriority === "boolean" ? isPriority : (existing.status === "clean" ? false : Boolean(existing.isPriority)));
    if (markAsClean || !existing.isPriority) delete existing.priorityReason;
    if (markAsClean) {
      for (const r of (db.reservations || [])) {
        if (
          (Number(r.flatId) === Number(flat.id) || String(r.flatNumber) === String(flat.number)) &&
          (r.checkoutDate === requestDate || r.checkinDate === requestDate || (r.checkinDate <= requestDate && r.checkoutDate >= requestDate)) &&
          r.isPriority
        ) {
          r.isPriority = false;
          delete r.priorityReason;
        }
      }
    }
    existing.status = markAsClean ? "clean" : "dirty";
    existing.isVacant = markAsClean ? true : !flat.isOccupied;
    existing.twinBeds = resolvedTwinBeds;
    existing.manualTwinBeds = true;
    existing.manualExtraMattress = true;
    existing.manualAdminNote = Boolean(noteText);
    existing.isManualInstruction = Boolean(noteText || resolvedTwinBeds || isInstruction);
    existing.adminNote = noteText || null;
    existing.pendingObservation = noteText || null;
    existing.notes = noteText || null;
    if (assignedUser) {
      existing.assignedUserId = assignedUser.id;
      existing.assignedUsername = assignedUser.username;
      existing.assignedUserName = assignedUser.name || assignedUser.username;
    } else if (!markAsClean && !assignedUserId) {
      existing.assignedUserId = null;
      existing.assignedUsername = null;
      existing.assignedUserName = null;
    }
    existing.willCleanAt = markAsClean ? completedDateIso : null;
    existing.cleaningStartedAt = markAsClean ? completedDateIso : null;
    existing.completedAt = markAsClean ? completedDateIso : null;
    existing.updatedAt = nowIso;
    saveDatabase();
    return res.json(existing);
  }

  if (markAsClean) {
    for (const r of (db.reservations || [])) {
      if (
        (Number(r.flatId) === Number(flat.id) || String(r.flatNumber) === String(flat.number)) &&
        (r.checkoutDate === requestDate || r.checkinDate === requestDate || (r.checkinDate <= requestDate && r.checkoutDate >= requestDate)) &&
        r.isPriority
      ) {
        r.isPriority = false;
        delete r.priorityReason;
      }
    }
  }

  const newReq = {
    id: db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) + 1 : 1,
    flatId: flat.id,
    flatNumber: flat.number,
    requestDate,
    source: isInstruction ? "manual_instruction" : "manual",
    type: isInstruction ? (resolvedTwinBeds ? "bed_adjustment_only" : "instruction") : "cleaning",
    isInstructionOnly: isInstruction,
    isBedAdjustmentOnly: isInstruction && resolvedTwinBeds,
    isPaidCleaning: isPaid,
    instructionText: isInstruction ? noteText : null,
    status: markAsClean ? "clean" : "dirty",
    assignedUserId: assignedUser ? assignedUser.id : null,
    assignedUsername: assignedUser ? assignedUser.username : null,
    assignedUserName: assignedUser ? (assignedUser.name || assignedUser.username) : null,
    isVacant: markAsClean ? true : !flat.isOccupied,
    isPriority: markAsClean ? false : Boolean(isPriority),
    isExtended: false,
    twinBeds: resolvedTwinBeds,
    manualTwinBeds: true,
    manualExtraMattress: true,
    manualAdminNote: true,
    isManualInstruction: true,
    adminNote: noteText,
    notes: noteText,
    leavingGuest: null,
    arrivingGuest: null,
    pendingObservation: noteText,
    willCleanAt: markAsClean ? completedDateIso : null,
    cleaningStartedAt: markAsClean ? completedDateIso : null,
    completedAt: markAsClean ? completedDateIso : null,
    createdAt: nowIso,
    updatedAt: nowIso
  };

  db.cleaningRequests.unshift(newReq);
  saveDatabase();
  return res.status(201).json(newReq);
});

// ── B2B Housekeeping & Linen Tracking Helpers ───────────────────────────────
function isB2bReservation(r) {
  if (!r) return false;
  const chanLower = String(r.channel || "").toLowerCase().trim();

  // Guarda estrita de canais não-B2B:
  // Se o canal for expressamente OTA ou canal direto convencional (Booking, Airbnb, WhatsApp, Site, Balcão, Direto),
  // rejeita categoricamente, mesmo que haja companyName ou agencyName preenchidos para nota fiscal corporativa.
  // Exceção estrita: se houver flag explícita isB2b === true ou o canal contiver "b2b".
  const isExplicitNonB2b =
    chanLower === "booking" || chanLower.includes("booking") ||
    chanLower === "airbnb" || chanLower.includes("airbnb") ||
    chanLower === "whatsapp" || chanLower.includes("whatsapp") ||
    chanLower === "site" || chanLower.includes("site") ||
    chanLower === "balcao" || chanLower === "direto" || chanLower === "direct";

  if (isExplicitNonB2b && r.isB2b !== true && chanLower !== "b2b" && !chanLower.includes("b2b")) {
    return false;
  }

  return Boolean(
    chanLower === "b2b" ||
    chanLower.includes("b2b") ||
    r.isB2b === true ||
    r.b2bReservationNumber ||
    r.b2bLocatorRloc ||
    String(r.code || "").startsWith("B2B-") ||
    r.agencyId ||
    r.agencyName ||
    r.agencyTradeName ||
    r.companyName
  );
}
const isB2BReservation = isB2bReservation;

function computeLinenTracking(reservation, dateStr, db) {
  if (!reservation || !reservation.checkinDate || !reservation.checkoutDate) {
    return null;
  }

  const checkinDate = reservation.checkinDate.substring(0, 10);
  const checkoutDate = reservation.checkoutDate.substring(0, 10);
  const targetDate = (dateStr || (typeof getTodayStr === "function" ? getTodayStr() : new Date().toISOString().substring(0, 10))).substring(0, 10);

  const msPerDay = 86400000;
  const checkinMs = new Date(`${checkinDate}T12:00:00Z`).getTime();
  const checkoutMs = new Date(`${checkoutDate}T12:00:00Z`).getTime();
  const currentMs = new Date(`${targetDate}T12:00:00Z`).getTime();

  const totalStayNights = Math.max(1, Math.round((checkoutMs - checkinMs) / msPerDay));
  const daysFromCheckin = Math.round((currentMs - checkinMs) / msPerDay);
  const stayDayNumber = Math.min(totalStayNights, Math.max(1, daysFromCheckin + 1));

  // Histórico de trocas
  const pastCleanings = (db?.cleaningRequests || []).filter(c =>
    (c.flatId === reservation.flatId || String(c.flatNumber) === String(reservation.flatNumber)) &&
    (c.status === "clean" || Boolean(c.completedAt)) &&
    c.requestDate >= checkinDate &&
    c.requestDate <= targetDate
  );

  // Última troca de cama
  const beddingCleanings = pastCleanings.filter(c => c.beddingChanged);
  beddingCleanings.sort((a, b) => (b.requestDate || "").localeCompare(a.requestDate || ""));

  const resBeddingChanges = (reservation.linenChangeHistory || reservation.linenChanges || [])
    .filter(h => h.beddingChanged && h.date <= targetDate);
  resBeddingChanges.sort((a, b) => (b.date || "").localeCompare(a.date || ""));

  let lastBeddingChangeDate = reservation.lastBeddingChangeDate || null;
  if (beddingCleanings[0]?.requestDate) {
    if (!lastBeddingChangeDate || beddingCleanings[0].requestDate > lastBeddingChangeDate) {
      lastBeddingChangeDate = beddingCleanings[0].requestDate;
    }
  }
  if (resBeddingChanges[0]?.date) {
    if (!lastBeddingChangeDate || resBeddingChanges[0].date > lastBeddingChangeDate) {
      lastBeddingChangeDate = resBeddingChanges[0].date;
    }
  }
  if (!lastBeddingChangeDate || lastBeddingChangeDate < checkinDate) {
    lastBeddingChangeDate = checkinDate;
  }

  const lastBeddingMs = new Date(`${lastBeddingChangeDate}T12:00:00Z`).getTime();
  const daysSinceBeddingChange = Math.max(0, Math.round((currentMs - lastBeddingMs) / msPerDay));
  const needsBeddingChangeAlert = daysSinceBeddingChange >= 3;

  // Última troca de toalhas
  const towelCleanings = pastCleanings.filter(c => c.towelsChanged);
  towelCleanings.sort((a, b) => (b.requestDate || "").localeCompare(a.requestDate || ""));

  const resTowelChanges = (reservation.linenChangeHistory || reservation.linenChanges || [])
    .filter(h => h.towelsChanged && h.date <= targetDate);
  resTowelChanges.sort((a, b) => (b.date || "").localeCompare(a.date || ""));

  let lastTowelsChangeDate = reservation.lastTowelsChangeDate || null;
  if (towelCleanings[0]?.requestDate) {
    if (!lastTowelsChangeDate || towelCleanings[0].requestDate > lastTowelsChangeDate) {
      lastTowelsChangeDate = towelCleanings[0].requestDate;
    }
  }
  if (resTowelChanges[0]?.date) {
    if (!lastTowelsChangeDate || resTowelChanges[0].date > lastTowelsChangeDate) {
      lastTowelsChangeDate = resTowelChanges[0].date;
    }
  }
  if (!lastTowelsChangeDate || lastTowelsChangeDate < checkinDate) {
    lastTowelsChangeDate = checkinDate;
  }

  const lastTowelsMs = new Date(`${lastTowelsChangeDate}T12:00:00Z`).getTime();
  const daysSinceTowelsChange = Math.max(0, Math.round((currentMs - lastTowelsMs) / msPerDay));

  // Solicitações ativas do hóspede pelo portal B2B para a data consultada
  const activeLinenRequest = (reservation.linenRequests || []).find(lr =>
    lr.targetDate === targetDate && lr.status !== "cancelled"
  );
  const guestRequestedBedding = Boolean(activeLinenRequest && (activeLinenRequest.type === "bedding" || activeLinenRequest.type === "both"));
  const guestRequestedTowels = Boolean(activeLinenRequest && (activeLinenRequest.type === "towels" || activeLinenRequest.type === "both"));

  const doNotDisturb = Boolean(reservation.doNotDisturb);

  return {
    stayDayNumber,
    totalStayNights,
    lastBeddingChangeDate,
    daysSinceBeddingChange,
    needsBeddingChangeAlert,
    lastTowelsChangeDate,
    daysSinceTowelsChange,
    guestRequestedBedding,
    guestRequestedTowels,
    doNotDisturb
  };
}

export function invalidateRequestsForDateCache() {
  requestsForDateVersion++;
  requestsForDateCache.clear();
}

function getRequestsForDate(dateStr, isNested = false) {
  const now = Date.now();
  if (!isNested && requestsForDateCache.has(dateStr)) {
    const cached = requestsForDateCache.get(dateStr);
    if (cached && cached.version === requestsForDateVersion && (now - cached.timestamp < 3000)) {
      return cached.data;
    }
  }

  const sanitizeCardNote = (note) => {
    if (!note || typeof note !== "string") return null;
    let cleaned = note
      .replace(/(?:•\s*)?Check-out\s+confirmado[^\n•]*/gi, "")
      .replace(/(?:•\s*)?Check-out\s+expresso[^\n•]*/gi, "")
      .replace(/(?:•\s*)?Confirmado\s+na\s+Portaria[^\n•]*/gi, "")
      .replace(/(?:•\s*)?Limpeza\s+de\s+check-out\s+gerada\s+automaticamente[^\n•]*/gi, "")
      .replace(/(?:•\s*)?Quarto\s+desocupado[^\n•]*/gi, "")
      .trim();
    cleaned = cleaned.replace(/^[•\s\-,|]+|[•\s\-,|]+$/g, "").trim();
    return cleaned.length > 0 ? cleaned : null;
  };

  // Busca observação manual de card anterior do mesmo flat que ficou pendente (não limpo) até ser concluído
  const findUncleanedPriorManualNote = (fNumber, fId, targetDate) => {
    if (typeof getTodayStr === "function" && targetDate < getTodayStr()) return null;
    const candidates = (db.cleaningRequests || []).filter(r => {
      if (!r || r.isDeleted || r.status === "deleted") return false;
      const isSameFlat = (String(r.flatNumber) === String(fNumber)) || (fId && Number(r.flatId) === Number(fId));
      if (!isSameFlat) return false;
      const isInst = Boolean(r.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.isBedAdjustmentOnly);
      if (isInst) return false;
      if (!r.requestDate || r.requestDate < "2026-09-01" || r.requestDate >= targetDate) return false;
      if (r.status === "clean" || r.status === "extended" || r.status === "no_show") return false;
      if (!r.manualAdminNote) return false;
      const cleanNote = sanitizeCardNote(r.adminNote);
      if (!cleanNote) return false;
      const alreadyResolvedAfter = (db.cleaningRequests || []).some(c =>
        ((String(c.flatNumber) === String(fNumber)) || (fId && Number(c.flatId) === Number(fId))) &&
        !c.isInstructionOnly &&
        c.source !== "manual_instruction" &&
        c.type !== "instruction" &&
        c.type !== "bed_adjustment_only" &&
        (c.effectiveDate || (c.completedAt ? c.completedAt.substring(0, 10) : c.requestDate)) >= r.requestDate &&
        (c.effectiveDate || (c.completedAt ? c.completedAt.substring(0, 10) : c.requestDate)) <= targetDate &&
        c.status === "clean"
      );
      return !alreadyResolvedAfter;
    });
    if (candidates.length === 0) return null;
    candidates.sort((a, b) => String(b.requestDate).localeCompare(String(a.requestDate)));
    return sanitizeCardNote(candidates[0].adminNote);
  };

  // Se a consulta for para uma data futura (ex: amanhã), garante que as solicitações de hoje já estão geradas e sincronizadas
  if (!isNested && typeof getTodayStr === "function" && dateStr > getTodayStr()) {
    getRequestsForDate(getTodayStr(), true);
  }

  // Garante que cleaningRequests existe e não possui registros nulos, de flats inexistentes ou órfãos de testes antigos
  const validFlatIdsForReq = new Set((db.flats || []).map(f => Number(f.id)).filter(Boolean));
  const validFlatNumbersForReq = new Set((db.flats || []).map(f => String(f.number)).filter(Boolean));
  const hasRegisteredFlatsForReq = validFlatNumbersForReq.size > 0;
  const beforeCleanFilterCount = (db.cleaningRequests || []).length;
  db.cleaningRequests = (db.cleaningRequests || []).filter(r => {
    if (!r || (!r.flatId && !r.flatNumber) || String(r.flatNumber) === "502" || r.flatId === 9) return false;
    if (r.source === "service_order" && (!r.serviceOrderId || String(r.requestDate || "") <= "2026-10-15")) return false;
    if (hasRegisteredFlatsForReq) {
      const matchesFlat = (r.flatNumber && validFlatNumbersForReq.has(String(r.flatNumber))) || (r.flatId && validFlatIdsForReq.has(Number(r.flatId)));
      if (!matchesFlat) return false;
    }
    return true;
  });
  const requestsForDate = [];
  const existingFlatNumbersForDate = new Set();
  let shouldSaveDb = db.cleaningRequests.length !== beforeCleanFilterCount;

  // 1. Identifica flats que estão com hóspede contínuo (STAYOVER) na data consultada
  // Se o hóspede entrou ANTES de dateStr (checkinDate < dateStr) e só sai DEPOIS de dateStr (checkoutDate > dateStr),
  // o flat é um stayover. Hóspedes entrando hoje (checkinDate === dateStr) são novos check-ins / turnovers, não stayover!
  // Reservas concluídas (checkoutDone === true, status: completed/checked_out, earlyCheckout) não são stayover ativo.
  const stayoverFlatNumbers = new Set(
    (db.reservations || [])
      .filter(r =>
        r.status !== "cancelada" &&
        r.status !== "cancelado" &&
        r.status !== "cancelled" &&
        r.status !== "expirada" &&
        r.status !== "pre_reserva" &&
        r.status !== "pendente" &&
        r.status !== "no_show" &&
        r.status !== "completed" &&
        r.status !== "checked_out" &&
        !r.checkoutDone &&
        !r.earlyCheckout &&
        r.checkinDate < dateStr &&
        r.checkoutDate > dateStr
      )
      .map(r => String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || "")))
  );

  // 1.2. Identifica e gera cards de limpeza diária (STAYOVER) exclusivos para reservas B2B em dias intermediários
  // Reservas de Booking, Airbnb, WhatsApp, Site Direto NUNCA geram card de stayover nas datas intermediárias.
  // Reservas que já fizeram checkout antecipado (completed, checked_out, checkoutDone) NUNCA geram card de stayover.
  const b2bStayoversForDate = (db.reservations || []).filter(r =>
    r.status !== "cancelada" &&
    r.status !== "cancelado" &&
    r.status !== "cancelled" &&
    r.status !== "expirada" &&
    r.status !== "pre_reserva" &&
    r.status !== "pendente" &&
    r.status !== "no_show" &&
    r.status !== "completed" &&
    r.status !== "checked_out" &&
    !r.checkoutDone &&
    !r.earlyCheckout &&
    r.checkinDate &&
    r.checkoutDate &&
    r.checkinDate < dateStr &&
    r.checkoutDate > dateStr &&
    isB2bReservation(r)
  );

  for (const b2bRes of b2bStayoversForDate) {
    const fNumber = String(b2bRes.flatNumber || (db.flats.find(f => f.id === b2bRes.flatId)?.number || ""));
    if (!fNumber) continue;
    const flat = db.flats.find(f => String(f.number) === fNumber) || { id: b2bRes.flatId, number: fNumber, isOccupied: true };

    const deletedStayover = (db.cleaningRequests || []).find(c =>
      (String(c.flatNumber) === fNumber || c.flatId === flat.id) &&
      c.requestDate === dateStr &&
      (c.source === "stayover" || c.cleaningType === "stayover") &&
      (c.isDeleted || c.status === "deleted")
    );

    const existingStayover = (db.cleaningRequests || []).find(c =>
      (String(c.flatNumber) === fNumber || c.flatId === flat.id) &&
      c.requestDate === dateStr &&
      (c.source === "stayover" || c.cleaningType === "stayover") &&
      !c.isDeleted && c.status !== "deleted"
    );

    if (deletedStayover && !existingStayover) {
      continue;
    }

    let card;
    if (existingStayover) {
      card = existingStayover;
      card.source = "stayover";
      card.cleaningType = "stayover";
      card.reservationId = b2bRes.id;
      card.autoReservationId = b2bRes.id;
      card.autoReservationCode = b2bRes.code || null;
      card.currentGuest = b2bRes.guestName || b2bRes.title || "Hóspede";
      card.guestName = b2bRes.guestName || b2bRes.title || "Hóspede";
      card.doNotDisturb = Boolean(b2bRes.doNotDisturb);
      card.isVacant = false;
      if (card.status === "clean" && (card.isPriority || card.priorityReason)) {
        card.isPriority = false;
        delete card.priorityReason;
        shouldSaveDb = true;
      }
    } else {
      const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) : 0;
      card = {
        id: maxId + 1,
        flatId: flat.id,
        flatNumber: flat.number,
        requestDate: dateStr,
        source: "stayover",
        cleaningType: "stayover",
        status: "dirty",
        assignedUserId: null,
        assignedUsername: null,
        assignedUserName: null,
        isVacant: false,
        isVacantExplicitlySet: false,
        vacantSource: null,
        isPriority: Boolean(b2bRes.isPriority),
        isExtended: false,
        twinBeds: Boolean(b2bRes.twinBeds || b2bRes.bedType === "2 Solteiro" || b2bRes.bedType === "twin"),
        extraMattress: Boolean(b2bRes.extraMattress),
        reservationId: b2bRes.id,
        autoReservationCode: b2bRes.code || null,
        autoReservationId: b2bRes.id || null,
        adminNote: null,
        leavingGuest: null,
        currentGuest: b2bRes.guestName || b2bRes.title || "Hóspede",
        guestName: b2bRes.guestName || b2bRes.title || "Hóspede",
        arrivingGuest: null,
        pendingObservation: null,
        doNotDisturb: Boolean(b2bRes.doNotDisturb),
        towelsChanged: false,
        beddingChanged: false,
        smokedInRoom: false,
        guestSmoked: false,
        willCleanAt: null,
        cleaningStartedAt: null,
        completedAt: null,
        durationMinutes: null,
        createdAt: `${dateStr}T08:00:00.000Z`,
        updatedAt: `${dateStr}T08:00:00.000Z`
      };
      db.cleaningRequests.push(card);
      shouldSaveDb = true;
    }

    if (!card.manualAdminNote && !card.adminNote && card.status !== "clean") {
      const carriedStayoverNote = findUncleanedPriorManualNote(fNumber, flat.id, dateStr);
      if (carriedStayoverNote) {
        card.adminNote = carriedStayoverNote;
        card.pendingObservation = carriedStayoverNote;
        card.manualAdminNote = true;
        shouldSaveDb = true;
      }
    }

    requestsForDate.push(card);
    existingFlatNumbersForDate.add(fNumber);
  }

  // 1.5. Garante que checkouts de reservas ativas recentes (últimos 7 dias até dateStr) possuam registro de limpeza
  // Isso protege contra reinicializações do servidor ou avanços de dia sem que o checkout fosse registrado em db.cleaningRequests
  const minRecentCheckoutDate = typeof getOffsetDateStr === "function" ? getOffsetDateStr(-7) : "2026-09-01";
  const recentPmsCheckouts = (db.reservations || []).filter(r =>
    r.status !== "cancelada" &&
    r.status !== "cancelado" &&
    r.status !== "cancelled" &&
    r.status !== "expirada" &&
    r.status !== "pre_reserva" &&
    r.status !== "pendente" &&
    r.status !== "no_show" &&
    r.checkoutDate &&
    r.checkoutDate >= minRecentCheckoutDate &&
    r.checkoutDate <= dateStr
  );

  for (const pmsRes of recentPmsCheckouts) {
    const fNumber = String(pmsRes.flatNumber || (db.flats.find(f => f.id === pmsRes.flatId)?.number || ""));
    if (!fNumber) continue;
    if (stayoverFlatNumbers.has(fNumber)) continue;

    const resDate = pmsRes.checkoutDate;
    const flat = db.flats.find(f => String(f.number) === fNumber) || { id: pmsRes.flatId, number: fNumber, isOccupied: true };

    const matchingCleanings = (db.cleaningRequests || []).filter(c =>
      (String(c.flatNumber) === fNumber || c.flatId === flat.id) &&
      c.requestDate === resDate
    );

    if (matchingCleanings.length === 0) {
      const alreadyCleanedAfter = (db.cleaningRequests || []).some(c =>
        (String(c.flatNumber) === fNumber || c.flatId === flat.id) &&
        !c.isInstructionOnly &&
        c.source !== "manual_instruction" &&
        c.type !== "instruction" &&
        c.type !== "bed_adjustment_only" &&
        (c.effectiveDate || (c.completedAt ? c.completedAt.substring(0, 10) : c.requestDate)) >= resDate &&
        c.status === "clean"
      );

      if (!alreadyCleanedAfter) {
        const arrivingRes = (db.reservations || []).find(r =>
          r.status !== "cancelada" &&
          r.status !== "cancelado" &&
          r.status !== "cancelled" &&
          r.status !== "expirada" &&
          r.status !== "pre_reserva" &&
          r.status !== "pendente" &&
          r.status !== "no_show" &&
          String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || "")) === fNumber &&
          r.checkinDate === resDate
        );

        const nextResHasTwin = Boolean(arrivingRes && (arrivingRes.twinBeds || arrivingRes.bedType === "2 Solteiro" || arrivingRes.bedType === "twin"));
        const nextResHasExtraMattress = Boolean(arrivingRes && arrivingRes.extraMattress);
        let arrivingNote = arrivingRes ? ((arrivingRes.specialRequests || "").trim() || (arrivingRes.notes || "").trim() || null) : null;
        if (arrivingNote && (arrivingNote.includes("Limpeza de check-out gerada automaticamente") || arrivingNote.toLowerCase() === "teste")) arrivingNote = null;
        if (!arrivingNote && (nextResHasTwin || nextResHasExtraMattress)) {
          const parts = [];
          if (nextResHasTwin) parts.push("Separar as camas, colocar como 2 solteiras");
          if (nextResHasExtraMattress) parts.push("Colocar 1 colchão extra");
          arrivingNote = parts.join(" • ");
        }

        const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) : 0;
        const card = {
          id: maxId + 1,
          flatId: flat.id,
          flatNumber: flat.number,
          requestDate: resDate,
          source: "checkout",
          status: "dirty",
          assignedUserId: null,
          assignedUsername: null,
          assignedUserName: null,
          isVacant: false,
          isPriority: Boolean(pmsRes.isPriority),
          isExtended: false,
          twinBeds: nextResHasTwin,
          extraMattress: nextResHasExtraMattress,
          checkoutReservationId: pmsRes.id || null,
          checkoutReservationCode: pmsRes.code || null,
          autoReservationCode: arrivingRes ? arrivingRes.code : null,
          autoReservationId: arrivingRes ? arrivingRes.id : null,
          adminNote: arrivingNote,
          leavingGuest: pmsRes.guestName || pmsRes.title || "Hóspede",
          arrivingGuest: arrivingRes ? (arrivingRes.guestName || arrivingRes.title) : null,
          pendingObservation: arrivingNote,
          smokedInRoom: false,
          guestSmoked: false,
          willCleanAt: null,
          cleaningStartedAt: null,
          completedAt: null,
          durationMinutes: null,
          createdAt: `${resDate}T08:00:00.000Z`,
          updatedAt: `${resDate}T08:00:00.000Z`
        };

        db.cleaningRequests.push(card);
        shouldSaveDb = true;
      }
    }
  }

  // 2. Busca todas as reservas ativas que possuem CHECKOUT na data consultada (checkoutDate === dateStr)
  const pmsCheckouts = (db.reservations || []).filter(r =>
    r.status !== "cancelada" &&
    r.status !== "cancelado" &&
    r.status !== "cancelled" &&
    r.status !== "expirada" &&
    r.status !== "pre_reserva" &&
    r.status !== "pendente" &&
    r.status !== "no_show" &&
    r.checkoutDate === dateStr
  );

  // Se houver reservas para o mesmo flat, mantém a mais recente
  const pmsCheckoutsByFlat = new Map();
  for (const res of pmsCheckouts) {
    const fNumber = String(res.flatNumber || (db.flats.find(f => f.id === res.flatId)?.number || ""));
    if (!fNumber) continue;
    pmsCheckoutsByFlat.set(fNumber, res);
  }

  // 3. Monta os cards de limpeza dinâmicos a partir dos checkouts do PMS
  for (const [flatNumber, pmsRes] of pmsCheckoutsByFlat.entries()) {
    const flat = db.flats.find(f => String(f.number) === flatNumber) || { id: pmsRes.flatId, number: flatNumber, isOccupied: true };

    const arrivingRes = (db.reservations || []).find(r =>
      r.status !== "cancelada" &&
      r.status !== "cancelado" &&
      r.status !== "cancelled" &&
      r.status !== "expirada" &&
      r.status !== "pre_reserva" &&
      r.status !== "pendente" &&
      r.status !== "no_show" &&
      String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || "")) === flatNumber &&
      r.checkinDate === dateStr
    );

    const flatNumClean = flatNumber.replace(/\D/g, "");
    // Prioriza o cleaningRequest específico da data consultada (checkout atual)
    const exactDateCleanings = (db.cleaningRequests || []).filter(c =>
      (String(c.flatNumber).replace(/\D/g, "") === flatNumClean || c.flatId === flat.id) &&
      c.requestDate === dateStr &&
      !c.isInstructionOnly &&
      c.source !== "manual_instruction" &&
      c.type !== "bed_adjustment_only" &&
      c.type !== "instruction"
    );

    const activeExactCleanings = exactDateCleanings.filter(c => !c.isDeleted && c.status !== "deleted");
    const deletedExactCleaning = exactDateCleanings.find(c => c.isDeleted || c.status === "deleted");
    if (deletedExactCleaning && activeExactCleanings.length === 0) {
      const isAutoDeletedOtherRes = Boolean(
        deletedExactCleaning.deletedBy === "pre_reservation_expired" ||
        deletedExactCleaning.deletedBy === "reservation_cancelled" ||
        deletedExactCleaning.deletedBy === "auto_orphan_checkout_cleanup" ||
        (deletedExactCleaning.deletedReservationId && Number(pmsRes.id) !== Number(deletedExactCleaning.deletedReservationId))
      );
      const isNewResAfterDelete = Boolean(
        isAutoDeletedOtherRes ||
        (
          pmsRes.createdAt &&
          deletedExactCleaning.deletedAt &&
          pmsRes.createdAt > deletedExactCleaning.deletedAt &&
          (!deletedExactCleaning.deletedReservationId || Number(pmsRes.id) !== Number(deletedExactCleaning.deletedReservationId))
        )
      );
      if (!isNewResAfterDelete) {
        existingFlatNumbersForDate.add(flatNumber);
        continue;
      }
      deletedExactCleaning.isDeleted = false;
      deletedExactCleaning.status = "dirty";
      delete deletedExactCleaning.deletedAt;
      delete deletedExactCleaning.deletedBy;
      delete deletedExactCleaning.deletedReservationId;
      shouldSaveDb = true;
    }

    const revertedExactCleaning = activeExactCleanings.find(c => c.status === "dirty" && c.revertedToDirtyAt);
    const cleanExactCleaning = activeExactCleanings.find(c =>
      c.status === "clean" &&
      (!revertedExactCleaning || String(c.completedAt || "") > String(revertedExactCleaning.revertedToDirtyAt))
    );
    let existingCleaning = revertedExactCleaning ||
      activeExactCleanings.find(c => c.leavingGuest && pmsRes.guestName && c.leavingGuest.toLowerCase().includes(pmsRes.guestName.toLowerCase())) ||
      cleanExactCleaning ||
      activeExactCleanings.find(c => c.status === "no_show") ||
      activeExactCleanings[0] ||
      (deletedExactCleaning && !deletedExactCleaning.isDeleted ? deletedExactCleaning : undefined);

    // Só busca em effectiveDate se não houver NENHUM cleaningRequest criado para a data de hoje
    if (!existingCleaning) {
      const matchingCleanings = (db.cleaningRequests || []).filter(c =>
        (String(c.flatNumber).replace(/\D/g, "") === flatNumClean || c.flatId === flat.id) &&
        c.effectiveDate === dateStr && c.status === "clean" && !c.revertedToDirtyAt
      );
      existingCleaning = matchingCleanings[0];
    }

    // Blindagem de Auditoria: Se o status ainda for dirty mas o ÚLTIMO evento de auditoria de hoje for clean (sem devolução posterior), respeita o clean
    let auditCleanEvent = null;
    if ((!existingCleaning || existingCleaning.status !== "clean") && !existingCleaning?.revertedToDirtyAt) {
      const flatAuditLogsToday = (db.auditLogs || [])
        .filter(l =>
          (
            l.action === "CLEANING_STATUS_CLEAN" ||
            l.action === "CLEANING_COMPLETED_BY_ADMIN_FOR_MAID" ||
            l.action === "CLEANING_STATUS_DIRTY" ||
            l.action === "CLEANING_RELEASED"
          ) &&
          String(l.details?.flatNumber || "").replace(/\D/g, "") === flatNumClean &&
          (String(l.timestamp || "").substring(0, 10) === dateStr || String(l.details?.requestDate || "") === dateStr)
        )
        .sort((a, b) => String(b.timestamp || "").localeCompare(String(a.timestamp || "")));
      const latestFlatAudit = flatAuditLogsToday[0];
      if (
        latestFlatAudit &&
        (latestFlatAudit.action === "CLEANING_STATUS_CLEAN" || latestFlatAudit.action === "CLEANING_COMPLETED_BY_ADMIN_FOR_MAID")
      ) {
        auditCleanEvent = latestFlatAudit;
      }
    }

    const isManualTwin = Boolean(existingCleaning?.manualTwinBeds || existingCleaning?.isManualInstruction);
    const isManualMattress = Boolean(existingCleaning?.manualExtraMattress || existingCleaning?.isManualInstruction);
    const isManualNote = Boolean(existingCleaning?.manualAdminNote || existingCleaning?.isManualInstruction);

    // Preferências de cama e colchão automáticas seguem ESTRITAMENTE a reserva que chega HOJE (arrivingRes na data do checkout)
    const arrivingHasTwin = Boolean(arrivingRes && (arrivingRes.twinBeds || arrivingRes.bedType === "2 Solteiro" || arrivingRes.bedType === "twin"));
    const arrivingHasMattress = Boolean(arrivingRes && arrivingRes.extraMattress);

    const resolvedTwinBeds = isManualTwin
      ? Boolean(existingCleaning.twinBeds)
      : arrivingHasTwin;

    const resolvedExtraMattress = isManualMattress
      ? Boolean(existingCleaning.extraMattress)
      : arrivingHasMattress;

    const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) : 0;
    const isFutureDate = typeof getTodayStr === "function" && dateStr > getTodayStr();
    let resolvedStatus = existingCleaning ? existingCleaning.status : (auditCleanEvent ? "clean" : "dirty");
    if (isFutureDate && resolvedStatus === "clean" && (!existingCleaning?.completedAt || existingCleaning.completedAt.substring(0, 10) < dateStr)) {
      resolvedStatus = "dirty";
    }

    // Extrai nota da reserva que está chegando hoje + eventual observação manual pendente de dia anterior não limpo
    const arrivingMaidNoteRaw = arrivingRes ? ((arrivingRes.specialRequests || "").trim() || (arrivingRes.notes || "").trim() || null) : null;
    const validArrivingMaidNote = (arrivingMaidNoteRaw && !arrivingMaidNoteRaw.includes("Limpeza de check-out gerada automaticamente") && arrivingMaidNoteRaw.toLowerCase() !== "teste")
      ? sanitizeCardNote(arrivingMaidNoteRaw)
      : null;
    const carriedPriorManualNote = (!isManualNote && resolvedStatus !== "clean")
      ? findUncleanedPriorManualNote(flatNumber, flat.id, dateStr)
      : null;

    let resolvedAdminNote = null;
    if (isManualNote && existingCleaning) {
      resolvedAdminNote = existingCleaning.adminNote || null;
    } else if (carriedPriorManualNote && validArrivingMaidNote) {
      resolvedAdminNote = carriedPriorManualNote.includes(validArrivingMaidNote)
        ? carriedPriorManualNote
        : `${carriedPriorManualNote} • ${validArrivingMaidNote}`;
    } else if (carriedPriorManualNote) {
      resolvedAdminNote = carriedPriorManualNote;
    } else if (validArrivingMaidNote) {
      resolvedAdminNote = validArrivingMaidNote;
    } else if (!isManualNote && (resolvedTwinBeds || resolvedExtraMattress)) {
      const parts = [];
      if (resolvedTwinBeds) parts.push("Separar as camas, colocar como 2 solteiras");
      if (resolvedExtraMattress) parts.push("Colocar 1 colchão extra");
      resolvedAdminNote = parts.join(" • ");
    }
    const resolvedMaidName = resolvedStatus === "clean"
      ? (existingCleaning?.assignedUsername || existingCleaning?.assignedUserName || auditCleanEvent?.details?.assignedMaidName || (auditCleanEvent ? "Cris" : null))
      : (isFutureDate ? null : (existingCleaning?.assignedUsername || existingCleaning?.assignedUserName || null));
    const resolvedMaidId = resolvedStatus === "clean"
      ? (existingCleaning?.assignedUserId || auditCleanEvent?.details?.assignedUserId || (auditCleanEvent ? 2 : null))
      : (isFutureDate ? null : (existingCleaning?.assignedUserId || null));

    // Regra de Negócio: Check-outs entram como padrão com status OCUPADO (isVacant = false).
    // "Desocupado" apenas quando explicitamente confirmado manualmente via card, via link/WhatsApp (hóspede ou recepção) ou quando a limpeza já foi iniciada/concluída.
    const isCleaningStartedOrDone = !isFutureDate && (resolvedStatus === "cleaning_now" || resolvedStatus === "in_progress" || resolvedStatus === "clean");
    const actualCheckoutBrlDate = pmsRes.actualCheckoutAt
      ? new Date(new Date(pmsRes.actualCheckoutAt).getTime() - 3 * 3600 * 1000).toISOString().substring(0, 10)
      : null;
    // Blindagem temporal: ignora carimbos de check-out gravados em dias anteriores à data de saída (ex.: contaminação em turnover ou meio de estadia)
    const isValidResCheckoutForDate = !actualCheckoutBrlDate || actualCheckoutBrlDate >= dateStr;
    const isExplicitlyVacantCheckout = Boolean(
      isCleaningStartedOrDone ||
      (existingCleaning && existingCleaning.isVacant && (
        existingCleaning.isVacantExplicitlySet ||
        existingCleaning.vacantSource === "guest_checkout" ||
        existingCleaning.vacantSource === "reception_checkout" ||
        existingCleaning.vacantSource === "whatsapp_concierge" ||
        existingCleaning.vacantSource === "whatsapp_guest" ||
        existingCleaning.vacantSource === "cleaning_started" ||
        existingCleaning.vacantSource === "cleaning_completed" ||
        existingCleaning.vacantSource === "manual_card" ||
        existingCleaning.vacantSource === "admin" ||
        existingCleaning.source === "guest_checkout" ||
        existingCleaning.source === "whatsapp_concierge" ||
        existingCleaning.source === "whatsapp_guest"
      )) ||
      (!isFutureDate && (!existingCleaning || !existingCleaning.isVacantExplicitlySet) && isValidResCheckoutForDate && Boolean(
        pmsRes.checkoutDone || pmsRes.status === "completed" || pmsRes.status === "checked_out" || pmsRes.actualCheckoutAt
      ))
    );

    const cleanExistingAdmin = sanitizeCardNote(resolvedAdminNote);
    const cleanExistingPendingObs = existingCleaning ? sanitizeCardNote(existingCleaning.pendingObservation) : cleanExistingAdmin;
    const resolvedVacantSource = existingCleaning?.vacantSource || (
      isExplicitlyVacantCheckout
        ? (isCleaningStartedOrDone ? "cleaning_started" : (pmsRes.checkoutMethod || "reception_checkout"))
        : null
    );

    const resolvedSmoked = existingCleaning && (typeof existingCleaning.smokedInRoom === "boolean" || typeof existingCleaning.guestSmoked === "boolean")
      ? Boolean(existingCleaning.smokedInRoom || existingCleaning.guestSmoked)
      : Boolean(resolvedStatus === "clean" && (pmsRes?.smokedInRoom || pmsRes?.guestSmoked));

    const card = {
      id: existingCleaning ? existingCleaning.id : (maxId + 1),
      flatId: flat.id,
      flatNumber: flat.number,
      requestDate: dateStr,
      source: "checkout",
      status: resolvedStatus,
      assignedUserId: resolvedMaidId,
      assignedUsername: resolvedMaidName,
      assignedUserName: resolvedMaidName,
      isVacant: isExplicitlyVacantCheckout,
      isVacantExplicitlySet: Boolean(existingCleaning?.isVacantExplicitlySet || isExplicitlyVacantCheckout),
      vacantSource: resolvedVacantSource,
      isPriority: resolvedStatus === "clean" ? false : (existingCleaning ? Boolean(existingCleaning.isPriority) : Boolean(pmsRes.isPriority)),
      isExtended: false,
      twinBeds: resolvedTwinBeds,
      extraMattress: resolvedExtraMattress,
      manualTwinBeds: Boolean(existingCleaning?.manualTwinBeds),
      manualExtraMattress: Boolean(existingCleaning?.manualExtraMattress),
      manualAdminNote: Boolean(existingCleaning?.manualAdminNote || carriedPriorManualNote),
      isManualInstruction: Boolean(existingCleaning?.isManualInstruction),
      checkoutReservationId: pmsRes.id || existingCleaning?.checkoutReservationId || null,
      checkoutReservationCode: pmsRes.code || existingCleaning?.checkoutReservationCode || null,
      autoReservationCode: arrivingRes ? arrivingRes.code : (existingCleaning?.autoReservationCode || null),
      autoReservationId: arrivingRes ? arrivingRes.id : (existingCleaning?.autoReservationId || null),
      adminNote: cleanExistingAdmin,
      leavingGuest: pmsRes.guestName || pmsRes.title || "Hóspede",
      arrivingGuest: arrivingRes ? (arrivingRes.guestName || arrivingRes.title) : null,
      pendingObservation: resolvedStatus === "pending_issue" ? (cleanExistingPendingObs || cleanExistingAdmin) : cleanExistingAdmin,
      smokedInRoom: resolvedSmoked,
      guestSmoked: resolvedSmoked,
      smokedMarkedAt: existingCleaning?.smokedMarkedAt || null,
      smokedMarkedBy: existingCleaning?.smokedMarkedBy || null,
      willCleanAt: existingCleaning ? existingCleaning.willCleanAt : null,
      cleaningStartedAt: (isFutureDate && resolvedStatus === "dirty") ? null : (existingCleaning ? existingCleaning.cleaningStartedAt : null),
      completedAt: (isFutureDate && resolvedStatus === "dirty") ? null : (existingCleaning ? existingCleaning.completedAt : null),
      durationMinutes: (isFutureDate && resolvedStatus === "dirty") ? null : (existingCleaning ? existingCleaning.durationMinutes : null),
      createdAt: existingCleaning ? existingCleaning.createdAt : `${dateStr}T08:00:00.000Z`,
      updatedAt: existingCleaning ? existingCleaning.updatedAt : `${dateStr}T08:00:00.000Z`
    };

    if (existingCleaning) {
      if (pmsRes.id && existingCleaning.checkoutReservationId !== pmsRes.id) {
        existingCleaning.checkoutReservationId = pmsRes.id;
        existingCleaning.checkoutReservationCode = pmsRes.code || null;
      }
      if (typeof existingCleaning.smokedInRoom !== "boolean") {
        existingCleaning.smokedInRoom = resolvedSmoked;
        existingCleaning.guestSmoked = resolvedSmoked;
      }
      if (isFutureDate && existingCleaning.status === "clean" && (!existingCleaning.completedAt || existingCleaning.completedAt.substring(0, 10) < dateStr)) {
        existingCleaning.status = "dirty";
        existingCleaning.isPriority = false;
        delete existingCleaning.priorityReason;
        existingCleaning.assignedUserId = null;
        existingCleaning.assignedUsername = null;
        existingCleaning.assignedUserName = null;
        existingCleaning.completedAt = null;
        existingCleaning.cleaningStartedAt = null;
        existingCleaning.durationMinutes = null;
        shouldSaveDb = true;
      } else if (existingCleaning.status === "clean" && (existingCleaning.isPriority || existingCleaning.priorityReason)) {
        existingCleaning.isPriority = false;
        delete existingCleaning.priorityReason;
        shouldSaveDb = true;
      }
      if (isExplicitlyVacantCheckout && !existingCleaning.isVacant) {
        existingCleaning.isVacant = true;
        existingCleaning.isVacantExplicitlySet = true;
        existingCleaning.vacantSource = resolvedVacantSource;
        shouldSaveDb = true;
      }
      if (existingCleaning.twinBeds !== resolvedTwinBeds || existingCleaning.extraMattress !== resolvedExtraMattress || existingCleaning.adminNote !== cleanExistingAdmin || (carriedPriorManualNote && !existingCleaning.manualAdminNote)) {
        existingCleaning.twinBeds = resolvedTwinBeds;
        existingCleaning.extraMattress = resolvedExtraMattress;
        existingCleaning.adminNote = cleanExistingAdmin;
        existingCleaning.pendingObservation = cleanExistingAdmin;
        if (carriedPriorManualNote) {
          existingCleaning.manualAdminNote = true;
        }
        if (!isManualTwin && !arrivingRes) {
          existingCleaning.autoReservationCode = null;
          existingCleaning.autoReservationId = null;
          existingCleaning.arrivingGuest = null;
        }
        shouldSaveDb = true;
      }
    } else if (dateStr >= "2026-09-01") {
      db.cleaningRequests.push(card);
      shouldSaveDb = true;
    }

    if (
      !isFutureDate &&
      isExplicitlyVacantCheckout &&
      !pmsRes.checkoutDone &&
      pmsRes._checkoutUndoneDate !== dateStr &&
      pmsRes.status !== "expirada" &&
      pmsRes.status !== "pre_reserva" &&
      pmsRes.status !== "pendente" &&
      pmsRes.status !== "cancelada" &&
      pmsRes.status !== "cancelled" &&
      pmsRes.status !== "cancelado" &&
      pmsRes.status !== "no_show"
    ) {
      pmsRes.checkoutDone = true;
      if (pmsRes.status !== "completed" && pmsRes.status !== "checked_out") {
        pmsRes.previousStatus = pmsRes.status;
        pmsRes.status = "completed";
      }
      pmsRes.checkoutMethod = pmsRes.checkoutMethod || resolvedVacantSource || "checkout_sync";
      cancelPendingStayRemindersForCheckout(db, null, {
        reservation: pmsRes,
        flatId: flat.id,
        flatNumber: flat.number,
        reason: "Cancelado: check-out sincronizado com governança"
      });
      shouldSaveDb = true;
    }

    requestsForDate.push(card);
    existingFlatNumbersForDate.add(flatNumber);
  }

  // Helper: Descarta automaticamente cards de checkout órfãos (reserva cancelada, expirada, no_show, excluída ou remarcada)
  const isOrphanCheckoutRequest = (r, fNumber) => {
    if (!r || r.source !== "checkout" || r.status === "clean" || r.isVacantExplicitlySet || r.markedByAdmin || r.revertedToDirtyAt) return false;
    const hasActiveCheckoutOnReqDate = (db.reservations || []).some(res =>
      res.status !== "cancelada" &&
      res.status !== "cancelado" &&
      res.status !== "cancelled" &&
      res.status !== "expirada" &&
      res.status !== "pre_reserva" &&
      res.status !== "pendente" &&
      res.status !== "no_show" &&
      String(res.flatNumber || (db.flats.find(f => f.id === res.flatId)?.number || "")) === fNumber &&
      (res.checkoutDate === r.requestDate || res.earlyCheckoutDate === r.requestDate)
    );
    if (hasActiveCheckoutOnReqDate) return false;

    const hasCancelledOrMovedCheckout = (db.reservations || []).some(res => {
      const resFlat = String(res.flatNumber || (db.flats.find(f => f.id === res.flatId)?.number || ""));
      const isCancelledOrNoShow = res.status === "cancelada" || res.status === "cancelado" || res.status === "cancelled" || res.status === "no_show" || res.status === "expirada" || res.status === "pre_reserva";
      if (isCancelledOrNoShow && resFlat === fNumber && (res.checkoutDate === r.requestDate || res.earlyCheckoutDate === r.requestDate)) {
        return true;
      }
      if (r.leavingGuest && res.guestName && res.guestName.trim().toLowerCase() === r.leavingGuest.trim().toLowerCase()) {
        if (isCancelledOrNoShow || resFlat !== fNumber || (res.checkoutDate !== r.requestDate && res.earlyCheckoutDate !== r.requestDate)) {
          return true;
        }
      }
      return false;
    });

    if (hasCancelledOrMovedCheckout) {
      const nowIso = new Date().toISOString();
      r.isDeleted = true;
      r.status = "deleted";
      r.deletedAt = nowIso;
      r.deletedBy = "auto_orphan_checkout_cleanup";
      r.updatedAt = nowIso;
      shouldSaveDb = true;
      return true;
    }
    return false;
  };

  // 4. Garante que qualquer solicitação existente no banco de dados para a data apareça na listagem
  for (const r of (db.cleaningRequests || [])) {
    if (r.isDeleted || r.status === "deleted") continue;
    if (r.status === "clean" && (r.isPriority || r.priorityReason)) {
      r.isPriority = false;
      delete r.priorityReason;
      shouldSaveDb = true;
    }
    const fNumber = String(r.flatNumber || "");
    const isInst = Boolean(r.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.isBedAdjustmentOnly);
    // Instrução: concluiu, sumiu! Não exibe no painel de pendências ativas
    if (isInst && r.status === "clean") continue;
    if (!isInst && isOrphanCheckoutRequest(r, fNumber)) continue;
    if (r.requestDate === dateStr && (!existingFlatNumbersForDate.has(fNumber) || isInst)) {
      if (stayoverFlatNumbers.has(fNumber) && r.source === "checkout" && !r.twinBeds && !r.extraMattress && !r.adminNote && !r.pendingObservation) continue;
      requestsForDate.push(r);
      if (!isInst) existingFlatNumbersForDate.add(fNumber);
    }
  }

  // 4.5. Solicitações de dias anteriores que foram trabalhadas ou concluídas nesta data (ex: carry-over limpo hoje)
  for (const r of (db.cleaningRequests || [])) {
    if (r.isDeleted || r.status === "deleted") continue;
    const fNumber = String(r.flatNumber || "");
    const isInst = Boolean(r.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.isBedAdjustmentOnly);
    if (isInst) continue; // Instruções nunca são transferidas para outra data
    if (isOrphanCheckoutRequest(r, fNumber)) continue;
    if (!existingFlatNumbersForDate.has(fNumber)) {
      const execDate = r.effectiveDate ||
        (r.completedAt ? r.completedAt.substring(0, 10) : null) ||
        (r.cleaningStartedAt ? r.cleaningStartedAt.substring(0, 10) : null) ||
        (r.willCleanAt ? r.willCleanAt.substring(0, 10) : null);

      if (execDate === dateStr && r.requestDate < dateStr) {
        requestsForDate.push({
          ...r,
          isPendingFromPreviousDay: true,
          originalRequestDate: r.originalRequestDate || r.requestDate
        });
        existingFlatNumbersForDate.add(fNumber);
      }
    }
  }

  // 5. Carry-Over de pendências não limpas de dias anteriores (para hoje e dias futuros)
  if (typeof getTodayStr === "function" && dateStr >= getTodayStr()) {
    const previousUncleaned = (db.cleaningRequests || []).filter(r => {
      if (r.isDeleted || r.status === "deleted") return false;
      const fNumber = String(r.flatNumber || "");
      const isInst = Boolean(r.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.isBedAdjustmentOnly);
      if (isInst) return false;
      if (r.source === "stayover" || r.cleaningType === "stayover") {
        if (!stayoverFlatNumbers.has(fNumber)) return false;
      }
      if (stayoverFlatNumbers.has(fNumber)) {
        const currentStayRes = (db.reservations || []).find(res =>
          res.status !== "cancelada" &&
          res.status !== "cancelled" &&
          String(res.flatNumber || (db.flats.find(f => f.id === res.flatId)?.number || "")) === fNumber &&
          res.checkinDate < dateStr && res.checkoutDate > dateStr
        );
        // Só descarta se a solicitação for de uma estadia anterior à chegada do hóspede atual
        if (currentStayRes && r.requestDate < currentStayRes.checkinDate) return false;
        // Se for checkout puramente automático sem camas/instruções gerado para data intermediária que não coincide com a saída, descarta
        if (r.source === "checkout" && !r.twinBeds && !r.extraMattress && !r.adminNote && !r.pendingObservation && (!currentStayRes || r.requestDate !== currentStayRes.checkoutDate)) return false;
      }
      if (!r.requestDate || r.requestDate < "2026-09-01" || r.requestDate >= dateStr || r.status === "clean" || r.status === "extended" || r.status === "no_show") return false;
      if (!r.leavingGuest && r.source !== "manual" && r.source !== "admin_manual" && r.source !== "guest_checkout" && !(r.source === "service_order" && r.serviceOrderId && r.requestDate >= "2026-11-01") && !(r.manualAdminNote && r.adminNote)) return false;
      if (existingFlatNumbersForDate.has(fNumber)) return false;

      // Descarta cards de checkout órfãos cuja reserva associada na data foi cancelada, no_show ou remarcada
      if (isOrphanCheckoutRequest(r, fNumber)) return false;

      // Se o flat já possui qualquer limpeza efetivamente concluída (status === "clean") nessa mesma data ou em data posterior (até dateStr),
      // ele já foi higienizado e NÃO deve ser considerado pendência nem reaparecer para limpar!
      const alreadyCleanedOnOrAfter = (db.cleaningRequests || []).some(c => {
        if (String(c.flatNumber) !== fNumber && c.flatId !== r.flatId) return false;
        if (c.isInstructionOnly || c.isBedAdjustmentOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only") return false;
        if (c.status !== "clean") return false;
        const cExecDate = c.effectiveDate || (c.completedAt ? c.completedAt.substring(0, 10) : c.requestDate);
        return Boolean(cExecDate && cExecDate >= r.requestDate && cExecDate <= dateStr);
      });
      if (alreadyCleanedOnOrAfter) return false;

      return true;
    });

    previousUncleaned.sort((a, b) => new Date(b.requestDate).getTime() - new Date(a.requestDate).getTime());

    for (const prevReq of previousUncleaned) {
      const fNumber = String(prevReq.flatNumber || "");
      if (!existingFlatNumbersForDate.has(fNumber)) {
        const isManualTwin = Boolean(prevReq.manualTwinBeds || prevReq.isManualInstruction);
        const isManualMattress = Boolean(prevReq.manualExtraMattress || prevReq.isManualInstruction);
        const isManualNote = Boolean(prevReq.manualAdminNote || prevReq.isManualInstruction);

        const arrivingToday = (db.reservations || []).find(res =>
          res.status !== "cancelada" && res.status !== "cancelled" &&
          String(res.flatNumber || (db.flats.find(f => f.id === res.flatId)?.number || "")) === fNumber &&
          res.checkinDate === dateStr
        );

        const resolvedTwin = isManualTwin ? Boolean(prevReq.twinBeds) : Boolean(arrivingToday && (arrivingToday.twinBeds || arrivingToday.bedType === "2 Solteiro" || arrivingToday.bedType === "twin"));
        const resolvedMattress = isManualMattress ? Boolean(prevReq.extraMattress) : Boolean(arrivingToday && arrivingToday.extraMattress);
        const arrNoteRaw = arrivingToday ? ((arrivingToday.specialRequests || "").trim() || (arrivingToday.notes || "").trim() || null) : null;
        const validArrNote = (arrNoteRaw && !arrNoteRaw.includes("Limpeza de check-out gerada automaticamente") && arrNoteRaw.toLowerCase() !== "teste")
          ? sanitizeCardNote(arrNoteRaw)
          : null;
        let resolvedNote = prevReq.adminNote;
        if (isManualNote) {
          const cleanPrevNote = sanitizeCardNote(prevReq.adminNote);
          if (cleanPrevNote && validArrNote && !cleanPrevNote.includes(validArrNote)) {
            resolvedNote = `${cleanPrevNote} • ${validArrNote}`;
          } else {
            resolvedNote = cleanPrevNote;
          }
        } else {
          if (validArrNote) {
            resolvedNote = validArrNote;
          } else if (resolvedTwin || resolvedMattress) {
            const parts = [];
            if (resolvedTwin) parts.push("Separar as camas, colocar como 2 solteiras");
            if (resolvedMattress) parts.push("Colocar 1 colchão extra");
            resolvedNote = parts.join(" • ");
          } else {
            resolvedNote = null;
          }
        }

        requestsForDate.push({
          ...prevReq,
          twinBeds: resolvedTwin,
          extraMattress: resolvedMattress,
          adminNote: sanitizeCardNote(resolvedNote),
          pendingObservation: sanitizeCardNote(resolvedNote),
          arrivingGuest: arrivingToday ? (arrivingToday.guestName || arrivingToday.title) : null,
          isPendingFromPreviousDay: true,
          originalRequestDate: prevReq.originalRequestDate || prevReq.requestDate
        });
        existingFlatNumbersForDate.add(fNumber);
      }
    }
  }

  if (shouldSaveDb) {
    saveDatabase("get_requests_sync");
  }

  if (!isNested) {
    requestsForDateCache.set(dateStr, {
      timestamp: Date.now(),
      data: requestsForDate,
      version: requestsForDateVersion
    });
  }

  return requestsForDate;
}

app.post("/api/admin/reset-cleaning-cache", requireDevAuth, (req, res) => {
  db.cleaningRequests = [];
  saveDatabase();
  res.json({ success: true, count: 0 });
});

app.post("/api/reservations/clear-all", requireDevAuth, (req, res) => {
  const count = (db.reservations || []).length;
  db.reservations = [];
  if (db.guestBreakfastOrders) db.guestBreakfastOrders = [];
  saveDatabase();
  console.log(`[PMS] ${count} reservas de teste excluídas com sucesso.`);
  res.json({ success: true, count, message: `${count} reservas de teste foram excluídas com sucesso!` });
});

app.get("/api/reservations/checkouts", (req, res) => {
  triggerBackgroundSync();
  sweepExpiredPreReservations(db, saveDatabase);
  if (isUniversalIntegrityDirty && reconcileUniversalIntegrity()) {
    setImmediate(() => saveDatabase("integrity_reconciled"));
  }
  const dateStr = req.query.date || getTodayStr();
  const requestsForDate = getRequestsForDate(dateStr);
  const activeSurveys = db.surveys.filter(s => s.isActive);

  // O(1) Indexing: Map de última execução por task + flat e reservas ativas por flat
  const latestExecutionMap = new Map();
  for (const e of (db.periodicExecutions || [])) {
    if (!e) continue;
    const key = `${e.periodicTaskId}_${e.flatId}`;
    const existing = latestExecutionMap.get(key);
    if (!existing || new Date(e.executedAt).getTime() > new Date(existing.executedAt).getTime()) {
      latestExecutionMap.set(key, e);
    }
  }
  const reservationsByFlat = new Map();
  for (const r of (db.reservations || [])) {
    if (!r || r.status === 'cancelada' || r.status === 'cancelado' || r.status === 'cancelled' || r.status === 'expirada' || r.status === 'pre_reserva' || r.status === 'pendente' || r.status === 'no_show') continue;
    const fId = Number(r.flatId);
    const fNum = String(r.flatNumber || "");
    if (fId) {
      if (!reservationsByFlat.has(fId)) reservationsByFlat.set(fId, []);
      reservationsByFlat.get(fId).push(r);
    }
    if (fNum) {
      if (!reservationsByFlat.has(fNum)) reservationsByFlat.set(fNum, []);
      reservationsByFlat.get(fNum).push(r);
    }
  }
  const checkoutsContext = { latestExecutionMap, reservationsByFlat };

  const result = requestsForDate.map(req_ => {
    const isStayover = Boolean(req_.source === "stayover" || req_.cleaningType === "stayover");
    const flat = db.flats.find(f => f.id === req_.flatId) || { id: req_.flatId, number: req_.flatNumber || String(req_.flatId), isOccupied: true };
    const assignedUser = db.users.find(u => u.id === req_.assignedUserId);
    const checkinResToday = (db.reservations || []).find(r =>
      (r.flatId === flat.id || String(r.flatNumber || "") === String(flat.number)) &&
      r.checkinDate === dateStr &&
      r.status !== "cancelada" &&
      r.status !== "cancelado" &&
      r.status !== "cancelled" &&
      r.status !== "expirada" &&
      r.status !== "pre_reserva" &&
      r.status !== "pendente" &&
      r.status !== "no_show"
    );
    const hasCheckinToday = Boolean(checkinResToday) || (!req_.isPendingFromPreviousDay && Boolean(req_.arrivingGuest));
    const resolvedArrivingGuest = checkinResToday
      ? (checkinResToday.guestName || checkinResToday.title)
      : (!req_.isPendingFromPreviousDay ? req_.arrivingGuest : null);

    const pendingTasks = [];
    for (const pt of (db.periodicTasks || []).filter(t => t.isActive && t.assignToHousekeeping !== false && (!Array.isArray(t.flatIds) || t.flatIds.length === 0 || t.flatIds.map(Number).includes(Number(flat.id))))) {
      const taskStatus = computePeriodicTaskStatus(pt, flat, dateStr, checkoutsContext);
      if (taskStatus.isDue) {
        pendingTasks.push({
          id: pt.id,
          name: pt.name,
          description: pt.description,
          periodDays: pt.periodDays,
          periodType: pt.periodType || "calendar_days",
          firstDueDate: pt.firstDueDate,
          nextDueAt: taskStatus.nextDueAt,
          currentOccupiedDays: taskStatus.currentOccupiedDays,
          remainingOccupiedDays: taskStatus.remainingOccupiedDays,
          daysOverdue: taskStatus.daysOverdue
        });
      }
    }

    const pendingSurveys = [];
    if (!isStayover) {
      for (const s of activeSurveys) {
        // Se a vistoria tiver flatIds especificados, só se aplica aos flats selecionados
        const appliesToFlat = !Array.isArray(s.flatIds) || s.flatIds.length === 0 || s.flatIds.map(Number).includes(Number(flat.id));
        if (!appliesToFlat) continue;

        // Só aparece se o flat ainda NÃO tiver respondido
        const alreadyAnswered = Array.isArray(s.responses) && s.responses.some(r => Number(r.flatId) === Number(flat.id));
        if (!alreadyAnswered) {
          pendingSurveys.push({
            id: s.id,
            title: s.title,
            description: s.description || "",
            flatIds: s.flatIds || [],
            questions: Array.isArray(s.questions) && s.questions.length > 0
              ? s.questions
              : [{
                  id: `q_${s.id}_default`,
                  question: s.question || s.title,
                  type: s.type || "yes_no",
                  options: [],
                  isRequired: true
                }]
          });
        }
      }
    }

    // Regra de Negócio: Check-outs entram como padrão com status OCUPADO (isOccupied = true, isVacant = false).
    // "Desocupado" apenas quando explicitamente confirmado manualmente via card, via link/WhatsApp (hóspede ou recepção) ou quando a limpeza já foi iniciada/concluída.
    const isCleaningStartedOrDone = dateStr <= getTodayStr() && (req_.status === "cleaning_now" || req_.status === "in_progress" || req_.status === "clean");
    const isExplicitlyVacant = Boolean(
      isCleaningStartedOrDone ||
      ((
        req_.isVacantExplicitlySet ||
        req_.vacantSource === "guest_checkout" ||
        req_.vacantSource === "reception_checkout" ||
        req_.vacantSource === "whatsapp_concierge" ||
        req_.vacantSource === "whatsapp_guest" ||
        req_.vacantSource === "cleaning_started" ||
        req_.vacantSource === "cleaning_completed" ||
        req_.vacantSource === "manual_card" ||
        req_.vacantSource === "admin" ||
        req_.source === "guest_checkout" ||
        req_.source === "whatsapp_concierge" ||
        req_.source === "whatsapp_guest"
      ) && Boolean(req_.isVacant))
    );

    // Stayover preserva flat ocupado: isOccupied = true, isVacant = false
    const isVacant = isStayover ? false : isExplicitlyVacant;
    const isOccupied = isStayover ? true : !isVacant;

    // Check for arriving reservation setup preferences or admin custom instructions
    const isManualTwin = Boolean(req_.manualTwinBeds || req_.isManualInstruction);
    const isManualMattress = Boolean(req_.manualExtraMattress || req_.isManualInstruction);
    const isManualNote = Boolean(req_.manualAdminNote || req_.isManualInstruction);

    // Instruções automáticas seguem ESTRITAMENTE a reserva de check-in de HOJE (dateStr)
    const arrivingTodayRes = checkinResToday || (db.reservations || []).find(r =>
      (r.flatId === flat.id || String(r.flatNumber) === String(flat.number)) &&
      r.checkinDate === dateStr &&
      r.status !== "cancelada" && r.status !== "cancelado" && r.status !== "cancelled" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show"
    );

    const hasTwinBeds = isManualTwin
      ? Boolean(req_.twinBeds)
      : Boolean(arrivingTodayRes && (arrivingTodayRes.twinBeds || arrivingTodayRes.bedType === "2 Solteiro" || arrivingTodayRes.bedType === "twin"));

    const hasExtraMattress = isManualMattress
      ? Boolean(req_.extraMattress)
      : Boolean(arrivingTodayRes && arrivingTodayRes.extraMattress);

    const hasPrefersHighFloor = Boolean(arrivingTodayRes && arrivingTodayRes.prefersHighFloor);

    // Nota da camareira da reserva que chega hoje ou observação manual descartável do card
    const resNoteForMaid = (arrivingTodayRes && ((arrivingTodayRes.specialRequests || "").trim() || (arrivingTodayRes.notes || "").trim())) || null;
    let resolvedSpecialRequests = null;
    if (Boolean(req_.manualAdminNote)) {
      if (req_.adminNote) {
        let cleanAdminNote = String(req_.adminNote).trim();
        if (cleanAdminNote.includes("Pagamento integral") || cleanAdminNote.includes("Quitação de saldo") || cleanAdminNote.includes("Limpeza de check-out gerada automaticamente")) {
          cleanAdminNote = "";
        }
        resolvedSpecialRequests = sanitizeCardNote(cleanAdminNote);
      } else {
        resolvedSpecialRequests = null;
      }
    } else {
      if (isManualNote && req_.adminNote) {
        let cleanAdminNote = String(req_.adminNote).trim();
        if (cleanAdminNote.includes("Pagamento integral") || cleanAdminNote.includes("Quitação de saldo") || cleanAdminNote.includes("Limpeza de check-out gerada automaticamente")) {
          cleanAdminNote = "";
        }
        resolvedSpecialRequests = sanitizeCardNote(cleanAdminNote);
      }
      if (!resolvedSpecialRequests && resNoteForMaid) {
        let cleanResNote = String(resNoteForMaid).trim();
        if (cleanResNote.includes("Pagamento integral") || cleanResNote.includes("Quitação de saldo") || cleanResNote.includes("Limpeza de check-out gerada automaticamente") || cleanResNote.toLowerCase() === "teste") {
          cleanResNote = "";
        }
        resolvedSpecialRequests = sanitizeCardNote(cleanResNote);
      }
      if (!resolvedSpecialRequests && (hasTwinBeds || hasExtraMattress)) {
        const autoNotes = [];
        if (hasTwinBeds) autoNotes.push("Separar as camas, colocar como 2 solteiras");
        if (hasExtraMattress) autoNotes.push("Colocar 1 colchão extra");
        if (autoNotes.length > 0) {
          resolvedSpecialRequests = autoNotes.join(" • ");
        }
      }
    }

    const cleanPendingObs = sanitizeCardNote(req_.pendingObservation);
    const isInst = Boolean(req_.isInstructionOnly || req_.source === "manual_instruction" || req_.type === "instruction" || req_.type === "bed_adjustment_only" || req_.isBedAdjustmentOnly);
    const isServiceCleaning = Boolean(req_.source === "service_order" || req_.cleaningType === "service_order" || req_.type === "service_cleaning");
    const isPaid = typeof req_.isPaidCleaning === "boolean" ? req_.isPaidCleaning : ((isInst || isServiceCleaning) ? false : true);
    const instText = req_.instructionText || req_.notes || sanitizeCardNote(req_.adminNote) || cleanPendingObs || (req_.twinBeds ? "Separar as camas, colocar como 2 solteiras" : null);

    const setupInfo = isInst ? {
      twinBeds: Boolean(req_.twinBeds),
      extraMattress: false,
      prefersHighFloor: false,
      specialRequests: instText,
      adminNote: instText,
      guestName: null
    } : {
      twinBeds: hasTwinBeds,
      extraMattress: hasExtraMattress,
      prefersHighFloor: hasPrefersHighFloor,
      specialRequests: resolvedSpecialRequests,
      adminNote: resolvedSpecialRequests,
      guestName: (isStayover || isServiceCleaning) ? null : (arrivingTodayRes?.guestName || req_.arrivingGuest || null)
    };

    // Check if flat is currently occupied with a checkout on the next day or future
    const activeResToday = isInst ? null : (db.reservations || []).find(r =>
      (r.flatId === flat.id || String(r.flatNumber) === String(flat.number)) &&
      r.status !== "cancelada" && r.status !== "cancelado" && r.status !== "cancelled" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
      r.checkinDate < dateStr && r.checkoutDate > dateStr
    );
    const hasFutureCheckoutOnly = !isInst && !isStayover && !isServiceCleaning && Boolean(activeResToday && activeResToday.checkoutDate > dateStr && !req_.leavingGuest && req_.source !== "guest_checkout" && !req_.isVacant);

    // Identifica a reserva B2B ativa de stayover
    const stayoverRes = isStayover ? ((db.reservations || []).find(r =>
      r.id === req_.reservationId ||
      r.id === req_.autoReservationId ||
      (req_.autoReservationCode && r.code === req_.autoReservationCode) ||
      (
        r.status !== "cancelada" && r.status !== "cancelado" && r.status !== "cancelled" &&
        r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" &&
        r.status !== "no_show" && r.status !== "completed" && r.status !== "checked_out" &&
        !r.checkoutDone && !r.earlyCheckout &&
        (r.flatId === flat.id || String(r.flatNumber) === String(flat.number)) &&
        r.checkinDate < dateStr && r.checkoutDate > dateStr &&
        isB2bReservation(r)
      )
    ) || activeResToday) : null;

    // Identifica a reserva do hóspede saindo hoje ou ativa no flat
    const checkoutRes = (isInst || isServiceCleaning) ? null : (stayoverRes || ((db.reservations || []).find(r =>
      (r.flatId === flat.id || String(r.flatNumber) === String(flat.number)) &&
      r.status !== "cancelada" && r.status !== "cancelado" && r.status !== "cancelled" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
      r.checkoutDate === (req_.originalRequestDate || req_.requestDate || dateStr)
    ) || (req_.leavingGuest ? (db.reservations || []).find(r =>
      (r.flatId === flat.id || String(r.flatNumber) === String(flat.number)) &&
      r.status !== "cancelada" && r.status !== "cancelado" && r.status !== "cancelled" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
      (r.guestName?.toLowerCase() === req_.leavingGuest?.toLowerCase() || (r.guestName && req_.leavingGuest && req_.leavingGuest.toLowerCase().includes(r.guestName.toLowerCase())))
    ) : null) || activeResToday));

    const linenTracking = isStayover && (stayoverRes || activeResToday)
      ? computeLinenTracking(stayoverRes || activeResToday, dateStr, db)
      : null;

    const currentGuest = isStayover
      ? (stayoverRes?.guestName || req_.currentGuest || req_.guestName || activeResToday?.guestName || "Hóspede")
      : null;

    const doNotDisturb = isStayover
      ? Boolean(stayoverRes?.doNotDisturb || req_.doNotDisturb)
      : false;

    return {
      flatId: flat.id,
      flatNumber: flat.number,
      source: isStayover ? "stayover" : (isServiceCleaning ? "service_order" : (req_.source || "checkout")),
      cleaningType: isStayover ? "stayover" : (isServiceCleaning ? "service_order" : (req_.cleaningType || "checkout")),
      serviceOrderId: req_.serviceOrderId || null,
      serviceTitle: req_.serviceTitle || null,
      serviceWorkerName: req_.serviceWorkerName || null,
      serviceOrigin: req_.serviceOrigin || null,
      serviceReason: req_.serviceReason || null,
      serviceInProgress: getFlatServiceInProgress(flat.id, flat.number),
      checkoutDate: req_.requestDate,
      hasCheckinToday: isInst || isStayover ? false : hasCheckinToday,
      isOccupied: isInst ? false : isOccupied,
      isVacant: isInst ? true : isVacant,
      isPriority: req_.status === "clean" ? false : Boolean(req_.isPriority),
      isExtended: (isInst || isServiceCleaning) ? false : (req_.isExtended || req_.status === "extended"),
      isPendingFromPreviousDay: Boolean(req_.isPendingFromPreviousDay),
      originalRequestDate: req_.originalRequestDate || null,
      leavingGuest: (isInst || isStayover || isServiceCleaning) ? null : (req_.leavingGuest || null),
      arrivingGuest: (isInst || isStayover) ? null : (resolvedArrivingGuest || (arrivingTodayRes?.guestName || null)),
      currentGuest: currentGuest,
      doNotDisturb: doNotDisturb,
      linenTracking: linenTracking,
      activeReservation: isStayover && stayoverRes ? {
        guestName: stayoverRes.guestName,
        checkinDate: stayoverRes.checkinDate,
        checkoutDate: stayoverRes.checkoutDate,
        isFutureCheckout: true
      } : (activeResToday ? {
        guestName: activeResToday.guestName,
        checkinDate: activeResToday.checkinDate,
        checkoutDate: activeResToday.checkoutDate,
        isFutureCheckout: activeResToday.checkoutDate > dateStr
      } : null),
      reservation: checkoutRes ? {
        id: checkoutRes.id,
        code: checkoutRes.code,
        guestName: checkoutRes.guestName,
        checkinDate: checkoutRes.checkinDate,
        checkoutDate: checkoutRes.checkoutDate,
        dailyRate: Number(checkoutRes.dailyRate || 0),
        totalAmount: Number(checkoutRes.totalAmount || checkoutRes.price || 0),
        paidAmount: Number(checkoutRes.paidAmount || 0),
        paymentStatus: checkoutRes.paymentStatus || (isStayover ? "pago_total" : "pendente")
      } : null,
      hasFutureCheckoutOnly,
      setupInfo,
      pendingPeriodicTasks: (isInst || isServiceCleaning) ? [] : pendingTasks,
      pendingSurveys: (isInst || isStayover || isServiceCleaning) ? [] : pendingSurveys,
      isInstructionOnly: isInst,
      isBedAdjustmentOnly: Boolean(req_.isBedAdjustmentOnly || req_.type === "bed_adjustment_only"),
      isPaidCleaning: isPaid,
      instructionText: instText,
      smokedInRoom: isServiceCleaning
        ? false
        : ((typeof req_.smokedInRoom === "boolean" || typeof req_.guestSmoked === "boolean")
            ? Boolean(req_.smokedInRoom || req_.guestSmoked)
            : Boolean(!isInst && req_.status === "clean" && (checkoutRes?.smokedInRoom || checkoutRes?.guestSmoked))),
      guestSmoked: isServiceCleaning
        ? false
        : ((typeof req_.smokedInRoom === "boolean" || typeof req_.guestSmoked === "boolean")
            ? Boolean(req_.smokedInRoom || req_.guestSmoked)
            : Boolean(!isInst && req_.status === "clean" && (checkoutRes?.smokedInRoom || checkoutRes?.guestSmoked))),
      cleaningRequest: {
        id: req_.id,
        flatId: req_.flatId,
        flatNumber: flat.number,
        requestDate: req_.requestDate,
        source: isStayover ? "stayover" : (isServiceCleaning ? "service_order" : req_.source),
        cleaningType: isStayover ? "stayover" : (isServiceCleaning ? "service_order" : (req_.cleaningType || "checkout")),
        serviceOrderId: req_.serviceOrderId || null,
        serviceTitle: req_.serviceTitle || null,
        serviceWorkerName: req_.serviceWorkerName || null,
        serviceOrigin: req_.serviceOrigin || null,
        serviceReason: req_.serviceReason || null,
        status: req_.status,
        type: req_.type || (isStayover ? "stayover" : (isServiceCleaning ? "service_cleaning" : (isInst ? "instruction" : "cleaning"))),
        isInstructionOnly: isInst,
        isBedAdjustmentOnly: Boolean(req_.isBedAdjustmentOnly || req_.type === "bed_adjustment_only"),
        isPaidCleaning: isPaid,
        instructionText: instText,
        smokedInRoom: isServiceCleaning
          ? false
          : ((typeof req_.smokedInRoom === "boolean" || typeof req_.guestSmoked === "boolean")
              ? Boolean(req_.smokedInRoom || req_.guestSmoked)
              : Boolean(!isInst && req_.status === "clean" && (checkoutRes?.smokedInRoom || checkoutRes?.guestSmoked))),
        guestSmoked: isServiceCleaning
          ? false
          : ((typeof req_.smokedInRoom === "boolean" || typeof req_.guestSmoked === "boolean")
              ? Boolean(req_.smokedInRoom || req_.guestSmoked)
              : Boolean(!isInst && req_.status === "clean" && (checkoutRes?.smokedInRoom || checkoutRes?.guestSmoked))),
        twinBeds: hasTwinBeds,
        extraMattress: hasExtraMattress,
        adminNote: resolvedSpecialRequests,
        pendingObservation: req_.status === "pending_issue" ? (cleanPendingObs || resolvedSpecialRequests) : resolvedSpecialRequests,
        arrivingGuest: isStayover ? null : (arrivingTodayRes?.guestName || req_.arrivingGuest || null),
        leavingGuest: (isStayover || isServiceCleaning) ? null : (req_.leavingGuest || null),
        currentGuest: currentGuest,
        doNotDisturb: doNotDisturb,
        linenTracking: linenTracking,
        towelsChanged: Boolean(req_.towelsChanged),
        beddingChanged: Boolean(req_.beddingChanged),
        isPriority: req_.status === "clean" ? false : Boolean(req_.isPriority),
        isExtended: req_.isExtended || req_.status === "extended",
        isPendingFromPreviousDay: Boolean(req_.isPendingFromPreviousDay),
        originalRequestDate: req_.originalRequestDate || null,
        assignedUserId: req_.assignedUserId,
        assignedUsername: assignedUser ? assignedUser.username : null,
        assignedUserName: assignedUser ? (assignedUser.name || assignedUser.username) : null,
        isVacant: isInst ? true : isVacant,
        isVacantExplicitlySet: Boolean(req_.isVacantExplicitlySet),
        vacantSource: req_.vacantSource || null,
        willCleanAt: req_.willCleanAt,
        cleaningStartedAt: req_.cleaningStartedAt,
        completedAt: req_.completedAt,
        durationMinutes: req_.durationMinutes || null,
        createdAt: req_.createdAt,
        updatedAt: req_.updatedAt,
      }
    };
  });

  result.sort((a, b) => {
    if (a.isPriority && !b.isPriority) return -1;
    if (!a.isPriority && b.isPriority) return 1;
    if (a.isPendingFromPreviousDay && !b.isPendingFromPreviousDay) return -1;
    if (!a.isPendingFromPreviousDay && b.isPendingFromPreviousDay) return 1;
    if (a.hasCheckinToday && !b.hasCheckinToday) return -1;
    if (!a.hasCheckinToday && b.hasCheckinToday) return 1;
    return a.flatNumber.localeCompare(b.flatNumber, undefined, { numeric: true });
  });

  res.json(result);
});

app.get("/api/reservations/checkins", (req, res) => {
  const dateStr = req.query.date || getTodayStr();
  const list = (db.reservations || [])
    .filter(r => (r.checkinDate === dateStr || r.checkinDate?.substring(0, 10) === dateStr) && r.status !== "cancelada")
    .map(r => {
      const flat = db.flats.find(f => f.id === r.flatId || String(f.number) === String(r.flatNumber)) || { id: r.flatId, number: r.flatNumber || "113" };
      const matchedGuest = (db.guests || []).find(g =>
        (r.guestId && (Number(g.id) === Number(r.guestId) || String(g.id) === String(r.guestId))) ||
        (r.guestDocument && g.document && g.document.replace(/\D/g, "") === r.guestDocument.replace(/\D/g, "")) ||
        (r.guestName && g.name && g.name.trim().toLowerCase() === r.guestName.trim().toLowerCase())
      );
      const isSmoker = Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked || matchedGuest?.isSmoker || matchedGuest?.smokedInRoom || (matchedGuest?.tags || []).includes("Fumante"));
      return {
        id: r.id,
        flatId: flat.id,
        flatNumber: flat.number,
        guestName: r.guestName,
        checkinDate: r.checkinDate,
        checkoutDate: r.checkoutDate,
        guestCount: r.guestCount || r.adults || 1,
        channel: r.channel || "direta",
        notes: r.notes || "",
        earlyCheckinAuthorized: Boolean(r.earlyCheckinAuthorized),
        hasPreCheckin: Boolean(r.fnhrCompleted || (r.guests && r.guests.some(g => g.hasCompletedCheckin))),
        isSmoker,
        smokerGuestAlert: isSmoker,
        guestSmoked: isSmoker
      };
    });
  res.json(list);
});

// ── Calendar Sync & .ICS Download Endpoint (RFC 5545 / RFC 5546) ─────────────
app.get("/api/reservations/:code/calendar.ics", (req, res) => {
  try {
    const code = req.params.code;
    const resItem = (db.reservations || []).find(r =>
      String(r.id) === code || String(r.code) === code || String(r.reservationCode) === code
    );

    if (!resItem) {
      return res.status(404).send("Reserva não encontrada");
    }

    const isCancelled = resItem.status === "cancelada" || resItem.status === "CANCELLED" || req.query.action === "cancel";
    const method = isCancelled ? "CANCEL" : "REQUEST";
    const status = isCancelled ? "CANCELLED" : "CONFIRMED";
    const sequence = resItem.calendarSequence ?? (isCancelled ? 1 : 0);

    const checkinDt = (resItem.checkinDate || getTodayStr()).replace(/-/g, "") + "T140000";
    const checkoutDt = (resItem.checkoutDate || getTodayStr()).replace(/-/g, "") + "T120000";
    const nowDt = new Date().toISOString().replace(/[-:T.]/g, "").substring(0, 15) + "Z";

    const uid = `booking-${resItem.code || resItem.id}@corpflats.com.br`;
    const title = isCancelled
      ? `CANCELADA: Hospedagem CorpFlats - Flat ${resItem.flatNumber || '113'} (#${resItem.code || resItem.id})`
      : sequence > 0
      ? `REMARCADA: Hospedagem CorpFlats - Flat ${resItem.flatNumber || '113'} (#${resItem.code || resItem.id})`
      : `Hospedagem CorpFlats - Flat ${resItem.flatNumber || '113'} - Reserva #${resItem.code || resItem.id}`;

    const location = `Edifício Soho Residence Service, Rua Conselheiro Otaviano, 209 - Centro, Campos dos Goytacazes - RJ, CEP 28010-140`;
    const manageUrl = `https://corpflats.com.br/minha-reserva/${resItem.code || resItem.id}`;
    const guestEmail = resItem.guestEmail || `hospede-${resItem.code || resItem.id}@corpflats.com.br`;

    const descLines = [];
    if (isCancelled) {
      descLines.push(
        `⚠️ RESERVA CANCELADA`,
        `----------------------------------------`,
        `A sua reserva #${resItem.code || resItem.id} no Flat ${resItem.flatNumber || '113'} foi cancelada.`,
        `Mais informações: ${manageUrl}`,
        `WhatsApp do Atendimento: +55 (22) 99712-4021`
      );
    } else {
      descLines.push(
        sequence > 0 ? `🔄 RESERVA REMARCADA / ATUALIZADA` : `🏨 HOSPEDAGEM CONFIRMADA NA CORPFLATS`,
        `----------------------------------------`,
        `Acomodação: Flat ${resItem.flatNumber || '905'}`,
        `Reserva: #${resItem.code || resItem.id}`,
        `Hóspede: ${resItem.guestName || 'Hóspede'}`,
        `Check-in: ${resItem.checkinDate} a partir das 14:00`,
        `Check-out: ${resItem.checkoutDate} até as 12:00`,
        `🔑 Acesso: Retirada do cartão NFC na recepção 24h (mediante check-in digital concluído).`,
        `Wi-Fi: apto${resItem.flatNumber || ''} (Senha: 1234567890123)`,
        `Gerenciar sua reserva: ${manageUrl}`,
        `WhatsApp Suporte: +55 (22) 99712-4021`
      );
    }

    const formattedDesc = descLines.join("\\n").replace(/,/g, "\\,").replace(/;/g, "\\;");
    const partStat = sequence > 0 ? "NEEDS-ACTION" : "ACCEPTED";

    const lines = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//CorpFlats//Motor de Reservas 2.0//PT",
      "CALSCALE:GREGORIAN",
      `METHOD:${method}`,
      "BEGIN:VEVENT",
      `UID:${uid}`,
      `SEQUENCE:${sequence}`,
      `STATUS:${status}`,
      `DTSTAMP:${nowDt}`,
      `DTSTART;TZID=America/Sao_Paulo:${checkinDt}`,
      `DTEND;TZID=America/Sao_Paulo:${checkoutDt}`,
      `SUMMARY:${title}`,
      `DESCRIPTION:${formattedDesc}`,
      `LOCATION:${location}`,
      `URL:${manageUrl}`,
      `ORGANIZER;CN="CorpFlats Campos dos Goytacazes":mailto:reservas@corpflats.com.br`,
      `ATTENDEE;CUTYPE=INDIVIDUAL;ROLE=REQ-PARTICIPANT;PARTSTAT=${partStat};CN=${resItem.guestName || 'Hospede'}:mailto:${guestEmail}`
    ];

    if (!isCancelled) {
      lines.push(
        "BEGIN:VALARM",
        "TRIGGER:-PT24H",
        "ACTION:DISPLAY",
        `DESCRIPTION:Lembrete de Check-in amanhã no Flat ${resItem.flatNumber || '905'} da CorpFlats!`,
        "END:VALARM",
        "BEGIN:VALARM",
        "TRIGGER:-PT2H",
        "ACTION:DISPLAY",
        `DESCRIPTION:Check-in CorpFlats hoje às 14:00 - Flat ${resItem.flatNumber || '905'}. Tenha seu código de acesso em mãos.`,
        "END:VALARM"
      );
    }

    lines.push("END:VEVENT", "END:VCALENDAR");
    const icsPayload = lines.join("\r\n");

    res.setHeader("Content-Type", `text/calendar; charset=UTF-8; method=${method}`);
    res.setHeader("Content-Disposition", `inline; filename="reserva-corpflats-${resItem.code || resItem.id}.ics"`);
    res.send(icsPayload);
  } catch (err) {
    res.status(500).send("Erro ao gerar calendário .ics: " + err.message);
  }
});

// ── Dashboard Summary ───────────────────────────────────────────────────────
app.get("/api/dashboard/summary", (req, res) => {
  triggerBackgroundSync();
  const dateStr = req.query.date || getTodayStr();
  const requestsForDate = getRequestsForDate(dateStr);

  let totalClean = 0, totalPending = 0, totalCleaning = 0, totalWillClean = 0, totalDirty = 0;
  for (const r of requestsForDate) {
    const isInst = Boolean(r.isInstructionOnly || r.cleaningRequest?.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.cleaningRequest?.type === "bed_adjustment_only");
    if (isInst) {
      // Instruções avulsas / favores operacionais não poluem contagem de quartos sujos/faxinas
      continue;
    }
    const status = r.cleaningRequest?.status || r.status;
    if (status === "clean") totalClean++;
    else if (status === "pending_issue") totalPending++;
    else if (status === "cleaning_now") totalCleaning++;
    else if (status === "will_clean") totalWillClean++;
    else if (status === "no_show" || status === "extended") {
      // No Show e Estendeu não contam como sujos/pendentes de faxina
    }
    else totalDirty++;
  }

  const byUserMap = {};
  for (const r of requestsForDate) {
    const isInst = Boolean(r.isInstructionOnly || r.cleaningRequest?.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.cleaningRequest?.type === "bed_adjustment_only");
    const isSvcCleaning = Boolean(r.source === "service_order" || r.cleaningRequest?.source === "service_order" || r.cleaningType === "service_order" || r.type === "service_cleaning");
    if ((isInst || isSvcCleaning) && r.isPaidCleaning === false) continue;
    const assignedId = r.cleaningRequest?.assignedUserId || r.assignedUserId;
    if (!assignedId) continue;
    const u = db.users.find(x => x.id === assignedId);
    if (!byUserMap[assignedId]) {
      byUserMap[assignedId] = {
        userId: assignedId,
        username: u ? u.username : "Desconhecido",
        count: 0
      };
    }
    byUserMap[assignedId].count++;
  }

  const regularTurnovers = requestsForDate.filter(r => {
    const isInst = Boolean(r.isInstructionOnly || r.cleaningRequest?.isInstructionOnly || r.source === "manual_instruction" || r.type === "instruction" || r.type === "bed_adjustment_only" || r.cleaningRequest?.type === "bed_adjustment_only");
    const st = r.cleaningRequest?.status || r.status;
    return !isInst && st !== "no_show";
  });

  res.json({
    date: dateStr,
    totalCheckouts: regularTurnovers.length,
    totalClean,
    totalPending,
    totalCleaning,
    totalWillClean,
    totalDirty,
    byUser: Object.values(byUserMap),
  });
});

// ── Priority Toggle Endpoint ────────────────────────────────────────────────
app.patch("/api/cleaning/assignments/:requestId/priority", (req, res) => {
  const reqId = Number(req.params.requestId);
  const { flatId, flatNumber, requestDate, isPriority } = req.body || {};
  const item = findOrUpsertCleaningRequest(reqId, flatNumber, flatId, requestDate);
  if (!item) return res.status(404).json({ error: "Solicitação não encontrada" });

  if (item.status === "clean") {
    item.isPriority = false;
    delete item.priorityReason;
  } else {
    item.isPriority = typeof isPriority === "boolean" ? isPriority : !item.isPriority;
    if (!item.isPriority) {
      delete item.priorityReason;
    }
  }
  if (!item.isPriority) {
    const targetDate = requestDate || item.requestDate || getTodayStr();
    for (const r of (db.reservations || [])) {
      if (
        (Number(r.flatId) === Number(item.flatId) || String(r.flatNumber) === String(item.flatNumber)) &&
        (r.checkoutDate === targetDate || r.checkinDate === targetDate || (r.checkinDate <= targetDate && r.checkoutDate >= targetDate)) &&
        r.isPriority
      ) {
        r.isPriority = false;
        delete r.priorityReason;
      }
    }
  }
  item.updatedAt = new Date().toISOString();
  saveDatabase();
  res.json(item);
});

// ── Twin Beds Toggle Endpoint (1 Cama Casal <-> 2 Camas Solteiro) ───────────
app.patch("/api/cleaning/assignments/:requestId/twin-beds", (req, res) => {
  const reqId = Number(req.params.requestId);
  const { flatId, flatNumber, requestDate, twinBeds } = req.body || {};
  const item = findOrUpsertCleaningRequest(reqId, flatNumber, flatId, requestDate);
  if (!item) return res.status(404).json({ error: "Solicitação não encontrada" });

  const nextTwin = typeof twinBeds === "boolean" ? twinBeds : !item.twinBeds;
  item.twinBeds = nextTwin;
  item.manualTwinBeds = true;
  item.isManualInstruction = true;
  item.updatedAt = new Date().toISOString();

  // Sincroniza também com a reserva correspondente no flat
  const targetDate = requestDate || item.requestDate || getTodayStr();
  const relatedRes = (db.reservations || []).find(r =>
    (Number(r.flatId) === Number(item.flatId) || String(r.flatNumber) === String(item.flatNumber)) &&
    r.status !== "cancelada" && r.status !== "cancelado" &&
    (r.checkinDate === targetDate || (r.checkinDate <= targetDate && r.checkoutDate >= targetDate))
  );
  if (relatedRes) {
    relatedRes.twinBeds = nextTwin;
    if (!nextTwin && (relatedRes.bedType === "2 Solteiro" || relatedRes.bedType === "twin")) {
      relatedRes.bedType = "1 Casal";
    } else if (nextTwin && (!relatedRes.bedType || relatedRes.bedType === "1 Casal")) {
      relatedRes.bedType = "2 Solteiro";
    }
    relatedRes.updatedAt = new Date().toISOString();
  }

  saveDatabase();
  res.json(item);
});

// ── Helpers de Snapshot e Reversão Completa ("Devolver Quarto") ─────────────
function capturePreCleanSnapshot(item, targetDate) {
  if (!item || item.preCleanSnapshot) return;
  const effDate = targetDate || item.requestDate || item.effectiveDate || getTodayStr();
  const matchingReservations = (db.reservations || []).filter(r =>
    (Number(r.flatId) === Number(item.flatId) || String(r.flatNumber) === String(item.flatNumber)) &&
    (r.checkoutDate === effDate || r.checkinDate === effDate || (r.checkinDate <= effDate && r.checkoutDate >= effDate))
  );
  item.preCleanSnapshot = {
    capturedAt: new Date().toISOString(),
    status: "dirty",
    source: item.source || "checkout",
    cleaningType: item.cleaningType || (item.source === "stayover" ? "stayover" : "checkout"),
    isVacant: Boolean(item.isVacant),
    isVacantExplicitlySet: Boolean(item.isVacantExplicitlySet),
    vacantSource: item.vacantSource || null,
    isPriority: Boolean(item.isPriority),
    priorityReason: item.priorityReason || null,
    adminNote: item.adminNote ?? null,
    pendingObservation: item.pendingObservation ?? null,
    twinBeds: Boolean(item.twinBeds),
    extraMattress: Boolean(item.extraMattress),
    towelsChanged: Boolean(item.towelsChanged),
    beddingChanged: Boolean(item.beddingChanged),
    smokedInRoom: Boolean(item.smokedInRoom || item.guestSmoked),
    smokedMarkedAt: item.smokedMarkedAt || null,
    smokedMarkedBy: item.smokedMarkedBy || null,
    reservationPriorities: matchingReservations.map(r => ({
      id: r.id,
      isPriority: Boolean(r.isPriority),
      priorityReason: r.priorityReason || null,
    })),
  };
}

function revertCleaningRequestToDirty(item, { date = null, userAuth = null, now = new Date().toISOString(), explicitIsVacant = undefined } = {}) {
  if (!item) return null;
  const targetDate = date || item.requestDate || item.effectiveDate || getTodayStr();
  const isInst = Boolean(item.isInstructionOnly || item.source === "manual_instruction" || item.type === "instruction" || item.type === "bed_adjustment_only" || item.isBedAdjustmentOnly);
  const isStayover = Boolean(item.source === "stayover" || item.cleaningType === "stayover");
  const flatNumClean = String(item.flatNumber || "").replace(/\D/g, "");
  const relatedFlat = (db.flats || []).find(f => Number(f.id) === Number(item.flatId) || (flatNumClean && String(f.number).replace(/\D/g, "") === flatNumClean));

  // Coleta todos os registros correlacionados deste flat na data (incluindo carry-overs ou duplicatas)
  const correlatedRecords = isInst
    ? [item]
    : (db.cleaningRequests || []).filter(c => {
        if (!c || c.isDeleted || c.status === "deleted") return false;
        const cInst = Boolean(c.isInstructionOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only" || c.isBedAdjustmentOnly);
        if (cInst) return false;
        const sameFlat =
          (item.flatId && Number(c.flatId) === Number(item.flatId)) ||
          (flatNumClean && String(c.flatNumber || "").replace(/\D/g, "") === flatNumClean);
        if (!sameFlat) return false;
        if (Number(c.id) === Number(item.id)) return true;
        const cCompDate = c.completedAt ? String(c.completedAt).substring(0, 10) : "";
        const cStartDate = c.cleaningStartedAt ? String(c.cleaningStartedAt).substring(0, 10) : "";
        const cWillDate = c.willCleanAt ? String(c.willCleanAt).substring(0, 10) : "";
        return (
          c.requestDate === targetDate ||
          c.effectiveDate === targetDate ||
          c.executionDate === targetDate ||
          cCompDate === targetDate ||
          cStartDate === targetDate ||
          cWillDate === targetDate ||
          (item.requestDate && (c.requestDate === item.requestDate || c.effectiveDate === item.requestDate))
        );
      });

  if (!correlatedRecords.includes(item)) {
    correlatedRecords.unshift(item);
  }

  const snap = item.preCleanSnapshot || correlatedRecords.find(c => c.preCleanSnapshot)?.preCleanSnapshot || null;
  const correlatedIds = new Set(correlatedRecords.map(c => Number(c.id)).filter(Boolean));
  const previousAssignedUserIds = new Set(
    correlatedRecords.map(c => Number(c.assignedUserId)).filter(uid => Number.isFinite(uid) && uid > 0)
  );
  const completedTimestamps = new Set(
    correlatedRecords.map(c => c.completedAt).filter(Boolean)
  );

  // Determina ocupação a preservar: se estava Desocupado, continua Desocupado ao devolver!
  const wasVacant = typeof explicitIsVacant === "boolean"
    ? explicitIsVacant
    : Boolean(
        !isStayover && (
          item.isVacant ||
          snap?.isVacant ||
          correlatedRecords.some(c => c.isVacant) ||
          (relatedFlat && relatedFlat.isOccupied === false)
        )
      );

  const preservedVacantSource = !wasVacant
    ? null
    : (
        (snap?.vacantSource && snap.vacantSource !== "cleaning_started" && snap.vacantSource !== "cleaning_completed")
          ? snap.vacantSource
          : (
              (item.vacantSource && item.vacantSource !== "cleaning_started" && item.vacantSource !== "cleaning_completed")
                ? item.vacantSource
                : "admin"
            )
      );

  // Reverte fumo se foi alterado na finalização
  if (snap && Boolean(item.smokedInRoom || item.guestSmoked) !== Boolean(snap.smokedInRoom)) {
    updateSmokingStatusForCleaning(item, Boolean(snap.smokedInRoom), userAuth, targetDate);
  }

  // Reverte prioridades nas reservas se havia snapshot
  if (snap && Array.isArray(snap.reservationPriorities)) {
    for (const rp of snap.reservationPriorities) {
      const targetRes = (db.reservations || []).find(r => String(r.id) === String(rp.id));
      if (targetRes) {
        targetRes.isPriority = Boolean(rp.isPriority);
        if (rp.priorityReason) {
          targetRes.priorityReason = rp.priorityReason;
        } else {
          delete targetRes.priorityReason;
        }
      }
    }
  }

  // Reverte histórico de enxoval em reservas de stayover
  if (isStayover) {
    for (const r of (db.reservations || [])) {
      if (Number(r.flatId) !== Number(item.flatId) && String(r.flatNumber || "").replace(/\D/g, "") !== flatNumClean) continue;
      if (Array.isArray(r.linenChangeHistory) && r.linenChangeHistory.length > 0) {
        const beforeLen = r.linenChangeHistory.length;
        r.linenChangeHistory = r.linenChangeHistory.filter(entry => {
          if (!entry) return false;
          if (entry.cleaningRequestId && correlatedIds.has(Number(entry.cleaningRequestId))) return false;
          if (entry.date === targetDate && entry.createdAt && completedTimestamps.has(entry.createdAt)) return false;
          return true;
        });
        if (r.linenChangeHistory.length !== beforeLen) {
          r.linenChanges = r.linenChangeHistory;
          const lastBed = [...r.linenChangeHistory].reverse().find(e => e.beddingChanged);
          const lastTow = [...r.linenChangeHistory].reverse().find(e => e.towelsChanged);
          r.lastBeddingChangeDate = lastBed ? lastBed.date : null;
          r.lastTowelsChangeDate = lastTow ? lastTow.date : null;
          r.updatedAt = now;
        }
      }
    }
  }

  // Reverte execuções de tarefas preventivas geradas na conclusão desta limpeza
  if (Array.isArray(db.periodicExecutions)) {
    db.periodicExecutions = db.periodicExecutions.filter(e => {
      if (!e) return false;
      if (e.cleaningRequestId && correlatedIds.has(Number(e.cleaningRequestId))) return false;
      if (
        Number(e.flatId) === Number(item.flatId) &&
        e.executedAt &&
        completedTimestamps.has(e.executedAt) &&
        e.notes === "Executado durante a limpeza do checkout"
      ) {
        return false;
      }
      return true;
    });
  }

  // Reverte respostas de vistoria vinculadas a esta limpeza
  if (Array.isArray(db.surveys)) {
    for (const survey of db.surveys) {
      if (Array.isArray(survey?.responses)) {
        survey.responses = survey.responses.filter(
          resp => !(resp && resp.cleaningRequestId && correlatedIds.has(Number(resp.cleaningRequestId)))
        );
      }
    }
  }

  // Atualiza todos os registros correlacionados para "dirty"
  for (const c of correlatedRecords) {
    c.status = "dirty";
    c.assignedUserId = null;
    c.assignedUsername = null;
    c.assignedUserName = null;
    c.willCleanAt = null;
    c.cleaningStartedAt = null;
    c.completedAt = null;
    c.durationMinutes = null;
    c.effectiveDate = null;
    c.executionDate = null;
    c.markedByAdmin = false;
    c.revertedToDirtyAt = now;
    c.revertedBy = userAuth ? (userAuth.name || userAuth.username) : "Sistema";

    if (isStayover) {
      c.isVacant = false;
    } else if (wasVacant) {
      c.isVacant = true;
      c.isVacantExplicitlySet = true;
      c.vacantSource = preservedVacantSource || "admin";
      c.vacantSetAt = c.vacantSetAt || now;
      c.vacantSetBy = c.vacantSetBy || (userAuth?.username || "admin");
    } else if (snap) {
      c.isVacant = Boolean(snap.isVacant);
      c.isVacantExplicitlySet = Boolean(snap.isVacantExplicitlySet);
      c.vacantSource = snap.vacantSource || null;
    }

    if (snap) {
      c.isPriority = Boolean(snap.isPriority);
      if (snap.priorityReason) {
        c.priorityReason = snap.priorityReason;
      } else {
        delete c.priorityReason;
      }
      c.adminNote = snap.adminNote ?? c.adminNote ?? null;
      c.pendingObservation = snap.pendingObservation ?? null;
      c.towelsChanged = Boolean(snap.towelsChanged);
      c.beddingChanged = Boolean(snap.beddingChanged);
      c.smokedInRoom = Boolean(snap.smokedInRoom);
      c.guestSmoked = Boolean(snap.smokedInRoom);
    } else {
      c.pendingObservation = null;
    }

    delete c.preCleanSnapshot;
    c.updatedAt = now;
  }

  if (relatedFlat && !isStayover && wasVacant) {
    relatedFlat.isOccupied = false;
    relatedFlat.updatedAt = now;
  }

  // Remove duplicatas correlacionadas da mesma data mantendo apenas `item`
  if (!isInst && correlatedRecords.length > 1) {
    const duplicateIdsToDrop = new Set(
      correlatedRecords
        .filter(c => c !== item && c.requestDate === item.requestDate)
        .map(c => Number(c.id))
    );
    if (duplicateIdsToDrop.size > 0) {
      db.cleaningRequests = (db.cleaningRequests || []).filter(c => !duplicateIdsToDrop.has(Number(c.id)));
    }
  }

  // Remove lançamentos de extrato da camareira vinculados e ressincroniza créditos
  if (Array.isArray(db.maidStatementEntries)) {
    db.maidStatementEntries = db.maidStatementEntries.filter(
      e => !(correlatedIds.has(Number(e.cleaningRequestId)) && e.entryDate >= "2026-09-01")
    );
  }
  for (const maidUid of previousAssignedUserIds) {
    if (typeof syncMaidCredits === "function") {
      try { syncMaidCredits(maidUid); } catch (_) {}
    }
  }

  return item;
}

// ── Release / Devolver Flat Endpoint ────────────────────────────────────────
app.post("/api/cleaning/assignments/:requestId/release", (req, res) => {
  const reqId = Number(req.params.requestId);
  const { flatNumber, flatId, date } = req.body || {};
  let item = findOrUpsertCleaningRequest(reqId, flatNumber, flatId, date);
  if (!item) return res.status(404).json({ error: "Solicitação não encontrada" });

  const userAuth = getAuthUser(req);
  const now = new Date().toISOString();
  const targetDate = date || item.requestDate || item.effectiveDate || getTodayStr();

  revertCleaningRequestToDirty(item, { date: targetDate, userAuth, now });

  const flat = db.flats.find(f => f.id === item.flatId);
  logAuditEvent({
    level: "info",
    category: "cleaning",
    action: "CLEANING_STATUS_DIRTY",
    actor: { name: userAuth ? (userAuth.name || userAuth.username) : "Sistema", role: userAuth?.role || "admin" },
    details: {
      requestId: item.id,
      flatNumber: flat ? flat.number : (item.flatNumber || String(item.flatId)),
      requestDate: targetDate,
      status: "dirty",
      assignedUserId: null,
      assignedMaidName: null,
      markedByAdmin: userAuth?.role === "admin" || userAuth?.role === "dev",
      revertedToDirtyAt: now,
    },
    source: "cleaning_dashboard"
  });

  if (typeof invalidateRequestsForDateCache === "function") invalidateRequestsForDateCache();
  saveDatabase();
  checkAndNotifyAvailableServiceFlats();

  res.json({
    ...item,
    flatNumber: flat ? flat.number : String(item.flatId),
    assignedUsername: null,
    assignedUserName: null,
  });
});

// ── Resolve Issue / Baixa de Pendência Endpoint ─────────────────────────────
app.post("/api/cleaning/assignments/:requestId/resolve-issue", (req, res) => {
  const reqId = Number(req.params.requestId);
  const item = db.cleaningRequests.find(r => r.id === reqId);
  if (!item) return res.status(404).json({ error: "Solicitação não encontrada" });

  const userAuth = getAuthUser(req);
  const isCallerAdmin = Boolean((userAuth && (userAuth.role === "admin" || userAuth.role === "dev")) || req.body?.markedByAdmin);
  const activeService = getFlatServiceInProgress(item.flatId, item.flatNumber);
  if (activeService && !activeService.allowSimultaneousCleaning && !isCallerAdmin) {
    return res.status(422).json({
      error: `Limpeza bloqueada: Serviço externo em andamento (${activeService.serviceTitle || "Manutenção"}). Aguarde a conclusão do prestador.`
    });
  }

  const now = new Date().toISOString();
  item.status = "clean";
  item.isPriority = false;
  delete item.priorityReason;
  const targetDate = item.requestDate || item.effectiveDate || getTodayStr();
  for (const r of (db.reservations || [])) {
    if (
      (Number(r.flatId) === Number(item.flatId) || String(r.flatNumber) === String(item.flatNumber)) &&
      (r.checkoutDate === targetDate || r.checkinDate === targetDate || (r.checkinDate <= targetDate && r.checkoutDate >= targetDate)) &&
      r.isPriority
    ) {
      r.isPriority = false;
      delete r.priorityReason;
    }
  }
  item.assignedUserId = userAuth ? userAuth.id : (item.assignedUserId || 2);
  item.completedAt = now;
  item.pendingObservation = null;
  item.updatedAt = now;
  if (typeof invalidateRequestsForDateCache === "function") invalidateRequestsForDateCache();
  saveDatabase();

  const flat = db.flats.find(f => f.id === item.flatId);
  const assignedUser = db.users.find(u => u.id === item.assignedUserId);

  res.json({
    ...item,
    flatNumber: flat ? flat.number : String(item.flatId),
    assignedUsername: assignedUser ? assignedUser.username : null,
  });
});


// ── Helper Universal: Encontra ou Auto-Cria Solicitação de Limpeza em Memória / Banco ──
function findOrUpsertCleaningRequest(reqId, flatNumber, flatId, dateStr = null) {
  if (!db.cleaningRequests) db.cleaningRequests = [];
  const targetDate = dateStr || getTodayStr();

  let item = null;

  // 1. Se informou flatNumber ou flatId, prioriza encontrar por quarto e data para evitar colisão de IDs virtuais
  // 1. Procura por ID numérico direto (para identificar perfeitamente cards reais e instruções)
  if (reqId) {
    const candidate = db.cleaningRequests.find(r => Number(r.id) === Number(reqId));
    if (candidate) {
      item = candidate;
    }
  }

  // 2. Se ainda não achou e informou flatNumber ou flatId, procura por quarto e data (incluindo effectiveDate)
  if (!item && flatNumber) {
    const fClean = String(flatNumber).replace(/\D/g, "");
    const matching = db.cleaningRequests.filter(r =>
      !r.isDeleted && r.status !== "deleted" &&
      String(r.flatNumber || "").replace(/\D/g, "") === fClean &&
      (r.requestDate === targetDate || r.effectiveDate === targetDate)
    );
    item = matching.find(r => r.revertedToDirtyAt) || matching.find(r => r.status === "clean") || matching[0];
  }
  if (!item && flatId) {
    const matching = db.cleaningRequests.filter(r =>
      !r.isDeleted && r.status !== "deleted" &&
      Number(r.flatId) === Number(flatId) &&
      (r.requestDate === targetDate || r.effectiveDate === targetDate)
    );
    item = matching.find(r => r.revertedToDirtyAt) || matching.find(r => r.status === "clean") || matching[0];
  }

  // 3. Se ainda não achou, procura nos cards dinâmicos gerados para a data
  if (!item) {
    const virtualList = getRequestsForDate(targetDate);
    const virtualCard = virtualList.find(c =>
      (flatNumber && String(c.flatNumber) === String(flatNumber)) ||
      (flatId && Number(c.flatId) === Number(flatId)) ||
      (reqId && Number(c.id) === Number(reqId))
    );

    if (virtualCard && virtualCard.id) {
      const existingByVirtualId = db.cleaningRequests.find(r => Number(r.id) === Number(virtualCard.id));
      if (existingByVirtualId) {
        item = existingByVirtualId;
      }
    }

    if (!item) {
      const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) : 0;
      const newId = maxId + 1;
      const now = new Date().toISOString();

      const targetFlatObj = db.flats.find(f =>
        (flatNumber && String(f.number) === String(flatNumber)) ||
        (flatId && Number(f.id) === Number(flatId)) ||
        (virtualCard && (Number(f.id) === Number(virtualCard.flatId) || String(f.number) === String(virtualCard.flatNumber)))
      );

      const isVirtualStayover = Boolean(virtualCard?.source === "stayover" || virtualCard?.cleaningType === "stayover");

      item = {
        id: newId,
        flatId: targetFlatObj ? targetFlatObj.id : (virtualCard?.flatId || (flatId ? Number(flatId) : 1)),
        flatNumber: targetFlatObj ? targetFlatObj.number : (virtualCard?.flatNumber || String(flatNumber || "113")),
        requestDate: targetDate,
        source: virtualCard?.source || "checkout",
        cleaningType: virtualCard?.cleaningType || (isVirtualStayover ? "stayover" : "checkout"),
        status: virtualCard?.status || "dirty",
        assignedUserId: virtualCard?.assignedUserId || null,
        assignedUsername: virtualCard?.assignedUsername || null,
        assignedUserName: virtualCard?.assignedUserName || null,
        isVacant: Boolean(virtualCard?.isVacant),
        isVacantExplicitlySet: Boolean(virtualCard?.isVacantExplicitlySet || virtualCard?.isVacant),
        vacantSource: virtualCard?.vacantSource || (virtualCard?.isVacant ? "admin" : null),
        isPriority: Boolean(virtualCard?.isPriority),
        isExtended: false,
        twinBeds: Boolean(virtualCard?.twinBeds),
        extraMattress: Boolean(virtualCard?.extraMattress),
        reservationId: isVirtualStayover
          ? (virtualCard?.reservationId || virtualCard?.autoReservationId || null)
          : (virtualCard?.checkoutReservationId || virtualCard?.reservationId || null),
        checkoutReservationId: !isVirtualStayover ? (virtualCard?.checkoutReservationId || null) : null,
        checkoutReservationCode: !isVirtualStayover ? (virtualCard?.checkoutReservationCode || null) : null,
        adminNote: virtualCard?.adminNote || null,
        leavingGuest: virtualCard?.leavingGuest || null,
        currentGuest: virtualCard?.currentGuest || null,
        arrivingGuest: virtualCard?.arrivingGuest || null,
        pendingObservation: null,
        doNotDisturb: Boolean(virtualCard?.doNotDisturb),
        towelsChanged: Boolean(virtualCard?.towelsChanged),
        beddingChanged: Boolean(virtualCard?.beddingChanged),
        smokedInRoom: Boolean(virtualCard?.smokedInRoom || virtualCard?.guestSmoked),
        guestSmoked: Boolean(virtualCard?.smokedInRoom || virtualCard?.guestSmoked),
        willCleanAt: null,
        cleaningStartedAt: null,
        completedAt: null,
        createdAt: now,
        updatedAt: now
      };

      db.cleaningRequests.unshift(item);
    }
  }

  if (item && item.smokedInRoom === undefined && item.guestSmoked !== undefined) {
    item.smokedInRoom = Boolean(item.guestSmoked);
  }

  return item;
}

// ── Helper Estrito de Identidade Nominal para Marcação de Fumo ──────────────
// Impede falsos positivos causados por placeholders ("Hóspede 2") ou telefones corporativos B2B.
function isStrictSamePersonForSmoking(nameA, nameB, allowInitialMatch = false) {
  if (!nameA || !nameB) return false;
  if (typeof isSystemOrServiceOrderGuestName === "function" && (isSystemOrServiceOrderGuestName(nameA) || isSystemOrServiceOrderGuestName(nameB))) return false;
  if (typeof isPlaceholderOrEmptyGuestName === "function" && (isPlaceholderOrEmptyGuestName(nameA) || isPlaceholderOrEmptyGuestName(nameB))) return false;

  const cleanTokenize = (str) => {
    const norm = String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
    if (!norm) return [];
    if (/^(hospede|acompanhante|visitante|a definir|sem nome|bloqueio|manutencao|teste|quarto|flat)(\s+\d+)?$/i.test(norm)) return [];
    const stopWords = new Set(["de", "da", "do", "dos", "das", "del", "di", "du", "e", "jr", "junior", "filho", "filha", "neto", "neta", "sr", "sra", "dr", "dra"]);
    return norm.split(" ").filter(t => t.length >= 1 && !stopWords.has(t));
  };

  const tokensA = cleanTokenize(nameA);
  const tokensB = cleanTokenize(nameB);
  if (tokensA.length === 0 || tokensB.length === 0) return false;

  const fullA = tokensA.join(" ");
  const fullB = tokensB.join(" ");
  if (fullA === fullB && fullA.length >= 3) return true;

  if (tokensA.length >= 2 && tokensB.length >= 2) {
    if (tokensA[0] === tokensB[0] && tokensA[0].length >= 2) {
      const shorter = tokensA.length <= tokensB.length ? tokensA : tokensB;
      const longer = tokensA.length <= tokensB.length ? tokensB : tokensA;
      if (shorter.every(t => longer.includes(t))) return true;
    }
    if (allowInitialMatch) {
      const lastA = tokensA[tokensA.length - 1];
      const lastB = tokensB[tokensB.length - 1];
      if (lastA.length >= 3 && lastA === lastB) {
        const hasInitialOrToken = tokensA.some(ta => tokensB.some(tb => ta === tb || (ta.length === 1 && tb.startsWith(ta)) || (tb.length === 1 && ta.startsWith(tb))));
        if (hasInitialOrToken) return true;
      }
    }
  }
  return false;
}

// ── Helper: Atualização de Fumo da Limpeza no Cadastro do Hóspede e Reservas Futuras ──
function updateSmokingStatusForCleaning(cleaningItem, isSmoker, userAuth, targetDate = null, dbInstance = null) {
  const currentDb = dbInstance || db;
  const now = new Date().toISOString();
  cleaningItem.smokedInRoom = Boolean(isSmoker);
  cleaningItem.guestSmoked = Boolean(isSmoker);
  if (isSmoker) {
    cleaningItem.smokedMarkedAt = now;
    cleaningItem.smokedMarkedBy = userAuth?.name || userAuth?.username || "Camareira";
  } else {
    delete cleaningItem.smokedMarkedAt;
    delete cleaningItem.smokedMarkedBy;
  }

  const effectiveDate = targetDate || cleaningItem.requestDate || cleaningItem.effectiveDate || getTodayStr();

  // Sincroniza quaisquer outros registros de limpeza do mesmo flat na mesma data
  for (const cr of (currentDb.cleaningRequests || [])) {
    if (!cr || cr.isInstructionOnly || cr.source === "manual_instruction" || cr.type === "instruction" || cr.type === "bed_adjustment_only") continue;
    if (
      (Number(cr.flatId) === Number(cleaningItem.flatId) || String(cr.flatNumber) === String(cleaningItem.flatNumber)) &&
      cr.requestDate === effectiveDate
    ) {
      cr.smokedInRoom = Boolean(isSmoker);
      cr.guestSmoked = Boolean(isSmoker);
      if (isSmoker) {
        cr.smokedMarkedAt = now;
        cr.smokedMarkedBy = userAuth?.name || userAuth?.username || "Camareira";
      } else {
        delete cr.smokedMarkedAt;
        delete cr.smokedMarkedBy;
      }
    }
  }

  const normalizeStr = (str) => {
    if (!str) return "";
    return String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();
  };

  const isStayover = Boolean(cleaningItem.source === "stayover" || cleaningItem.cleaningType === "stayover");
  const cleanGuestCandidate = isStayover
    ? (cleaningItem.currentGuest || cleaningItem.guestName || cleaningItem.leavingGuest)
    : (cleaningItem.leavingGuest || cleaningItem.currentGuest || cleaningItem.guestName);

  // 1. Identificar reserva correspondente à estadia (NUNCA usar autoReservationId/autoReservationCode em cards de checkout, pois pertencem ao hóspede que está ENTRANDO)
  let res = null;
  if (isStayover) {
    if (cleaningItem.reservationId) {
      res = (currentDb.reservations || []).find(r => String(r.id) === String(cleaningItem.reservationId) || r.code === cleaningItem.reservationId);
    }
    if (!res && cleaningItem.autoReservationId) {
      res = (currentDb.reservations || []).find(r => String(r.id) === String(cleaningItem.autoReservationId) || r.code === cleaningItem.autoReservationId);
    }
    if (!res && cleaningItem.reservationCode) {
      res = (currentDb.reservations || []).find(r => r.code === cleaningItem.reservationCode);
    }
    if (!res && cleaningItem.autoReservationCode) {
      res = (currentDb.reservations || []).find(r => r.code === cleaningItem.autoReservationCode);
    }
    if (!res) {
      res = (currentDb.reservations || []).find(r =>
        r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
        (Number(r.flatId) === Number(cleaningItem.flatId) || String(r.flatNumber) === String(cleaningItem.flatNumber)) &&
        r.checkinDate <= effectiveDate && r.checkoutDate >= effectiveDate
      );
    }
  } else {
    if (cleaningItem.checkoutReservationId) {
      res = (currentDb.reservations || []).find(r => String(r.id) === String(cleaningItem.checkoutReservationId) || r.code === cleaningItem.checkoutReservationId);
    }
    if (!res && cleaningItem.checkoutReservationCode) {
      res = (currentDb.reservations || []).find(r => r.code === cleaningItem.checkoutReservationCode);
    }
    if (!res && cleaningItem.reservationId) {
      const cand = (currentDb.reservations || []).find(r => String(r.id) === String(cleaningItem.reservationId) || r.code === cleaningItem.reservationId);
      if (cand && (!cleanGuestCandidate || !cand.guestName || isStrictSamePersonForSmoking(cand.guestName, cleanGuestCandidate, true))) {
        res = cand;
      }
    }
    if (!res && cleaningItem.reservationCode) {
      const cand = (currentDb.reservations || []).find(r => r.code === cleaningItem.reservationCode);
      if (cand && (!cleanGuestCandidate || !cand.guestName || isStrictSamePersonForSmoking(cand.guestName, cleanGuestCandidate, true))) {
        res = cand;
      }
    }
    if (!res) {
      const sameDayCheckouts = (currentDb.reservations || []).filter(r =>
        r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
        (Number(r.flatId) === Number(cleaningItem.flatId) || String(r.flatNumber) === String(cleaningItem.flatNumber)) &&
        (r.checkoutDate === effectiveDate || r.checkoutDate === cleaningItem.requestDate || r.earlyCheckoutDate === effectiveDate)
      );
      res = (cleanGuestCandidate && sameDayCheckouts.find(r => r.guestName && isStrictSamePersonForSmoking(r.guestName, cleanGuestCandidate, true))) || sameDayCheckouts[0] || null;
    }
    if (!res && cleanGuestCandidate) {
      res = (currentDb.reservations || []).find(r =>
        r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
        (Number(r.flatId) === Number(cleaningItem.flatId) || String(r.flatNumber) === String(cleaningItem.flatNumber)) &&
        (!r.checkinDate || r.checkinDate <= effectiveDate) &&
        r.guestName && isStrictSamePersonForSmoking(r.guestName, cleanGuestCandidate, false)
      ) || null;
    }
    // Blindagem: em card de checkout, nunca associar a uma reserva de outro hóspede (ex: hóspede fazendo check-in hoje no mesmo flat)
    if (res && cleanGuestCandidate && !isPlaceholderOrEmptyGuestName(cleanGuestCandidate) && res.guestName && !isPlaceholderOrEmptyGuestName(res.guestName)) {
      if (!isStrictSamePersonForSmoking(res.guestName, cleanGuestCandidate, true)) {
        res = null;
      }
    }
  }

  if (res) {
    res.smokedInRoom = Boolean(isSmoker);
    res.guestSmoked = Boolean(isSmoker);
    res.isSmoker = Boolean(isSmoker);
    res.smokerGuestAlert = Boolean(isSmoker);
    if (isSmoker) {
      res.smokingAlert = "Hóspede com histórico de fumo no quarto";
    } else {
      delete res.smokingAlert;
    }
    res.updatedAt = now;
  }

  const primarySmokerName = (!isStayover && cleanGuestCandidate && !isPlaceholderOrEmptyGuestName(cleanGuestCandidate))
    ? cleanGuestCandidate
    : (res?.guestName || cleanGuestCandidate || "");

  // 2. Identificar e atualizar cadastro do hóspede em currentDb.guests (com verificação estrita de identidade)
  if (!currentDb.guests) currentDb.guests = [];
  let guest = null;
  if (res?.guestId) {
    const cand = currentDb.guests.find(g => Number(g.id) === Number(res.guestId) || String(g.id) === String(res.guestId));
    if (cand && (!primarySmokerName || isStrictSamePersonForSmoking(primarySmokerName, cand.fullName || cand.name, true))) {
      guest = cand;
    }
  }
  if (!guest && (res?.guestDocument || res?.document)) {
    const docClean = String(res.guestDocument || res.document).replace(/\D/g, "");
    if (docClean.length >= 8) {
      const cand = currentDb.guests.find(g => (g.document && g.document.replace(/\D/g, "") === docClean) || (g.documentNumber && g.documentNumber.replace(/\D/g, "") === docClean));
      if (cand && (!primarySmokerName || isStrictSamePersonForSmoking(primarySmokerName, cand.fullName || cand.name, true))) {
        guest = cand;
      }
    }
  }
  if (!guest && primarySmokerName) {
    guest = currentDb.guests.find(g => isStrictSamePersonForSmoking(primarySmokerName, g.fullName || g.name, false));
  }
  if (!guest && (res?.guestPhone || res?.phone) && primarySmokerName) {
    const candPhone = res?.guestPhone || res?.phone;
    guest = currentDb.guests.find(g =>
      (phonesMatch(g.phone, candPhone) || phonesMatch(g.phoneNumber, candPhone)) &&
      isStrictSamePersonForSmoking(primarySmokerName, g.fullName || g.name, true)
    );
  }
  if (!guest && (res?.guestEmail || res?.email) && primarySmokerName) {
    const em = String(res.guestEmail || res.email).trim().toLowerCase();
    if (em.includes("@")) {
      guest = currentDb.guests.find(g =>
        g.email && String(g.email).trim().toLowerCase() === em &&
        isStrictSamePersonForSmoking(primarySmokerName, g.fullName || g.name, true)
      );
    }
  }

  // Se o cadastro não existe mas temos referência nominal válida de hóspede, cria o cadastro quando fumo é confirmado
  if (!guest && isSmoker && primarySmokerName && !isPlaceholderOrEmptyGuestName(primarySmokerName)) {
    const nextId = currentDb.guests.length > 0 ? Math.max(...currentDb.guests.map(g => Number(g.id) || 0)) + 1 : 1;
    guest = {
      id: nextId,
      guestCode: `HOSP-${String(nextId).padStart(5, "0")}`,
      name: primarySmokerName,
      fullName: primarySmokerName,
      document: res?.guestDocument || res?.document || "",
      documentNumber: res?.guestDocument || res?.document || "",
      phone: res?.guestPhone || res?.phone || "",
      email: res?.guestEmail || res?.email || "",
      tags: [],
      createdAt: now,
      updatedAt: now
    };
    currentDb.guests.push(guest);
    if (res) res.guestId = guest.id;
  }

  // 3. Atualizar reservas futuras exclusivamente deste mesmo hóspede (sem contaminar terceiros ou placeholders)
  const guestIds = new Set();
  if (guest?.id) guestIds.add(String(guest.id));
  if (res?.guestId) guestIds.add(String(res.guestId));

  const guestDocs = new Set();
  if (guest?.document) guestDocs.add(guest.document.replace(/\D/g, ""));
  if (guest?.documentNumber) guestDocs.add(guest.documentNumber.replace(/\D/g, ""));
  if (res?.guestDocument) guestDocs.add(res.guestDocument.replace(/\D/g, ""));
  if (res?.document) guestDocs.add(res.document.replace(/\D/g, ""));
  guestDocs.delete("");

  const rawGuestPhones = [];
  if (guest?.phone) rawGuestPhones.push(String(guest.phone));
  if (guest?.phoneNumber) rawGuestPhones.push(String(guest.phoneNumber));
  if (res?.guestPhone) rawGuestPhones.push(String(res.guestPhone));
  if (res?.phone) rawGuestPhones.push(String(res.phone));

  const cleanPhoneDigits = (p) => String(p || "").replace(/\D/g, "");
  const matchesAnyPhone = (candidatePhone) => {
    if (!candidatePhone) return false;
    const cleanCand = cleanPhoneDigits(candidatePhone);
    if (cleanCand.length < 8) return false;
    const candNorm = typeof normalizePhone === "function" ? normalizePhone(cleanCand) : cleanCand;
    for (const gp of rawGuestPhones) {
      if (typeof phonesMatch === "function" && phonesMatch(gp, candidatePhone)) return true;
      const cleanGp = cleanPhoneDigits(gp);
      if (cleanGp === cleanCand) return true;
      const gpNorm = typeof normalizePhone === "function" ? normalizePhone(cleanGp) : cleanGp;
      if (gpNorm && candNorm && gpNorm === candNorm) return true;
      if (cleanCand.slice(-8) === cleanGp.slice(-8)) return true;
    }
    return false;
  };

  const guestEmails = new Set();
  const cleanEmailStr = (e) => String(e || "").trim().toLowerCase();
  if (cleanEmailStr(guest?.email).includes("@")) guestEmails.add(cleanEmailStr(guest.email));
  if (cleanEmailStr(res?.guestEmail).includes("@")) guestEmails.add(cleanEmailStr(res.guestEmail));
  if (cleanEmailStr(res?.email).includes("@")) guestEmails.add(cleanEmailStr(res.email));

  const rawGuestNames = [];
  const pushValidSmokerName = (candidate) => {
    if (!candidate) return;
    if (primarySmokerName && !isStrictSamePersonForSmoking(primarySmokerName, candidate, true)) return;
    if (!rawGuestNames.includes(candidate)) rawGuestNames.push(candidate);
  };
  pushValidSmokerName(primarySmokerName);
  pushValidSmokerName(guest?.fullName);
  pushValidSmokerName(guest?.name);
  pushValidSmokerName(res?.guestName);
  pushValidSmokerName(cleanGuestCandidate);

  const matchesAnyNameStrict = (candidateName, allowInitial = false) => {
    if (!candidateName) return false;
    for (const gn of rawGuestNames) {
      if (isStrictSamePersonForSmoking(gn, candidateName, allowInitial)) {
        return true;
      }
    }
    return false;
  };

  const isMatchingGuest = (otherRes) => {
    if (!otherRes) return false;
    const doc = (otherRes.guestDocument || otherRes.document || otherRes.cpf || "").replace(/\D/g, "");
    if (doc.length >= 8 && guestDocs.has(doc)) {
      if (!otherRes.guestName || matchesAnyNameStrict(otherRes.guestName, true)) return true;
    }
    if (otherRes.guestId && guestIds.has(String(otherRes.guestId))) {
      if (!otherRes.guestName || matchesAnyNameStrict(otherRes.guestName, true)) return true;
    }
    if (matchesAnyPhone(otherRes.guestPhone || otherRes.phone)) {
      if (matchesAnyNameStrict(otherRes.guestName, true)) return true;
    }
    const email = cleanEmailStr(otherRes.guestEmail || otherRes.email);
    if (email.includes("@") && guestEmails.has(email)) {
      if (matchesAnyNameStrict(otherRes.guestName, true)) return true;
    }
    if (matchesAnyNameStrict(otherRes.guestName, false)) return true;

    if (Array.isArray(otherRes.guests)) {
      for (const g of otherRes.guests) {
        if (!g) continue;
        const gName = g.name || g.fullName || "";
        const gDoc = (g.cpf || g.document || "").replace(/\D/g, "");
        if (gDoc.length >= 8 && guestDocs.has(gDoc) && (!gName || matchesAnyNameStrict(gName, true))) return true;
        if (gName && matchesAnyNameStrict(gName, false)) return true;
      }
    }
    return false;
  };

  // Se a indicação de fumo está sendo desmarcada/revertida neste card, verifica se
  // existe outro apontamento ativo de fumo em outra limpeza de data distinta deste mesmo hóspede.
  const hasOtherSmokingReport = (currentDb.cleaningRequests || []).some(cr =>
    cr && String(cr.id) !== String(cleaningItem.id) &&
    !(
      (Number(cr.flatId) === Number(cleaningItem.flatId) || String(cr.flatNumber) === String(cleaningItem.flatNumber)) &&
      cr.requestDate === effectiveDate
    ) &&
    (cr.smokedInRoom === true || cr.guestSmoked === true) &&
    (
      (cr.leavingGuest && matchesAnyNameStrict(cr.leavingGuest, false)) ||
      (cr.checkoutReservationId && (currentDb.reservations || []).some(r => String(r.id) === String(cr.checkoutReservationId) && isMatchingGuest(r))) ||
      (cr.reservationId && (currentDb.reservations || []).some(r => String(r.id) === String(cr.reservationId) && isMatchingGuest(r)))
    )
  ) || (currentDb.reservations || []).some(r =>
    r && (!res || String(r.id) !== String(res.id)) &&
    r.checkoutDate < effectiveDate &&
    (r.smokedInRoom === true || r.guestSmoked === true) &&
    isMatchingGuest(r)
  );

  const targetSmokerState = Boolean(isSmoker || hasOtherSmokingReport);

  if (res && targetSmokerState && !isSmoker) {
    res.isSmoker = true;
    res.smokerGuestAlert = true;
    res.smokingAlert = "Hóspede com histórico de fumo no quarto";
  }

  if (guest) {
    if (!Array.isArray(guest.tags)) guest.tags = [];
    if (targetSmokerState) {
      guest.isSmoker = true;
      guest.smokedInRoom = true;
      if (!guest.smokingReportedAt) guest.smokingReportedAt = now;
      if (!guest.smokingReportedBy) guest.smokingReportedBy = userAuth?.name || userAuth?.username || "Camareira";
      if (!guest.tags.includes("Fumante")) {
        guest.tags.push("Fumante");
      }
    } else {
      guest.isSmoker = false;
      guest.smokedInRoom = false;
      guest.tags = guest.tags.filter(t => t.toLowerCase() !== "fumante");
      delete guest.smokingReportedAt;
      delete guest.smokingReportedBy;
    }
    guest.updatedAt = now;
  }

  for (const otherRes of (currentDb.reservations || [])) {
    if (res && String(otherRes.id) === String(res.id)) continue;
    if (!isMatchingGuest(otherRes)) continue;

    const isFuture = otherRes.checkinDate >= effectiveDate || otherRes.checkoutDate >= effectiveDate || (!otherRes.checkoutDone && otherRes.status !== "cancelada" && otherRes.status !== "cancelled" && otherRes.status !== "completed");

    if (isFuture || !targetSmokerState) {
      if (targetSmokerState) {
        otherRes.isSmoker = true;
        otherRes.smokerGuestAlert = true;
        otherRes.smokingAlert = "Hóspede com histórico de fumo no quarto";
      } else {
        otherRes.isSmoker = false;
        otherRes.smokerGuestAlert = false;
        otherRes.guestSmoked = false;
        otherRes.smokedInRoom = false;
        delete otherRes.smokingAlert;
      }
      otherRes.updatedAt = now;
    }
  }
}

// ── Cleaning Status Change & Execution ──────────────────────────────────────
app.patch("/api/cleaning/assignments/:requestId/status", async (req, res) => {
  const reqId = Number(req.params.requestId);
  const {
    status,
    observation,
    isVacant,
    executedPeriodicTaskIds = [],
    surveyAnswers = [],
    flatNumber,
    flatId,
    date,
    assignedUserId,
    completedAt: customCompletedAt,
    cleaningStartedAt: customStartedAt,
    effectiveDate: customEffectiveDate,
    durationMinutes: customDuration,
    markedByAdmin: bodyMarkedByAdmin,
    smokedInRoom,
    guestSmoked
  } = req.body;

  let item = findOrUpsertCleaningRequest(reqId, flatNumber, flatId, date);
  if (!item) return res.status(404).json({ error: "Solicitação não encontrada" });

  const userAuth = getAuthUser(req);
  const now = new Date().toISOString();
  const isStayover = Boolean(item.source === "stayover" || item.cleaningType === "stayover");
  const targetDate = item.requestDate || date || item.effectiveDate || getTodayStr();

  // Se for stayover, identifica a reserva B2B ativa no flat
  const stayoverActiveRes = isStayover ? (db.reservations || []).find(r =>
    r.id === item.reservationId ||
    r.id === item.autoReservationId ||
    (item.autoReservationCode && r.code === item.autoReservationCode) ||
    (
      r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
      r.status !== "no_show" && r.status !== "completed" && r.status !== "checked_out" &&
      !r.checkoutDone && !r.earlyCheckout &&
      (r.flatId === item.flatId || String(r.flatNumber) === String(item.flatNumber)) &&
      r.checkinDate < targetDate && r.checkoutDate > targetDate &&
      isB2bReservation(r)
    )
  ) : null;

  // Trava de Não Perturbe (DND) para camareiras
  if (isStayover && (stayoverActiveRes?.doNotDisturb || item.doNotDisturb) && (status === "cleaning_now" || status === "clean") && userAuth?.role !== "admin" && userAuth?.role !== "dev") {
    return res.status(422).json({
      error: "Não é possível iniciar ou concluir a limpeza. Hóspede ativou o modo Não Perturbe."
    });
  }

  // Trava de Serviço Externo em Andamento (liberado para Admin ou quando a OS permite limpeza simultânea)
  const activeService = getFlatServiceInProgress(item.flatId, item.flatNumber);
  const isCallerAdmin = Boolean((userAuth && (userAuth.role === "admin" || userAuth.role === "dev")) || bodyMarkedByAdmin);
  if (
    activeService &&
    !activeService.allowSimultaneousCleaning &&
    !isCallerAdmin &&
    (status === "will_clean" || status === "cleaning_now" || status === "clean")
  ) {
    return res.status(422).json({
      error: `Limpeza bloqueada: Serviço externo em andamento (${activeService.serviceTitle || "Manutenção"}). Aguarde a conclusão do prestador.`
    });
  }

  if (typeof isVacant === "boolean") {
    if (isStayover) {
      item.isVacant = false;
      const relatedFlat = db.flats.find(f => f.id === item.flatId || String(f.number) === String(item.flatNumber));
      if (relatedFlat) {
        relatedFlat.isOccupied = true;
        relatedFlat.updatedAt = now;
      }
    } else {
      item.isVacant = isVacant;
      item.isVacantExplicitlySet = true;
      item.vacantSource = (userAuth?.role === "admin" || userAuth?.role === "dev") ? "admin" : "manual_card";
      item.vacantSetAt = now;
      item.vacantSetBy = userAuth?.username || "card";

      const relatedFlat = db.flats.find(f => f.id === item.flatId || String(f.number) === String(item.flatNumber));
      if (relatedFlat) {
        relatedFlat.isOccupied = !isVacant;
        relatedFlat.updatedAt = now;
      }

      const todayRefVacant = getTodayStr();
      const checkoutRes = targetDate <= todayRefVacant ? (db.reservations || []).find(r =>
        r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
        r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
        (r.flatId === item.flatId || String(r.flatNumber) === String(item.flatNumber || relatedFlat?.number || "")) &&
        (r.checkoutDate <= todayRefVacant || r.earlyCheckoutDate <= todayRefVacant) &&
        (
          r.checkoutDate === targetDate ||
          r.checkoutDate === (date || todayRefVacant) ||
          r.earlyCheckoutDate === targetDate ||
          r.earlyCheckoutDate === (date || todayRefVacant)
        )
      ) : null;
      if (checkoutRes) {
        if (isVacant) {
          applyReservationCheckoutAndEarlyRelease(db, saveDatabase, checkoutRes, {
            source: "card_desocupado",
            actorName: userAuth?.name || userAuth?.username || "Camareira / Governança",
            nowIso: now,
            todayStr: targetDate
          }).catch(e => console.warn("[Cleaning Card Checkout Error]:", e?.message));
          cancelPendingStayRemindersForCheckout(db, null, {
            reservation: checkoutRes,
            flatId: item.flatId,
            flatNumber: item.flatNumber || relatedFlat?.number,
            reason: "Cancelado: card de limpeza marcado como desocupado"
          });
          triggerCheckoutWhatsApp(db, saveDatabase, checkoutRes, "card_desocupado").catch(e => {
            console.warn("[Cleaning Card Vacant Checkout Trigger Error]:", e.message);
          });
        } else {
          undoReservationCheckoutAndRestoreStay(db, checkoutRes, {
            actorUser: userAuth,
            source: "Governança / Card Ocupado",
            nowIso: now,
            todayStr: todayRefVacant
          });
        }
        checkoutRes.updatedAt = now;
      } else if (isVacant) {
        cancelPendingStayRemindersForCheckout(db, null, {
          flatId: item.flatId,
          flatNumber: item.flatNumber || relatedFlat?.number,
          reason: "Cancelado: card de limpeza marcado como desocupado"
        });
      }
    }
  }

  // Minimum time enforcement: 10 minutes minimum from cleaningStartedAt (bypassed for instructions / adjustments, stayovers and post-service cleanings/conferences)
  const isInstructionRequest = Boolean(item.isInstructionOnly || item.isBedAdjustmentOnly || item.type === "instruction" || item.type === "bed_adjustment_only" || item.source === "manual_instruction");
  const isServiceOrderCleaning = Boolean(item.source === "service_order" || item.cleaningType === "service_order" || item.type === "service_cleaning");
  if (status === "clean" && item.cleaningStartedAt && !customCompletedAt && !isInstructionRequest && !isStayover && !isServiceOrderCleaning) {
    const started = new Date(item.cleaningStartedAt).getTime();
    const elapsedMinutes = (Date.now() - started) / 60000;
    if (elapsedMinutes < 10 && userAuth?.role !== "admin" && userAuth?.role !== "dev") {
      return res.status(400).json({
        error: "Não é possível finalizar a limpeza ainda. Tempo insuficiente de higienização (mínimo de 10 minutos)."
      });
    }
  }

  // Captura snapshot do estado original ("dirty") antes de assumir ou finalizar a limpeza,
  // permitindo reversão exata ao clicar em "Devolver Quarto".
  if (status && (status === "will_clean" || status === "cleaning_now" || status === "clean" || status === "pending_issue")) {
    if (item.status === "dirty" || !item.preCleanSnapshot) {
      capturePreCleanSnapshot(item, targetDate);
    }
    delete item.revertedToDirtyAt;
    delete item.revertedBy;
  }

  // Regra de Negócio: Sempre que um card de CHECKOUT for marcado como limpeza iniciada (ou concluída),
  // considera-se automaticamente como desocupado e check-out realizado caso ainda não esteja.
  // Em STAYOVER ou LIMPEZA/CONFERÊNCIA PÓS-SERVIÇO, NÃO realiza check-out automático de reserva ativa!
  if (!isInstructionRequest && !isStayover && !isServiceOrderCleaning && (status === "cleaning_now" || status === "in_progress" || status === "clean")) {
    const autoSource = status === "clean" ? "cleaning_completed" : "cleaning_started";
    if (!item.isVacant || !item.isVacantExplicitlySet) {
      item.isVacant = true;
      item.isVacantExplicitlySet = true;
      item.vacantSource = item.vacantSource || autoSource;
      item.vacantSetAt = item.vacantSetAt || now;
      item.vacantSetBy = item.vacantSetBy || (userAuth?.username || autoSource);
    }

    const relatedFlat = db.flats.find(f => f.id === item.flatId || String(f.number) === String(item.flatNumber));
    if (relatedFlat) {
      relatedFlat.isOccupied = false;
      relatedFlat.updatedAt = now;
    }

    const todayRefClean = getTodayStr();
    const checkoutRes = targetDate <= todayRefClean ? (db.reservations || []).find(r =>
      r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
      r.status !== "expirada" && r.status !== "pre_reserva" && r.status !== "pendente" && r.status !== "no_show" &&
      (r.flatId === item.flatId || String(r.flatNumber) === String(item.flatNumber || relatedFlat?.number || "")) &&
      r.checkoutDate <= todayRefClean &&
      (r.checkoutDate === targetDate || r.checkoutDate === (date || todayRefClean))
    ) : null;
    if (checkoutRes) {
      checkoutRes.checkoutDone = true;
      if (checkoutRes.status !== "completed" && checkoutRes.status !== "checked_out") {
        checkoutRes.previousStatus = checkoutRes.status;
        checkoutRes.status = "completed";
      }
      if (!checkoutRes.actualCheckoutAt) checkoutRes.actualCheckoutAt = now;
      checkoutRes.checkoutMethod = checkoutRes.checkoutMethod || item.vacantSource || autoSource;
      checkoutRes.updatedAt = now;
      cancelPendingStayRemindersForCheckout(db, null, {
        reservation: checkoutRes,
        flatId: item.flatId,
        flatNumber: item.flatNumber || relatedFlat?.number,
        reason: `Cancelado: card de limpeza marcado como ${status === "clean" ? "limpo" : "limpeza iniciada"}`
      });
      triggerCheckoutWhatsApp(db, saveDatabase, checkoutRes, autoSource).catch(e => {
        console.warn("[Cleaning Started Checkout Trigger Error]:", e.message);
      });
    } else {
      cancelPendingStayRemindersForCheckout(db, null, {
        flatId: item.flatId,
        flatNumber: item.flatNumber || relatedFlat?.number,
        reason: `Cancelado: card de limpeza marcado como ${status === "clean" ? "limpo" : "limpeza iniciada"}`
      });
    }
  } else if (isStayover) {
    item.isVacant = false;
    const relatedFlat = db.flats.find(f => f.id === item.flatId || String(f.number) === String(item.flatNumber));
    if (relatedFlat) {
      relatedFlat.isOccupied = true;
      relatedFlat.updatedAt = now;
    }
  }

  if (assignedUserId) {
    const targetUser = db.users.find(u => u.id === Number(assignedUserId));
    if (targetUser) {
      item.assignedUserId = targetUser.id;
    }
  }

  if (status) {
    const previousStatus = item.status;
    item.status = status;
    if (status === "dirty") {
      revertCleaningRequestToDirty(item, {
        date: targetDate,
        userAuth,
        now,
        explicitIsVacant: typeof isVacant === "boolean" ? isVacant : undefined,
      });
    } else if (status === "will_clean") {
      item.effectiveDate = customEffectiveDate || item.effectiveDate || date || getTodayStr();
      if (assignedUserId) {
        item.assignedUserId = Number(assignedUserId);
      } else {
        item.assignedUserId = userAuth ? userAuth.id : 2;
      }
      const assignedU = db.users.find(u => u.id === item.assignedUserId);
      if (assignedU) {
        item.assignedUsername = assignedU.username;
        item.assignedUserName = assignedU.name || assignedU.username;
      }
      item.willCleanAt = now;
    } else if (status === "cleaning_now") {
      item.effectiveDate = customEffectiveDate || item.effectiveDate || date || getTodayStr();
      item.cleaningStartedAt = customStartedAt || now;
      if (assignedUserId) {
        item.assignedUserId = Number(assignedUserId);
      } else if (!item.assignedUserId) {
        item.assignedUserId = userAuth ? userAuth.id : 2;
      }
      const assignedU = db.users.find(u => u.id === item.assignedUserId);
      if (assignedU) {
        item.assignedUsername = assignedU.username;
        item.assignedUserName = assignedU.name || assignedU.username;
      }
    } else if (status === "clean" || status === "pending_issue") {
      item.completedAt = customCompletedAt || item.completedAt || now;
      if (customStartedAt) item.cleaningStartedAt = customStartedAt;
      item.effectiveDate = customEffectiveDate || date || getExecutionDateStr(item.completedAt);
      if (assignedUserId) {
        item.assignedUserId = Number(assignedUserId);
      } else if (!item.assignedUserId) {
        item.assignedUserId = userAuth ? userAuth.id : 2;
      }
      const assignedU = db.users.find(u => u.id === item.assignedUserId);
      if (assignedU) {
        item.assignedUsername = assignedU.username;
        item.assignedUserName = assignedU.name || assignedU.username;
      }
      item.pendingObservation = status === "pending_issue" ? (observation || "Pendência registrada") : null;

      if (status === "clean") {
        item.isPriority = false;
        delete item.priorityReason;
        if (stayoverActiveRes && stayoverActiveRes.isPriority) {
          stayoverActiveRes.isPriority = false;
          delete stayoverActiveRes.priorityReason;
        }
        for (const r of (db.reservations || [])) {
          if (
            (Number(r.flatId) === Number(item.flatId) || String(r.flatNumber) === String(item.flatNumber)) &&
            (r.checkoutDate === targetDate || r.checkinDate === targetDate || (r.checkinDate <= targetDate && r.checkoutDate >= targetDate)) &&
            r.isPriority
          ) {
            r.isPriority = false;
            delete r.priorityReason;
          }
        }

        const isAdmin = Boolean((userAuth && (userAuth.role === "admin" || userAuth.role === "dev")) || bodyMarkedByAdmin);
        if (isAdmin) {
          item.markedByAdmin = true;
        }
        if (!item.completedAt) {
          item.completedAt = customCompletedAt || now;
        }
        if (item.adminNote && item.adminNote.includes("Limpeza de check-out gerada automaticamente")) {
          item.adminNote = null;
        }

        if (typeof req.body.towelsChanged === "boolean") {
          item.towelsChanged = Boolean(req.body.towelsChanged);
        }
        if (typeof req.body.beddingChanged === "boolean") {
          item.beddingChanged = Boolean(req.body.beddingChanged);
        }

        if (typeof req.body.smokedInRoom === "boolean" || typeof req.body.guestSmoked === "boolean" || typeof smokedInRoom === "boolean" || typeof guestSmoked === "boolean") {
          const smokedVal = Boolean(req.body.smokedInRoom ?? req.body.guestSmoked ?? smokedInRoom ?? guestSmoked);
          updateSmokingStatusForCleaning(item, smokedVal, userAuth, targetDate);
        }

        if (isStayover) {
          const execDate = item.requestDate || date || getTodayStr();
          const targetRes = stayoverActiveRes || (db.reservations || []).find(r =>
            r.id === item.reservationId ||
            r.id === item.autoReservationId ||
            (
              r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" &&
              r.status !== "no_show" && r.status !== "completed" && r.status !== "checked_out" &&
              !r.checkoutDone && !r.earlyCheckout &&
              (r.flatId === item.flatId || String(r.flatNumber) === String(item.flatNumber)) &&
              r.checkinDate < execDate && r.checkoutDate > execDate &&
              isB2bReservation(r)
            )
          );

          if (targetRes) {
            if (item.beddingChanged) {
              targetRes.lastBeddingChangeDate = execDate;
            }
            if (item.towelsChanged) {
              targetRes.lastTowelsChangeDate = execDate;
            }

            if (!Array.isArray(targetRes.linenChangeHistory)) {
              targetRes.linenChangeHistory = Array.isArray(targetRes.linenChanges) ? [...targetRes.linenChanges] : [];
            }
            targetRes.linenChangeHistory.push({
              cleaningRequestId: item.id,
              date: execDate,
              beddingChanged: Boolean(item.beddingChanged),
              towelsChanged: Boolean(item.towelsChanged),
              performedByUserId: item.assignedUserId || userAuth?.id || 2,
              performedByName: userAuth ? (userAuth.name || userAuth.username) : "Camareira",
              createdAt: now
            });
            targetRes.linenChanges = targetRes.linenChangeHistory;
            targetRes.updatedAt = now;
          }
        }
      }

      if (customDuration !== undefined) {
        item.durationMinutes = Number(customDuration);
      } else if (status === "clean") {
        if (item.cleaningStartedAt && item.completedAt) {
          const startMs = new Date(item.cleaningStartedAt).getTime();
          const endMs = new Date(item.completedAt).getTime();
          if (endMs > startMs) {
            item.durationMinutes = Math.max(1, Math.round((endMs - startMs) / 60000));
          }
        } else if (!item.durationMinutes) {
          item.durationMinutes = 35;
        }
      }

      if (status === "pending_issue") {
        const flatObj = db.flats.find(f => f.id === item.flatId);
        const fNum = flatObj ? flatObj.number : (item.flatNumber || String(item.flatId));
        createNotification({
          category: "defect",
          title: `⚠️ Pendência / Defeito no Apt ${fNum}`,
          message: observation ? `Observação: "${observation}"` : "Camareira registrou uma pendência ou defeito no quarto.",
          severity: "warning",
          metadata: { flatId: item.flatId, flatNumber: fNum, observation },
          targetUrl: "/dashboard"
        });
      }

      let tasksToExecute = Array.isArray(executedPeriodicTaskIds) ? [...executedPeriodicTaskIds] : [];
      if (status === "clean" && tasksToExecute.length === 0 && !isInstructionRequest) {
        // Auto-conclui tarefas preventivas pendentes deste quarto para governança caso não passadas explicitamente
        const flatTargetId = Number(item.flatId);
        const flatObj = db.flats.find(f => Number(f.id) === flatTargetId) || { id: flatTargetId, flatId: flatTargetId, number: item.flatNumber };
        const pendingForFlat = (db.periodicTasks || []).filter(t =>
          t.isActive &&
          t.assignToHousekeeping !== false &&
          (!Array.isArray(t.flatIds) || t.flatIds.length === 0 || t.flatIds.map(Number).includes(flatTargetId))
        );
        for (const pt of pendingForFlat) {
          const taskStatus = computePeriodicTaskStatus(pt, flatObj, date || item.requestDate || getTodayStr());
          if (taskStatus.isDue) {
            tasksToExecute.push(pt.id);
          }
        }
      }

      for (const ptId of tasksToExecute) {
        if (!db.periodicExecutions) db.periodicExecutions = [];
        db.periodicExecutions.push({
          id: db.periodicExecutions.length > 0 ? Math.max(...db.periodicExecutions.map(e => e.id)) + 1 : 1,
          periodicTaskId: Number(ptId),
          flatId: Number(item.flatId),
          cleaningRequestId: item.id,
          executedByUserId: item.assignedUserId ? Number(item.assignedUserId) : (userAuth ? Number(userAuth.id) : 2),
          executedAt: now,
          notes: "Executado durante a limpeza do checkout",
          createdAt: now,
        });
      }

      for (const ans of surveyAnswers) {
        const survey = (db.surveys || []).find(s => s.id === Number(ans.surveyId));
        if (survey) {
          if (!Array.isArray(survey.responses)) survey.responses = [];
          const flat = db.flats.find(f => f.id === item.flatId);

          let parsedAnswers = [];
          if (Array.isArray(ans.answers)) {
            for (const a of ans.answers) {
              let photoUrl = a.photoUrl || null;
              if (a.type === "photo" && a.photoBase64) {
                try {
                  photoUrl = await uploadImageToStorage(a.photoBase64, `survey_flat${item.flatId}_${a.questionId}`, db, "surveys");
                } catch (err) {
                  console.warn("Falha upload foto vistoria, salvando base64:", err.message);
                  photoUrl = a.photoBase64;
                }
              }
              parsedAnswers.push({
                questionId: a.questionId,
                questionText: a.questionText || "",
                type: a.type || "text",
                answer: a.answer ?? "",
                photoUrl: photoUrl || null
              });
            }
          } else {
            // Compatibilidade retroativa
            parsedAnswers.push({
              questionId: "q_legacy",
              questionText: survey.question || survey.title,
              type: survey.type || "yes_no",
              answer: ans.answer || "Sim",
              notes: ans.notes || null
            });
          }

          const existingRespIdx = survey.responses.findIndex(r => Number(r.flatId) === Number(item.flatId));
          const respObj = {
            id: `resp_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
            flatId: item.flatId,
            flatNumber: flat ? flat.number : String(item.flatId),
            cleaningRequestId: item.id,
            answeredByUserId: item.assignedUserId || (userAuth ? userAuth.id : 2),
            answeredByUsername: userAuth ? (userAuth.name || userAuth.username) : "Camareira",
            answeredAt: now,
            answers: parsedAnswers
          };

          if (existingRespIdx >= 0) {
            survey.responses[existingRespIdx] = respObj;
          } else {
            survey.responses.push(respObj);
          }
        }
      }
    }
  }
  item.updatedAt = now;
  if (typeof invalidateRequestsForDateCache === "function") invalidateRequestsForDateCache();
  saveDatabase();

  const flat = db.flats.find(f => f.id === item.flatId);
  const assignedUser = db.users.find(u => u.id === item.assignedUserId);

  logAuditEvent({
    level: "info",
    category: "cleaning",
    action: (userAuth?.role === "admin" || userAuth?.role === "dev") && status === "clean" && assignedUserId
      ? "CLEANING_COMPLETED_BY_ADMIN_FOR_MAID"
      : `CLEANING_STATUS_${(status || "UPDATED").toUpperCase()}`,
    actor: { name: userAuth ? (userAuth.name || userAuth.username) : "Sistema", role: userAuth?.role || "admin" },
    details: {
      requestId: item.id,
      flatNumber: flat ? flat.number : (item.flatNumber || String(item.flatId)),
      requestDate: targetDate,
      status: item.status,
      assignedUserId: item.assignedUserId,
      assignedMaidName: assignedUser ? (assignedUser.name || assignedUser.username) : (status === "dirty" ? null : "Camareira"),
      markedByAdmin: userAuth?.role === "admin" || userAuth?.role === "dev",
      ...(status === "dirty" ? { revertedToDirtyAt: now } : {}),
    },
    source: "cleaning_dashboard"
  });

  // ── WhatsApp: Notificar hóspedes que chegam hoje neste flat ─────────────────
  if (status === "clean" && !isStayover) {
    const flatNum = flat ? flat.number : (item.flatNumber || String(item.flatId));
    const reqBaseUrl = `${req.protocol}://${req.get("host")}`;
    triggerRoomReadyWhatsApp(db, saveDatabase, item.flatId, flatNum, reqBaseUrl).catch(e =>
      console.warn("[Room Ready WhatsApp] Erro ao notificar:", e.message)
    );
  }

  // ── Sincronização Reativa do Extrato da Camareira ───────────────────────────
  if (status === "clean" && item.assignedUserId) {
    syncMaidCredits(item.assignedUserId);
  } else if (status && status !== "clean") {
    if (Array.isArray(db.maidStatementEntries)) {
      db.maidStatementEntries = db.maidStatementEntries.filter(
        e => !(e.cleaningRequestId === item.id && e.entryDate >= "2026-09-01")
      );
      saveDatabase();
    }
  }

  // ── WhatsApp Prestador: Notificar se algum flat de OS ativa ficou disponível ─
  checkAndNotifyAvailableServiceFlats();

  res.json({
    ...item,
    flatNumber: flat ? flat.number : String(item.flatId),
    assignedUsername: assignedUser ? assignedUser.username : null,
    assignedUserName: assignedUser ? (assignedUser.name || assignedUser.username) : null,
  });
});

// ── Alternar / Atualizar Apontamento de Fumo no Quarto ──────────────────────
app.patch("/api/cleaning/assignments/:requestId/smoking", async (req, res) => {
  const reqId = Number(req.params.requestId);
  const { smokedInRoom, guestSmoked, flatNumber, flatId, date } = req.body;
  const isSmoker = Boolean(smokedInRoom ?? guestSmoked);

  let item = findOrUpsertCleaningRequest(reqId, flatNumber, flatId, date);
  if (!item) return res.status(404).json({ error: "Solicitação não encontrada" });

  const userAuth = getAuthUser(req);
  const targetDate = item.requestDate || date || item.effectiveDate || getTodayStr();

  updateSmokingStatusForCleaning(item, isSmoker, userAuth, targetDate);

  if (typeof invalidateRequestsForDateCache === "function") invalidateRequestsForDateCache();
  saveDatabase();

  const flat = db.flats.find(f => f.id === item.flatId);
  const assignedUser = db.users.find(u => u.id === item.assignedUserId);

  logAuditEvent({
    level: "info",
    category: "cleaning",
    action: isSmoker ? "CLEANING_MARKED_SMOKER" : "CLEANING_UNMARKED_SMOKER",
    actor: { name: userAuth ? (userAuth.name || userAuth.username) : "Sistema", role: userAuth?.role || "camareira" },
    details: {
      requestId: item.id,
      flatNumber: flat ? flat.number : (item.flatNumber || String(item.flatId)),
      smokedInRoom: item.smokedInRoom
    },
    source: "cleaning_dashboard"
  });

  res.json({
    ...item,
    flatNumber: flat ? flat.number : String(item.flatId),
    assignedUsername: assignedUser ? assignedUser.username : null,
    assignedUserName: assignedUser ? (assignedUser.name || assignedUser.username) : null,
  });
});

app.post("/api/cleaning/assignments/batch-claim", (req, res) => {
  const { requestIds = [] } = req.body;
  const userAuth = getAuthUser(req);
  const isAdminUser = userAuth?.role === "admin" || userAuth?.role === "dev";
  const now = new Date().toISOString();
  let claimed = 0;

  const todayStr = getTodayStr();
  for (const id of requestIds) {
    const item = findOrUpsertCleaningRequest(id, null, null, todayStr);
    if (item && (item.status === "dirty" || !item.status)) {
      const activeService = getFlatServiceInProgress(item.flatId, item.flatNumber);
      if (activeService && !activeService.allowSimultaneousCleaning && !isAdminUser) {
        continue;
      }
      item.status = "will_clean";
      item.assignedUserId = userAuth ? userAuth.id : 2;
      const assignedU = db.users.find(u => u.id === item.assignedUserId);
      if (assignedU) {
        item.assignedUsername = assignedU.username;
        item.assignedUserName = assignedU.name || assignedU.username;
      }
      item.willCleanAt = now;
      item.updatedAt = now;
      claimed++;
    }
  }
  saveDatabase();
  res.json({ claimed, total: requestIds.length });
});

app.get("/api/cleaning/history", (req, res) => {
  const userAuth = getAuthUser(req);
  const startDate = req.query.startDate || "2000-01-01";
  const endDate = req.query.endDate || "2099-12-31";

  let list = db.cleaningRequests.filter(r => {
    if (r.status !== "clean") return false;
    const effectiveDate = r.effectiveDate || (r.completedAt ? getExecutionDateStr(r.completedAt) : r.requestDate);
    if (effectiveDate < "2026-09-01") return false;
    if (effectiveDate < startDate || effectiveDate > endDate) return false;
    if (userAuth?.role === "camareira" && r.assignedUserId !== userAuth.id) return false;
    return true;
  });

  const result = list.map(r => {
    const flat = db.flats.find(f => f.id === r.flatId);
    const assignedUser = db.users.find(u => u.id === r.assignedUserId);

    let durationMinutes = r.durationMinutes || 35;
    if (!r.durationMinutes && r.cleaningStartedAt && r.completedAt) {
      const startMs = new Date(r.cleaningStartedAt).getTime();
      const endMs = new Date(r.completedAt).getTime();
      if (endMs > startMs) {
        durationMinutes = Math.max(1, Math.round((endMs - startMs) / 60000));
      }
    }

    const effDate = r.effectiveDate || (r.completedAt ? getExecutionDateStr(r.completedAt) : r.requestDate);

    return {
      id: r.id,
      flatId: r.flatId,
      flatNumber: flat ? flat.number : (r.flatNumber || String(r.flatId)),
      requestDate: r.requestDate,
      effectiveDate: effDate,
      executionDate: effDate,
      status: r.status,
      isPriority: r.isPriority || false,
      source: r.source || "checkout",
      assignedUserId: r.assignedUserId,
      assignedUsername: assignedUser ? assignedUser.username : (r.assignedUsername || "Camareira"),
      pendingObservation: r.pendingObservation || r.adminNote || null,
      cleaningStartedAt: r.cleaningStartedAt,
      completedAt: r.completedAt,
      durationMinutes: r.durationMinutes || durationMinutes,
      addedBy: r.addedBy || null,
      addedAt: r.addedAt || null,
      adminNote: r.adminNote || null,
      leavingGuest: r.leavingGuest || null,
      createdAt: r.createdAt,
    };
  });

  // Ordena do mais recente para o mais antigo
  result.sort((a, b) => {
    const timeA = new Date(a.completedAt || a.requestDate).getTime();
    const timeB = new Date(b.completedAt || b.requestDate).getTime();
    return timeB - timeA;
  });

  res.json(result);
});

// ── Admin Housekeeping Report Management (Add/Remove records with Audit) ────
app.post("/api/cleaning/admin/record", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) {
    return res.status(403).json({ error: "Apenas administradores podem adicionar diárias de limpeza." });
  }

  const { flatNumber, flatId, requestDate, assignedUserId, status = "clean", durationMinutes = 35, adminNote = "", observation = "" } = req.body || {};
  if (!requestDate) {
    return res.status(400).json({ error: "A data da limpeza é obrigatória." });
  }

  const targetFlat = db.flats.find(f => (flatNumber && String(f.number) === String(flatNumber)) || (flatId && f.id === Number(flatId)));
  const finalFlatNumber = targetFlat ? String(targetFlat.number) : String(flatNumber || "101");
  const finalFlatId = targetFlat ? targetFlat.id : Number(flatId || 1);
  const targetUser = assignedUserId ? db.users.find(u => u.id === Number(assignedUserId)) : null;

  if (!db.cleaningRequests) db.cleaningRequests = [];
  const maxId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) : 0;
  const nowIso = new Date().toISOString();
  const completedTimeIso = status === "clean" ? `${requestDate}T18:00:00.000Z` : null;

  const newReq = {
    id: maxId + 1,
    flatId: finalFlatId,
    flatNumber: finalFlatNumber,
    requestDate: requestDate,
    source: "admin_manual",
    status: status || "clean",
    assignedUserId: targetUser ? targetUser.id : (assignedUserId ? Number(assignedUserId) : null),
    assignedUsername: targetUser ? targetUser.username : null,
    assignedUserName: targetUser ? targetUser.username : null,
    isVacant: true,
    isPriority: false,
    markedByAdmin: true,
    adminNote: adminNote || observation || "Lançamento manual pelo ADM",
    pendingObservation: observation || adminNote || null,
    durationMinutes: Number(durationMinutes) || 35,
    cleaningStartedAt: status === "clean" ? `${requestDate}T17:15:00.000Z` : null,
    completedAt: completedTimeIso,
    addedBy: userAuth.username || "admin",
    addedAt: nowIso,
    createdAt: nowIso,
    updatedAt: nowIso
  };

  db.cleaningRequests.unshift(newReq);
  saveDatabase();

  logAuditEvent({
    level: "info",
    category: "cleaning",
    action: "CLEANING_RECORD_ADDED_BY_ADMIN",
    actor: { name: userAuth.username || "admin", role: "admin" },
    details: {
      requestId: newReq.id,
      flatNumber: finalFlatNumber,
      requestDate,
      assignedMaidName: targetUser ? targetUser.username : "Sem camareira",
      addedBy: userAuth.username || "admin",
      addedAt: nowIso
    }
  });

  res.status(201).json({ success: true, message: "Diária de limpeza adicionada com sucesso!", record: newReq });
});

