// GET /api/service-orders — Lista todas as ordens de serviço (Admin)
app.get("/api/service-orders", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth) return res.status(401).json({ error: "Não autenticado." });
  if (userAuth.role !== "admin" && userAuth.role !== "dev") return res.status(403).json({ error: "Acesso negado." });

  if (ensureServiceCatalogAndReconcileOrders()) {
    saveDatabase("auto_reconcile_service_catalog");
  }

  const list = [...db.serviceOrders].sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime()).map(o => {
    const worker = (db.serviceWorkers || []).find(w => w.token === o.token || w.serviceOrderId === o.id);
    const catalogItem = o.serviceTypeId ? (db.serviceCatalog || []).find(c => c.id === o.serviceTypeId) : inferServiceTypeFromText(o.title);
    return {
      ...o,
      serviceTypeId: o.serviceTypeId || catalogItem?.id || null,
      serviceTypeName: o.serviceTypeName || catalogItem?.name || o.title,
      serviceCategory: catalogItem?.categoryLabel || "Serviço Geral",
      allowedRoomStatuses: getAllowedRoomStatuses(o),
      allowSimultaneousCleaning: Boolean(o.allowSimultaneousCleaning),
      workerName: worker?.mainWorker?.name || o.workerName || null,
      workerCpf: worker?.mainWorker?.cpf || o.workerCpf || null,
      workerPhone: worker?.mainWorker?.phone || o.workerPhone || null,
      workerCollaborators: Array.isArray(worker?.collaborators) ? worker.collaborators : [],
      workerVehicle: worker?.vehicle || null
    };
  });
  res.json(list);
});

// Calcula o período ativo de bloqueio de um apartamento com serviço em andamento (in_progress).
// Enquanto o serviço não for finalizado, o bloqueio permanece estendido pelo menos até a data atual (todayStr).
function getActiveServiceFlatBlockRange(oflat, todayStr = getTodayStr()) {
  if (!oflat || oflat.status !== "in_progress") return null;
  const startDate = oflat.customBlockStartDate || (oflat.startedAt ? getExecutionDateStr(oflat.startedAt) : todayStr);
  const estDate = oflat.customBlockEndDate || (oflat.estimatedFinishAt ? getExecutionDateStr(oflat.estimatedFinishAt) : startDate);
  const endDate = oflat.customBlockEndDate
    ? (oflat.customBlockEndDate >= startDate ? oflat.customBlockEndDate : startDate)
    : ([startDate, estDate, todayStr].filter(Boolean).sort().pop() || todayStr);
  return {
    startDate,
    endDate,
    isExtendedPastEstimate: Boolean(estDate && todayStr > estDate && !oflat.customBlockEndDate)
  };
}

// Sincroniza bloqueios de inventário (db.roomBlocks) quando uma OS interdita apartamentos
function syncServiceOrderRoomBlocks(order, isDeleted = false, targetDb = db) {
  if (!order || !order.id || !targetDb) return;
  if (!Array.isArray(targetDb.roomBlocks)) targetDb.roomBlocks = [];
  targetDb.roomBlocks = targetDb.roomBlocks.filter(b => b.serviceOrderId !== order.id);

  if (isDeleted || order.status !== "active" || (!order.blockFlats && !order.interdictFlats)) {
    return;
  }

  const todayStr = getTodayStr();
  const baseStartDate = order.blockStartDate || todayStr;
  const baseEndDate = order.blockEndDate || getOffsetDateStr(1);

  for (const f of (order.flats || [])) {
    if (f.status === "done" || (f.status === "pending" && f.returnedAt)) continue;
    const flatStartDate = f.startedAt ? getExecutionDateStr(f.startedAt) : baseStartDate;
    const startDate = f.customBlockStartDate || (flatStartDate < baseStartDate ? flatStartDate : baseStartDate);
    const estEndDate = f.customBlockEndDate || (f.estimatedFinishAt ? getExecutionDateStr(f.estimatedFinishAt) : baseEndDate);
    const endDate = f.customBlockEndDate
      ? (f.customBlockEndDate >= startDate ? f.customBlockEndDate : startDate)
      : (f.status === "in_progress"
        ? [startDate, baseEndDate, estEndDate, todayStr].filter(Boolean).sort().pop()
        : (baseEndDate >= todayStr ? baseEndDate : todayStr));
    const nextBlockId = targetDb.roomBlocks.length > 0 ? Math.max(...targetDb.roomBlocks.map(b => Number(b.id) || 0)) + 1 : 1;
    targetDb.roomBlocks.push({
      id: nextBlockId,
      flatId: Number(f.flatId),
      flatNumber: String(f.flatNumber),
      startDate,
      endDate,
      reason: `OS Manutenção: ${order.title}`,
      serviceOrderId: order.id,
      createdAt: new Date().toISOString()
    });
  }
}

// POST /api/service-orders — Cria nova ordem de serviço (Admin)
app.post("/api/service-orders", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth) return res.status(401).json({ error: "Não autenticado." });
  if (userAuth.role !== "admin" && userAuth.role !== "dev") return res.status(403).json({ error: "Acesso negado." });

  const {
    title,
    cleanFlatMode: rawCleanFlatMode,
    allowedRoomStatuses: rawAllowedStatuses,
    maxSimultaneousFlats = 2,
    maxFlatsPerDay = 4,
    requirePhotos = true,
    estimatedDurationHours = null,
    instructionFormat = "text",
    flats = [],
    defaultInstructions = "",
    notificationRecipients = [],
    blockFlats = false,
    interdictFlats = false,
    blockStartDate = null,
    blockEndDate = null
  } = req.body || {};

  if (!title || !String(title).trim()) {
    return res.status(400).json({ error: "Título do serviço é obrigatório." });
  }

  // Token único com 24 caracteres hexadecimais
  const token = crypto.randomBytes(12).toString("hex");

  const formattedFlats = (Array.isArray(flats) ? flats : []).map(f => {
    let flatId, flatNumber, instructions;
    if (typeof f === "object" && f !== null) {
      flatId = Number(f.flatId || f.id);
      flatNumber = f.flatNumber || f.number;
      instructions = f.instructions !== undefined ? String(f.instructions).trim() : String(defaultInstructions || "").trim();
    } else {
      flatId = Number(f);
      instructions = String(defaultInstructions || "").trim();
    }
    const foundFlat = (db.flats || []).find(fl => fl.id === flatId || String(fl.number) === String(flatNumber));
    return {
      flatId: foundFlat ? foundFlat.id : flatId,
      flatNumber: foundFlat ? foundFlat.number : String(flatNumber || flatId),
      instructions,
      status: "pending",
      startedAt: null,
      finishedAt: null,
      workerName: null,
      workerCpf: null,
      estimatedFinishAt: null,
      observations: null,
      photos: [],
      needsCleaning: null,
      wasCleanWhenStarted: null,
      workerNotifiedAvailable: false,
      workerNotifiedAvailableAt: null
    };
  });

  const allowedRoomStatuses = Array.isArray(rawAllowedStatuses)
    ? rawAllowedStatuses.filter(s => VALID_ROOM_STATUSES.includes(s))
    : [...DEFAULT_ALLOWED_ROOM_STATUSES];

  const cleanFlatMode = ["never", "priority", "always"].includes(rawCleanFlatMode)
    ? rawCleanFlatMode
    : (Array.isArray(rawAllowedStatuses) ? "always" : "priority");

  ensureServiceCatalogAndReconcileOrders();
  const requestedServiceTypeId = req.body?.serviceTypeId ? String(req.body.serviceTypeId).trim() : null;
  const matchedCatalog = requestedServiceTypeId
    ? (db.serviceCatalog || []).find(c => c.id === requestedServiceTypeId)
    : inferServiceTypeFromText(title);

  const newOrder = {
    id: `so_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
    title: String(title).trim(),
    serviceTypeId: matchedCatalog ? matchedCatalog.id : (requestedServiceTypeId || null),
    serviceTypeName: matchedCatalog ? matchedCatalog.name : String(title).trim(),
    token,
    status: req.body.status || "active",
    createdAt: new Date().toISOString(),
    createdBy: userAuth.name || userAuth.username || "admin",
    cleanFlatMode,
    allowedRoomStatuses,
    allowSimultaneousCleaning: Boolean(
      req.body?.allowSimultaneousCleaning ??
      req.body?.allowCleaningDuringService ??
      (req.body?.blockCleaningDuringService !== undefined ? !req.body.blockCleaningDuringService : false)
    ),
    maxSimultaneousFlats: Math.max(1, parseInt(maxSimultaneousFlats, 10) || 2),
    maxFlatsPerDay: Math.max(1, parseInt(maxFlatsPerDay, 10) || 4),
    requirePhotos: typeof requirePhotos === "boolean" ? requirePhotos : true,
    estimatedDurationHours: estimatedDurationHours ? Number(estimatedDurationHours) : null,
    instructionFormat: instructionFormat === "list" ? "list" : "text",
    notificationRecipients: Array.isArray(notificationRecipients) ? notificationRecipients : [],
    blockFlats: Boolean(blockFlats || interdictFlats),
    interdictFlats: Boolean(blockFlats || interdictFlats),
    blockStartDate: blockStartDate || null,
    blockEndDate: blockEndDate || null,
    flats: formattedFlats,
    workerName: String(req.body.workerName || req.body.mainWorker?.name || "").trim() || null,
    workerCpf: String(req.body.workerCpf || req.body.mainWorker?.cpf || "").replace(/\D/g, "") || null,
    workerPhone: req.body.workerPhone || req.body.mainWorker?.phone || null
  };

  const preWorkerName = String(req.body.workerName || req.body.mainWorker?.name || "").trim();
  const preWorkerCpf = String(req.body.workerCpf || req.body.mainWorker?.cpf || "").replace(/\D/g, "");
  const preWorkerPhone = String(req.body.workerPhone || req.body.mainWorker?.phone || "").replace(/\D/g, "");
  const cleanedPrePhone = preWorkerPhone ? (cleanWhatsAppPhone ? cleanWhatsAppPhone(preWorkerPhone) : preWorkerPhone) : "";
  newOrder.workerPhone = cleanedPrePhone || null;

  const rawPreCollabs = req.body.workerCollaborators || req.body.collaborators || [];
  const preCollaborators = Array.isArray(rawPreCollabs)
    ? rawPreCollabs.map(c => ({ name: String(c?.name || "").trim(), cpf: String(c?.cpf || "").replace(/\D/g, "") })).filter(c => c.name && c.cpf.length === 11)
    : [];
  const rawPreVehicle = req.body.workerVehicle || req.body.vehicle || null;
  const preVehicle = rawPreVehicle && typeof rawPreVehicle === "object" ? {
    needsGarage: Boolean(rawPreVehicle.needsGarage),
    plate: String(rawPreVehicle.plate || "").trim().toUpperCase(),
    modelColor: String(rawPreVehicle.modelColor || "").trim()
  } : { needsGarage: false, plate: "", modelColor: "" };

  if (preWorkerName || cleanedPrePhone || preWorkerCpf) {
    if (!Array.isArray(db.serviceWorkers)) db.serviceWorkers = [];
    db.serviceWorkers.push({
      id: `sw_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`,
      serviceOrderId: newOrder.id,
      token: newOrder.token,
      mainWorker: {
        name: preWorkerName || "Prestador",
        cpf: preWorkerCpf,
        phone: cleanedPrePhone
      },
      collaborators: preCollaborators,
      vehicle: preVehicle,
      registeredAt: new Date().toISOString()
    });
  }

  if (!Array.isArray(db.serviceOrders)) db.serviceOrders = [];
  db.serviceOrders.unshift(newOrder);
  syncServiceOrderRoomBlocks(newOrder);
  saveDatabase("create_service_order");

  checkAndNotifyAvailableServiceFlats(newOrder.id, { onWorkerRegistered: Boolean(cleanedPrePhone) });

  try {
    const todayStr = getTodayStr();
    notifyPmsMutation(db, {
      type: "service_order_created",
      minDate: newOrder.blockStartDate || todayStr,
      maxDate: newOrder.blockEndDate || todayStr
    });
  } catch (_) {}

  const createdWorker = (db.serviceWorkers || []).find(w => w.serviceOrderId === newOrder.id || w.token === newOrder.token) || null;
  logAuditEvent({
    level: "info",
    category: "cleaning",
    action: "SERVICE_ORDER_CREATED",
    actor: { id: userAuth.id, name: userAuth.username, role: userAuth.role },
    details: {
      serviceOrderId: newOrder.id,
      orderId: newOrder.id,
      token: newOrder.token,
      action: "created",
      title: newOrder.title,
      flatsCount: newOrder.flats.length,
      blockFlats: newOrder.blockFlats,
      order: newOrder,
      worker: createdWorker
    }
  });

  res.status(201).json(newOrder);
});

