// ── Configuração de Valores de Pagamento por Quarto (Camareiras) ────────────
app.get("/api/cleaning/rates", (req, res) => {
  if (!db.cleaningRates) {
    db.cleaningRates = {
      defaultRatePerRoom: 22.50,
      userRates: { "2": 22.50, "3": 23.25 },
      defaultStayoverRatePerRoom: 15.00,
      userStayoverRates: { "2": 15.00, "3": 15.00 }
    };
    saveDatabase();
  }
  if (db.cleaningRates.defaultStayoverRatePerRoom === undefined) {
    db.cleaningRates.defaultStayoverRatePerRoom = 15.00;
  }
  if (!db.cleaningRates.userStayoverRates) {
    db.cleaningRates.userStayoverRates = { "2": 15.00, "3": 15.00 };
  } else {
    if (db.cleaningRates.userStayoverRates["2"] === undefined) db.cleaningRates.userStayoverRates["2"] = 15.00;
    if (db.cleaningRates.userStayoverRates["3"] === undefined) db.cleaningRates.userStayoverRates["3"] = 15.00;
  }
  const cleaners = (db.users || []).filter(u => u.role === "camareira" || u.role === "cleaner" || u.role === "admin" || u.role === "dev");
  const list = cleaners.map(u => ({
    userId: u.id,
    username: u.username,
    name: u.name || u.username,
    role: u.role,
    rate: db.cleaningRates.userRates?.[u.id] !== undefined ? Number(db.cleaningRates.userRates[u.id]) : Number(db.cleaningRates.defaultRatePerRoom || 22.50),
    stayoverRate: db.cleaningRates.userStayoverRates?.[u.id] !== undefined ? Number(db.cleaningRates.userStayoverRates[u.id]) : Number(db.cleaningRates.defaultStayoverRatePerRoom || 15.00)
  }));

  res.json({
    defaultRatePerRoom: Number(db.cleaningRates.defaultRatePerRoom || 22.50),
    userRates: db.cleaningRates.userRates || {},
    defaultStayoverRatePerRoom: Number(db.cleaningRates.defaultStayoverRatePerRoom || 15.00),
    userStayoverRates: db.cleaningRates.userStayoverRates || {},
    cleaners: list
  });
});

app.post("/api/cleaning/rates", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) {
    return res.status(403).json({ error: "Apenas administradores podem configurar taxas e diárias." });
  }
  const { defaultRatePerRoom, userRates, defaultStayoverRatePerRoom, userStayoverRates } = req.body;
  if (!db.cleaningRates) db.cleaningRates = {};
  if (defaultRatePerRoom !== undefined) db.cleaningRates.defaultRatePerRoom = Number(defaultRatePerRoom);
  if (userRates !== undefined) db.cleaningRates.userRates = userRates;
  if (defaultStayoverRatePerRoom !== undefined) db.cleaningRates.defaultStayoverRatePerRoom = Number(defaultStayoverRatePerRoom);
  if (userStayoverRates !== undefined) db.cleaningRates.userStayoverRates = userStayoverRates;
  saveDatabase();
  res.json({ success: true, rates: db.cleaningRates });
});

app.get("/api/analytics/report", (req, res) => {
  const userAuth = getAuthUser(req);
  const isCamareira = userAuth?.role === "camareira";
  const startDate = req.query.startDate || getOffsetDateStr(-30);
  const endDate = req.query.endDate || getTodayStr();

  if (!db.cleaningRates) {
    db.cleaningRates = {
      defaultRatePerRoom: 22.50,
      userRates: { "2": 22.50, "3": 23.25 },
      defaultStayoverRatePerRoom: 15.00,
      userStayoverRates: { "2": 15.00, "3": 15.00 }
    };
  }
  const defaultRate = Number(db.cleaningRates.defaultRatePerRoom || 22.50);
  const defaultStayoverRate = Number(db.cleaningRates.defaultStayoverRatePerRoom !== undefined ? db.cleaningRates.defaultStayoverRatePerRoom : 15.00);

  // Filtra limpezas concluídas no período [startDate, endDate]
  const completedCleanings = (db.cleaningRequests || []).filter(r => {
    if (r.status !== "clean" || r.isBedAdjustmentOnly || r.isInstructionOnly || r.type === "instruction" || r.source === "manual_instruction" || r.isPaidCleaning === false) return false;
    const effectiveDate = r.effectiveDate || (r.completedAt ? getExecutionDateStr(r.completedAt) : r.requestDate);
    if (effectiveDate < "2026-09-01") return false;
    return effectiveDate >= startDate && effectiveDate <= endDate;
  });

  let grandTotalToPay = 0;
  let grandTotalAdvances = 0;
  let grandTotalNetProduced = 0;
  let grandTotalNetToPay = 0;
  let grandTotalPayments = 0;

  // Helper para conciliação precisa de pagamentos e vales por período via motor canônico
  function matchesPeriod(entry, payment, startD, endD) {
    return matchesPeriodCanonical(entry, payment, startD, endD);
  }

  // Camareiras / Usuários
  const candidateUsers = (db.users || []).filter(u => u.role === "camareira" || u.role === "cleaner" || u.role === "admin" || u.role === "dev");
  const cleaningsByUser = candidateUsers.map(u => {
    syncMaidCredits(u.id);
    const currentBalance = Math.round(getMaidBalance(u.id) * 100) / 100;

    // Vales / Adiantamentos concedidos no período [startDate, endDate]
    const userVales = (db.maidStatementEntries || []).filter(e => {
      if (e.userId !== u.id || e.entryType !== "debit") return false;
      const payment = e.paymentId ? (db.maidPayments || []).find(p => p.id === e.paymentId) : null;
      if (!matchesPeriod(e, payment, startDate, endDate)) return false;
      return payment ? payment.type === "advance" : true;
    });
    const advancesInPeriod = userVales.reduce((acc, v) => acc + Number(v.amount || 0), 0);

    // Pagamentos PIX realizados no período [startDate, endDate] ou referentes à quinzena
    const userPayments = (db.maidStatementEntries || []).filter(e => {
      if (e.userId !== u.id || e.entryType !== "debit") return false;
      const payment = e.paymentId ? (db.maidPayments || []).find(p => p.id === e.paymentId) : null;
      if (payment && payment.type === "advance") return false;
      if (!matchesPeriod(e, payment, startDate, endDate)) return false;
      return payment ? payment.type === "payment" : true;
    });
    const paymentsInPeriod = userPayments.reduce((acc, p) => acc + Number(p.amount || 0), 0);

    const userCleanings = completedCleanings
      .filter(c => c.assignedUserId === u.id)
      .sort((a, b) => {
        const dateA = a.effectiveDate || (a.completedAt ? getExecutionDateStr(a.completedAt) : (a.requestDate || ""));
        const dateB = b.effectiveDate || (b.completedAt ? getExecutionDateStr(b.completedAt) : (b.requestDate || ""));
        const c = dateA.localeCompare(dateB);
        if (c !== 0) return c;
        return Number(String(a.flatNumber).replace(/\D/g, "") || 0) - Number(String(b.flatNumber).replace(/\D/g, "") || 0);
      });
    let totalMinutes = 0;
    let validDurationCount = 0;

    userCleanings.forEach(c => {
      if (c.cleaningStartedAt && c.completedAt) {
        const startMs = new Date(c.cleaningStartedAt).getTime();
        const endMs = new Date(c.completedAt).getTime();
        if (endMs > startMs) {
          const diffMins = (endMs - startMs) / 60000;
          // Regra: Quartos com mais de 90min (esquecimento de finalização) não entram no cálculo do tempo médio
          if (diffMins <= 90) {
            totalMinutes += diffMins;
            validDurationCount++;
          }
        }
      }
    });

    const avgMinutes = validDurationCount > 0 ? Math.round(totalMinutes / validDurationCount) : 35;
    const ratePerRoom = db.cleaningRates.userRates?.[u.id] !== undefined
      ? Number(db.cleaningRates.userRates[u.id])
      : defaultRate;
    const stayoverRate = db.cleaningRates.userStayoverRates?.[u.id] !== undefined
      ? Number(db.cleaningRates.userStayoverRates[u.id])
      : (u.id === 2 || u.id === 3 ? 15.00 : defaultStayoverRate);

    const checkoutCleanings = userCleanings.filter(c => c.cleaningType !== "stayover" && c.source !== "stayover");
    const stayoverCleanings = userCleanings.filter(c => c.cleaningType === "stayover" || c.source === "stayover");

    const checkoutCount = checkoutCleanings.length;
    const stayoverCount = stayoverCleanings.length;

    const checkoutTotal = checkoutCount * ratePerRoom;
    const stayoverTotal = stayoverCount * stayoverRate;
    const totalToPay = checkoutTotal + stayoverTotal;

    const netProduced = Math.max(0, Number((totalToPay - advancesInPeriod).toFixed(2)));
    const pendingToPay = Math.max(0, Number((netProduced - paymentsInPeriod).toFixed(2)));
    const isPaid = (totalToPay > 0 || advancesInPeriod > 0) && pendingToPay === 0 && paymentsInPeriod >= netProduced;
    const paidAt = isPaid ? (userPayments[0]?.entryDate || (userPayments[0]?.createdAt ? userPayments[0].createdAt.substring(0, 10) : endDate)) : null;

    grandTotalToPay += totalToPay;
    grandTotalAdvances += advancesInPeriod;
    grandTotalNetProduced += netProduced;
    grandTotalNetToPay += pendingToPay;
    grandTotalPayments += paymentsInPeriod;

    return {
      userId: u.id,
      username: u.username,
      name: u.name || u.username,
      role: u.role,
      pixKey: u.pixKey || "",
      whatsapp: u.whatsapp || u.phone || "",
      count: userCleanings.length,
      checkoutCount,
      stayoverCount,
      avgDurationMinutes: avgMinutes,
      ratePerRoom,
      stayoverRate,
      checkoutTotal: Number(checkoutTotal.toFixed(2)),
      stayoverTotal: Number(stayoverTotal.toFixed(2)),
      totalToPay: Number(totalToPay.toFixed(2)),
      advancesInPeriod: Number(advancesInPeriod.toFixed(2)),
      paymentsInPeriod: Number(paymentsInPeriod.toFixed(2)),
      netProduced: Number(netProduced.toFixed(2)),
      netToPay: Number(pendingToPay.toFixed(2)),
      pendingToPay: Number(pendingToPay.toFixed(2)),
      isPaid,
      paidAt,
      currentBalance,
      cleanings: userCleanings.map(c => {
        const flat = (db.flats || []).find(f => f.id === c.flatId);
        let itemDuration = 35;
        if (c.cleaningStartedAt && c.completedAt) {
          const s = new Date(c.cleaningStartedAt).getTime();
          const e = new Date(c.completedAt).getTime();
          if (e > s) itemDuration = Math.max(1, Math.round((e - s) / 60000));
        }
        const isStay = c.cleaningType === "stayover" || c.source === "stayover";
        return {
          id: c.id,
          flatNumber: flat ? flat.number : (c.flatNumber || String(c.flatId)),
          requestDate: c.requestDate,
          effectiveDate: c.effectiveDate || (c.completedAt ? getExecutionDateStr(c.completedAt) : c.requestDate),
          cleaningStartedAt: c.cleaningStartedAt,
          completedAt: c.completedAt,
          durationMinutes: c.durationMinutes || itemDuration,
          rate: isStay ? stayoverRate : ratePerRoom,
          cleaningType: isStay ? "stayover" : "checkout",
          source: c.source || (isStay ? "stayover" : "reservation"),
          leavingGuest: c.leavingGuest || null
        };
      }),
      totalHoursSpent: Number((totalMinutes / 60).toFixed(1))
    };
  }).filter(u => u.role === "camareira" || u.role === "cleaner" || u.count > 0);

  // My cleanings stats se for camareira
  const myCleanings = userAuth ? completedCleanings.filter(c => c.assignedUserId === userAuth.id) : [];
  const myCheckoutCleanings = myCleanings.filter(c => c.cleaningType !== "stayover" && c.source !== "stayover");
  const myStayoverCleanings = myCleanings.filter(c => c.cleaningType === "stayover" || c.source === "stayover");

  const myRate = userAuth && db.cleaningRates.userRates?.[userAuth.id] !== undefined
    ? Number(db.cleaningRates.userRates[userAuth.id])
    : defaultRate;
  const myStayoverRate = userAuth && db.cleaningRates.userStayoverRates?.[userAuth.id] !== undefined
    ? Number(db.cleaningRates.userStayoverRates[userAuth.id])
    : (userAuth && (userAuth.id === 2 || userAuth.id === 3) ? 15.00 : defaultStayoverRate);

  const myCheckoutTotal = myCheckoutCleanings.length * myRate;
  const myStayoverTotal = myStayoverCleanings.length * myStayoverRate;
  const myTotalToPay = myCheckoutTotal + myStayoverTotal;

  let myAdvancesInPeriod = 0;
  let myPaymentsInPeriod = 0;
  let myCurrentBalance = 0;

  if (userAuth) {
    syncMaidCredits(userAuth.id);
    myCurrentBalance = Math.round(getMaidBalance(userAuth.id) * 100) / 100;
    (db.maidStatementEntries || []).forEach(e => {
      if (e.userId !== userAuth.id || e.entryType !== "debit") return;
      const payment = e.paymentId ? (db.maidPayments || []).find(p => p.id === e.paymentId) : null;
      if (!matchesPeriod(e, payment, startDate, endDate)) return;

      if (payment && payment.type === "advance") {
        myAdvancesInPeriod += Number(e.amount || 0);
      } else {
        myPaymentsInPeriod += Number(e.amount || 0);
      }
    });
  }
  const myNetProduced = Math.max(0, Number((myTotalToPay - myAdvancesInPeriod).toFixed(2)));
  const myPendingToPay = Math.max(0, Number((myNetProduced - myPaymentsInPeriod).toFixed(2)));
  const myIsPaid = (myTotalToPay > 0 || myAdvancesInPeriod > 0) && myPendingToPay === 0 && myPaymentsInPeriod >= myNetProduced;

  // Cleanings by day of week
  const daysOfWeek = ["Domingo", "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado"];
  const dayCounts = [0, 0, 0, 0, 0, 0, 0];
  completedCleanings.forEach(c => {
    const dStr = c.effectiveDate || (c.completedAt ? getExecutionDateStr(c.completedAt) : c.requestDate);
    if (dStr) {
      const d = new Date(dStr + "T12:00:00Z");
      const dayIndex = d.getUTCDay();
      if (!isNaN(dayIndex)) {
        dayCounts[dayIndex]++;
      }
    }
  });

  const cleaningsByDayOfWeek = daysOfWeek.map((dayName, idx) => ({
    dayName,
    count: dayCounts[idx]
  }));

  // Top flats by cleanings
  const flatCleanCounts = new Map();
  completedCleanings.forEach(c => {
    const flat = db.flats.find(f => f.id === c.flatId);
    const flatNum = flat ? flat.number : (c.flatNumber || String(c.flatId));
    flatCleanCounts.set(flatNum, (flatCleanCounts.get(flatNum) || 0) + 1);
  });

  const topFlatsByCleanings = Array.from(flatCleanCounts.entries())
    .map(([flatNumber, count]) => ({ flatNumber, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 8);

  // Observações por categoria
  const observationsByCategoryMap = new Map();
  (db.observations || []).forEach(o => {
    const oDate = o.createdAt ? o.createdAt.substring(0, 10) : "";
    if (!oDate || (oDate >= startDate && oDate <= endDate)) {
      const cat = o.category || "defeito";
      observationsByCategoryMap.set(cat, (observationsByCategoryMap.get(cat) || 0) + 1);
    }
  });

  const observationsByCategory = Array.from(observationsByCategoryMap.entries()).map(([category, count]) => ({
    category,
    count
  }));

  let totalCheckoutCleanings = 0;
  let totalStayoverCleanings = 0;
  completedCleanings.forEach(c => {
    if (c.cleaningType === "stayover" || c.source === "stayover") {
      totalStayoverCleanings++;
    } else {
      totalCheckoutCleanings++;
    }
  });

  res.json({
    startDate,
    endDate,
    isCamareira,
    totalCleanings: completedCleanings.length,
    totalCheckoutCleanings,
    totalStayoverCleanings,
    grandTotalToPay: Number(grandTotalToPay.toFixed(2)),
    grandTotalAdvances: Number(grandTotalAdvances.toFixed(2)),
    grandTotalNetProduced: Number((grandTotalNetProduced || 0).toFixed(2)),
    grandTotalNetToPay: Number(grandTotalNetToPay.toFixed(2)),
    grandTotalPayments: Number(grandTotalPayments.toFixed(2)),
    grandTotalPendingToPay: Number(grandTotalNetToPay.toFixed(2)),
    isPeriodFullyPaid: grandTotalToPay > 0 && grandTotalNetToPay === 0 && grandTotalPayments >= (grandTotalToPay - grandTotalAdvances),
    defaultRatePerRoom: defaultRate,
    defaultStayoverRatePerRoom: defaultStayoverRate,
    myTotalToPay: Number(myTotalToPay.toFixed(2)),
    myCheckoutCount: myCheckoutCleanings.length,
    myStayoverCount: myStayoverCleanings.length,
    myCheckoutTotal: Number(myCheckoutTotal.toFixed(2)),
    myStayoverTotal: Number(myStayoverTotal.toFixed(2)),
    myAdvancesInPeriod: Number(myAdvancesInPeriod.toFixed(2)),
    myNetProduced: Number(myNetProduced.toFixed(2)),
    myNetToPay: Number(myPendingToPay.toFixed(2)),
    myPendingToPay: Number(myPendingToPay.toFixed(2)),
    myPaymentsInPeriod: Number(myPaymentsInPeriod.toFixed(2)),
    myIsPaid,
    myCurrentBalance,
    myRatePerRoom: myRate,
    myStayoverRate,
    myPixKey: userAuth?.pixKey || "",
    myTotalCleanings: userAuth ? completedCleanings.filter(c => c.assignedUserId === userAuth.id).length : completedCleanings.length,
    myAvgDurationMinutes: (() => {
      let myTotalMins = 0;
      let myValidCnt = 0;
      myCleanings.forEach(c => {
        if (c.cleaningStartedAt && c.completedAt) {
          const s = new Date(c.cleaningStartedAt).getTime();
          const e = new Date(c.completedAt).getTime();
          if (e > s) {
            const diff = (e - s) / 60000;
            if (diff <= 90) {
              myTotalMins += diff;
              myValidCnt++;
            }
          }
        }
      });
      return myValidCnt > 0 ? Math.round(myTotalMins / myValidCnt) : 35;
    })(),
    topFlatsByCleanings,
    topFlatsByObservations: [],
    observationsByCategory,
    cleaningsByDayOfWeek,
    cleaningsByUser,
  });
});

export function calculateCanonicalDirectStayQuote({
  checkinDate,
  checkoutDate,
  ratePlan = "with_breakfast",
  rooms = null,
  numGuests = 2,
  bedType = "queen",
  hasPet = false,
  petCount = 1,
  earlyCheckinFee = 0,
  lateCheckout = false,
  lateCheckoutTime = "18:00",
  lateCheckoutFeeOverride = null,
  flatId = null,
  channel = "direct"
} = {}) {
  const tarSettings = getTariffSettings();
  const wbpState = WbpPricingManager.getPricingState(db);
  const siteCfg = db.siteConfig || DEFAULT_SITE_CONFIG;

  const start = new Date(String(checkinDate || getTodayStr()).slice(0, 10) + "T12:00:00Z");
  const end = new Date(String(checkoutDate || getTodayStr()).slice(0, 10) + "T12:00:00Z");
  const requestedNights = [];
  if (isNaN(start.getTime()) || isNaN(end.getTime()) || start >= end) {
    requestedNights.push(String(checkinDate || getTodayStr()).slice(0, 10));
  } else {
    const cur = new Date(start);
    while (cur < end) {
      requestedNights.push(cur.toISOString().slice(0, 10));
      cur.setUTCDate(cur.getUTCDate() + 1);
    }
  }
  const nights = Math.max(1, requestedNights.length);

  const roomsList = Array.isArray(rooms) && rooms.length > 0
    ? rooms.map((r, idx) => ({
        id: r?.id ?? idx + 1,
        bedType: r?.bedType === "twin" ? "twin" : "queen",
        adults: Math.min(3, Math.max(1, Number(r?.adults) || 2))
      }))
    : [{ id: 1, bedType: bedType === "twin" ? "twin" : "queen", adults: Math.min(3, Math.max(1, Number(numGuests) || 2)) }];

  const flatsCount = roomsList.length;

  const stayDiscounts = tarSettings.stayDiscounts || { weeklyPct: 0.10, biweeklyPct: 0.15, monthlyPct: 0.25 };
  let stayDiscountPct = 0;
  if (nights >= 30) stayDiscountPct = Number(stayDiscounts.monthlyPct ?? 0.25);
  else if (nights >= 15) stayDiscountPct = Number(stayDiscounts.biweeklyPct ?? 0.15);
  else if (nights >= 7) stayDiscountPct = Number(stayDiscounts.weeklyPct ?? 0.10);

  const breakfastSurchargePerGuest = Number(
    wbpState.settings?.breakfastSurchargePerGuest ??
    tarSettings.breakfastSurchargePerGuest ??
    siteCfg.pricing?.breakfastSurchargePerGuest ??
    20
  );

  const cardMarkupPercent = Number(
    siteCfg.pricing?.cardMarkupPercent ??
    tarSettings.cardMarkupPercent ??
    siteCfg.pricing?.pixDiscountPercent ??
    5
  );

  const baseSemCafeRates = requestedNights.map(d => ({
    date: d,
    rate: calculateDailyRate(flatId, d, channel)
  }));

  const discountedSemCafeRates = baseSemCafeRates.map(item => ({
    date: item.date,
    rate: stayDiscountPct > 0
      ? Math.round(item.rate * (1 - stayDiscountPct) * 100) / 100
      : item.rate
  }));

  const isWithBf = ratePlan === "with_breakfast";
  const perNightCombinedRates = discountedSemCafeRates.map(item => {
    let nightSumAcrossFlats = 0;
    for (const rm of roomsList) {
      const bfAdd = isWithBf ? rm.adults * breakfastSurchargePerGuest : 0;
      nightSumAcrossFlats += Math.round((item.rate + bfAdd) * 100) / 100;
    }
    return {
      date: item.date,
      rate: Math.round(nightSumAcrossFlats * 100) / 100,
      perFlatAvgRate: Math.round((nightSumAcrossFlats / flatsCount) * 100) / 100
    };
  });

  const pixAccommodationSubtotal = Math.round(
    perNightCombinedRates.reduce((acc, n) => acc + n.rate, 0) * 100
  ) / 100;

  const avgDailyRatePerFlat = Math.round((pixAccommodationSubtotal / (nights * flatsCount)) * 100) / 100;

  // Taxa de limpeza (0 no plano com café por padrão hoteleiro; R$ 50/flat no plano sem café)
  const rawWbCfg = siteCfg.ratePlans?.with_breakfast || {};
  const rawRoCfg = siteCfg.ratePlans?.room_only || {};
  const activePlanCfg = isWithBf
    ? { cleaningFeeEnabled: Boolean(rawWbCfg.cleaningFeeEnabled), cleaningFeeAmount: Number(rawWbCfg.cleaningFeeAmount ?? 0), cleaningFeeType: rawWbCfg.cleaningFeeType || "per_stay" }
    : { cleaningFeeEnabled: rawRoCfg.cleaningFeeEnabled !== false, cleaningFeeAmount: Number(rawRoCfg.cleaningFeeAmount ?? 50), cleaningFeeType: rawRoCfg.cleaningFeeType || "per_stay" };

  const cleaningFeePerFlat = activePlanCfg.cleaningFeeEnabled
    ? (activePlanCfg.cleaningFeeType === "per_night" ? activePlanCfg.cleaningFeeAmount * nights : activePlanCfg.cleaningFeeAmount)
    : 0;
  const cleaningFee = Math.round(cleaningFeePerFlat * flatsCount * 100) / 100;

  // Camas Twin
  const twinCount = roomsList.filter(r => r.bedType === "twin").length;
  const twinFeeUnit = Number(siteCfg.bedConfig?.twinFeeAmount ?? 30);
  const twinFee = Math.round(
    twinCount * (siteCfg.bedConfig?.twinFeeType === "per_night" ? twinFeeUnit * nights : twinFeeUnit) * 100
  ) / 100;

  // Colchonete Extra (3º hóspede) — desativado por padrão no site até o gestor habilitar
  const extraBedCount = roomsList.filter(r => r.adults >= 3).length;
  const extraBedFeeUnit = Number(wbpState.settings?.extraBedFee ?? siteCfg.extraBedConfig?.feeAmount ?? 60);
  const extraBedEnabled = Boolean(siteCfg.extraBedConfig?.enabled);
  const extraBedFee = extraBedEnabled
    ? Math.round(extraBedCount * (siteCfg.extraBedConfig?.feeType === "per_night" ? extraBedFeeUnit * nights : extraBedFeeUnit) * 100) / 100
    : 0;

  // Taxa Pet
  const petFeeUnit = Number(siteCfg.petPolicy?.feeAmount ?? 40);
  const cleanPetCount = hasPet ? Math.max(1, Number(petCount) || 1) : 0;
  const petFee = hasPet
    ? Math.round((siteCfg.petPolicy?.feeType === "per_night" ? petFeeUnit * nights * cleanPetCount : petFeeUnit * cleanPetCount) * 100) / 100
    : 0;

  // Late Check-out
  let lateCheckoutFee = 0;
  if (lateCheckoutFeeOverride !== null && lateCheckoutFeeOverride !== undefined) {
    lateCheckoutFee = Math.max(0, Number(lateCheckoutFeeOverride) || 0);
  } else if (lateCheckout) {
    const [hStr, mStr] = String(lateCheckoutTime || "18:00").split(":");
    const hours = (parseInt(hStr, 10) || 0) + ((parseInt(mStr || "0", 10) || 0) / 60);
    if (hours <= 13.0) lateCheckoutFee = 0;
    else if (hours <= 18.0) lateCheckoutFee = 50 * flatsCount;
    else lateCheckoutFee = Math.round(avgDailyRatePerFlat * flatsCount * 100) / 100;
  }

  const resolvedEarlyFee = Math.max(0, Number(earlyCheckinFee) || 0);
  const extrasTotal = Math.round((cleaningFee + twinFee + extraBedFee + petFee + resolvedEarlyFee + lateCheckoutFee) * 100) / 100;

  // Preço Normal Real = Valor Final PIX (100% do Preço Base, sem corte de -15%)
  const pixTotalAmount = Math.round((pixAccommodationSubtotal + extrasTotal) * 100) / 100;
  // Preço Cartão = Preço Normal + acréscimo silencioso embutido (ex: +5%)
  const cardTotalAmount = computeCardAmountFromPix(pixTotalAmount, cardMarkupPercent);
  const pixDiscountAmount = Math.round((cardTotalAmount - pixTotalAmount) * 100) / 100;
  const cardDisplaySubtotal = Math.round((cardTotalAmount - extrasTotal) * 100) / 100;

  // Comparativo real contra plataformas (Booking / Airbnb = Preço Base + Comissão de cada plataforma em diárias e todas as taxas)
  const bookingMarkupDec = resolveChannelEffectiveMarkupPct(tarSettings.channelMarkups, "booking");
  const airbnbMarkupDec = resolveChannelEffectiveMarkupPct(tarSettings.channelMarkups, "airbnb");
  const referenceOtaMarkupDec =
    bookingMarkupDec > 0 && airbnbMarkupDec > 0
      ? Math.round(((bookingMarkupDec + airbnbMarkupDec) / 2) * 10000) / 10000
      : Math.max(bookingMarkupDec, airbnbMarkupDec);
  const otaMultRef = 1 + referenceOtaMarkupDec;
  const otaTotalBooking = Math.round(pixTotalAmount * (1 + bookingMarkupDec) * 100) / 100;
  const otaTotalAirbnb = Math.round(pixTotalAmount * (1 + airbnbMarkupDec) * 100) / 100;
  const otaReferenceTotal = Math.round(pixTotalAmount * otaMultRef * 100) / 100;
  const otaAvgDailyRatePerFlat = Math.round(avgDailyRatePerFlat * otaMultRef * 100) / 100;
  const otaSavingsAmount = Math.max(0, Math.round((otaReferenceTotal - pixTotalAmount) * 100) / 100);
  const otaChannelFees = calculateChannelAdjustedFees(
    {
      breakfastSurchargePerGuest,
      cleaningFee: Number(rawRoCfg.cleaningFeeAmount ?? 50),
      petFee: petFeeUnit,
      extraBedFee: extraBedFeeUnit,
      twinFee: twinFeeUnit,
      lateCheckoutFee: 50
    },
    tarSettings.channelMarkups
  );

  return {
    nights,
    flatsCount,
    ratePlan: isWithBf ? "with_breakfast" : "room_only",
    breakfastSurchargePerGuest,
    cardMarkupPercent,
    stayDiscountPct,
    baseSemCafeRates,
    discountedSemCafeRates,
    perNightCombinedRates,
    avgDailyRatePerFlat,
    pixAccommodationSubtotal,
    cardDisplaySubtotal,
    cleaningFee,
    twinFee,
    extraBedFee,
    petFee,
    earlyCheckinFee: resolvedEarlyFee,
    lateCheckoutFee,
    extrasTotal,
    pixTotalAmount,
    cardTotalAmount,
    pixDiscountAmount,
    otaComparison: {
      bookingMarkupPercent: Math.round(bookingMarkupDec * 10000) / 100,
      airbnbMarkupPercent: Math.round(airbnbMarkupDec * 10000) / 100,
      referenceMarkupPercent: Math.round(referenceOtaMarkupDec * 10000) / 100,
      otaAvgDailyRatePerFlat,
      otaAccommodationSubtotal: Math.round(pixAccommodationSubtotal * otaMultRef * 100) / 100,
      otaCleaningFee: Math.round(cleaningFee * otaMultRef * 100) / 100,
      otaTwinFee: Math.round(twinFee * otaMultRef * 100) / 100,
      otaExtraBedFee: Math.round(extraBedFee * otaMultRef * 100) / 100,
      otaPetFee: Math.round(petFee * otaMultRef * 100) / 100,
      otaTotalBooking,
      otaTotalAirbnb,
      otaReferenceTotal,
      otaSavingsAmount,
      channelFees: otaChannelFees
    }
  };
}

