app.patch("/api/settings", async (req, res) => {
  const { onedriveShareUrl, syncIntervalMinutes, sheetName, alertHour, termsAndRules, houseRules, contractTerms, adminWhatsApp, autoEarlyCheckinForSite, checkinTime, checkoutTime, hotelAddress, googleMapsUrl, receptionEmail, garageEmail, buildingName, petPolicy, childPolicy, cancellationPolicy, bedConfig, extraBedConfig, ratePlans, pricing, checkinProvider, serproConfig, validateConnection } = req.body;
  if (onedriveShareUrl !== undefined) db.settings.onedriveShareUrl = onedriveShareUrl;
  if (syncIntervalMinutes !== undefined) db.settings.syncIntervalMinutes = syncIntervalMinutes;
  if (sheetName !== undefined) db.settings.sheetName = sheetName;
  if (alertHour !== undefined) db.settings.alertHour = alertHour;
  if (houseRules !== undefined) db.settings.houseRules = houseRules;
  if (contractTerms !== undefined) db.settings.contractTerms = contractTerms;
  if (termsAndRules !== undefined) db.settings.termsAndRules = termsAndRules;
  if (adminWhatsApp !== undefined) db.settings.adminWhatsApp = adminWhatsApp;
  if (autoEarlyCheckinForSite !== undefined) db.settings.autoEarlyCheckinForSite = Boolean(autoEarlyCheckinForSite);
  if (checkinTime !== undefined) db.settings.checkinTime = checkinTime;
  if (checkoutTime !== undefined) db.settings.checkoutTime = checkoutTime;
  if (hotelAddress !== undefined) db.settings.hotelAddress = hotelAddress;
  if (googleMapsUrl !== undefined) db.settings.googleMapsUrl = googleMapsUrl;
  if (receptionEmail !== undefined) db.settings.receptionEmail = receptionEmail;
  if (garageEmail !== undefined) db.settings.garageEmail = garageEmail ? String(garageEmail).trim() : "promenadesoho@pfbestacionamentos.com.br";
  if (buildingName !== undefined) db.settings.buildingName = buildingName;

  // Validação e mesclagem de serproConfig (antes da validação de ativação do provedor)
  if (serproConfig !== undefined) {
    if (typeof serproConfig !== "object" || serproConfig === null) {
      return res.status(400).json({ error: "serproConfig deve ser um objeto válido." });
    }
    if (serproConfig.env && !["homologacao", "producao"].includes(serproConfig.env)) {
      return res.status(400).json({ error: "serproConfig.env inválido. Deve ser 'homologacao' ou 'producao'." });
    }
    const cleanSerpro = { ...(db.settings.serproConfig || {}) };
    if (serproConfig.user !== undefined) cleanSerpro.user = String(serproConfig.user).trim();
    if (serproConfig.password !== undefined && String(serproConfig.password).trim() !== "") {
      cleanSerpro.password = String(serproConfig.password).trim();
    }
    if (serproConfig.cpfSolicitante !== undefined) {
      cleanSerpro.cpfSolicitante = String(serproConfig.cpfSolicitante).replace(/\D/g, "");
    }
    if (serproConfig.env !== undefined) cleanSerpro.env = serproConfig.env;
    db.settings.serproConfig = cleanSerpro;

    // Auto-detecção de ambiente (Produção vs Homologação) ao salvar credenciais
    if (cleanSerpro.user && cleanSerpro.password && !cleanSerpro.mock && process.env.SERPRO_MOCK !== "true") {
      try {
        const health = await fnrhSerproService.checkHealth(db.settings);
        if (health.ok && health.env && db.settings.serproConfig.env !== health.env) {
          db.settings.serproConfig.env = health.env;
        }
      } catch (_) {}
    }
  }

  // Validação e persistência do checkinProvider
  if (checkinProvider !== undefined) {
    if (checkinProvider !== "proprio" && checkinProvider !== "gov_fnrh") {
      return res.status(400).json({
        error: "checkinProvider inválido. Deve ser 'proprio' ou 'gov_fnrh'."
      });
    }
    if (checkinProvider === "gov_fnrh" && validateConnection === true) {
      const health = await fnrhSerproService.checkHealth(db.settings);
      if (!health.ok) {
        return res.status(400).json({
          error: health.message || "Não foi possível ativar o Check-in Oficial Gov.br: verifique as credenciais SERPRO antes de ativar.",
          serproHealth: health
        });
      }
      if (health.env && db.settings.serproConfig && db.settings.serproConfig.env !== health.env) {
        db.settings.serproConfig.env = health.env;
      }
    }
    db.settings.checkinProvider = checkinProvider;
  }

  if (petPolicy !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.petPolicy = {
      ...(db.siteConfig.petPolicy || DEFAULT_SITE_CONFIG.petPolicy),
      ...petPolicy
    };
    db.settings.petPolicy = db.siteConfig.petPolicy;
  }
  if (childPolicy !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.childPolicy = {
      ...(db.siteConfig.childPolicy || db.settings.childPolicy || {}),
      ...childPolicy
    };
    db.settings.childPolicy = db.siteConfig.childPolicy;
  }
  if (cancellationPolicy !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.cancellationPolicy = {
      ...(db.siteConfig.cancellationPolicy || db.settings.cancellationPolicy || {}),
      ...cancellationPolicy
    };
    db.settings.cancellationPolicy = db.siteConfig.cancellationPolicy;
  }
  if (bedConfig !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.bedConfig = {
      ...(db.siteConfig.bedConfig || DEFAULT_SITE_CONFIG.bedConfig),
      ...bedConfig
    };
  }
  if (extraBedConfig !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.extraBedConfig = {
      ...(db.siteConfig.extraBedConfig || DEFAULT_SITE_CONFIG.extraBedConfig),
      ...extraBedConfig
    };
  }
  if (ratePlans !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.ratePlans = {
      ...(db.siteConfig.ratePlans || DEFAULT_SITE_CONFIG.ratePlans),
      ...ratePlans
    };
  }
  if (pricing !== undefined) {
    if (!db.siteConfig) db.siteConfig = {};
    db.siteConfig.pricing = {
      ...(db.siteConfig.pricing || DEFAULT_SITE_CONFIG.pricing),
      ...pricing
    };
  }
  if (petPolicy !== undefined || childPolicy !== undefined || cancellationPolicy !== undefined || bedConfig !== undefined || extraBedConfig !== undefined || ratePlans !== undefined || pricing !== undefined) {
    syncSiteConfigToSettings({ petPolicy, childPolicy, cancellationPolicy, bedConfig, extraBedConfig, ratePlans, pricing });
  }
  saveDatabase("settings_update");
  const currentPetPolicy = db.siteConfig?.petPolicy || db.settings?.petPolicy || DEFAULT_SITE_CONFIG.petPolicy;
  const currentChildPolicy = db.siteConfig?.childPolicy || db.settings?.childPolicy;
  const currentCancellationPolicy = db.siteConfig?.cancellationPolicy || db.settings?.cancellationPolicy;
  res.json({
    ...db.settings,
    checkinProvider: db.settings.checkinProvider || "proprio",
    serproConfig: {
      user: db.settings?.serproConfig?.user || process.env.SERPRO_USER || "",
      hasPassword: Boolean(db.settings?.serproConfig?.password || process.env.SERPRO_PASSWORD),
      cpfSolicitante: db.settings?.serproConfig?.cpfSolicitante || process.env.SERPRO_CPF_SOLICITANTE || "12585736792",
      env: db.settings?.serproConfig?.env || process.env.SERPRO_ENV || "homologacao"
    },
    petPolicy: currentPetPolicy,
    childPolicy: currentChildPolicy,
    cancellationPolicy: currentCancellationPolicy,
    houseRules: db.settings.houseRules || DEFAULT_HOUSE_RULES,
    contractTerms: db.settings.contractTerms || DEFAULT_CONTRACT_TERMS
  });
});

// ── Health Check da Conexão SERPRO FNRH Digital v2.4.2 ────────────────────────
app.get("/api/fnrh-serpro/status", async (req, res) => {
  try {
    const provider = db.settings?.checkinProvider || "proprio";
    const health = await fnrhSerproService.checkHealth(db.settings);
    if (health.ok && health.detectedEnv && db.settings?.serproConfig && db.settings.serproConfig.env !== health.detectedEnv) {
      db.settings.serproConfig.env = health.detectedEnv;
      saveDatabase("serpro_auto_env_detect");
    }
    return res.json({
      ok: Boolean(health.ok),
      provider,
      env: health.env || db.settings?.serproConfig?.env || process.env.SERPRO_ENV || "homologacao",
      latencyMs: Number(health.latencyMs) || 0,
      status: health.status || (health.ok ? "healthy" : "unreachable"),
      message: health.message || (health.ok ? "Conexão operacional com SERPRO FNRH" : health.error || "Falha de conexão"),
      error: health.error || null
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      provider: db.settings?.checkinProvider || "proprio",
      env: db.settings?.serproConfig?.env || process.env.SERPRO_ENV || "homologacao",
      latencyMs: 0,
      status: "internal_error",
      error: err.message
    });
  }
});

