// ── Endpoint de Consulta de Disponibilidade Geral & Camas Solteiro ────────────
app.get("/api/reservations/availability", (req, res) => {
  try {
    const { checkin, checkout } = req.query;
    if (!checkin || !checkout) {
      return res.status(400).json({ error: "Check-in e Check-out são obrigatórios." });
    }

    const siteCfg = db.siteConfig || DEFAULT_SITE_CONFIG;
    const bedCfg = siteCfg.bedConfig || DEFAULT_SITE_CONFIG.bedConfig;
    const twinAllowed = (bedCfg.twinAllowedFlats || []).map(String);
    const cutoffTime = bedCfg.twinSameDayCutoffTime || "12:00";

    const allFlats = (db.flats || []).filter(f => !f.status || f.status !== "manutencao_bloqueada");

    // Verifica flats ocupados no período (reservas ativas e holds provisórios)
    const nowMs = Date.now();
    const occupiedFlatIds = new Set();
    (db.reservations || []).forEach(r => {
      if (r.status === "cancelada" || r.status === "CANCELLED" || r.status === "expirada") return;
      if ((r.status === "pre_reserva" || r.status === "pendente") && r.expiresAt && new Date(r.expiresAt).getTime() < nowMs && r.paymentStatus !== "pago_total") {
        return;
      }
      if (r.checkinDate < checkout && r.checkoutDate > checkin) {
        if (r.flatNumber != null) occupiedFlatIds.add(String(r.flatNumber));
        if (r.flatId != null) occupiedFlatIds.add(String(r.flatId));
      }
      if (r.pendingModification && (r.pendingModification.status === "pending" || r.pendingModification.status === "pending_payment")) {
        if (r.pendingModification.expiresAt && new Date(r.pendingModification.expiresAt).getTime() < nowMs) {
          r.pendingModification.status = "expired";
          r.pendingModification.expiredAt = new Date(nowMs).toISOString();
        } else {
          const pHoldIn = r.pendingModification.newCheckinDate || r.pendingModification.proposedCheckinDate;
          const pHoldOut = r.pendingModification.newCheckoutDate || r.pendingModification.proposedCheckoutDate;
          const pHoldFlatNum = r.pendingModification.newFlatNumber || r.pendingModification.proposedFlatNumber;
          const pHoldFlatId = r.pendingModification.newFlatId || r.pendingModification.proposedFlatId;
          if (pHoldIn && pHoldOut && pHoldIn < checkout && pHoldOut > checkin) {
            if (pHoldFlatNum != null) occupiedFlatIds.add(String(pHoldFlatNum));
            if (pHoldFlatId != null) occupiedFlatIds.add(String(pHoldFlatId));
          }
        }
      }
    });

    const availableFlats = allFlats.filter(f => !occupiedFlatIds.has(String(f.number)) && !occupiedFlatIds.has(String(f.id)));
    const totalAvailable = availableFlats.length;

    // Flats disponíveis que suportam 2 camas de solteiro
    const availableTwinFlats = availableFlats.filter(f => twinAllowed.includes(String(f.number)));
    const twinAvailableCount = availableTwinFlats.length;

    // Validação de horário limite para o mesmo dia (sempre em America/Sao_Paulo)
    const bNow = getBrasiliaNow();
    const todayStr = bNow.date;
    let allowTwinForDates = true;
    let twinCutoffReached = false;
    const extraCutoffHour = Number(siteCfg.extraBedConfig?.cutoffHour) || 12;
    const extraCutoffTime = `${String(extraCutoffHour).padStart(2, "0")}:00`;
    let extraBedCutoffReached = false;

    if (checkin === todayStr) {
      if (bNow.timeStr >= cutoffTime) {
        allowTwinForDates = false;
        twinCutoffReached = true;
      }
      if (bNow.timeStr >= extraCutoffTime) {
        extraBedCutoffReached = true;
      }
    }

    // Cálculo de noites solicitadas e disponibilidade diária
    const requestedNights = [];
    let curr = new Date(checkin + "T12:00:00Z");
    const end = new Date(checkout + "T12:00:00Z");

    if (isNaN(curr.getTime()) || isNaN(end.getTime()) || curr >= end) {
      requestedNights.push(checkin);
    } else {
      while (curr < end) {
        requestedNights.push(curr.toISOString().slice(0, 10));
        curr.setUTCDate(curr.getUTCDate() + 1);
      }
    }

    const activeReservations = (db.reservations || []).filter(r => r.status !== "cancelada");
    const dailyAvailability = requestedNights.map(d => {
      const occupiedOnDate = new Set(
        activeReservations
          .filter(r => r.checkinDate <= d && r.checkoutDate > d)
          .map(r => String(r.flatNumber || r.flatId))
      );
      const availableCount = allFlats.filter(
        f => !occupiedOnDate.has(String(f.number)) && !occupiedOnDate.has(String(f.id))
      ).length;
      return {
        date: d,
        availableFlats: availableCount
      };
    });

    const minAvailableOnAnyDate = dailyAvailability.length > 0
      ? Math.min(...dailyAvailability.map(item => item.availableFlats))
      : totalAvailable;

    const hasLowAvailability = minAvailableOnAnyDate <= 5 || totalAvailable <= 5;
    const quoteSampleRoomOnly = calculateCanonicalDirectStayQuote({
      checkinDate: String(checkin),
      checkoutDate: String(checkout),
      ratePlan: "room_only",
      rooms: [{ id: 1, bedType: "queen", adults: 2 }]
    });
    const quoteSampleWithBf1 = calculateCanonicalDirectStayQuote({
      checkinDate: String(checkin),
      checkoutDate: String(checkout),
      ratePlan: "with_breakfast",
      rooms: [{ id: 1, bedType: "queen", adults: 1 }]
    });
    const quoteSampleWithBf2 = calculateCanonicalDirectStayQuote({
      checkinDate: String(checkin),
      checkoutDate: String(checkout),
      ratePlan: "with_breakfast",
      rooms: [{ id: 1, bedType: "queen", adults: 2 }]
    });

    res.json({
      available: totalAvailable > 0,
      totalAvailableFlats: totalAvailable,
      dailyAvailability,
      minAvailableOnAnyDate,
      hasLowAvailability,
      twinAvailableCount,
      allowTwinBeds: Boolean(bedCfg.allowTwinBeds && allowTwinForDates && twinAvailableCount > 0),
      twinCutoffReached,
      twinCutoffMessage: twinCutoffReached
        ? `Flats com 2 camas separadas de solteiro precisam ser reservados até no máximo às ${cutoffTime} do dia do check-in.`
        : (twinAvailableCount === 0 ? "Não há mais disponibilidade de flats com 2 camas de solteiro para as datas selecionadas (apenas Cama Queen Casal disponível)." : null),
      bedConfig: bedCfg,
      extraBedConfig: (() => {
        const wbpStateAvail = WbpPricingManager.getPricingState(db);
        const resolvedExtraFee = Number(
          wbpStateAvail.settings?.extraBedFee ??
          siteCfg.extraBedConfig?.feeAmount ??
          DEFAULT_SITE_CONFIG.extraBedConfig.feeAmount ??
          60
        );
        const isExtraEnabled = Boolean(siteCfg.extraBedConfig?.enabled);
        return {
          ...(DEFAULT_SITE_CONFIG.extraBedConfig),
          ...(siteCfg.extraBedConfig || {}),
          feeAmount: resolvedExtraFee,
          enabled: isExtraEnabled,
          extraBedCutoffReached,
          maxGuests: isExtraEnabled && !extraBedCutoffReached ? 3 : 2
        };
      })(),
      petPolicy: {
        ...(DEFAULT_SITE_CONFIG.petPolicy),
        ...(siteCfg.petPolicy || {})
      },
      ratePlans: {
        ...(siteCfg.ratePlans || DEFAULT_SITE_CONFIG.ratePlans),
        with_breakfast: {
          ...DEFAULT_SITE_CONFIG.ratePlans.with_breakfast,
          ...(siteCfg.ratePlans?.with_breakfast || {}),
          dailyRate: quoteSampleWithBf1.avgDailyRatePerFlat,
          dailyRate1Guest: quoteSampleWithBf1.avgDailyRatePerFlat,
          dailyRate2Guests: quoteSampleWithBf2.avgDailyRatePerFlat,
          cleaningFeeEnabled: Boolean(siteCfg.ratePlans?.with_breakfast?.cleaningFeeEnabled),
          cleaningFeeAmount: Number(siteCfg.ratePlans?.with_breakfast?.cleaningFeeAmount ?? 0)
        },
        room_only: {
          ...DEFAULT_SITE_CONFIG.ratePlans.room_only,
          ...(siteCfg.ratePlans?.room_only || {}),
          dailyRate: quoteSampleRoomOnly.avgDailyRatePerFlat,
          cleaningFeeEnabled: siteCfg.ratePlans?.room_only?.cleaningFeeEnabled !== false,
          cleaningFeeAmount: Number(siteCfg.ratePlans?.room_only?.cleaningFeeAmount ?? 50)
        }
      },
      pricing: {
        ...DEFAULT_SITE_CONFIG.pricing,
        ...(siteCfg.pricing || {}),
        directDiscountPercent: 0,
        cardMarkupPercent: quoteSampleRoomOnly.cardMarkupPercent,
        pixDiscountPercent: quoteSampleRoomOnly.cardMarkupPercent,
        breakfastSurchargePerGuest: quoteSampleRoomOnly.breakfastSurchargePerGuest,
        otaComparison: quoteSampleRoomOnly.otaComparison
      },
      dynamicPricing: {
        nights: quoteSampleRoomOnly.nights,
        baseSemCafeRates: quoteSampleRoomOnly.baseSemCafeRates,
        discountedSemCafeRates: quoteSampleRoomOnly.discountedSemCafeRates,
        stayDiscountPct: quoteSampleRoomOnly.stayDiscountPct,
        breakfastSurchargePerGuest: quoteSampleRoomOnly.breakfastSurchargePerGuest,
        cardMarkupPercent: quoteSampleRoomOnly.cardMarkupPercent,
        avgRoomOnlyRate: quoteSampleRoomOnly.avgDailyRatePerFlat,
        avgWithBreakfast1GuestRate: quoteSampleWithBf1.avgDailyRatePerFlat,
        avgWithBreakfast2GuestsRate: quoteSampleWithBf2.avgDailyRatePerFlat,
        otaComparison: {
          ...quoteSampleRoomOnly.otaComparison,
          otaAvgRoomOnlyRate: quoteSampleRoomOnly.otaComparison.otaAvgDailyRatePerFlat,
          otaAvgWithBreakfast1GuestRate: quoteSampleWithBf1.otaComparison.otaAvgDailyRatePerFlat,
          otaAvgWithBreakfast2GuestsRate: quoteSampleWithBf2.otaComparison.otaAvgDailyRatePerFlat
        }
      }
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Utilitários PIX Padrão BACEN (BR Code EMV) ──────────────────────────────
function crc16(str) {
  let crc = 0xFFFF;
  for (let i = 0; i < str.length; i++) {
    crc ^= (str.charCodeAt(i) << 8);
    for (let j = 0; j < 8; j++) {
      if ((crc & 0x8000) !== 0) {
        crc = ((crc << 1) ^ 0x1021) & 0xFFFF;
      } else {
        crc = (crc << 1) & 0xFFFF;
      }
    }
  }
  return crc.toString(16).toUpperCase().padStart(4, "0");
}

export function generateStaticPixPayload({ pixKey = "47964813000165", amount = 0, merchantName = "CORPFLATS LTDA", merchantCity = "CAMPOS DOS GOYTACAZES", txid = "***" }) {
  const formatTag = (id, value) => `${id}${String(value.length).padStart(2, "0")}${value}`;
  let payload = formatTag("00", "01");
  const gui = formatTag("00", "br.gov.bcb.pix");
  const key = formatTag("01", pixKey);
  payload += formatTag("26", `${gui}${key}`);
  payload += formatTag("52", "0000");
  payload += formatTag("53", "986");
  if (amount && Number(amount) > 0) {
    payload += formatTag("54", Number(amount).toFixed(2));
  }
  payload += formatTag("58", "BR");
  const cleanName = (merchantName || "CORPFLATS LTDA")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9 ]/g, "").trim().substring(0, 25);
  payload += formatTag("59", cleanName || "CORPFLATS LTDA");
  const cleanCity = (merchantCity || "CAMPOS")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-zA-Z0-9 ]/g, "").trim().substring(0, 15);
  payload += formatTag("60", cleanCity || "CAMPOS");
  const cleanTxId = (txid || "***").replace(/[^a-zA-Z0-9]/g, "").substring(0, 25) || "***";
  payload += formatTag("62", formatTag("05", cleanTxId));
  const toCrc = `${payload}6304`;
  return `${toCrc}${crc16(toCrc)}`;
}

