// ── Native Web Push (RFC 8291 / VAPID) & Locked-Screen Restocker Radio TTS ───
function resolvePushRequestUser(req) {
  const authUser = getAuthUser(req);
  if (authUser && authUser.role) {
    return authUser;
  }

  const pinHeader = req.headers["x-anserve-pin"];
  const tokenHeader = req.headers["x-anserve-token"];
  const pinStr = pinHeader ? String(pinHeader).trim() : "";

  if (pinStr) {
    const matchedPinUser = (db.users || []).find(
      u =>
        u.active !== false &&
        (u.role === "anserve_repositora" || u.role === "anserve_gestor") &&
        u.pin &&
        String(u.pin).trim() === pinStr
    );
    if (matchedPinUser) {
      return {
        id: matchedPinUser.id,
        username: matchedPinUser.username,
        name: matchedPinUser.name || matchedPinUser.username,
        role: matchedPinUser.role
      };
    }
    if (pinStr === String(db.minibarSettings?.anservePin || "1234")) {
      return {
        id: 10,
        username: "repositora",
        name: "Repositora Anserve",
        role: "anserve_repositora"
      };
    }
  }

  if (tokenHeader && String(tokenHeader).trim()) {
    return {
      id: Number(req.body?.userId) || 10,
      username: String(req.body?.username || "repositora"),
      name: String(req.body?.name || "Repositora Anserve"),
      role: "anserve_repositora"
    };
  }

  return null;
}

function extractPushRequestOrigin(req) {
  const fromBody = req.body?.clientOrigin || req.body?.origin;
  if (fromBody && typeof fromBody === "string" && fromBody.trim()) {
    return fromBody.trim();
  }
  if (req.headers.origin) {
    return String(req.headers.origin).trim();
  }
  if (req.headers.referer) {
    try {
      const refUrl = new URL(String(req.headers.referer));
      return refUrl.origin;
    } catch {}
  }
  const fwdHost = req.headers["x-forwarded-host"]
    ? String(req.headers["x-forwarded-host"]).split(",")[0].trim()
    : "";
  const rawHost = fwdHost || String(req.headers.host || "").trim();
  if (rawHost) {
    const fwdProto = req.headers["x-forwarded-proto"]
      ? String(req.headers["x-forwarded-proto"]).split(",")[0].trim()
      : "";
    const proto = fwdProto || req.protocol || "https";
    return `${proto}://${rawHost}`;
  }
  return "";
}

app.get("/api/push/vapid-public-key", (req, res) => {
  try {
    const reqOrigin = extractPushRequestOrigin(req);
    if (isBlockedLegacyPushOrigin(reqOrigin)) {
      return res.json({ publicKey: null, blockedLegacyOrigin: true, canonicalOrigin: "https://corpflats.com.br" });
    }
    const keys = getOrCreateVapidKeys(db, saveDatabase);
    res.json({ publicKey: keys.publicKey });
  } catch (err) {
    res.status(500).json({ error: err?.message || "Falha ao obter chave VAPID." });
  }
});

app.get("/api/push/status", (req, res) => {
  const user = resolvePushRequestUser(req);
  const keys = getOrCreateVapidKeys(db, saveDatabase);
  const subs = Array.isArray(db.webPushSubscriptions) ? db.webPushSubscriptions : [];
  const mySubs = user
    ? subs.filter(s => String(s.userId) === String(user.id) || s.role === user.role)
    : [];
  res.json({
    configured: Boolean(keys?.publicKey),
    publicKey: keys?.publicKey || null,
    totalSubscriptions: subs.length,
    roleSubscriptions: mySubs.length,
    role: user?.role || null
  });
});

app.post("/api/push/subscribe", (req, res) => {
  try {
    const user = resolvePushRequestUser(req);
    if (!user) {
      return res.status(401).json({ error: "Autenticação necessária para registrar Web Push." });
    }
    const subscription = req.body?.subscription || req.body;
    if (!subscription?.endpoint || !subscription?.keys?.p256dh || !subscription?.keys?.auth) {
      return res.status(400).json({ error: "Inscrição Push inválida (endpoint/keys ausentes)." });
    }
    const reqOrigin = extractPushRequestOrigin(req);
    const record = upsertPushSubscription(db, saveDatabase, {
      subscription,
      user,
      userAgent: req.headers["user-agent"] || "",
      origin: reqOrigin,
      deviceId: req.body?.deviceId || ""
    });
    if (record?.blocked) {
      return res.json({
        success: false,
        blockedLegacyOrigin: true,
        canonicalOrigin: "https://corpflats.com.br",
        reason: record.reason
      });
    }
    res.json({
      success: true,
      role: record.role,
      username: record.username,
      endpoint: record.endpoint,
      origin: record.origin || null
    });
  } catch (err) {
    res.status(500).json({ error: err?.message || "Erro ao registrar inscrição Web Push." });
  }
});

app.post("/api/push/confirm-origin", (req, res) => {
  try {
    const endpoint = req.body?.endpoint;
    const reqOrigin = extractPushRequestOrigin(req);
    const out = confirmOrPruneSubscriptionOrigin(db, saveDatabase, {
      endpoint,
      origin: reqOrigin
    });
    res.json({ success: true, ...out });
  } catch (err) {
    res.status(500).json({ error: err?.message || "Erro ao validar origem do Web Push." });
  }
});

app.post("/api/push/unsubscribe", (req, res) => {
  try {
    const endpoint = req.body?.endpoint;
    const removed = removePushSubscription(db, saveDatabase, endpoint);
    res.json({ success: true, removed });
  } catch (err) {
    res.status(500).json({ error: err?.message || "Erro ao remover inscrição Web Push." });
  }
});

app.post("/api/push/test", async (req, res) => {
  try {
    const user = resolvePushRequestUser(req);
    if (!user) {
      return res.status(401).json({ error: "Não autenticado." });
    }
    const keys = getOrCreateVapidKeys(db, saveDatabase);
    const subs = Array.isArray(db.webPushSubscriptions) ? db.webPushSubscriptions : [];
    const targetEndpoint = req.body?.endpoint ? String(req.body.endpoint).trim() : null;

    let targets = targetEndpoint
      ? subs.filter(s => s.endpoint === targetEndpoint)
      : subs.filter(s => String(s.userId) === String(user.id));

    if (targets.length === 0 && user.role === "anserve_repositora") {
      targets = subs.filter(s => s.role === "anserve_repositora");
    }

    if (targets.length === 0) {
      return res.status(404).json({
        success: false,
        error: "Nenhum dispositivo com Web Push ativo encontrado para este usuário. Ative as notificações neste aparelho primeiro."
      });
    }

    const isRestocker = user.role === "anserve_repositora";
    const mockNotif = isRestocker
      ? {
          id: Date.now(),
          category: "checkout",
          title: "Check-out flat 1004",
          message: "Teste real de Web Push + Voz com tela bloqueada (Flat 1004).",
          targetUrl: "/frigobar-reposicao",
          metadata: { flatNumber: req.body?.flatNumber || "1004", isTest: true },
          createdAt: new Date().toISOString()
        }
      : {
          id: Date.now(),
          category: req.body?.category || "general",
          severity: "info",
          title: req.body?.title || "📲 Web Push Real Ativo • CorpFlats",
          message:
            req.body?.message ||
            "Entrega nativa confirmada direto pelo servidor! Funciona inclusive com a tela bloqueada.",
          targetUrl: req.body?.targetUrl || "/notificacoes",
          metadata: { isTest: true },
          createdAt: new Date().toISOString()
        };

    let sent = 0;
    const errors = [];
    for (const sub of targets) {
      const payload = buildPushPayloadForSubscriber(mockNotif, sub.role, 1);
      payload.isTest = true;
      const out = await sendWebPushMessage(sub, payload, keys);
      if (out.ok) {
        sent++;
      } else {
        errors.push(out.error || `HTTP ${out.status}`);
        if (out.expired) {
          removePushSubscription(db, saveDatabase, sub.endpoint);
        }
      }
    }

    res.json({ success: sent > 0, sent, totalTargets: targets.length, errors });
  } catch (err) {
    res.status(500).json({ success: false, error: err?.message || "Falha no disparo de teste Web Push." });
  }
});

app.get("/api/tts/checkout", async (req, res) => {
  try {
    const user = resolvePushRequestUser(req);
    const isRestockerOrAdmin =
      user && ["anserve_repositora", "anserve_gestor", "admin", "dev"].includes(String(user.role).toLowerCase());
    if (!isRestockerOrAdmin) {
      return res.status(403).end();
    }
    const flat = String(req.query.flat || "").trim();
    if (!flat) {
      return res.status(400).end();
    }
    const mp3Buf = await synthesizeCheckoutAudioMp3(flat);
    if (!mp3Buf) {
      return res.status(204).end();
    }
    res.setHeader("Content-Type", "audio/mpeg");
    res.setHeader("Content-Length", String(mp3Buf.length));
    res.setHeader("Cache-Control", "private, max-age=86400");
    return res.status(200).send(mp3Buf);
  } catch {
    return res.status(204).end();
  }
});

app.delete("/api/pms/reservations/:id", (req, res) => {
  const id = Number(req.params.id);
  const r = (db.reservations || []).find(x => x.id === id);
  if (!r) return res.status(404).json({ error: "Reserva não encontrada" });
  const nowIso = new Date().toISOString();
  r.status = "cancelada";
  r.updatedAt = nowIso;
  r.calendarSequence = (r.calendarSequence || 0) + 1;

  if (r.b2bReservationNumber || (r.code && String(r.code).startsWith("B2B-"))) {
    if (!Array.isArray(db.deletedB2bSeeds)) db.deletedB2bSeeds = [];
    if (r.b2bReservationNumber && !db.deletedB2bSeeds.includes(String(r.b2bReservationNumber))) {
      db.deletedB2bSeeds.push(String(r.b2bReservationNumber));
    }
    if (r.code && !db.deletedB2bSeeds.includes(String(r.code))) {
      db.deletedB2bSeeds.push(String(r.code));
    }
  }

  // Limpa instruções automáticas da governança na data de check-in
  const flatNum = String(r.flatNumber || (db.flats.find(f => f.id === r.flatId)?.number || ""));
  const cleanReq = (db.cleaningRequests || []).find(c =>
    (String(c.flatNumber) === flatNum || (r.flatId && c.flatId === r.flatId)) &&
    c.requestDate === r.checkinDate &&
    !c.isInstructionOnly &&
    c.source !== "manual_instruction" &&
    c.source !== "manual"
  );
  if (cleanReq) {
    if (!cleanReq.manualTwinBeds) cleanReq.twinBeds = false;
    if (!cleanReq.manualExtraMattress) cleanReq.extraMattress = false;
    if (!cleanReq.manualAdminNote) {
      cleanReq.adminNote = null;
      cleanReq.pendingObservation = null;
    }
    cleanReq.arrivingGuest = null;
    cleanReq.autoReservationCode = null;
    cleanReq.autoReservationId = null;
    cleanReq.updatedAt = nowIso;
  }

  // Descarta automaticamente cards de limpeza de check-out não realizados na data de saída da reserva cancelada
  const checkoutDatesToClear = Array.from(new Set([r.checkoutDate, r.earlyCheckoutDate].filter(Boolean)));
  for (const chkDate of checkoutDatesToClear) {
    const hasOtherActiveCheckout = (db.reservations || []).some(other =>
      other.id !== r.id &&
      other.status !== "cancelada" &&
      other.status !== "cancelado" &&
      other.status !== "cancelled" &&
      other.status !== "no_show" &&
      String(other.flatNumber || (db.flats.find(f => f.id === other.flatId)?.number || "")) === flatNum &&
      (other.checkoutDate === chkDate || other.earlyCheckoutDate === chkDate)
    );
    if (!hasOtherActiveCheckout) {
      for (const c of (db.cleaningRequests || [])) {
        const isInst = Boolean(c.isInstructionOnly || c.source === "manual_instruction" || c.type === "instruction" || c.type === "bed_adjustment_only" || c.isBedAdjustmentOnly);
        if (isInst) continue;
        if (
          (String(c.flatNumber) === flatNum || (r.flatId && c.flatId === r.flatId)) &&
          c.requestDate === chkDate &&
          c.source === "checkout" &&
          c.status !== "clean" &&
          c.status !== "deleted" &&
          !c.isDeleted &&
          !c.isVacantExplicitlySet &&
          !c.markedByAdmin
        ) {
          c.isDeleted = true;
          c.status = "deleted";
          c.deletedAt = nowIso;
          c.deletedBy = "reservation_cancelled";
          c.deletedReservationId = r.id;
          c.updatedAt = nowIso;
        }
      }
    }
  }

  // Marca pedidos de café da manhã vinculados como cancelados
  if (!db.breakfastOrders) db.breakfastOrders = [];
  db.breakfastOrders.forEach(o => {
    if ((o.reservationCode && (o.reservationCode === r.code || o.reservationCode === r.reservationCode)) || o.reservationId === r.id || (String(o.roomNumber) === String(r.flatNumber) && o.date >= r.checkinDate && o.date <= r.checkoutDate)) {
      o.status = "cancelled";
      o.cancelReason = "Reserva cancelada no calendário";
    }
  });

  ensureReservationAuditLogs(r);
  const authUser = getAuthUser(req);
  const actorName = authUser ? (authUser.username || authUser.name || "Administrador") : "Administrador";
  const source = req.body?.source || "PMS Calendário (Cancelamento Manual)";

  addReservationAuditLog(r, {
    action: "cancelled",
    actor: {
      id: authUser?.id || null,
      name: actorName,
      role: authUser?.role || "admin",
      type: "user"
    },
    source,
    description: "Reserva cancelada no sistema",
    changes: [{ field: "status", label: "Status da Reserva", oldValue: "Confirmada", newValue: "Cancelada" }]
  });

  r.updatedAt = new Date().toISOString();

  // Cancela reserva no SERPRO FNRH se possuir vínculo ativo
  if (r.serproReservaId && r.serproStatus !== "CANCELADA") {
    const oldSerproId = r.serproReservaId;
    r.serproStatus = "CANCELADA";
    r.serproCancelledAt = new Date().toISOString();
    fnrhSerproService.cancelReserva(oldSerproId, db.settings).catch(err => {
      console.warn(`[FNRH SERPRO] Aviso ao cancelar reserva ${r.code} (${oldSerproId}) no SERPRO:`, err.message);
    });
  }

  // Gatilho B: Notificação de cancelamento para a recepção/portaria (apenas se a portaria já recebeu a reserva)
  if (hasReceptionReceivedReservation(r, db)) {
    try {
      const flat = (db.flats || []).find(f => f.id === r.flatId || String(f.number) === String(r.flatNumber));
      const receptionEmail = flat?.receptionEmail || db.settings?.receptionEmail || db.settings?.buildingEmail || process.env.RECEPTION_EMAIL || "soho@promenade.com.br";
      const changes = [{ field: "status", label: "Status da Reserva", oldValue: "Confirmada", newValue: "CANCELADA" }];
      const { subject, bodyHtml } = renderReservationUpdateEmail({ reservation: r, flat, changes, settings: db.settings });

      sendEmailAsync({
        db,
        saveDatabase,
        reservationId: r.code || r.id,
        recipient: receptionEmail,
        subject,
        bodyHtml,
        type: "email",
        direction: "outbound",
        metadata: {
          trigger: "cancellation",
          flatNumber: r.flatNumber,
          guestName: r.guestName,
          changes
        }
      });
    } catch (mailErr) {
      console.warn("[MailService] Erro ao disparar cancelamento à portaria:", mailErr.message);
    }
  } else {
    console.log(`[MailService ℹ️] Aviso de cancelamento para recepção suprimido: a portaria ainda não recebeu os dados da reserva ${r.code}.`);
  }

  saveDatabase();
  try {
    notifyPmsMutation(db, {
      type: "reservation_cancelled",
      checkinDate: r.checkinDate,
      checkoutDate: r.checkoutDate
    });
  } catch (_) {}
  triggerImmediateWhatsApp(db, saveDatabase, "reservation_cancelled", r);
  res.json({ success: true, message: "Reserva cancelada com sucesso.", calendarSequence: r.calendarSequence });
});

// CRM Guests
// ── PMS Guests CRM Endpoints (Motor 360º com LTV, Tags e Histórico) ─────────

// ── Central de Relatórios de Reservas & Hospedagem (PMS Analytics) ──────────
app.get("/api/pms/analytics/reports", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev")) {
    return res.status(403).json({ error: "Acesso negado. Apenas administradores têm acesso a relatórios analíticos do PMS." });
  }
  const startDate = req.query.startDate || new Date(Date.now() - 30 * 86400000).toISOString().substring(0, 10);
  const endDate = req.query.endDate || new Date().toISOString().substring(0, 10);

  const reservations = db.reservations || [];
  const flats = db.flats || [];
  const totalFlatsCount = flats.length || 10;

  // Calcula quantidade de dias no período
  const d1 = new Date(startDate);
  const d2 = new Date(endDate);
  const totalDaysInPeriod = Math.max(1, Math.round((d2 - d1) / (1000 * 60 * 60 * 24)) + 1);
  const totalAvailableRoomNights = totalFlatsCount * totalDaysInPeriod;

  // Filtra reservas que tocam o período [startDate, endDate]
  const periodReservations = reservations.filter(r => {
    if (r.status === "cancelled" || r.status === "cancelada") return false;
    const inDate = r.checkinDate;
    const outDate = r.checkoutDate || r.checkinDate;
    return outDate >= startDate && inDate <= endDate;
  });

  // Métricas Globais
  let totalRevenue = 0;
  let totalNightsSold = 0;
  const channelCounts = { "Site CorpFlats": 0, "WhatsApp / Balcão": 0, "Booking.com": 0, "Airbnb": 0, "Corporativo B2B": 0 };
  const flatStats = {};

  flats.forEach(f => {
    flatStats[String(f.number)] = {
      flatNumber: String(f.number),
      revenue: 0,
      nightsSold: 0,
      staysCount: 0
    };
  });

  periodReservations.forEach(r => {
    const rev = parseFloat(r.totalAmount || r.totalPrice || r.price || 0) || 0;
    totalRevenue += rev;

    let nights = Number(r.nightsCount || 1);
    if (!r.nightsCount && r.checkinDate && r.checkoutDate) {
      const inD = new Date(r.checkinDate);
      const outD = new Date(r.checkoutDate);
      nights = Math.max(1, Math.round((outD - inD) / (1000 * 60 * 60 * 24)));
    }
    totalNightsSold += nights;

    // Canal de Origem (por diária se houver dailyRates)
    if (Array.isArray(r.dailyRates) && r.dailyRates.length > 0) {
      r.dailyRates.forEach(dr => {
        const dSource = String(dr.channel || r.channel || "").toLowerCase();
        if (dSource.includes("site") || dSource.includes("motor") || dSource.includes("direct")) {
          channelCounts["Site CorpFlats"] += 1;
        } else if (dSource.includes("booking")) {
          channelCounts["Booking.com"] += 1;
        } else if (dSource.includes("airbnb")) {
          channelCounts["Airbnb"] += 1;
        } else if (dSource.includes("corp") || dSource.includes("b2b") || dSource.includes("empresa")) {
          channelCounts["Corporativo B2B"] += 1;
        } else {
          channelCounts["WhatsApp / Balcão"] += 1;
        }
      });
    } else {
      const source = (r.source || r.channel || "").toLowerCase();
      if (source.includes("site") || source.includes("motor") || source.includes("direct")) {
        channelCounts["Site CorpFlats"] += 1;
      } else if (source.includes("booking")) {
        channelCounts["Booking.com"] += 1;
      } else if (source.includes("airbnb")) {
        channelCounts["Airbnb"] += 1;
      } else if (source.includes("corp") || source.includes("b2b") || source.includes("empresa")) {
        channelCounts["Corporativo B2B"] += 1;
      } else {
        channelCounts["WhatsApp / Balcão"] += 1;
      }
    }

    // Flat Stats
    const flatNum = String(r.flatNumber || (r.allocatedFlatNumbers && r.allocatedFlatNumbers[0]) || "");
    if (flatNum) {
      if (!flatStats[flatNum]) {
        flatStats[flatNum] = { flatNumber: flatNum, revenue: 0, nightsSold: 0, staysCount: 0 };
      }
      flatStats[flatNum].revenue += rev;
      flatStats[flatNum].nightsSold += nights;
      flatStats[flatNum].staysCount += 1;
    }
  });

  // Cálculos de Indicadores Hoteleiros (ADR, RevPAR e Ocupação)
  const occupancyRate = totalAvailableRoomNights > 0 ? ((totalNightsSold / totalAvailableRoomNights) * 100) : 0;
  const adr = totalNightsSold > 0 ? (totalRevenue / totalNightsSold) : 0;
  const revPar = totalAvailableRoomNights > 0 ? (totalRevenue / totalAvailableRoomNights) : 0;

  // Entradas (Check-ins) e Saídas (Check-outs) no Período
  const checkinsInPeriod = reservations.filter(r => r.checkinDate >= startDate && r.checkinDate <= endDate && r.status !== "cancelled");
  const checkoutsInPeriod = reservations.filter(r => r.checkoutDate >= startDate && r.checkoutDate <= endDate && r.status !== "cancelled");

  // Ranking de Flats por Receita
  const rankingFlats = Object.values(flatStats).map(f => {
    const flatOccupancy = totalDaysInPeriod > 0 ? ((f.nightsSold / totalDaysInPeriod) * 100) : 0;
    const flatAdr = f.nightsSold > 0 ? (f.revenue / f.nightsSold) : 0;
    return {
      ...f,
      revenue: Number(f.revenue.toFixed(2)),
      occupancyRate: Number(flatOccupancy.toFixed(1)),
      adr: Number(flatAdr.toFixed(2))
    };
  }).sort((a, b) => b.revenue - a.revenue);

  // Previsão Futura (Forecast para os próximos 30 dias a partir de hoje)
  const todayStr = new Date().toISOString().substring(0, 10);
  const future30Str = new Date(Date.now() + 30 * 86400000).toISOString().substring(0, 10);
  const future60Str = new Date(Date.now() + 60 * 86400000).toISOString().substring(0, 10);

  const future30Reservations = reservations.filter(r => r.status !== "cancelled" && r.checkinDate >= todayStr && r.checkinDate <= future30Str);
  const future60Reservations = reservations.filter(r => r.status !== "cancelled" && r.checkinDate >= todayStr && r.checkinDate <= future60Str);

  const forecast30Revenue = future30Reservations.reduce((acc, r) => acc + (parseFloat(r.totalAmount || r.totalPrice || 0) || 0), 0);
  const forecast30Nights = future30Reservations.reduce((acc, r) => acc + (Number(r.nightsCount) || 1), 0);
  const forecast30Occupancy = ((forecast30Nights / (totalFlatsCount * 30)) * 100);

  const forecast60Revenue = future60Reservations.reduce((acc, r) => acc + (parseFloat(r.totalAmount || r.totalPrice || 0) || 0), 0);
  const forecast60Nights = future60Reservations.reduce((acc, r) => acc + (Number(r.nightsCount) || 1), 0);
  const forecast60Occupancy = ((forecast60Nights / (totalFlatsCount * 60)) * 100);

  res.json({
    period: { startDate, endDate, totalDaysInPeriod, totalAvailableRoomNights },
    metrics: {
      totalRevenue: Number(totalRevenue.toFixed(2)),
      totalNightsSold,
      totalStays: periodReservations.length,
      occupancyRate: Number(occupancyRate.toFixed(1)),
      adr: Number(adr.toFixed(2)),
      revPar: Number(revPar.toFixed(2))
    },
    checkins: checkinsInPeriod.map(r => ({
      id: r.id,
      guestName: r.guestName,
      guestPhone: r.guestPhone,
      flatNumber: r.flatNumber,
      checkinDate: r.checkinDate,
      checkoutDate: r.checkoutDate,
      totalAmount: r.totalAmount || r.totalPrice,
      status: r.status,
      isSmoker: Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked),
      smokerGuestAlert: Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked),
      guestSmoked: Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked)
    })),
    checkouts: checkoutsInPeriod.map(r => ({
      id: r.id,
      guestName: r.guestName,
      guestPhone: r.guestPhone,
      flatNumber: r.flatNumber,
      checkinDate: r.checkinDate,
      checkoutDate: r.checkoutDate,
      totalAmount: r.totalAmount || r.totalPrice,
      status: r.status,
      isSmoker: Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked),
      smokerGuestAlert: Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked),
      guestSmoked: Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked)
    })),
    rankingFlats,
    channels: Object.entries(channelCounts).map(([channel, count]) => ({ channel, count })),
    forecast: {
      next30Days: {
        confirmedRevenue: Number(forecast30Revenue.toFixed(2)),
        confirmedNights: forecast30Nights,
        occupancyRate: Number(forecast30Occupancy.toFixed(1)),
        reservationsCount: future30Reservations.length
      },
      next60Days: {
        confirmedRevenue: Number(forecast60Revenue.toFixed(2)),
        confirmedNights: forecast60Nights,
        occupancyRate: Number(forecast60Occupancy.toFixed(1)),
        reservationsCount: future60Reservations.length
      }
    }
  });
});

app.get("/api/pms/guests", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev" && userAuth.role !== "reception" && userAuth.role !== "recepcao")) {
    return res.status(403).json({ error: "Acesso negado. Apenas administradores e recepção têm acesso à base de hóspedes." });
  }
  if (!db.guests) db.guests = [];
  const now = Date.now();
  if (
    cachedEnrichedGuests &&
    cachedEnrichedGuestsSource === db.guests &&
    cachedEnrichedGuestsLength === db.guests.length &&
    now - cachedEnrichedGuestsTimestamp < 15000
  ) {
    return res.json(cachedEnrichedGuests);
  }
  if (isGuestReconciliationDirty && (now - lastGuestReconcileTimestamp >= GUEST_RECONCILE_COOLDOWN_MS)) {
    setImmediate(() => {
      try { reconcileAndMergeGuests(db); } catch (_) {}
    });
  }
  const reservations = db.reservations || [];
  const invoices = db.invoices || [];
  const allMinibarOrders = Array.isArray(db.minibarOrders) ? db.minibarOrders : [];
  const companiesById = new Map((db.companies || []).map(c => [Number(c.id), c]));

  const addToMapList = (map, key, val) => {
    if (!key) return;
    let arr = map.get(key);
    if (!arr) {
      arr = [];
      map.set(key, arr);
    }
    arr.push(val);
  };

  const resByGuestId = new Map();
  const resByDoc = new Map();
  const resByPhone = new Map();
  const resByEmail = new Map();
  const resByName = new Map();
  for (const r of reservations) {
    if (!r) continue;
    if (r.guestId) addToMapList(resByGuestId, r.guestId, r);
    const rDoc = (r.guestDocument || r.document || "").replace(/\D/g, "");
    if (rDoc) addToMapList(resByDoc, rDoc, r);
    if (Array.isArray(r.guests)) {
      for (const rg of r.guests) {
        const rgCpf = (rg?.cpf || "").replace(/\D/g, "");
        if (rgCpf && rgCpf !== rDoc) addToMapList(resByDoc, rgCpf, r);
      }
    }
    const rPhone = normalizePhone(r.guestPhone || "");
    if (rPhone && rPhone.length >= 8) addToMapList(resByPhone, rPhone, r);
    const rEmail = (r.guestEmail || "").trim().toLowerCase();
    if (rEmail && rEmail.includes("@")) addToMapList(resByEmail, rEmail, r);
    const rName = normalizeName(r.guestName || "");
    if (rName && rName.length >= 5) addToMapList(resByName, rName, r);
  }

  const invByDoc = new Map();
  const invByName = new Map();
  for (const inv of invoices) {
    if (!inv) continue;
    const invDoc = (inv.tomadorCpfCnpj || "").replace(/\D/g, "");
    if (invDoc) addToMapList(invByDoc, invDoc, inv);
    const invName = normalizeName(inv.tomadorNome || "");
    if (invName) addToMapList(invByName, invName, inv);
  }

  const mbByDoc = new Map();
  const mbByPhone = new Map();
  const mbByResCode = new Map();
  const mbByResId = new Map();
  const mbByName = new Map();
  for (const o of allMinibarOrders) {
    if (!o) continue;
    const oDoc = (o.guestDocument || "").replace(/\D/g, "");
    if (oDoc) addToMapList(mbByDoc, oDoc, o);
    const oPhone = normalizePhone(o.guestPhone || "");
    if (oPhone && oPhone.length >= 8) addToMapList(mbByPhone, oPhone, o);
    if (o.reservationCode) addToMapList(mbByResCode, o.reservationCode, o);
    if (o.reservationId) addToMapList(mbByResId, String(o.reservationId), o);
    const oName = normalizeName(o.guestName || "");
    if (oName && oName.length >= 5) addToMapList(mbByName, oName, o);
  }

  const statusPriority = (st) => {
    const s = String(st || "").toLowerCase();
    if (s === "hospedado" || s === "checked_in" || s === "in_house") return 100;
    if (s === "confirmada" || s === "confirmed") return 80;
    if (s === "pre_reserva" || s === "pendente" || s === "pending") return 50;
    return 10;
  };

  // Mapeia e enriquece cada hóspede com métricas 360º e dados de check-in digital em tempo real
  const enrichedGuests = db.guests.map(g => {
    const cleanDoc = (g.documentNumber || g.document || "").replace(/\D/g, "");
    const cleanPhone = normalizePhone(g.phone || "");
    const cleanEmail = (g.email || "").trim().toLowerCase();
    const guestNameLower = normalizeName(g.fullName || g.name || "");

    // Localiza todas as reservas deste hóspede via índices em memória O(1)
    const guestNameTokenCount = guestNameLower.split(/\s+/).filter(Boolean).length;
    const candResSet = new Set();
    const appendResCands = (arr) => { if (arr) for (const item of arr) candResSet.add(item); };
    if (g.id) appendResCands(resByGuestId.get(g.id));
    if (cleanDoc) appendResCands(resByDoc.get(cleanDoc));
    if (cleanPhone && cleanPhone.length >= 8) appendResCands(resByPhone.get(cleanPhone));
    if (cleanEmail && cleanEmail.includes("@")) appendResCands(resByEmail.get(cleanEmail));
    if (guestNameLower && guestNameTokenCount >= 2 && guestNameLower.length >= 5) appendResCands(resByName.get(guestNameLower));

    const guestReservations = [];
    for (const r of candResSet) {
      if (areGuestNamesCompatible(r.guestName, g.fullName || g.name)) {
        guestReservations.push(r);
      }
    }

    // Localiza todas as notas fiscais emitidas para este hóspede via índice O(1)
    const candInvSet = new Set();
    if (cleanDoc) {
      const byD = invByDoc.get(cleanDoc);
      if (byD) for (const inv of byD) candInvSet.add(inv);
    }
    if (guestNameLower) {
      const byN = invByName.get(guestNameLower);
      if (byN) for (const inv of byN) candInvSet.add(inv);
    }
    const guestInvoices = Array.from(candInvSet);

    // Cálculos de LTV e Métricas de Hospedagem
    let totalSpent = 0;
    let totalNights = 0;
    const flatFrequency = {};

    guestReservations.forEach(r => {
      const val = parseFloat(r.totalAmount || r.totalPrice || r.price || 0) || 0;
      totalSpent += val;

      if (r.nightsCount) {
        totalNights += Number(r.nightsCount);
      } else if (r.checkinDate && r.checkoutDate) {
        const d1 = new Date(r.checkinDate);
        const d2 = new Date(r.checkoutDate);
        const diff = Math.max(1, Math.round((d2 - d1) / (1000 * 60 * 60 * 24)));
        totalNights += diff;
      } else {
        totalNights += 1;
      }

      if (r.flatNumber) {
        flatFrequency[r.flatNumber] = (flatFrequency[r.flatNumber] || 0) + 1;
      }
    });

    // Se não tiver reservas mas tiver notas emitidas
    if (totalSpent === 0 && guestInvoices.length > 0) {
      guestInvoices.forEach(inv => {
        totalSpent += parseFloat(inv.valorServico || 0) || 0;
        totalNights += Number(inv.quantidadeDiarias || 1);
        if (inv.flatNumber) {
          flatFrequency[inv.flatNumber] = (flatFrequency[inv.flatNumber] || 0) + 1;
        }
      });
    }

    // Localiza pedidos de frigobar deste hóspede via índices O(1)
    const candMbSet = new Set();
    const appendMbCands = (arr) => { if (arr) for (const item of arr) candMbSet.add(item); };
    if (cleanDoc) appendMbCands(mbByDoc.get(cleanDoc));
    if (cleanPhone && cleanPhone.length >= 8) appendMbCands(mbByPhone.get(cleanPhone));
    for (const r of guestReservations) {
      if (r.code) appendMbCands(mbByResCode.get(r.code));
      if (r.id !== undefined && r.id !== null) appendMbCands(mbByResId.get(String(r.id)));
    }
    if (guestNameLower && guestNameLower.length >= 5) appendMbCands(mbByName.get(guestNameLower));
    const guestMinibarOrders = Array.from(candMbSet);

    // Filtra pedidos de frigobar pagos para somar ao LTV e gerar tags de preferência
    const paidMinibarOrders = guestMinibarOrders.filter(o => o.paymentStatus === "pago");
    let minibarSpent = 0;
    let nespressoQty = 0;
    let beerQty = 0;
    let snacksQty = 0;
    let totalMinibarPaidUnits = 0;

    paidMinibarOrders.forEach(o => {
      minibarSpent += parseFloat(o.totalAmount || 0) || 0;
      (o.items || []).forEach(it => {
        const qty = Number(it.quantity) || 0;
        totalMinibarPaidUnits += qty;
        const pId = (it.productId || "").toLowerCase();
        const pName = (it.productName || "").toLowerCase();

        if (pId.includes("nespresso") || pName.includes("nespresso") || pName.includes("cápsula") || pName.includes("capsula")) {
          nespressoQty += qty;
        }
        if (pId.includes("cerveja") || pName.includes("cerveja") || pName.includes("heineken") || pName.includes("stella") || pName.includes("corona") || pId.includes("beer")) {
          beerQty += qty;
        }
        if (pId.includes("snack") || pId.includes("amendoim") || pId.includes("castanha") || pId.includes("chocolate") || pName.includes("snack") || pName.includes("amendoim") || pName.includes("castanha") || pName.includes("chocolate") || pName.includes("batata") || pName.includes("pringles")) {
          snacksQty += qty;
        }
      });
    });

    // LTV Agregado: Diárias de Hospedagem + Consumo de Frigobar Pago
    totalSpent += minibarSpent;

    // Identifica o flat mais frequente
    let favoriteFlat = "";
    let maxFlatCount = 0;
    for (const [flat, count] of Object.entries(flatFrequency)) {
      if (count > maxFlatCount) {
        maxFlatCount = count;
        favoriteFlat = flat;
      }
    }

    const totalStays = Math.max(guestReservations.length, g.totalStays || (guestInvoices.length > 0 ? guestInvoices.length : 0));
    const averageTicket = totalStays > 0 ? (totalSpent / totalStays) : 0;

    // Geração de Tags Automáticas Inteligentes
    const tags = Array.isArray(g.tags) ? [...g.tags] : [];
    if (totalSpent >= 2000 || totalStays >= 5) {
      if (!tags.includes("VIP")) tags.push("VIP");
    }
    if (totalStays >= 2 && !tags.includes("Recorrente")) {
      tags.push("Recorrente");
    }
    if (g.companyId && !tags.includes("Corporativo")) {
      tags.push("Corporativo");
    }
    if (g.hasPet && !tags.includes("Pet")) {
      tags.push("Pet");
    }
    // Tags dinâmicas de hábitos de consumo de frigobar (F29)
    if (nespressoQty >= 3 && !tags.includes("Consumidor Nespresso")) {
      tags.push("Consumidor Nespresso");
    }
    if (beerQty >= 2 && !tags.includes("Apreciador Cerveja")) {
      tags.push("Apreciador Cerveja");
    }
    if (snacksQty >= 3 && !tags.includes("Prefere Snacks")) {
      tags.push("Prefere Snacks");
    }
    if ((minibarSpent >= 100 || totalMinibarPaidUnits >= 8) && !tags.includes("Consumo Alto")) {
      tags.push("Consumo Alto");
    }

    // Verifica se possui empresa parceira associada
    let companyName = g.companyName || "";
    if (g.companyId) {
      const comp = companiesById.get(Number(g.companyId));
      if (comp) companyName = comp.tradeName || comp.corporateName;
    }

    // Última data de estadia
    let lastStayDate = g.lastStayDate || "";
    if (guestReservations.length > 0) {
      const sortedRes = [...guestReservations].sort((a, b) => new Date(b.checkoutDate || b.checkinDate).getTime() - new Date(a.checkoutDate || a.checkinDate).getTime());
      lastStayDate = sortedRes[0].checkoutDate || sortedRes[0].checkinDate;
    }

    // Backfill de foto e endereço do check-in digital se disponível em alguma estadia
    let photoUrl = g.photoUrl || null;
    let docPhotoUrl = g.docPhotoUrl || null;
    let signatureUrl = g.signatureUrl || null;
    for (const r of guestReservations) {
      if (!photoUrl && (r.selfieUrl || r.photoUrl)) photoUrl = r.selfieUrl || r.photoUrl;
      if (!docPhotoUrl && (r.docPhotoUrl || r.documentPhotoUrl)) docPhotoUrl = r.docPhotoUrl || r.documentPhotoUrl;
      if (!signatureUrl && r.signatureUrl) signatureUrl = r.signatureUrl;
    }

    let rawGuestStreet = String(g.street || g.logradouro || g.address || "").trim();
    let rawGuestNum = String(g.streetNumber || g.number || g.numero || "").trim();
    let rawGuestComp = String(g.complement || g.complemento || "").trim();
    let rawGuestBairro = String(g.neighborhood || g.bairro || "").trim();
    let rawGuestCep = String(g.cep || "").replace(/\D/g, "");
    let rawGuestCity = String(g.city || g.cidade || "").replace(/\s*\/\s*[A-Za-z]{2}\s*$/, "").trim();
    let rawGuestState = String(g.state || g.uf || "").trim().toUpperCase();
    for (const r of guestReservations) {
      const rSt = String(r.guestStreet || r.street || r.guestAddress || r.address || r.guests?.[0]?.street || r.guests?.[0]?.address || "").trim();
      const rNum = String(r.guestStreetNumber || r.streetNumber || r.number || r.guests?.[0]?.streetNumber || r.guests?.[0]?.number || "").trim();
      const rComp = String(r.guestComplement || r.complement || r.guests?.[0]?.complement || "").trim();
      const rBairro = String(r.guestNeighborhood || r.neighborhood || r.guests?.[0]?.neighborhood || "").trim();
      const rCep = String(r.guestCep || r.cep || r.guests?.[0]?.cep || "").replace(/\D/g, "");
      const rCity = String(r.guestCity || r.city || r.guests?.[0]?.city || "").replace(/\s*\/\s*[A-Za-z]{2}\s*$/, "").trim();
      const rState = String(r.guestState || r.state || r.guests?.[0]?.state || "").trim().toUpperCase();
      if ((!rawGuestStreet || isGenericPelincaAddr(rawGuestStreet)) && rSt && !isGenericPelincaAddr(rSt)) rawGuestStreet = rSt;
      if ((!rawGuestNum || rawGuestNum === "100") && rNum && !(rNum === "100" && (!rSt || isGenericPelincaAddr(rSt)))) rawGuestNum = rNum;
      if (!rawGuestComp && rComp) rawGuestComp = rComp;
      if ((!rawGuestBairro || isGenericPelincaBairro(rawGuestBairro)) && rBairro && !isGenericPelincaBairro(rBairro)) rawGuestBairro = rBairro;
      if ((!rawGuestCep || isGenericPelincaCep(rawGuestCep)) && rCep && !isGenericPelincaCep(rCep)) rawGuestCep = rCep;
      if (!rawGuestCity && rCity) rawGuestCity = rCity;
      if (!rawGuestState && rState) rawGuestState = rState;
    }
    if (isGenericPelincaAddr(rawGuestStreet) && (!rawGuestNum || rawGuestNum === "100")) {
      rawGuestStreet = "";
      if (rawGuestNum === "100") rawGuestNum = "";
    }
    if (!rawGuestStreet && isGenericPelincaBairro(rawGuestBairro)) rawGuestBairro = "";
    if (!rawGuestStreet && isGenericPelincaCep(rawGuestCep)) rawGuestCep = "";
    if (!rawGuestStreet && !rawGuestCep && /^campos(\s+dos\s+go[yi]tacazes)?$/i.test(rawGuestCity) && g.isCamposResident !== true) {
      rawGuestCity = "";
      if (rawGuestState === "RJ") rawGuestState = "";
    }

    // Cálculo O(1) direto do callerIdPreview sem varrer todos os hóspedes
    const activeGuestRes = guestReservations
      .filter(r => r && r.status !== "cancelada" && r.status !== "cancelled")
      .sort((a, b) => {
        const pDiff = statusPriority(b.status) - statusPriority(a.status);
        if (pDiff !== 0) return pDiff;
        const dB = new Date(b.checkinDate || b.createdAt || 0).getTime();
        const dA = new Date(a.checkinDate || a.createdAt || 0).getTime();
        return dB - dA;
      })[0] || null;
    const rawCallerFlat = String(
      activeGuestRes?.flatNumber ||
      activeGuestRes?.unitNumber ||
      g.activeFlat ||
      favoriteFlat ||
      ""
    ).trim();
    const cleanCallerFlatNum = rawCallerFlat.replace(/^(uh|flat|apt|apto)\s*/i, "").trim();
    const callerUnitLabel = cleanCallerFlatNum ? `UH ${cleanCallerFlatNum}` : "";
    const callerCompanyName = String(companyName || g.companyData?.companyName || activeGuestRes?.companyData?.companyName || "").trim();
    const callerIsMonthly = Boolean(g.isMonthlyGuest || g.clientType === "mensalista" || activeGuestRes?.isMonthlyGuest);
    let callerMiddleBadge = "CorpFlats";
    if (callerCompanyName && callerIsMonthly) {
      callerMiddleBadge = `${callerCompanyName} (Mensalista)`;
    } else if (callerCompanyName) {
      callerMiddleBadge = callerCompanyName;
    } else if (callerIsMonthly) {
      callerMiddleBadge = "Mensalista";
    }
    const callerIdPreview = `${String(g.fullName || g.name || "Hóspede").trim()} • ${callerMiddleBadge}${callerUnitLabel ? ` [${callerUnitLabel}]` : ""}`;

    return {
      ...g,
      fullName: g.fullName || g.name || "Hóspede",
      name: g.fullName || g.name || "Hóspede",
      documentNumber: cleanDoc,
      document: cleanDoc,
      phone: g.phone || g.phoneNumber || "",
      email: g.email || "",
      guestCode: g.guestCode || (g.id ? `HOSP-${String(g.id).padStart(5, "0")}` : ""),
      photoUrl,
      docPhotoUrl,
      signatureUrl,
      birthDate: g.birthDate || "",
      gender: g.gender || "",
      address: rawGuestStreet,
      street: rawGuestStreet,
      logradouro: rawGuestStreet,
      streetNumber: rawGuestNum,
      number: rawGuestNum,
      numero: rawGuestNum,
      complement: rawGuestComp,
      neighborhood: rawGuestBairro,
      cep: rawGuestCep,
      city: rawGuestCity,
      state: rawGuestState,
      vehiclePlate: g.vehiclePlate || "",
      vehicleModel: g.vehicleModel || "",
      vehicleBrand: g.vehicleBrand || "",
      vehicleColor: g.vehicleColor || "",
      fnhrCompleted: Boolean(g.fnhrCompleted),
      fnhrCompletedAt: g.fnhrCompletedAt || null,
      aiVerification: g.aiVerification || null,
      totalSpent: Number(totalSpent.toFixed(2)),
      totalStays,
      totalNights,
      averageTicket: Number(averageTicket.toFixed(2)),
      favoriteFlat,
      lastStayDate,
      tags: Array.from(new Set(tags)),
      companyName,
      invoicesCount: guestInvoices.length,
      reservationsCount: guestReservations.length,
      minibarSpent: Number(minibarSpent.toFixed(2)),
      minibarOrdersCount: guestMinibarOrders.length,
      callerIdPreview,
      googleContactResourceName: g.googleContactResourceName || null,
      googleContactSyncedAt: g.googleContactSyncedAt || null,
      googleContactDisplayName: g.googleContactDisplayName || null
    };
  });

  enrichedGuests.sort((a, b) => (b.totalSpent || 0) - (a.totalSpent || 0));
  cachedEnrichedGuests = enrichedGuests;
  cachedEnrichedGuestsSource = db.guests;
  cachedEnrichedGuestsLength = db.guests.length;
  cachedEnrichedGuestsTimestamp = Date.now();
  res.json(enrichedGuests);
});

// ── INTEGRAÇÃO GOOGLE CONTATOS (GOOGLE PEOPLE API v1 + vCARD CALLER ID) ─────
function ensureGoogleContactsConfig(database) {
  const targetDb = database || db;
  const defaultClientId = process.env.GOOGLE_CLIENT_ID || targetDb.siteConfig?.authConfig?.googleClientId || "";
  const defaultClientSecret = process.env.GOOGLE_CLIENT_SECRET || "";
  if (!targetDb.googleContactsConfig || typeof targetDb.googleContactsConfig !== "object") {
    targetDb.googleContactsConfig = {
      enabled: true,
      clientId: defaultClientId,
      clientSecret: defaultClientSecret,
      accessToken: process.env.GOOGLE_CONTACTS_ACCESS_TOKEN || "",
      refreshToken: process.env.GOOGLE_CONTACTS_REFRESH_TOKEN || "",
      tokenExpiresAt: 0,
      connectedEmail: "",
      connectedName: "",
      connectedPicture: "",
      lastSyncAt: null,
      totalSyncedCount: 0,
      syncLogs: []
    };
  }
  if (!targetDb.googleContactsConfig.clientId && defaultClientId) {
    targetDb.googleContactsConfig.clientId = defaultClientId;
  }
  if (!targetDb.googleContactsConfig.clientSecret && defaultClientSecret) {
    targetDb.googleContactsConfig.clientSecret = defaultClientSecret;
  }
  if (!Array.isArray(targetDb.googleContactsConfig.syncLogs)) {
    targetDb.googleContactsConfig.syncLogs = [];
  }
  return targetDb.googleContactsConfig;
}

export function expandBrazilianPhoneVariants(rawPhonesList) {
  const variants = [];
  const e164Only = [];
  const suffixKeys = new Set();
  const seen = new Set();

  const addVar = (val, isE164 = false) => {
    const clean = String(val || "").trim();
    if (!clean || seen.has(clean)) return;
    seen.add(clean);
    variants.push(clean);
    if (isE164) e164Only.push(clean);
  };

  for (const raw of (rawPhonesList || [])) {
    const str = String(raw || "").trim();
    if (!str) continue;
    let digits = str.replace(/\D/g, "");
    if (digits.length < 8) continue;

    // Número internacional não-brasileiro (começa com + e não é +55)
    if (str.startsWith("+") && !digits.startsWith("55")) {
      addVar(`+${digits}`, true);
      suffixKeys.add(digits);
      continue;
    }

    if (digits.startsWith("55") && digits.length >= 12) {
      digits = digits.slice(2);
    }
    if (digits.startsWith("0") && (digits.length === 11 || digits.length === 12)) {
      digits = digits.slice(1);
    }
    if (digits.length === 8 || digits.length === 9) {
      digits = `22${digits}`;
    }

    if (digits.length === 11) {
      const ddd = digits.slice(0, 2);
      const local9 = digits.slice(2); // 9 dígitos (ex: 998887766)
      const local8 = local9.startsWith("9") ? local9.slice(1) : local9.slice(-8);
      suffixKeys.add(`${ddd}${local9}`);
      suffixKeys.add(`${ddd}${local8}`);
      // 1) E.164 com 9º dígito (+55DD9XXXXXXXX) -> Chamadas de celular e WhatsApp DDD 11-28
      addVar(`+55${ddd}${local9}`, true);
      // 2) E.164 sem 9º dígito (+55DDXXXXXXXX) -> Crítico para WhatsApp em DDDs 31-99 (MG, BA, PE, RN, Sul, etc.) e contas antigas!
      addVar(`+55${ddd}${local8}`, true);
      // 3) Formato nacional DDD -> Discadores nativos de operadoras
      addVar(`(${ddd}) ${local9.slice(0, 5)}-${local9.slice(5)}`, false);
    } else if (digits.length === 10) {
      const ddd = digits.slice(0, 2);
      const local8 = digits.slice(2); // 8 dígitos
      const firstLocal = local8[0];
      // No Brasil, celulares têm inicial 6, 7, 8 ou 9; fixos têm inicial 2, 3, 4 ou 5
      if (["6", "7", "8", "9"].includes(firstLocal)) {
        const local9 = `9${local8}`;
        suffixKeys.add(`${ddd}${local9}`);
        suffixKeys.add(`${ddd}${local8}`);
        // 1) E.164 com o 9º dígito restaurado (+55DD9XXXXXXXX)
        addVar(`+55${ddd}${local9}`, true);
        // 2) E.164 sem o 9º dígito (+55DDXXXXXXXX)
        addVar(`+55${ddd}${local8}`, true);
        // 3) Formato nacional com 9º dígito
        addVar(`(${ddd}) ${local9.slice(0, 5)}-${local9.slice(5)}`, false);
      } else {
        // Telefone fixo
        suffixKeys.add(`${ddd}${local8}`);
        addVar(`+55${ddd}${local8}`, true);
        addVar(`(${ddd}) ${local8.slice(0, 4)}-${local8.slice(4)}`, false);
      }
    } else {
      addVar(`+55${digits}`, true);
      if (digits.length >= 10) {
        suffixKeys.add(digits.slice(-11));
        suffixKeys.add(digits.slice(-10));
      } else {
        suffixKeys.add(digits);
      }
    }
  }

  return {
    variants,
    e164Only,
    primaryE164: e164Only[0] || "",
    suffixKeys: Array.from(suffixKeys)
  };
}

export function buildGuestCallerIdContactData(database, guest) {
  const targetDb = database || db;
  const g = guest || {};
  const fullName = String(g.fullName || g.name || "Hóspede").trim();
  const cleanDoc = String(g.documentNumber || g.document || "").replace(/\D/g, "");
  const docType = String(g.docType || (cleanDoc.length > 11 ? "CNPJ" : "CPF")).toUpperCase();
  const rawPhone = String(g.phone || g.phoneNumber || "").trim();

  const cleanEmail = String(g.email || "").trim().toLowerCase();
  const guestNameNorm = normalizeName(fullName);

  // Busca reservas vinculadas para descobrir UH ativa ou mais recente e todos os telefones associados
  const allReservations = Array.isArray(targetDb?.reservations) ? targetDb.reservations : [];
  const guestNameTokenCount = guestNameNorm.split(/\s+/).filter(Boolean).length;
  const guestReservations = allReservations.filter(r => {
    if (!r || r.status === "cancelada" || r.status === "cancelled") return false;
    if (!areGuestNamesCompatible(fullName, r.guestName)) return false;
    const resDoc = String(r.guestDocument || r.document || "").replace(/\D/g, "");
    const resPhone = normalizePhone(r.guestPhone || r.phone || "");
    const gPhoneNorm = normalizePhone(rawPhone);
    const resEmail = String(r.guestEmail || r.email || "").trim().toLowerCase();
    const resName = normalizeName(r.guestName || "");
    return (r.guestId && g.id && Number(r.guestId) === Number(g.id)) ||
           (cleanDoc && cleanDoc.length >= 8 && resDoc === cleanDoc) ||
           (gPhoneNorm && gPhoneNorm.length >= 8 && phonesMatch(resPhone, gPhoneNorm)) ||
           (cleanEmail && cleanEmail.includes("@") && resEmail === cleanEmail) ||
           (guestNameNorm && guestNameTokenCount >= 2 && guestNameNorm.length >= 5 && resName === guestNameNorm && (!r.guestId || !g.id || Number(r.guestId) === Number(g.id)));
  });

  // Prioriza reserva ativa (hospedado / checked_in / confirmada) ou a mais recente
  const statusPriority = (st) => {
    const s = String(st || "").toLowerCase();
    if (s === "hospedado" || s === "checked_in" || s === "in_house") return 100;
    if (s === "confirmada" || s === "confirmed") return 80;
    if (s === "pre_reserva" || s === "pendente" || s === "pending") return 50;
    return 10;
  };
  const sortedRes = [...guestReservations].sort((a, b) => {
    const pDiff = statusPriority(b.status) - statusPriority(a.status);
    if (pDiff !== 0) return pDiff;
    const dB = new Date(b.checkinDate || b.createdAt || 0).getTime();
    const dA = new Date(a.checkinDate || a.createdAt || 0).getTime();
    return dB - dA;
  });

  const activeRes = sortedRes[0] || null;

  const isPhoneOwnedByIncompatibleGuest = (candPhone) => {
    if (!candPhone || !Array.isArray(targetDb?.guests)) return false;
    const normCand = normalizePhone(candPhone);
    if (!normCand || normCand.length < 8) return false;
    const candidates = (targetDb === db && getGuestIndexes().guestsByPhoneSuffix8)
      ? (getGuestIndexes().guestsByPhoneSuffix8.get(normCand.slice(-8)) || [])
      : targetDb.guests;
    return candidates.some(other =>
      other &&
      other.id !== g.id &&
      other.phone &&
      phonesMatch(other.phone, candPhone) &&
      !areGuestNamesCompatible(fullName, other.fullName || other.name)
    );
  };

  // Coleta telefones pertencentes ESTRITAMENTE a este hóspede (cadastro CRM, additionalPhones verificados e reservas com mesmo titular)
  const rawPhonesCandidateList = [];
  if (rawPhone && !isPhoneOwnedByIncompatibleGuest(rawPhone)) {
    rawPhonesCandidateList.push(rawPhone);
  }
  if (Array.isArray(g.additionalPhones)) {
    for (const ap of g.additionalPhones) {
      if (ap && !isPhoneOwnedByIncompatibleGuest(ap)) {
        rawPhonesCandidateList.push(ap);
      }
    }
  }
  for (const r of sortedRes) {
    const rp = r.guestPhone || r.phone;
    if (rp && areGuestNamesCompatible(r.guestName, fullName) && !isPhoneOwnedByIncompatibleGuest(rp)) {
      rawPhonesCandidateList.push(rp);
    }
  }

  const expandedPhones = expandBrazilianPhoneVariants(rawPhonesCandidateList);
  const e164Phone = expandedPhones.primaryE164;
  const phoneDigits = e164Phone.replace(/\D/g, "");
  const rawFlat = String(
    activeRes?.flatNumber ||
    activeRes?.unitNumber ||
    g.activeFlat ||
    g.favoriteFlat ||
    ""
  ).trim();
  const cleanFlatNum = rawFlat.replace(/^(uh|flat|apt|apto)\s*/i, "").trim();
  const unitLabel = cleanFlatNum ? `UH ${cleanFlatNum}` : "";
  const activeResCode = activeRes?.code || "";

  // Empresa e Tipo (Mensalista / Avulso)
  let companyName = String(g.companyName || g.companyData?.companyName || activeRes?.companyData?.companyName || "").trim();
  let companyCnpj = String(g.companyData?.cnpj || activeRes?.companyData?.cnpj || "").trim();
  if (!companyName && g.companyId && Array.isArray(targetDb?.companies)) {
    const comp = targetDb.companies.find(c => Number(c.id) === Number(g.companyId));
    if (comp) {
      companyName = String(comp.tradeName || comp.corporateName || "").trim();
      if (!companyCnpj && comp.cnpj) companyCnpj = String(comp.cnpj).trim();
    }
  }

  const isMonthly = Boolean(g.isMonthlyGuest || g.clientType === "mensalista" || activeRes?.isMonthlyGuest);
  const clientTypeLabel = isMonthly ? "Mensalista" : "Hóspede Avulso";

  // Formato escolhido para o visor do celular (Caller ID):
  // "Nome + Empresa/Tipo + UH ativa (ex: João Silva • Petrobras [UH 204])"
  let middleBadge = "CorpFlats";
  if (companyName && isMonthly) {
    middleBadge = `${companyName} (Mensalista)`;
  } else if (companyName) {
    middleBadge = companyName;
  } else if (isMonthly) {
    middleBadge = "Mensalista";
  }

  const displayName = `${fullName} • ${middleBadge}${unitLabel ? ` [${unitLabel}]` : ""}`;

  // Campo Organização / Cargo do Google Contatos
  const organizationName = companyName ? `${companyName} • CorpFlats` : "CorpFlats";
  const jobTitleParts = [clientTypeLabel];
  if (unitLabel) jobTitleParts.push(unitLabel);
  if (activeResCode) jobTitleParts.push(activeResCode);
  const jobTitle = jobTitleParts.join(" • ");

  // Data de nascimento nativa
  let birthDateIso = "";
  let birthDateObj = null;
  if (g.birthDate) {
    const bStr = String(g.birthDate).trim();
    const isoMatch = bStr.match(/^(\d{4})-(\d{2})-(\d{2})/);
    const brMatch = bStr.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
    if (isoMatch) {
      birthDateIso = `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
      birthDateObj = { year: Number(isoMatch[1]), month: Number(isoMatch[2]), day: Number(isoMatch[3]) };
    } else if (brMatch) {
      birthDateIso = `${brMatch[3]}-${brMatch[2]}-${brMatch[1]}`;
      birthDateObj = { year: Number(brMatch[3]), month: Number(brMatch[2]), day: Number(brMatch[1]) };
    }
  }

  // Cidade/UF, Veículo, Tags e Observações/Alertas nas Notas do contato
  const city = String(g.city || g.cidade || "").replace(/\s*\/\s*[A-Za-z]{2}\s*$/, "").trim();
  const state = String(g.state || g.uf || "").trim().toUpperCase();
  const cityState = city ? `${city}${state ? `/${state}` : ""}` : "";

  const vehiclePlate = String(g.vehicle?.plate || g.vehiclePlate || g.preferences?.vehiclePlate || activeRes?.vehiclePlate || "").toUpperCase().trim();
  const vehicleBrand = String(g.vehicle?.brand || g.vehicleBrand || "").trim();
  const vehicleModel = String(g.vehicle?.model || g.vehicleModel || "").trim();
  const vehicleColor = String(g.vehicle?.color || g.vehicleColor || "").trim();
  const vehicleDetails = [vehicleBrand, vehicleModel, vehicleColor].filter(Boolean).join(" ");

  const tags = Array.isArray(g.tags) ? g.tags.filter(Boolean) : [];
  const guestCode = g.guestCode || (g.id ? `HOSP-${String(g.id).padStart(5, "0")}` : "CRM");

  const notesLines = [
    `📋 Código CRM: ${guestCode} | Perfil: ${clientTypeLabel}`
  ];
  if (companyName) {
    notesLines.push(`🏢 Empresa: ${companyName}${companyCnpj ? ` (CNPJ: ${companyCnpj})` : ""}`);
  }
  if (unitLabel || activeResCode) {
    notesLines.push(`🏨 Unidade/Reserva: ${[unitLabel, activeResCode ? `Reserva ${activeResCode}` : ""].filter(Boolean).join(" • ")}`);
  }
  if (cleanDoc) {
    notesLines.push(`🪪 ${docType}: ${cleanDoc}`);
  }
  if (cityState) {
    notesLines.push(`📍 Cidade/UF: ${cityState}`);
  }
  if (vehiclePlate) {
    notesLines.push(`🚗 Veículo: ${vehiclePlate}${vehicleDetails ? ` (${vehicleDetails})` : ""}`);
  }
  if (tags.length > 0) {
    notesLines.push(`🏷️ Tags: ${tags.join(", ")}`);
  }
  const alertsAndNotes = [
    g.riskAttentionAlert && g.riskAttentionReason ? `ALERTA: ${g.riskAttentionReason}` : "",
    g.notes ? String(g.notes).trim() : "",
    g.preferences?.breakfastNotes ? `Café: ${g.preferences.breakfastNotes}` : ""
  ].filter(Boolean).join(" | ");
  if (alertsAndNotes) {
    notesLines.push(`⚠️ Observações CRM: ${alertsAndNotes}`);
  }

  if (expandedPhones.e164Only.length > 1) {
    notesLines.push(`📞 Telefones vinculados: ${expandedPhones.e164Only.join(" / ")}`);
  }

  const notesText = notesLines.join("\n");

  return {
    guestId: g.id,
    guestCode,
    fullName,
    displayName,
    organizationName,
    jobTitle,
    companyName,
    clientTypeLabel,
    unitLabel,
    activeResCode,
    rawPhone,
    phoneDigits,
    e164Phone,
    phoneVariants: expandedPhones.variants,
    e164Phones: expandedPhones.e164Only,
    phoneSuffixKeys: expandedPhones.suffixKeys,
    email: cleanEmail,
    docType,
    document: cleanDoc,
    cityState,
    vehiclePlate,
    vehicleDetails,
    tags,
    alertsAndNotes,
    birthDateIso,
    birthDateObj,
    notesText
  };
}

function escapeVCardValue(val) {
  return String(val || "")
    .replace(/\\/g, "\\\\")
    .replace(/\r?\n/g, "\\n")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,");
}

function generateGuestVCard(database, guest) {
  const c = buildGuestCallerIdContactData(database, guest);
  if (!c.e164Phone && !c.rawPhone && !c.email) return "";
  const lines = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    `FN:${escapeVCardValue(c.displayName)}`,
    `N:;${escapeVCardValue(c.displayName)};;;`,
    `ORG:${escapeVCardValue(c.organizationName)}`,
    `TITLE:${escapeVCardValue(c.jobTitle)}`
  ];
  if (Array.isArray(c.phoneVariants) && c.phoneVariants.length > 0) {
    for (const pv of c.phoneVariants) {
      lines.push(`TEL;TYPE=CELL,VOICE,MSG:${pv}`);
    }
  } else if (c.e164Phone) {
    lines.push(`TEL;TYPE=CELL,VOICE,MSG:${c.e164Phone}`);
  } else if (c.rawPhone) {
    lines.push(`TEL;TYPE=CELL,VOICE:${c.rawPhone}`);
  }
  if (c.email) {
    lines.push(`EMAIL;TYPE=INTERNET:${c.email}`);
  }
  if (c.birthDateIso) {
    lines.push(`BDAY:${c.birthDateIso}`);
  }
  if (c.tags.length > 0) {
    lines.push(`CATEGORIES:${c.tags.map(t => escapeVCardValue(t)).join(",")},CorpFlats`);
  } else {
    lines.push("CATEGORIES:CorpFlats");
  }
  lines.push(`NOTE:${escapeVCardValue(c.notesText)}`);
  lines.push("END:VCARD");
  return lines.join("\r\n");
}

async function getValidGoogleContactsAccessToken(database, options = {}) {
  const cfg = ensureGoogleContactsConfig(database);
  if (!cfg.accessToken && !cfg.refreshToken) return null;

  const forceRefresh = Boolean(options?.forceRefresh);
  const isExpired = forceRefresh || !cfg.tokenExpiresAt || Date.now() > (cfg.tokenExpiresAt - 60000);
  if (cfg.accessToken && !isExpired) {
    return cfg.accessToken;
  }

  // Se houver refreshToken + clientId + clientSecret, renova automaticamente junto ao Google OAuth2
  if (cfg.refreshToken && cfg.clientId && cfg.clientSecret) {
    try {
      const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          client_id: cfg.clientId,
          client_secret: cfg.clientSecret,
          refresh_token: cfg.refreshToken,
          grant_type: "refresh_token"
        }).toString()
      });
      if (tokenRes.ok) {
        const tokenData = await tokenRes.json();
        if (tokenData.access_token) {
          cfg.accessToken = tokenData.access_token;
          cfg.tokenExpiresAt = Date.now() + (Number(tokenData.expires_in || 3599) * 1000);
          saveDatabase();
          return cfg.accessToken;
        }
      }
    } catch (err) {
      console.error("[GoogleContacts] Erro ao renovar access_token:", err?.message || err);
    }
  }

  return cfg.accessToken || null;
}

export function buildGooglePersonPayload(contactData, guestId) {
  const phoneEntries = (Array.isArray(contactData.phoneVariants) && contactData.phoneVariants.length > 0)
    ? contactData.phoneVariants.map(val => ({ value: val, type: "mobile" }))
    : [{ value: contactData.e164Phone, type: "mobile" }];

  const personPayload = {
    names: [
      {
        givenName: contactData.displayName,
        familyName: "",
        unstructuredName: contactData.displayName
      }
    ],
    phoneNumbers: phoneEntries,
    organizations: [
      {
        name: contactData.organizationName,
        title: contactData.jobTitle,
        department: `CRM ${contactData.guestCode}`,
        type: "work",
        current: true
      }
    ],
    biographies: [
      {
        value: contactData.notesText,
        contentType: "TEXT_PLAIN"
      }
    ],
    userDefined: [
      { key: "CRM_ID", value: String(guestId || "") },
      { key: "Codigo_CRM", value: contactData.guestCode },
      ...(contactData.document ? [{ key: "Documento", value: `${contactData.docType} ${contactData.document}` }] : []),
      ...(contactData.vehiclePlate ? [{ key: "Placa_Veiculo", value: contactData.vehiclePlate }] : []),
      ...(contactData.unitLabel ? [{ key: "Unidade_UH", value: contactData.unitLabel }] : [])
    ]
  };

  if (contactData.email) {
    personPayload.emailAddresses = [{ value: contactData.email, type: "home" }];
  }
  if (contactData.birthDateObj) {
    personPayload.birthdays = [{ date: contactData.birthDateObj }];
  }
  return personPayload;
}

function isFakeGoogleContactResourceName(rn) {
  if (!rn || typeof rn !== "string") return true;
  const s = rn.trim();
  if (!s.startsWith("people/")) return true;
  if (s === "people/synced" || s.startsWith("people/c_corpflats_") || s.startsWith("people/c_raiza_")) return true;
  return false;
}

export async function syncSingleGuestToGoogleContacts(database, guest, options = {}) {
  const targetDb = database || db;
  const cfg = ensureGoogleContactsConfig(targetDb);
  if (!guest) return { success: false, error: "Hóspede inválido." };

  if (
    Number(guest.id) === 33 ||
    isForbiddenTestOrInternalGuestName(guest.fullName || guest.name) ||
    isPlaceholderOrEmptyGuestName(guest.fullName || guest.name) ||
    isInternalOrForbiddenGuestPhone(guest.phone || guest.phoneNumber)
  ) {
    return {
      success: false,
      skipped: true,
      reason: "Contato interno, protegido ou de teste não sincronizável como hóspede UH"
    };
  }

  const contactData = buildGuestCallerIdContactData(targetDb, guest);
  if (Array.isArray(targetDb?.reservations) && targetDb.reservations.length > 0 && !contactData.activeResCode) {
    return {
      success: false,
      skipped: true,
      reason: "Apenas hóspedes com reserva válida são sincronizados com o Google Contatos",
      contactData
    };
  }
  if (isFakeGoogleContactResourceName(guest.googleContactResourceName)) {
    guest.googleContactResourceName = null;
    guest.googleContactEtag = null;
  }
  if (guest.googleContactResourceName && Array.isArray(targetDb?.guests)) {
    const ownedByCompatibleOther = targetDb.guests.some(other =>
      other &&
      Number(other.id) !== Number(guest.id) &&
      other.googleContactResourceName === guest.googleContactResourceName &&
      !areGuestNamesCompatible(contactData.fullName, other.fullName || other.name)
    );
    if (ownedByCompatibleOther && Number(guest.id) !== 20 && Number(guest.id) !== 10) {
      guest.googleContactResourceName = null;
      guest.googleContactEtag = null;
    }
  }
  guest.googleContactDisplayName = contactData.displayName;

  if (!contactData.e164Phone) {
    return {
      success: false,
      skipped: true,
      reason: "Sem telefone válido cadastrado",
      contactData
    };
  }

  const accessToken = await getValidGoogleContactsAccessToken(targetDb);
  if (!accessToken) {
    return {
      success: false,
      skipped: true,
      reason: "Conta Google Contatos ainda não conectada via OAuth2",
      contactData
    };
  }

  const personPayload = buildGooglePersonPayload(contactData, guest.id);

  const updateFields = "names,phoneNumbers,emailAddresses,organizations,biographies,birthdays,userDefined";
  let resourceName = guest.googleContactResourceName || "";
  let etag = guest.googleContactEtag || "";
  let allowOverwriteMisnamed = false;
  let action = "created";

  try {
    if (contactData.phoneDigits.length >= 8) {
      try {
        const searchPhoneQuery = contactData.phoneDigits.length >= 10
          ? contactData.phoneDigits.slice(-11)
          : contactData.phoneDigits;
        const searchUrl = `https://people.googleapis.com/v1/people:searchContacts?query=${encodeURIComponent(searchPhoneQuery)}&readMask=names,phoneNumbers,organizations,biographies,userDefined,metadata`;
        const searchRes = await fetch(searchUrl, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (searchRes.ok) {
          const searchData = await searchRes.json();
          for (const item of (searchData.results || [])) {
            const p = item?.person;
            if (!p || !p.resourceName) continue;
            const hasGuestPhone = (p.phoneNumbers || []).some(pn => pn.value && phonesMatch(pn.value, contactData.e164Phone));
            const crmIdUd = (p.userDefined || []).find(ud => (ud.key === "CRM_ID" || ud.key === "CorpFlatsGuestId") && ud.value);
            const isSameCrmId = Boolean(crmIdUd && String(crmIdUd.value) === String(guest.id));
            if (!hasGuestPhone && !isSameCrmId) continue;

            const pRawName = p.names?.[0]?.displayName || p.names?.[0]?.unstructuredName || [p.names?.[0]?.givenName, p.names?.[0]?.familyName].filter(Boolean).join(" ") || "";
            const pPersonName = String(pRawName).split("•")[0].trim();
            const isCompatibleName = !pPersonName || areGuestNamesCompatible(contactData.fullName, pPersonName);
            const otherPhones = (p.phoneNumbers || []).filter(pn => !pn.value || !phonesMatch(pn.value, contactData.e164Phone));

            const ownedByOtherInDb = Array.isArray(targetDb?.guests) && targetDb.guests.some(other =>
              other && Number(other.id) !== Number(guest.id) &&
              (other.googleContactResourceName === p.resourceName || (pPersonName && areGuestNamesCompatible(other.fullName || other.name, pPersonName) && other.phone && !phonesMatch(other.phone, contactData.e164Phone)))
            );

            if ((isCompatibleName || isSameCrmId || (!ownedByOtherInDb && otherPhones.length === 0)) && !resourceName) {
              resourceName = p.resourceName;
              etag = p.etag || "";
              allowOverwriteMisnamed = true;
            } else if (!isCompatibleName && hasGuestPhone) {
              if (otherPhones.length > 0 && p.etag) {
                await fetch(
                  `https://people.googleapis.com/v1/${p.resourceName}:updateContact?updatePersonFields=phoneNumbers`,
                  {
                    method: "PATCH",
                    headers: {
                      Authorization: `Bearer ${accessToken}`,
                      "Content-Type": "application/json"
                    },
                    body: JSON.stringify({
                      etag: p.etag,
                      phoneNumbers: otherPhones
                    })
                  }
                ).catch(() => {});
              } else if (otherPhones.length === 0 && resourceName && p.resourceName !== resourceName) {
                await fetch(
                  `https://people.googleapis.com/v1/${p.resourceName}:deleteContact`,
                  {
                    method: "DELETE",
                    headers: { Authorization: `Bearer ${accessToken}` }
                  }
                ).catch(() => {});
              }
            }
          }
        }
      } catch (_) {}
    }

    if (resourceName) {
      const getRes = await fetch(`https://people.googleapis.com/v1/${resourceName}?personFields=names,phoneNumbers,userDefined,metadata`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      if (getRes.ok) {
        const existingPerson = await getRes.json();
        const existingCrmIdUd = (existingPerson.userDefined || []).find(ud => (ud.key === "CRM_ID" || ud.key === "CorpFlatsGuestId") && ud.value);
        const existingRawName = existingPerson.names?.[0]?.displayName || existingPerson.names?.[0]?.unstructuredName || [existingPerson.names?.[0]?.givenName, existingPerson.names?.[0]?.familyName].filter(Boolean).join(" ") || "";
        const existingPersonName = String(existingRawName).split("•")[0].trim();

        const isSameCrmId = Boolean(existingCrmIdUd && String(existingCrmIdUd.value) === String(guest.id));
        const onlyHasThisGuestPhone = (existingPerson.phoneNumbers || []).length > 0 &&
          (existingPerson.phoneNumbers || []).every(pn => pn.value && phonesMatch(pn.value, contactData.e164Phone));
        const isTrueOwnerByResource = (Number(guest.id) === 20 && resourceName === "people/c5362578501072660427") ||
          (Number(guest.id) === 10 && resourceName === "people/c3038839061011966662");

        const isCrmIdConflict = Boolean(existingCrmIdUd && String(existingCrmIdUd.value) !== String(guest.id) && !allowOverwriteMisnamed && !onlyHasThisGuestPhone && !isTrueOwnerByResource);
        const isNameConflict = Boolean(existingPersonName && !areGuestNamesCompatible(contactData.fullName, existingPersonName) && !isSameCrmId && !allowOverwriteMisnamed && !onlyHasThisGuestPhone && !isTrueOwnerByResource);

        if (isCrmIdConflict || isNameConflict) {
          guest.googleContactResourceName = null;
          guest.googleContactEtag = null;
          resourceName = "";
          etag = "";
        } else {
          etag = existingPerson.etag || etag;
          const updateRes = await fetch(
            `https://people.googleapis.com/v1/${resourceName}:updateContact?updatePersonFields=${updateFields}`,
            {
              method: "PATCH",
              headers: {
                Authorization: `Bearer ${accessToken}`,
                "Content-Type": "application/json"
              },
              body: JSON.stringify({
                ...personPayload,
                etag
              })
            }
          );
          if (updateRes.ok) {
            const updatedPerson = await updateRes.json();
            guest.googleContactResourceName = updatedPerson.resourceName || resourceName;
            guest.googleContactEtag = updatedPerson.etag || etag;
            guest.googleContactSyncedAt = new Date().toISOString();
            guest.googleContactDisplayName = contactData.displayName;
            action = "updated";

            cfg.lastSyncAt = guest.googleContactSyncedAt;
            cfg.syncLogs.unshift({
              timestamp: guest.googleContactSyncedAt,
              guestId: guest.id,
              guestName: contactData.fullName,
              displayName: contactData.displayName,
              phone: contactData.e164Phone,
              action: "updated",
              status: "success"
            });
            if (cfg.syncLogs.length > 40) cfg.syncLogs.length = 40;
            if (!options.skipSave) saveDatabase();
            return {
              success: true,
              action,
              resourceName: guest.googleContactResourceName,
              displayName: contactData.displayName,
              contactData
            };
          }
        }
      } else if (getRes.status === 404) {
        resourceName = "";
        etag = "";
      } else if (getRes.status === 401 || getRes.status === 403) {
        cfg.tokenExpiresAt = 1;
        const errBody = await getRes.text();
        throw new Error(`Permissão ou token Google expirado (${getRes.status}): ${errBody.slice(0, 140)}`);
      }
    }

    const createRes = await fetch(
      `https://people.googleapis.com/v1/people:createContact?personFields=${updateFields}`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(personPayload)
      }
    );

    if (!createRes.ok) {
      const errText = await createRes.text();
      throw new Error(`Google People API (${createRes.status}): ${errText.slice(0, 180)}`);
    }

    const createdPerson = await createRes.json();
    guest.googleContactResourceName = createdPerson.resourceName || "";
    guest.googleContactEtag = createdPerson.etag || "";
    guest.googleContactSyncedAt = new Date().toISOString();
    guest.googleContactDisplayName = contactData.displayName;

    cfg.lastSyncAt = guest.googleContactSyncedAt;
    cfg.totalSyncedCount = (Number(cfg.totalSyncedCount) || 0) + 1;
    cfg.syncLogs.unshift({
      timestamp: guest.googleContactSyncedAt,
      guestId: guest.id,
      guestName: contactData.fullName,
      displayName: contactData.displayName,
      phone: contactData.e164Phone,
      action: "created",
      status: "success"
    });
    if (cfg.syncLogs.length > 40) cfg.syncLogs.length = 40;
    if (!options.skipSave) saveDatabase();

    return {
      success: true,
      action: "created",
      resourceName: guest.googleContactResourceName,
      displayName: contactData.displayName,
      contactData
    };
  } catch (err) {
    const errMsg = err?.message || String(err);
    cfg.syncLogs.unshift({
      timestamp: new Date().toISOString(),
      guestId: guest.id,
      guestName: contactData.fullName,
      displayName: contactData.displayName,
      phone: contactData.e164Phone,
      action: "error",
      status: "error",
      error: errMsg
    });
    if (cfg.syncLogs.length > 40) cfg.syncLogs.length = 40;
    return {
      success: false,
      error: errMsg,
      contactData
    };
  }
}

function triggerAutoGoogleContactSync(database, guest) {
  try {
    const targetDb = database || db;
    if (!guest) return;
    const contactData = buildGuestCallerIdContactData(targetDb, guest);
    guest.googleContactDisplayName = contactData.displayName;

    const cfg = ensureGoogleContactsConfig(targetDb);
    if (!cfg.enabled || (!cfg.accessToken && !cfg.refreshToken)) return;

    setImmediate(() => {
      syncSingleGuestToGoogleContacts(targetDb, guest).catch(err => {
        console.error("[GoogleContacts AutoSync] Falha ao sincronizar hóspede:", err?.message || err);
      });
    });
  } catch (_) {}
}

export async function executeFullGoogleContactsSyncAndRepair(database) {
  const targetDb = database || db;
  reconcileAndMergeGuests(targetDb);
  const cfg = ensureGoogleContactsConfig(targetDb);
  const allGuests = Array.isArray(targetDb.guests) ? targetDb.guests : [];

  for (const g of allGuests) {
    if (isFakeGoogleContactResourceName(g.googleContactResourceName)) {
      g.googleContactResourceName = null;
      g.googleContactEtag = null;
    }
  }

  let accessToken = await getValidGoogleContactsAccessToken(targetDb);
  if (!accessToken) {
    for (const g of allGuests) {
      const c = buildGuestCallerIdContactData(targetDb, g);
      g.googleContactDisplayName = c.displayName;
    }
    saveDatabase();
    return {
      success: false,
      tokenExpired: true,
      totalProcessed: allGuests.length,
      syncedCount: 0,
      createdCount: 0,
      updatedCount: 0,
      skippedCount: allGuests.length,
      errorCount: 0,
      firstError: "Conta Google Contatos ainda não conectada via OAuth2 ou sessão expirada."
    };
  }

  // 1. Lê todos os contatos existentes no Google Contatos (até 10 páginas = 10.000 contatos)
  const existingByResource = new Map();
  const existingByCrmId = new Map();
  const existingListByPhone = new Map();

  const addPhoneEntry = (key, entry) => {
    if (!key) return;
    if (!existingListByPhone.has(key)) existingListByPhone.set(key, []);
    const arr = existingListByPhone.get(key);
    if (!arr.includes(entry)) arr.push(entry);
  };

  try {
    let pageToken = "";
    for (let page = 0; page < 10; page++) {
      const connectionsUrl = `https://people.googleapis.com/v1/people/me/connections?personFields=names,phoneNumbers,emailAddresses,organizations,biographies,userDefined,metadata&pageSize=1000${pageToken ? `&pageToken=${encodeURIComponent(pageToken)}` : ""}`;
      let connRes = await fetch(connectionsUrl, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      if (connRes.status === 401 || connRes.status === 403) {
        const refreshed = await getValidGoogleContactsAccessToken(targetDb, { forceRefresh: true });
        if (refreshed && refreshed !== accessToken) {
          accessToken = refreshed;
          connRes = await fetch(connectionsUrl, {
            headers: { Authorization: `Bearer ${accessToken}` }
          });
        }
      }
      if (connRes.status === 401 || connRes.status === 403) {
        cfg.tokenExpiresAt = 1;
        saveDatabase();
        return {
          success: false,
          tokenExpired: true,
          totalProcessed: allGuests.length,
          syncedCount: 0,
          createdCount: 0,
          updatedCount: 0,
          skippedCount: allGuests.length,
          errorCount: 1,
          firstError: "Sessão Google Contatos expirada (401). Clique em Reconectar Conta Google para atualizar a agenda automaticamente."
        };
      }
      if (!connRes.ok) break;
      const connData = await connRes.json();
      for (const p of (connData.connections || [])) {
        if (!p?.resourceName) continue;
        const rawContactName = p.names?.[0]?.displayName || p.names?.[0]?.unstructuredName || [p.names?.[0]?.givenName, p.names?.[0]?.familyName].filter(Boolean).join(" ") || "";
        const contactPersonName = String(rawContactName).split("•")[0].trim();
        const crmIdUd = (p.userDefined || []).find(ud => (ud.key === "CRM_ID" || ud.key === "CorpFlatsGuestId") && ud.value);
        const codigoCrmUd = (p.userDefined || []).find(ud => ud.key === "Codigo_CRM" && ud.value);
        const isCorpFlatsManaged = rawContactName.includes("CorpFlats") ||
          Boolean(crmIdUd) ||
          Boolean(codigoCrmUd) ||
          (p.organizations || []).some(o => String(o?.name || "").includes("CorpFlats") || String(o?.department || "").includes("CRM")) ||
          (p.biographies || []).some(b => String(b?.value || "").includes("Código CRM:"));

        const rawPhoneObjects = Array.isArray(p.phoneNumbers) ? p.phoneNumbers : [];
        const normPhones = [];
        for (const pn of rawPhoneObjects) {
          const digits = String(pn?.value || pn?.canonicalForm || "").replace(/\D/g, "");
          if (digits.length >= 8) {
            const norm = normalizePhone(digits);
            if (norm.length >= 8 && !normPhones.includes(norm)) normPhones.push(norm);
          }
        }

        const entry = {
          resourceName: p.resourceName,
          etag: p.etag || "",
          crmId: crmIdUd ? String(crmIdUd.value) : "",
          rawContactName,
          contactPersonName,
          isCorpFlatsManaged,
          rawPhoneObjects,
          normPhones
        };
        existingByResource.set(p.resourceName, entry);
        if (entry.crmId) {
          existingByCrmId.set(entry.crmId, entry);
        }
        for (const pn of rawPhoneObjects) {
          const digits = String(pn?.value || pn?.canonicalForm || "").replace(/\D/g, "");
          if (digits.length >= 8) {
            const norm = normalizePhone(digits);
            if (norm.length === 11) {
              const ddd = norm.slice(0, 2);
              const local9 = norm.slice(2);
              const local8 = local9.startsWith("9") ? local9.slice(1) : local9.slice(-8);
              addPhoneEntry(`${ddd}${local9}`, entry);
              addPhoneEntry(`${ddd}${local8}`, entry);
            } else if (norm.length === 10) {
              const ddd = norm.slice(0, 2);
              const local8 = norm.slice(2);
              addPhoneEntry(`${ddd}${local8}`, entry);
              if (["6", "7", "8", "9"].includes(local8[0])) {
                addPhoneEntry(`${ddd}9${local8}`, entry);
              }
            } else if (digits.length >= 10) {
              addPhoneEntry(digits, entry);
              addPhoneEntry(digits.slice(-11), entry);
              addPhoneEntry(digits.slice(-10), entry);
            } else {
              addPhoneEntry(norm, entry);
            }
          }
        }
      }
      if (!connData.nextPageToken) break;
      pageToken = connData.nextPageToken;
    }
  } catch (err) {
    console.warn("[GoogleContacts Batch] Falha ao listar conexões existentes:", err?.message || err);
  }

  let createdCount = 0;
  let updatedCount = 0;
  let skippedCount = 0;
  let errorCount = 0;
  let firstError = "";

  const toCreate = [];
  const toUpdate = [];
  const seenPhonesInBatch = new Set();

  // Mapa canônico de qual hóspede do CRM é dono legítimo de cada telefone
  const crmOwnerByNormPhone = new Map();
  const registerCrmPhoneOwner = (phoneVal, ownerBundle) => {
    const norm = normalizePhone(phoneVal);
    if (!norm || norm.length < 8) return;
    crmOwnerByNormPhone.set(norm, ownerBundle);
    if (norm.length === 11) {
      const ddd = norm.slice(0, 2);
      const local9 = norm.slice(2);
      const local8 = local9.startsWith("9") ? local9.slice(1) : local9.slice(-8);
      crmOwnerByNormPhone.set(`${ddd}${local9}`, ownerBundle);
      crmOwnerByNormPhone.set(`${ddd}${local8}`, ownerBundle);
    } else if (norm.length === 10) {
      const ddd = norm.slice(0, 2);
      const local8 = norm.slice(2);
      crmOwnerByNormPhone.set(`${ddd}${local8}`, ownerBundle);
      if (["6", "7", "8", "9"].includes(local8[0])) {
        crmOwnerByNormPhone.set(`${ddd}9${local8}`, ownerBundle);
      }
    }
  };

  const guestBundles = [];
  const hasReservationsInDb = Array.isArray(targetDb?.reservations) && targetDb.reservations.length > 0;
  for (const g of allGuests) {
    if (!g) continue;
    if (
      Number(g.id) === 33 ||
      isForbiddenTestOrInternalGuestName(g.fullName || g.name) ||
      isPlaceholderOrEmptyGuestName(g.fullName || g.name) ||
      isInternalOrForbiddenGuestPhone(g.phone || g.phoneNumber)
    ) {
      g.googleContactResourceName = null;
      g.googleContactEtag = null;
      skippedCount++;
      continue;
    }
    const contactData = buildGuestCallerIdContactData(targetDb, g);
    g.googleContactDisplayName = contactData.displayName;
    if (!contactData.e164Phone || contactData.phoneDigits.length < 8) {
      skippedCount++;
      continue;
    }
    if (hasReservationsInDb && !contactData.activeResCode) {
      const hasAnyValidRes = targetDb.reservations.some(r =>
        r && r.status !== "cancelada" && r.status !== "cancelled" &&
        (Number(r.guestId) === Number(g.id) || (Array.isArray(r.guests) && r.guests.some(rg => Number(rg?.guestId) === Number(g.id))))
      );
      if (!hasAnyValidRes) {
        g.googleContactResourceName = null;
        g.googleContactEtag = null;
        skippedCount++;
        continue;
      }
    }
    const personPayload = buildGooglePersonPayload(contactData, g.id);
    const bundle = { guest: g, contactData, personPayload };
    guestBundles.push(bundle);
    registerCrmPhoneOwner(contactData.e164Phone, bundle);
    for (const ep of (contactData.e164Phones || [])) {
      registerCrmPhoneOwner(ep, bundle);
    }
  }

  // 1.2. Restauração e blindagem automática dos contatos internos e operacionais no Google Contatos
  const protectedInternalResources = new Set();
  const extraDuplicateInternalToDelete = [];
  const buildCleanInternalPayload = (cleanName, phoneValues, orgName, orgTitle, bioNote) => ({
    names: [{ givenName: cleanName, familyName: "", unstructuredName: cleanName }],
    phoneNumbers: phoneValues.map(v => ({ value: v, type: "work" })),
    organizations: [{ name: orgName, title: orgTitle, type: "work", current: true }],
    biographies: [{ value: bioNote, contentType: "TEXT_PLAIN" }],
    userDefined: []
  });

  const internalSpecs = [
    {
      key: "corpflats",
      cleanName: "CorpFlats",
      phones: ["+5522997124021", "(22) 99712-4021"],
      orgName: "CorpFlats",
      orgTitle: "Atendimento Oficial WhatsApp",
      bio: "Contato Oficial CorpFlats",
      matches: (entry) =>
        entry.resourceName === "people/c665097223076018139" ||
        entry.normPhones.some(p => phonesMatch(p, "22997124021")) ||
        /^lucas\s+teste\b/i.test(entry.contactPersonName)
    },
    {
      key: "miller",
      cleanName: "Miller Mendonça Pessanha",
      phones: ["+5522998505276", "(22) 99850-5276"],
      orgName: "CorpFlats",
      orgTitle: "Administração",
      bio: "Administração CorpFlats",
      matches: (entry) =>
        entry.resourceName === "people/c4914615224608862756" ||
        entry.normPhones.some(p => phonesMatch(p, "22998505276"))
    },
    {
      key: "portaria_soho",
      cleanName: "Portaria / Garagem Soho",
      phones: ["+5522997873654", "(22) 99787-3654"],
      orgName: "CorpFlats • Edifício Soho",
      orgTitle: "Portaria e Garagem",
      bio: "Portaria e Garagem Edifício Soho",
      matches: (entry) =>
        entry.normPhones.some(p => phonesMatch(p, "22997873654")) ||
        /^portaria\b/i.test(entry.contactPersonName)
    },
    {
      key: "felipi_os",
      cleanName: "Felipi Rangel Leandro",
      phones: ["+5522999082462", "(22) 99908-2462"],
      orgName: "Prestador de Serviço",
      orgTitle: "Manutenção",
      bio: "Prestador de Serviço",
      matches: (entry) =>
        entry.resourceName === "people/c7991532134028326146" ||
        entry.normPhones.some(p => phonesMatch(p, "22999082462"))
    },
    {
      key: "priscila_equipe",
      cleanName: "Priscila da Silva Pinto",
      phones: ["+5522997048709", "(22) 99704-8709"],
      orgName: "Equipe Governança",
      orgTitle: "Camareira",
      bio: "Equipe Governança",
      matches: (entry) =>
        entry.resourceName === "people/c1926963521653928002" ||
        entry.normPhones.some(p => phonesMatch(p, "22997048709"))
    },
    {
      key: "tamires_equipe",
      cleanName: "Tamires da Silva Rocha",
      phones: ["+5522997810703", "(22) 99781-0703"],
      orgName: "Equipe Governança",
      orgTitle: "Camareira",
      bio: "Equipe Governança",
      matches: (entry) =>
        entry.resourceName === "people/c7860054758378652205" ||
        entry.normPhones.some(p => phonesMatch(p, "22997810703"))
    },
    {
      key: "jefferson_os",
      cleanName: "Jefferson Bruno",
      phones: ["+5522999922473", "(22) 99992-2473"],
      orgName: "Prestador de Serviço",
      orgTitle: "Ar-Condicionado / Manutenção",
      bio: "Prestador de Serviço",
      matches: (entry) =>
        entry.normPhones.some(p => phonesMatch(p, "22999922473"))
    },
    {
      key: "recepcao_soho",
      cleanName: "Recepção Soho",
      phones: ["+552237040100", "(22) 3704-0100"],
      orgName: "CorpFlats • Edifício Soho",
      orgTitle: "Recepção",
      bio: "Recepção Edifício Soho • CorpFlats",
      matches: (entry) => {
        if (entry.normPhones.some(p => phonesMatch(p, "2237040100"))) return true;
        if (/^(ordem\s+de\s+servi[cç]o|os\s*#\d+|recep[cç][aã]o\s+soho)/i.test(entry.contactPersonName)) {
          const belongsToKnownGuest = entry.normPhones.some(ep => crmOwnerByNormPhone.has(ep));
          return !belongsToKnownGuest;
        }
        return false;
      }
    }
  ];

  for (const spec of internalSpecs) {
    const matchedEntries = Array.from(existingByResource.values()).filter(
      e => e && e.resourceName && !protectedInternalResources.has(e.resourceName) && spec.matches(e)
    );
    if (matchedEntries.length > 0) {
      const primary = matchedEntries[0];
      protectedInternalResources.add(primary.resourceName);
      const preservedPhones = primary.rawPhoneObjects
        .map(pn => String(pn?.value || pn?.canonicalForm || "").trim())
        .filter(Boolean);
      const mergedPhones = Array.from(new Set([...spec.phones, ...(spec.key === "recepcao_soho" ? preservedPhones : [])]));
      if (primary.etag) {
        toUpdate.push({
          guest: null,
          contactData: {
            fullName: spec.cleanName,
            displayName: spec.cleanName,
            e164Phone: mergedPhones[0] || ""
          },
          personPayload: buildCleanInternalPayload(spec.cleanName, mergedPhones, spec.orgName, spec.orgTitle, spec.bio),
          resourceName: primary.resourceName,
          etag: primary.etag
        });
      }
      for (let i = 1; i < matchedEntries.length; i++) {
        const dup = matchedEntries[i];
        protectedInternalResources.add(dup.resourceName);
        if (dup.isCorpFlatsManaged || /^(ordem\s+de\s+servi[cç]o|lucas\s+teste)/i.test(dup.contactPersonName)) {
          extraDuplicateInternalToDelete.push(dup.resourceName);
        }
      }
    }
  }

  const isEntryCompatibleWithGuest = (entry, guestObj, cData) => {
    if (!entry || !entry.resourceName || protectedInternalResources.has(entry.resourceName)) return false;
    // Se outro hóspede no CRM detém legitimamente este resourceName e tem nome compatível com o contato atual no Google
    const ownedByCompatibleOtherInDb = allGuests.some(other =>
      other && Number(other.id) !== Number(guestObj.id) &&
      other.googleContactResourceName === entry.resourceName &&
      (!entry.contactPersonName || areGuestNamesCompatible(other.fullName || other.name, entry.contactPersonName))
    );
    if (ownedByCompatibleOtherInDb) return false;

    // Regra 1: Dono explícito do resourceName quando é João Eduardo (20) ou Francine (10) ou quando o contato possui o telefone/CRM_ID deste hóspede
    if (guestObj.googleContactResourceName && guestObj.googleContactResourceName === entry.resourceName) {
      const hasThisPhone = entry.normPhones.some(ep => phonesMatch(ep, cData.e164Phone));
      if (hasThisPhone || entry.crmId === String(guestObj.id) || Number(guestObj.id) === 20 || Number(guestObj.id) === 10 || areGuestNamesCompatible(cData.fullName, entry.contactPersonName)) {
        return true;
      }
    }

    // Regra 2: Mesmo CRM_ID no contato CorpFlats (mesmo que o nome no Google tenha sido sobrescrito por bug anterior, ex: Roselene ID 143 salva como Raiza)
    if (entry.crmId && String(entry.crmId) === String(guestObj.id)) {
      const hasThisPhone = entry.normPhones.some(ep => phonesMatch(ep, cData.e164Phone));
      const anyPhoneOwnedByNameOwner = entry.contactPersonName && !areGuestNamesCompatible(cData.fullName, entry.contactPersonName) &&
        entry.normPhones.some(ep => {
          const owner = crmOwnerByNormPhone.get(ep);
          return owner && Number(owner.guest.id) !== Number(guestObj.id) && areGuestNamesCompatible(owner.contactData.fullName, entry.contactPersonName);
        });
      if (hasThisPhone || !anyPhoneOwnedByNameOwner) {
        return true;
      }
    }

    // Regra 3: Nome compatível com o titular no Google Contatos (mesmo que o CRM_ID tenha sido contaminado antes, ex: João Eduardo ID 20 com CRM_ID 359)
    if (entry.contactPersonName && areGuestNamesCompatible(cData.fullName, entry.contactPersonName)) {
      if (!entry.crmId || String(entry.crmId) === String(guestObj.id) || entry.isCorpFlatsManaged) {
        return true;
      }
    }

    // Regra 4: Contato gerenciado pelo CorpFlats cujos telefones pertencem exclusivamente a este hóspede e nenhum hóspede do CRM tem o nome que está lá
    if (entry.isCorpFlatsManaged && entry.normPhones.length > 0) {
      const allPhonesBelongToThisGuest = entry.normPhones.every(ep => phonesMatch(ep, cData.e164Phone));
      const nameBelongsToAnotherCrmGuest = entry.contactPersonName && guestBundles.some(b =>
        Number(b.guest.id) !== Number(guestObj.id) &&
        areGuestNamesCompatible(b.contactData.fullName, entry.contactPersonName) &&
        (!b.guest.googleContactResourceName || b.guest.googleContactResourceName === entry.resourceName)
      );
      if (allPhonesBelongToThisGuest && !nameBelongsToAnotherCrmGuest) {
        return true;
      }
    }

    return false;
  };

  for (const bundle of guestBundles) {
    const { guest: g, contactData, personPayload } = bundle;
    if (g.googleContactResourceName) {
      const prevEntry = existingByResource.get(g.googleContactResourceName);
      if (prevEntry && !isEntryCompatibleWithGuest(prevEntry, g, contactData)) {
        g.googleContactResourceName = null;
        g.googleContactEtag = null;
      }
    }

    const fullPhoneKey = contactData.phoneDigits.length >= 10 ? contactData.phoneDigits.slice(-11) : contactData.phoneDigits;

    const candidateSet = new Set();
    if (g.googleContactResourceName && existingByResource.has(g.googleContactResourceName)) {
      candidateSet.add(existingByResource.get(g.googleContactResourceName));
    }
    if (existingByCrmId.has(String(g.id))) {
      candidateSet.add(existingByCrmId.get(String(g.id)));
    }
    if (Array.isArray(contactData.phoneSuffixKeys)) {
      for (const sk of contactData.phoneSuffixKeys) {
        for (const e of (existingListByPhone.get(sk) || [])) candidateSet.add(e);
      }
    }
    for (const e of (existingListByPhone.get(fullPhoneKey) || [])) candidateSet.add(e);
    for (const e of (existingListByPhone.get(contactData.phoneDigits) || [])) candidateSet.add(e);

    const candidates = Array.from(candidateSet).filter(Boolean);
    const matchedExisting = candidates.find(cand =>
      isEntryCompatibleWithGuest(cand, g, contactData) &&
      !toUpdate.some(u => u.resourceName === cand.resourceName && !areGuestNamesCompatible(u.contactData.fullName, contactData.fullName))
    ) || null;

    if (matchedExisting && matchedExisting.resourceName && matchedExisting.etag) {
      const existingUpdateItem = toUpdate.find(u => u.resourceName === matchedExisting.resourceName);
      if (!existingUpdateItem) {
        toUpdate.push({
          guest: g,
          contactData,
          personPayload,
          resourceName: matchedExisting.resourceName,
          etag: matchedExisting.etag
        });
      } else if (areGuestNamesCompatible(existingUpdateItem.contactData.fullName, contactData.fullName)) {
        g.googleContactResourceName = matchedExisting.resourceName;
        g.googleContactSyncedAt = new Date().toISOString();
      }
    } else {
      if (!seenPhonesInBatch.has(fullPhoneKey)) {
        seenPhonesInBatch.add(fullPhoneKey);
        if (Array.isArray(contactData.phoneSuffixKeys)) {
          for (const sk of contactData.phoneSuffixKeys) {
            seenPhonesInBatch.add(sk);
          }
        }
        toCreate.push({
          guest: g,
          contactData,
          personPayload
        });
      } else {
        skippedCount++;
      }
    }
  }

  // 1.5. Varredura de Descontaminação de Contatos Órfãos ou Contaminados no Google Contatos
  const toDeleteResourceNames = [...extraDuplicateInternalToDelete];
  const toCleanPhonesEntries = [];
  const claimedResources = new Set([...protectedInternalResources, ...toUpdate.map(u => u.resourceName)]);

  for (const entry of existingByResource.values()) {
    if (!entry || !entry.resourceName || claimedResources.has(entry.resourceName)) continue;
    if (!Array.isArray(entry.rawPhoneObjects) || entry.rawPhoneObjects.length === 0) {
      if (entry.isCorpFlatsManaged || isSystemOrServiceOrderGuestName(entry.rawContactName) || isForbiddenTestOrInternalGuestName(entry.contactPersonName)) {
        toDeleteResourceNames.push(entry.resourceName);
      }
      continue;
    }

    const keptPhoneObjects = [];
    const foreignOwners = [];

    for (const pn of entry.rawPhoneObjects) {
      const digits = String(pn?.value || pn?.canonicalForm || "").replace(/\D/g, "");
      const norm = normalizePhone(digits);
      const owner = norm.length >= 8 ? crmOwnerByNormPhone.get(norm) : null;

      if (!owner) {
        keptPhoneObjects.push(pn);
        continue;
      }

      const isCompatibleWithEntryName = !entry.contactPersonName || areGuestNamesCompatible(entry.contactPersonName, owner.contactData.fullName);
      const ownerAlreadyUpdatedElsewhere = toUpdate.some(u => u.guest && Number(u.guest.id) === Number(owner.guest.id) && u.resourceName !== entry.resourceName);

      if (!isCompatibleWithEntryName || (entry.isCorpFlatsManaged && ownerAlreadyUpdatedElsewhere)) {
        if (!foreignOwners.includes(owner)) foreignOwners.push(owner);
      } else {
        keptPhoneObjects.push(pn);
      }
    }

    if (keptPhoneObjects.length < entry.rawPhoneObjects.length) {
      if (keptPhoneObjects.length === 0) {
        // Todos os telefones deste contato pertencem a hóspedes incompatíveis ou já atualizados em outro contato!
        const primaryOwner = foreignOwners[0] || null;
        const createIdx = primaryOwner
          ? toCreate.findIndex(c => c.guest && Number(c.guest.id) === Number(primaryOwner.guest.id))
          : -1;

        if (createIdx !== -1 && entry.etag) {
          // Reivindica e renomeia o contato corrompido in-place para o verdadeiro dono do telefone!
          const [claimedCreate] = toCreate.splice(createIdx, 1);
          toUpdate.push({
            guest: claimedCreate.guest,
            contactData: claimedCreate.contactData,
            personPayload: claimedCreate.personPayload,
            resourceName: entry.resourceName,
            etag: entry.etag
          });
          claimedResources.add(entry.resourceName);
        } else if (entry.isCorpFlatsManaged) {
          toDeleteResourceNames.push(entry.resourceName);
        }
      } else if (entry.etag) {
        // Remove cirurgicamente apenas os telefones de outras pessoas que haviam sido injetados neste contato
        toCleanPhonesEntries.push({
          resourceName: entry.resourceName,
          etag: entry.etag,
          phoneNumbers: keptPhoneObjects
        });
      }
    } else if (
      !claimedResources.has(entry.resourceName) &&
      (
        entry.isCorpFlatsManaged ||
        isSystemOrServiceOrderGuestName(entry.rawContactName) ||
        isForbiddenTestOrInternalGuestName(entry.contactPersonName)
      )
    ) {
      // Contato criado pelo CRM CorpFlats sem vínculo com nenhum hóspede real com reserva válida (ex: testes, 0 estadias, LIDs, duplicatas antigas)
      toDeleteResourceNames.push(entry.resourceName);
    }
  }

  const nowIso = new Date().toISOString();
  const updateMask = "names,phoneNumbers,emailAddresses,organizations,biographies,birthdays,userDefined";
  const chunkSize = 180;

  // 1.6. Executa limpeza cirúrgica de telefones infiltrados e remoção de duplicatas corrompidas
  for (const cleanItem of toCleanPhonesEntries) {
    try {
      const cleanRes = await fetch(
        `https://people.googleapis.com/v1/${cleanItem.resourceName}:updateContact?updatePersonFields=phoneNumbers`,
        {
          method: "PATCH",
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            etag: cleanItem.etag,
            phoneNumbers: cleanItem.phoneNumbers
          })
        }
      );
      if (cleanRes.ok) updatedCount++;
    } catch (_) {}
  }

  if (toDeleteResourceNames.length > 0) {
    for (let i = 0; i < toDeleteResourceNames.length; i += 400) {
      const delChunk = toDeleteResourceNames.slice(i, i + 400);
      try {
        await fetch("https://people.googleapis.com/v1/people:batchDeleteContacts", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${accessToken}`,
            "Content-Type": "application/json"
          },
          body: JSON.stringify({ resourceNames: delChunk })
        });
      } catch (_) {}
    }
  }

  // 2. Executa atualização em lote via people:batchUpdateContacts (até 180 contatos por requisição)
  for (let i = 0; i < toUpdate.length; i += chunkSize) {
    const chunk = toUpdate.slice(i, i + chunkSize);
    try {
      const contactsMap = {};
      for (const item of chunk) {
        contactsMap[item.resourceName] = {
          ...item.personPayload,
          resourceName: item.resourceName,
          etag: item.etag
        };
      }
      const batchUpdRes = await fetch("https://people.googleapis.com/v1/people:batchUpdateContacts", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          contacts: contactsMap,
          updateMask,
          readMask: "names,phoneNumbers,metadata"
        })
      });

      if (batchUpdRes.ok) {
        const updData = await batchUpdRes.json();
        const results = updData.updateResult || {};
        for (const item of chunk) {
          const itemResult = results[item.resourceName];
          const resPerson = itemResult?.person;
          if (itemResult?.httpStatusCode && itemResult.httpStatusCode >= 400 && !resPerson) {
            if (item.guest) {
              // Fallback individual caso o etag estivesse defasado ou o contato tenha sido removido
              const fallbackRes = await syncSingleGuestToGoogleContacts(targetDb, item.guest, { skipSave: true });
              if (fallbackRes?.success) updatedCount++;
              else errorCount++;
            }
            continue;
          }
          if (item.guest) {
            item.guest.googleContactResourceName = resPerson?.resourceName || item.resourceName;
            item.guest.googleContactEtag = resPerson?.etag || item.etag;
            item.guest.googleContactSyncedAt = nowIso;
          }
          updatedCount++;
          cfg.syncLogs.unshift({
            timestamp: nowIso,
            guestId: item.guest ? item.guest.id : "INTERNAL",
            guestName: item.contactData.fullName,
            displayName: item.contactData.displayName,
            phone: item.contactData.e164Phone,
            action: "updated",
            status: "success"
          });
        }
      } else {
        const errText = await batchUpdRes.text();
        errorCount += chunk.length;
        if (!firstError) firstError = `BatchUpdate (${batchUpdRes.status}): ${errText.slice(0, 200)}`;
      }
    } catch (err) {
      errorCount += chunk.length;
      if (!firstError) firstError = err?.message || String(err);
    }
  }

  // 3. Executa criação em lote via people:batchCreateContacts (até 180 contatos por requisição)
  for (let i = 0; i < toCreate.length; i += chunkSize) {
    const chunk = toCreate.slice(i, i + chunkSize);
    try {
      const batchRes = await fetch("https://people.googleapis.com/v1/people:batchCreateContacts", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          contacts: chunk.map(item => ({ contactPerson: item.personPayload })),
          readMask: "names,phoneNumbers,metadata"
        })
      });

      if (batchRes.ok) {
        const batchData = await batchRes.json();
        const createdPeople = batchData.createdPeople || [];
        chunk.forEach((item, idx) => {
          const createdPerson = createdPeople[idx]?.person;
          item.guest.googleContactResourceName = createdPerson?.resourceName || item.guest.googleContactResourceName || null;
          item.guest.googleContactEtag = createdPerson?.etag || "";
          item.guest.googleContactSyncedAt = nowIso;
          createdCount++;
          cfg.syncLogs.unshift({
            timestamp: nowIso,
            guestId: item.guest.id,
            guestName: item.contactData.fullName,
            displayName: item.contactData.displayName,
            phone: item.contactData.e164Phone,
            action: "created",
            status: "success"
          });
        });
      } else {
        const errText = await batchRes.text();
        errorCount += chunk.length;
        if (!firstError) firstError = `BatchCreate (${batchRes.status}): ${errText.slice(0, 200)}`;
      }
    } catch (err) {
      errorCount += chunk.length;
      if (!firstError) firstError = err?.message || String(err);
    }
  }

  if (cfg.syncLogs.length > 40) cfg.syncLogs.length = 40;
  cfg.lastSyncAt = nowIso;
  cfg.totalSyncedCount = (Number(cfg.totalSyncedCount) || 0) + createdCount;
  if (errorCount === 0 && (createdCount + updatedCount + toDeleteResourceNames.length) > 0) {
    cfg._googleContactsFullHealV6 = true;
  }
  saveDatabase();

  return {
    success: errorCount === 0 || (createdCount + updatedCount + toDeleteResourceNames.length) > 0,
    totalProcessed: allGuests.length,
    syncedCount: createdCount + updatedCount,
    createdCount,
    updatedCount,
    deletedCount: toDeleteResourceNames.length,
    cleanedSharedCount: toCleanPhonesEntries.length,
    skippedCount,
    errorCount,
    firstError: firstError || null,
    lastSyncAt: cfg.lastSyncAt
  };
}

let isHealingGoogleContactsInFlight = false;
async function healContaminatedGoogleContactsPostBoot(database) {
  if (isHealingGoogleContactsInFlight) return;
  try {
    const targetDb = database || db;
    if (!targetDb || !Array.isArray(targetDb.guests)) return;
    const cfg = ensureGoogleContactsConfig(targetDb);
    if (!cfg.enabled || (!cfg.accessToken && !cfg.refreshToken)) return;
    if (cfg._googleContactsFullHealV6) return;

    isHealingGoogleContactsInFlight = true;
    const result = await executeFullGoogleContactsSyncAndRepair(targetDb);
    if (result?.success) {
      console.log(`[GoogleContacts PostBoot Heal V6] Reparo completo concluído: ${result.updatedCount} atualizados, ${result.createdCount} criados, ${result.deletedCount || 0} duplicados/inválidos removidos.`);
    }
  } catch (err) {
    console.warn("[GoogleContacts PostBoot Heal] Aviso:", err?.message || err);
  } finally {
    isHealingGoogleContactsInFlight = false;
  }
}

// Status e Pré-visualização da Integração Google Contatos
app.get("/api/pms/guests/google-contacts/status", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev" && userAuth.role !== "recepcao" && userAuth.role !== "reception")) {
    return res.status(403).json({ error: "Acesso restrito." });
  }
  reconcileAndMergeGuests(db);
  const cfg = ensureGoogleContactsConfig(db);
  const allGuests = Array.isArray(db.guests) ? db.guests : [];
  for (const g of allGuests) {
    if (isFakeGoogleContactResourceName(g.googleContactResourceName)) {
      g.googleContactResourceName = null;
      g.googleContactEtag = null;
    }
  }
  const guestsWithPhone = allGuests.filter(g => Number(g.id) !== 33 && String(g.phone || g.phoneNumber || "").replace(/\D/g, "").length >= 8);
  const syncedGuests = guestsWithPhone.filter(g => Boolean(g.googleContactSyncedAt || g.googleContactResourceName));

  const previewContacts = guestsWithPhone.slice(0, 6).map(g => buildGuestCallerIdContactData(db, g));
  const defaultClientId = process.env.GOOGLE_CLIENT_ID || db.siteConfig?.authConfig?.googleClientId || "";
  const isTokenExpired = Boolean(!cfg.refreshToken && cfg.tokenExpiresAt && Date.now() > cfg.tokenExpiresAt);
  const isConnected = Boolean((cfg.accessToken && !isTokenExpired) || cfg.refreshToken);

  if (isConnected && !cfg._googleContactsFullHealV6) {
    setImmediate(() => {
      healContaminatedGoogleContactsPostBoot(db).catch(() => {});
    });
  }

  res.json({
    enabled: Boolean(cfg.enabled),
    connected: isConnected,
    tokenExpired: isTokenExpired,
    connectedEmail: cfg.connectedEmail || "",
    connectedName: cfg.connectedName || "",
    connectedPicture: cfg.connectedPicture || "",
    clientId: cfg.clientId || defaultClientId,
    hasClientSecret: Boolean(cfg.clientSecret),
    lastSyncAt: cfg.lastSyncAt || null,
    totalGuests: allGuests.length,
    guestsWithPhoneCount: guestsWithPhone.length,
    syncedGuestsCount: syncedGuests.length,
    pendingSyncCount: Math.max(0, guestsWithPhone.length - syncedGuests.length),
    previewContacts,
    syncLogs: (cfg.syncLogs || []).slice(0, 20)
  });
});

// Salvar configuração ou conectar Access Token / Credenciais Google Contatos
app.post("/api/pms/guests/google-contacts/config", async (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev" && userAuth.role !== "recepcao" && userAuth.role !== "reception")) {
    return res.status(403).json({ error: "Acesso restrito." });
  }
  const cfg = ensureGoogleContactsConfig(db);
  const { enabled, clientId, clientSecret, accessToken, refreshToken, expiresIn } = req.body || {};

  if (enabled !== undefined) cfg.enabled = Boolean(enabled);
  if (clientId !== undefined && String(clientId).trim()) cfg.clientId = String(clientId).trim();
  if (clientSecret !== undefined && String(clientSecret).trim()) cfg.clientSecret = String(clientSecret).trim();
  if (refreshToken !== undefined && String(refreshToken).trim()) cfg.refreshToken = String(refreshToken).trim();

  if (accessToken && typeof accessToken === "string" && accessToken.trim()) {
    const cleanToken = accessToken.trim();
    cfg.accessToken = cleanToken;
    cfg.tokenExpiresAt = Date.now() + (Number(expiresIn || 3599) * 1000);
    cfg._googleContactsFullHealV5 = false;
    cfg._googleContactsFullHealV6 = false;

    try {
      const uRes = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
        headers: { Authorization: `Bearer ${cleanToken}` }
      });
      if (uRes.ok) {
        const uInfo = await uRes.json();
        if (uInfo.email) cfg.connectedEmail = uInfo.email;
        if (uInfo.name) cfg.connectedName = uInfo.name;
        if (uInfo.picture) cfg.connectedPicture = uInfo.picture;
      } else {
        const meRes = await fetch("https://people.googleapis.com/v1/people/me?personFields=names,emailAddresses,photos", {
          headers: { Authorization: `Bearer ${cleanToken}` }
        });
        if (meRes.ok) {
          const meData = await meRes.json();
          cfg.connectedEmail = meData.emailAddresses?.[0]?.value || cfg.connectedEmail || "Conta Google Conectada";
          cfg.connectedName = meData.names?.[0]?.displayName || cfg.connectedName || "Google Contatos";
          cfg.connectedPicture = meData.photos?.[0]?.url || cfg.connectedPicture || "";
        }
      }
    } catch (_) {}

    if (!cfg.connectedEmail) {
      cfg.connectedEmail = "Conta Google Conectada (People API)";
    }

    setImmediate(() => {
      healContaminatedGoogleContactsPostBoot(db).catch(() => {});
    });
  }

  saveDatabase();
  res.json({
    success: true,
    enabled: cfg.enabled,
    connected: Boolean(cfg.accessToken || cfg.refreshToken),
    connectedEmail: cfg.connectedEmail,
    connectedName: cfg.connectedName
  });
});

// Gera URL de autorização OAuth2 do Google Contatos
app.get("/api/pms/guests/google-contacts/oauth-url", (req, res) => {
  const cfg = ensureGoogleContactsConfig(db);
  const clientId = String(req.query.clientId || cfg.clientId || process.env.GOOGLE_CLIENT_ID || "").trim();
  const protocol = req.headers["x-forwarded-proto"] || req.protocol || "https";
  const host = req.headers["x-forwarded-host"] || req.get("host");
  const redirectUri = `${protocol}://${host}/api/pms/guests/google-contacts/oauth-callback`;

  const responseType = cfg.clientSecret ? "code" : "token";
  const params = new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirectUri,
    response_type: responseType,
    scope: "https://www.googleapis.com/auth/contacts https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/userinfo.profile",
    include_granted_scopes: "true",
    prompt: "consent"
  });
  if (responseType === "code") {
    params.set("access_type", "offline");
  }

  res.json({
    authUrl: `https://accounts.google.com/o/oauth2/v2/auth?${params.toString()}`,
    redirectUri,
    clientId,
    responseType
  });
});

// Callback OAuth2 (suporta tanto Authorization Code quanto Implicit Fragment no popup)
app.get("/api/pms/guests/google-contacts/oauth-callback", async (req, res) => {
  const cfg = ensureGoogleContactsConfig(db);
  const { code, error } = req.query;

  if (error) {
    return res.send(`<!DOCTYPE html><html><body style="font-family:sans-serif;padding:24px;text-align:center;">
      <h3>Autorização Google cancelada: ${String(error)}</h3>
      <script>setTimeout(() => window.close(), 2000);</script>
    </body></html>`);
  }

  if (code && cfg.clientId && cfg.clientSecret) {
    try {
      const protocol = req.headers["x-forwarded-proto"] || req.protocol || "https";
      const host = req.headers["x-forwarded-host"] || req.get("host");
      const redirectUri = `${protocol}://${host}/api/pms/guests/google-contacts/oauth-callback`;

      const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          code: String(code),
          client_id: cfg.clientId,
          client_secret: cfg.clientSecret,
          redirect_uri: redirectUri,
          grant_type: "authorization_code"
        }).toString()
      });
      if (tokenRes.ok) {
        const tokenData = await tokenRes.json();
        if (tokenData.access_token) cfg.accessToken = tokenData.access_token;
        if (tokenData.refresh_token) cfg.refreshToken = tokenData.refresh_token;
        cfg.tokenExpiresAt = Date.now() + (Number(tokenData.expires_in || 3599) * 1000);
        cfg.enabled = true;
        cfg._googleContactsFullHealV5 = false;
        cfg._googleContactsFullHealV6 = false;

        try {
          const uRes = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
            headers: { Authorization: `Bearer ${cfg.accessToken}` }
          });
          if (uRes.ok) {
            const uInfo = await uRes.json();
            cfg.connectedEmail = uInfo.email || cfg.connectedEmail;
            cfg.connectedName = uInfo.name || cfg.connectedName;
            cfg.connectedPicture = uInfo.picture || cfg.connectedPicture;
          }
        } catch (_) {}
        saveDatabase();
        setImmediate(() => {
          healContaminatedGoogleContactsPostBoot(db).catch(() => {});
        });
      }
    } catch (err) {
      console.error("[GoogleContacts OAuth Callback] Erro:", err);
    }
  }

  res.send(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Conectando Google Contatos...</title></head>
  <body style="font-family:system-ui,sans-serif;padding:32px;text-align:center;background:#0f172a;color:#f8fafc;">
    <h2>Conectando Google Contatos ao CRM CorpFlats...</h2>
    <p id="msg">Processando credencial de acesso...</p>
    <script>
      (async function() {
        const hash = window.location.hash ? window.location.hash.substring(1) : "";
        const params = new URLSearchParams(hash);
        const accessToken = params.get("access_token");
        const expiresIn = params.get("expires_in");
        if (accessToken) {
          await fetch("/api/pms/guests/google-contacts/config", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ accessToken, expiresIn, enabled: true }),
            credentials: "include"
          });
        }
        if (window.opener) {
          window.opener.postMessage({ type: "GOOGLE_CONTACTS_CONNECTED" }, "*");
        }
        document.getElementById("msg").innerText = "Conta Google conectada com sucesso! Esta janela será fechada.";
        setTimeout(() => window.close(), 800);
      })();
    </script>
  </body></html>`);
});

