// Detalhe 360º completo de um Hóspede (Ficha cadastral, mídias, FNHR e histórico unificado)
app.get("/api/pms/guests/:id", async (req, res) => {
  const id = Number(req.params.id);
  if (!db.guests) db.guests = [];
  reconcileAndMergeGuests(db);
  const guest = db.guests.find(g => g.id === id);
  if (!guest) return res.status(404).json({ error: "Hóspede não encontrado." });

  const cleanDoc = (guest.documentNumber || guest.document || "").replace(/\D/g, "");
  const cleanPhone = normalizePhone(guest.phone || "");
  const cleanEmail = (guest.email || "").trim().toLowerCase();
  const guestNameLower = normalizeName(guest.fullName || guest.name || "");
  const guestNameTokenCount = guestNameLower.split(/\s+/).filter(Boolean).length;

  // Histórico de Reservas (por ID, CPF, telefone ou nome composto, respeitando compatibilidade nominal)
  const guestReservations = (db.reservations || []).filter(r => {
    if (!areGuestNamesCompatible(r.guestName, guest.fullName || guest.name)) {
      return false;
    }
    const resDoc = (r.guestDocument || r.document || "").replace(/\D/g, "");
    const resPhone = normalizePhone(r.guestPhone || "");
    const resEmail = (r.guestEmail || "").trim().toLowerCase();
    const resName = normalizeName(r.guestName || "");
    return (r.guestId && r.guestId === guest.id) ||
           (cleanDoc && resDoc === cleanDoc) ||
           (cleanPhone && cleanPhone.length >= 8 && resPhone === cleanPhone) ||
           (cleanEmail && cleanEmail.includes("@") && resEmail === cleanEmail) ||
           (guestNameLower && guestNameTokenCount >= 2 && guestNameLower.length >= 5 && resName === guestNameLower) ||
           (cleanDoc && Array.isArray(r.guests) && r.guests.some(rg => (rg.cpf || "").replace(/\D/g, "") === cleanDoc));
  }).sort((a, b) => new Date(b.checkinDate || b.createdAt).getTime() - new Date(a.checkinDate || a.createdAt).getTime());

  // Histórico de Notas Fiscais
  const guestInvoices = (db.invoices || []).filter(inv => {
    const invDoc = (inv.tomadorCpfCnpj || "").replace(/\D/g, "");
    const invName = normalizeName(inv.tomadorNome || "");
    return (cleanDoc && invDoc === cleanDoc) || (guestNameLower && invName === guestNameLower);
  }).sort((a, b) => new Date(b.dataEmissao || 0).getTime() - new Date(a.dataEmissao || 0).getTime());

  // Backfill de mídias e dados de check-in caso não estejam no cadastro mestre
  let photoUrl = guest.photoUrl || null;
  let docPhotoUrl = guest.docPhotoUrl || null;
  let signatureUrl = guest.signatureUrl || null;
  let minorAuthDocUrl = guest.minorAuthDocUrl || null;
  let birthDate = guest.birthDate || "";
  let gender = guest.gender || "";
  let cep = String(guest.cep || guest.guestCep || guest.zipCode || "").replace(/\D/g, "");
  let street = guest.street || guest.logradouro || "";
  let streetNumber = guest.streetNumber || guest.number || guest.numero || "";
  let complement = guest.complement || guest.complemento || "";
  let neighborhood = guest.neighborhood || guest.bairro || "";
  let address = guest.address || "";
  let city = guest.city || guest.cidade || "";
  let state = guest.state || guest.uf || "";
  let vehiclePlate = guest.vehiclePlate || "";
  let vehicleBrand = guest.vehicleBrand || "";
  let vehicleModel = guest.vehicleModel || "";
  let vehicleColor = guest.vehicleColor || "";
  let fnhrCompleted = Boolean(guest.fnhrCompleted);
  let fnhrCompletedAt = guest.fnhrCompletedAt || null;

  const extractCepFromText = (txt) => {
    if (!txt) return "";
    const m = String(txt).match(/\b(\d{5})-?(\d{3})\b/);
    return m ? `${m[1]}${m[2]}` : "";
  };

  for (const s of guestReservations) {
    if (!photoUrl && (s.selfieUrl || s.photoUrl)) photoUrl = s.selfieUrl || s.photoUrl;
    if (!docPhotoUrl && (s.docPhotoUrl || s.documentPhotoUrl)) docPhotoUrl = s.docPhotoUrl || s.documentPhotoUrl;
    if (!signatureUrl && s.signatureUrl) signatureUrl = s.signatureUrl;
    if (!cep && (s.guestCep || s.cep || s.zipCode)) {
      cep = String(s.guestCep || s.cep || s.zipCode).replace(/\D/g, "");
    }
    if (!cep && s.fnrhAuditTrail?.guestAddress) {
      cep = extractCepFromText(s.fnrhAuditTrail.guestAddress);
    }
    if (!street && (s.guestStreet || s.street)) street = s.guestStreet || s.street;
    if (!streetNumber && (s.guestStreetNumber || s.streetNumber || s.number)) streetNumber = s.guestStreetNumber || s.streetNumber || s.number;
    if (!complement && (s.guestComplement || s.complement)) complement = s.guestComplement || s.complement;
    if (!neighborhood && (s.guestNeighborhood || s.neighborhood)) neighborhood = s.guestNeighborhood || s.neighborhood;
    if (!address && (s.guestAddress || s.address)) address = s.guestAddress || s.address;
    if (!city && (s.guestCity || s.city)) city = s.guestCity || s.city;
    if (!state && (s.guestState || s.state)) state = s.guestState || s.state;
    if (!vehiclePlate && s.vehicle?.plate) {
      vehiclePlate = s.vehicle.plate;
      vehicleBrand = s.vehicle.brand || "";
      vehicleModel = s.vehicle.model || "";
      vehicleColor = s.vehicle.color || "";
    }
    if (s.fnhrCompleted) {
      fnhrCompleted = true;
      if (!fnhrCompletedAt) fnhrCompletedAt = s.fnhrCompletedAt || s.updatedAt;
    }
    if (Array.isArray(s.guests)) {
      const matchSlot = s.guests.find(rg =>
        (cleanDoc && (rg.cpf || "").replace(/\D/g, "") === cleanDoc) ||
        (guestNameLower && normalizeName(rg.name || "") === guestNameLower) ||
        rg.guestId === guest.id
      ) || s.guests[0];

      if (matchSlot) {
        if (!photoUrl && matchSlot.selfieUrl) photoUrl = matchSlot.selfieUrl;
        if (!docPhotoUrl && matchSlot.docPhotoUrl) docPhotoUrl = matchSlot.docPhotoUrl;
        if (!signatureUrl && matchSlot.signatureUrl) signatureUrl = matchSlot.signatureUrl;
        if (!minorAuthDocUrl && matchSlot.minorAuthDocUrl) minorAuthDocUrl = matchSlot.minorAuthDocUrl;
        if (!birthDate && matchSlot.birthDate) birthDate = matchSlot.birthDate;
        if (!gender && matchSlot.gender) gender = matchSlot.gender;
        if (!cep && (matchSlot.cep || matchSlot.guestCep || matchSlot.zipCode)) {
          cep = String(matchSlot.cep || matchSlot.guestCep || matchSlot.zipCode).replace(/\D/g, "");
        }
        if (!cep && matchSlot.fnrhAuditTrail?.guestAddress) {
          cep = extractCepFromText(matchSlot.fnrhAuditTrail.guestAddress);
        }
        if (!street && matchSlot.street) street = matchSlot.street;
        if (!streetNumber && (matchSlot.streetNumber || matchSlot.number)) streetNumber = matchSlot.streetNumber || matchSlot.number;
        if (!complement && matchSlot.complement) complement = matchSlot.complement;
        if (!neighborhood && matchSlot.neighborhood) neighborhood = matchSlot.neighborhood;
        if (!address && matchSlot.address) address = matchSlot.address;
        if (!city && matchSlot.city) city = matchSlot.city;
        if (!state && matchSlot.state) state = matchSlot.state;
        if (matchSlot.hasCompletedCheckin) {
          fnhrCompleted = true;
          if (!fnhrCompletedAt) fnhrCompletedAt = matchSlot.checkinCompletedAt;
        }
      }
    }
  }

  for (const inv of guestInvoices) {
    const invHasRealAddr = Boolean(
      (inv.tomadorEndereco && !isGenericPelincaAddr(inv.tomadorEndereco)) ||
      (inv.tomadorCep && !isGenericPelincaCep(inv.tomadorCep))
    );
    if (!invHasRealAddr) continue;
    if ((!cep || isGenericPelincaCep(cep)) && inv.tomadorCep && !isGenericPelincaCep(inv.tomadorCep)) {
      cep = String(inv.tomadorCep).replace(/\D/g, "");
    }
    if (!address && inv.tomadorEndereco && !isGenericPelincaAddr(inv.tomadorEndereco)) address = inv.tomadorEndereco;
    if (!streetNumber && inv.tomadorNumero && !(inv.tomadorNumero === "100" && isGenericPelincaAddr(inv.tomadorEndereco))) streetNumber = inv.tomadorNumero;
    if (!complement && inv.tomadorComplemento) complement = inv.tomadorComplemento;
    if (!neighborhood && inv.tomadorBairro && !isGenericPelincaBairro(inv.tomadorBairro)) neighborhood = inv.tomadorBairro;
    if (!city && inv.tomadorCidade) city = inv.tomadorCidade;
    if (!state && inv.tomadorUf) state = inv.tomadorUf;
  }
  if (address && isGenericPelincaAddr(address) && (!streetNumber || streetNumber === "100")) address = "";
  if (street && isGenericPelincaAddr(street) && (!streetNumber || streetNumber === "100")) street = "";
  if (!address && !street && streetNumber === "100") streetNumber = "";
  if (!address && !street && neighborhood && isGenericPelincaBairro(neighborhood)) neighborhood = "";
  if (!address && !street && cep && isGenericPelincaCep(cep)) cep = "";

  if (!cep && address) {
    cep = extractCepFromText(address);
  }

  // Normaliza cidade caso contenha "/ UF" duplicado (ex: "Rio de Janeiro / RJ")
  if (city && city.includes("/")) {
    const parts = city.split("/").map(p => p.trim()).filter(Boolean);
    if (parts.length >= 2 && parts[parts.length - 1].length === 2) {
      if (!state) state = parts[parts.length - 1].toUpperCase();
      city = parts.slice(0, -1).join(" / ");
    }
  }

  // Caso o hóspede tenha logradouro + cidade + UF mas o CEP não tenha sido salvo anteriormente, busca reversamente no ViaCEP
  if ((!cep || cep.length < 8) && (street || address) && city) {
    const parsedAddr = normalizeTomadorAddressFields({
      endereco: address,
      logradouro: street,
      numero: streetNumber,
      complemento: complement,
      bairro: neighborhood,
      cep,
      cidade: city,
      uf: state || "RJ"
    });
    const lookupStreet = (street || parsedAddr.logradouro || "")
      .split(",")[0]
      .split(" - ")[0]
      .replace(/\b(apt|apto|apartamento|bloco|casa|lote|sala|nº|num)\b.*$/i, "")
      .trim();
    const lookupCity = (city || parsedAddr.cidade || "").split("/")[0].trim();
    const lookupUf = (state || parsedAddr.uf || "RJ").trim().toUpperCase();
    if (lookupStreet.length >= 3 && lookupCity.length >= 3 && lookupUf.length === 2 && !isGenericPelincaStreet(lookupStreet)) {
      try {
        const viaRes = await fetch(
          `https://viacep.com.br/ws/${encodeURIComponent(lookupUf)}/${encodeURIComponent(lookupCity)}/${encodeURIComponent(lookupStreet)}/json/`,
          { signal: AbortSignal.timeout(2500) }
        );
        if (viaRes.ok) {
          const viaList = await viaRes.json();
          if (Array.isArray(viaList) && viaList.length > 0) {
            const normBairro = normalizeName(neighborhood || parsedAddr.bairro || "");
            const bestMatch = (normBairro && viaList.find(item => normalizeName(item.bairro || "") === normBairro)) || viaList[0];
            const foundCep = String(bestMatch?.cep || "").replace(/\D/g, "");
            if (foundCep.length === 8) {
              cep = foundCep;
            }
          }
        }
      } catch {}
    }
  }

  // Persiste enriquecimento no cadastro mestre
  let changed = false;
  if (!guest.photoUrl && photoUrl) { guest.photoUrl = photoUrl; changed = true; }
  if (!guest.docPhotoUrl && docPhotoUrl) { guest.docPhotoUrl = docPhotoUrl; changed = true; }
  if (!guest.signatureUrl && signatureUrl) { guest.signatureUrl = signatureUrl; changed = true; }
  if (!guest.birthDate && birthDate) { guest.birthDate = birthDate; changed = true; }
  if (!guest.gender && gender) { guest.gender = gender; changed = true; }
  if ((!guest.cep || isGenericPelincaCep(guest.cep)) && cep) { guest.cep = cep; changed = true; }
  if (!guest.street && street) { guest.street = street; guest.logradouro = street; changed = true; }
  if (!guest.streetNumber && streetNumber) { guest.streetNumber = streetNumber; guest.number = streetNumber; guest.numero = streetNumber; changed = true; }
  if (!guest.complement && complement) { guest.complement = complement; guest.complemento = complement; changed = true; }
  if (!guest.neighborhood && neighborhood) { guest.neighborhood = neighborhood; guest.bairro = neighborhood; changed = true; }
  if (!guest.address && address) { guest.address = address; changed = true; }
  if (city && guest.city !== city) { guest.city = city; guest.cidade = city; changed = true; }
  if (!guest.state && state) { guest.state = state; guest.uf = state; changed = true; }
  if (!guest.vehiclePlate && vehiclePlate) {
    guest.vehiclePlate = vehiclePlate;
    guest.vehicleBrand = vehicleBrand;
    guest.vehicleModel = vehicleModel;
    guest.vehicleColor = vehicleColor;
    changed = true;
  }
  if (!guest.fnhrCompleted && fnhrCompleted) {
    guest.fnhrCompleted = true;
    guest.fnhrCompletedAt = fnhrCompletedAt || new Date().toISOString();
    changed = true;
  }
  if (changed) saveDatabase();

  // Histórico de Pedidos de Café da Manhã
  const guestBreakfastOrders = (db.breakfastOrders || []).filter(bo => {
    return (cleanDoc && bo.guestDocument === cleanDoc) || (guestNameLower && normalizeName(bo.guestName || "") === guestNameLower);
  });

  // Histórico de Pedidos de Frigobar
  const guestResCodes = new Set(guestReservations.map(r => r.code).filter(Boolean));
  const guestResIds = new Set(guestReservations.map(r => String(r.id)).filter(Boolean));
  const allMinibarOrders = Array.isArray(db.minibarOrders) ? db.minibarOrders : [];
  const guestMinibarOrders = allMinibarOrders.filter(o => {
    if (!o) return false;
    const oDoc = (o.guestDocument || "").replace(/\D/g, "");
    const oPhone = normalizePhone(o.guestPhone || "");
    const oName = normalizeName(o.guestName || "");
    return (cleanDoc && oDoc === cleanDoc) ||
           (cleanPhone && cleanPhone.length >= 8 && oPhone === cleanPhone) ||
           (o.reservationCode && guestResCodes.has(o.reservationCode)) ||
           (o.reservationId && guestResIds.has(String(o.reservationId))) ||
           (guestNameLower && guestNameLower.length >= 5 && oName === guestNameLower);
  }).sort((a, b) => new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime());

  const minibarSpent = guestMinibarOrders
    .filter(o => o.paymentStatus === "pago")
    .reduce((acc, o) => acc + (parseFloat(o.totalAmount || 0) || 0), 0);

  // Métricas
  const baseSpent = guestReservations.reduce((acc, r) => acc + (parseFloat(r.totalAmount || r.totalPrice || r.price || 0) || 0), 0) ||
                    guestInvoices.reduce((acc, i) => acc + (parseFloat(i.valorServico || 0) || 0), 0);
  const totalSpent = baseSpent + minibarSpent;

  res.json({
    ...guest,
    fullName: guest.fullName || guest.name,
    name: guest.fullName || guest.name,
    guestCode: guest.guestCode || `HOSP-${String(guest.id).padStart(5, "0")}`,
    documentNumber: cleanDoc,
    document: cleanDoc,
    photoUrl: guest.photoUrl || photoUrl,
    docPhotoUrl: guest.docPhotoUrl || docPhotoUrl,
    signatureUrl: guest.signatureUrl || signatureUrl,
    minorAuthDocUrl: guest.minorAuthDocUrl || minorAuthDocUrl,
    birthDate: guest.birthDate || birthDate,
    gender: guest.gender || gender,
    cep: guest.cep || cep || "",
    street: guest.street || street || "",
    logradouro: guest.logradouro || guest.street || street || "",
    streetNumber: guest.streetNumber || guest.number || streetNumber || "",
    number: guest.number || guest.streetNumber || streetNumber || "",
    numero: guest.numero || guest.number || guest.streetNumber || streetNumber || "",
    complement: guest.complement || complement || "",
    neighborhood: guest.neighborhood || neighborhood || "",
    address: guest.address || address,
    city: guest.city || city,
    state: guest.state || state,
    vehiclePlate: guest.vehiclePlate || vehiclePlate,
    vehicleBrand: guest.vehicleBrand || vehicleBrand,
    vehicleModel: guest.vehicleModel || vehicleModel,
    vehicleColor: guest.vehicleColor || vehicleColor,
    fnhrCompleted: Boolean(guest.fnhrCompleted || fnhrCompleted),
    fnhrCompletedAt: guest.fnhrCompletedAt || fnhrCompletedAt,
    totalSpent: Number(totalSpent.toFixed(2)),
    minibarSpent: Number(minibarSpent.toFixed(2)),
    totalStays: Math.max(guestReservations.length, guest.totalStays || 0),
    reservations: guestReservations,
    stays: guestReservations,
    invoices: guestInvoices,
    boletos: (() => {
      const gBoletos = (db.boletos || []).filter(b =>
        b && (
          (b.guestId && Number(b.guestId) === Number(guest.id)) ||
          (cleanDoc && onlyDigits(b.payer?.cpfCnpj || b.payerDocument || "") === cleanDoc) ||
          (b.reservationId && guestResIds.has(String(b.reservationId))) ||
          (b.reservationCode && guestResCodes.has(b.reservationCode))
        )
      ).map(b => enrichBoletoDynamicStatus(b));
      return gBoletos;
    })(),
    boletosSummary: (() => {
      const gBoletos = (db.boletos || []).filter(b =>
        b && (
          (b.guestId && Number(b.guestId) === Number(guest.id)) ||
          (cleanDoc && onlyDigits(b.payer?.cpfCnpj || b.payerDocument || "") === cleanDoc) ||
          (b.reservationId && guestResIds.has(String(b.reservationId))) ||
          (b.reservationCode && guestResCodes.has(b.reservationCode))
        )
      ).map(b => enrichBoletoDynamicStatus(b));
      return computeBoletosSummaryMetrics(gBoletos);
    })(),
    breakfastOrders: guestBreakfastOrders,
    minibarOrders: guestMinibarOrders.map(o => ({
      ...o,
      invoice: sanitizeMinibarInvoiceForResponse(o.invoice),
      invoiceFileUrl: o.invoice?.invoiceFileUrl || null,
      invoiceFileName: o.invoice?.invoiceFileName || null,
      invoiceNumber: o.invoice?.invoiceNumber || null,
      invoiceStatus: o.invoice?.status || null
    })),
    documents: guest.documents || [],
    callerIdDetails: buildGuestCallerIdContactData(db, guest),
    callerIdPreview: buildGuestCallerIdContactData(db, guest).displayName,
    googleContactResourceName: guest.googleContactResourceName || null,
    googleContactSyncedAt: guest.googleContactSyncedAt || null
  });
});

// Exportação da base de Hóspedes em CSV
app.get("/api/pms/guests/export/csv", (req, res) => {
  const userAuth = getAuthUser(req);
  if (!userAuth || (userAuth.role !== "admin" && userAuth.role !== "dev" && userAuth.role !== "recepcao" && userAuth.role !== "reception")) {
    return res.status(403).json({ error: "Acesso restrito à administração e recepção." });
  }
  if (!db.guests) db.guests = [];
  reconcileAndMergeGuests(db);

  const headers = ["ID", "Código", "Nome Completo", "CPF/CNPJ", "Telefone", "E-mail", "Cidade/UF", "Total Gasto (R$)", "Total Estadias", "Flat Mais Frequente", "FNHR Concluída", "Tags", "Empresa"];
  const rows = db.guests.map(g => {
    return [
      g.id,
      `"${g.guestCode || ''}"`,
      `"${(g.fullName || g.name || '').replace(/"/g, '""')}"`,
      `"${g.documentNumber || g.document || ''}"`,
      `"${g.phone || ''}"`,
      `"${g.email || ''}"`,
      `"${(g.city || '').replace(/"/g, '""')}"`,
      (g.totalSpent || 0).toFixed(2),
      g.totalStays || 1,
      g.favoriteFlat || '',
      g.fnhrCompleted ? "Sim" : "Não",
      `"${(Array.isArray(g.tags) ? g.tags.join(', ') : '')}"`,
      `"${(g.companyName || '').replace(/"/g, '""')}"`
    ].join(";");
  });

  const csvContent = "\uFEFF" + [headers.join(";"), ...rows].join("\r\n");
  res.setHeader("Content-Type", "text/csv; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename=hospedes_corpflats_${new Date().toISOString().substring(0, 10)}.csv`);
  res.send(csvContent);
});


const handleUpdateGuest = async (req, res) => {
  const id = Number(req.params.id);
  const guest = (db.guests || []).find(g => g.id === id);
  if (!guest) return res.status(404).json({ error: "Hóspede não encontrado." });

  const previousName = (guest.fullName || guest.name || "").trim();
  const previousEmail = (guest.email || "").trim().toLowerCase();
  const previousDoc = normalizeDoc(guest.document || guest.documentNumber);
  const previousPhone = normalizePhone(guest.phone);

  const fields = [
    "name", "fullName", "phone", "email", "docType", "document", "documentNumber", "birthDate", "gender",
    "nationality", "profession", "city", "notes", "tags",
    "isMonthlyGuest", "clientType", "companyId", "companyName", "companyData", "preferredInvoiceRecipient", "preferences", "autoEmitInvoice",
    "docPhotoUrl", "hasMinor", "minorAge", "isCamposResident", "riskAttentionAlert", "riskAttentionReason",
    "address", "street", "logradouro", "number", "streetNumber", "numero", "complement", "complemento",
    "neighborhood", "bairro", "cep", "state", "uf", "ibgeCode", "codigoMunicipio",
    "vehiclePlate", "vehicleBrand", "vehicleModel", "vehicleColor", "vehicle"
  ];
  for (const f of fields) {
    if (req.body[f] !== undefined) guest[f] = req.body[f];
  }

  if (req.body.phone !== undefined && Array.isArray(guest.additionalPhones)) {
    const newCleanPhone = normalizePhone(req.body.phone);
    guest.additionalPhones = guest.additionalPhones.filter(ap =>
      !phonesMatch(ap, newCleanPhone) && (!previousPhone || phonesMatch(newCleanPhone, previousPhone) || !phonesMatch(ap, previousPhone))
    );
  }

  if (req.body.name !== undefined || req.body.fullName !== undefined) {
    const nm = (req.body.fullName ?? req.body.name ?? "").trim();
    if (nm) {
      guest.name = nm;
      guest.fullName = nm;
    }
  }
  if (req.body.document !== undefined || req.body.documentNumber !== undefined) {
    const dc = String(req.body.document ?? req.body.documentNumber ?? "").trim();
    guest.document = dc;
    guest.documentNumber = dc;
  }

  // Normalização de chaves bilíngues de endereço e fiscais
  if (req.body.address !== undefined || req.body.street !== undefined || req.body.logradouro !== undefined || req.body.endereco !== undefined) {
    const a = (req.body.street ?? req.body.address ?? req.body.logradouro ?? req.body.endereco ?? "").trim();
    guest.address = (req.body.address ?? a).trim();
    guest.street = a;
    guest.logradouro = a;
  }
  if (req.body.number !== undefined || req.body.streetNumber !== undefined || req.body.numero !== undefined) {
    const n = String(req.body.streetNumber ?? req.body.number ?? req.body.numero ?? "").trim();
    guest.number = n;
    guest.streetNumber = n;
    guest.numero = n;
  }
  if (req.body.complement !== undefined || req.body.complemento !== undefined) {
    const c = (req.body.complement ?? req.body.complemento ?? "").trim();
    guest.complement = c;
    guest.complemento = c;
  }
  if (req.body.neighborhood !== undefined || req.body.bairro !== undefined) {
    const b = (req.body.neighborhood ?? req.body.bairro ?? "").trim();
    guest.neighborhood = b;
    guest.bairro = b;
  }
  if (req.body.cep !== undefined) {
    guest.cep = String(req.body.cep || "").replace(/\D/g, "");
  }
  if (req.body.city !== undefined || req.body.cidade !== undefined || req.body.municipio !== undefined) {
    const ct = (req.body.city ?? req.body.cidade ?? req.body.municipio ?? "").trim();
    guest.city = ct;
    guest.cidade = ct;
  }
  if (req.body.state !== undefined || req.body.uf !== undefined || req.body.estado !== undefined) {
    const st = String(req.body.state ?? req.body.uf ?? req.body.estado ?? "").trim().toUpperCase();
    guest.state = st;
    guest.uf = st;
  }
  if (req.body.ibgeCode !== undefined || req.body.codigoMunicipio !== undefined || req.body.codigoIbge !== undefined) {
    const ib = (req.body.ibgeCode ?? req.body.codigoMunicipio ?? req.body.codigoIbge ?? "").trim();
    guest.ibgeCode = ib;
    guest.codigoMunicipio = ib;
  }
  const prefVehiclePlate = req.body.preferences?.vehiclePlate !== undefined
    ? String(req.body.preferences.vehiclePlate || "").toUpperCase().trim()
    : undefined;
  if (req.body.vehicle !== undefined || req.body.vehiclePlate !== undefined || req.body.vehicleBrand !== undefined || req.body.vehicleModel !== undefined || req.body.vehicleColor !== undefined || prefVehiclePlate !== undefined) {
    if (req.body.vehicle === null) {
      guest.vehicle = null;
      guest.vehiclePlate = "";
      guest.vehicleBrand = "";
      guest.vehicleModel = "";
      guest.vehicleColor = "";
      if (guest.preferences && typeof guest.preferences === "object") {
        guest.preferences.vehiclePlate = "";
      }
    } else {
      const vObj = typeof req.body.vehicle === "object" && req.body.vehicle ? req.body.vehicle : {};
      const plate = String(vObj.plate ?? req.body.vehiclePlate ?? prefVehiclePlate ?? guest.vehiclePlate ?? "").toUpperCase().trim();
      const brand = String(vObj.brand ?? req.body.vehicleBrand ?? guest.vehicleBrand ?? "").trim();
      const model = String(vObj.model ?? req.body.vehicleModel ?? guest.vehicleModel ?? "").trim();
      const color = String(vObj.color ?? req.body.vehicleColor ?? guest.vehicleColor ?? "").trim();
      guest.vehiclePlate = plate;
      guest.vehicleBrand = brand;
      guest.vehicleModel = model;
      guest.vehicleColor = color;
      guest.vehicle = plate ? { plate, brand, model, color } : null;
      if (guest.preferences && typeof guest.preferences === "object") {
        guest.preferences.vehiclePlate = plate;
      }
    }
  }
  if (req.body.companyId !== undefined) {
    guest.companyId = req.body.companyId ? Number(req.body.companyId) : null;
    if (guest.companyId && db.companies) {
      const comp = db.companies.find(c => Number(c.id) === Number(guest.companyId));
      if (comp) {
        guest.companyName = comp.corporateName || comp.tradeName;
        guest.companyData = {
          cnpj: comp.cnpj || guest.companyData?.cnpj || "",
          companyName: guest.companyName || "",
          companyEmail: comp.financialEmail || comp.email || guest.companyData?.companyEmail || "",
          companyPhone: comp.phone || guest.companyData?.companyPhone || ""
        };
      }
      if (req.body.preferredInvoiceRecipient === undefined && !guest.preferredInvoiceRecipient) {
        guest.preferredInvoiceRecipient = "company";
      }
    } else if (!guest.companyId) {
      if (req.body.companyData === undefined && req.body.companyName === undefined) {
        guest.companyName = null;
      }
      if (req.body.preferredInvoiceRecipient === undefined) {
        guest.preferredInvoiceRecipient = "guest";
      }
    }
  }
  if (req.body.companyData !== undefined || req.body.companyCnpj !== undefined || req.body.companyEmail !== undefined || req.body.companyPhone !== undefined) {
    if (req.body.companyData === null) {
      guest.companyData = null;
    } else {
      const cObj = typeof req.body.companyData === "object" && req.body.companyData ? req.body.companyData : {};
      const existingComp = guest.companyData || {};
      const cnpj = String(cObj.cnpj ?? req.body.companyCnpj ?? existingComp.cnpj ?? "").trim();
      const companyName = String(cObj.companyName ?? req.body.companyName ?? existingComp.companyName ?? guest.companyName ?? "").trim();
      const companyEmail = String(cObj.companyEmail ?? req.body.companyEmail ?? existingComp.companyEmail ?? "").trim();
      const companyPhone = String(cObj.companyPhone ?? req.body.companyPhone ?? existingComp.companyPhone ?? "").trim();
      guest.companyData = (cnpj || companyName || companyEmail || companyPhone)
        ? { cnpj, companyName, companyEmail, companyPhone }
        : null;
      if (companyName) guest.companyName = companyName;
    }
  }

  if (req.body.docPhotoBase64) {
    try {
      const uploadedDoc = await uploadImageToStorage(req.body.docPhotoBase64, `doc_guest_${guest.id}`, db, "guests");
      guest.docPhotoUrl = uploadedDoc;
    } catch (e) {
      guest.docPhotoUrl = req.body.docPhotoBase64;
    }
  }

  // Sincroniza docPhotoUrl, hasMinor e isCamposResident com as reservas do hóspede
  if (guest.docPhotoUrl) {
    const cleanDoc = (guest.document || guest.documentNumber || "").replace(/\D/g, "");
    (db.reservations || []).forEach(r => {
      if (!isPlaceholderOrEmptyGuestName(r.guestName) && !areGuestNamesCompatible(r.guestName, guest.fullName || guest.name)) return;
      const resDoc = (r.guestDocument || r.document || "").replace(/\D/g, "");
      if ((cleanDoc && resDoc === cleanDoc) || r.guestId === guest.id) {
        if (!r.docPhotoUrl || req.body.docPhotoBase64 || req.body.docPhotoUrl) {
          r.docPhotoUrl = guest.docPhotoUrl;
        }
        if (r.guests?.[0] && (!r.guests[0].docPhotoUrl || req.body.docPhotoBase64 || req.body.docPhotoUrl)) {
          r.guests[0].docPhotoUrl = guest.docPhotoUrl;
        }
        if (guest.hasMinor !== undefined) r.hasMinor = Boolean(guest.hasMinor);
        if (guest.isCamposResident !== undefined) {
          r.isCamposResident = Boolean(guest.isCamposResident);
          if (guest.isCamposResident) {
            r.riskAttentionAlert = true;
            r.riskAttentionReason = guest.riskAttentionReason || "Radar Operacional: Hóspede com documento ou endereço de Campos dos Goytacazes/RJ";
          }
        }
      }
    });
  }

  if (req.body.isMonthlyGuest !== undefined || req.body.clientType !== undefined) {
    guest.isMonthlyGuest = Boolean(req.body.isMonthlyGuest || req.body.clientType === "mensalista");
    guest.clientType = guest.isMonthlyGuest ? "mensalista" : "avulso";

    // Atualiza imediatamente todas as reservas desse hóspede
    const cleanDoc = (guest.document || guest.documentNumber || "").replace(/\D/g, "");
    const cleanPhone = (guest.phone || "").replace(/\D/g, "");
    const guestNameLower = (guest.fullName || guest.name || "").trim().toLowerCase();

    (db.reservations || []).forEach(r => {
      if (!isPlaceholderOrEmptyGuestName(r.guestName) && !areGuestNamesCompatible(r.guestName, guest.fullName || guest.name)) return;
      const resDoc = (r.guestDocument || r.document || "").replace(/\D/g, "");
      const resPhone = (r.guestPhone || "").replace(/\D/g, "");
      const resName = (r.guestName || "").trim().toLowerCase();
      if ((cleanDoc && resDoc === cleanDoc) || (cleanPhone && resPhone === cleanPhone) || (guestNameLower && resName === guestNameLower) || r.guestId === guest.id) {
        r.isMonthlyGuest = guest.isMonthlyGuest;
        r.clientType = guest.clientType;
      }
    });
  }

  if (req.body.autoEmitInvoice !== undefined) {
    guest.autoEmitInvoice = Boolean(req.body.autoEmitInvoice);
    const cleanDoc = (guest.document || guest.documentNumber || "").replace(/\D/g, "");
    const cleanPhone = (guest.phone || "").replace(/\D/g, "");
    const guestNameLower = (guest.fullName || guest.name || "").trim().toLowerCase();

    (db.reservations || []).forEach(r => {
      if (!isPlaceholderOrEmptyGuestName(r.guestName) && !areGuestNamesCompatible(r.guestName, guest.fullName || guest.name)) return;
      const resDoc = (r.guestDocument || r.document || "").replace(/\D/g, "");
      const resPhone = (r.guestPhone || "").replace(/\D/g, "");
      const resName = (r.guestName || "").trim().toLowerCase();
      if ((cleanDoc && resDoc === cleanDoc) || (cleanPhone && resPhone === cleanPhone) || (guestNameLower && resName === guestNameLower) || r.guestId === guest.id) {
        r.autoEmitInvoice = guest.autoEmitInvoice;
      }
    });
  }

  applyCrmBillingConfigFields(guest, req.body);

  guest.updatedAt = new Date().toISOString();

  // Sincronização Bidirecional Atômica CRM -> Minha Conta (db.guestAccounts) e Reservas
  syncBidirectionalGuestProfile(db, guest, {
    ...req.body,
    ...(prefVehiclePlate !== undefined && req.body.vehiclePlate === undefined ? { vehiclePlate: prefVehiclePlate } : {}),
    previousName,
    previousEmail,
    previousDoc,
    previousPhone,
    guestId: guest.id
  });

  saveDatabase();
  res.json(guest);
};

app.put("/api/pms/guests/:id", handleUpdateGuest);
app.patch("/api/pms/guests/:id", handleUpdateGuest);

