app.put("/api/pms/amenities/essential-tags", (req, res) => {
  const { essentialTagIds } = req.body;
  if (Array.isArray(essentialTagIds)) {
    db.essentialTagIds = essentialTagIds;
    saveDatabase();
  }
  res.json({ essentialTagIds: db.essentialTagIds || [] });
});

app.post("/api/pms/guests", async (req, res) => {
  const {
    name, fullName, phone, email, docType, document, documentNumber,
    birthDate, gender, nationality, profession,
    city, cidade, municipio, notes, tags, isMonthlyGuest, clientType, autoEmitInvoice,
    companyId, companyName, companyData, preferredInvoiceRecipient, preferences, docPhotoUrl, docPhotoBase64, hasMinor, minorAge, isCamposResident,
    address, street, logradouro, endereco, number, streetNumber, numero, complement, complemento,
    neighborhood, bairro, cep, state, uf, estado, ibgeCode, codigoMunicipio, codigoIbge,
    vehiclePlate, vehicleBrand, vehicleModel, vehicleColor, vehicle
  } = req.body;
  const primName = (fullName || name || "").trim();
  if (!primName) return res.status(400).json({ error: "Nome é obrigatório." });
  if (!db.guests) db.guests = [];

  let finalDocUrl = docPhotoUrl || null;
  if (docPhotoBase64 && !finalDocUrl) {
    try {
      finalDocUrl = await uploadImageToStorage(docPhotoBase64, `doc_guest_${Date.now()}`, db, "guests");
    } catch (e) {
      finalDocUrl = docPhotoBase64;
    }
  }

  const isMonthly = Boolean(isMonthlyGuest || clientType === "mensalista");
  const resolvedAddress = (street || address || logradouro || endereco || "").trim();
  const resolvedNumber = String(streetNumber || number || numero || "").trim();
  const resolvedComplement = (complement || complemento || "").trim();
  const resolvedNeighborhood = (neighborhood || bairro || "").trim();
  const resolvedCep = (cep || "").toString().replace(/\D/g, "");
  const resolvedCity = (city || cidade || municipio || "").trim();
  const resolvedState = (state || uf || estado || "").trim().toUpperCase();
  const resolvedIbge = (ibgeCode || codigoMunicipio || codigoIbge || (resolvedCity.toLowerCase().includes("campos") ? "3301009" : "")).trim();
  const resolvedCompId = companyId ? Number(companyId) : null;
  let resolvedCompName = companyName || companyData?.companyName || null;
  if (resolvedCompId && !resolvedCompName && db.companies) {
    const c = db.companies.find(comp => Number(comp.id) === Number(resolvedCompId));
    if (c) resolvedCompName = c.corporateName || c.tradeName;
  }

  const vPlate = String(vehicle?.plate || vehiclePlate || preferences?.vehiclePlate || "").toUpperCase().trim();
  const vBrand = String(vehicle?.brand || vehicleBrand || "").trim();
  const vModel = String(vehicle?.model || vehicleModel || "").trim();
  const vColor = String(vehicle?.color || vehicleColor || "").trim();

  const nextId = db.guests.length > 0 ? Math.max(...db.guests.map(g => Number(g.id) || 0)) + 1 : 1;
  const newGuest = {
    id: nextId,
    guestCode: `HOSP-${String(nextId).padStart(5, "0")}`,
    name: primName,
    fullName: primName,
    phone: phone || "",
    email: email || "",
    docType: docType || "CPF",
    document: document || documentNumber || "",
    documentNumber: documentNumber || document || "",
    birthDate: birthDate || "",
    gender: gender || "",
    nationality: nationality || "Brasileira",
    profession: profession || "",
    address: resolvedAddress,
    street: resolvedAddress,
    logradouro: resolvedAddress,
    number: resolvedNumber,
    streetNumber: resolvedNumber,
    numero: resolvedNumber,
    complement: resolvedComplement,
    complemento: resolvedComplement,
    neighborhood: resolvedNeighborhood,
    bairro: resolvedNeighborhood,
    cep: resolvedCep,
    city: resolvedCity,
    cidade: resolvedCity,
    state: resolvedState,
    uf: resolvedState,
    ibgeCode: resolvedIbge,
    codigoMunicipio: resolvedIbge,
    vehiclePlate: vPlate,
    vehicleBrand: vBrand,
    vehicleModel: vModel,
    vehicleColor: vColor,
    vehicle: vPlate ? { plate: vPlate, brand: vBrand, model: vModel, color: vColor } : null,
    companyId: resolvedCompId,
    companyName: resolvedCompName,
    companyData: companyData || (resolvedCompName ? { cnpj: "", companyName: resolvedCompName, companyEmail: "", companyPhone: "" } : null),
    preferredInvoiceRecipient: preferredInvoiceRecipient === "company" || (preferredInvoiceRecipient === undefined && Boolean(resolvedCompId)) ? "company" : "guest",
    isMonthlyGuest: isMonthly,
    clientType: isMonthly ? "mensalista" : "avulso",
    autoEmitInvoice: Boolean(autoEmitInvoice),
    docPhotoUrl: finalDocUrl,
    hasMinor: Boolean(hasMinor),
    minorAge: minorAge ? Number(minorAge) : null,
    isCamposResident: Boolean(isCamposResident),
    notes: notes || "",
    preferences: preferences || {},
    tags: tags || [],
    createdAt: new Date().toISOString()
  };
  applyCrmBillingConfigFields(newGuest, req.body);
  db.guests.unshift(newGuest);
  syncBidirectionalGuestProfile(db, newGuest, { ...req.body, guestId: newGuest.id });
  saveDatabase();
  res.status(201).json(newGuest);
});


// Exclusão Total e Definitiva de Hóspede/Cliente e Todos os Dados Vinculados (LGPD & Operacional)
app.delete("/api/pms/guests/:id", async (req, res) => {
  try {
    const id = Number(req.params.id);
    if (!db.guests) db.guests = [];
    const guest = db.guests.find(g => g.id === id);
    if (!guest) {
      return res.status(404).json({ error: "Hóspede não encontrado." });
    }

    const cleanDoc = (guest.documentNumber || guest.document || "").replace(/\D/g, "");
    const cleanPhone = normalizePhone(guest.phone || "");
    const cleanEmail = (guest.email || "").trim().toLowerCase();
    const guestNameLower = normalizeName(guest.fullName || guest.name || "");
    const guestId = guest.id;
    const guestCode = guest.guestCode;

    // Função auxiliar para identificar correspondência com o hóspede
    const matchesGuest = (candDoc, candPhone, candEmail, candName, candGuestId) => {
      if (candGuestId && Number(candGuestId) === guestId) return true;
      const cDoc = (candDoc || "").replace(/\D/g, "");
      if (cleanDoc && cDoc && cleanDoc === cDoc) return true;
      const cPhone = normalizePhone(candPhone || "");
      if (cleanPhone && cleanPhone.length >= 8 && cPhone === cleanPhone) return true;
      const cEmail = (candEmail || "").trim().toLowerCase();
      if (cleanEmail && cleanEmail.includes("@") && cEmail === cleanEmail) return true;
      const cName = normalizeName(candName || "");
      if (guestNameLower && guestNameLower.length >= 5 && cName === guestNameLower) return true;
      return false;
    };

    // 1. Armazena documento e ID na lista anti-reconciliação
    if (!db.deletedGuestDocs) db.deletedGuestDocs = [];
    if (cleanDoc && !db.deletedGuestDocs.includes(cleanDoc)) {
      db.deletedGuestDocs.push(cleanDoc);
    }
    if (!db.deletedGuestIds) db.deletedGuestIds = [];
    if (!db.deletedGuestIds.includes(guestId)) {
      db.deletedGuestIds.push(guestId);
    }

    // 2. Coletar e remover arquivos físicos em disco (selfies, fotos de documentos, assinaturas)
    const filesToDelete = new Set();
    const addFileCandidate = (url) => {
      if (!url || typeof url !== "string") return;
      if (url.startsWith("/api/storage/files/")) {
        const rel = url.replace("/api/storage/files/", "");
        filesToDelete.add(path.join(UPLOADS_DIR, rel));
      } else if (url.startsWith("/uploads/")) {
        const rel = url.replace("/uploads/", "");
        filesToDelete.add(path.join(UPLOADS_DIR, rel));
      } else if (url.includes("uploads/")) {
        const parts = url.split("uploads/");
        filesToDelete.add(path.join(UPLOADS_DIR, parts[1]));
      }
    };

    addFileCandidate(guest.photoUrl);
    addFileCandidate(guest.docPhotoUrl);
    addFileCandidate(guest.signatureUrl);
    addFileCandidate(guest.minorAuthDocUrl);
    if (Array.isArray(guest.documents)) {
      guest.documents.forEach(d => addFileCandidate(d.url || d.fileUrl));
    }

    // 3. Expurgo em Reservas: titular e acompanhante
    const deletedReservationCodes = new Set();
    const remainingReservations = [];
    let reservationsCount = 0;

    for (const r of (db.reservations || [])) {
      const isTitular = matchesGuest(r.guestDocument || r.document, r.guestPhone, r.guestEmail, r.guestName, r.guestId);
      if (isTitular) {
        reservationsCount++;
        const code = r.code || r.reservationCode;
        if (code) deletedReservationCodes.add(code);
        addFileCandidate(r.selfieUrl || r.photoUrl);
        addFileCandidate(r.docPhotoUrl || r.documentPhotoUrl);
        addFileCandidate(r.signatureUrl);
        if (Array.isArray(r.guests)) {
          r.guests.forEach(rg => {
            addFileCandidate(rg.selfieUrl);
            addFileCandidate(rg.docPhotoUrl);
            addFileCandidate(rg.signatureUrl);
            addFileCandidate(rg.minorAuthDocUrl);
          });
        }
      } else {
        if (Array.isArray(r.guests)) {
          r.guests = r.guests.filter(rg => {
            const isAccompanier = matchesGuest(rg.cpf || rg.document, rg.phone, rg.email, rg.name, rg.guestId);
            if (isAccompanier) {
              addFileCandidate(rg.selfieUrl);
              addFileCandidate(rg.docPhotoUrl);
              addFileCandidate(rg.signatureUrl);
              addFileCandidate(rg.minorAuthDocUrl);
              return false;
            }
            return true;
          });
        }
        remainingReservations.push(r);
      }
    }
    db.reservations = remainingReservations;

    // Verificar documentos FNRH em disco relacionados a CPF, guestCode ou código de reserva
    try {
      const fnrhDir = path.join(UPLOADS_DIR, "fnrh_documents");
      if (fs.existsSync(fnrhDir)) {
        const fnrhFiles = fs.readdirSync(fnrhDir);
        for (const f of fnrhFiles) {
          if (
            (cleanDoc && f.includes(cleanDoc)) ||
            (guestCode && f.includes(guestCode)) ||
            Array.from(deletedReservationCodes).some(c => f.includes(c))
          ) {
            filesToDelete.add(path.join(fnrhDir, f));
          }
        }
      }
    } catch {}

    // Remover fisicamente os arquivos do disco
    for (const filePath of filesToDelete) {
      try {
        if (fs.existsSync(filePath)) {
          fs.unlinkSync(filePath);
        }
      } catch (err) {
        console.warn(`[Guest Delete] Erro ao remover arquivo ${filePath}:`, err.message);
      }
    }

    // 4. Remover de db.guests
    db.guests = (db.guests || []).filter(g => g.id !== guestId && (!cleanDoc || (g.documentNumber || g.document || "").replace(/\D/g, "") !== cleanDoc));

    // 5. Remover de db.guestAccounts (Contas do Portal do Hóspede)
    let accountsCount = 0;
    db.guestAccounts = (db.guestAccounts || []).filter(a => {
      const match = matchesGuest(a.cpf || a.document, a.phone, a.email, a.name || a.fullName, a.id);
      if (match) {
        accountsCount++;
        return false;
      }
      return true;
    });

    // 6. Remover Notas Fiscais (NFS-e / Invoices)
    let invoicesCount = 0;
    db.invoices = (db.invoices || []).filter(inv => {
      const match = matchesGuest(inv.tomadorCpfCnpj, inv.tomadorTelefone, inv.tomadorEmail, inv.tomadorNome) ||
                    (inv.reservationCode && deletedReservationCodes.has(inv.reservationCode)) ||
                    (inv.codigoReserva && deletedReservationCodes.has(inv.codigoReserva));
      if (match) {
        invoicesCount++;
        return false;
      }
      return true;
    });

    // 7. Remover Pedidos de Café da Manhã
    let ordersCount = 0;
    db.breakfastOrders = (db.breakfastOrders || []).filter(bo => {
      const match = matchesGuest(bo.guestDocument, bo.guestPhone, bo.guestEmail, bo.guestName) ||
                    (bo.reservationCode && deletedReservationCodes.has(bo.reservationCode));
      if (match) {
        ordersCount++;
        return false;
      }
      return true;
    });
    db.guestBreakfastOrders = (db.guestBreakfastOrders || []).filter(bo => {
      const match = (bo.reservationCode && deletedReservationCodes.has(bo.reservationCode)) || bo.guestId === guestId;
      return !match;
    });

    // 8. Limpar referências em solicitações de camareira (Cleaning Requests)
    if (Array.isArray(db.cleaningRequests)) {
      db.cleaningRequests.forEach(req => {
        if (req.reservationCode && deletedReservationCodes.has(req.reservationCode)) {
          req.reservationCode = null;
          req.guestName = null;
          req.guestPhone = null;
        }
        if (req.guestName && normalizeName(req.guestName) === guestNameLower) {
          req.guestName = null;
        }
        if (req.leavingGuest && normalizeName(req.leavingGuest) === guestNameLower) {
          req.leavingGuest = "Hóspede";
        }
        if (req.arrivingGuest && normalizeName(req.arrivingGuest) === guestNameLower) {
          req.arrivingGuest = null;
        }
      });
    }

    // 9. Autorizações de Garagem & Observações
    db.garageAuthorizations = (db.garageAuthorizations || []).filter(ga => {
      return !matchesGuest(ga.cpf || ga.document, ga.phone, null, ga.guestName) &&
             !(ga.reservationCode && deletedReservationCodes.has(ga.reservationCode));
    });
    db.observations = (db.observations || []).filter(obs => {
      return obs.guestId !== guestId &&
             !matchesGuest(obs.guestDocument, obs.guestPhone, null, obs.guestName) &&
             !(obs.reservationCode && deletedReservationCodes.has(obs.reservationCode));
    });

    // 10. Avaliações, Pesquisas e NPS
    db.surveys = (db.surveys || []).filter(s => s.guestId !== guestId && !(s.reservationCode && deletedReservationCodes.has(s.reservationCode)));
    db.npsResponses = (db.npsResponses || []).filter(s => s.guestId !== guestId && !(s.reservationCode && deletedReservationCodes.has(s.reservationCode)));
    db.reviews = (db.reviews || []).filter(r => r.guestId !== guestId && !(r.reservationCode && deletedReservationCodes.has(r.reservationCode)));

    // 11. Comunicações, FNRH Tokens e Auditoria FNRH
    db.reservationCommunications = (db.reservationCommunications || []).filter(c => c.guestId !== guestId && !(c.reservationCode && deletedReservationCodes.has(c.reservationCode)));
    db.fnrhAuditDocuments = (db.fnrhAuditDocuments || []).filter(d => d.guestId !== guestId && !(d.reservationCode && deletedReservationCodes.has(d.reservationCode)));
    db.fnrhSignatureTokens = (db.fnrhSignatureTokens || []).filter(t => t.guestId !== guestId && !(t.reservationCode && deletedReservationCodes.has(t.reservationCode)));
    db.fnrhInternalAuditLogs = (db.fnrhInternalAuditLogs || []).filter(l => l.guestId !== guestId && !(l.reservationCode && deletedReservationCodes.has(l.reservationCode)));

    // 12. Mensagens e Histórico de WhatsApp
    if (cleanPhone) {
      db.whatsappConversations = (db.whatsappConversations || []).filter(c => normalizePhone(c.phone || c.guestPhone || "") !== cleanPhone);
      db.whatsappHistory = (db.whatsappHistory || []).filter(h => normalizePhone(h.phone || h.guestPhone || "") !== cleanPhone);
      db.whatsappInboundMessages = (db.whatsappInboundMessages || []).filter(m => normalizePhone(m.phone || m.from || "") !== cleanPhone);
      db.whatsappDispatchHistory = (db.whatsappDispatchHistory || []).filter(d => normalizePhone(d.phone || "") !== cleanPhone);
    }

    // 13. Sentimento do Hóspede
    db.guestSentiment = (db.guestSentiment || []).filter(s => {
      return s.guestId !== guestId && (!cleanPhone || normalizePhone(s.guestPhone || "") !== cleanPhone);
    });

    // 14. Carrinhos Abandonados, Sessões e Contratos
    db.abandonedCarts = (db.abandonedCarts || []).filter(c => {
      const match = matchesGuest(null, c.guestPhone, c.guestEmail, c.guestName);
      return !match;
    });
    db.cartSessions = (db.cartSessions || []).filter(c => {
      const match = matchesGuest(null, c.guestPhone, c.guestEmail, c.guestName);
      return !match;
    });
    db.longStayContracts = (db.longStayContracts || []).filter(c => {
      return c.guestId !== guestId && !matchesGuest(c.guestDocument, c.guestPhone, c.guestEmail, c.guestName);
    });
    if (cleanEmail) {
      db.emailQueue = (db.emailQueue || []).filter(e => (e.to || "").trim().toLowerCase() !== cleanEmail);
    }

    // 15. Salvar banco de dados e registrar evento de auditoria
    saveDatabase();

    await logAuditEvent({
      level: "warn",
      category: "crm_security",
      action: "guest_permanently_deleted",
      actor: "admin",
      details: {
        guestId,
        guestCode,
        guestName: guest.fullName || guest.name,
        document: cleanDoc,
        deletedReservationsCount: reservationsCount,
        deletedInvoicesCount: invoicesCount,
        deletedBreakfastOrdersCount: ordersCount,
        deletedAccountsCount: accountsCount,
        deletedFilesCount: filesToDelete.size
      }
    });

    res.json({
      success: true,
      message: `Cliente ${guest.fullName || guest.name} e todos os seus dados vinculados foram excluídos com sucesso.`,
      stats: {
        reservationsDeleted: reservationsCount,
        invoicesDeleted: invoicesCount,
        breakfastOrdersDeleted: ordersCount,
        accountsDeleted: accountsCount,
        filesDeleted: filesToDelete.size
      }
    });
  } catch (err) {
    console.error("[Guest Delete] Erro ao excluir cliente:", err);
    res.status(500).json({ error: "Erro interno ao excluir cliente: " + err.message });
  }
});

// Room Blocks (Manutenção / Proprietário)
app.post("/api/pms/blocks", (req, res) => {
  const { flatId, startDate, endDate, reason = "manutencao", notes = "" } = req.body;
  if (!flatId || !startDate || !endDate) return res.status(400).json({ error: "Preencha quarto e período." });
  const flat = db.flats.find(f => f.id === Number(flatId));
  if (!flat) return res.status(404).json({ error: "Quarto não encontrado." });

  if (!db.roomBlocks) db.roomBlocks = [];
  const newBlock = {
    id: db.roomBlocks.length > 0 ? Math.max(...db.roomBlocks.map(b => b.id)) + 1 : 1,
    flatId: flat.id,
    flatNumber: flat.number,
    startDate,
    endDate,
    reason,
    notes,
    createdAt: new Date().toISOString()
  };
  db.roomBlocks.push(newBlock);
  saveDatabase();
  try {
    notifyPmsMutation(db, {
      type: "block_created",
      minDate: newBlock.startDate,
      maxDate: newBlock.endDate
    });
  } catch (_) {}
  res.status(201).json(newBlock);
});

const handleUpdateRoomBlock = (req, res) => {
  const rawId = String(req.params.id || "").trim();
  const numId = Number(rawId);
  const { flatId, startDate, endDate, reason, notes } = req.body || {};

  if (!startDate || !endDate) {
    return res.status(400).json({ error: "Preencha as datas de início e fim do bloqueio." });
  }
  const normalizedStart = startDate <= endDate ? startDate : endDate;
  const normalizedEnd = startDate <= endDate ? endDate : startDate;

  // Caso seja um bloqueio dinâmico de Ordem de Serviço em andamento (service_block_<orderId>_<flatId>)
  if (rawId.startsWith("service_block_")) {
    const withoutPrefix = rawId.replace(/^service_block_/, "");
    const lastUnderscore = withoutPrefix.lastIndexOf("_");
    const orderId = lastUnderscore > 0 ? withoutPrefix.slice(0, lastUnderscore) : withoutPrefix;
    const sFlatId = lastUnderscore > 0 ? Number(withoutPrefix.slice(lastUnderscore + 1)) : Number(flatId);
    const order = (db.serviceOrders || []).find(o => String(o.id) === String(orderId));
    if (!order) return res.status(404).json({ error: "Ordem de serviço do bloqueio não encontrada." });

    const oflat = (order.flats || []).find(f => Number(f.flatId) === Number(sFlatId));
    const oldStart = oflat?.customBlockStartDate || order.blockStartDate || normalizedStart;
    const oldEnd = oflat?.customBlockEndDate || order.blockEndDate || normalizedEnd;
    if (oflat) {
      oflat.customBlockStartDate = normalizedStart;
      oflat.customBlockEndDate = normalizedEnd;
    }
    syncServiceOrderRoomBlocks(order);
    saveDatabase("update_service_room_block");
    try {
      notifyPmsMutation(db, {
        type: "block_updated",
        minDate: oldStart < normalizedStart ? oldStart : normalizedStart,
        maxDate: oldEnd > normalizedEnd ? oldEnd : normalizedEnd
      });
    } catch (_) {}
    return res.json({
      id: rawId,
      flatId: oflat ? oflat.flatId : sFlatId,
      flatNumber: oflat ? oflat.flatNumber : String(sFlatId),
      startDate: normalizedStart,
      endDate: normalizedEnd,
      reason: "service_order",
      isServiceBlock: true,
      serviceOrderId: order.id
    });
  }

  if (!db.roomBlocks) db.roomBlocks = [];
  const block = db.roomBlocks.find(b => b.id === numId || String(b.id) === rawId);
  if (!block) return res.status(404).json({ error: "Bloqueio não encontrado." });

  const oldStart = block.startDate || normalizedStart;
  const oldEnd = block.endDate || normalizedEnd;

  if (flatId !== undefined && flatId !== null) {
    const flat = (db.flats || []).find(f => f.id === Number(flatId));
    if (!flat) return res.status(404).json({ error: "Quarto não encontrado." });
    block.flatId = flat.id;
    block.flatNumber = flat.number;
  }

  block.startDate = normalizedStart;
  block.endDate = normalizedEnd;
  if (reason !== undefined) block.reason = reason;
  if (notes !== undefined) block.notes = notes;
  block.updatedAt = new Date().toISOString();

  // Se o bloqueio estiver vinculado a uma Ordem de Serviço, sincroniza as datas customizadas na OS
  if (block.serviceOrderId) {
    const linkedOrder = (db.serviceOrders || []).find(o => String(o.id) === String(block.serviceOrderId));
    if (linkedOrder) {
      const oflat = (linkedOrder.flats || []).find(f => Number(f.flatId) === Number(block.flatId));
      if (oflat) {
        oflat.customBlockStartDate = normalizedStart;
        oflat.customBlockEndDate = normalizedEnd;
      }
    }
  }

  saveDatabase("update_room_block");
  try {
    notifyPmsMutation(db, {
      type: "block_updated",
      minDate: oldStart < normalizedStart ? oldStart : normalizedStart,
      maxDate: oldEnd > normalizedEnd ? oldEnd : normalizedEnd
    });
  } catch (_) {}

  res.json(block);
};

app.put("/api/pms/blocks/:id", handleUpdateRoomBlock);
app.patch("/api/pms/blocks/:id", handleUpdateRoomBlock);

app.delete("/api/pms/blocks/:id", (req, res) => {
  const id = Number(req.params.id);
  const block = (db.roomBlocks || []).find(b => b.id === id);
  db.roomBlocks = (db.roomBlocks || []).filter(b => b.id !== id);
  saveDatabase();
  if (block) {
    try {
      notifyPmsMutation(db, {
        type: "block_deleted",
        minDate: block.startDate,
        maxDate: block.endDate
      });
    } catch (_) {}
  }
  res.json({ success: true });
});

// ── Reception Tablet & Portaria Endpoints (Open Operational Mode — Sanitized) ─
function formatReceptionChannelLabel(r) {
  if (!r || typeof r !== "object") return "Site CorpFlats";
  if (r.channelLabel && String(r.channelLabel).trim()) return String(r.channelLabel).trim();
  const raw = String(r.channel || r.source || "").toLowerCase().trim();
  if (
    raw.includes("b2b") ||
    raw.includes("corporat") ||
    raw.includes("agenc") ||
    raw.includes("agênc") ||
    r.isCorporate ||
    r.isB2B ||
    r.agencyId ||
    r.b2bReservationNumber ||
    r.b2bLocatorRloc
  ) {
    return "Agência / B2B";
  }
  if (raw.includes("booking")) return "Booking.com";
  if (raw.includes("airbnb")) return "Airbnb";
  if (raw.includes("expedia")) return "Expedia";
  if (raw.includes("decolar")) return "Decolar";
  if (raw.includes("whats") || raw.includes("wpp") || raw === "direta" || raw === "direto") return "WhatsApp";
  if (raw.includes("site") || raw.includes("motor") || raw.includes("corpflats") || raw === "direct") return "Site CorpFlats";
  if (raw.includes("balcao") || raw.includes("balcão") || raw.includes("presencial") || raw.includes("recepcao") || raw.includes("recepção")) {
    return "Recepção / Balcão";
  }
  const orig = String(r.channel || r.source || "").trim();
  return orig ? orig.charAt(0).toUpperCase() + orig.slice(1) : "Site CorpFlats";
}

export function evaluateReceptionEarlyCheckin(r, {
  isRoomReady = true,
  cleaningStatus = "clean",
  cleaningLabel = "✨ Limpo",
  bNow = null,
  settings = null,
  allCheckinDone = false,
  someCheckinDone = false,
  completedCount = 0,
  totalCount = 1,
  isReSignatureNeeded = false
} = {}) {
  const activeBNow = bNow || getBrasiliaNow();
  const activeSettings = settings || db?.settings || {};
  const today = activeBNow.date;
  const currentTimeHHMM = activeBNow.timeStr || `${String(activeBNow.hour || 0).padStart(2, "0")}:${String(activeBNow.minute || 0).padStart(2, "0")}`;
  const standardCheckinTime = activeSettings?.checkinTime || "14:00";

  const resCheckinDate = String(r?.checkinDate || "").substring(0, 10);
  const isCheckinDatePast = Boolean(resCheckinDate && resCheckinDate < today);
  const isCheckinDateToday = Boolean(!resCheckinDate || resCheckinDate === today);
  const isCheckinDateFuture = Boolean(resCheckinDate && resCheckinDate > today);

  // Regra unificada da Sofia:
  // - Site / Direto / WhatsApp: cortesia grátis a partir das 10:00 (com flat limpo)
  // - Booking / Airbnb / Agência (OTA / B2B): cortesia grátis a partir das 12:00 (com flat limpo)
  // - Antes desses horários: somente com autorização/pagamento registrado pela Administração
  const isOtaOrB2b = isOtaOrB2bReservation(r);
  const channelLabel = formatReceptionChannelLabel(r);
  const freeEarlyTime = isOtaOrB2b ? "12:00" : "10:00";

  const hasPendingEarlyPayment = Boolean(r?.pendingEarlyCheckin && r.pendingEarlyCheckin.status === "pending_payment");
  const isPaidEarly = Boolean(r?.pendingEarlyCheckin && r.pendingEarlyCheckin.status === "paid");
  const isEarlyAuthorizedByAdmin = Boolean(r?.earlyCheckinAuthorized || isPaidEarly);

  const validAuthorizedTime = (typeof r?.earlyCheckinTime === "string" && /^\d{2}:\d{2}$/.test(r.earlyCheckinTime.trim()))
    ? r.earlyCheckinTime.trim()
    : null;

  let effectiveAllowedTime = freeEarlyTime;
  if (isEarlyAuthorizedByAdmin) {
    const adminTime = validAuthorizedTime || "00:00";
    effectiveAllowedTime = adminTime < freeEarlyTime ? adminTime : freeEarlyTime;
  }

  let isTimeAllowed = false;
  if (isCheckinDatePast) {
    isTimeAllowed = true;
  } else if (isCheckinDateFuture) {
    isTimeAllowed = false;
  } else {
    isTimeAllowed = currentTimeHHMM >= effectiveAllowedTime;
  }

  const isRegularCheckinWindow = isCheckinDatePast || (isCheckinDateToday && currentTimeHHMM >= standardCheckinTime);

  let earlyCheckinStatus = "Não liberado";
  let earlyCheckinReason = "";
  const formattedCheckinBr = resCheckinDate ? resCheckinDate.split("-").reverse().join("/") : "";

  if (isCheckinDateFuture) {
    earlyCheckinStatus = "Aguardando data";
    earlyCheckinReason = `Entrada prevista para ${formattedCheckinBr} (cortesia a partir das ${freeEarlyTime} no dia da chegada)`;
  } else if (!isTimeAllowed) {
    earlyCheckinStatus = "Não liberado";
    if (isEarlyAuthorizedByAdmin && validAuthorizedTime) {
      earlyCheckinReason = `Autorizado pela Administração a partir das ${validAuthorizedTime} (horário atual: ${currentTimeHHMM})`;
    } else {
      earlyCheckinReason = isOtaOrB2b
        ? `${channelLabel}: liberado grátis somente a partir das 12:00 (antes das 12:00 exige autorização da Administração)`
        : `${channelLabel}: liberado grátis a partir das 10:00 (antes das 10:00 exige autorização da Administração)`;
    }
  } else if (!isRoomReady) {
    earlyCheckinStatus = "Aguardando limpeza";
    earlyCheckinReason = `Horário permitido (a partir das ${effectiveAllowedTime}), aguardando limpeza do flat`;
  } else {
    earlyCheckinStatus = "Liberado";
    if (isEarlyAuthorizedByAdmin && currentTimeHHMM < freeEarlyTime) {
      earlyCheckinReason = validAuthorizedTime
        ? `Autorizado pela Administração (a partir das ${validAuthorizedTime})`
        : "Autorizado pela Administração";
    } else if (!isRegularCheckinWindow) {
      earlyCheckinReason = `Cortesia ${isOtaOrB2b ? "OTA/Agência" : "Site/Direto/WhatsApp"} liberada (a partir das ${freeEarlyTime})`;
    } else {
      earlyCheckinReason = `Horário regular liberado (${standardCheckinTime})`;
    }
  }

  const blockedReasons = [];
  if (isCheckinDateFuture) {
    blockedReasons.push(`Data de entrada prevista apenas para ${formattedCheckinBr}`);
  }
  if (isReSignatureNeeded) {
    blockedReasons.push("Re-assinatura obrigatória do Check-in Digital pendente");
  } else if (completedCount === 0) {
    blockedReasons.push(`Check-in Digital pendente (0/${totalCount} concluído)`);
  }
  if (!isCheckinDateFuture && !isTimeAllowed) {
    blockedReasons.push(`Horário atual (${currentTimeHHMM}) anterior às ${effectiveAllowedTime}${isEarlyAuthorizedByAdmin ? " (horário autorizado pela Administração)" : " sem autorização da Administração"}`);
  }
  if (!isRoomReady) {
    blockedReasons.push(`Apartamento ainda não está limpo (${cleaningLabel})`);
  }

  const canAuthorizeEntry = !isCheckinDateFuture && !isReSignatureNeeded && completedCount > 0 && isTimeAllowed && isRoomReady;

  let entryMessage = "";
  let entryBadgeType = "neutral";
  if (isCheckinDateFuture) {
    entryMessage = `Entrada prevista para ${formattedCheckinBr}`;
    entryBadgeType = "warning";
  } else if (isReSignatureNeeded) {
    entryMessage = "Check-in Pendente (Re-assinatura de Termo Obrigatória)";
    entryBadgeType = "error";
  } else if (completedCount === 0) {
    entryMessage = `Check-in Digital Pendente (0/${totalCount} concluído)`;
    entryBadgeType = "error";
  } else if (!isTimeAllowed) {
    entryMessage = isEarlyAuthorizedByAdmin && validAuthorizedTime
      ? `Aguardando Horário Autorizado pela Administração (${effectiveAllowedTime})`
      : `Aguardando Horário (${effectiveAllowedTime}) ou Autorização da Administração`;
    entryBadgeType = "warning";
  } else if (!isRoomReady) {
    entryMessage = `Quarto não está pronto (${cleaningLabel})`;
    entryBadgeType = "error";
  } else if (!allCheckinDone) {
    entryMessage = `Entrada Parcial Liberada (${completedCount}/${totalCount} prontos)`;
    entryBadgeType = "warning";
  } else if (isRegularCheckinWindow) {
    entryMessage = `Check-in Regular Liberado (${standardCheckinTime})`;
    entryBadgeType = "success";
  } else {
    entryMessage = `⚡ Early Check-in Liberado (${earlyCheckinReason})`;
    entryBadgeType = "success";
  }

  return {
    channelLabel,
    isOtaOrB2b,
    freeEarlyTime,
    effectiveAllowedTime,
    standardCheckinTime,
    currentTimeHHMM,
    isCheckinDatePast,
    isCheckinDateToday,
    isCheckinDateFuture,
    isTimeAllowed,
    isRegularCheckinWindow,
    isEarlyAuthorizedByAdmin,
    earlyCheckinTime: validAuthorizedTime,
    hasPendingEarlyPayment,
    isRoomReady: Boolean(isRoomReady),
    cleaningStatus,
    cleaningLabel,
    completedGuestsCount: completedCount,
    totalGuestsCount: totalCount,
    allCheckinDone: Boolean(allCheckinDone),
    someCheckinDone: Boolean(someCheckinDone),
    needsReSignature: Boolean(isReSignatureNeeded),
    earlyCheckinStatus,
    earlyCheckinReason,
    canAuthorizeEntry,
    entryMessage,
    entryBadgeType,
    blockedReasons
  };
}

export function buildSanitizedReceptionItem(r, { now = null, bNow = null, todayCleaningRequests = null } = {}) {
  const activeNow = now || getEffectiveDate();
  const activeBNow = bNow || getBrasiliaNow();
  const today = activeBNow.date;
  const activeCleanReqs = todayCleaningRequests || (typeof getRequestsForDate === "function" ? getRequestsForDate(today) : (db.cleaningRequests || []));

  const flat = (db.flats || []).find(f => f.id === r.flatId || String(f.number) === String(r.flatNumber)) || {
    id: r.flatId,
    number: r.flatNumber || String(r.flatId)
  };
  const guest = (db.guests || []).find(g =>
    areGuestNamesCompatible(r.guestName, g.fullName || g.name) && (
      (r.guestId && g.id === r.guestId) ||
      (r.guestDocument && g.document && r.guestDocument.replace(/\D/g, "") === g.document.replace(/\D/g, "")) ||
      (r.guestEmail && g.email && r.guestEmail.trim().toLowerCase() === g.email.trim().toLowerCase()) ||
      (r.guestPhone && g.phone && r.guestPhone.replace(/\D/g, "") === g.phone.replace(/\D/g, ""))
    )
  ) || {};

  const cleanReq = activeCleanReqs.find(c =>
    (c.flatId === flat.id || String(c.flatNumber) === String(flat.number)) &&
    !c.isDeleted &&
    c.status !== "deleted" &&
    !c.isInstructionOnly &&
    c.source !== "manual_instruction" &&
    c.type !== "bed_adjustment_only" &&
    c.type !== "instruction"
  ) || (db.cleaningRequests || []).find(c =>
    (c.flatId === flat.id || String(c.flatNumber) === String(flat.number)) &&
    c.requestDate === today &&
    !c.isDeleted &&
    c.status !== "deleted" &&
    !c.isInstructionOnly &&
    c.source !== "manual_instruction" &&
    c.type !== "bed_adjustment_only" &&
    c.type !== "instruction"
  );

  const hasPendingCheckoutToday = (db.reservations || []).some(res =>
    (res.flatId === flat.id || String(res.flatNumber) === String(flat.number)) &&
    res.checkoutDate === today &&
    res.id !== r.id &&
    res.status !== "cancelada" &&
    res.status !== "cancelado" &&
    res.status !== "completed"
  );

  let cleaningStatus = "clean";
  let cleaningLabel = "✨ Limpo";
  let cleaningMinutes = 0;

  if (r.status === "in_house") {
    cleaningStatus = "clean";
    cleaningLabel = "✨ Ocupado";
  } else if (cleanReq) {
    if (cleanReq.status === "cleaning_now" || cleanReq.status === "in_progress") {
      cleaningStatus = "cleaning_now";
      const startedAt = cleanReq.startedAt || cleanReq.assignedAt || cleanReq.updatedAt || new Date().toISOString();
      const diffMins = Math.max(0, Math.floor((activeNow.getTime() - new Date(startedAt).getTime()) / 60000));
      cleaningMinutes = diffMins;
      cleaningLabel = `🧹 Limpando (há ${diffMins} min)`;
    } else if (cleanReq.status === "dirty" || cleanReq.status === "pending") {
      cleaningStatus = "dirty";
      cleaningLabel = "⚠️ Sujo (aguardando limpeza)";
    } else {
      cleaningStatus = "clean";
      cleaningLabel = "✨ Limpo";
    }
  } else if (hasPendingCheckoutToday) {
    cleaningStatus = "dirty";
    cleaningLabel = "⚠️ Sujo (aguardando limpeza)";
  }

  const isRoomReady = cleaningStatus === "clean";
  const isReSignatureNeeded = Boolean(r.needsReSignature);

  const count = Math.min(Math.max(Number(r.guestCount) || Number(r.adults) || (Array.isArray(r.guests) ? r.guests.length : 1) || 1, 1), 4);
  const rawGuests = Array.isArray(r.guests) && r.guests.length > 0 ? [...r.guests] : [];
  const guestList = [];

  if (rawGuests.length === 0) {
    const titularDone = Boolean(
      !isReSignatureNeeded && (r.fnhrCompleted || r.preCheckinCompleted || r.fnrhDocumentUuid || r.fnrhSignedAt || r.status === "in_house")
    );
    guestList.push({
      index: 1,
      name: r.guestName || guest.fullName || guest.name || "Hóspede 1",
      cpf: r.guestDocument || guest.document || "",
      document: r.guestDocument || guest.document || "",
      phone: r.guestPhone || guest.phone || "",
      email: r.guestEmail || guest.email || "",
      hasCompletedCheckin: titularDone,
      needsReSignature: isReSignatureNeeded,
      checkinCompletedAt: titularDone ? (r.fnrhSignedAt || r.updatedAt || null) : null,
      entryAuthorized: Boolean(r.status === "in_house")
    });
    for (let i = 2; i <= count; i++) {
      guestList.push({
        index: i,
        name: `Hóspede ${i}`,
        cpf: "",
        document: "",
        phone: "",
        email: "",
        hasCompletedCheckin: false,
        needsReSignature: isReSignatureNeeded,
        checkinCompletedAt: null,
        entryAuthorized: false
      });
    }
  } else {
    for (let i = 1; i <= count; i++) {
      const posFallback = rawGuests[i - 1] && (!rawGuests[i - 1].index || Number(rawGuests[i - 1].index) === i)
        ? rawGuests[i - 1]
        : null;
      const existing = rawGuests.find(g => Number(g?.index || 0) === i) || posFallback;
      if (existing) {
        const done = !isReSignatureNeeded && !existing.needsReSignature && Boolean(
          existing.hasCompletedCheckin || existing.status === "CHECKED_IN" || existing.fnrhDocumentUuid || existing.fnrhSignedAt
        );
        guestList.push({
          ...existing,
          index: Number(existing.index) || i,
          hasCompletedCheckin: done,
          needsReSignature: Boolean(isReSignatureNeeded || existing.needsReSignature)
        });
      } else {
        guestList.push({
          index: i,
          name: i === 1 ? (r.guestName || guest.fullName || guest.name || "Hóspede 1") : `Hóspede ${i}`,
          cpf: i === 1 ? (r.guestDocument || guest.document || "") : "",
          document: i === 1 ? (r.guestDocument || guest.document || "") : "",
          phone: i === 1 ? (r.guestPhone || guest.phone || "") : "",
          email: i === 1 ? (r.guestEmail || guest.email || "") : "",
          hasCompletedCheckin: false,
          needsReSignature: isReSignatureNeeded,
          checkinCompletedAt: null,
          entryAuthorized: false
        });
      }
    }
  }

  const completedCount = guestList.filter(g => g.hasCompletedCheckin && !g.needsReSignature).length;
  const totalCount = guestList.length;
  const allCheckinDone = !isReSignatureNeeded && totalCount > 0 && completedCount >= totalCount;
  const someCheckinDone = !isReSignatureNeeded && completedCount > 0;

  const earlyEval = evaluateReceptionEarlyCheckin(r, {
    isRoomReady,
    cleaningStatus,
    cleaningLabel,
    bNow: activeBNow,
    settings: db.settings,
    allCheckinDone,
    someCheckinDone,
    completedCount,
    totalCount,
    isReSignatureNeeded
  });

  let safePdfUrl = r.fnrhPdfUrl || null;
  let safeDownloadUrl = r.fnrhDownloadUrl || null;
  if (r.fnrhDocumentUuid) {
    const tkn = generateSignedFnrhToken(r.fnrhDocumentUuid, 60 * 24 * 30);
    safePdfUrl = `/api/pms/fnrh/${r.fnrhDocumentUuid}/view?token=${tkn}`;
    safeDownloadUrl = `/api/pms/fnrh/${r.fnrhDocumentUuid}/download?token=${tkn}`;
  }

  const annotateMediaBlobMimeHint = (rawUrl) => {
    if (!rawUrl || typeof rawUrl !== "string") return rawUrl || null;
    const blobMatch = rawUrl.match(/^\/api\/media\/blob\/([a-zA-Z0-9_\-]+)$/);
    if (blobMatch) {
      const cached = mediaBlobMemoryCache.get(blobMatch[1]);
      if (cached?.mimeType === "application/pdf") {
        return `${rawUrl}?mime=application/pdf`;
      }
    }
    return rawUrl;
  };

  // Sanitização estrita por allowlist de cada hóspede (sem valores financeiros nem senhas)
  const sanitizedGuests = guestList.map((g, idx) => {
    let gPdfUrl = g.fnrhPdfUrl || null;
    let gDownloadUrl = g.fnrhDownloadUrl || null;
    if (g.fnrhDocumentUuid) {
      const tkn = generateSignedFnrhToken(g.fnrhDocumentUuid, 60 * 24 * 30);
      gPdfUrl = `/api/pms/fnrh/${g.fnrhDocumentUuid}/view?token=${tkn}`;
      gDownloadUrl = `/api/pms/fnrh/${g.fnrhDocumentUuid}/download?token=${tkn}`;
    }
    return {
      index: Number(g.index) || idx + 1,
      name: g.name || "",
      cpf: g.cpf || g.document || "",
      document: g.document || g.cpf || "",
      phone: g.phone || "",
      email: g.email || "",
      birthDate: g.birthDate || "",
      age: g.age ?? null,
      address: g.address || "",
      cep: g.cep || "",
      city: g.city || "",
      state: g.state || "",
      hasCompletedCheckin: Boolean(g.hasCompletedCheckin),
      checkinCompletedAt: g.checkinCompletedAt || g.fnrhSignedAt || null,
      needsReSignature: Boolean(g.needsReSignature),
      entryAuthorized: Boolean(g.entryAuthorized),
      entryAuthorizedAt: g.entryAuthorizedAt || null,
      selfieUrl: g.selfieUrl || null,
      docPhotoUrl: annotateMediaBlobMimeHint(g.docPhotoUrl),
      signatureUrl: g.signatureUrl || null,
      fnrhDocumentUuid: g.fnrhDocumentUuid || null,
      fnrhPdfUrl: gPdfUrl,
      fnrhDownloadUrl: gDownloadUrl,
      isMinor: Boolean(g.isMinor),
      minorKinship: g.minorKinship || null,
      minorAuthDocUrl: annotateMediaBlobMimeHint(g.minorAuthDocUrl),
      aiVerification: g.aiVerification ? { facesMatch: Boolean(g.aiVerification.facesMatch) } : null
    };
  });

  const isSmoker = Boolean(
    r.isSmoker || r.smokerGuestAlert || r.guestSmoked || guest.isSmoker || guest.smokedInRoom || (guest.tags || []).includes("Fumante")
  );

  // Allowlist estrita: NENHUM valor financeiro (dailyRate, totalAmount, paidAmount, payments, charges,
  // boletos, pixCopiaECola, earlyCheckinFee, notes internos, auditLogs) e NENHUMA senha (doorPassword,
  // lockPassword, accessCode, wifiPassword) sai nas rotas públicas /api/reception/*
  return {
    id: r.id,
    code: r.code || r.reservationCode || null,
    reservationCode: r.reservationCode || r.code || null,
    flatId: flat.id ?? r.flatId,
    flatNumber: String(flat.number || r.flatNumber || ""),
    buildingName: flat.buildingName || flat.building || db.settings?.buildingName || "Edifício Soho Residence Service",
    channel: r.channel || "site",
    channelLabel: earlyEval.channelLabel,
    status: r.status || "confirmada",
    guestName: r.guestName || "",
    guestPhone: r.guestPhone || guest.phone || "",
    guestEmail: r.guestEmail || guest.email || "",
    guestDocument: r.guestDocument || guest.document || "",
    guestAddress: r.guestAddress || guest.address || "",
    guestCep: r.guestCep || r.cep || guest.cep || "",
    guestCity: r.guestCity || r.city || guest.city || "",
    guestState: r.guestState || r.state || guest.state || "",
    checkinDate: r.checkinDate || "",
    checkoutDate: r.checkoutDate || "",
    checkinTime: r.checkinTime || db.settings?.checkinTime || "14:00",
    checkoutTime: r.checkoutTime || db.settings?.checkoutTime || "12:00",
    actualCheckinAt: r.actualCheckinAt || null,
    actualCheckoutAt: r.actualCheckoutAt || null,
    guestCount: count,
    guests: sanitizedGuests,
    vehicle: (r.vehicle && r.vehicle.plate)
      ? {
          plate: String(r.vehicle.plate).toUpperCase(),
          brand: r.vehicle.brand || "",
          model: r.vehicle.model || "",
          color: r.vehicle.color || ""
        }
      : null,
    cleaningStatus,
    cleaningLabel,
    cleaningMinutes,
    isRoomReady,
    earlyCheckinStatus: earlyEval.earlyCheckinStatus,
    earlyCheckinReason: earlyEval.earlyCheckinReason,
    earlyCheckinAuthorized: earlyEval.isEarlyAuthorizedByAdmin,
    earlyCheckinTime: earlyEval.earlyCheckinTime,
    earlyCheckinChecklist: earlyEval,
    allCheckinDone,
    someCheckinDone,
    canAuthorizeEntry: earlyEval.canAuthorizeEntry,
    entryMessage: earlyEval.entryMessage,
    entryBadgeType: earlyEval.entryBadgeType,
    receptionNotes: r.receptionNotes || "",
    guestPhoto: r.selfieUrl || guest.photoUrl || null,
    docPhoto: r.docPhotoUrl || guest.docPhotoUrl || null,
    signatureUrl: r.signatureUrl || null,
    fnrhDocumentUuid: r.fnrhDocumentUuid || null,
    fnrhPdfUrl: safePdfUrl,
    fnrhDownloadUrl: safeDownloadUrl,
    serproPrecheckinUrl: r.serproPrecheckinUrl || null,
    needsReSignature: isReSignatureNeeded,
    reSignatureReason: r.reSignatureReason || (isReSignatureNeeded ? "Alteração de acomodação (flat) ou período da estadia" : null),
    hasPreCheckin: Boolean(!isReSignatureNeeded && someCheckinDone),
    isCheckoutToday: Boolean(r.checkoutDate === today),
    isPartialCheckin: Boolean(r.isPartialCheckin),
    hasMinor: Boolean(r.hasMinor || sanitizedGuests.some(g => g.isMinor)),
    isCamposResident: Boolean(r.isCamposResident),
    riskAttentionAlert: Boolean(r.riskAttentionAlert),
    riskAttentionReason: r.riskAttentionReason || null,
    isSmoker,
    smokerGuestAlert: isSmoker,
    guestSmoked: isSmoker,
    smokingAlert: r.smokingAlert || (guest.isSmoker ? "Hóspede com histórico de fumo no quarto" : null)
  };
}

app.get("/api/reception/today", (req, res) => {
  try {
    triggerBackgroundSync();
    const now = getEffectiveDate();
    const bNow = getBrasiliaNow();
    const today = bNow.date;
    const todayCleaningRequests = typeof getRequestsForDate === "function" ? getRequestsForDate(today) : (db.cleaningRequests || []);
    const ctx = { now, bNow, todayCleaningRequests };

    // 1. Chegadas Previstas para Hoje (Aguardando Check-in ou com Entrada Parcial Ativa)
    // Pré-reservas aguardando pagamento NUNCA são enviadas/exibidas na recepção/portaria.
    const arrivals = (db.reservations || [])
      .filter(r => {
        const resDate = r.checkinDate ? r.checkinDate.substring(0, 10) : "";
        if (r.status === "cancelada" || r.status === "cancelado" || r.status === "completed" || r.status === "checked_out" || r.status === "expirada") {
          return false;
        }
        if (isPreReservationBlocked(r)) {
          return false;
        }
        if (resDate === today && r.status !== "in_house") {
          return true;
        }
        if (r.isPartialCheckin && Array.isArray(r.guests) && r.guests.some(g => !g.entryAuthorized)) {
          return true;
        }
        return false;
      })
      .map(r => buildSanitizedReceptionItem(r, ctx));

    // 2. Hóspedes Atualmente Hospedados (In House)
    const inHouse = (db.reservations || [])
      .filter(r => {
        if (r.status === "cancelada" || r.status === "cancelado" || r.status === "completed" || r.status === "checked_out" || r.status === "expirada") {
          return false;
        }
        if (isPreReservationBlocked(r)) {
          return false;
        }
        if (r.status === "in_house") {
          return true;
        }
        if (r.checkinDate < today && r.checkoutDate >= today && r.status !== "pendente" && r.status !== "pre_reserva") {
          return true;
        }
        return false;
      })
      .map(r => buildSanitizedReceptionItem(r, ctx));

    // 3. Checkouts Realizados Hoje (com opção de desfazer permanente)
    const completedToday = (db.reservations || [])
      .filter(r => r.status === "completed" && (r.actualCheckoutAt?.startsWith(today) || r.checkoutDate === today))
      .map(r => buildSanitizedReceptionItem(r, ctx));

    // 4. Todas as Saídas Previstas para Hoje
    const departures = (db.reservations || [])
      .filter(r => r.checkoutDate === today && r.status !== "cancelada" && r.status !== "cancelado" && r.status !== "expirada" && !isPreReservationBlocked(r))
      .map(r => buildSanitizedReceptionItem(r, ctx));

    // 5. Reserva focada via deep-link de e-mail (?res=CODIGO) — higienizada e bloqueada se pré-reserva/cancelada
    let focusedReservation = null;
    const rawFocusCode = String(req.query?.res || "").trim();
    if (rawFocusCode) {
      const upperFocus = rawFocusCode.toUpperCase();
      const targetRes = (db.reservations || []).find(r =>
        String(r.id) === rawFocusCode ||
        String(r.code || "").trim().toUpperCase() === upperFocus ||
        String(r.reservationCode || "").trim().toUpperCase() === upperFocus
      );
      if (
        targetRes &&
        targetRes.status !== "cancelada" &&
        targetRes.status !== "cancelado" &&
        targetRes.status !== "expirada" &&
        !isPreReservationBlocked(targetRes)
      ) {
        focusedReservation = buildSanitizedReceptionItem(targetRes, ctx);
      }
    }

    res.json({
      today,
      currentTimeHHMM: bNow.timeStr,
      arrivals,
      inHouse,
      completedToday,
      departures,
      focusedReservation,
      totalFlats: (db.flats || []).length
    });
  } catch (err) {
    console.error("[RECEPTION_TODAY_ERROR]", err);
    res.status(500).json({
      error: "Erro ao processar dados de recepção",
      today: new Date().toISOString().substring(0, 10),
      arrivals: [],
      inHouse: [],
      completedToday: [],
      departures: [],
      focusedReservation: null,
      totalFlats: (db.flats || []).length
    });
  }
});

// Endpoint: Portaria solicita análise de Early Check-in à Administração no WhatsApp
const receptionEarlyRequestCooldown = new Map();
app.post("/api/reception/reservations/:id/request-early-checkin-analysis", async (req, res) => {
  try {
    const idOrCode = String(req.params.id || "").trim();
    const { requestedTime = "", receptionNote = "", note = "" } = req.body || {};
    const upperCode = idOrCode.toUpperCase();
    const r = (db.reservations || []).find(x =>
      String(x.id) === idOrCode ||
      String(x.code || "").trim().toUpperCase() === upperCode ||
      String(x.reservationCode || "").trim().toUpperCase() === upperCode
    );
    if (!r || r.status === "cancelada" || r.status === "cancelado") {
      return res.status(404).json({ error: "Reserva não encontrada." });
    }
    if (isPreReservationBlocked(r)) {
      return res.status(403).json({ error: "Pré-reserva aguardando pagamento." });
    }

    const lastReqAt = receptionEarlyRequestCooldown.get(String(r.id)) || 0;
    if (Date.now() - lastReqAt < 45000) {
      return res.json({
        success: true,
        alreadySentRecently: true,
        message: "A Administração já recebeu o alerta desta reserva há poucos segundos. Aguarde a atualização automática na tela."
      });
    }

    const sanitizedItem = buildSanitizedReceptionItem(r);
    const checklist = sanitizedItem.earlyCheckinChecklist;
    const rawAdminPhone = String(
      db.settings?.adminWhatsApp ||
      db.whatsappAiSettings?.adminPhone ||
      process.env.ADMIN_WHATSAPP_NUMBER ||
      "5522997124021"
    ).trim();
    const cleanAdminPhone = typeof cleanWhatsAppPhone === "function"
      ? cleanWhatsAppPhone(rawAdminPhone)
      : rawAdminPhone.replace(/\D/g, "");

    const safeRequestedTime = String(requestedTime || "").trim().slice(0, 20);
    const safeNote = String(receptionNote || note || "").trim().slice(0, 240);

    const adminMsg = [
      `⏰ *PORTARIA SOLICITA ANÁLISE DE EARLY CHECK-IN*`,
      ``,
      `🏢 *Apartamento:* Flat ${sanitizedItem.flatNumber}`,
      `👤 *Hóspede:* ${sanitizedItem.guestName}`,
      `🔖 *Reserva:* #${sanitizedItem.code || sanitizedItem.id} (${sanitizedItem.channelLabel})`,
      `🕒 *Horário na portaria:* ${checklist.currentTimeHHMM}${safeRequestedTime ? ` | Solicitado p/: ${safeRequestedTime}` : ""}`,
      `🧹 *Governança:* ${sanitizedItem.cleaningLabel}`,
      `📋 *Check-in Digital:* ${checklist.completedGuestsCount}/${checklist.totalGuestsCount} concluído(s)`,
      ...(safeNote ? [`💬 *Obs. da Portaria:* ${safeNote}`] : []),
      ``,
      `⚠️ *Regra aplicada:* Cortesia gratuita deste canal inicia às *${checklist.freeEarlyTime}*. Para liberar antes desse horário, ative *"Early Check-in Autorizado"* na reserva pelo PMS.`
    ].join("\n");

    let sendResult = { success: false };
    if (cleanAdminPhone && typeof sendZapiMessage === "function") {
      sendResult = await sendZapiMessage(db.zapiConfig, {
        phone: cleanAdminPhone,
        message: adminMsg,
        title: "Análise de Early Check-in • Portaria",
        footer: "CorpFlats • Terminal da Portaria",
        channelId: "admin_alerts",
        recipientRole: "admin",
        triggerEvent: "reception_early_checkin_request",
        db
      });
    }

    receptionEarlyRequestCooldown.set(String(r.id), Date.now());

    if (typeof createNotification === "function") {
      createNotification({
        category: "checkin",
        title: `⏰ Portaria pede análise de Early Check-in: Flat ${sanitizedItem.flatNumber}`,
        message: `${sanitizedItem.guestName} (#${sanitizedItem.code || sanitizedItem.id}, ${sanitizedItem.channelLabel}) solicitou entrada às ${safeRequestedTime || checklist.currentTimeHHMM} (antes das ${checklist.freeEarlyTime}).${safeNote ? ` Obs: ${safeNote}` : ""}`,
        severity: "warning",
        metadata: {
          reservationId: r.id,
          reservationCode: r.code,
          flatNumber: sanitizedItem.flatNumber,
          requestedTime: safeRequestedTime || checklist.currentTimeHHMM,
          note: safeNote || null
        }
      });
    }

    const realZapiSent = Boolean(sendResult?.success && !sendResult?.mock && !sendResult?.simulated);

    if (typeof logAuditEvent === "function") {
      await logAuditEvent({
        level: "info",
        category: "reception",
        action: "RECEPTION_REQUEST_EARLY_CHECKIN_ANALYSIS",
        actor: getAuthUser(req) || { name: "Terminal da Portaria", role: "reception" },
        details: {
          reservationId: r.id,
          reservationCode: r.code,
          flatNumber: sanitizedItem.flatNumber,
          channelLabel: sanitizedItem.channelLabel,
          requestedTime: safeRequestedTime || checklist.currentTimeHHMM,
          sentViaZapi: realZapiSent
        }
      });
    }

    saveDatabase();

    const normalizedWaPhone = cleanAdminPhone.startsWith("55") ? cleanAdminPhone : `55${cleanAdminPhone}`;
    const fallbackWaWebUrl = !realZapiSent && cleanAdminPhone
      ? `https://wa.me/${normalizedWaPhone}?text=${encodeURIComponent(adminMsg)}`
      : null;

    return res.json({
      success: true,
      sentViaZapi: realZapiSent,
      fallbackWaWebUrl,
      message: realZapiSent
        ? "Solicitação enviada com sucesso para o WhatsApp da Administração! Assim que autorizarem no sistema, a liberação aparecerá automaticamente aqui na tela."
        : "Alerta registrado no painel da Administração. O disparo automático Z-API não pôde ser concluído agora — você pode abrir no WhatsApp Web se desejar."
    });
  } catch (err) {
    return res.status(500).json({ error: err?.message || "Erro ao solicitar análise da Administração." });
  }
});

app.patch("/api/pms/reservations/:id/early-checkin", (req, res) => {
  const authUser = getAuthUser(req);
  if (!authUser) {
    return res.status(401).json({ error: "Não autenticado. Somente a Administração pode autorizar Early Check-in manualmente." });
  }
  if (authUser.role !== "admin" && authUser.role !== "dev") {
    return res.status(403).json({ error: "Acesso negado. Somente a Administração pode autorizar Early Check-in antes do horário." });
  }

  const id = Number(req.params.id);
  const r = (db.reservations || []).find(x => x.id === id);
  if (!r) return res.status(404).json({ error: "Reserva não encontrada" });

  ensureReservationAuditLogs(r);
  const newEarly = Boolean(req.body.earlyCheckinAuthorized);
  if (Boolean(r.earlyCheckinAuthorized) !== newEarly) {
    addReservationAuditLog(r, {
      action: "early_checkin",
      actor: {
        id: authUser?.id || null,
        name: authUser?.username || "Administrador",
        role: authUser?.role || "admin",
        type: "user"
      },
      source: "PMS Calendário",
      description: newEarly ? "Early Check-in autorizado para liberação antecipada" : "Autorização de Early Check-in revogada",
      changes: [{
        field: "earlyCheckinAuthorized",
        label: "Early Check-in Autorizado",
        oldValue: r.earlyCheckinAuthorized ? "Sim" : "Não",
        newValue: newEarly ? "Sim" : "Não"
      }]
    });
  }

  r.earlyCheckinAuthorized = newEarly;
  if (req.body.earlyCheckinTime !== undefined) {
    r.earlyCheckinTime = req.body.earlyCheckinTime || null;
  } else if (newEarly) {
    // Liberação manual pelo Admin no PMS vale imediatamente em qualquer horário
    r.earlyCheckinTime = null;
  }
  r.updatedAt = new Date().toISOString();
  saveDatabase();
  res.json({ success: true, earlyCheckinAuthorized: r.earlyCheckinAuthorized });
});

