app.post("/api/reception/checkin/:reservationId", (req, res) => {
  const rawId = String(req.params.reservationId || "").trim();
  const id = Number(rawId);
  const r = (db.reservations || []).find(x => x.id === id || String(x.id) === rawId || x.code === rawId);
  if (!r || r.status === "cancelada" || r.status === "cancelado") {
    return res.status(404).json({ error: "Reserva não encontrada" });
  }

  if (isPreReservationBlocked(r)) {
    return res.status(403).json({
      error: "Não é permitido liberar entrada na portaria para uma pré-reserva aguardando pagamento. A reserva precisa estar paga e confirmada.",
      preCheckinBlocked: true
    });
  }

  const authUser = getAuthUser(req);
  const isVerifiedAdminOverride = Boolean(
    req.body?.adminOverride && authUser && (authUser.role === "admin" || authUser.role === "dev")
  );

  // Bloqueio mandatório: se a reserva requer re-assinatura de termo (datas ou flat alterados)
  if (r.needsReSignature && !isVerifiedAdminOverride) {
    return res.status(400).json({
      error: "Não é possível liberar a entrada: Re-assinatura de termo obrigatória devido a alterações na reserva (datas/acomodação). O hóspede precisa assinar o termo atualizado antes da liberação.",
      needsReSignature: true,
      reSignatureReason: r.reSignatureReason || "Alteração de acomodação (flat) ou período da estadia"
    });
  }

  // Garante array de hóspedes consistente (respeitando eventual redução explícita de guestCount/adults, ex: 2 -> 1)
  const explicitCount = Number(r.guestCount) || Number(r.adults) || 0;
  const count = Math.min(Math.max(explicitCount || (Array.isArray(r.guests) ? r.guests.length : 1) || 1, 1), 4);
  if (!r.guests || r.guests.length === 0) {
    const titularCompleted = Boolean(!r.needsReSignature && (r.fnhrCompleted || r.preCheckinCompleted || r.fnrhDocumentUuid || r.fnrhSignedAt));
    r.guests = [{
      index: 1,
      name: r.guestName || "Hóspede 1",
      cpf: r.guestDocument || "",
      phone: r.guestPhone || "",
      email: r.guestEmail || "",
      hasCompletedCheckin: titularCompleted,
      checkinCompletedAt: titularCompleted ? (r.fnrhSignedAt || r.updatedAt) : null,
      entryAuthorized: r.status === "in_house"
    }];
    for (let i = 2; i <= count; i++) {
      r.guests.push({
        index: i,
        name: `Hóspede ${i}`,
        cpf: "",
        phone: "",
        email: "",
        hasCompletedCheckin: false,
        checkinCompletedAt: null,
        entryAuthorized: false
      });
    }
  } else {
    for (let i = 1; i <= count; i++) {
      if (!r.guests.some(g => Number(g?.index || 0) === i)) {
        r.guests.push({
          index: i,
          name: `Hóspede ${i}`,
          cpf: "",
          phone: "",
          email: "",
          hasCompletedCheckin: false,
          checkinCompletedAt: null,
          entryAuthorized: false
        });
      }
    }
    if (explicitCount > 0 && r.guests.length > count) {
      r.guests = r.guests.filter((g, idx) => {
        const slot = Number(g?.index) || idx + 1;
        return slot <= count || Boolean(g?.entryAuthorized);
      });
    }
  }

  const isGuestCheckinValid = (g) => Boolean(
    g && !r.needsReSignature && !g.needsReSignature && (g.hasCompletedCheckin || g.status === "CHECKED_IN" || g.fnrhDocumentUuid || g.fnrhSignedAt)
  );

  const guests = r.guests;
  const pendingGuests = guests.filter(g => !isGuestCheckinValid(g));
  const clearedGuests = guests.filter(g => isGuestCheckinValid(g));
  const isPartialRequested = Boolean(req.body?.partial || (Array.isArray(req.body?.guestIndices) && req.body.guestIndices.length > 0));

  // Bloqueio mandatório: se nenhum hóspede completou a ficha digital
  if (clearedGuests.length === 0 && !isVerifiedAdminOverride) {
    return res.status(400).json({
      error: "Não é possível liberar a entrada: Nenhum hóspede concluiu o Check-in Digital ainda. É necessário preencher a ficha digital antes da liberação de entrada."
    });
  }

  // Validação determinística da Regra Unificada de Early Check-in (Sofia) e Limpeza
  const sanitizedSnapshot = buildSanitizedReceptionItem(r);
  const earlyChecklist = sanitizedSnapshot.earlyCheckinChecklist;

  if (earlyChecklist.isCheckinDateFuture && !isVerifiedAdminOverride) {
    return res.status(400).json({
      error: `Não é possível liberar a entrada antes da data de check-in da reserva (${String(r.checkinDate || "").split("-").reverse().join("/")}).`,
      earlyCheckinBlocked: true,
      earlyCheckinChecklist: earlyChecklist
    });
  }

  if (!earlyChecklist.isTimeAllowed && !isVerifiedAdminOverride) {
    const allowedTimeDisplay = earlyChecklist.effectiveAllowedTime || earlyChecklist.freeEarlyTime;
    const blockedMsg = (earlyChecklist.isEarlyAuthorizedByAdmin && earlyChecklist.earlyCheckinTime)
      ? `Entrada ainda não liberada pelo horário: a Administração agendou o Early Check-in a partir das ${allowedTimeDisplay}.`
      : `Entrada ainda não liberada pelo horário: para reservas via ${earlyChecklist.channelLabel}, a cortesia de Early Check-in inicia às ${allowedTimeDisplay}. Antes desse horário, somente com autorização registrada pela Administração.`;
    return res.status(400).json({
      error: blockedMsg,
      earlyCheckinBlocked: true,
      earlyCheckinChecklist: earlyChecklist
    });
  }

  // Antes do horário padrão (14:00), Early Check-in exige flat limpo (a menos que Admin autenticado force).
  // A partir das 14:00 (janela regular), caso a governança ainda não tenha dado baixa no app, aceita confirmação explícita force=true.
  const canForceCleanInRegularWindow = Boolean(req.body?.force && earlyChecklist.isRegularCheckinWindow);
  if (!earlyChecklist.isRoomReady && !canForceCleanInRegularWindow && !isVerifiedAdminOverride) {
    return res.status(400).json({
      error: `Não é possível liberar Early Check-in enquanto o apartamento consta como "${sanitizedSnapshot.cleaningLabel}". Aguarde a conclusão da limpeza pela governança.`,
      roomNotReady: true,
      earlyCheckinChecklist: earlyChecklist
    });
  }

  // Se houver pendentes e NÃO foi solicitada confirmação de liberação parcial nem adminOverride
  if (pendingGuests.length > 0 && !isPartialRequested && !isVerifiedAdminOverride) {
    const pendingNames = pendingGuests.map(g => g.name || `Hóspede ${g.index}`).join(", ");
    const clearedNames = clearedGuests.map(g => g.name || `Hóspede ${g.index}`).join(", ");
    return res.status(400).json({
      error: `Há hóspede(s) com check-in pendente (${pendingNames}). Apenas a entrada de ${clearedNames} está liberada no momento. Deseja registrar a entrada apenas dele(s)?`,
      requiresPartialConfirmation: true,
      pendingGuests: pendingGuests.map(g => ({ index: g.index, name: g.name })),
      clearedGuests: clearedGuests.map(g => ({ index: g.index, name: g.name }))
    });
  }

  // Identifica quais hóspedes terão a entrada autorizada neste momento
  let guestsToAuthorize = [];
  if (Array.isArray(req.body?.guestIndices) && req.body.guestIndices.length > 0) {
    const targetIndices = req.body.guestIndices.map(Number);
    guestsToAuthorize = guests.filter(g => targetIndices.includes(Number(g.index)));
  } else if (isPartialRequested) {
    guestsToAuthorize = clearedGuests.filter(g => !g.entryAuthorized);
    if (guestsToAuthorize.length === 0) guestsToAuthorize = clearedGuests;
  } else {
    guestsToAuthorize = clearedGuests.length > 0 ? clearedGuests : guests;
  }

  if (guestsToAuthorize.length === 0) {
    return res.status(400).json({
      error: "Nenhum hóspede elegível para registrar entrada física."
    });
  }

  // Não permitir liberar hóspede cujo check-in digital não foi concluído sem adminOverride verificado
  const unauthorizedAttempt = guestsToAuthorize.filter(g => !isGuestCheckinValid(g) && !isVerifiedAdminOverride);
  if (unauthorizedAttempt.length > 0) {
    const names = unauthorizedAttempt.map(g => g.name || `Hóspede ${g.index}`).join(", ");
    return res.status(400).json({
      error: `Não é possível liberar a entrada de ${names}: Check-in Digital pendente.`
    });
  }

  const nowIso = new Date().toISOString();
  const previousStatus = r.status || "confirmada";
  const authorizerName = authUser?.username || "Recepção / Portaria";

  // Autoriza a entrada física dos hóspedes selecionados
  guestsToAuthorize.forEach(g => {
    g.hasCompletedCheckin = Boolean(isGuestCheckinValid(g) || isVerifiedAdminOverride);
    g.entryAuthorized = true;
    g.entryAuthorizedAt = g.entryAuthorizedAt || nowIso;
    g.entryAuthorizedBy = authorizerName;
  });

  const allGuestsAuthorized = guests.every(g => g.entryAuthorized);
  r.isPartialCheckin = !allGuestsAuthorized;
  r.status = "in_house";
  r.actualCheckinAt = r.actualCheckinAt || nowIso;
  r.updatedAt = nowIso;

  const flat = db.flats.find(f => f.id === r.flatId || String(f.number) === String(r.flatNumber));
  if (flat) {
    flat.isOccupied = true;
    flat.updatedAt = nowIso;
  }

  if (canForceCleanInRegularWindow && !earlyChecklist.isRoomReady) {
    const todayStr = getBrasiliaNow().date;
    const pendingClean = (db.cleaningRequests || []).find(c =>
      (c.flatId === r.flatId || String(c.flatNumber) === String(r.flatNumber)) &&
      c.requestDate === todayStr &&
      !c.isDeleted &&
      c.status !== "clean"
    );
    if (pendingClean) {
      pendingClean.status = "clean";
      pendingClean.completedAt = nowIso;
      pendingClean.updatedAt = nowIso;
    }
  }

  const clearedNames = guestsToAuthorize.map(g => g.name || `Hóspede ${g.index}`).join(", ");
  const remainingPending = guests.filter(g => !g.entryAuthorized);
  const remainingNames = remainingPending.map(g => g.name || `Hóspede ${g.index}`).join(", ");

  ensureReservationAuditLogs(r);
  addReservationAuditLog(r, {
    action: r.isPartialCheckin ? "partial_checkin" : "checkin",
    actor: {
      id: authUser?.id || null,
      name: authorizerName,
      role: authUser?.role || "reception",
      type: "user"
    },
    source: "Recepção / Portaria",
    description: r.isPartialCheckin
      ? `Entrada parcial do Apt ${r.flatNumber} registrada na portaria para: ${clearedNames}. Pendente(s): ${remainingNames}`
      : `Check-in / Entrada do Apt ${r.flatNumber} registrado na portaria para: ${clearedNames}`,
    changes: [{ field: "status", label: "Status da Reserva", oldValue: previousStatus, newValue: "in_house" }]
  });

  saveDatabase();
  ensureReceptionAndGarageNotifiedForArrival(r, {
    trigger: "reception_manual_checkin_fallback",
    source: "Check-in Registrado na Portaria"
  }).catch(() => {});
  triggerImmediateWhatsApp(db, saveDatabase, "checkin_completed", r);

  res.json({
    success: true,
    isPartialCheckin: r.isPartialCheckin,
    message: r.isPartialCheckin
      ? `Entrada registrada apenas para ${clearedNames}. Hóspede(s) pendente(s): ${remainingNames}.`
      : `Check-in do Apt ${r.flatNumber} realizado com sucesso!`,
    authorizedGuests: clearedNames,
    pendingGuests: remainingNames,
    reservation: buildSanitizedReceptionItem(r)
  });
});

const handleCheckout = async (req, res) => {
  const isReceptionPublicPath = String(req.path || "").startsWith("/api/reception/");
  const authUser = getAuthUser(req);
  if (!isReceptionPublicPath && !authUser) {
    return res.status(401).json({ error: "Não autenticado." });
  }

  const rawId = req.params.reservationId || req.params.id;
  const id = Number(rawId);
  const r = (db.reservations || []).find(x => x.id === id || String(x.id) === String(rawId));
  if (!r) return res.status(404).json({ error: "Reserva não encontrada" });

  ensureReservationAuditLogs(r);
  const previousStatus = r.status;
  r.previousStatus = previousStatus;

  const checkoutResult = await applyReservationCheckoutAndEarlyRelease(db, saveDatabase, r, {
    source: req.body?.source || "reception_pms",
    actorName: req.body?.reportedBy || authUser?.name || authUser?.username || "Recepção / Portaria",
    actorId: authUser?.id || null,
    actorRole: authUser?.role || "reception"
  });

  const flat = db.flats.find(f => f.id === r.flatId);
  if (flat) {
    flat.isOccupied = false;
    flat.updatedAt = new Date().toISOString();
  }

  // Notifica ou agenda limpeza na governança
  const today = getTodayStr();
  let cleanReq = (db.cleaningRequests || []).find(c =>
    (c.flatId === r.flatId || String(c.flatNumber) === String(r.flatNumber)) &&
    (c.requestDate === today || c.requestDate === r.checkoutDate)
  );
  if (!cleanReq) {
    cleanReq = findOrUpsertCleaningRequest(0, r.flatNumber, r.flatId, today);
  }
  if (cleanReq) {
    cleanReq.isVacant = true;
    cleanReq.isVacantExplicitlySet = true;
    cleanReq.vacantSource = "reception_checkout";
    cleanReq.vacantSetAt = new Date().toISOString();
  }

  // Automatic NFS-e Check with Channel Matrix Rules
  let autoInvoiceEmitted = false;
  let autoInvoiceNumber = null;
  let autoInvoicePdf = null;

  getFiscalData();
  const ch = (r.channel || "whatsapp").toLowerCase();
  // Channel rule (true = auto-emit all from this channel, false = locked/manual only)
  const channelRules = db.nfseConfig.channelRules || { site: true, whatsapp: true, booking: false, airbnb: false };
  const isChannelAutoEnabled = Boolean(channelRules[ch]);

  const guest = db.guests ? db.guests.find(g =>
    areGuestNamesCompatible(r.guestName, g.fullName || g.name) && (
      (r.guestId && g.id === r.guestId) ||
      (r.guestDocument && (g.document === r.guestDocument || g.documentNumber === r.guestDocument || onlyDigits(g.document || g.documentNumber) === onlyDigits(r.guestDocument))) ||
      (r.guestPhone && g.phone && cleanPhone(g.phone) === cleanPhone(r.guestPhone))
    )
  ) : null;
  const clientRequested = Boolean(r.autoEmitInvoice || (guest && guest.autoEmitInvoice));

  // Emite se o canal estiver ativado OU se o cliente específico tiver a flag ligada
  const shouldAutoEmit = Boolean(isChannelAutoEnabled || clientRequested);

  const companyId = r.companyId || guest?.companyId;
  const company = companyId && db.companies
    ? db.companies.find(c => c.id === companyId || String(c.id) === String(companyId))
    : null;

  // Trava estrita contra emissão duplicada de nota fiscal no check-out
  const existingInvForCheckout = findExistingInvoiceForReservation(db, {
    reservation: r,
    reservationId: r.id,
    reservationCode: r.code
  });
  if (existingInvForCheckout) {
    r.invoiceId = existingInvForCheckout.id;
    r.numeroNfse = existingInvForCheckout.numeroNfse;
  }

  const confFiscal = r.confirmedFiscalData || null;

  const isResFaturado = Boolean(
    r.isFaturadoBoleto ||
    r.paymentMethod === "faturado_boleto" ||
    r.paymentMethod === "boleto_faturado" ||
    r.paymentMethod === "boleto" ||
    r.paymentMethod === "faturado_pj" ||
    r.paymentMethod === "faturado_b2b" ||
    r.b2bPaymentType === "FATURADO" ||
    req.body?.emitBoleto === true
  );
  const shouldEmitBoletoOnCheckout = isResFaturado && (r.autoEmitBoletoOnCheckout !== false || req.body?.emitBoleto === true);

  if (shouldAutoEmit && !shouldEmitBoletoOnCheckout && !r.invoiceId && !existingInvForCheckout) {
    try {
      const officialDraft = buildOfficialNfseDraftForReservation(db, { reservation: r });
      const breakdown = computeReservationAccommodationAndConsumption(r, db);
      const valor = (confFiscal?.managerApprovedValue && Number(confFiscal.valorServico) > 0)
        ? Number(confFiscal.valorServico)
        : Number(breakdown.accommodationAmount || officialDraft?.valorServico || r.dailyRate || confFiscal?.valorServico || 250);

      const tomadorNome = confFiscal?.tomadorNome || officialDraft?.tomadorNome || r.guestName || "";
      const tomadorDoc = onlyDigits(
        confFiscal?.tomadorCpfCnpj ||
        officialDraft?.tomadorCpfCnpj ||
        r.guestDocument ||
        guest?.documentNumber ||
        guest?.document ||
        company?.cnpj ||
        ""
      );

      if (tomadorNome && (tomadorDoc.length === 11 || tomadorDoc.length === 14)) {
        const effectiveInvoiceCheckout = (r.earlyCheckout && r.originalCheckoutDate) ? r.originalCheckoutDate : r.checkoutDate;
        const targetNfPhone = cleanPhone(
          confFiscal?.tomadorTelefone ||
          officialDraft?.tomadorTelefone ||
          r.guestPhone ||
          guest?.phone ||
          ""
        );

        const nfseOut = await executeNfseEmissionInternal({
          reservationId: r.id,
          reservationCode: r.reservationCode || r.code || null,
          flatNumber: String(r.flatNumber || "113"),
          checkinDate: r.checkinDate,
          checkoutDate: effectiveInvoiceCheckout,
          guestId: guest ? Number(guest.id) : (r.guestId ? Number(r.guestId) : null),
          guestName: r.guestName || officialDraft?.guestName || tomadorNome,
          guestPhone: cleanPhone(r.guestPhone || guest?.phone || ""),
          companyId: officialDraft?.companyId || (company ? Number(company.id) : (r.companyId ? Number(r.companyId) : null)),
          agencyId: officialDraft?.agencyId || (r.agencyId ? Number(r.agencyId) : null),
          invoiceRecipientType: r.invoiceRecipientType || officialDraft?.invoiceRecipientType || (tomadorDoc.length === 14 ? "company" : "guest"),
          tomadorNome: toTitleCase(tomadorNome),
          tomadorCpfCnpj: tomadorDoc,
          tomadorEmail: (confFiscal?.tomadorEmail || officialDraft?.tomadorEmail || r.guestEmail || guest?.email || "").trim().toLowerCase(),
          tomadorTelefone: targetNfPhone,
          whatsappTargetPhone: !r.nfHideFromGuest ? targetNfPhone : "",
          tomadorEndereco: (confFiscal?.tomadorEndereco || officialDraft?.tomadorEndereco || guest?.address || guest?.logradouro || "").trim(),
          tomadorNumero: (confFiscal?.tomadorNumero || officialDraft?.tomadorNumero || guest?.number || "").trim(),
          tomadorComplemento: (confFiscal?.tomadorComplemento ?? officialDraft?.tomadorComplemento ?? guest?.complement ?? "").trim(),
          tomadorBairro: (confFiscal?.tomadorBairro || officialDraft?.tomadorBairro || guest?.neighborhood || guest?.bairro || "").trim(),
          tomadorCep: cleanCep(confFiscal?.tomadorCep || officialDraft?.tomadorCep || guest?.cep || ""),
          tomadorCidade: (confFiscal?.tomadorCidade || officialDraft?.tomadorCidade || guest?.city || guest?.cidade || "Campos dos Goytacazes").trim(),
          tomadorUf: (confFiscal?.tomadorUf || officialDraft?.tomadorUf || guest?.state || guest?.uf || "RJ").trim().toUpperCase(),
          tomadorCodigoMunicipio: (confFiscal?.tomadorCodigoMunicipio || officialDraft?.tomadorCodigoMunicipio || guest?.ibgeCode || guest?.codigoMunicipio || "3301009").trim(),
          valorServico: valor,
          discriminacao: confFiscal?.descricaoServico || officialDraft?.descricaoServico,
          descricaoServico: confFiscal?.descricaoServico || officialDraft?.descricaoServico,
          nfHideFromGuest: Boolean(r.nfHideFromGuest),
          nfDeliveryEmails: Array.isArray(r.nfDeliveryEmails) ? r.nfDeliveryEmails : undefined,
          skipAutoWhatsapp: Boolean(r.nfHideFromGuest)
        });

        if (nfseOut && nfseOut.success && nfseOut.invoice) {
          autoInvoiceEmitted = true;
          autoInvoiceNumber = nfseOut.numeroNfse;
          autoInvoicePdf = nfseOut.pdfUrl || nfseOut.danfseUrl;

          // Atualiza sessão fiscal da Sofia caso estivesse agendada para o check-out
          if (Array.isArray(db.whatsappConversations)) {
            for (const c of db.whatsappConversations) {
              const fc = c?.fiscalConferenceState;
              if (!fc) continue;
              const matchesRes =
                (fc.reservationId && Number(fc.reservationId) === Number(r.id)) ||
                (fc.reservationCode && r.code && String(fc.reservationCode) === String(r.code));
              if (matchesRes && fc.status === "scheduled_for_checkout") {
                fc.status = "emitted";
                fc.numeroNfse = nfseOut.numeroNfse;
                fc.emittedAt = new Date().toISOString();
              }
            }
          }
        }
      }
    } catch (e) {
      console.error("[Auto-Invoice Error]", e);
    }
  }

  // ── Emissão e Disparo Automático de Boleto(s) Banco Inter + NFS-e no Check-out (Faturado a Prazo) ──
  let autoBoletosEmitted = false;
  let emittedBoletos = [];
  let emittedInvoice = null;
  let faturadoPackageOut = null;
  let faturadoDispatchResult = null;
  if (shouldEmitBoletoOnCheckout) {
    try {
      const faturadoPkg = await emitCheckoutFaturadoPackage(r, {
        ...(req.body || {}),
        triggerSource: "checkout_auto"
      });
      if (faturadoPkg) {
        faturadoPackageOut = faturadoPkg;
        if (Array.isArray(faturadoPkg.boletos) && faturadoPkg.boletos.length > 0) {
          autoBoletosEmitted = true;
          emittedBoletos = faturadoPkg.boletos;
        }
        if (faturadoPkg.invoice) {
          emittedInvoice = faturadoPkg.invoice;
          autoInvoiceEmitted = true;
          autoInvoiceNumber = faturadoPkg.invoice.numeroNfse || faturadoPkg.invoice.numeroNota || autoInvoiceNumber;
          autoInvoicePdf = faturadoPkg.invoice.danfseUrl || faturadoPkg.invoice.linkPdf || autoInvoicePdf;
        }
        faturadoDispatchResult = faturadoPkg.dispatchResult || null;
      }
    } catch (bolErr) {
      console.error("[Auto-Boleto Checkout Error]", bolErr);
    }
  }

  saveDatabase();

  // Dispara WhatsApp de check-out com desduplicação e agendamento da avaliação Google
  await triggerCheckoutWhatsApp(db, saveDatabase, r, "reception_pms").catch(e => {
    console.warn("[Reception Checkout WhatsApp Trigger Error]:", e.message);
  });

  if (isReceptionPublicPath) {
    return res.json({
      success: true,
      message: `Check-out do Apt ${r.flatNumber} realizado. Apartamento desocupado!`,
      reservationId: r.id,
      flatNumber: r.flatNumber
    });
  }

  res.json({
    success: true,
    message: autoBoletosEmitted
      ? `Check-out do Apt ${r.flatNumber} realizado! ${emittedBoletos.length} Boleto(s) Inter${autoInvoiceNumber ? ` e NFS-e Nº ${autoInvoiceNumber}` : ""} emitido(s) e enviado(s) automaticamente.`
      : autoInvoiceEmitted
      ? `Check-out do Apt ${r.flatNumber} realizado com sucesso! NFS-e Nº ${autoInvoiceNumber} emitida automaticamente.`
      : `Check-out do Apt ${r.flatNumber} realizado. Apartamento desocupado!`,
    reservationId: r.id,
    flatNumber: r.flatNumber,
    autoInvoiceEmitted,
    autoInvoiceNumber,
    autoInvoicePdf,
    autoBoletosEmitted,
    boletos: emittedBoletos,
    invoice: emittedInvoice,
    faturadoPackage: faturadoPackageOut,
    faturadoDispatchResult
  });
};
app.post("/api/reception/checkout/:reservationId", handleCheckout);
app.post("/api/pms/reservations/:id/checkout", handleCheckout);

app.patch("/api/pms/guests/:id/auto-invoice", (req, res) => {
  const authUser = getAuthUser(req);
  if (!authUser) return res.status(401).json({ error: "Não autenticado." });
  const id = Number(req.params.id);
  const guest = (db.guests || []).find(g => g.id === id);
  if (!guest) return res.status(404).json({ error: "Hóspede não encontrado" });

  guest.autoEmitInvoice = Boolean(req.body.autoEmitInvoice);
  guest.updatedAt = new Date().toISOString();
  saveDatabase();
  res.json({ success: true, autoEmitInvoice: guest.autoEmitInvoice });
});

app.patch("/api/pms/reservations/:id/auto-invoice", (req, res) => {
  const authUser = getAuthUser(req);
  if (!authUser) return res.status(401).json({ error: "Não autenticado." });
  const id = Number(req.params.id);
  const r = (db.reservations || []).find(x => x.id === id);
  if (!r) return res.status(404).json({ error: "Reserva não encontrada" });

  r.autoEmitInvoice = Boolean(req.body.autoEmitInvoice);
  r.updatedAt = new Date().toISOString();
  saveDatabase();
  res.json({ success: true, autoEmitInvoice: r.autoEmitInvoice });
});

function resolveOriginalCheckoutDateForUndo(db, r) {
  if (!r) return null;
  const curOut = String(r.checkoutDate || "").slice(0, 10);
  const isValidFutureCandidate = (cand) => {
    const s = String(cand || "").trim().slice(0, 10);
    return /^\d{4}-\d{2}-\d{2}$/.test(s) && (!curOut || s > curOut);
  };

  if (isValidFutureCandidate(r.originalCheckoutDate)) {
    return String(r.originalCheckoutDate).slice(0, 10);
  }
  if (isValidFutureCandidate(r.previousCheckoutDate)) {
    return String(r.previousCheckoutDate).slice(0, 10);
  }

  if (Array.isArray(r.auditLogs)) {
    for (const log of r.auditLogs) {
      if (!log) continue;
      if (isValidFutureCandidate(log.details?.originalCheckoutDate)) {
        return String(log.details.originalCheckoutDate).slice(0, 10);
      }
      if (log.action === "early_checkout" && Array.isArray(log.changes)) {
        const outChange = log.changes.find(ch => ch && ch.field === "checkoutDate");
        const oldValMatch = String(outChange?.oldValue || "").match(/(\d{4}-\d{2}-\d{2})/);
        if (oldValMatch && isValidFutureCandidate(oldValMatch[1])) {
          return oldValMatch[1];
        }
        const newValOrigMatch = String(outChange?.newValue || "").match(/Original:\s*(\d{4}-\d{2}-\d{2})/i);
        if (newValOrigMatch && isValidFutureCandidate(newValOrigMatch[1])) {
          return newValOrigMatch[1];
        }
      }
    }
  }

  const noteText = `${r.earlyCheckoutNote || ""}\n${r.notes || ""}`;
  const brMatch = noteText.match(/sa[íi]da\s+original\s+prevista:\s*(\d{2})\/(\d{2})(?:\/(\d{4}))?/i);
  if (brMatch) {
    const dd = brMatch[1];
    const mm = brMatch[2];
    let yyyy = brMatch[3];
    if (!yyyy) {
      const baseYear = Number(String(curOut || r.checkinDate || getBrasiliaNow().date).slice(0, 4)) || new Date().getFullYear();
      const baseMonth = Number(String(curOut || r.checkinDate || "2026-01-01").slice(5, 7)) || 1;
      yyyy = String(Number(mm) < baseMonth ? baseYear + 1 : baseYear);
    }
    const parsedIso = `${yyyy}-${mm}-${dd}`;
    if (isValidFutureCandidate(parsedIso)) {
      return parsedIso;
    }
  }

  if (Array.isArray(r.dailyRates) && r.dailyRates.length > 0) {
    const validDates = r.dailyRates
      .map(d => String(d?.date || "").slice(0, 10))
      .filter(s => /^\d{4}-\d{2}-\d{2}$/.test(s))
      .sort();
    if (validDates.length > 0) {
      const lastNight = validDates[validDates.length - 1];
      const nextDay = new Date(lastNight + "T12:00:00Z");
      if (!isNaN(nextDay.getTime())) {
        nextDay.setUTCDate(nextDay.getUTCDate() + 1);
        const candFromRates = nextDay.toISOString().slice(0, 10);
        if (isValidFutureCandidate(candFromRates)) {
          return candFromRates;
        }
      }
    }
  }

  if (Array.isArray(db?.breakfastOrders)) {
    for (const o of db.breakfastOrders) {
      if (!o) continue;
      const matchesOrder =
        (o.reservationCode && (o.reservationCode === r.code || o.reservationCode === r.reservationCode)) ||
        (o.reservationId && Number(o.reservationId) === Number(r.id));
      if (matchesOrder && isValidFutureCandidate(o.checkoutWarningInfo?.originalCheckoutDate)) {
        return String(o.checkoutWarningInfo.originalCheckoutDate).slice(0, 10);
      }
    }
  }

  if (r.originalCheckoutDate && /^\d{4}-\d{2}-\d{2}$/.test(String(r.originalCheckoutDate).slice(0, 10))) {
    return String(r.originalCheckoutDate).slice(0, 10);
  }
  return curOut || null;
}

export function undoReservationCheckoutAndRestoreStay(db, r, options = {}) {
  if (!db || !r) return { wasEarlyCheckout: false, restoredCheckoutDate: null };

  ensureReservationAuditLogs(r);
  const nowIso = options.nowIso || new Date().toISOString();
  const todayStr = options.todayStr || getBrasiliaNow().date;
  const oldCheckoutDate = r.checkoutDate;
  const oldEarlyCheckoutDate = r.earlyCheckoutDate || null;
  const oldStatus = r.status;

  const resolvedOriginalCheckout = options.explicitCheckoutDate
    ? String(options.explicitCheckoutDate).slice(0, 10)
    : resolveOriginalCheckoutDateForUndo(db, r);

  const wasEarlyCheckout = Boolean(
    r.earlyCheckout ||
    r.earlyCheckoutDate ||
    r.earlyCheckoutAt ||
    r.earlyCheckoutReleasedAt ||
    (resolvedOriginalCheckout && oldCheckoutDate && resolvedOriginalCheckout > oldCheckoutDate)
  );
  const restoredCheckoutDate = (wasEarlyCheckout && resolvedOriginalCheckout)
    ? resolvedOriginalCheckout
    : (options.explicitCheckoutDate || r.checkoutDate);

  if (!options.preserveIncomingStatus) {
    const prevSt = String(r.previousStatus || "").toLowerCase();
    const isValidPrevActiveStatus =
      Boolean(r.previousStatus) &&
      !["completed", "checked_out", "cancelada", "cancelado", "cancelled", "expirada", "pre_reserva", "pendente", "no_show"].includes(prevSt);
    if (isValidPrevActiveStatus) {
      r.status = (r.checkinDate <= todayStr && restoredCheckoutDate >= todayStr && r.actualCheckinAt)
        ? "in_house"
        : r.previousStatus;
    } else if (r.checkinDate && r.checkinDate > todayStr) {
      r.status = "confirmada";
    } else {
      r.status = "in_house";
    }
  }
  if (["completed", "checked_out", "expirada", "pre_reserva"].includes(String(r.previousStatus || "").toLowerCase())) {
    delete r.previousStatus;
  }

  r.checkoutDone = false;
  r.actualCheckoutAt = null;
  r.actualCheckoutTime = null;
  r.checkedOutAt = null;
  r.digitalCheckoutAt = null;
  r.checkoutMethod = null;
  r.checkoutReportedBy = null;
  r.checkoutReportedAt = null;
  r.finalMinibarInspectionAt = null;
  r._checkoutUndoneDate = todayStr;
  r._checkoutUndoneAt = nowIso;
  if (r.status !== "pre_reserva") {
    r.expiresAt = null;
    r.reminderAt = null;
    delete r.expiredAt;
    delete r.expiredWhatsappSentAt;
    delete r.preReservationReminderSentAt;
  }

  if (wasEarlyCheckout || r.earlyCheckout || r.earlyCheckoutNote || (r.notes && String(r.notes).includes("Check-out antecipado em")) || (r.specialRequests && String(r.specialRequests).includes("Check-out antecipado em"))) {
    r.checkoutDate = restoredCheckoutDate;
    const stripUndoneEarlyNote = (rawStr) => {
      if (!rawStr) return "";
      let cleaned = String(rawStr);
      if (r.earlyCheckoutNote) {
        cleaned = cleaned.replace(
          new RegExp(`(?:^|\\n)\\s*•?\\s*${String(r.earlyCheckoutNote).replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "g"),
          ""
        );
      }
      return cleaned
        .replace(/(?:^|\n)\s*•?\s*Check-out antecipado em [^\n]+/g, "")
        .trim();
    };
    if (r.notes) {
      r.notes = stripUndoneEarlyNote(r.notes);
    }
    if (r.specialRequests) {
      r.specialRequests = stripUndoneEarlyNote(r.specialRequests);
    }
    r.earlyCheckout = false;
    r.originalCheckoutDate = null;
    r.earlyCheckoutDate = null;
    r.earlyCheckoutTime = null;
    r.earlyCheckoutAt = null;
    r.earlyCheckoutReleasedAt = null;
    r.earlyCheckoutReportedBy = null;
    r.earlyCheckoutNote = null;
    r.earlyCheckoutAdminNotifiedAt = null;
    r._earlyCheckoutUndone = true;
    r.calendarSequence = (r.calendarSequence || 0) + 1;

    if (!options.preserveIncomingRates) {
      if (Number(r.originalTotalAmount) > 0) {
        if (Number(r.totalAmount || 0) < Number(r.originalTotalAmount)) {
          r.totalAmount = Number(r.originalTotalAmount);
        }
        delete r.originalTotalAmount;
      }
      if (r.checkinDate && r.checkoutDate && r.checkoutDate > r.checkinDate && Array.isArray(r.dailyRates) && r.dailyRates.length > 0) {
        const d1 = new Date(r.checkinDate + "T12:00:00Z");
        const d2 = new Date(r.checkoutDate + "T12:00:00Z");
        const expectedNights = Math.max(1, Math.round((d2.getTime() - d1.getTime()) / 86400000));
        if (r.dailyRates.length < expectedNights) {
          const rateMap = new Map();
          r.dailyRates.forEach(d => {
            if (d && d.date) rateMap.set(String(d.date).slice(0, 10), d);
          });
          const chargesSum = Array.isArray(r.charges)
            ? r.charges.reduce((acc, c) => acc + (Number(c?.amount) || 0), 0)
            : (Number(r.cleaningFee) || 0);
          const existingAvg = Math.round((r.dailyRates.reduce((acc, d) => acc + (Number(d?.rate ?? d?.amount) || 0), 0) / r.dailyRates.length) * 100) / 100;
          const inferredUnit = Number(r.dailyRate) > 0
            ? Number(r.dailyRate)
            : (existingAvg > 0
                ? existingAvg
                : (Number(r.totalAmount) > chargesSum ? Math.round(((Number(r.totalAmount) - chargesSum) / expectedNights) * 100) / 100 : 250));
          const rebuilt = [];
          for (let i = 0; i < expectedNights; i++) {
            const dStr = new Date(d1.getTime() + i * 86400000).toISOString().slice(0, 10);
            const ex = rateMap.get(dStr);
            if (ex) {
              rebuilt.push(ex);
            } else {
              const prev = rebuilt.length > 0 ? rebuilt[rebuilt.length - 1] : null;
              rebuilt.push({
                date: dStr,
                rate: prev && Number(prev.rate ?? prev.amount) > 0 ? Number(prev.rate ?? prev.amount) : inferredUnit,
                channel: (prev && prev.channel) || r.channel || "whatsapp"
              });
            }
          }
          r.dailyRates = rebuilt;
        }
      }
    }

    if (!options.skipAuditLog) {
      const authUser = options.actorUser || null;
      addReservationAuditLog(r, {
        action: "undo_early_checkout",
        actor: {
          id: authUser?.id || null,
          name: authUser?.name || authUser?.username || "Administrador / Recepção",
          role: authUser?.role || "admin",
          type: "user"
        },
        source: options.source || "PMS / Recepção",
        description: `Check-out antecipado desfeito. Saída restaurada de ${oldCheckoutDate} para ${restoredCheckoutDate}.`,
        changes: [
          { field: "checkoutDate", label: "Data de Check-out", oldValue: oldCheckoutDate, newValue: restoredCheckoutDate },
          { field: "status", label: "Status da Reserva", oldValue: oldStatus || "completed", newValue: r.status }
        ]
      });
    }
  } else if (!options.skipAuditLog) {
    const authUser = options.actorUser || null;
    addReservationAuditLog(r, {
      action: "undo_checkout",
      actor: {
        id: authUser?.id || null,
        name: authUser?.name || authUser?.username || "Administrador / Recepção",
        role: authUser?.role || "admin",
        type: "user"
      },
      source: options.source || "PMS / Recepção",
      description: `Check-out do Apt ${r.flatNumber} desfeito e estadia reativada.`,
      changes: [
        { field: "status", label: "Status da Reserva", oldValue: oldStatus || "completed", newValue: r.status }
      ]
    });
  }
  r.updatedAt = nowIso;

  const flat = (db.flats || []).find(f => f.id === r.flatId || String(f.number) === String(r.flatNumber));
  if (flat && (!r.checkinDate || r.checkinDate <= todayStr) && (!r.checkoutDate || r.checkoutDate >= todayStr)) {
    flat.isOccupied = true;
    flat.updatedAt = nowIso;
  }

  const targetFlatNum = String(r.flatNumber || flat?.number || "");
  if (!Array.isArray(db.cleaningRequests)) db.cleaningRequests = [];
  let hasActiveCheckoutCardOnRestoredDate = false;
  let softDeletedCheckoutCardOnRestoredDate = null;

  for (const c of db.cleaningRequests) {
    if (!c) continue;
    const sameFlat = (r.flatId && Number(c.flatId) === Number(r.flatId)) || (targetFlatNum && String(c.flatNumber) === targetFlatNum);
    if (!sameFlat) continue;
    const isInst = Boolean(
      c.isInstructionOnly ||
      c.isBedAdjustmentOnly ||
      c.source === "manual_instruction" ||
      c.type === "instruction" ||
      c.type === "bed_adjustment_only"
    );
    if (isInst) continue;
    const isStayoverOrService = Boolean(
      c.source === "stayover" ||
      c.cleaningType === "stayover" ||
      c.type === "stayover" ||
      c.source === "service_order" ||
      c.cleaningType === "service_order"
    );
    if (isStayoverOrService) continue;

    const reqDate = c.requestDate || c.effectiveDate;
    if ((c.isDeleted || c.status === "deleted") && reqDate === r.checkoutDate && reqDate >= todayStr) {
      softDeletedCheckoutCardOnRestoredDate = c;
      continue;
    }
    if (c.isDeleted || c.status === "deleted") continue;

    const isIntermediateUndoDate = Boolean(
      reqDate &&
      r.checkoutDate &&
      reqDate < r.checkoutDate &&
      (reqDate === oldCheckoutDate || reqDate === oldEarlyCheckoutDate || reqDate === todayStr || (r.checkinDate && reqDate > r.checkinDate))
    );

    if (isIntermediateUndoDate) {
      const hasOtherActiveCheckoutOnDate = (db.reservations || []).some(other =>
        other &&
        other.id !== r.id &&
        !["cancelada", "cancelado", "cancelled", "expirada", "pre_reserva", "pendente", "no_show"].includes(String(other.status || "").toLowerCase()) &&
        ((r.flatId && Number(other.flatId) === Number(r.flatId)) || String(other.flatNumber || "") === targetFlatNum) &&
        (other.checkoutDate === reqDate || other.earlyCheckoutDate === reqDate)
      );
      if (!hasOtherActiveCheckoutOnDate) {
        c.isVacant = false;
        c.isVacantExplicitlySet = false;
        c.vacantSource = null;
        c.vacantSetAt = null;
        c.vacantSetBy = null;
        c.updatedAt = nowIso;
        if (c.status !== "clean" && c.status !== "cleaning_now" && c.status !== "in_progress") {
          c.isDeleted = true;
          c.status = "deleted";
          c.deletedAt = nowIso;
          c.deletedBy = "undo_early_checkout";
        }
      }
    } else if (reqDate === r.checkoutDate && reqDate >= todayStr) {
      hasActiveCheckoutCardOnRestoredDate = true;
      c.isVacant = false;
      c.isVacantExplicitlySet = false;
      c.vacantSource = null;
      c.vacantSetAt = null;
      c.vacantSetBy = null;
      if (c.status === "will_clean" || (reqDate === todayStr && (c.status === "clean" || c.status === "cleaning_now" || c.status === "in_progress"))) {
        c.status = "dirty";
        c.willCleanAt = null;
        c.cleaningStartedAt = null;
        c.completedAt = null;
        c.durationMinutes = null;
      }
      c.updatedAt = nowIso;
    }
  }

  if (
    r.checkoutDate &&
    r.checkoutDate >= todayStr &&
    !hasActiveCheckoutCardOnRestoredDate &&
    !["cancelada", "cancelado", "cancelled", "expirada", "pre_reserva", "pendente", "no_show"].includes(String(r.status || "").toLowerCase())
  ) {
    if (softDeletedCheckoutCardOnRestoredDate) {
      softDeletedCheckoutCardOnRestoredDate.isDeleted = false;
      softDeletedCheckoutCardOnRestoredDate.status = "dirty";
      softDeletedCheckoutCardOnRestoredDate.leavingGuest = r.guestName || softDeletedCheckoutCardOnRestoredDate.leavingGuest || "Hóspede";
      softDeletedCheckoutCardOnRestoredDate.isVacant = false;
      softDeletedCheckoutCardOnRestoredDate.isVacantExplicitlySet = false;
      softDeletedCheckoutCardOnRestoredDate.vacantSource = null;
      softDeletedCheckoutCardOnRestoredDate.vacantSetAt = null;
      softDeletedCheckoutCardOnRestoredDate.vacantSetBy = null;
      delete softDeletedCheckoutCardOnRestoredDate.deletedAt;
      delete softDeletedCheckoutCardOnRestoredDate.deletedBy;
      delete softDeletedCheckoutCardOnRestoredDate.deletedReservationId;
      softDeletedCheckoutCardOnRestoredDate.updatedAt = nowIso;
    } else if (targetFlatNum) {
      const maxCleanId = db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(x => Number(x?.id) || 0)) : 0;
      db.cleaningRequests.unshift({
        id: maxCleanId + 1,
        flatId: r.flatId || flat?.id || null,
        flatNumber: targetFlatNum,
        requestDate: r.checkoutDate,
        source: "checkout",
        status: "dirty",
        assignedUserId: null,
        assignedUsername: null,
        isVacant: false,
        isVacantExplicitlySet: false,
        isPriority: false,
        leavingGuest: r.guestName || "Hóspede",
        arrivingGuest: null,
        adminNote: null,
        createdAt: nowIso,
        updatedAt: nowIso
      });
    }
  }

  // Reativar pedidos de café da manhã vinculados caso tenham sido cancelados por checkout / check-out antecipado
  if (Array.isArray(db.breakfastOrders)) {
    db.breakfastOrders.forEach(o => {
      if (!o) return;
      const isMatch =
        (o.reservationCode && (o.reservationCode === r.code || o.reservationCode === r.reservationCode)) ||
        (o.reservationId && Number(o.reservationId) === Number(r.id)) ||
        (!o.reservationCode && !o.reservationId && String(o.roomNumber) === targetFlatNum && o.date >= r.checkinDate && o.date <= r.checkoutDate);
      if (
        isMatch &&
        o.status === "cancelled" &&
        !o.cancelledManually &&
        o.date >= todayStr &&
        o.date <= r.checkoutDate &&
        (
          o.cancelledByCheckout ||
          o.checkoutWarningInfo ||
          /check-out|antecipad|reduzida|removida/i.test(String(o.cancelReason || ""))
        )
      ) {
        o.status = "pending";
        o.cancelReason = null;
        o.cancelledByCheckout = false;
        o.checkoutWarningInfo = null;
        o.updatedAt = nowIso;
      }
    });
  }

  try {
    ensureReservationScheduledEmails(db, null, r);
  } catch (_) {}

  return { wasEarlyCheckout, restoredCheckoutDate, oldCheckoutDate };
}

const handleUndoCheckout = (req, res) => {
  const isReceptionUndo = String(req.path || "").startsWith("/api/reception/");
  const authUser = getAuthUser(req);
  if (!isReceptionUndo && !authUser) {
    return res.status(401).json({ error: "Não autenticado." });
  }

  const rawId = String(req.params.reservationId || req.params.id || "").trim();
  const id = Number(rawId);
  const upperRawId = rawId.toUpperCase();
  const r = (db.reservations || []).find(x =>
    x && (
      (!isNaN(id) && x.id === id) ||
      String(x.id) === rawId ||
      (x.code && String(x.code).toUpperCase() === upperRawId) ||
      (x.reservationCode && String(x.reservationCode).toUpperCase() === upperRawId)
    )
  );
  if (!r) return res.status(404).json({ error: "Reserva não encontrada" });

  undoReservationCheckoutAndRestoreStay(db, r, {
    actorUser: authUser,
    source: isReceptionUndo ? "Recepção / Portaria" : "PMS / Recepção"
  });

  const undoConflicts = typeof findActiveOverbookingConflicts === "function"
    ? findActiveOverbookingConflicts(db, {
        flatId: r.flatId,
        flatNumber: r.flatNumber,
        checkinDate: r.checkinDate,
        checkoutDate: r.checkoutDate,
        excludeResId: r.id
      })
    : [];
  if (undoConflicts.length > 0) {
    r.isOverbooking = true;
    r.conflictWarning = `Conflito de reserva no Flat ${r.flatNumber}`;
    r.conflictDetails = undoConflicts;
  } else {
    r.isOverbooking = false;
    delete r.conflictWarning;
    delete r.conflictDetails;
  }

  saveDatabase();
  const responseRes = isReceptionUndo
    ? buildSanitizedReceptionItem(r)
    : {
        ...r,
        code: r.code || r.reservationCode || `RES-${r.flatNumber || "000"}-${String(r.id).padStart(4, "0")}`,
        checkoutDone: false,
        isCheckedOutToday: false,
        earlyCheckout: false,
        originalCheckoutDate: null,
        earlyCheckoutDate: null,
        earlyCheckoutTime: null,
        earlyCheckoutReportedBy: null,
        earlyCheckoutNote: null
      };
  res.json({
    success: true,
    message: `Check-out do Apt ${r.flatNumber} desfeito com sucesso!`,
    conflicts: undoConflicts,
    reservation: responseRes
  });
};
app.post("/api/reception/undo-checkout/:reservationId", handleUndoCheckout);
app.post("/api/pms/reservations/:id/undo-checkout", handleUndoCheckout);

// ── Communications & Messaging History Engine (Zoho Mail SMTP & Portaria) ────

// Gerador de E-mails Agendados para Reserva (Fila de Pré/Pós Estadia)
export function ensureReservationScheduledEmails(db, saveDatabase, r) {
  if (!r || !r.guestEmail || r.status === "cancelada" || isPreReservationBlocked(r)) return;
  if (!db.emailQueue) db.emailQueue = [];

  if (isReservationOrFlatCheckedOut(db, r)) {
    cancelPendingStayRemindersForCheckout(db, saveDatabase, {
      reservation: r,
      flatId: r.flatId,
      flatNumber: r.flatNumber,
      reason: "Cancelado: check-out já realizado no flat"
    });
    return;
  }

  const resCode = r.code || `RES-${r.flatNumber || '00'}-${r.id}`;
  const guestEmail = r.guestEmail.trim();

  // 1. E-mail de Pré-Check-in / Instruções de Chegada (véspera ou dia do check-in às 09:00)
  const existingWelcome = db.emailQueue.find(q =>
    (q.reservationCode === resCode || q.reservationId === String(r.id)) &&
    q.triggerEvent === "checkin_welcome" &&
    q.status !== "cancelled"
  );
  if (r.checkinDate) {
    let schedDate = r.checkinDate;
    try {
      const d = new Date(r.checkinDate + "T09:00:00Z");
      d.setDate(d.getDate() - 1);
      schedDate = d.toISOString().split("T")[0];
    } catch {}

    const welcomeSubject = `[INSTRUÇÕES DE CHEGADA] Flat ${r.flatNumber} - CorpFlats Soho`;
    const welcomeBodyHtml = wrapEmailTemplate({
      title: welcomeSubject,
      badge: `<span class="badge badge-checkin" style="display: inline-block; padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; background-color: #ECFDF5; color: #047857; border: 1px solid #A7F3D0;">Pré-Check-in</span>`,
      contentHtml: `
        <div style="margin-bottom: 20px;">
          <h1 style="font-size: 20px; font-weight: 600; line-height: 1.3; color: #111827; margin: 0 0 8px 0;">Instruções de Chegada • Flat ${r.flatNumber}</h1>
          <p style="font-size: 15px; color: #374151; margin: 0; line-height: 1.6;">Olá, <strong>${r.guestName}</strong>!</p>
        </div>
        <div style="background-color: #F9FAFB; border: 1px solid #E5E7EB; border-radius: 6px; padding: 16px; margin-bottom: 16px; font-size: 15px; color: #374151; line-height: 1.6;">
          Sua estadia no <strong>Flat ${r.flatNumber}</strong> está próxima! Lembramos que o check-in inicia às 14:00. Preencha sua ficha de check-in digital antecipadamente para agilizar sua entrada na portaria.
        </div>
      `
    });
    const welcomeBodyText = `Olá, ${r.guestName}! Sua estadia no Flat ${r.flatNumber} está próxima! Check-in a partir das 14:00.`;
    const welcomeScheduledFor = `${schedDate}T09:00:00.000Z`;

    if (!existingWelcome) {
      db.emailQueue.push({
        id: `em_q_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
        reservationId: String(r.id),
        reservationCode: resCode,
        guestName: r.guestName || "Hóspede",
        recipient: guestEmail,
        subject: welcomeSubject,
        bodyHtml: welcomeBodyHtml,
        bodyText: welcomeBodyText,
        status: "pending",
        scheduledFor: welcomeScheduledFor,
        triggerEvent: "checkin_welcome",
        createdAt: new Date().toISOString(),
        sentAt: null,
        error: null
      });
    } else if (existingWelcome.status === "pending" || existingWelcome.status === "scheduled") {
      existingWelcome.guestName = r.guestName || "Hóspede";
      existingWelcome.recipient = guestEmail;
      existingWelcome.subject = welcomeSubject;
      existingWelcome.bodyHtml = welcomeBodyHtml;
      existingWelcome.bodyText = welcomeBodyText;
      existingWelcome.scheduledFor = welcomeScheduledFor;
    }
  }

  // 2. E-mail de Lembrete de Check-out (dia de saída às 08:30)
  const existingCheckout = db.emailQueue.find(q =>
    (q.reservationCode === resCode || q.reservationId === String(r.id)) &&
    q.triggerEvent === "checkout_reminder" &&
    q.status !== "cancelled"
  );
  if (r.checkoutDate) {
    const checkoutSubject = `[LEMBRETE DE CHECK-OUT] Flat ${r.flatNumber} - CorpFlats Soho`;
    const checkoutBodyHtml = wrapEmailTemplate({
      title: checkoutSubject,
      badge: `<span class="badge badge-general" style="display: inline-block; padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; background-color: #F9FAFB; color: #374151; border: 1px solid #E5E7EB;">Check-out</span>`,
      contentHtml: `
        <div style="margin-bottom: 20px;">
          <h1 style="font-size: 20px; font-weight: 600; line-height: 1.3; color: #111827; margin: 0 0 8px 0;">Lembrete de Check-out • Flat ${r.flatNumber}</h1>
          <p style="font-size: 15px; color: #374151; margin: 0; line-height: 1.6;">Bom dia, <strong>${r.guestName}</strong>!</p>
        </div>
        <div style="background-color: #F9FAFB; border: 1px solid #E5E7EB; border-radius: 6px; padding: 16px; margin-bottom: 16px; font-size: 15px; color: #374151; line-height: 1.6;">
          Lembramos que hoje encerra sua estadia no <strong>Flat ${r.flatNumber}</strong>. O horário limite de saída é às 12:00. Ao desocupar a unidade, basta entregar a chave na portaria.
        </div>
      `
    });
    const checkoutBodyText = `Bom dia, ${r.guestName}! Lembramos que hoje é a data de saída do Flat ${r.flatNumber} até as 12:00.`;
    const checkoutScheduledFor = `${r.checkoutDate}T08:30:00.000Z`;

    if (!existingCheckout) {
      db.emailQueue.push({
        id: `em_q_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
        reservationId: String(r.id),
        reservationCode: resCode,
        guestName: r.guestName || "Hóspede",
        recipient: guestEmail,
        subject: checkoutSubject,
        bodyHtml: checkoutBodyHtml,
        bodyText: checkoutBodyText,
        status: "pending",
        scheduledFor: checkoutScheduledFor,
        triggerEvent: "checkout_reminder",
        createdAt: new Date().toISOString(),
        sentAt: null,
        error: null
      });
    } else if (existingCheckout.status === "pending" || existingCheckout.status === "scheduled") {
      existingCheckout.guestName = r.guestName || "Hóspede";
      existingCheckout.recipient = guestEmail;
      existingCheckout.subject = checkoutSubject;
      existingCheckout.bodyHtml = checkoutBodyHtml;
      existingCheckout.bodyText = checkoutBodyText;
      existingCheckout.scheduledFor = checkoutScheduledFor;
    }
  }

  if (typeof saveDatabase === "function") saveDatabase();
}

function formatTriggerTitle(trigger) {
  const map = {
    reservation_created: "Nova Reserva • Confirmação + Early Check-in",
    pre_reservation_created: "Pré-Reserva • Confirmação & Aguardando Pagamento",
    pre_reservation_expired: "Pré-Reserva Expirada • Prazo de Pagamento Encerrado",
    payment_confirmed: "Pagamento Confirmado • Reserva Garantida",
    sameday_reservation: "Reserva de Hoje • Confirmação & Instruções",
    pre_checkin_completed: "Check-in Online Concluído • Confirmação & Instruções",
    room_ready: "Apartamento Pronto • Acesso Liberado",
    checkin_completed: "Check-in Realizado • Boas-Vindas",
    checkout_completed: "Check-out Realizado • Agradecimento",
    checkout_reminder: "Lembrete de Check-out",
    post_checkout_review: "Avaliação Pós-Hospedagem",
    breakfast_order: "Pedido de Café da Manhã",
    manual_dispatch: "Mensagem Manual",
    chat_direct: "Mensagem Direta"
  };
  return map[trigger] || trigger;
}

// 1. Obter histórico de comunicações vinculado à reserva (E-mails e WhatsApp: Enviados e Agendados)
app.get("/api/pms/reservations/:id/communications", async (req, res) => {
  const paramId = String(req.params.id || "").trim();
  const r = (db.reservations || []).find(x =>
    String(x.id) === paramId ||
    x.code === paramId ||
    (x.code && x.code.toUpperCase() === paramId.toUpperCase())
  );
  const resIdStr = r ? String(r.id) : paramId;
  const resCode = r?.code || (paramId.startsWith("RES-") || paramId.startsWith("CORP-") || paramId.startsWith("B2B-") ? paramId : null);

  if (r && (!pgPool || pgHydratedSuccessfully)) {
    ensureReservationScheduledEmails(db, saveDatabase, r);
    try {
      scheduleUpcomingReservationTriggers(db, saveDatabase);
    } catch (_) {}
    const isB2b = String(r.channel || "").toLowerCase().includes("b2b") || Boolean(r.b2bReservationNumber);
    if (isB2b && (!r.guestPhone || !r.guestDocument) && !r.b2bCredentialCompletedAt && !r.b2bCredentialEmailSentAt) {
      const baseUrl = `${req.protocol}://${req.get("host")}`.replace(/https?:\/\/corpflats\.onrender\.com/gi, "https://corpflats.com.br");
      await ensurePendingB2bAgencyCredentialDispatches(db, saveDatabase, { baseUrl });
    }
  }

  // 1. E-mails Enviados
  if (!db.reservationCommunications) db.reservationCommunications = [];
  const emailsSent = db.reservationCommunications.filter(c =>
    String(c.reservation_id) === resIdStr ||
    (resCode && String(c.reservation_id) === String(resCode))
  );
  emailsSent.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());

  // 2. E-mails Agendados
  if (!db.emailQueue) db.emailQueue = [];
  const emailsScheduled = db.emailQueue.filter(q =>
    (q.reservationCode && (q.reservationCode === resCode || q.reservationCode === resIdStr)) ||
    (q.reservationId && (String(q.reservationId) === resIdStr || String(q.reservationId) === String(resCode)))
  );

  // 3. Resolução Consolidada de Telefones e Identificadores para WhatsApp
  const matchedGuest = r ? (db.guests || []).find(g =>
    (r.guestId && g.id === r.guestId) ||
    (r.guestPhone && g.phone && g.phone.replace(/\D/g, "") === r.guestPhone.replace(/\D/g, "")) ||
    (r.guestDocument && g.document && g.document.replace(/\D/g, "") === r.guestDocument.replace(/\D/g, "")) ||
    (r.guestName && g.name && g.name.toLowerCase().trim() === r.guestName.toLowerCase().trim())
  ) : null;

  const phoneCandidates = new Set();
  const addPhoneDigits = (raw) => {
    if (!raw) return;
    const digits = String(raw).replace(/\D/g, "");
    if (!digits) return;
    phoneCandidates.add(digits);
    const cleaned = cleanWhatsAppPhone(raw);
    if (cleaned) phoneCandidates.add(cleaned);
    if (digits.startsWith("55") && digits.length >= 12) {
      phoneCandidates.add(digits.substring(2));
    }
  };

  addPhoneDigits(r?.guestPhone);
  addPhoneDigits(r?.guests?.[0]?.phone);
  addPhoneDigits(matchedGuest?.phone);

  const isMiller = (r?.guestName && r.guestName.toLowerCase().includes("miller")) ||
                   (r?.guestDocument && r.guestDocument.replace(/\D/g, "") === "12585736792");
  if (isMiller) {
    addPhoneDigits("22998505276");
    addPhoneDigits("5522998505276");
  }

  const candidateDigitsList = Array.from(phoneCandidates);

  const phoneMatches = (targetPhone) => {
    if (!targetPhone) return false;
    const tDigits = String(targetPhone).replace(/\D/g, "");
    if (!tDigits) return false;
    return candidateDigitsList.some(cand =>
      cand === tDigits ||
      cand.endsWith(tDigits) ||
      tDigits.endsWith(cand) ||
      (cand.length >= 8 && tDigits.length >= 8 && cand.slice(-8) === tDigits.slice(-8))
    );
  };

  const idMatches = (code, id) => {
    if (resCode && code && String(code).toUpperCase() === String(resCode).toUpperCase()) return true;
    if (resIdStr && (String(code) === resIdStr || String(id) === resIdStr)) return true;
    if (paramId && (String(code) === paramId || String(id) === paramId)) return true;
    return false;
  };

  // 4. Mensagens de WhatsApp Agendadas (Fila) — vinculação estrita por reserva quando reservationCode/reservationId existir
  const whatsappQueue = (db.whatsappQueue || []).filter(q => {
    if (idMatches(q.reservationCode, q.reservationId)) return true;
    if (q.reservationCode || q.reservationId) return false;
    if (phoneMatches(q.guestPhone)) return true;
    return false;
  });

  // 5. Histórico de Mensagens de WhatsApp Enviadas — nunca misturar mensagens de reservas anteriores/canceladas do mesmo hóspede
  const whatsappHistory = (db.whatsappHistory || []).filter(h => {
    if (idMatches(h.reservationCode, h.reservationId)) return true;
    if (h.reservationCode || h.reservationId) return false;
    if (r?.createdAt && h.sentAt && h.sentAt < r.createdAt) return false;
    if (phoneMatches(h.guestPhone)) return true;
    if (r?.guestName && h.guestName && h.guestName.toLowerCase().trim() === r.guestName.toLowerCase().trim()) {
      return true;
    }
    return false;
  });

  // 6. Incorpora também mensagens outbound de WhatsApp das conversas ativas se pertencerem a esta reserva
  const convs = (db.whatsappConversations || []).filter(c => phoneMatches(c.phone) || phoneMatches(c.id));
  convs.forEach(conv => {
    (conv.messages || []).forEach(m => {
      if (!m.fromMe) return;
      const hasExplicitRes = Boolean(m.reservationCode || m.reservationId);
      const isRel = hasExplicitRes
        ? idMatches(m.reservationCode, m.reservationId)
        : Boolean(
            m.triggerEvent &&
            m.triggerEvent !== "chat_direct" &&
            (!r?.createdAt || !m.timestamp || m.timestamp >= r.createdAt)
          );
      if (isRel) {
        const already = whatsappHistory.some(h =>
          (h.id && m.id && h.id === m.id) ||
          (h.message === m.text && h.triggerEvent === m.triggerEvent)
        );
        if (!already) {
          whatsappHistory.push({
            id: m.id || m.messageId || `conv_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
            reservationCode: m.reservationCode || resCode,
            reservationId: r?.id,
            guestName: r?.guestName || conv.name,
            guestPhone: conv.phone,
            triggerEvent: m.triggerEvent || "mensagem_whatsapp",
            title: m.triggerEvent ? formatTriggerTitle(m.triggerEvent) : "Mensagem WhatsApp",
            message: m.text,
            buttons: m.buttons || [],
            documentUrl: m.mediaUrl || null,
            documentName: m.fileName || null,
            status: m.status === "failed" ? "failed" : "sent",
            method: "whatsapp",
            sentAt: m.timestamp || new Date().toISOString()
          });
        }
      }
    });
  });

  whatsappHistory.sort((a, b) => new Date(b.sentAt || 0).getTime() - new Date(a.sentAt || 0).getTime());

  res.json({
    emails: emailsSent,
    emailsScheduled,
    whatsappQueue,
    whatsappHistory,
    legacy: emailsSent
  });
});

// 2. Envio manual rápido de e-mail a partir do painel da reserva
app.post("/api/pms/reservations/:id/communications/send-email", async (req, res) => {
  const paramId = String(req.params.id || "").trim();
  const { recipient, subject, body } = req.body;

  if (!recipient || !subject || !body) {
    return res.status(400).json({ error: "Destinatário, assunto e corpo da mensagem são obrigatórios." });
  }

  const r = (db.reservations || []).find(x => String(x.id) === paramId || x.code === paramId);
  const flat = r ? (db.flats || []).find(f => f.id === r.flatId || String(f.number) === String(r.flatNumber)) : null;

  const { bodyHtml } = renderManualEmail({
    subject: subject.trim(),
    message: body.trim(),
    reservation: r,
    flat,
    settings: db.settings
  });

  const commLog = await sendEmailAsync({
    db,
    saveDatabase,
    reservationId: r?.code || r?.id || paramId,
    recipient: recipient.trim(),
    subject: subject.trim(),
    bodyHtml,
    bodyText: body.trim(),
    type: "email",
    direction: "outbound",
    metadata: {
      trigger: "manual",
      flatNumber: r?.flatNumber || flat?.number,
      guestName: r?.guestName
    }
  });

  res.json({ success: true, communication: commLog });
});

