// Gerar fatura mensal no Contas a Receber e link de cobrança WhatsApp para Contrato Long-Stay
app.post("/api/pms/longstay-contracts/:id/generate-invoice", (req, res) => {
  initERPFinancialData();
  const id = Number(req.params.id);
  const contract = db.longStayContracts.find(c => c.id === id);
  if (!contract) return res.status(404).json({ error: "Contrato não encontrado." });

  const refMonth = req.body.refMonth || new Date().toISOString().substring(0, 7); // YYYY-MM
  const dueYearMonth = refMonth;
  const dueDayFormatted = String(contract.dueDay || 5).padStart(2, '0');
  const dueDate = `${dueYearMonth}-${dueDayFormatted}`;

  const newReceivable = {
    id: db.accountsReceivable.length > 0 ? Math.max(...db.accountsReceivable.map(i => i.id)) + 1 : 1,
    flatNumber: contract.flatNumber,
    clientName: contract.tenantName,
    category: "mensalidade_longstay",
    description: `Mensalidade Flat ${contract.flatNumber} - Ref. ${refMonth}`,
    amount: contract.monthlyRate,
    dueDate,
    receivedDate: null,
    paymentMethod: "pix",
    status: "pendente",
    notes: `Contrato Nº ${contract.id} (${contract.tenantName})`,
    createdAt: new Date().toISOString()
  };

  db.accountsReceivable.unshift(newReceivable);
  saveDatabase();

  const cleanPhone = (contract.phone || "").replace(/\D/g, "");
  const firstName = (contract.occupantName || contract.tenantName).split(" ")[0];
  const msg = encodeURIComponent(
    `Olá, ${firstName}! Tudo bem? 🏢\n\nSegue a fatura de locação da CorpFlats referente ao Flat ${contract.flatNumber} (Mês ${refMonth}):\n\n💰 Valor: R$ ${contract.monthlyRate.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}\n📅 Vencimento: ${dueDate}\n\nChave PIX CorpFlats:\n👉 pix@corpflats.com.br\n\nQualquer dúvida estamos à disposição!`
  );
  const whatsappUrl = cleanPhone ? `https://wa.me/55${cleanPhone}?text=${msg}` : null;

  res.json({
    success: true,
    message: `Fatura referente a ${refMonth} gerada com sucesso no Contas a Receber!`,
    receivable: newReceivable,
    whatsappUrl
  });
});

// ── Endpoints Fluxo de Caixa e DRE Integrado ────────────────────────────────
app.get("/api/finance/cashflow", (req, res) => {
  initERPFinancialData();
  const payables = db.accountsPayable || [];
  const receivables = db.accountsReceivable || [];
  const reservations = (db.reservations || []).filter(r => r.status !== "cancelada" && r.status !== "cancelado");

  // Sum from accountsReceivable
  let recPaidTotal = receivables.filter(r => r.status === "recebido" || r.status === "pago").reduce((acc, r) => acc + (Number(r.amount) || 0), 0);
  let recPendingTotal = receivables.filter(r => r.status !== "recebido" && r.status !== "pago").reduce((acc, r) => acc + (Number(r.amount) || 0), 0);

  // Sum from reservations (avoid double counting if an account receivable has matching reservation code/id)
  const existingRecCodes = new Set(receivables.map(r => String(r.reservationCode || r.code || "")).filter(Boolean));

  let resPaidTotal = 0;
  let resPendingTotal = 0;

  for (const r of reservations) {
    const code = String(r.id || r.code || "");
    if (existingRecCodes.has(code) || (r.code && existingRecCodes.has(String(r.code)))) {
      continue;
    }
    const total = Number(r.totalAmount || 0);
    const paid = Number(r.paidAmount || (r.paymentStatus === "pago_total" || r.paymentStatus === "pago" ? total : 0));
    const pending = Math.max(0, total - paid);

    resPaidTotal += paid;
    if (r.paymentStatus !== "pago_total" && r.paymentStatus !== "pago") {
      resPendingTotal += pending > 0 ? pending : total;
    }
  }

  const totalInflow = round2(recPaidTotal + resPaidTotal);
  const totalPendingInflow = round2(recPendingTotal + resPendingTotal);

  const totalOutflow = round2(payables.filter(p => p.status === "pago").reduce((acc, p) => acc + (Number(p.amount) || 0), 0));
  const totalPendingOutflow = round2(payables.filter(p => p.status !== "pago").reduce((acc, p) => acc + (Number(p.amount) || 0), 0));

  const netRealized = round2(totalInflow - totalOutflow);
  const netProjected = round2((totalInflow + totalPendingInflow) - (totalOutflow + totalPendingOutflow));

  res.json({
    totalInflow,
    totalPendingInflow,
    totalOutflow,
    totalPendingOutflow,
    netRealized,
    netProjected,
    breakdown: {
      receivablesPaid: round2(recPaidTotal),
      receivablesPending: round2(recPendingTotal),
      reservationsPaid: round2(resPaidTotal),
      reservationsPending: round2(resPendingTotal)
    },
    recentPayables: payables.slice(0, 10),
    recentReceivables: receivables.slice(0, 10)
  });
});

