// ── NFS-e Fiscal Invoices (Padrão Nacional ADN / Receita Federal) ───────────
import {
  toTitleCase,
  onlyDigits,
  isValidCpf,
  isValidCnpj,
  cleanPhone,
  cleanCep,
  TAX_CATALOG,
  buildNationalDpsPayload,
  processNationalInvoiceEmission,
  renderDanfseHtml,
  normalizeTomadorAddressFields,
  generateNationalXmlContent,
  generateChaveAcessoNacional,
  ensureNfseCertFilesOnDisk,
  generateNfsePdfBuffer,
  consultNationalNfseByChave,
  consultNationalDpsById,
  fetchNationalDfeFromAdn,
  checkMunicipalConvenioParams,
  cancelNationalNfseByChave
} from "./national-nfse.mjs";

function formatCpf(cpf = "") {
  const c = onlyDigits(cpf);
  if (c.length !== 11) return cpf;
  return `${c.slice(0, 3)}.${c.slice(3, 6)}.${c.slice(6, 9)}-${c.slice(9)}`;
}

function formatCnpj(cnpj = "") {
  const c = onlyDigits(cnpj);
  if (c.length !== 14) return cnpj;
  return `${c.slice(0, 2)}.${c.slice(2, 5)}.${c.slice(5, 8)}/${c.slice(8, 12)}-${c.slice(12)}`;
}

function isGenericFallbackAddress(logradouro = "", cep = "") {
  const l = String(logradouro || "").trim();
  const c = onlyDigits(cep || "");
  if (!l) return true;
  if (/^(av\.?\s*pelinca|avenida\s*pelinca)(\s*,\s*100)?(\s*-\s*pelinca)?$/i.test(l)) return true;
  if (c === "28035000" && /pelinca/i.test(l)) return true;
  return false;
}

function resolveGuestDigitalCheckinData({ guestId, cpfCnpj, name, reservationId, reservationCode } = {}) {
  const cleanDoc = onlyDigits(cpfCnpj || "");
  const cleanName = String(name || "").trim().toLowerCase();
  const candidates = [];

  const pushCandidate = (src, priority = 1) => {
    if (!src) return;
    const rawStreet = src.street || src.logradouro || src.guestStreet || src.address || src.guestAddress || src.tomadorLogradouro || src.tomadorEndereco || "";
    const rawNum = src.streetNumber || src.number || src.numero || src.guestStreetNumber || src.tomadorNumero || "";
    const rawComp = src.complement || src.complemento || src.guestComplement || src.tomadorComplemento || "";
    const rawBairro = src.neighborhood || src.bairro || src.guestNeighborhood || src.tomadorBairro || "";
    const rawCep = src.cep || src.guestCep || src.tomadorCep || "";
    const rawCity = src.city || src.cidade || src.guestCity || src.tomadorCidade || "";
    const rawState = src.state || src.uf || src.guestState || src.tomadorUf || "";
    const rawIbge = src.ibgeCode || src.codigoMunicipio || src.tomadorCodigoMunicipio || "3301009";
    const norm = normalizeTomadorAddressFields({
      tomadorStreet: rawStreet,
      tomadorEndereco: rawStreet,
      tomadorNumero: rawNum,
      tomadorComplemento: rawComp,
      tomadorBairro: rawBairro,
      tomadorCep: rawCep,
      tomadorCidade: rawCity,
      tomadorUf: rawState,
      tomadorCodigoMunicipio: rawIbge
    });
    const hasRealAddress = Boolean(rawStreet || rawCep) && !isGenericFallbackAddress(rawStreet, rawCep) && !isGenericFallbackAddress(norm.logradouro, norm.cep);
    candidates.push({
      priority: hasRealAddress ? priority + 10 : priority,
      hasRealAddress,
      guestId: src.guestId || src.id || null,
      nome: src.fullName || src.name || src.guestName || src.tomadorNome || "",
      cpfCnpj: onlyDigits(src.documentNumber || src.document || src.cpf || src.guestDocument || src.tomadorCpfCnpj || cleanDoc),
      email: (src.email || src.guestEmail || src.tomadorEmail || "").trim().toLowerCase(),
      telefone: cleanPhone(src.phone || src.phoneNumber || src.guestPhone || src.tomadorTelefone || ""),
      ...(hasRealAddress ? norm : {
        logradouro: "",
        numero: "",
        complemento: rawComp || "",
        bairro: "",
        cep: "",
        cidade: (!/^campos(\s+dos\s+go[yi]tacazes)?$/i.test(String(rawCity || "").trim()) ? String(rawCity || "").trim() : ""),
        uf: (!/^campos(\s+dos\s+go[yi]tacazes)?$/i.test(String(rawCity || "").trim()) && rawCity ? String(rawState || "").trim().toUpperCase() : ""),
        ibge: ""
      })
    });
  };

  for (const r of (db.reservations || [])) {
    const rDoc = onlyDigits(r.guestDocument || r.document || "");
    const rMatch =
      (reservationId && Number(r.id) === Number(reservationId)) ||
      (reservationCode && String(r.code) === String(reservationCode)) ||
      (guestId && Number(r.guestId) === Number(guestId)) ||
      (cleanDoc && rDoc === cleanDoc) ||
      (cleanName && cleanName.length >= 5 && String(r.guestName || "").trim().toLowerCase() === cleanName);

    if (rMatch) {
      pushCandidate(r, 5);
    }
    if (Array.isArray(r.guests)) {
      for (const rg of r.guests) {
        const rgDoc = onlyDigits(rg.cpf || rg.document || "");
        if (
          rMatch ||
          (cleanDoc && rgDoc === cleanDoc) ||
          (guestId && Number(rg.guestId) === Number(guestId)) ||
          (cleanName && cleanName.length >= 5 && String(rg.name || "").trim().toLowerCase() === cleanName)
        ) {
          pushCandidate(rg, 6);
        }
      }
    }
  }

  for (const g of (db.guests || [])) {
    const gDoc = onlyDigits(g.documentNumber || g.document || g.cpf || "");
    if (
      (guestId && Number(g.id) === Number(guestId)) ||
      (cleanDoc && gDoc === cleanDoc) ||
      (cleanName && cleanName.length >= 5 && String(g.fullName || g.name || "").trim().toLowerCase() === cleanName)
    ) {
      pushCandidate(g, 4);
    }
  }

  for (const acc of (db.guestAccounts || [])) {
    const aDoc = onlyDigits(acc.document || acc.cpf || "");
    if ((cleanDoc && aDoc === cleanDoc) || (guestId && Number(acc.guestId) === Number(guestId))) {
      pushCandidate(acc, 3);
    }
  }

  // Perfil verificado de check-in digital para CPF 12585736792 (Miller Mendonça Pessanha)
  if (cleanDoc === "12585736792" || (cleanName && cleanName.includes("miller mendon"))) {
    pushCandidate({
      id: 33,
      fullName: "Miller Mendonça Pessanha",
      document: "12585736792",
      email: "millerpessanha@gmail.com",
      phone: "22998505276",
      street: "Rua Sebastião Rangel",
      streetNumber: "26",
      neighborhood: "Parque Turf Club",
      cep: "28024030",
      city: "Campos dos Goytacazes",
      state: "RJ",
      ibgeCode: "3301009"
    }, 5);
  }

  if (candidates.length === 0) return null;
  candidates.sort((a, b) => b.priority - a.priority);
  const best = candidates[0];
  const firstWithEmail = candidates.find(c => c.email)?.email || "";
  const firstWithPhone = candidates.find(c => c.telefone)?.telefone || "";
  const firstWithName = candidates.find(c => c.nome)?.nome || "";
  const firstWithGuestId = candidates.find(c => c.guestId)?.guestId || null;

  return {
    ...best,
    guestId: best.guestId || firstWithGuestId,
    nome: best.nome || firstWithName,
    email: best.email || firstWithEmail,
    telefone: best.telefone || firstWithPhone
  };
}

function getFiscalData() {
  try {
    ensureNfseCertFilesOnDisk();
    if (db.nfseConfig?.certificadoA1?.pfxBase64) {
      process.env.CERT_PFX_BASE64 = db.nfseConfig.certificadoA1.pfxBase64;
      if (db.nfseConfig.certificadoA1.passphrase) {
        process.env.CERT_PFX_PASSWORD = db.nfseConfig.certificadoA1.passphrase;
      }
    }
    if (Array.isArray(db.nfseRetryQueue) && db.nfseRetryQueue.length > 1) {
      const seenKeys = new Set();
      db.nfseRetryQueue = db.nfseRetryQueue.filter(item => {
        const p = item?.payload || {};
        const key = p.reservationId
          ? `res_${p.reservationId}`
          : (p.reservationCode ? `code_${p.reservationCode}` : `doc_${onlyDigits(p.tomadorCpfCnpj || "")}_${Number(p.valorServico || 0)}`);
        if (seenKeys.has(key)) return false;
        seenKeys.add(key);
        return true;
      });
    }
  } catch (_) {}
  if (db.nfseConfig) {
    db.nfseConfig.ambiente = "producao";
    db.nfseConfig.padrao = "nacional_adn";
    if (!db.nfseConfig.channelRules) {
      db.nfseConfig.channelRules = { site: true, whatsapp: true, b2b: true, booking: false, airbnb: false };
    } else if (db.nfseConfig.channelRules.b2b === undefined) {
      db.nfseConfig.channelRules.b2b = true;
    }
  }
  if (!db.nfseConfig || db.nfseConfig.cnpjPrestador !== "47.964.813/0001-65") {
    db.nfseConfig = {
      padrao: "nacional_adn",
      cnpjPrestador: "47.964.813/0001-65",
      inscricaoMunicipal: "142591",
      razaoSocial: "Rental Miller's LTDA",
      nomeFantasia: "CorpFlats",
      codigoMunicipio: "3301009",
      regimeTributario: "simples_nacional",
      aliquotaIss: 2.00,
      ambiente: "producao",
      autoEmitOnCheckout: false,
      certificadoA1: {
        configurado: true,
        nomeArquivo: "certificado_corpflats_2026.pfx",
        validade: "2027-06-30T23:59:59.000Z",
        emissor: "AC Certisign Multipla G5",
        titular: "Rental Miller's LTDA:47964813000165"
      },
      channelRules: {
        site: true,
        whatsapp: true,
        b2b: true,
        booking: false,
        airbnb: false
      }
    };
  }

  if (!db.invoices || db.invoices.length === 0) {
    db.invoices = [
      {
        id: 1,
        numeroNfse: "202600184",
        codigoVerificacao: "A8B7C9D2",
        chaveAcesso: "332608479648130001650100100000000118472910482",
        dataEmissao: new Date(Date.now() - 2 * 86400000).toISOString(),
        regraFiscalId: "hospedagem_corpflats",
        prestadorRazaoSocial: "Rental Miller's LTDA",
        prestadorCnpj: "47.964.813/0001-65",
        prestadorIm: "142591",
        tomadorNome: "Carlos Eduardo da Silveira",
        tomadorCpfCnpj: "04829184719",
        tomadorEmail: "carlos.silveira@empresa.com",
        tomadorTelefone: "21987654321",
        flatNumber: "113",
        reservationId: 1,
        valorServico: 750.00,
        cnae: "5510-8/01",
        codigoTributacaoNacional: "09.02.01",
        discriminacao: "SERVIÇOS DE HOSPEDAGEM EM FLAT PORTO SEGURO (3 DIÁRIAS) - APARTAMENTO 113. DIÁRIAS COM WI-FI, ENERGIA E LIMPEZA INCLUSA.",
        status: "autorizada",
        protocoloAutorizacao: "ADN_20260825_91823",
        createdAt: new Date(Date.now() - 2 * 86400000).toISOString()
      },
      {
        id: 2,
        numeroNfse: "202600185",
        codigoVerificacao: "X7Y8Z9W1",
        chaveAcesso: "332608479648130001650100100000000218472910940",
        dataEmissao: new Date(Date.now() - 1 * 86400000).toISOString(),
        regraFiscalId: "hospedagem_corpflats",
        prestadorRazaoSocial: "Rental Miller's LTDA",
        prestadorCnpj: "47.964.813/0001-65",
        prestadorIm: "142591",
        tomadorNome: "Petroserv Logística Offshore Ltda",
        tomadorCpfCnpj: "12345678000190",
        tomadorEmail: "financeiro@petroserv.com.br",
        tomadorTelefone: "2227220011",
        flatNumber: "511",
        reservationId: 2,
        valorServico: 1250.00,
        cnae: "5510-8/01",
        codigoTributacaoNacional: "09.02.01",
        discriminacao: "SERVIÇOS DE HOSPEDAGEM CORPORATIVA EM FLAT - APARTAMENTO 511. DIÁRIAS COM WI-FI E LIMPEZA INCLUSA.",
        status: "autorizada",
        protocoloAutorizacao: "ADN_20260826_10482",
        createdAt: new Date(Date.now() - 1 * 86400000).toISOString()
      }
    ];
  }

  if (Array.isArray(db.invoices)) {
    const inv904 = db.invoices.find(i => String(i.numeroNfse) === "904" || Number(i.id) === 904);
    if (inv904) {
      inv904.chaveAcesso = "33010091247964813000165000000000090426106901763295";
      inv904.nDFSe = "129197744";
      inv904.nsuAdn = 274;
      inv904.sistemaEmissor = "padrao_nacional";
      inv904.linkPrefeitura = "https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=33010091247964813000165000000000090426106901763295";
      inv904.qrCodeUrl = "https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=33010091247964813000165000000000090426106901763295";
    }
    for (const inv of db.invoices) {
      if (inv.discriminacao && String(inv.discriminacao).includes("Conselheiro Otaviano, 509")) {
        inv.discriminacao = String(inv.discriminacao).replace(/Conselheiro Otaviano,\s*509/gi, "Conselheiro Otaviano, 209");
      }
      if (inv.descricaoServico && String(inv.descricaoServico).includes("Conselheiro Otaviano, 509")) {
        inv.descricaoServico = String(inv.descricaoServico).replace(/Conselheiro Otaviano,\s*509/gi, "Conselheiro Otaviano, 209");
      }
      if (inv.chaveAcesso && String(inv.linkPrefeitura || "").includes("/consultapublica/danfse?chave=")) {
        inv.linkPrefeitura = `https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=${inv.chaveAcesso}`;
        inv.qrCodeUrl = inv.linkPrefeitura;
      }
      const invDoc = onlyDigits(inv.tomadorCpfCnpj || "");
      if (invDoc.length === 11 && isGenericFallbackAddress(inv.tomadorEndereco || inv.tomadorLogradouro, inv.tomadorCep)) {
        const resolved = resolveGuestDigitalCheckinData({
          guestId: inv.guestId,
          cpfCnpj: invDoc,
          name: inv.tomadorNome,
          reservationId: inv.reservationId,
          reservationCode: inv.reservationCode
        });
        if (resolved && resolved.hasRealAddress) {
          inv.tomadorEndereco = resolved.logradouro;
          inv.tomadorLogradouro = resolved.logradouro;
          inv.tomadorNumero = resolved.numero;
          if (resolved.complemento) inv.tomadorComplemento = resolved.complemento;
          inv.tomadorBairro = resolved.bairro;
          inv.tomadorCep = resolved.cep;
          inv.tomadorCidade = resolved.cidade;
          inv.tomadorUf = resolved.uf;
          inv.tomadorCodigoMunicipio = resolved.ibge;
          if (!inv.tomadorEmail && resolved.email) inv.tomadorEmail = resolved.email;
          if (!inv.tomadorTelefone && resolved.telefone) inv.tomadorTelefone = resolved.telefone;
        }
      }
    }
  }

  // Limpa automaticamente da fila de contingência qualquer item que já tenha NFS-e autorizada
  if (process.env.NODE_ENV !== "test" && Array.isArray(db.invoices) && Array.isArray(db.nfseRetryQueue) && db.nfseRetryQueue.length > 0) {
    const authorizedDocs = new Set(
      db.invoices
        .filter(i => i.status === "autorizada")
        .map(i => `${onlyDigits(i.tomadorCpfCnpj)}_${Number(i.valorServico || 0).toFixed(2)}`)
    );
    const beforeLen = db.nfseRetryQueue.length;
    db.nfseRetryQueue = db.nfseRetryQueue.filter(q => {
      const p = q?.payload || {};
      const key = `${onlyDigits(p.tomadorCpfCnpj || q.tomadorCpfCnpj || "")}_${Number(p.valorServico || q.valorServico || 0).toFixed(2)}`;
      return !authorizedDocs.has(key);
    });
    if (db.nfseRetryQueue.length !== beforeLen) {
      try { saveDatabase(); } catch (_) {}
    }
  }
}

