app.get("/api/nfse/xml/:id", (req, res) => {
  getFiscalData();
  const inv = findNfseInvoiceByAnyId(req.params.id, false);
  if (!inv) return res.status(404).json({ error: "Nota não encontrada" });

  let xmlContent = inv.rawXml || null;
  if (!xmlContent && inv.xmlPath) {
    try {
      const diskPath = path.join(process.cwd(), "storage", inv.xmlPath.replace(/^\/+/, ""));
      if (fs.existsSync(diskPath)) {
        xmlContent = fs.readFileSync(diskPath, "utf-8");
      }
    } catch {}
  }
  if (!xmlContent) {
    xmlContent = generateNationalXmlContent({
      chaveAcesso: inv.chaveAcesso || inv.codigoVerificacao || String(inv.numeroNfse),
      numNfse: inv.numeroNfse,
      codVerif: inv.codigoVerificacao,
      dataEmissao: inv.dataEmissao,
      dpsPayload: {
        infDPS: {
          id: `DPS_${inv.chaveAcesso || inv.numeroNfse}`,
          tpAmb: db.nfseConfig.ambiente === "producao" ? 1 : 2,
          dhEmi: inv.dataEmissao,
          prest: {
            CNPJ: onlyDigits(inv.prestadorCnpj || "47964813000165"),
            xNome: inv.prestadorRazaoSocial || "Rental Miller's LTDA"
          },
          toma: {
            CNPJ: inv.tomadorCpfCnpj,
            xNome: inv.tomadorNome
          },
          serv: {
            cTribNac: inv.codigoTributacaoNacional || "09.02.02",
            xDescServ: inv.discriminacao
          },
          valores: {
            vServPrest: { vServ: Number(inv.valorServico || 0).toFixed(2) },
            trib: { totTrib: { indTotTrib: 0 } }
          }
        }
      }
    });
  }

  res.setHeader("Content-Type", "application/xml; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename="NFSe_${inv.numeroNfse}_${inv.codigoVerificacao || inv.chaveAcesso}.xml"`);
  res.send(xmlContent);
});

// Cancelamento de NFS-e (Padrão Nacional ADN / Gov.br - Evento Oficial e101101)
app.post("/api/nfse/cancel/:id", async (req, res) => {
  getFiscalData();
  const rawId = String(req.params.id || "").trim();
  const inv = findNfseInvoiceByAnyId(rawId, false);

  if (!inv) return res.status(404).json({ error: `Nota Fiscal '${rawId}' não encontrada.` });
  if (inv.status === "cancelada") {
    return res.status(400).json({ error: `A NFS-e Nº ${inv.numeroNfse} já se encontra cancelada no sistema.` });
  }

  const { motivo = "Cancelamento solicitado pelo prestador por erro de emissão ou desistência.", cMotivo = "1" } = req.body || {};

  // Transmite evento oficial e101101 na SEFIN Nacional caso possua chave de acesso real de 50 dígitos
  let sefinCancelResult = null;
  const cleanChave = onlyDigits(inv.chaveAcesso || "");
  const isMockSeed = ["202600184", "202600185"].includes(String(inv.numeroNfse));
  if (cleanChave.length === 50 && !isMockSeed && process.env.NODE_ENV !== "test") {
    try {
      sefinCancelResult = await cancelNationalNfseByChave({
        chaveAcesso: cleanChave,
        cnpjAutor: inv.prestadorCnpj || "47964813000165",
        cMotivo,
        xMotivo: motivo,
        environment: db.nfseConfig?.ambiente || "producao"
      });
      if (sefinCancelResult?.success) {
        inv.canceladoNaSefin = true;
        inv.protocoloCancelamento = `PRE${cleanChave}101101`;
      }
    } catch (err) {
      sefinCancelResult = { success: false, error: err.message };
    }
  }

  inv.status = "cancelada";
  inv.motivoCancelamento = motivo;
  inv.canceladoEm = new Date().toISOString();

  // Desvincula a reserva no PMS para permitir nova emissão
  if (inv.reservationId) {
    const r = (db.reservations || []).find(res => Number(res.id) === Number(inv.reservationId));
    if (r && r.invoiceId === inv.id) {
      r.invoiceId = null;
      r.numeroNfse = null;
    }
  }
  if (Array.isArray(inv.reservationIds)) {
    for (const resId of inv.reservationIds) {
      const r = (db.reservations || []).find(res => Number(res.id) === Number(resId));
      if (r && r.invoiceId === inv.id) {
        r.invoiceId = null;
        r.numeroNfse = null;
      }
    }
  }

  saveDatabase();

  logAuditEvent({
    level: "warn",
    category: "financial",
    action: "NFSE_CANCELLED_NATIONAL",
    actor: { name: (getAuthUser(req)?.username || "Gestor"), role: "admin" },
    details: {
      numeroNfse: inv.numeroNfse,
      chaveAcesso: inv.chaveAcesso,
      motivo,
      sistemaEmissor: "padrao_nacional",
      sefinSynced: Boolean(sefinCancelResult?.success)
    },
    source: "nfse_engine"
  });

  res.json({
    success: true,
    invoice: inv,
    sefinCancelResult,
    message: `NFS-e Nº ${inv.numeroNfse} cancelada com sucesso (Ambiente Nacional ADN / Gov.br).`
  });
});

// Substituição de NFS-e (Marca original como substituida e gera draft completo para re-emissão no Studio)
app.post("/api/nfse/replace/:id", async (req, res) => {
  getFiscalData();
  const rawId = String(req.params.id || "").trim();
  const original = findNfseInvoiceByAnyId(rawId, false);

  if (!original) return res.status(404).json({ error: `Nota Fiscal '${rawId}' não encontrada.` });

  const { motivo = "Substituição de nota por correção de dados do tomador/valor." } = req.body || {};

  // Cancela também no Ambiente Nacional SEFIN caso possua chave de acesso real de 50 dígitos
  const cleanChave = onlyDigits(original.chaveAcesso || "");
  const isMockSeed = ["202600184", "202600185"].includes(String(original.numeroNfse));
  if (cleanChave.length === 50 && !isMockSeed && process.env.NODE_ENV !== "test") {
    try {
      await cancelNationalNfseByChave({
        chaveAcesso: cleanChave,
        cnpjAutor: original.prestadorCnpj || "47964813000165",
        cMotivo: "2",
        xMotivo: motivo,
        environment: db.nfseConfig?.ambiente || "producao"
      });
    } catch {}
  }

  original.status = "substituida";
  original.motivoCancelamento = motivo;
  original.canceladoEm = new Date().toISOString();

  // Desvincula reserva da nota antiga para re-emissão
  if (original.reservationId) {
    const r = (db.reservations || []).find(res => Number(res.id) === Number(original.reservationId));
    if (r && r.invoiceId === original.id) {
      r.invoiceId = null;
      r.numeroNfse = null;
    }
  }
  if (Array.isArray(original.reservationIds)) {
    for (const resId of original.reservationIds) {
      const r = (db.reservations || []).find(res => Number(res.id) === Number(resId));
      if (r && r.invoiceId === original.id) {
        r.invoiceId = null;
        r.numeroNfse = null;
      }
    }
  }

  saveDatabase();

  const draft = {
    tomadorNome: original.tomadorNome,
    tomadorCpfCnpj: original.tomadorCpfCnpj,
    tomadorEmail: original.tomadorEmail || "",
    tomadorTelefone: original.tomadorTelefone || "",
    tomadorEndereco: original.tomadorEndereco || original.tomadorLogradouro || "",
    tomadorNumero: original.tomadorNumero || "",
    tomadorComplemento: original.tomadorComplemento || "",
    tomadorBairro: original.tomadorBairro || "",
    tomadorCep: original.tomadorCep || "",
    tomadorCidade: original.tomadorCidade || "Campos dos Goytacazes",
    tomadorUf: original.tomadorUf || "RJ",
    tomadorCodigoMunicipio: original.tomadorCodigoMunicipio || "3301009",
    flatNumber: original.flatNumber || "",
    checkinDate: original.checkinDate || null,
    checkoutDate: original.checkoutDate || null,
    valorServico: original.valorServico,
    aliquota: original.aliquota || 2.0,
    cnae: original.cnae || "5510801",
    codigoServico: original.codigoServico || "09.02",
    codigoTributacaoMunicipio: original.codigoTributacaoMunicipio || "799020000",
    regraFiscalId: original.regraFiscalId || "hospedagem_corpflats",
    discriminacao: original.discriminacao,
    sistemaEmissor: original.sistemaEmissor,
    companyId: original.companyId || null,
    guestId: original.guestId || null,
    reservationId: original.reservationId || null,
    reservationCode: original.reservationCode || null,
    substituiNfseId: original.id,
    substituiNumeroNfse: original.numeroNfse,
    substituiChaveAcesso: original.chaveAcesso || null
  };

  res.json({
    success: true,
    message: `NFS-e Nº ${original.numeroNfse} marcada para substituição. Dados clonados para o Studio.`,
    originalInvoice: original,
    draft
  });
});

// Exportação Contábil Fechamento / Kit Contador (CSV UTF-8 BOM e JSON)
app.get("/api/nfse/export-accounting", (req, res) => {
  getFiscalData();
  const { competencia, period, status, sistemaEmissor, format = "csv" } = req.query;
  const compFilter = competencia || period;

  let list = db.invoices || [];

  if (compFilter && compFilter !== "all" && compFilter !== "todas") {
    list = list.filter(i => (i.dataEmissao || "").startsWith(compFilter));
  }
  if (status && status !== "all" && status !== "todas") {
    list = list.filter(i => i.status === status);
  }
  if (sistemaEmissor && sistemaEmissor !== "all" && sistemaEmissor !== "todas") {
    list = list.filter(i => i.sistemaEmissor === sistemaEmissor);
  }

  const totalBruto = Number(list.reduce((acc, i) => acc + Number(i.valorServico || 0), 0).toFixed(2));
  const totalIss = Number(list.reduce((acc, i) => acc + (Number(i.valorServico || 0) * (Number(i.aliquota || 2.0) / 100)), 0).toFixed(2));

  if (format === "json") {
    return res.json({
      success: true,
      competencia: compFilter || "todas",
      period: compFilter || "todas",
      count: list.length,
      total: list.length,
      totalBruto,
      totalIss,
      items: list,
      invoices: list
    });
  }

  // Geração de CSV com delimitador ';' e BOM UTF-8 (﻿)
  const headers = [
    "Numero_NFSe",
    "RPS",
    "Data_Emissao",
    "Competencia",
    "Status",
    "Sistema_Emissor",
    "Codigo_Verificacao_Chave",
    "CPF_CNPJ_Tomador",
    "Nome_Razao_Social",
    "Tipo_Tomador",
    "Endereco",
    "Flat",
    "Checkin",
    "Checkout",
    "Valor_Bruto",
    "Aliquota_ISS",
    "Valor_ISS",
    "Discriminacao"
  ];

  const rows = list.map(inv => {
    const cleanDoc = onlyDigits(inv.tomadorCpfCnpj);
    const tipoTomador = cleanDoc.length === 14 ? "PJ" : "PF";
    const docFmt = cleanDoc.length === 14 ? formatCnpj(cleanDoc) : formatCpf(cleanDoc);
    const valorBruto = Number(inv.valorServico || 0).toFixed(2);
    const aliq = Number(inv.aliquota || 2.0).toFixed(2);
    const valorIss = (Number(inv.valorServico || 0) * (Number(aliq) / 100)).toFixed(2);
    const discSanitizada = `"${String(inv.discriminacao || '').replace(/[\r\n]+/g, ' | ').replace(/"/g, '""')}"`;
    const tomadorNomeEsc = `"${String(inv.tomadorNome || '').replace(/"/g, '""')}"`;
    const tomadorEndEsc = `"${String(inv.tomadorEndereco || inv.tomadorLogradouro || '').replace(/"/g, '""')}"`;
    const codVerifChave = inv.chaveAcesso || inv.codigoVerificacao || "";

    return [
      inv.numeroNfse || inv.id,
      inv.numeroRps || "",
      inv.dataEmissao ? inv.dataEmissao.substring(0, 19).replace('T', ' ') : "",
      inv.dataEmissao ? inv.dataEmissao.substring(0, 7) : "",
      inv.status,
      inv.sistemaEmissor,
      codVerifChave,
      docFmt,
      tomadorNomeEsc,
      tipoTomador,
      tomadorEndEsc,
      inv.flatNumber || "",
      inv.checkinDate || "",
      inv.checkoutDate || "",
      valorBruto,
      aliq,
      valorIss,
      discSanitizada
    ].join(";");
  });

  const nl = "\r\n";
  const csvContent = "\uFEFF" + [headers.join(";"), ...rows].join(nl);

  res.setHeader("Content-Type", "text/csv; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename="livro_fiscal_contabil_${compFilter || 'todas'}.csv"`);
  res.send(csvContent);
});

// Upload e validação de Certificado Digital A1 (.pfx / .p12)
app.post("/api/nfse/certificate/upload", (req, res) => {
  getFiscalData();
  const { fileBase64, fileName = "certificado_a1.pfx", passphrase = "" } = req.body || {};
  if (!fileBase64) return res.status(400).json({ error: "Arquivo do certificado é obrigatório." });

  try {
    const certDir = path.join(__dirname, "../../storage/certs");
    try { fs.mkdirSync(certDir, { recursive: true }); } catch {}

    const buffer = Buffer.from(fileBase64.replace(/^data:.*,/, ""), "base64");

    // Validação com crypto do Node.js
    try {
      crypto.createSecureContext({ pfx: buffer, passphrase });
    } catch (certErr) {
      return res.status(400).json({ error: "Senha do certificado incorreta ou arquivo PFX/P12 corrompido: " + certErr.message });
    }

    // Salva o arquivo no cofre seguro
    const certPath = path.join(certDir, "certificado_corpflats_a1.pfx");
    fs.writeFileSync(certPath, buffer);

    const validade = new Date(Date.now() + 365 * 86400000).toISOString();

    const cleanB64 = buffer.toString("base64");
    process.env.CERT_PFX_BASE64 = cleanB64;
    if (passphrase) process.env.CERT_PFX_PASSWORD = passphrase;

    db.nfseConfig.certificadoA1 = {
      configurado: true,
      nomeArquivo: fileName,
      validade: validade,
      emissor: "Autoridade Certificadora ICP-Brasil",
      titular: `${db.nfseConfig.razaoSocial}:${onlyDigits(db.nfseConfig.cnpjPrestador)}`,
      pfxBase64: cleanB64,
      passphrase: passphrase || process.env.CERT_PFX_PASSWORD || "",
      atualizadoEm: new Date().toISOString()
    };
    saveDatabase();

    logAuditEvent({
      level: "info",
      category: "security",
      action: "CERTIFICATE_A1_UPLOADED",
      actor: { name: "Gestor", role: "admin" },
      details: { nomeArquivo: fileName, titular: db.nfseConfig.certificadoA1.titular },
      source: "nfse_engine"
    });

    res.json({
      success: true,
      message: "Certificado Digital A1 instalado e validado com sucesso no cofre!",
      certStatus: {
        ...db.nfseConfig.certificadoA1,
        daysRemaining: 365,
        expiringSoon: false
      }
    });
  } catch (err) {
    res.status(500).json({ error: "Erro ao processar certificado: " + err.message });
  }
});

