// Sincroniza DF-e de NFS-e emitidas no ADN Nacional (https://adn.nfse.gov.br/contribuintes/DFe)
app.post("/api/nfse/adn-sync", async (req, res) => {
  getFiscalData();
  try {
    const startNsu = Number(req.body?.nsu ?? 270);
    const result = await fetchNationalDfeFromAdn(startNsu, "producao");
    const lote = Array.isArray(result.response?.LoteDFe) ? result.response.LoteDFe : [];
    let syncedCount = 0;
    for (const item of lote) {
      if (item.TipoDocumento === "EVENTO" && item.xmlDecoded && item.xmlDecoded.includes("<e101101>")) {
        const targetInv = (db.invoices || []).find(i => i.chaveAcesso === item.ChaveAcesso);
        if (targetInv && targetInv.status !== "cancelada") {
          const xMot = (item.xmlDecoded.match(/<xMotivo>([\s\S]*?)<\/xMotivo>/) || [])[1] || "Cancelamento registrado no ADN Nacional";
          targetInv.status = "cancelada";
          targetInv.motivoCancelamento = xMot;
          targetInv.canceladoNaSefin = true;
          syncedCount++;
        }
        continue;
      }
      if (item.TipoDocumento !== "NFSE" || !item.xmlDecoded) continue;
      const xml = item.xmlDecoded;
      const nNfse = (xml.match(/<nNFSe>(\d+)<\/nNFSe>/) || [])[1];
      const nDfse = (xml.match(/<nDFSe>(\d+)<\/nDFSe>/) || [])[1];
      const dhEmi = (xml.match(/<dhProc>([^<]+)<\/dhProc>/) || xml.match(/<dhEmi>([^<]+)<\/dhEmi>/) || [])[1];
      const vServ = Number((xml.match(/<vServ>([^<]+)<\/vServ>/) || [])[1] || 0);
      const tomaBlock = (xml.match(/<toma>([\s\S]*?)<\/toma>/) || [])[1] || "";
      const tomaDoc = (tomaBlock.match(/<(?:CPF|CNPJ)>(\d+)<\/(?:CPF|CNPJ)>/) || [])[1] || "";
      const tomaNome = (tomaBlock.match(/<xNome>([^<]+)<\/xNome>/) || [])[1] || "Hóspede";
      const xDescServ = (xml.match(/<xDescServ>([\s\S]*?)<\/xDescServ>/) || [])[1] || "";
      if (!nNfse) continue;

      const existing = (db.invoices || []).find(i =>
        i.chaveAcesso === item.ChaveAcesso ||
        (String(i.numeroNfse) === String(nNfse) && (!i.chaveAcesso || i.chaveAcesso === item.ChaveAcesso))
      );
      if (existing) {
        existing.chaveAcesso = item.ChaveAcesso;
        existing.nDFSe = nDfse || existing.nDFSe;
        existing.nsuAdn = item.NSU;
        existing.rawXml = xml;
        existing.sistemaEmissor = "padrao_nacional";
        existing.linkPrefeitura = `https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=${item.ChaveAcesso}`;
        existing.qrCodeUrl = `https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=${item.ChaveAcesso}`;
      } else {
        const maxInvId = db.invoices && db.invoices.length > 0 ? Math.max(...db.invoices.map(i => Number(i.id || 0))) : 900;
        db.invoices.unshift({
          id: Number(nNfse) > 100 ? Number(nNfse) : maxInvId + 1,
          numeroRps: Number(nNfse),
          numeroNfse: String(nNfse),
          numeroNota: String(nNfse),
          nDFSe: nDfse || null,
          nsuAdn: item.NSU,
          codigoVerificacao: item.ChaveAcesso.slice(-9),
          chaveAcesso: item.ChaveAcesso,
          protocoloAutorizacao: `ADN_NSU_${item.NSU}`,
          dataEmissao: dhEmi || item.DataHoraGeracao || new Date().toISOString(),
          sistemaEmissor: "padrao_nacional",
          municipioEmissor: "Campos dos Goytacazes - RJ (3301009)",
          regraFiscalId: "hospedagem_corpflats",
          prestadorRazaoSocial: "Rental Miller's LTDA",
          prestadorCnpj: "47.964.813/0001-65",
          prestadorIm: "142591",
          tomadorNome: toTitleCase(tomaNome),
          tomadorCpfCnpj: tomaDoc,
          valorServico: vServ,
          aliquota: 2.0,
          cnae: "5510801",
          codigoServico: "09.02",
          codigoTributacaoMunicipio: "090202",
          discriminacao: xDescServ,
          status: "autorizada",
          rawXml: xml,
          linkPrefeitura: `https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=${item.ChaveAcesso}`,
          qrCodeUrl: `https://www.nfse.gov.br/ConsultaPublica?tpc=1&chave=${item.ChaveAcesso}`,
          danfseUrl: `/api/nfse/danfse/${nNfse}`,
          pdfUrl: `/api/nfse/pdf/${nNfse}`,
          createdAt: dhEmi || new Date().toISOString()
        });
      }
      syncedCount++;
    }
    if (syncedCount > 0 && process.env.NODE_ENV !== "test") {
      saveDatabase();
    }
    res.json({
      success: true,
      syncedCount,
      totalLote: lote.length,
      maxNsu: lote.length > 0 ? Math.max(...lote.map(i => Number(i.NSU || 0))) : startNsu
    });
  } catch (err) {
    res.status(502).json({ success: false, error: err.message });
  }
});

// Helper central de disparo da NFS-e (PDF + link) no WhatsApp com bypass da trava de teste (exclusivo NFS-e)
async function dispatchNfseInvoiceWhatsApp(inv, opts = {}) {
  if (!inv) return { success: false, sent: false, pdfSent: false };

  const linkedRes = Array.isArray(db.reservations)
    ? db.reservations.find(r =>
        r && (
          (inv.reservationId && Number(r.id) === Number(inv.reservationId)) ||
          (inv.reservationCode && String(r.code) === String(inv.reservationCode))
        )
      )
    : null;
  const linkedGuest = Array.isArray(db.guests)
    ? db.guests.find(g =>
        g && (
          (inv.guestId && Number(g.id) === Number(inv.guestId)) ||
          (linkedRes?.guestId && Number(g.id) === Number(linkedRes.guestId)) ||
          (inv.guestName && String(g.fullName || g.name || "").trim().toLowerCase() === String(inv.guestName).trim().toLowerCase())
        )
      )
    : null;

  const rawPhone =
    opts.phone ||
    (!inv.nfHideFromGuest && (inv.guestPhone || linkedRes?.guestPhone || linkedRes?.guests?.[0]?.phone || linkedGuest?.phone)) ||
    inv.tomadorTelefone ||
    linkedRes?.guestPhone ||
    linkedGuest?.phone ||
    "";
  const cleanPhoneNum = onlyDigits(rawPhone);
  const displayRecipientName = (!inv.nfHideFromGuest && (inv.guestName || linkedRes?.guestName || linkedGuest?.fullName || linkedGuest?.name)) || inv.tomadorNome || "Hóspede";
  const firstName = String(displayRecipientName).trim().split(/\s+/)[0] || "Hóspede";
  const numNota = String(inv.numeroNfse || inv.numeroNota || inv.id);
  const danfseUrl = `https://corpflats.com.br/api/nfse/danfse/${numNota}`;
  const pdfUrl = `https://corpflats.com.br/api/nfse/pdf/${numNota}`;
  const fileName = `NFSe_${numNota}_CorpFlats.pdf`;

  const captionText =
    `Olá, *${firstName}*! Tudo bem? 🧾\n\n` +
    `Segue em anexo o *PDF oficial da sua Nota Fiscal de Serviços Eletrônica (NFS-e Padrão Nacional Nº ${numNota})* — *CorpFlats (Rental Miller's LTDA)*${inv.flatNumber ? ` referente ao Flat ${inv.flatNumber}` : ""}.\n\n` +
    `🔑 *Chave de Acesso Nacional (Gov.br):*\n${inv.chaveAcesso || ""}\n\n` +
    `📄 *Link direto do PDF:* ${pdfUrl}\n\n` +
    `Agradecemos a sua preferência e esperamos você de volta em breve! ✨`;

  const whatsappUrl = `https://wa.me/${cleanPhoneNum.startsWith("55") ? cleanPhoneNum : `55${cleanPhoneNum}`}?text=${encodeURIComponent(captionText)}`;

  let pdfSent = false;
  let textSent = false;
  let zapiResult = null;
  let pdfBytes = 0;

  try {
    const pdfBuf = await generateNfsePdfBuffer(inv);
    pdfBytes = pdfBuf.length;
    try {
      const vaultDir = path.join(process.cwd(), "storage/invoices_vault");
      fs.mkdirSync(vaultDir, { recursive: true });
      fs.writeFileSync(path.join(vaultDir, fileName), pdfBuf);
    } catch (_) {}

    if (cleanPhoneNum.length >= 10 && opts.sendZapi !== false) {
      const dispatchChannelId = opts.channelId || "reservations";
      const dispatchSenderName = opts.senderName || "CorpFlats";
      const dispatchBypassTest = opts.bypassTestMode !== undefined ? Boolean(opts.bypassTestMode) : true;
      const pdfBase64Uri = `data:application/pdf;base64,${pdfBuf.toString("base64")}`;
      zapiResult = await sendZapiDocument(db.zapiConfig || {}, {
        phone: cleanPhoneNum,
        document: pdfBase64Uri,
        fileName,
        caption: captionText,
        channelId: dispatchChannelId,
        recipientRole: "guest",
        triggerEvent: "nfse_pdf_dispatch",
        bypassTestMode: dispatchBypassTest,
        db
      });
      pdfSent = Boolean(zapiResult?.success);

      if (!pdfSent && typeof sendZapiMessage === "function") {
        zapiResult = await sendZapiMessage(db.zapiConfig || {}, {
          phone: cleanPhoneNum,
          message: captionText,
          channelId: dispatchChannelId,
          recipientRole: "guest",
          triggerEvent: "nfse_dispatch",
          bypassTestMode: dispatchBypassTest,
          db
        });
        textSent = Boolean(zapiResult?.success);
      }

      if ((pdfSent || textSent) && typeof appendMessageToConversation === "function") {
        appendMessageToConversation(db, {
          phone: cleanPhoneNum,
          senderName: dispatchSenderName,
          fromMe: true,
          text: captionText,
          type: pdfSent ? "document" : "text",
          documentName: pdfSent ? fileName : undefined,
          documentUrl: pdfSent ? `/api/nfse/pdf/${numNota}` : undefined,
          triggerEvent: "nfse_pdf_dispatch",
          reservationCode: inv.reservationCode || linkedRes?.code || null,
          status: "delivered",
          timestamp: new Date().toISOString()
        });
      }
    }
  } catch (err) {
    console.warn("[NFS-e WhatsApp PDF Dispatch Error]:", err.message);
  }

  return {
    success: true,
    sent: Boolean(pdfSent || textSent),
    pdfSent,
    textSent,
    phone: cleanPhoneNum,
    fileName,
    pdfBytes,
    pdfUrl,
    danfseUrl,
    whatsappUrl,
    zapiResult
  };
}

// Disparo Integrado do PDF Oficial da NFS-e no WhatsApp (Z-API send-document/pdf + Link Fallback)
app.post("/api/nfse/whatsapp/:id", async (req, res) => {
  getFiscalData();
  const inv = findNfseInvoiceByAnyId(req.params.id);
  if (!inv) return res.status(404).json({ error: "Nota não encontrada" });

  const dispatchResult = await dispatchNfseInvoiceWhatsApp(inv, {
    phone: req.body?.phone,
    sendZapi: req.body?.sendZapi
  });

  res.json(dispatchResult);
});

// Lookup CNPJ / CPF publicly via BrasilAPI + MinhaReceita Fallback + Local CRM / Check-in Digital DB
app.get("/api/nfse/lookup-cnpj/:cnpj", async (req, res) => {
  const cnpj = onlyDigits(req.params.cnpj);
  if (cnpj.length === 11) {
    const resolved = resolveGuestDigitalCheckinData({ cpfCnpj: cnpj });
    if (!resolved) return res.status(404).json({ error: "Hóspede não encontrado no cadastro/check-in digital." });
    const healedCpf = await resolveValidCepAndIbge({
      cep: resolved.cep,
      logradouro: resolved.logradouro,
      bairro: resolved.bairro,
      cidade: resolved.cidade,
      uf: resolved.uf,
      codigoMunicipio: resolved.ibge
    });
    const ibgeCpf = healedCpf.codigoMunicipio || resolved.ibge || "3301009";
    return res.json({
      razaoSocial: resolved.nome,
      nome: resolved.nome,
      cpf: cnpj,
      email: resolved.email || "",
      telefone: resolved.telefone || "",
      logradouro: resolved.logradouro || "",
      endereco: resolved.logradouro || "",
      numero: resolved.numero || "",
      complemento: resolved.complemento || "",
      bairro: resolved.bairro || "",
      cep: healedCpf.cep || resolved.cep || "",
      cidade: healedCpf.cidade || resolved.cidade || "Campos dos Goytacazes",
      uf: healedCpf.uf || resolved.uf || "RJ",
      codigoMunicipio: ibgeCpf,
      ibge: ibgeCpf,
      ibgeCode: ibgeCpf,
      guestId: resolved.guestId || null,
      origem: "checkin_digital"
    });
  }
  if (cnpj.length !== 14) return res.status(400).json({ error: "CNPJ inválido. Deve conter 14 dígitos." });

  try {
    const data = await lookupCnpj(cnpj, db);
    if (!data || data.source === "fallback") {
      return res.status(404).json({ error: "CNPJ não encontrado na Receita Federal" });
    }
    const ibge = data.codigoMunicipio || data.ibge || data.ibgeCode || "3301009";
    return res.json({
      ...data,
      razaoSocial: data.razaoSocial,
      nomeFantasia: data.nomeFantasia || data.razaoSocial,
      cnpj,
      cep: data.cep || "",
      endereco: data.logradouro || "",
      logradouro: data.logradouro || "",
      numero: data.numero || "S/N",
      complemento: data.complemento || "",
      bairro: data.bairro || "",
      cidade: data.cidade || "Campos dos Goytacazes",
      municipio: data.cidade || "Campos dos Goytacazes",
      uf: data.uf || "RJ",
      codigoMunicipio: ibge,
      ibge,
      ibgeCode: ibge,
      email: data.email || "",
      telefone: data.telefone || "",
      agencyId: data.agencyId || null,
      companyId: data.companyId || null,
      isAgency: data.entityType === "agency",
      origem: data.source || "receita_federal"
    });
  } catch (err) {
    return res.status(404).json({ error: err.message || "CNPJ não encontrado na Receita Federal" });
  }
});

// Lookup CEP via ViaCEP / BrasilAPI
app.get("/api/lookup-cep/:cep", async (req, res) => {
  const cep = onlyDigits(req.params.cep);
  if (cep.length !== 8) return res.status(400).json({ error: "CEP inválido. Deve conter 8 dígitos." });

  try {
    const data = await lookupCep(cep, db);
    if (!data) return res.status(404).json({ error: "CEP não encontrado" });
    const ibge = data.codigoMunicipio || data.ibge || "3301009";
    res.json({
      cep: data.cep || cep,
      logradouro: data.logradouro || "",
      bairro: data.bairro || "",
      cidade: data.cidade || "",
      localidade: data.cidade || "",
      uf: data.uf || "RJ",
      codigoMunicipio: ibge,
      ibge,
      ibgeCode: ibge,
      enderecoCompleto: `${data.logradouro || ""}, ${data.bairro || ""} - ${data.cidade || ""}/${data.uf || "RJ"}`
    });
  } catch {
    res.status(500).json({ error: "Falha ao consultar CEP" });
  }
});

