app.get(["/api/companies/:id", "/api/pms/companies/:id"], (req, res) => {
  const id = Number(req.params.id);
  const company = (db.companies || []).find(c => Number(c.id) === id);
  if (!company) return res.status(404).json({ error: "Empresa não encontrada" });

  const compCnpj = onlyDigits(company.cnpj || "");
  const reservations = (db.reservations || []).filter(r =>
    (r.companyId && Number(r.companyId) === id) ||
    (compCnpj && onlyDigits(r.companyCnpj || "") === compCnpj) ||
    (company.tradeName && r.companyName && String(r.companyName).toLowerCase().includes(String(company.tradeName).toLowerCase()))
  );
  const resIds = new Set(reservations.map(r => String(r.id)));
  const resCodes = new Set(reservations.map(r => r.code).filter(Boolean));

  const invoices = (db.invoices || []).filter(inv =>
    (inv.companyId && Number(inv.companyId) === id) ||
    (compCnpj && onlyDigits(inv.tomadorCpfCnpj || "") === compCnpj) ||
    (inv.reservationId && resIds.has(String(inv.reservationId))) ||
    (inv.reservationCode && resCodes.has(inv.reservationCode))
  );

  const boletos = (db.boletos || []).filter(b =>
    b && (
      (b.companyId && Number(b.companyId) === id) ||
      (compCnpj && onlyDigits(b.payer?.cpfCnpj || b.payerDocument || "") === compCnpj) ||
      (b.reservationId && resIds.has(String(b.reservationId))) ||
      (b.reservationCode && resCodes.has(b.reservationCode))
    )
  ).map(b => enrichBoletoDynamicStatus(b));

  const guests = (db.guests || []).filter(g =>
    (g.companyId && Number(g.companyId) === id) ||
    reservations.some(r => Number(r.guestId) === Number(g.id))
  );

  const totalRevenue = reservations
    .filter(r => r.status !== "cancelada" && r.status !== "cancelled")
    .reduce((acc, r) => acc + (Number(r.totalAmount) || 0), 0);

  const boletosSummary = computeBoletosSummaryMetrics(boletos);

  res.json({
    ...company,
    company,
    reservations,
    invoices,
    boletos,
    boletosSummary,
    guests,
    metrics: {
      totalReservations: reservations.length,
      invoicesCount: invoices.length,
      boletosCount: boletos.length,
      openBoletosCount: boletos.filter(b => b.status === "aberto" || b.status === "vencido").length,
      openBoletosAmount: Number(boletos.filter(b => b.status === "aberto" || b.status === "vencido").reduce((s, b) => s + (Number(b.amount) || 0), 0).toFixed(2)),
      paidBoletosAmount: Number(boletos.filter(b => b.status === "pago").reduce((s, b) => s + (Number(b.paidAmount || b.amount) || 0), 0).toFixed(2)),
      totalRevenue: Number(totalRevenue.toFixed(2))
    }
  });
});

app.post("/api/companies", (req, res) => {
  if (!db.companies) db.companies = [];
  const {
    corporateName, razaoSocial,
    tradeName, nomeFantasia,
    cnpj,
    stateRegistration = "", inscricaoEstadual = "",
    municipalRegistration = "", inscricaoMunicipal = "",
    financialEmail = "", emailFinanceiro = "", email = "",
    phone = "", telefone = "",
    contactPerson = "", contato = "",
    billingTerms = "", condicaoFaturamento = "",
    companyRole,
    allowsDirectReservations,
    isInvoiceOnly,
    billingEnabled,
    notes = "", observacoes = "",
    address = "", logradouro = "", endereco = "",
    number = "", numero = "",
    complement = "", complemento = "",
    neighborhood = "", bairro = "",
    cep = "",
    city = "", cidade = "", municipio = "",
    state = "", uf = "", estado = "",
    ibgeCode = "", codigoMunicipio = "", codigoIbge = ""
  } = req.body;

  const resolvedCorporateName = (corporateName || razaoSocial || "").trim();
  if (!resolvedCorporateName) {
    return res.status(400).json({ error: "Razão Social é obrigatória." });
  }

  const resolvedTradeName = (tradeName || nomeFantasia || resolvedCorporateName).trim();
  const resolvedCnpj = (cnpj || "Isento / Não informado").trim();
  const resolvedStateReg = (stateRegistration || inscricaoEstadual || "").trim();
  const resolvedMunReg = (municipalRegistration || inscricaoMunicipal || "").trim();
  const resolvedEmail = (financialEmail || emailFinanceiro || email || "").trim();
  const resolvedPhone = (phone || telefone || "").trim();
  const resolvedContact = (contactPerson || contato || "").trim();
  const resolvedAllowsDirect = allowsDirectReservations !== undefined
    ? Boolean(allowsDirectReservations)
    : (companyRole === "invoice_only" || isInvoiceOnly === true ? false : true);
  const resolvedRole = resolvedAllowsDirect ? "booking_partner" : "invoice_only";
  const resolvedBillingEnabled = billingEnabled !== undefined
    ? Boolean(billingEnabled)
    : (resolvedRole === "invoice_only" ? false : true);
  const rawBillingTerms = (billingTerms || condicaoFaturamento || "").trim();
  const resolvedBilling = resolvedBillingEnabled
    ? (rawBillingTerms || `${Number(req.body.defaultBoletoTermDays ?? 28) || 28} dias`)
    : "";
  const resolvedNotes = (notes || observacoes || "").trim();
  const resolvedAddress = (address || logradouro || endereco || "").trim();
  const resolvedNumber = (number || numero || "").trim();
  const resolvedComplement = (complement || complemento || "").trim();
  const resolvedNeighborhood = (neighborhood || bairro || "").trim();
  const rawCep = (cep || "").toString().replace(/\D/g, "");
  const rawCity = (city || cidade || municipio || "Campos dos Goytacazes").trim();
  const rawState = (state || uf || estado || "RJ").trim().toUpperCase();
  const rawIbge = (ibgeCode || codigoMunicipio || codigoIbge || "").trim();
  const inferredCompGeo = inferIbgeAndValidCep({
    cep: rawCep,
    cidade: rawCity,
    uf: rawState,
    codigoMunicipio: rawIbge
  });
  const resolvedCep = rawCep || inferredCompGeo.cep || "";
  const resolvedCity = inferredCompGeo.cidade || rawCity;
  const resolvedState = inferredCompGeo.uf || rawState;
  const resolvedIbge = inferredCompGeo.codigoMunicipio || rawIbge || "3301009";

  // Evita duplicidade se o mesmo CNPJ (14 dígitos) já existir no CRM de Empresas
  const cleanInCnpj = resolvedCnpj.replace(/\D/g, "");
  const existingCompByCnpj = cleanInCnpj.length === 14
    ? db.companies.find(c => String(c?.cnpj || "").replace(/\D/g, "") === cleanInCnpj)
    : null;
  if (existingCompByCnpj) {
    if (resolvedCorporateName) {
      existingCompByCnpj.corporateName = resolvedCorporateName;
      existingCompByCnpj.razaoSocial = resolvedCorporateName;
    }
    if (resolvedTradeName) {
      existingCompByCnpj.tradeName = resolvedTradeName;
      existingCompByCnpj.nomeFantasia = resolvedTradeName;
    }
    if (resolvedEmail) {
      existingCompByCnpj.financialEmail = resolvedEmail;
      existingCompByCnpj.emailFinanceiro = resolvedEmail;
    }
    if (resolvedPhone) {
      existingCompByCnpj.phone = resolvedPhone;
      existingCompByCnpj.telefone = resolvedPhone;
    }
    if (resolvedContact) {
      existingCompByCnpj.contactPerson = resolvedContact;
      existingCompByCnpj.contato = resolvedContact;
    }
    if (resolvedAddress) {
      existingCompByCnpj.address = resolvedAddress;
      existingCompByCnpj.logradouro = resolvedAddress;
      existingCompByCnpj.endereco = resolvedAddress;
    }
    if (resolvedNumber) {
      existingCompByCnpj.number = resolvedNumber;
      existingCompByCnpj.numero = resolvedNumber;
    }
    if (resolvedComplement) {
      existingCompByCnpj.complement = resolvedComplement;
      existingCompByCnpj.complemento = resolvedComplement;
    }
    if (resolvedNeighborhood) {
      existingCompByCnpj.neighborhood = resolvedNeighborhood;
      existingCompByCnpj.bairro = resolvedNeighborhood;
    }
    if (resolvedCep) existingCompByCnpj.cep = resolvedCep;
    if (resolvedCity) {
      existingCompByCnpj.city = resolvedCity;
      existingCompByCnpj.cidade = resolvedCity;
    }
    if (resolvedState) {
      existingCompByCnpj.state = resolvedState;
      existingCompByCnpj.uf = resolvedState;
    }
    if (resolvedIbge) {
      existingCompByCnpj.ibgeCode = resolvedIbge;
      existingCompByCnpj.codigoMunicipio = resolvedIbge;
    }
    if (resolvedNotes && !existingCompByCnpj.notes) existingCompByCnpj.notes = resolvedNotes;
    if (resolvedAllowsDirect && existingCompByCnpj.allowsDirectReservations === false) {
      existingCompByCnpj.allowsDirectReservations = true;
      existingCompByCnpj.companyRole = "booking_partner";
      existingCompByCnpj.isInvoiceOnly = false;
    }
    if (resolvedBillingEnabled && existingCompByCnpj.billingEnabled === false) {
      existingCompByCnpj.billingEnabled = true;
      if (!existingCompByCnpj.billingTerms) existingCompByCnpj.billingTerms = resolvedBilling;
    }
    if (resolvedBillingEnabled) {
      applyCrmBillingConfigFields(existingCompByCnpj, req.body);
    }
    existingCompByCnpj.updatedAt = new Date().toISOString();
    saveDatabase("company_reused_" + existingCompByCnpj.id);
    return res.status(200).json(existingCompByCnpj);
  }

  const newCompany = {
    id: db.companies.length > 0 ? Math.max(...db.companies.map(c => Number(c.id) || 0)) + 1 : 1,
    corporateName: resolvedCorporateName,
    razaoSocial: resolvedCorporateName,
    tradeName: resolvedTradeName,
    nomeFantasia: resolvedTradeName,
    cnpj: resolvedCnpj,
    stateRegistration: resolvedStateReg,
    inscricaoEstadual: resolvedStateReg,
    municipalRegistration: resolvedMunReg,
    inscricaoMunicipal: resolvedMunReg,
    financialEmail: resolvedEmail,
    emailFinanceiro: resolvedEmail,
    phone: resolvedPhone,
    telefone: resolvedPhone,
    contactPerson: resolvedContact,
    contato: resolvedContact,
    companyRole: resolvedRole,
    allowsDirectReservations: resolvedAllowsDirect,
    isInvoiceOnly: !resolvedAllowsDirect,
    billingEnabled: resolvedBillingEnabled,
    billingTerms: resolvedBilling,
    notes: resolvedNotes,
    address: resolvedAddress,
    logradouro: resolvedAddress,
    endereco: resolvedAddress,
    number: resolvedNumber,
    numero: resolvedNumber,
    complement: resolvedComplement,
    complemento: resolvedComplement,
    neighborhood: resolvedNeighborhood,
    bairro: resolvedNeighborhood,
    cep: resolvedCep,
    city: resolvedCity,
    cidade: resolvedCity,
    state: resolvedState,
    uf: resolvedState,
    ibgeCode: resolvedIbge,
    codigoMunicipio: resolvedIbge,
    createdAt: new Date().toISOString()
  };

  applyCrmBillingConfigFields(newCompany, req.body);

  db.companies.push(newCompany);
  saveDatabase("company_created_" + newCompany.id);
  logAuditEvent({
    level: "info",
    category: "company",
    action: "COMPANY_CREATED",
    actor: req.user || { name: "Usuário", role: "admin" },
    details: { companyId: newCompany.id, corporateName: newCompany.corporateName, tradeName: newCompany.tradeName, cnpj: newCompany.cnpj, fullCompany: newCompany },
    source: "CRM Empresas"
  });
  res.status(201).json(newCompany);
});

const handleUpdateCompany = (req, res) => {
  const id = Number(req.params.id);
  if (!db.companies) db.companies = [];
  const company = db.companies.find(c => c.id === id);
  if (!company) return res.status(404).json({ error: "Empresa não encontrada" });

  const b = req.body;
  if (b.corporateName !== undefined || b.razaoSocial !== undefined) {
    const val = (b.corporateName ?? b.razaoSocial ?? "").trim();
    company.corporateName = val;
    company.razaoSocial = val;
  }
  if (b.tradeName !== undefined || b.nomeFantasia !== undefined) {
    const val = (b.tradeName ?? b.nomeFantasia ?? "").trim();
    company.tradeName = val;
    company.nomeFantasia = val;
  }
  if (b.cnpj !== undefined) company.cnpj = b.cnpj.trim();
  if (b.stateRegistration !== undefined || b.inscricaoEstadual !== undefined) {
    const val = (b.stateRegistration ?? b.inscricaoEstadual ?? "").trim();
    company.stateRegistration = val;
    company.inscricaoEstadual = val;
  }
  if (b.municipalRegistration !== undefined || b.inscricaoMunicipal !== undefined) {
    const val = (b.municipalRegistration ?? b.inscricaoMunicipal ?? "").trim();
    company.municipalRegistration = val;
    company.inscricaoMunicipal = val;
  }
  if (b.financialEmail !== undefined || b.emailFinanceiro !== undefined || b.email !== undefined) {
    const val = (b.financialEmail ?? b.emailFinanceiro ?? b.email ?? "").trim();
    company.financialEmail = val;
    company.emailFinanceiro = val;
  }
  if (b.phone !== undefined || b.telefone !== undefined) {
    const val = (b.phone ?? b.telefone ?? "").trim();
    company.phone = val;
    company.telefone = val;
  }
  if (b.contactPerson !== undefined || b.contato !== undefined) {
    const val = (b.contactPerson ?? b.contato ?? "").trim();
    company.contactPerson = val;
    company.contato = val;
  }
  if (b.allowsDirectReservations !== undefined || b.companyRole !== undefined || b.isInvoiceOnly !== undefined) {
    const allowsDirect = b.allowsDirectReservations !== undefined
      ? Boolean(b.allowsDirectReservations)
      : (b.companyRole === "invoice_only" || b.isInvoiceOnly === true ? false : true);
    company.allowsDirectReservations = allowsDirect;
    company.companyRole = allowsDirect ? "booking_partner" : "invoice_only";
    company.isInvoiceOnly = !allowsDirect;
  }
  if (b.billingEnabled !== undefined) {
    company.billingEnabled = Boolean(b.billingEnabled);
  }
  if (b.billingTerms !== undefined || b.condicaoFaturamento !== undefined) {
    const val = (b.billingTerms ?? b.condicaoFaturamento ?? "").trim();
    company.billingTerms = company.billingEnabled === false ? "" : val;
  } else if (b.billingEnabled === false) {
    company.billingTerms = "";
  } else if (b.billingEnabled === true && !company.billingTerms) {
    company.billingTerms = `${Number(b.defaultBoletoTermDays ?? company.defaultBoletoTermDays ?? 28) || 28} dias`;
  }
  if (b.notes !== undefined || b.observacoes !== undefined) {
    const val = (b.notes ?? b.observacoes ?? "").trim();
    company.notes = val;
  }
  if (b.address !== undefined || b.logradouro !== undefined || b.endereco !== undefined) {
    const val = (b.address ?? b.logradouro ?? b.endereco ?? "").trim();
    company.address = val;
    company.logradouro = val;
    company.endereco = val;
  }
  if (b.number !== undefined || b.numero !== undefined) {
    const val = (b.number ?? b.numero ?? "").trim();
    company.number = val;
    company.numero = val;
  }
  if (b.complement !== undefined || b.complemento !== undefined) {
    const val = (b.complement ?? b.complemento ?? "").trim();
    company.complement = val;
    company.complemento = val;
  }
  if (b.neighborhood !== undefined || b.bairro !== undefined) {
    const val = (b.neighborhood ?? b.bairro ?? "").trim();
    company.neighborhood = val;
    company.bairro = val;
  }
  if (b.cep !== undefined) {
    company.cep = String(b.cep || "").replace(/\D/g, "");
  }
  if (b.city !== undefined || b.cidade !== undefined || b.municipio !== undefined) {
    const val = (b.city ?? b.cidade ?? b.municipio ?? "").trim();
    company.city = val;
    company.cidade = val;
  }
  if (b.state !== undefined || b.uf !== undefined || b.estado !== undefined) {
    const val = String(b.state ?? b.uf ?? b.estado ?? "").trim().toUpperCase();
    company.state = val;
    company.uf = val;
  }
  if (b.ibgeCode !== undefined || b.codigoMunicipio !== undefined || b.codigoIbge !== undefined) {
    const val = (b.ibgeCode ?? b.codigoMunicipio ?? b.codigoIbge ?? "").trim();
    company.ibgeCode = val;
    company.codigoMunicipio = val;
  }
  const patchedGeo = inferIbgeAndValidCep({
    cep: company.cep,
    cidade: company.city || company.cidade,
    uf: company.state || company.uf,
    codigoMunicipio: company.ibgeCode || company.codigoMunicipio
  });
  if (patchedGeo.codigoMunicipio) {
    company.ibgeCode = patchedGeo.codigoMunicipio;
    company.codigoMunicipio = patchedGeo.codigoMunicipio;
  }

  applyCrmBillingConfigFields(company, b);

  company.updatedAt = new Date().toISOString();
  saveDatabase("company_updated_" + id);
  logAuditEvent({
    level: "info",
    category: "company",
    action: "COMPANY_UPDATED",
    actor: req.user || { name: "Usuário", role: "admin" },
    details: { companyId: id, corporateName: company.corporateName, changes: req.body },
    source: "CRM Empresas"
  });
  res.json(company);
};
app.patch("/api/companies/:id", handleUpdateCompany);
app.put("/api/companies/:id", handleUpdateCompany);

app.delete("/api/companies/:id", (req, res) => {
  const id = Number(req.params.id);
  if (!db.companies) db.companies = [];
  const company = db.companies.find(c => c.id === id);
  const removed = company ? { ...company } : null;
  db.companies = db.companies.filter(c => c.id !== id);
  saveDatabase("company_deleted_" + id);
  logAuditEvent({
    level: "warn",
    category: "company",
    action: "COMPANY_DELETED",
    actor: req.user || { name: "Usuário", role: "admin" },
    details: { companyId: id, removed },
    source: "CRM Empresas"
  });
  res.json({ success: true });
});

// ── Agências de Viagens B2B / Travel Agencies CRM & 360º Endpoints ──────────
app.get(["/api/agencies", "/api/pms/agencies"], (req, res) => {
  if (ensureB2bSeedData(db)) {
    setImmediate(() => saveDatabase("b2b_agencies_backfill"));
  }
  if (!db.agencies) db.agencies = [];
  const enriched = db.agencies.map(ag => {
    const agId = Number(ag.id);
    const agCnpj = onlyDigits(ag.cnpj || "");
    const reservations = (db.reservations || []).filter(r =>
      r.status !== "cancelada" && r.status !== "cancelled" && (
        (r.agencyId && Number(r.agencyId) === agId) ||
        (agCnpj && onlyDigits(r.agencyCnpj || "") === agCnpj) ||
        (ag.tradeName && r.agencyName && String(r.agencyName).toLowerCase().includes(String(ag.tradeName).toLowerCase()))
      )
    );
    const getB2bCommAmt = (resObj) => {
      const { resChannel } = resolveReservationChannelAndCommission(resObj, db.settings?.feeSettings, db.agencies || []);
      return resChannel === "b2b" ? (Number(resObj.b2bCommissionAmount) || 0) : 0;
    };
    const totalRevenue = reservations.reduce((acc, r) => acc + (Number(r.totalAmount) || 0), 0);
    const totalCommission = reservations.reduce((acc, r) => acc + getB2bCommAmt(r), 0);
    const totalNet = reservations.reduce((acc, r) => {
      const comm = getB2bCommAmt(r);
      return acc + ((Number(r.totalAmount) || 0) - comm);
    }, 0);

    // Normaliza clientCompanies para sempre expor objetos { id, name, tradeName, corporateName, cnpj }
    const rawClientCompanies = Array.isArray(ag.clientCompanies) ? ag.clientCompanies : [];
    const normalizedClientCompanies = rawClientCompanies.map((cc, idx) => {
      if (cc && typeof cc === "object") {
        const compName = cc.name || cc.tradeName || cc.corporateName || "";
        return { ...cc, name: compName };
      }
      const nameStr = String(cc || "").trim();
      const matchedComp = (db.companies || []).find(
        c =>
          String(c.tradeName || "").toLowerCase() === nameStr.toLowerCase() ||
          String(c.corporateName || "").toLowerCase().includes(nameStr.toLowerCase())
      );
      return {
        id: matchedComp?.id || idx + 1,
        name: matchedComp?.tradeName || nameStr,
        tradeName: matchedComp?.tradeName || nameStr,
        corporateName: matchedComp?.corporateName || nameStr,
        cnpj: matchedComp?.cnpj || ""
      };
    });

    return {
      ...ag,
      defaultRatePolicy: ag.defaultRatePolicy || ag.ratePolicy || "COMISSIONADA",
      defaultCommissionPct: ag.defaultCommissionPct ?? ag.commissionPct ?? 12,
      clientCompanies: normalizedClientCompanies,
      reservationsCount: reservations.length,
      totalReservations: reservations.length,
      totalRevenue: Number(totalRevenue.toFixed(2)),
      totalCommission: Number(totalCommission.toFixed(2)),
      totalNet: Number(totalNet.toFixed(2))
    };
  });
  res.json(enriched);
});

app.get(["/api/agencies/:id", "/api/pms/agencies/:id"], (req, res) => {
  ensureB2bSeedData(db);
  const id = Number(req.params.id);
  const agency = (db.agencies || []).find(a => Number(a.id) === id);
  if (!agency) return res.status(404).json({ error: "Agência não encontrada" });

  const agCnpj = onlyDigits(agency.cnpj || "");
  const reservationsRaw = (db.reservations || []).filter(r =>
    (r.agencyId && Number(r.agencyId) === id) ||
    (agCnpj && onlyDigits(r.agencyCnpj || "") === agCnpj) ||
    (agency.tradeName && r.agencyName && String(r.agencyName).toLowerCase().includes(String(agency.tradeName).toLowerCase()))
  );

  const reservations = reservationsRaw.map(r => {
    const cin = r.checkinDate || r.checkInDate || "";
    const cout = r.checkoutDate || r.checkOutDate || "";
    const nights =
      r.nights ||
      (cin && cout
        ? Math.max(1, Math.round((new Date(`${cout}T12:00:00Z`) - new Date(`${cin}T12:00:00Z`)) / 86400000))
        : 1);
    return {
      ...r,
      checkinDate: cin,
      checkoutDate: cout,
      checkInDate: cin,
      checkOutDate: cout,
      nights
    };
  });

  const companyIdsSet = new Set(Array.isArray(agency.clientCompanyIds) ? agency.clientCompanyIds.map(Number) : []);
  reservations.forEach(r => {
    if (r.companyId) companyIdsSet.add(Number(r.companyId));
  });
  if (Array.isArray(agency.clientCompanies)) {
    agency.clientCompanies.forEach(cc => {
      const nameStr = typeof cc === "string" ? cc : (cc?.name || cc?.tradeName || "");
      if (!nameStr) return;
      const matched = (db.companies || []).find(
        c =>
          String(c.tradeName || "").toLowerCase() === nameStr.toLowerCase() ||
          String(c.corporateName || "").toLowerCase().includes(nameStr.toLowerCase())
      );
      if (matched) companyIdsSet.add(Number(matched.id));
    });
  }
  const companies = (db.companies || [])
    .filter(c => companyIdsSet.has(Number(c.id)))
    .map(c => ({
      ...c,
      name: c.tradeName || c.corporateName || "",
      reservationsCount: reservations.filter(r => Number(r.companyId) === Number(c.id)).length
    }));

  const guestIdsSet = new Set();
  reservations.forEach(r => {
    if (r.guestId) guestIdsSet.add(Number(r.guestId));
  });
  const guests = (db.guests || [])
    .filter(g => guestIdsSet.has(Number(g.id)) || Number(g.agencyId) === id)
    .map(g => ({
      ...g,
      name: g.fullName || g.name || "",
      fullName: g.fullName || g.name || "",
      cpf: g.cpf || g.document || g.documentNumber || "",
      reservationsCount: reservations.filter(r => Number(r.guestId) === Number(g.id)).length
    }));

  const invoices = (db.invoices || []).filter(inv =>
    (inv.agencyId && Number(inv.agencyId) === id) ||
    (agCnpj && onlyDigits(inv.tomadorCpfCnpj || "") === agCnpj) ||
    reservations.some(r => Number(r.id) === Number(inv.reservationId) || (r.code && r.code === inv.reservationCode))
  );

  const boletos = (db.boletos || []).filter(b =>
    b && (
      (b.agencyId && Number(b.agencyId) === id) ||
      (agCnpj && onlyDigits(b.payer?.cpfCnpj || b.payerDocument || "") === agCnpj) ||
      reservations.some(r => Number(r.id) === Number(b.reservationId) || (r.code && r.code === b.reservationCode))
    )
  ).map(b => enrichBoletoDynamicStatus(b));

  const getActiveB2bCommAmt = (resObj) => {
    const { resChannel } = resolveReservationChannelAndCommission(resObj, db.settings?.feeSettings, db.agencies || []);
    return resChannel === "b2b" ? (Number(resObj.b2bCommissionAmount) || 0) : 0;
  };
  const activeRes = reservations.filter(r => r.status !== "cancelada" && r.status !== "cancelled");
  const totalNights = activeRes.reduce((acc, r) => acc + (Number(r.nights) || 1), 0);
  const totalRevenue = activeRes.reduce((acc, r) => acc + (Number(r.totalAmount) || 0), 0);
  const totalCommission = activeRes.reduce((acc, r) => acc + getActiveB2bCommAmt(r), 0);
  const totalNet = activeRes.reduce((acc, r) => acc + ((Number(r.totalAmount) || 0) - getActiveB2bCommAmt(r)), 0);

  const metrics = {
    totalReservations: reservations.length,
    reservationsCount: reservations.length,
    activeReservations: activeRes.length,
    activeReservationsCount: activeRes.length,
    totalNights,
    companiesCount: companies.length,
    companiesServedCount: companies.length,
    guestsCount: guests.length,
    guestsServedCount: guests.length,
    invoicesCount: invoices.length,
    invoicesIssuedCount: invoices.length,
    boletosCount: boletos.length,
    openBoletosCount: boletos.filter(b => b.status === "aberto" || b.status === "vencido").length,
    openBoletosAmount: Number(boletos.filter(b => b.status === "aberto" || b.status === "vencido").reduce((s, b) => s + (Number(b.amount) || 0), 0).toFixed(2)),
    paidBoletosAmount: Number(boletos.filter(b => b.status === "pago").reduce((s, b) => s + (Number(b.paidAmount || b.amount) || 0), 0).toFixed(2)),
    totalRevenue: Number(totalRevenue.toFixed(2)),
    totalCommission: Number(totalCommission.toFixed(2)),
    totalNet: Number(totalNet.toFixed(2)),
    totalNetRevenue: Number(totalNet.toFixed(2))
  };

  const boletosSummary = computeBoletosSummaryMetrics(boletos);

  res.json({
    ...agency,
    defaultRatePolicy: agency.defaultRatePolicy || agency.ratePolicy || "COMISSIONADA",
    defaultCommissionPct: agency.defaultCommissionPct ?? agency.commissionPct ?? 12,
    agency,
    reservations,
    companies,
    companiesServed: companies,
    guests,
    guestsServed: guests,
    invoices,
    boletos,
    boletosSummary,
    metrics,
    stats: metrics
  });
});

app.post(["/api/agencies", "/api/pms/agencies"], (req, res) => {
  if (!db.agencies) db.agencies = [];
  const b = req.body || {};
  const resolvedCorporateName = (b.corporateName || b.razaoSocial || b.tradeName || b.nomeFantasia || "").trim();
  if (!resolvedCorporateName) {
    return res.status(400).json({ error: "Razão Social ou Nome Fantasia da agência é obrigatório." });
  }
  const resolvedTradeName = (b.tradeName || b.nomeFantasia || resolvedCorporateName).trim();
  const resolvedCnpj = (b.cnpj || "").trim();
  const cleanCnpj = onlyDigits(resolvedCnpj);

  if (cleanCnpj.length === 14) {
    const existing = db.agencies.find(a => onlyDigits(a.cnpj) === cleanCnpj);
    if (existing) {
      if (b.posUnits && Array.isArray(b.posUnits)) existing.posUnits = b.posUnits;
      if (b.agents && Array.isArray(b.agents)) existing.agents = b.agents;
      if (b.financialEmail || b.email) existing.financialEmail = (b.financialEmail || b.email).trim();
      if (b.phone || b.telefone) existing.phone = (b.phone || b.telefone).trim();
      applyCrmBillingConfigFields(existing, b);
      existing.updatedAt = new Date().toISOString();
      saveDatabase("agency_upserted_" + existing.id);
      return res.status(200).json(existing);
    }
  }

  const resolvedStateReg = (b.stateRegistration || b.inscricaoEstadual || "").trim();
  const resolvedMunReg = (b.municipalRegistration || b.inscricaoMunicipal || "").trim();
  const resolvedEmail = (b.financialEmail || b.emailFinanceiro || b.email || "").trim();
  const resolvedPhone = (b.phone || b.telefone || "").trim();
  const resolvedContact = (b.contactPerson || b.contato || "").trim();
  const resolvedBilling = (b.billingTerms || b.condicaoFaturamento || "Cartão Virtual B2B (VCN) / Faturado").trim();
  const resolvedNotes = (b.notes || b.observacoes || "").trim();
  const resolvedAddress = (b.address || b.logradouro || b.endereco || "").trim();
  const resolvedNumber = (b.number || b.numero || "").trim();
  const resolvedComplement = (b.complement || b.complemento || "").trim();
  const resolvedNeighborhood = (b.neighborhood || b.bairro || "").trim();
  const resolvedCep = String(b.cep || "").replace(/\D/g, "");
  const resolvedCity = (b.city || b.cidade || b.municipio || "São Paulo").trim();
  const resolvedState = (b.state || b.uf || b.estado || "SP").trim().toUpperCase();
  const resolvedIbge = (b.ibgeCode || b.codigoMunicipio || b.codigoIbge || (resolvedCity.toLowerCase().includes("campos") ? "3301009" : "3550308")).trim();
  const defaultRatePolicy = String(b.defaultRatePolicy || "COMISSIONADA").toUpperCase() === "NET" ? "NET" : "COMISSIONADA";
  const defaultCommissionPct = b.defaultCommissionPct !== undefined ? Number(b.defaultCommissionPct) : (defaultRatePolicy === "NET" ? 0 : 12);
  const defaultInvoiceRecipient = ["guest", "company", "agency"].includes(String(b.defaultInvoiceRecipient || "").toLowerCase())
    ? String(b.defaultInvoiceRecipient).toLowerCase()
    : (defaultRatePolicy === "NET" ? "agency" : "company");

  const nextId = db.agencies.length > 0 ? Math.max(...db.agencies.map(a => Number(a.id) || 0)) + 1 : 1;
  const newAgency = {
    id: nextId,
    corporateName: resolvedCorporateName,
    razaoSocial: resolvedCorporateName,
    tradeName: resolvedTradeName,
    nomeFantasia: resolvedTradeName,
    cnpj: resolvedCnpj || "Não informado",
    stateRegistration: resolvedStateReg,
    inscricaoEstadual: resolvedStateReg,
    municipalRegistration: resolvedMunReg,
    inscricaoMunicipal: resolvedMunReg,
    financialEmail: resolvedEmail,
    emailFinanceiro: resolvedEmail,
    phone: resolvedPhone,
    telefone: resolvedPhone,
    contactPerson: resolvedContact,
    contato: resolvedContact,
    billingTerms: resolvedBilling,
    defaultRatePolicy,
    defaultCommissionPct,
    defaultInvoiceRecipient,
    posUnits: Array.isArray(b.posUnits) ? b.posUnits : [],
    agents: Array.isArray(b.agents) ? b.agents : [],
    clientCompanyIds: Array.isArray(b.clientCompanyIds) ? b.clientCompanyIds.map(Number) : [],
    notes: resolvedNotes,
    address: resolvedAddress,
    logradouro: resolvedAddress,
    endereco: resolvedAddress,
    number: resolvedNumber,
    numero: resolvedNumber,
    complement: resolvedComplement,
    complemento: resolvedComplement,
    neighborhood: resolvedNeighborhood,
    bairro: resolvedNeighborhood,
    cep: resolvedCep,
    city: resolvedCity,
    cidade: resolvedCity,
    state: resolvedState,
    uf: resolvedState,
    ibgeCode: resolvedIbge,
    codigoMunicipio: resolvedIbge,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  applyCrmBillingConfigFields(newAgency, b);

  db.agencies.push(newAgency);
  saveDatabase("agency_created_" + newAgency.id);
  logAuditEvent({
    level: "info",
    category: "agency",
    action: "AGENCY_CREATED",
    actor: req.user || { name: "Usuário", role: "admin" },
    details: { agencyId: newAgency.id, corporateName: newAgency.corporateName, tradeName: newAgency.tradeName, cnpj: newAgency.cnpj, fullAgency: newAgency },
    source: "CRM Agências"
  });
  res.status(201).json(newAgency);
});

