app.get("/api/v2/auth/passkeys/register-options", (req, res) => {
  const user = getAuthV2User(req);
  if (!user) return res.status(401).json({ error: "Não autenticado." });

  const challenge = crypto.randomBytes(32).toString("base64url");
  user.currentPasskeyChallenge = challenge;
  user.currentPasskeyChallengeExpires = Date.now() + 5 * 60 * 1000;
  saveDatabase();

  res.json({
    challenge,
    user: { id: user.id, email: user.email, name: user.name }
  });
});

app.post("/api/v2/auth/passkeys/register-verify", (req, res) => {
  const user = getAuthV2User(req);
  if (!user) return res.status(401).json({ error: "Não autenticado." });

  const { credentialId, deviceName, challenge } = req.body || {};
  if (!credentialId) return res.status(400).json({ error: "Credencial inválida." });

  if (!user.currentPasskeyChallenge || (user.currentPasskeyChallengeExpires && user.currentPasskeyChallengeExpires < Date.now())) {
    return res.status(400).json({ error: "Desafio (challenge) de registro de Passkey ausente ou expirado." });
  }
  if (challenge && challenge !== user.currentPasskeyChallenge) {
    return res.status(400).json({ error: "Desafio (challenge) de Passkey inválido." });
  }

  if (!user.passkeys) user.passkeys = [];
  if (!user.passkeys.some(p => p.credentialId === credentialId)) {
    user.passkeys.push({
      credentialId: String(credentialId),
      deviceName: deviceName || "Dispositivo Biométrico",
      createdAt: new Date().toISOString()
    });
  }
  delete user.currentPasskeyChallenge;
  delete user.currentPasskeyChallengeExpires;
  saveDatabase();

  res.json({ success: true, message: "Passkey registrada com sucesso!" });
});

app.get("/api/v2/auth/passkeys/auth-options", (req, res) => {
  const identifier = String(req.query.email || req.query.identifier || "").trim();
  const challenge = crypto.randomBytes(32).toString("base64url");
  passkeyAuthChallenges.set(challenge, {
    identifier,
    expiresAt: Date.now() + 5 * 60 * 1000
  });
  res.json({ challenge, email: identifier });
});

app.post("/api/v2/auth/passkeys/auth-verify", (req, res) => {
  try {
    const { credentialId, challenge } = req.body || {};
    if (!credentialId || typeof credentialId !== "string") {
      return res.status(401).json({ error: "Credencial de Passkey obrigatória." });
    }
    if (!challenge || !passkeyAuthChallenges.has(challenge)) {
      return res.status(401).json({ error: "Desafio (challenge) de Passkey inválido ou expirado." });
    }
    const storedChallenge = passkeyAuthChallenges.get(challenge);
    passkeyAuthChallenges.delete(challenge);
    if (storedChallenge.expiresAt < Date.now()) {
      return res.status(401).json({ error: "Desafio (challenge) de Passkey expirado." });
    }

    const account = (db.guestAccounts || []).find(g =>
      Array.isArray(g.passkeys) && g.passkeys.some(p => p.credentialId === credentialId)
    );

    if (!account) {
      return res.status(401).json({ error: "Passkey não encontrada ou não vinculada a nenhuma conta." });
    }

    account.lastLoginAt = new Date().toISOString();
    hydrateGuestAccountFromCrmAndReservations(account);
    saveDatabase();

    const safeUser = sanitizeAccountForClient(account);
    setAuthSessionCookie(res, safeUser);

    res.json({
      success: true,
      user: safeUser,
      guest: safeUser,
      token: createGuestV1Token(account),
      message: `Autenticado com Passkey, ${safeUser.name}!`
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 2.11 Exportação de Dados e Exclusão LGPD
app.get("/api/v2/auth/export-data", (req, res) => {
  const user = getAuthV2User(req);
  if (!user) return res.status(401).json({ error: "Não autenticado." });

  const myReservations = getGuestReservations(user);
  const safeUser = sanitizeAccountForClient(user);
  const exportPayload = {
    exportDate: new Date().toISOString(),
    profile: safeUser,
    reservations: myReservations,
    lgpdDisclaimer: "Este arquivo contém a totalidade dos dados cadastrais tratados pela CorpFlats em conformidade com o Art. 18 da LGPD."
  };

  res.setHeader("Content-Type", "application/json");
  res.setHeader("Content-Disposition", `attachment; filename=dados-corpflats-${user.id}.json`);
  res.send(JSON.stringify(exportPayload, null, 2));
});

app.delete("/api/v2/auth/account", (req, res) => {
  const user = getAuthV2User(req);
  if (!user) return res.status(401).json({ error: "Não autenticado." });

  db.guestAccounts = (db.guestAccounts || []).filter(g => g.id !== user.id);
  saveDatabase();

  res.clearCookie(GFM_SESSION_COOKIE, { path: "/" });
  res.json({ success: true, message: "Conta excluída definitivamente de acordo com a LGPD." });
});


// ══════════════════════════════════════════════════════════════════════════════
// MÓDULO 2: PAINEL DE OPERAÇÕES AO VIVO PARA MONITOR 32" HORIZONTAL (`/painel-aovivo`)
// ══════════════════════════════════════════════════════════════════════════════

app.get("/api/live-ops/metrics", (req, res) => {
  try {
    if (typeof ensureSentimentDB === "function") ensureSentimentDB();
    if (typeof initDefaultReviews === "function") initDefaultReviews();

    const now = new Date();
    const todayStr = getIsoDateStr(now);
    const brTimeParts = new Intl.DateTimeFormat("en-US", {
      timeZone: "America/Sao_Paulo",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).formatToParts(now);
    const currentHourBr = Number(brTimeParts.find(p => p.type === "hour")?.value || now.getHours());
    const currentMinBr = Number(brTimeParts.find(p => p.type === "minute")?.value || now.getMinutes());
    const currentMinutesOfDay = currentHourBr * 60 + currentMinBr;

    // Garante as 19 unidades ativas da CorpFlats (113 a 1304)
    const rawDbFlats = Array.isArray(db.flats) && db.flats.length >= 19 ? db.flats : DEFAULT_FLATS;
    const activeFlatsList = rawDbFlats
      .filter(f => f && String(f.number) !== "502" && f.id !== 9 && f.isActive !== false)
      .sort((a, b) => Number(a.number) - Number(b.number));
    const totalFlats = activeFlatsList.length || 19;

    // Helpers de verificação de reserva
    const isResPaidHelper = (r) => {
      if (!r) return false;
      const ch = String(r.channel || "").toLowerCase();
      const pm = String(r.paymentMethod || "").toLowerCase();
      const isOta = ch === "booking" || ch === "airbnb" || pm === "booking" || pm === "airbnb";
      const isGwPaid = Boolean(r.mpPaymentId || r.gatewayPaidAt || r.paidAt);
      const isUnpaidPre = r.status === "pre_reserva" && !isOta && !isGwPaid;
      return !isUnpaidPre && (
        isGwPaid ||
        r.paymentStatus === "pago_total" ||
        r.paymentStatus === "pago" ||
        (Number(r.paidAmount || 0) >= Number(r.totalAmount || 0) && Number(r.totalAmount || 0) > 0)
      );
    };

    const isResFnrhDoneHelper = (r) => {
      if (!r) return false;
      return Boolean(
        r.fnhrCompleted ||
        r.fnrhCompleted ||
        r.fnrhSigned ||
        r.hasCompletedCheckin ||
        r.checkinDone ||
        r.status === "checked_in" ||
        (Array.isArray(r.guests) && r.guests.length > 0 && r.guests.some(g => g.hasCompletedCheckin || g.checkinCompletedAt))
      );
    };

    const isResPasswordSentHelper = (r) => {
      if (!r) return false;
      return Boolean(
        r.checkinInstructionsSent ||
        r.passwordSent ||
        r.lockCodeSent ||
        r.accessSent ||
        r.checkinDone ||
        r.status === "checked_in"
      );
    };

    const allValidReservations = (db.reservations || []).filter(r => r && r.status !== "cancelada" && r.status !== "cancelled" && r.status !== "cancelado" && r.status !== "expirada" && r.status !== "no_show");

    // 1. Ocupação Hoje
    const occupiedReservationsToday = allValidReservations.filter(r =>
      r.checkinDate <= todayStr && r.checkoutDate > todayStr && r.status !== "pre_reserva"
    );
    const occupiedCount = occupiedReservationsToday.length;
    const occupancyRate = totalFlats > 0 ? Math.round((occupiedCount / totalFlats) * 100) : 0;

    // Previsão de Ocupação dos Próximos 7 Dias
    const next7Days = [];
    for (let i = 0; i < 7; i++) {
      const targetDate = addDaysNative(now, i);
      const targetStr = getIsoDateStr(targetDate);
      const occDay = allValidReservations.filter(r => r.checkinDate <= targetStr && r.checkoutDate > targetStr && r.status !== "pre_reserva").length;
      next7Days.push({
        date: targetStr,
        dayName: getDayNamePt(targetDate),
        dayNum: getDayNumStr(targetDate),
        occupiedCount: occDay,
        occupancyRate: totalFlats > 0 ? Math.round((occDay / totalFlats) * 100) : 0
      });
    }

    // 2. Check-ins e Check-outs de Hoje + Limpezas de Hoje
    const todayCleanings = (db.cleaningRequests || []).filter(r => r && r.requestDate === todayStr);
    const checkinsTodayRaw = allValidReservations.filter(r => r.checkinDate === todayStr);
    const checkoutsTodayRaw = allValidReservations.filter(r => r.checkoutDate === todayStr && r.status !== "pre_reserva");

    // Sentimentos WhatsApp indexados por flat e telefone
    const sentimentList = Array.isArray(db.guestSentiment) ? db.guestSentiment : [];
    const findGuestSentiment = (flatNum, phone, guestName) => {
      const cleanP = String(phone || "").replace(/\D/g, "");
      let match = null;
      if (cleanP && cleanP.length >= 8) {
        match = sentimentList.find(s => {
          const sp = String(s.guestPhone || "").replace(/\D/g, "");
          return sp && (sp.endsWith(cleanP.slice(-8)) || cleanP.endsWith(sp.slice(-8)));
        });
      }
      if (!match && flatNum) {
        match = sentimentList.find(s => String(s.flatNumber) === String(flatNum));
      }
      if (!match && guestName) {
        const gn = String(guestName).toLowerCase().trim();
        match = sentimentList.find(s => String(s.guestName || "").toLowerCase().trim() === gn);
      }
      return match || null;
    };

    // Ordens de Serviço (OS) e Ocorrências (Observations) ativas
    const activeServiceOrders = (db.serviceOrders || []).filter(o => o && o.status === "active");
    const pendingObservations = (db.observations || []).filter(o => o && o.status === "pendente");

    // Check-ins enriquecidos
    const checkinsEnriched = checkinsTodayRaw.map(r => {
      const flatNum = String(r.flatNumber || r.flatId || "");
      const cleanReq = todayCleanings.find(c => String(c.flatNumber) === flatNum || Number(c.flatId) === Number(r.flatId));
      const cleanSt = cleanReq ? (cleanReq.status || "pending") : "clean";
      const isRoomReady = cleanSt === "clean" || cleanSt === "inspected" || cleanSt === "no_show";
      const isDone = r.status === "checked_in" || Boolean(r.checkinDone);
      const isFnrhDone = isResFnrhDoneHelper(r);
      const isPaid = isResPaidHelper(r);
      const isPasswordSent = isResPasswordSentHelper(r);
      const sent = findGuestSentiment(flatNum, r.guestPhone, r.guestName);
      const matchedGuest = (db.guests || []).find(g =>
        (r.guestId && (Number(g.id) === Number(r.guestId) || String(g.id) === String(r.guestId))) ||
        (r.guestDocument && g.document && g.document.replace(/\D/g, "") === r.guestDocument.replace(/\D/g, "")) ||
        (r.guestPhone && g.phone && (phonesMatch(g.phone, r.guestPhone) || g.phone.replace(/\D/g, "").slice(-8) === r.guestPhone.replace(/\D/g, "").slice(-8))) ||
        (r.guestName && (g.fullName || g.name) && areGuestNamesCompatible(r.guestName, g.fullName || g.name))
      );
      const isSmoker = Boolean(r.isSmoker || r.smokerGuestAlert || r.guestSmoked || matchedGuest?.isSmoker || matchedGuest?.smokedInRoom || (matchedGuest?.tags || []).includes("Fumante"));
      return {
        id: r.id,
        code: r.code,
        guestName: r.guestName || "Hóspede",
        flatNumber: flatNum,
        channel: r.channel || "site",
        phone: r.guestPhone || "",
        checkinTime: r.checkinTime || "14:00",
        status: r.status,
        isPreReserva: r.status === "pre_reserva",
        isDone,
        isFnrhDone,
        isPaid,
        isPasswordSent,
        cleanStatus: isRoomReady ? "clean" : (cleanSt === "in_progress" || cleanSt === "assigned" ? "in_progress" : "dirty"),
        maidName: cleanReq?.assignedToName || null,
        whatsappTone: sent?.overallTone || null,
        whatsappScore: sent?.overallScore ?? null,
        isSmoker,
        smokerGuestAlert: isSmoker,
        guestSmoked: isSmoker,
        smokingAlert: r.smokingAlert || (isSmoker ? "Hóspede com histórico de fumo no quarto" : undefined)
      };
    });

    const checkinsDone = checkinsEnriched.filter(c => c.isDone).length;
    const checkinsPending = checkinsEnriched.length - checkinsDone;

    // Check-outs enriquecidos
    const checkoutsEnriched = checkoutsTodayRaw.map(r => {
      const flatNum = String(r.flatNumber || r.flatId || "");
      const cleanReq = todayCleanings.find(c => String(c.flatNumber) === flatNum || Number(c.flatId) === Number(r.flatId));
      const hasSameDayCheckin = checkinsEnriched.some(ci => String(ci.flatNumber) === flatNum);
      const isDone = r.status === "checked_out" || Boolean(r.checkoutDone) || Boolean(cleanReq && (cleanReq.status === "in_progress" || cleanReq.status === "clean" || cleanReq.status === "inspected"));
      return {
        id: r.id,
        code: r.code,
        guestName: r.guestName || "Hóspede",
        flatNumber: flatNum,
        channel: r.channel || "site",
        checkoutTime: r.checkoutTime || "12:00",
        isDone,
        hasTurnaround: hasSameDayCheckin,
        cleanStatus: cleanReq ? (cleanReq.status || "pending") : "pending",
        maidName: cleanReq?.assignedToName || null
      };
    });

    const checkoutsDone = checkoutsEnriched.filter(c => c.isDone).length;
    const checkoutsPending = checkoutsEnriched.length - checkoutsDone;

    // Dobradinhas do Dia (Turnarounds: Sai hoje e Entra hoje no mesmo Flat)
    const turnarounds = [];
    checkinsEnriched.forEach(ci => {
      const co = checkoutsEnriched.find(o => String(o.flatNumber) === String(ci.flatNumber));
      if (co) {
        const cleanReq = todayCleanings.find(c => String(c.flatNumber) === String(ci.flatNumber));
        turnarounds.push({
          flatNumber: ci.flatNumber,
          leavingGuest: co.guestName,
          checkoutDone: co.isDone,
          cleanStatus: ci.cleanStatus,
          maidName: cleanReq?.assignedToName || ci.maidName || null,
          arrivingGuest: ci.guestName,
          arrivingChannel: ci.channel,
          checkinTime: ci.checkinTime || "14:00",
          checkinDone: ci.isDone,
          isFnrhDone: ci.isFnrhDone,
          isPaid: ci.isPaid,
          isPasswordSent: ci.isPasswordSent,
          isUrgentDelay: ci.cleanStatus !== "clean" && currentMinutesOfDay >= 13 * 60 + 15
        });
      }
    });

    // 4. Governança & Mapa Completo dos 19 Flats (Zona B)
    const cleanCount = todayCleanings.filter(r => r.status === "clean" || r.status === "inspected" || r.status === "no_show").length;
    const inProgressCount = todayCleanings.filter(r => r.status === "in_progress" || r.status === "assigned").length;
    const dirtyCount = todayCleanings.filter(r => r.status === "pending" || !r.status).length;
    const maintenanceCount = pendingObservations.length;

    const flatsGrid = activeFlatsList.map(f => {
      const fNum = String(f.number);
      const req = todayCleanings.find(c => String(c.flatNumber) === fNum || Number(c.flatId) === Number(f.id));
      const resCurrent = occupiedReservationsToday.find(r => String(r.flatNumber || r.flatId) === fNum);
      const ciToday = checkinsEnriched.find(c => String(c.flatNumber) === fNum) || null;
      const coToday = checkoutsEnriched.find(c => String(c.flatNumber) === fNum) || null;
      const isTurnaround = Boolean(ciToday && coToday);

      // Verifica OS externa ou avaria pendente no flat
      let osMatch = null;
      let osFlatEntry = null;
      for (const ord of activeServiceOrders) {
        const mf = (ord.flats || []).find(of => String(of.flatNumber) === fNum && of.status !== "done");
        if (mf) {
          osMatch = ord;
          osFlatEntry = mf;
          break;
        }
      }
      const obsMatches = pendingObservations.filter(o => String(o.flatNumber) === fNum);

      // Status de limpeza normalizado
      let cleanSt = "clean";
      if (req) {
        if (req.status === "clean" || req.status === "inspected" || req.status === "no_show") cleanSt = "clean";
        else if (req.status === "in_progress" || req.status === "assigned") cleanSt = "in_progress";
        else cleanSt = "dirty";
      } else if (coToday && !coToday.isDone) {
        cleanSt = "dirty";
      }

      // Determina visualState principal do Card do Flat
      let visualState = "available_clean";
      if (osFlatEntry && osFlatEntry.status === "in_progress") {
        visualState = "maintenance";
      } else if (cleanSt === "in_progress") {
        visualState = "cleaning";
      } else if (cleanSt === "dirty") {
        visualState = (ciToday || isTurnaround) ? "turnaround_dirty" : "dirty";
      } else if (ciToday && !ciToday.isDone) {
        visualState = "ready_checkin_today";
      } else if (resCurrent) {
        visualState = "occupied";
      } else if (osMatch || obsMatches.length > 0) {
        visualState = "maintenance";
      }

      // Hóspede principal de referência para o Card
      const refRes = ciToday || (resCurrent ? {
        guestName: resCurrent.guestName,
        code: resCurrent.code,
        channel: resCurrent.channel || "site",
        checkinDate: resCurrent.checkinDate,
        checkoutDate: resCurrent.checkoutDate,
        isFnrhDone: isResFnrhDoneHelper(resCurrent),
        isPaid: isResPaidHelper(resCurrent),
        isPasswordSent: isResPasswordSentHelper(resCurrent),
        phone: resCurrent.guestPhone
      } : null);

      const sentimentObj = refRes ? findGuestSentiment(fNum, refRes.phone, refRes.guestName) : findGuestSentiment(fNum, null, null);

      const rawLabel = String(f.colName || f.name || "").replace(fNum, "").replace(/^X\s*/i, "").replace(/\s*X$/i, "").trim();
      const shortType = rawLabel ? rawLabel.charAt(0).toUpperCase() + rawLabel.slice(1) : "Flat";

      return {
        id: f.id,
        number: fNum,
        shortType,
        visualState,
        cleanStatus: cleanSt,
        maidName: req?.assignedToName || null,
        cleanCompletedAt: req?.completedAt || null,
        isOccupied: Boolean(resCurrent),
        isTurnaround,
        currentGuest: resCurrent ? resCurrent.guestName : null,
        checkoutDate: resCurrent ? resCurrent.checkoutDate : null,
        channel: refRes?.channel || null,
        arrivingToday: ciToday ? {
          guestName: ciToday.guestName,
          checkinTime: ciToday.checkinTime,
          isDone: ciToday.isDone,
          isPreReserva: ciToday.isPreReserva,
          channel: ciToday.channel,
          isSmoker: Boolean(ciToday.isSmoker || ciToday.smokerGuestAlert || ciToday.guestSmoked),
          smokerGuestAlert: Boolean(ciToday.isSmoker || ciToday.smokerGuestAlert || ciToday.guestSmoked)
        } : null,
        leavingToday: coToday ? {
          guestName: coToday.guestName,
          checkoutTime: coToday.checkoutTime,
          isDone: coToday.isDone
        } : null,
        badges: refRes ? {
          fnrh: Boolean(refRes.isFnrhDone),
          paid: Boolean(refRes.isPaid),
          password: Boolean(refRes.isPasswordSent),
          whatsappTone: sentimentObj?.overallTone || null,
          whatsappScore: sentimentObj?.overallScore ?? null
        } : null,
        maintenance: {
          hasIssue: Boolean(osMatch || obsMatches.length > 0),
          inProgress: Boolean(osFlatEntry?.status === "in_progress"),
          count: (osMatch ? 1 : 0) + obsMatches.length,
          title: osMatch ? osMatch.title : (obsMatches[0]?.description || null),
          workerName: osMatch?.workerName || null
        }
      };
    });

    // 5. Cafés da Manhã de Hoje (Sem dados de garagem)
    const breakfastOrdersToday = todayCleanings.filter(r =>
      r.hasBreakfast || r.breakfastOrder
    ).map(r => ({
      flatNumber: r.flatNumber,
      deliveryTime: r.breakfastOrder?.deliveryTime || "07:30",
      guestName: r.arrivingGuest || r.leavingGuest || "Hóspede",
      items: r.breakfastOrder?.items || ["Café", "Pães", "Frutas", "Suco"],
      status: r.breakfastDelivered ? "Entregue" : "Preparando"
    }));

    // 6. Financeiro Hoje, Mês & Canais
    const todayRevenue = occupiedReservationsToday.reduce((acc, r) => acc + (Number(r.dailyRate) || 250), 0);
    const currentMonth = todayStr.substring(0, 7);
    const monthReservations = allValidReservations.filter(r => r.checkinDate && r.checkinDate.startsWith(currentMonth) && r.status !== "pre_reserva");
    const monthRevenue = monthReservations.reduce((acc, r) => acc + (Number(r.totalAmount) || 0), 0);
    const adr = occupiedCount > 0 ? Math.round(todayRevenue / occupiedCount) : 250;
    const revpar = totalFlats > 0 ? Math.round(todayRevenue / totalFlats) : 0;

    const channelCounts = { site: 0, whatsapp: 0, booking: 0, airbnb: 0, corporate: 0 };
    monthReservations.forEach(r => {
      const ch = String(r.channel || "site").toLowerCase();
      if (ch.includes("booking")) channelCounts.booking++;
      else if (ch.includes("airbnb")) channelCounts.airbnb++;
      else if (ch.includes("whats") || ch.includes("sofia")) channelCounts.whatsapp++;
      else if (r.clientType === "empresa" || ch.includes("corp") || ch.includes("faturado")) channelCounts.corporate++;
      else channelCounts.site++;
    });

    const benchmarkSohoPrice = 289;
    const corpFlatsPrice = 250;
    const benchmarkSavingsPercent = Math.round(((benchmarkSohoPrice - corpFlatsPrice) / benchmarkSohoPrice) * 100);

    // 7. Funil de Conversões / Anúncios
    const cartSessions = (db.cartSessions || []).filter(s => s && s.updatedAt && s.updatedAt.startsWith(todayStr));
    const siteVisitorsToday = Math.max(cartSessions.length + 12, 18);
    const convertedBookingsToday = allValidReservations.filter(r => r.createdAt && r.createdAt.startsWith(todayStr)).length;
    const conversionRate = siteVisitorsToday > 0 ? ((convertedBookingsToday / siteVisitorsToday) * 100).toFixed(1) : "0.0";

    // 8. Clima no WhatsApp, Sentimento IA, Demandas & Pré-Reservas da Sofia (Zona C Inferior)
    const wppAnalyzed = sentimentList.filter(s => s && s.overallScore != null);
    const avgWppScore = wppAnalyzed.length > 0
      ? Math.round(wppAnalyzed.reduce((a, s) => a + (Number(s.overallScore) || 0), 0) / wppAnalyzed.length)
      : 88;
    const wppPositive = wppAnalyzed.filter(s => s.overallTone === "positive").length;
    const wppNeutral = wppAnalyzed.filter(s => s.overallTone === "neutral").length;
    const wppNegative = wppAnalyzed.filter(s => s.overallTone === "negative").length;
    const totalWppTones = Math.max(wppPositive + wppNeutral + wppNegative, 1);

    const attentionQueue = [...wppAnalyzed]
      .sort((a, b) => {
        const rank = (t) => t === "negative" ? 0 : t === "neutral" ? 1 : 2;
        if (rank(a.overallTone) !== rank(b.overallTone)) return rank(a.overallTone) - rank(b.overallTone);
        return new Date(b.analyzedAt || b.updatedAt || 0).getTime() - new Date(a.analyzedAt || a.updatedAt || 0).getTime();
      })
      .slice(0, 6)
      .map(s => ({
        guestName: s.guestName || "Hóspede",
        flatNumber: s.flatNumber || "--",
        tone: s.overallTone || "neutral",
        score: s.overallScore ?? 75,
        summary: s.summary || (Array.isArray(s.negativeKeywords) && s.negativeKeywords.length > 0 ? `Pontos: ${s.negativeKeywords.join(", ")}` : "Conversa monitorada pela IA"),
        keywords: s.overallTone === "negative" ? (s.negativeKeywords || []) : (s.positiveKeywords || []),
        updatedAt: s.analyzedAt || s.updatedAt || null
      }));

    const activePreReservations = allValidReservations
      .filter(r => r.status === "pre_reserva" && r.checkinDate >= todayStr)
      .slice(-5)
      .reverse()
      .map(r => ({
        code: r.code,
        guestName: r.guestName || "Interessado",
        flatNumber: r.flatNumber || r.flatId,
        checkinDate: r.checkinDate,
        totalAmount: Number(r.totalAmount || 0)
      }));

    const unmetDemands = (db.unmetDemands || db.botDemands || []).filter(d => d && d.status !== "resolved" && d.status !== "done");

    // 9. Avaliações, NPS & Melhorias IA (Slide 2 do Carrossel)
    const reviewsList = Array.isArray(db.reviews) ? db.reviews : [];
    const avgReviewScore = reviewsList.length > 0
      ? Number((reviewsList.reduce((a, r) => a + (Number(r.rating) || 5), 0) / reviewsList.length).toFixed(1))
      : 4.9;

    const npsList = Array.isArray(db.npsResponses) ? db.npsResponses : [];
    const npsResponded = npsList.filter(n => n && n.score != null);
    const npsPromoters = npsResponded.filter(n => Number(n.score) === 5).length;
    const npsNeutrals = npsResponded.filter(n => Number(n.score) >= 3 && Number(n.score) <= 4).length;
    const npsDetractors = npsResponded.filter(n => Number(n.score) <= 2).length;
    const npsSatisfactionRate = npsResponded.length > 0 ? Math.round((npsPromoters / npsResponded.length) * 100) : 100;

    const recentFeedbacks = [
      ...npsResponded.slice(-5).reverse().map(n => ({
        id: `nps_${n.id || n.phone}`,
        author: n.guestName || "Hóspede NPS",
        rating: Number(n.score || 5),
        channel: "WhatsApp NPS",
        flatNumber: n.flatNumber || null,
        comment: n.feedbackComment || n.comment || (Number(n.score) === 5 ? "Avaliação 5 estrelas no pós-checkout!" : `Nota ${n.score} registrada no WhatsApp`),
        tone: Number(n.score) >= 4 ? "positive" : Number(n.score) === 3 ? "neutral" : "negative",
        date: n.respondedAt || n.createdAt || null
      })),
      ...reviewsList.slice(-5).reverse().map(r => ({
        id: `rev_${r.id}`,
        author: r.author || "Hóspede",
        rating: Number(r.rating || 5),
        channel: (r.channel || "OTA").toUpperCase(),
        flatNumber: r.flatMentioned || null,
        comment: r.comment || r.sentimentSummary || "",
        tone: r.sentiment || (Number(r.rating) >= 4 ? "positive" : Number(r.rating) === 3 ? "neutral" : "negative"),
        date: r.date || r.createdAt || null
      }))
    ].slice(0, 5);

    const improvementsObj = db.npsImprovements || { pendingCount: 0, resolvedCount: 0, items: [] };
    const pendingImprovementItems = (improvementsObj.items || [])
      .filter(i => i && i.status !== "resolved")
      .slice(0, 4)
      .map(i => ({
        id: i.id,
        title: i.title || i.category || "Melhoria Sugerida",
        description: i.description || i.suggestion || "",
        flatNumber: i.flatNumber || null,
        priority: i.priority || "medium"
      }));

    // 10. Manutenção (OS), Frigobar & Vistorias (Slide 3 do Carrossel)
    const serviceOrdersSummary = [];
    activeServiceOrders.forEach(ord => {
      const pendingFlats = (ord.flats || []).filter(f => f.status !== "done");
      const inProgFlats = pendingFlats.filter(f => f.status === "in_progress");
      serviceOrdersSummary.push({
        id: ord.id,
        title: ord.title || "Ordem de Serviço",
        workerName: ord.workerName || "Prestador",
        flatsText: pendingFlats.map(f => f.flatNumber).join(", ") || "Concluído",
        status: inProgFlats.length > 0 ? "in_progress" : "pending",
        isExternalOs: true
      });
    });
    pendingObservations.slice(-5).reverse().forEach(obs => {
      serviceOrdersSummary.push({
        id: `obs_${obs.id}`,
        title: obs.description || "Avaria registrada",
        workerName: obs.reportedBy || "Governança",
        flatsText: String(obs.flatNumber || "--"),
        status: "pending",
        isExternalOs: false
      });
    });

    const minibarOrdersToday = (db.minibarOrders || []).filter(o => o && (o.createdAt || "").startsWith(todayStr));
    const minibarPaidToday = minibarOrdersToday.filter(o => o.paymentStatus === "pago");
    const minibarRevenueToday = minibarPaidToday.reduce((sum, o) => sum + Number(o.totalAmount || o.total || 0), 0);

    // 11. Saúde Técnica do Sistema (Zona A)
    const quarantineList = Array.isArray(db.wbpQuarantine) ? db.wbpQuarantine : [];
    const quarantinePendingCount = quarantineList.filter(q => q && q.status === "pending").length;
    const memUsage = process.memoryUsage();
    const zapiConnected = db.zapiConfig?.connectionState !== "disconnected" && db.zapiConfig?.enabled !== false;

    const systemHealth = {
      zapi: {
        connected: zapiConnected,
        state: db.zapiConfig?.connectionState || "connected",
        label: zapiConnected ? "Z-API Online" : "Z-API Alerta"
      },
      sofiaAi: {
        active: true,
        activePreReservationsCount: activePreReservations.length,
        unmetDemandsCount: unmetDemands.length
      },
      otaWbp: {
        synced: quarantinePendingCount === 0,
        quarantinePendingCount
      },
      server: {
        rssMB: Math.round(memUsage.rss / (1024 * 1024)),
        heapUsedMB: Math.round(memUsage.heapUsed / (1024 * 1024)),
        uptimeHours: Math.max(1, Math.round(process.uptime() / 3600)),
        cloudSynced: true
      }
    };

    // 12. Radar de Alertas Operacionais Críticos (Pulsantes no Topo)
    const criticalAlerts = [];

    checkinsEnriched.forEach(ci => {
      if (!ci.isDone && ci.cleanStatus !== "clean") {
        if (currentMinutesOfDay >= 13 * 60 + 30) {
          criticalAlerts.push({
            id: `delay_clean_${ci.flatNumber}`,
            severity: "critical",
            category: "governanca",
            title: `RISCO DE ATRASO CHECK-IN: Flat ${ci.flatNumber} (${ci.guestName}) ainda ${ci.cleanStatus === "in_progress" ? "EM FAXINA" : "SUJO"}!`,
            flatNumber: ci.flatNumber
          });
        } else if (currentMinutesOfDay >= 11 * 60 + 30) {
          criticalAlerts.push({
            id: `turnaround_watch_${ci.flatNumber}`,
            severity: "warning",
            category: "governanca",
            title: `Prioridade de Giro: Flat ${ci.flatNumber} tem entrada hoje (${ci.guestName}) e aguarda conclusão da limpeza.`,
            flatNumber: ci.flatNumber
          });
        }
      }
    });

    checkoutsEnriched.forEach(co => {
      if (!co.isDone && currentMinutesOfDay >= 12 * 60 + 15) {
        criticalAlerts.push({
          id: `late_co_${co.flatNumber}`,
          severity: co.hasTurnaround ? "critical" : "warning",
          category: "checkout",
          title: `CHECK-OUT PENDENTE: Flat ${co.flatNumber} (${co.guestName}) ainda não liberado após 12h${co.hasTurnaround ? " — TEM ENTRADA HOJE!" : ""}`,
          flatNumber: co.flatNumber
        });
      }
    });

    if (wppNegative > 0) {
      const negGuest = attentionQueue.find(a => a.tone === "negative");
      criticalAlerts.push({
        id: `wpp_neg_${negGuest?.flatNumber || "alert"}`,
        severity: "critical",
        category: "whatsapp",
        title: `CLIMA CRÍTICO WHATSAPP: ${negGuest ? `${negGuest.guestName} (Flat ${negGuest.flatNumber}) — ${negGuest.summary}` : `${wppNegative} conversa(s) com tom negativo detectado`}`,
        flatNumber: negGuest?.flatNumber || null
      });
    }

    if (quarantinePendingCount > 0) {
      criticalAlerts.push({
        id: "wbp_quarantine",
        severity: "critical",
        category: "ota",
        title: `RESERVA EM QUARENTENA: ${quarantinePendingCount} reserva(s) OTA aguardando alocação/reconciliação manual!`,
        flatNumber: null
      });
    }

    if (unmetDemands.length > 0) {
      criticalAlerts.push({
        id: "sofia_demands",
        severity: "warning",
        category: "sofia",
        title: `FILA DA SOFIA: ${unmetDemands.length} solicitação(ões) de hóspedes aguardando retorno da gestão.`,
        flatNumber: null
      });
    }

    // 13. Stream de Eventos Ao Vivo (Rodapé Ticker + Histórico)
    const liveEvents = [];

    allValidReservations.slice(-10).reverse().forEach(r => {
      const isPaid = isResPaidHelper(r);
      liveEvents.push({
        id: `res_${r.id}`,
        type: "reserva",
        title: `${r.status === "pre_reserva" ? "Pré-Reserva" : "Reserva"} (${(r.channel || "Site").toUpperCase()})`,
        subtitle: `${r.guestName} • Flat ${r.flatNumber || r.flatId}`,
        detail: `${r.checkinDate} a ${r.checkoutDate} • R$ ${Number(r.totalAmount || 0).toLocaleString("pt-BR")}${isPaid ? " (Pago)" : ""}`,
        time: r.createdAt || now.toISOString(),
        badge: r.status === "pre_reserva" ? "Pré-Reserva" : "Reserva",
        badgeColor: r.status === "pre_reserva" ? "bg-amber-600" : "bg-emerald-600"
      });
    });

    todayCleanings.slice(-8).reverse().forEach(c => {
      let timeStr = "--:--";
      if (c.completedAt) {
        const dt = new Date(c.completedAt);
        timeStr = `${String(dt.getHours()).padStart(2, "0")}:${String(dt.getMinutes()).padStart(2, "0")}`;
      }
      liveEvents.push({
        id: `clean_${c.id}`,
        type: "limpeza",
        title: c.status === "clean" ? `Flat ${c.flatNumber} Limpo e Pronto` : `Faxina no Flat ${c.flatNumber}`,
        subtitle: `Camareira: ${c.assignedToName || "Governança"}`,
        detail: c.completedAt ? `Concluído às ${timeStr}` : "Em andamento",
        time: c.updatedAt || c.createdAt || now.toISOString(),
        badge: c.status === "clean" ? "Limpo" : "Faxina",
        badgeColor: c.status === "clean" ? "bg-sky-600" : "bg-amber-600"
      });
    });

    pendingObservations.slice(-5).reverse().forEach(o => {
      liveEvents.push({
        id: `obs_${o.id}`,
        type: "avaria",
        title: `Manutenção: Flat ${o.flatNumber}`,
        subtitle: o.description || "Ocorrência registrada",
        detail: `Status: ${o.status || "Pendente"}`,
        time: o.createdAt || now.toISOString(),
        badge: "Manutenção",
        badgeColor: "bg-rose-600"
      });
    });

    liveEvents.sort((a, b) => new Date(b.time).getTime() - new Date(a.time).getTime());

    const soundCounters = {
      reservationsCount: allValidReservations.filter(r => r.status !== "pre_reserva").length,
      paidReservationsCount: allValidReservations.filter(r => isResPaidHelper(r)).length,
      cleanFlatsTodayCount: cleanCount,
      criticalAlertsCount: criticalAlerts.filter(a => a.severity === "critical").length
    };

    res.json({
      timestamp: now.toISOString(),
      todayStr,
      totalFlats,
      systemHealth,
      criticalAlerts,
      soundCounters,
      flatsGrid,
      turnarounds,
      occupancy: {
        occupiedCount,
        totalFlats,
        rate: occupancyRate,
        next7Days
      },
      checkins: {
        total: checkinsEnriched.length,
        done: checkinsDone,
        pending: checkinsPending,
        list: checkinsEnriched
      },
      checkouts: {
        total: checkoutsEnriched.length,
        done: checkoutsDone,
        pending: checkoutsPending,
        list: checkoutsEnriched
      },
      governance: {
        clean: cleanCount,
        inProgress: inProgressCount,
        dirty: dirtyCount,
        maintenance: maintenanceCount,
        flatsMap: flatsGrid.map(fg => ({
          id: fg.id,
          number: fg.number,
          cleanStatus: fg.cleanStatus,
          isOccupied: fg.isOccupied,
          currentGuest: fg.currentGuest
        }))
      },
      whatsappClimate: {
        analyzedCount: wppAnalyzed.length,
        avgScore: avgWppScore,
        positiveCount: wppPositive,
        neutralCount: wppNeutral,
        negativeCount: wppNegative,
        positivePercent: wppAnalyzed.length > 0 ? Math.round((wppPositive / totalWppTones) * 100) : 85,
        neutralPercent: wppAnalyzed.length > 0 ? Math.round((wppNeutral / totalWppTones) * 100) : 15,
        negativePercent: wppAnalyzed.length > 0 ? Math.round((wppNegative / totalWppTones) * 100) : 0,
        attentionQueue,
        activePreReservations,
        unmetDemandsCount: unmetDemands.length
      },
      reputationAndNps: {
        avgReviewScore,
        totalReviews: reviewsList.length,
        npsSent: npsList.length,
        npsResponded: npsResponded.length,
        npsPromoters,
        npsNeutrals,
        npsDetractors,
        npsSatisfactionRate,
        recentFeedbacks,
        pendingImprovementsCount: improvementsObj.pendingCount || pendingImprovementItems.length,
        resolvedImprovementsCount: improvementsObj.resolvedCount || 0,
        pendingImprovementItems
      },
      maintenanceAndOps: {
        activeOsCount: activeServiceOrders.length,
        pendingObsCount: pendingObservations.length,
        serviceOrdersList: serviceOrdersSummary.slice(0, 6),
        minibarOrdersTodayCount: minibarOrdersToday.length,
        minibarRevenueToday
      },
      breakfast: {
        count: breakfastOrdersToday.length,
        deliveredCount: breakfastOrdersToday.filter(b => b.status === "Entregue").length,
        pendingCount: breakfastOrdersToday.filter(b => b.status !== "Entregue").length,
        orders: breakfastOrdersToday
      },
      financial: {
        todayRevenue,
        monthRevenue,
        adr,
        revpar,
        benchmarkSohoPrice,
        corpFlatsPrice,
        benchmarkSavingsPercent,
        channelCounts
      },
      traffic: {
        visitorsToday: siteVisitorsToday,
        convertedToday: convertedBookingsToday,
        conversionRate: `${conversionRate}%`,
        cartAbandonmentCount: cartSessions.length
      },
      liveEvents: liveEvents.slice(0, 25)
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


// ══════════════════════════════════════════════════════════════════════════════
// MÓDULO 3: LEITOR INTELIGENTE DE AVALIAÇÕES COM IA (Review Insights)
// ══════════════════════════════════════════════════════════════════════════════

// Inicialização segura de avaliações (sem mockups fictícios)
function initDefaultReviews() {
  if (!db.reviews) db.reviews = [];
  // Purga definitiva de quaisquer dados mockados de teste antigos
  const mockAuthors = ["Marcelo Albuquerque", "Fernanda Costa", "Rodrigo Mendes (Engenheiro)", "Camila Nogueira"];
  const hadMock = db.reviews.some(r => mockAuthors.includes(r.author));

  const mockHighlights = [
    "Café da manhã no quarto elogiado por hóspedes corporativos e de lazer",
    "Agilidade no Check-in Digital com liberação na portaria do Soho",
    "Alta velocidade do Wi-Fi e qualidade do colchão Queen Size",
    "Flats silenciosos e ar condicionado split higienizado"
  ];
  const hadMockHighlights = db.reviewInsights?.highlights?.some(h => mockHighlights.includes(h));

  if (hadMock || hadMockHighlights || (db.reviews.length === 0 && db.reviewInsights?.highlights?.length > 0)) {
    if (hadMock) {
      db.reviews = db.reviews.filter(r => !mockAuthors.includes(r.author));
    }
    if (db.reviews.length === 0) {
      db.reviewInsights = null;
    } else if (db.reviewInsights?.highlights) {
      db.reviewInsights.highlights = db.reviewInsights.highlights.filter(h => !mockHighlights.includes(h));
    }
    if (db.observations) {
      db.observations = db.observations.filter(o => !o.description?.includes("[IA Auto-Ticket]") && !o.generatedFromReviewId);
    }
    saveDatabase();
  }
}
initDefaultReviews();

// 3.1 Listar Avaliações e Diagnóstico da IA
app.get("/api/ai/reviews", (req, res) => {
  initDefaultReviews();
  const reviews = db.reviews || [];

  const pendingActionItems = (db.observations || [])
    .filter(o => o.status === "pendente" && (
      o.generatedFromWhatsApp ||
      o.generatedFromNps ||
      o.generatedFromReviewId ||
      o.description?.includes("[IA Auto-Ticket]") ||
      o.description?.includes("[WhatsApp Defeito]") ||
      o.description?.includes("[WhatsApp Crítica]") ||
      o.description?.includes("[NPS Auto-Ticket]")
    ))
    .map(o => ({
      id: o.id,
      flat: o.flatNumber || "N/A",
      issue: o.description,
      priority: o.severity || "alta",
      status: o.status
    }));

  const emptyInsights = {
    overallScore: 0,
    npsScore: 0,
    totalAnalyzed: reviews.length,
    positivePercent: 0,
    mixedPercent: 0,
    negativePercent: 0,
    highlights: [],
    actionItems: []
  };

  const baseInsights = db.reviewInsights || emptyInsights;
  res.json({
    reviews,
    insights: {
      ...baseInsights,
      actionItems: pendingActionItems
    }
  });
});

// 3.1B Endpoint para Limpar Dados de Teste
app.post("/api/ai/clear-test-data", (req, res) => {
  try {
    db.reviews = [];
    db.reviewInsights = null;
    db.guestSentiment = [];
    db.npsResponses = [];
    db.npsImprovements = null;
    if (db.observations) {
      db.observations = db.observations.filter(o =>
        !o.description?.includes("[IA Auto-Ticket]") &&
        !o.description?.includes("[NPS Auto-Ticket]") &&
        !o.description?.includes("[WhatsApp Defeito]") &&
        !o.description?.includes("[WhatsApp Crítica]") &&
        !o.generatedFromReviewId &&
        !o.generatedFromNps &&
        !o.generatedFromWhatsApp
      );
    }
    saveDatabase();
    res.json({ success: true, message: "Dados de teste excluídos com sucesso!" });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 3.2 Analisar Avaliações com IA (Gera Ordens de Manutenção para Flats Citados)
app.post("/api/ai/analyze-reviews", async (req, res) => {
  try {
    initDefaultReviews();
    const reviews = db.reviews || [];
    const createdMaintenanceOrders = [];

    const getPendingActionItems = () => {
      return (db.observations || [])
        .filter(o => o.status === "pendente" && (
          o.generatedFromWhatsApp ||
          o.generatedFromNps ||
          o.generatedFromReviewId ||
          o.description?.includes("[IA Auto-Ticket]") ||
          o.description?.includes("[WhatsApp Defeito]") ||
          o.description?.includes("[WhatsApp Crítica]") ||
          o.description?.includes("[NPS Auto-Ticket]")
        ))
        .map(o => ({
          id: o.id,
          flat: o.flatNumber || "N/A",
          issue: o.description,
          priority: o.severity || "alta",
          status: o.status
        }));
    };

    // Se não há avaliações, zera métricas e destaques sem inventar nenhum dado mockado
    if (reviews.length === 0) {
      db.reviewInsights = {
        overallScore: 0,
        npsScore: 0,
        totalAnalyzed: 0,
        positivePercent: 0,
        mixedPercent: 0,
        negativePercent: 0,
        lastAnalyzedAt: new Date().toISOString(),
        highlights: [],
        actionItems: getPendingActionItems()
      };
      saveDatabase();
      return res.json({
        success: true,
        message: "Nenhuma avaliação cadastrada para analisar. As métricas e destaques foram calculados exclusivamente sobre dados reais (zerados).",
        createdMaintenanceOrders: [],
        insights: db.reviewInsights
      });
    }

    // Palavras-chave que indicam problemas de manutenção
    const maintenanceKeywords = [
      { trigger: /ar[- ]condicionado|pingando|gotejando|gelando pouco/i, title: "Revisão de Ar Condicionado Split" },
      { trigger: /chuveiro|pouca agua|pressao|frio|aquecedor|vazamento/i, title: "Manutenção Hidráulica / Chuveiro" },
      { trigger: /fechadura|tranca|cartao|porta/i, title: "Revisão de Fechadura / Porta" },
      { trigger: /lampada|luz|iluminacao|tomada/i, title: "Revisão Elétrica / Iluminação" },
      { trigger: /tv|smart tv|controle|netflix/i, title: "Configuração de TV / Controle Remoto" },
      { trigger: /frigobar|geladeira|micro-ondas/i, title: "Checagem de Eletrodomésticos" }
    ];

    for (const rev of reviews) {
      if (rev.analyzed && rev.maintenanceChecked) continue;

      // 1. Detecta número do flat no texto (ex: "quarto 304", "flat 1017", "apt 211")
      const flatMatch = (rev.comment || "").match(/(?:flat|quarto|apt|apto|apartamento|unidade)\s*([0-9]{2,4})/i) ||
                         (rev.flatMentioned ? [null, rev.flatMentioned] : null);

      if (flatMatch && flatMatch[1]) {
        const flatNum = flatMatch[1];
        rev.flatMentioned = flatNum;

        // 2. Procura se há menção a problemas técnicos
        for (const kw of maintenanceKeywords) {
          if (kw.trigger.test(rev.comment || "")) {
            if (!db.observations) db.observations = [];

            const existingObs = db.observations.find(o =>
              o.flatNumber === flatNum && o.description.includes(rev.author || "")
            );

            if (!existingObs) {
              const newObsId = db.observations.length > 0 ? Math.max(...db.observations.map(o => o.id || 0)) + 1 : 1;
              const newObs = {
                id: newObsId,
                flatNumber: flatNum,
                type: "manutencao",
                description: `[IA Auto-Ticket] ${kw.title} detectado na avaliação de ${rev.author || "Hóspede"} (${(rev.channel || "canal").toUpperCase()}): "${(rev.comment || "").substring(0, 120)}..."`,
                severity: "media",
                status: "pendente",
                createdAt: new Date().toISOString(),
                generatedFromReviewId: rev.id
              };
              db.observations.push(newObs);
              createdMaintenanceOrders.push(newObs);
              rev.maintenanceGenerated = true;
            }
          }
        }
      }

      rev.analyzed = true;
      rev.maintenanceChecked = true;
    }

    // Recalcula métricas globais exclusivamente com dados reais
    const total = reviews.length;
    const avgScore = Number((reviews.reduce((acc, r) => acc + (Number(r.rating) || 5), 0) / total).toFixed(1));

    const positiveCount = reviews.filter(r => Number(r.rating) >= 4 || r.sentiment === "positive").length;
    const mixedCount = reviews.filter(r => Number(r.rating) === 3 || r.sentiment === "neutral" || r.sentiment === "mixed").length;
    const negativeCount = reviews.filter(r => Number(r.rating) <= 2 || r.sentiment === "negative").length;

    const positivePercent = Math.round((positiveCount / total) * 100);
    const mixedPercent = Math.round((mixedCount / total) * 100);
    const negativePercent = Math.round((negativeCount / total) * 100);

    const promoters = reviews.filter(r => Number(r.rating) === 5).length;
    const detractors = reviews.filter(r => Number(r.rating) <= 3).length;
    const npsScore = Math.round(((promoters - detractors) / total) * 100);

    // Destaques estritamente reais extraídos de avaliações com nota >= 4
    let highlights = [];
    const positiveReviews = reviews.filter(r => (Number(r.rating) >= 4 || r.sentiment === "positive") && r.comment?.trim());

    if (positiveReviews.length > 0) {
      const apiKey = process.env.GEMINI_API_KEY || db.settings?.geminiApiKey || process.env.GOOGLE_AI_API_KEY;
      if (apiKey) {
        try {
          const sampleText = positiveReviews.slice(0, 10).map(r => `- "${r.comment.trim()}" (${r.author || "Hóspede"})`).join("\n");
          const prompt = `Você é um analista de hospitalidade do hotel CorpFlats. A seguir estão comentários REAIS de avaliações positivas de hóspedes:\n${sampleText}\n\nCom base ESTRITAMENTE nesses comentários reais, resuma de 1 a 4 principais pontos fortes ou elogios reais (máximo 12 palavras por item). NUNCA invente nada que não esteja citado nesses comentários.\nRetorne APENAS um JSON no formato: ["ponto 1", "ponto 2"]`;
          const aiRes = await callGeminiGenerateContent(apiKey, [{ parts: [{ text: prompt }] }]);
          if (aiRes.ok) {
            const raw = aiRes.data?.candidates?.[0]?.content?.parts?.[0]?.text || "";
            const jsonMatch = raw.match(/\[[\s\S]*\]/);
            if (jsonMatch) {
              const parsed = JSON.parse(jsonMatch[0]);
              if (Array.isArray(parsed)) {
                highlights = parsed.filter(p => typeof p === "string" && p.trim().length > 0).slice(0, 4);
              }
            }
          }
        } catch (err) {
          console.warn("[Gemini Highlights Error]", err.message);
        }
      }

      // Se a IA não gerou ou não há chave, extrair diretamente as frases reais dos comentários
      if (highlights.length === 0) {
        highlights = positiveReviews.slice(0, 4).map(r => {
          const firstSentence = r.comment.split(/[.!?\n]/)[0]?.trim();
          return firstSentence && firstSentence.length >= 10
            ? `${firstSentence} (${r.author || "Hóspede"})`
            : `${r.comment.substring(0, 75)}... (${r.author || "Hóspede"})`;
        });
      }
    }

    db.reviewInsights = {
      overallScore: avgScore,
      npsScore,
      totalAnalyzed: total,
      positivePercent,
      mixedPercent,
      negativePercent,
      lastAnalyzedAt: new Date().toISOString(),
      highlights,
      actionItems: getPendingActionItems()
    };

    saveDatabase();

    res.json({
      success: true,
      message: `Análise concluída com base em ${total} avaliação(ões) real(is)! ${createdMaintenanceOrders.length} ordens de manutenção geradas.`,
      createdMaintenanceOrders,
      insights: db.reviewInsights
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 3.3 Importar Nova Avaliação
app.post("/api/ai/import-review", async (req, res) => {
  try {
    const { author, rating, channel, comment, flatMentioned } = req.body;
    if (!author || !comment) {
      return res.status(400).json({ error: "Autor e comentário são obrigatórios." });
    }

    initDefaultReviews();
    const newId = db.reviews.length > 0 ? Math.max(...db.reviews.map(r => r.id || 0)) + 1 : 1;
    const newRev = {
      id: newId,
      author: author.trim(),
      rating: Number(rating) || 5,
      channel: channel || "airbnb",
      date: getIsoDateStr(new Date()),
      flatMentioned: flatMentioned || null,
      comment: comment.trim(),
      sentiment: Number(rating) >= 4 ? "positive" : Number(rating) === 3 ? "mixed" : "negative",
      analyzed: false
    };

    db.reviews.unshift(newRev);
    if (Number(newRev.rating) <= 4) {
      await rebuildNpsImprovementsSummary(db);
    }

    // [Feature F2 Hook Point 5: Avaliação importada externamente (Airbnb, Booking)]
    invokeMaidReviewHookSafe(db, {
      hookType: "imported_review",
      review: newRev,
      score: Number(newRev.rating),
      comment: newRev.comment,
      flatNumber: newRev.flatMentioned,
      guestName: newRev.author,
      respondedAt: newRev.date
    }, { saveDatabase }).catch(e => console.warn("[Hook 5 Non-Blocking]", e?.message));

    saveDatabase();

    res.json({ success: true, review: newRev });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});


// ══════════════════════════════════════════════════════════════════════════════
// MÓDULO 3B: ANÁLISE DE SENTIMENTO DE HÓSPEDES (WhatsApp + NPS + Filtro Google)
// ══════════════════════════════════════════════════════════════════════════════

// Normalizador e unificador canônico de palavras-chave para sentimento (remove pontuação e unifica lemas)
function sanitizeKeyword(raw) {
  if (!raw || typeof raw !== "string") return "";
  let clean = raw.trim()
    .replace(/^[\p{P}\p{S}\s]+|[\p{P}\p{S}\s]+$/gu, "")
    .toLowerCase();

  const lemmaMap = {
    "problemas": "problema",
    "suja": "sujo", "sujas": "sujo", "sujos": "sujo",
    "demorada": "demorado", "demoradas": "demorado", "demorados": "demorado", "demoras": "demora",
    "barulhenta": "barulhento", "barulhentas": "barulhento", "barulhentos": "barulhento", "barulhos": "barulho",
    "quebrada": "quebrado", "quebradas": "quebrado", "quebrados": "quebrado",
    "estragada": "estragado", "estragadas": "estragado", "estragados": "estragado",
    "defeitos": "defeito", "falhas": "falha", "vazamentos": "vazamento", "goteiras": "goteira",
    "ruins": "ruim", "pessimo": "péssimo", "pessima": "péssimo", "péssima": "péssimo",
    "terrivel": "terrível", "terriveis": "terrível", "terríveis": "terrível",
    "horrivel": "horrível", "horriveis": "horrível", "horríveis": "horrível",
    "otimo": "ótimo", "otima": "ótimo", "ótima": "ótimo", "otimos": "ótimo", "ótimos": "ótimo",
    "excelentes": "excelente", "maravilhosa": "maravilhoso", "maravilhosas": "maravilhoso", "maravilhosos": "maravilhoso",
    "perfeita": "perfeito", "perfeitas": "perfeito", "perfeitos": "perfeito",
    "impecavel": "impecável", "impecaveis": "impecável", "impecáveis": "impecável",
    "confortavel": "confortável", "confortaveis": "confortável", "confortáveis": "confortável"
  };
  return lemmaMap[clean] || clean;
}

// Helper: chama Gemini para analisar sentimento de texto livre com fallback heurístico automático
async function analyzeTextSentimentWithAI(text, context) {
  const ctx = context || "";
  const apiKey = process.env.GEMINI_API_KEY || db.settings?.geminiApiKey || process.env.GOOGLE_AI_API_KEY;

  const runHeuristicAnalysis = (reason = "") => {
    const positiveWords = /excelente|ótimo|otimo|maravilhoso|perfeito|adorei|parabéns|parabens|impecável|impecavel|muito bom|gostei muito|recomendo|nota 10|nota 5|satisfeito/i;
    const negativeWords = /ruim|péssimo|pessimo|terrível|terrivel|horrível|horrivel|problema|problemas|defeito|defeitos|falha|quebrado|sujo|barulho|barulhento|vazamento|goteira|gotejando|pingando|frio|calor|demora|demorado|não funciona|nao funciona|estragado|estragou/i;
    const maintWords = /ar[- ]condicionado|chuveiro|água|agua|aquecedor|fechadura|porta|chave|tranca|lâmpada|lampada|luz|tomada|tv|televisão|televisao|frigobar|geladeira|wi-fi|wifi|internet|vazamento|pia|vaso|dreno/i;

    const pos = positiveWords.test(text);
    const neg = negativeWords.test(text);
    const maint = maintWords.test(text);

    let score = 65;
    let tone = "neutral";
    if (neg) {
      score = maint ? 20 : 30;
      tone = "negative";
    } else if (pos) {
      score = 90;
      tone = "positive";
    }

    const rawWords = (text || "").split(/\s+/);
    const words = rawWords.map(w => sanitizeKeyword(w)).filter(w => w.length >= 3);
    const posKw = Array.from(new Set(words.filter(w => positiveWords.test(w)).map(sanitizeKeyword))).slice(0, 4);
    const negKw = Array.from(new Set(words.filter(w => negativeWords.test(w) || maintWords.test(w)).map(sanitizeKeyword))).slice(0, 4);

    const flatMatch = (text || "").match(/(?:apto|apt|flat|quarto|unidade|su[ií]te)\s*[:#º°]?\s*(\d{2,4}[a-z]?)/i);
    const flats = flatMatch ? [flatMatch[1]] : [];

    const suggestions = [];
    if (neg) {
      if (maint) suggestions.push(`Verificar reparo emergencial de manutenção${flats[0] ? ` no Flat ${flats[0]}` : ""}`);
      suggestions.push("Entrar em contato com o hóspede para acolhimento e resolução");
    }

    const summary = tone === "negative"
      ? `Reclamação identificada: "${text.substring(0, 100)}..."`
      : tone === "positive"
      ? `Feedback positivo recebido: "${text.substring(0, 100)}..."`
      : `Mensagem recebida: "${text.substring(0, 100)}..."`;

    return {
      score,
      tone,
      keywords: Array.from(new Set([...posKw, ...negKw])),
      positiveKeywords: Array.from(new Set(posKw)),
      negativeKeywords: Array.from(new Set(negKw)),
      suggestions,
      flatsMentioned: flats,
      summary,
      usingAI: false,
      fallbackReason: reason
    };
  };

  if (!apiKey) {
    return runHeuristicAnalysis("sem chave Gemini");
  }

  try {
    const prompt = `Você é um analista de experiência do cliente de um hotel boutique brasileiro chamado CorpFlats.\nAnalise o seguinte texto${ctx ? " (" + ctx + ")" : ""} e retorne um JSON estrito com os campos abaixo.\nTexto para análise: """${text}"""\n\nRetorne APENAS um JSON válido (sem markdown) no formato:\n{\n  "score": 82,\n  "tone": "positive",\n  "keywords": ["limpeza", "wi-fi", "ar condicionado"],\n  "positiveKeywords": ["impecável", "rápido", "confortável"],\n  "negativeKeywords": ["gotejando"],\n  "suggestions": ["Verificar ar condicionado do flat 304"],\n  "flatsMentioned": ["304"],\n  "summary": "Hóspede muito satisfeito, elogia limpeza e internet mas relata problema no AC"\n}\nOnde "score" é de 0 (péssimo) a 100 (excelente), "tone" é "positive", "neutral" ou "negative".`;

    const geminiResult = await callGeminiGenerateContent(apiKey, [{ parts: [{ text: prompt }] }]);

    if (geminiResult.ok) {
      const data = geminiResult.data;
      const rawText = data.candidates?.[0]?.content?.parts?.[0]?.text || "";
      const jsonMatch = rawText.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const parsed = JSON.parse(jsonMatch[0]);
        return {
          score: Number(parsed.score) || 65,
          tone: parsed.tone || "neutral",
          keywords: Array.isArray(parsed.keywords) ? Array.from(new Set(parsed.keywords.map(sanitizeKeyword).filter(w => w.length >= 3))) : [],
          positiveKeywords: Array.isArray(parsed.positiveKeywords) ? Array.from(new Set(parsed.positiveKeywords.map(sanitizeKeyword).filter(w => w.length >= 3))) : [],
          negativeKeywords: Array.isArray(parsed.negativeKeywords) ? Array.from(new Set(parsed.negativeKeywords.map(sanitizeKeyword).filter(w => w.length >= 3))) : [],
          suggestions: Array.isArray(parsed.suggestions) ? parsed.suggestions : [],
          flatsMentioned: Array.isArray(parsed.flatsMentioned) ? parsed.flatsMentioned : [],
          summary: parsed.summary || "",
          usingAI: true
        };
      }
    }
  } catch (err) {
    console.warn("[Sentiment AI]", err.message);
  }

  // Fallback para motor heurístico caso a API do Gemini esteja fora do ar ou com cota atingida
  return runHeuristicAnalysis("fallback por cota ou indisponibilidade da API Gemini");
}

// Inicializar estrutura de sentimentos se não existir e higienizar histórico
function ensureSentimentDB() {
  if (!db.guestSentiment) db.guestSentiment = [];
  if (!db.npsResponses) db.npsResponses = [];
  if (!db.whatsappInboundMessages) db.whatsappInboundMessages = [];

  let modified = false;
  for (const s of db.guestSentiment) {
    if (Array.isArray(s.negativeKeywords)) {
      const cleaned = Array.from(new Set(s.negativeKeywords.map(sanitizeKeyword).filter(w => w.length >= 3)));
      if (cleaned.length !== s.negativeKeywords.length || cleaned.some((w, i) => w !== s.negativeKeywords[i])) {
        s.negativeKeywords = cleaned;
        modified = true;
      }
    }
    if (Array.isArray(s.positiveKeywords)) {
      const cleaned = Array.from(new Set(s.positiveKeywords.map(sanitizeKeyword).filter(w => w.length >= 3)));
      if (cleaned.length !== s.positiveKeywords.length || cleaned.some((w, i) => w !== s.positiveKeywords[i])) {
        s.positiveKeywords = cleaned;
        modified = true;
      }
    }
  }
  if (Array.isArray(db.reviews)) {
    for (const r of db.reviews) {
      if (Array.isArray(r.negativeKeywords)) {
        const cleaned = Array.from(new Set(r.negativeKeywords.map(sanitizeKeyword).filter(w => w.length >= 3)));
        if (cleaned.length !== r.negativeKeywords.length || cleaned.some((w, i) => w !== r.negativeKeywords[i])) {
          r.negativeKeywords = cleaned;
          modified = true;
        }
      }
      if (Array.isArray(r.positiveKeywords)) {
        const cleaned = Array.from(new Set(r.positiveKeywords.map(sanitizeKeyword).filter(w => w.length >= 3)));
        if (cleaned.length !== r.positiveKeywords.length || cleaned.some((w, i) => w !== r.positiveKeywords[i])) {
          r.positiveKeywords = cleaned;
          modified = true;
        }
      }
    }
  }
  // Remove falsos positivos de NPS onde a pesquisa de satisfação nunca foi enviada ao telefone
  if (Array.isArray(db.npsResponses)) {
    const validNps = [];
    const removedPhones = new Set();
    const removedNames = new Set();
    for (const n of db.npsResponses) {
      if (!n) continue;
      const surveyInfo = getLatestNpsSurveySentInfo(db, n.guestPhone, { ignoreNpsResponsesTable: true });
      const isLegit = Boolean(surveyInfo.sent || n.manualEntry === true || n.surveyVerifiedSent === true || n.pendingResponse === true);
      if (!isLegit) {
        if (n.guestPhone) removedPhones.add(cleanWhatsAppPhone(n.guestPhone) || String(n.guestPhone).replace(/\D/g, ""));
        if (n.guestName && n.guestName !== "Hóspede") removedNames.add(String(n.guestName).trim());
        modified = true;
        continue;
      }
      if (surveyInfo.sent && !n.surveyVerifiedSent) {
        n.surveyVerifiedSent = true;
        modified = true;
      }
      // Enriquece nome do hóspede pela reserva caso esteja como "??" ou emoji
      const cPhone = cleanWhatsAppPhone(n.guestPhone || "") || String(n.guestPhone || "").replace(/\D/g, "");
      const resv = (db.reservations || []).find(r =>
        (n.reservationCode && String(r.code) === String(n.reservationCode)) ||
        (n.reservationId && String(r.id) === String(n.reservationId)) ||
        (surveyInfo.reservationCode && String(r.code) === String(surveyInfo.reservationCode)) ||
        (surveyInfo.reservationId && String(r.id) === String(surveyInfo.reservationId))
      ) || (db.reservations || []).find(r => {
        const rP = cleanWhatsAppPhone(r.guestPhone || r.phone || "") || String(r.guestPhone || r.phone || "").replace(/\D/g, "");
        return Boolean(rP && cPhone && rP.length >= 8 && (rP.endsWith(cPhone.slice(-8)) || cPhone.endsWith(rP.slice(-8))));
      });
      if (resv) {
        const bestName = resolveBestNpsGuestName(n.guestName, null, resv.guestName);
        if (bestName && bestName !== n.guestName) {
          n.guestName = bestName;
          modified = true;
        }
        if (!n.flatNumber && resv.flatNumber) {
          n.flatNumber = resv.flatNumber;
          modified = true;
        }
        if (!n.reservationCode && resv.code) {
          n.reservationCode = resv.code;
          modified = true;
        }
        if (!n.reservationId && resv.id) {
          n.reservationId = resv.id;
          modified = true;
        }
      }
      validNps.push(n);
    }
    if (validNps.length !== db.npsResponses.length) {
      db.npsResponses = validNps;
      if (Array.isArray(db.observations)) {
        db.observations = db.observations.filter(o => {
          if (!o) return false;
          const isNpsTicket = o.generatedFromNps || String(o.description || "").startsWith("[NPS Auto-Ticket]");
          if (!isNpsTicket) return true;
          const oPhone = cleanWhatsAppPhone(o.guestPhone || "") || String(o.guestPhone || "").replace(/\D/g, "");
          const phoneRemoved = oPhone && Array.from(removedPhones).some(rp => rp.length >= 8 && (oPhone.endsWith(rp.slice(-8)) || rp.endsWith(oPhone.slice(-8))));
          const nameRemoved = Array.from(removedNames).some(rn => rn.length >= 3 && String(o.description || "").includes(rn));
          return !(phoneRemoved || nameRemoved);
        });
      }
    }
  }
  if (modified) saveDatabase();
}

// 3B.1 — Visão geral de sentimento consolidada
app.get("/api/ai/sentiment/overview", (req, res) => {
  ensureSentimentDB();
  initDefaultReviews();

  const sentiment = db.guestSentiment || [];
  const npsResponses = db.npsResponses || [];
  const reviews = db.reviews || [];

  const wppAnalyzed = sentiment.filter(s => s.overallScore != null);
  const avgWppScore = wppAnalyzed.length > 0
    ? Math.round(wppAnalyzed.reduce((a, s) => a + (s.overallScore || 0), 0) / wppAnalyzed.length)
    : null;

  const wppPositive = wppAnalyzed.filter(s => s.overallTone === "positive").length;
  const wppNeutral = wppAnalyzed.filter(s => s.overallTone === "neutral").length;
  const wppNegative = wppAnalyzed.filter(s => s.overallTone === "negative").length;

  const npsTotal = npsResponses.length;
  const npsResponded = npsResponses.filter(n => n.score != null).length;
  const npsPromoters = npsResponses.filter(n => n.score === 5).length;
  const npsNeutrals = npsResponses.filter(n => n.score === 4 || n.score === 3).length;
  const npsDetractors = npsResponses.filter(n => n.score != null && n.score <= 2).length;
  const googleLinkSent = npsResponses.filter(n => n.googleLinkSent).length;
  const filterRate = npsResponded > 0 ? Math.round((npsPromoters / npsResponded) * 100) : null;

  const avgReviewScore = reviews.length > 0
    ? (reviews.reduce((a, r) => a + (r.rating || 5), 0) / reviews.length).toFixed(1)
    : 0;

  const kwFreq = {};
  const countKeywords = (list) => {
    if (!Array.isArray(list)) return;
    const seen = new Set();
    list.forEach(k => {
      const clean = sanitizeKeyword(k);
      if (clean && clean.length >= 3 && !seen.has(clean)) {
        seen.add(clean);
        kwFreq[clean] = (kwFreq[clean] || 0) + 1;
      }
    });
  };

  wppAnalyzed.forEach(s => countKeywords(s.negativeKeywords));
  reviews.forEach(r => countKeywords(r.negativeKeywords));

  const topNegativeKeywords = Object.entries(kwFreq)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
    .map(([word, count]) => ({ word, count }));

  res.json({
    whatsapp: { analyzed: wppAnalyzed.length, avgScore: avgWppScore, positive: wppPositive, neutral: wppNeutral, negative: wppNegative, positivePercent: wppAnalyzed.length > 0 ? Math.round((wppPositive / wppAnalyzed.length) * 100) : null },
    nps: { sent: npsTotal, responded: npsResponded, promoters: npsPromoters, neutrals: npsNeutrals, detractors: npsDetractors, googleLinkSent, filterRate },
    reviews: { total: reviews.length, avgScore: Number(avgReviewScore) },
    improvements: db.npsImprovements || { executiveSummary: "", pendingCount: 0, resolvedCount: 0, items: [] },
    topNegativeKeywords,
    lastUpdated: new Date().toISOString()
  });
});

// 3B.2 — Listar conversas WhatsApp com sentimento analisado
app.get("/api/ai/sentiment/whatsapp", (req, res) => {
  ensureSentimentDB();
  const { flatNumber, tone } = req.query;
  let list = db.guestSentiment || [];
  if (tone && tone !== "all") list = list.filter(s => s.overallTone === tone);
  if (flatNumber) list = list.filter(s => s.flatNumber === flatNumber);
  const enriched = list.map(s => {
    let reservation = (db.reservations || []).find(r => r.id === s.reservationId || String(r.id) === String(s.reservationId) || r.code === s.reservationId);
    if (!reservation && s.guestPhone) {
      const cleanP = s.guestPhone.replace(/\D/g, "");
      reservation = (db.reservations || []).find(r => {
        const rP = (r.guestPhone || r.phone || "").replace(/\D/g, "");
        return rP && (cleanP.endsWith(rP.slice(-8)) || rP.endsWith(cleanP.slice(-8)));
      });
    }
    const hasTicket = (db.observations || []).some(o => (o.guestPhone === s.guestPhone || o.description?.includes(s.guestPhone) || (s.guestName && o.description?.includes(s.guestName))) && o.status === "pendente");
    return {
      ...s,
      guestName: s.guestName || reservation?.guestName || "Hóspede",
      flatNumber: s.flatNumber || reservation?.flatNumber || reservation?.flat,
      checkoutDate: reservation?.checkoutDate,
      channel: reservation?.channel,
      hasMaintenanceTicket: hasTicket
    };
  });
  res.json({ sentiments: enriched });
});

// 3B.3 — Analisar TODAS as conversas WhatsApp com IA
app.post("/api/ai/sentiment/analyze-whatsapp", async (req, res) => {
  ensureSentimentDB();
  try {
    const reservations = db.reservations || [];
    const byPhone = {};

    // 1. Incorpora conversas do WhatsApp Web / Z-API
    const conversations = (db.whatsappConversations || []).filter(c => !c.isGroup);
    for (const conv of conversations) {
      const phone = conv.phone || conv.id;
      if (!phone) continue;
      if (!byPhone[phone]) {
        byPhone[phone] = {
          phone,
          messages: [],
          reservationId: conv.reservationId || conv.reservationCode,
          guestName: conv.name || "Hóspede",
          flatNumber: conv.flatNumber || null
        };
      } else {
        if (conv.flatNumber && !byPhone[phone].flatNumber) byPhone[phone].flatNumber = conv.flatNumber;
        if (conv.name && (!byPhone[phone].guestName || byPhone[phone].guestName === "Hóspede")) byPhone[phone].guestName = conv.name;
        if ((conv.reservationId || conv.reservationCode) && !byPhone[phone].reservationId) byPhone[phone].reservationId = conv.reservationId || conv.reservationCode;
      }
      for (const m of (conv.messages || [])) {
        const text = m.text || m.caption || "";
        if (!text.trim()) continue;
        const mTime = m.timestamp ? new Date(m.timestamp).toISOString() : new Date().toISOString();
        const already = byPhone[phone].messages.some(ex => ex.text === text && Math.abs(new Date(ex.at || 0).getTime() - new Date(mTime).getTime()) < 4000);
        if (!already) {
          byPhone[phone].messages.push({
            text,
            direction: m.fromMe ? "outbound" : "inbound",
            at: mTime
          });
        }
      }
    }

    // 2. Incorpora histórico de mensagens recebidas (Inbound)
    const inboundMsgs = db.whatsappInboundMessages || [];
    for (const msg of inboundMsgs) {
      const phone = msg.from || msg.phone;
      if (!phone) continue;
      if (!byPhone[phone]) byPhone[phone] = { phone, messages: [], guestName: msg.senderName || "Hóspede" };
      const text = msg.text || msg.body || "";
      if (!text.trim()) continue;
      const mTime = msg.receivedAt || msg.at || new Date().toISOString();
      const already = byPhone[phone].messages.some(ex => ex.text === text && Math.abs(new Date(ex.at || 0).getTime() - new Date(mTime).getTime()) < 4000);
      if (!already) {
        byPhone[phone].messages.push({ text, direction: "inbound", at: mTime });
      }
    }

    // 3. Incorpora histórico de mensagens enviadas (Dispatch)
    const dispatchHistory = db.whatsappDispatchHistory || [];
    for (const msg of dispatchHistory) {
      const phone = msg.guestPhone || msg.recipientPhone;
      if (!phone) continue;
      if (!byPhone[phone]) byPhone[phone] = { phone, messages: [], reservationId: msg.reservationId, guestName: msg.guestName || msg.recipientName };
      const text = msg.messageText || msg.message || "";
      if (!text.trim()) continue;
      const mTime = msg.sentAt || msg.scheduledAt || new Date().toISOString();
      const already = byPhone[phone].messages.some(ex => ex.text === text && Math.abs(new Date(ex.at || 0).getTime() - new Date(mTime).getTime()) < 4000);
      if (!already) {
        byPhone[phone].messages.push({ text, direction: "outbound", at: mTime });
      }
    }

    let analyzedCount = 0;
    const results = [];
    const force = Boolean(req.body?.force);

    for (const [phone, data] of Object.entries(byPhone)) {
      const inbounds = data.messages.filter(m => m.direction === "inbound");
      if (inbounds.length === 0) continue;
      const fullText = inbounds.map(m => m.text).join(" | ");
      if (!fullText.trim()) continue;

      const latestInboundAt = Math.max(...inbounds.map(m => new Date(m.at || 0).getTime()));
      const existing = (db.guestSentiment || []).find(s => s.guestPhone === phone);
      if (existing?.analyzedAt && !force) {
        const analyzedTime = new Date(existing.analyzedAt).getTime();
        const age = Date.now() - analyzedTime;
        if (latestInboundAt <= analyzedTime && age < 6 * 60 * 60 * 1000) {
          results.push(existing);
          continue;
        }
      }

      let reservation = reservations.find(r => r.id === data.reservationId || r.code === data.reservationId);
      if (!reservation) {
        const cleanP = phone.replace(/\D/g, "");
        reservation = reservations.find(r => {
          const rP = (r.guestPhone || r.phone || "").replace(/\D/g, "");
          return rP && (cleanP.endsWith(rP.slice(-8)) || rP.endsWith(cleanP.slice(-8)));
        });
      }

      const flatMatch = fullText.match(/(?:apto|apt|flat|quarto|unidade|su[ií]te)\s*[:#º°]?\s*(\d{2,4}[a-z]?)/i);
      const flatNumber = data.flatNumber || reservation?.flatNumber || reservation?.flat || (flatMatch ? flatMatch[1] : null);

      const analysis = await analyzeTextSentimentWithAI(fullText, "mensagens recebidas do hóspede via WhatsApp");

      const sentimentEntry = {
        id: existing?.id || ("sent_" + Date.now() + "_" + Math.random().toString(36).substring(2, 6)),
        guestPhone: phone,
        guestName: data.guestName || reservation?.guestName || "Hóspede",
        reservationId: data.reservationId || reservation?.id,
        flatNumber: flatNumber || null,
        overallScore: analysis.score,
        overallTone: analysis.tone,
        positiveKeywords: analysis.positiveKeywords || [],
        negativeKeywords: analysis.negativeKeywords || [],
        keywords: analysis.keywords || [],
        suggestions: analysis.suggestions || [],
        summary: analysis.summary,
        messageCount: data.messages.length,
        inboundCount: inbounds.length,
        analyzedAt: new Date().toISOString(),
        usingAI: analysis.usingAI
      };

      const idx = (db.guestSentiment || []).findIndex(s => s.guestPhone === phone);
      if (idx >= 0) db.guestSentiment[idx] = sentimentEntry;
      else {
        if (!db.guestSentiment) db.guestSentiment = [];
        db.guestSentiment.unshift(sentimentEntry);
      }

      // Detecção Estrita de Defeito Físico do Flat -> Sugestão de Manutenção da IA em db.observations
      const extractedDefect = flatNumber ? extractStrictMaintenanceDefectFromText(fullText) : null;
      if (extractedDefect && flatNumber) {
        const flatObj = (db.flats || []).find(f => String(f.number) === String(flatNumber));
        if (flatObj) {
          if (!db.observations) db.observations = [];
          const cleanP = String(phone || "").replace(/\D/g, "");
          const dedupKey = `${flatObj.number}_${extractedDefect.specialty}_${cleanP}`;
          const dismissed = Array.isArray(db.dismissedAiSuggestionKeys) && db.dismissedAiSuggestionKeys.includes(dedupKey);
          const alreadyHasTicket = db.observations.some(o => o.dedupKey === dedupKey);
          if (!alreadyHasTicket && !dismissed) {
            const obsId = db.observations.length > 0 ? Math.max(...db.observations.map(o => Number(o.id) || 0)) + 1 : 1;
            db.observations.push({
              id: obsId,
              flatId: Number(flatObj.id),
              flatNumber: String(flatObj.number),
              category: "manutencao",
              specialty: extractedDefect.specialty,
              text: extractedDefect.text,
              guestQuote: extractedDefect.guestQuote,
              guestName: sentimentEntry.guestName || "Hóspede",
              guestPhone: phone,
              authorUsername: `🤖 IA (${sentimentEntry.guestName || "Hóspede"})`,
              sourceLabel: "WhatsApp do Hóspede",
              isAiSuggestion: true,
              dedupKey,
              status: "sugestao_ia",
              workflowStage: "ai_suggestion",
              isRentalBlocker: false,
              assignedTo: "unassigned",
              photos: [],
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString()
            });
          }
        }
      }

      // Detecção de Resposta NPS (1 a 5) — ESTRITO: somente se a pesquisa NPS foi efetivamente enviada a este telefone
      const lastInboundText = inbounds.slice(-1)[0]?.text?.trim() || "";
      const npsMatch = lastInboundText.match(/^([1-5])$/) || lastInboundText.match(/^nota\s*([1-5])$/i);
      const surveyInfo = npsMatch ? getLatestNpsSurveySentInfo(db, phone) : { sent: false };
      if (npsMatch && surveyInfo.sent) {
        const npsScore = Number(npsMatch[1]);
        if (!db.npsResponses) db.npsResponses = [];
        let npsItem = db.npsResponses.find(n => n.guestPhone === phone);
        // Só registra se ainda não havia resposta gravada para esta pesquisa
        if (!npsItem || npsItem.score == null || npsItem.pendingResponse === true) {
          if (!npsItem) {
            npsItem = {
              id: `nps_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
              guestPhone: phone,
              guestName: resolveBestNpsGuestName(sentimentEntry.guestName, null, reservation?.guestName),
              sentAt: surveyInfo.sentAt || new Date().toISOString(),
              surveyVerifiedSent: true
            };
            db.npsResponses.unshift(npsItem);
          }
          npsItem.score = npsScore;
          npsItem.respondedAt = new Date().toISOString();
          npsItem.pendingResponse = false;
          npsItem.surveyVerifiedSent = true;
          npsItem.flatNumber = flatNumber || npsItem.flatNumber;
          if (npsScore === 5) {
            npsItem.autoAction = "google_link_sent";
            npsItem.googleLinkSent = true;
          } else if (npsScore <= 2) {
            npsItem.autoAction = "recovery_ticket_created";
          } else {
            npsItem.autoAction = "feedback_collected";
          }
        }
      }

      results.push(sentimentEntry);
      analyzedCount++;
    }

    saveDatabase();
    res.json({ success: true, analyzed: analyzedCount, results });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 3B.4 — Registrar resposta NPS de hóspede
app.post("/api/ai/nps-response", async (req, res) => {
  ensureSentimentDB();
  try {
    const { reservationId, guestPhone, guestName, score, comment, flatNumber, channel } = req.body;
    if (!reservationId && !guestPhone) return res.status(400).json({ error: "reservationId ou guestPhone são obrigatórios." });

    const numScore = Number(score);
    let googleLinkSent = numScore === 5;
    let autoAction = numScore === 5 ? "google_link_sent" : numScore >= 3 ? "feedback_collected" : "recovery_ticket_created";

    if (numScore <= 2) {
      if (!db.observations) db.observations = [];
      const obsId = db.observations.length > 0 ? Math.max(...db.observations.map(o => o.id || 0)) + 1 : 1;
      db.observations.push({ id: obsId, flatNumber: flatNumber || "N/A", type: "reclamacao", description: "[NPS Auto-Ticket] Hóspede " + (guestName || guestPhone) + " deu nota " + numScore + "/5 na pesquisa pós-checkout. Comentário: \"" + (comment || "Sem comentário") + "\". Entrar em contato para recuperação.", severity: numScore === 1 ? "alta" : "media", status: "pendente", createdAt: new Date().toISOString(), generatedFromNps: true });
    }

    let sentimentAnalysis = null;
    if (comment && comment.trim().length > 5) sentimentAnalysis = await analyzeTextSentimentWithAI(comment, "feedback NPS pós-checkout");

    const npsEntry = {
      id: "nps_" + Date.now() + "_" + Math.random().toString(36).substring(2, 5),
      reservationId: reservationId || null, guestPhone: guestPhone || null, guestName: guestName || "Hóspede",
      flatNumber: flatNumber || null, channel: channel || null, score: numScore, comment: comment || null,
      sentAt: new Date().toISOString(), respondedAt: new Date().toISOString(),
      googleLinkSent, autoAction, pendingResponse: false,
      manualEntry: true, surveyVerifiedSent: true,
      sentimentScore: sentimentAnalysis?.score || null, sentimentTone: sentimentAnalysis?.tone || null,
      sentimentSummary: sentimentAnalysis?.summary || null
    };

    const idx = (db.npsResponses || []).findIndex(n => String(n.reservationId) === String(reservationId) || n.guestPhone === guestPhone);
    let targetNpsEntry = npsEntry;
    if (idx >= 0) {
      db.npsResponses[idx] = { ...db.npsResponses[idx], ...npsEntry, id: db.npsResponses[idx].id };
      targetNpsEntry = db.npsResponses[idx];
    } else {
      db.npsResponses.unshift(npsEntry);
    }

    let improvements = null;
    if (numScore <= 4) {
      if (comment && String(comment).trim()) {
        syncNpsCommentToReviews(db, targetNpsEntry);
      }
      improvements = await rebuildNpsImprovementsSummary(db);
      await sendNpsManagerAlertWhatsApp(db, targetNpsEntry, {
        reason: "manual_or_portal_nps_response",
        saveDatabase
      });
    }

    // [Feature F2 Hook Point 4: Resposta NPS via Portal/API]
    invokeMaidReviewHookSafe(db, {
      hookType: "portal_or_api_nps_response",
      npsItem: targetNpsEntry,
      score: numScore,
      comment: comment || null,
      reservationId: reservationId || null,
      flatNumber: targetNpsEntry.flatNumber,
      guestPhone: targetNpsEntry.guestPhone,
      guestName: targetNpsEntry.guestName,
      respondedAt: targetNpsEntry.respondedAt
    }, { saveDatabase }).catch(e => console.warn("[Hook 4 Non-Blocking]", e?.message));

    saveDatabase();
    res.json({ success: true, npsEntry: targetNpsEntry, googleLinkSent, autoAction, improvements });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

