// MÓDULO 7: INTEGRAÇÃO OFICIAL MERCADO PAGO (CARTÃO DE CRÉDITO & CHECKOUT PRO)
// ══════════════════════════════════════════════════════════════════════════════

const DEFAULT_MP_CONFIG = {
  accessToken: process.env.MERCADOPAGO_ACCESS_TOKEN || "",
  publicKey: process.env.MERCADOPAGO_PUBLIC_KEY || "",
  clientId: process.env.MERCADOPAGO_CLIENT_ID || "",
  clientSecret: process.env.MERCADOPAGO_CLIENT_SECRET || "",
  isConfigured: Boolean(process.env.MERCADOPAGO_ACCESS_TOKEN),
  sandbox: process.env.MERCADOPAGO_SANDBOX === "true"
};


async function createMercadoPagoPreference({
  reservationCode,
  amount,
  guestName,
  guestEmail,
  nights,
  flatNumber,
  customTitle,
  customDescription,
  customBackUrls,
  isMinibar
}) {
  const cfg = db.settings?.mercadoPagoConfig || DEFAULT_MP_CONFIG;
  const accessToken = cfg.accessToken || DEFAULT_MP_CONFIG.accessToken;

  if (!accessToken) {
    throw new Error("Access Token do Mercado Pago não configurado. Por favor, adicione suas credenciais no painel de configurações.");
  }

  const isMinibarOrder = Boolean(isMinibar) || String(reservationCode || "").startsWith("MB-");
  const defaultTitle = isMinibarOrder
    ? `Consumo de Frigobar - Flat ${flatNumber || "Soho"} (CorpFlats)`
    : `Hospedagem CorpFlats - Flat ${flatNumber || "Studio"} (${nights || 1} ${nights === 1 ? "diária" : "diárias"})`;
  const defaultDescription = isMinibarOrder
    ? `Consumo de itens de frigobar no Flat ${flatNumber || "Soho"} - Edifício Soho Residence.`
    : `Locação por temporada autônoma no Edifício Soho Residence.`;

  const payload = {
    items: [
      {
        id: reservationCode || `RES-${Date.now()}`,
        title: customTitle || defaultTitle,
        description: customDescription || defaultDescription,
        category_id: isMinibarOrder ? "food" : "services",
        quantity: 1,
        currency_id: "BRL",
        unit_price: Number(amount)
      }
    ],
    payer: {
      name: (guestName || "Hóspede CorpFlats").substring(0, 100),
      email: (guestEmail || "reservas@corpflats.com.br").trim()
    },
    back_urls: customBackUrls || {
      success: `https://corpflats.com.br/minha-reserva/${reservationCode}?payment=success`,
      failure: `https://corpflats.com.br?payment=failure`,
      pending: `https://corpflats.com.br/minha-reserva/${reservationCode}?payment=pending`
    },
    auto_return: "approved",
    external_reference: reservationCode,
    statement_descriptor: "CORPFLATS",
    notification_url: "https://corpflats.com.br/api/pms/mercadopago/webhook",
    payment_methods: {
      excluded_payment_types: [
        { id: "ticket" },
        { id: "bank_transfer" },
        { id: "atm" },
        { id: "debit_card" },
        { id: "digital_currency" },
        { id: "digital_wallet" }
      ],
      default_payment_method_id: null,
      installments: 12,
      default_installments: 1
    }
  };

  const bodyStr = JSON.stringify(payload);

  return new Promise((resolve, reject) => {
    const req = https.request("https://api.mercadopago.com/checkout/preferences", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${accessToken}`,
        "Content-Type": "application/json",
        "Content-Length": Buffer.byteLength(bodyStr)
      }
    }, (res) => {
      let raw = "";
      res.on("data", c => raw += c);
      res.on("end", () => {
        try {
          const json = JSON.parse(raw);
          if (res.statusCode === 200 || res.statusCode === 201) {
            resolve({
              id: json.id,
              initPoint: json.init_point,
              sandboxInitPoint: json.sandbox_init_point
            });
          } else {
            reject(new Error(json.message || json.error || raw));
          }
        } catch (e) {
          reject(new Error(`Falha ao parsear retorno Mercado Pago: ${raw}`));
        }
      });
    });

    req.on("error", reject);
    req.write(bodyStr);
    req.end();
  });
}
globalThis.createInterPixCob = createInterPixCob;
globalThis.triggerGarageEmailNotification = triggerGarageEmailNotification;

// 7.1 Criar Preferência de Pagamento no Mercado Pago
app.post("/api/pms/mercadopago/create-preference", async (req, res) => {
  try {
    const { reservationCode, amount, guestName, guestEmail, nights, flatNumber } = req.body;
    const r = reservationCode
      ? (db.reservations || []).find(x => x.code === reservationCode || String(x.id) === reservationCode)
      : null;

    let chargeAmount = Number(amount) || 0;
    if (r && !String(reservationCode || "").startsWith("MB-")) {
      const pendingAmt = Math.max(0, (Number(r.totalAmount) || 0) - (Number(r.paidAmount) || 0)) || Number(r.totalAmount) || chargeAmount;
      chargeAmount = computeCardAmountFromPix(pendingAmt);
    }

    if (!chargeAmount || Number(chargeAmount) <= 0) {
      return res.status(400).json({ error: "Valor da reserva é obrigatório." });
    }

    const pref = await createMercadoPagoPreference({
      reservationCode,
      amount: chargeAmount,
      guestName: guestName || r?.guestName,
      guestEmail: guestEmail || r?.guestEmail,
      nights,
      flatNumber: flatNumber || r?.flatNumber
    });

    if (r) {
      r.mpPreferenceId = pref.id;
      r.mpInitPoint = pref.initPoint;
      r.mpChargedAmount = chargeAmount;
      saveDatabase();
    }

    res.json({
      success: true,
      initPoint: pref.initPoint,
      preferenceId: pref.id,
      amount: chargeAmount
    });
  } catch (err) {
    console.error("[Mercado Pago] Erro ao criar preferência:", err.message);
    res.status(500).json({ error: err.message });
  }
});

// 7.2 Webhook Oficial do Mercado Pago
app.post("/api/pms/mercadopago/webhook", async (req, res) => {
  try {
    const { type, topic, data, id } = req.body || {};
    const queryId = req.query["data.id"] || req.query.id || (data && data.id) || id;
    const actionType = type || topic || req.query.type || req.query.topic;

    console.log(`[Mercado Pago Webhook] Notificação recebida: ${actionType} ID: ${queryId}`);

    if (actionType === "payment" && (queryId || data?.external_reference || req.body?.external_reference)) {
      const cfg = db.settings?.mercadoPagoConfig || DEFAULT_MP_CONFIG;
      const accessToken = cfg.accessToken || process.env.MERCADOPAGO_ACCESS_TOKEN;

      let paymentRes = null;
      if (accessToken && queryId) {
        paymentRes = await new Promise((resolve) => {
          const req = https.request(`https://api.mercadopago.com/v1/payments/${queryId}`, {
            method: "GET",
            headers: { "Authorization": `Bearer ${accessToken}` }
          }, (resp) => {
            let r = "";
            resp.on("data", c => r += c);
            resp.on("end", () => {
              try { resolve(JSON.parse(r)); } catch { resolve(null); }
            });
          });
          req.on("error", () => resolve(null));
          req.end();
        });
      }

      const directExtRef = data?.external_reference || req.body?.external_reference || req.body?.payment?.external_reference;
      const directStatus = data?.status || req.body?.status || req.body?.payment?.status;
      const paymentFound = Boolean(paymentRes && paymentRes.id && typeof paymentRes.status === "string");
      const isApproved = (paymentFound && paymentRes.status === "approved") ||
        (!paymentFound && directExtRef && (directStatus === "approved" || directStatus === "pago"));

      if (isApproved) {
        const resCode = (paymentFound ? paymentRes.external_reference : null) || directExtRef;
        const valorPago = (paymentFound ? (paymentRes.transaction_amount || paymentRes.total_paid_amount) : null) ||
          Number(data?.transaction_amount || req.body?.transaction_amount || req.body?.amount) ||
          null;
        const dateApproved = (paymentFound ? paymentRes.date_approved : null) || new Date().toISOString();
        const effectivePaymentId = String((paymentFound ? paymentRes.id : null) || queryId || data?.id || id || `MP_LOCAL_${Date.now()}`);

        if (resCode) {
          if (resCode.startsWith("MB-")) {
            const orderId = resCode.replace(/^MB-/, "");
            const mbOrder = (db.minibarOrders || []).find(o => o.id === orderId || o.id === resCode);
            if (mbOrder && mbOrder.paymentStatus !== "pago") {
              const paidAmt = valorPago || mbOrder.totalAmount;
              if (typeof settleMinibarOrder === "function") {
                settleMinibarOrder(mbOrder, {
                  paidAt: dateApproved,
                  mpPaymentId: effectivePaymentId,
                  paymentMethod: mbOrder.paymentMethod === "cartao_credito" ? "cartao_credito" : "credit_card",
                  amount: paidAmt,
                  source: "mercadopago_webhook"
                });
              } else {
                mbOrder.paymentStatus = "pago";
                mbOrder.paidAt = dateApproved;
                mbOrder.mpPaymentId = effectivePaymentId;
                mbOrder.paymentMethod = mbOrder.paymentMethod === "cartao_credito" ? "cartao_credito" : "credit_card";
                saveDatabase();
              }
            }
          } else {
            const r = (db.reservations || []).find(resItem => resItem.code === resCode || String(resItem.id) === resCode);
            if (r) {
              await confirmReservationPayment(r, {
                amount: valorPago || r.totalAmount,
                paidAt: dateApproved,
                mpPaymentId: effectivePaymentId,
                paymentMethod: "cartao_credito",
                source: "Mercado Pago Webhook"
              });
            }
          }
        }
      }
    }

    res.status(200).send("OK");
  } catch (err) {
    console.error("[Mercado Pago Webhook] Erro:", err);
    res.status(500).json({ error: err.message });
  }
});

