app.put("/api/minibar/default-stock", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarAdmin(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito à administração." });
    }

    const { globalTemplate, flatOverrides, flatNumber, items } = req.body || {};
    if (!db.minibarDefaultStock) db.minibarDefaultStock = getDefaultMinibarStock();

    if (Array.isArray(globalTemplate)) {
      db.minibarDefaultStock.globalTemplate = globalTemplate.map(it => ({
        productId: it.productId,
        defaultQuantity: Number(it.defaultQuantity ?? it.quantity ?? 0),
        quantity: Number(it.quantity ?? it.defaultQuantity ?? 0)
      }));
    }
    if (flatOverrides && typeof flatOverrides === "object") {
      db.minibarDefaultStock.flatOverrides = flatOverrides;
    }
    if (flatNumber && Array.isArray(items)) {
      if (!db.minibarDefaultStock.flatOverrides) db.minibarDefaultStock.flatOverrides = {};
      db.minibarDefaultStock.flatOverrides[String(flatNumber)] = items.map(it => ({
        productId: it.productId,
        defaultQuantity: Number(it.defaultQuantity ?? it.quantity ?? 0),
        quantity: Number(it.quantity ?? it.defaultQuantity ?? 0)
      }));
    }
    saveDatabase("minibar_default_stock_updated");
    res.json({ success: true, defaultStock: db.minibarDefaultStock });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── Helpers de Múltiplos Hóspedes no Flat, Quitação Automática & Monitoramento de NF ──

function getReservationAllGuests(reservation) {
  if (!reservation) return [];
  const list = [];
  const crmGuests = Array.isArray(db.guests) ? db.guests : [];
  const fnrhDocs = Array.isArray(db.fnrhAuditDocuments)
    ? db.fnrhAuditDocuments.filter(
        d =>
          d &&
          ((reservation.code && d.reservationCode === reservation.code) ||
            (reservation.id && String(d.reservationId) === String(reservation.id)))
      )
    : [];

  // 1. Hóspede Titular (Slot 1)
  const primarySlot = Array.isArray(reservation.guests)
    ? reservation.guests.find(g => Number(g?.index || g?.order || 1) === 1) ||
      (!reservation.guests[0]?.index && !reservation.guests[0]?.order ? reservation.guests[0] : null)
    : null;
  const primarySplitSlot = Array.isArray(reservation.minibarSplitConfig?.guests)
    ? reservation.minibarSplitConfig.guests.find(g => Number(g?.index || 1) === 1)
    : null;
  const primaryCrm = crmGuests.find(cg =>
    (reservation.guestId && Number(cg.id) === Number(reservation.guestId)) ||
    (primarySlot?.guestId && Number(cg.id) === Number(primarySlot.guestId)) ||
    (reservation.guestDocument && String(cg.document || cg.documentNumber || "").replace(/\D/g, "") === String(reservation.guestDocument).replace(/\D/g, ""))
  );
  const primaryFnrh =
    primarySlot?.fnrhAuditTrail ||
    reservation.fnrhAuditTrail ||
    fnrhDocs.find(d => !d.guestIndex || Number(d.guestIndex) === 1) ||
    fnrhDocs[0] ||
    null;

  const primaryName = (
    reservation.guestName ||
    primarySlot?.name ||
    primarySplitSlot?.name ||
    primaryFnrh?.guestFullName ||
    primaryCrm?.name ||
    "Hóspede Titular"
  ).trim();
  const primaryPhone = (
    reservation.guestPhone ||
    primarySlot?.phone ||
    primarySlot?.whatsapp ||
    primarySplitSlot?.phone ||
    primaryFnrh?.guestPhone ||
    primaryCrm?.phone ||
    ""
  ).trim();
  const primaryEmail = (
    reservation.guestEmail ||
    primarySlot?.email ||
    primarySplitSlot?.email ||
    primaryFnrh?.guestEmail ||
    primaryCrm?.email ||
    ""
  ).trim();
  const primaryDoc = (
    reservation.guestDocument ||
    primarySlot?.cpf ||
    primarySlot?.document ||
    primarySplitSlot?.cpf ||
    primarySplitSlot?.document ||
    primaryFnrh?.guestCpf ||
    primaryCrm?.document ||
    primaryCrm?.documentNumber ||
    ""
  ).trim();

  list.push({
    index: 1,
    role: "titular",
    label: `${primaryName.split(" ")[0]} (1º Hóspede / Titular)`,
    guestId: reservation.guestId || primarySlot?.guestId || primaryCrm?.id || null,
    name: primaryName,
    firstName: primaryName.split(" ")[0] || "Hóspede",
    phone: primaryPhone,
    email: primaryEmail,
    cpf: primaryDoc,
    document: primaryDoc
  });

  // 2. Acompanhantes (2º, 3º hóspedes da reserva / FNRH / divisão do frigobar)
  const rawGuestsArr = Array.isArray(reservation.guests) ? reservation.guests : [];
  const splitSavedGuests = Array.isArray(reservation.minibarSplitConfig?.guests)
    ? reservation.minibarSplitConfig.guests
    : [];
  const fnrhHistoryArr = Array.isArray(reservation.fnrhHistory) ? reservation.fnibarFnrh || reservation.fnrhHistory : [];
  const maxRawIdx = rawGuestsArr.reduce((m, g, idx) => Math.max(m, Number(g?.index || g?.order || idx + 1) || 1), 1);
  const maxSplitIdx = splitSavedGuests.reduce((m, g, idx) => Math.max(m, Number(g?.index || idx + 1) || 1), 1);
  const maxFnrhIdx = fnrhHistoryArr.reduce((m, f, idx) => Math.max(m, Number(f?.guestIndex || f?.index || idx + 1) || 1), 1);

  const totalSlots = Math.max(
    Number(reservation.numGuests || reservation.guestsCount || 1),
    rawGuestsArr.length,
    fnrhDocs.length,
    maxRawIdx,
    maxSplitIdx,
    maxFnrhIdx
  );

  for (let i = 2; i <= totalSlots; i++) {
    const rawSlot =
      rawGuestsArr.find(g => Number(g?.index || g?.order) === i) ||
      (rawGuestsArr[i - 1] && !rawGuestsArr[i - 1]?.index && !rawGuestsArr[i - 1]?.order ? rawGuestsArr[i - 1] : null);
    const splitSlot = splitSavedGuests.find(g => Number(g?.index) === i) || null;
    const compSlot = rawSlot || splitSlot ? { ...(splitSlot || {}), ...(rawSlot || {}) } : null;
    const compFnrh =
      compSlot?.fnrhAuditTrail ||
      fnrhDocs.find(d => Number(d?.guestIndex || d?.index) === i) ||
      fnrhDocs[i - 1] ||
      (Array.isArray(reservation.fnrhHistory)
        ? reservation.fnrhHistory.find(
            f => Number(f?.guestIndex || f?.index) === i
          )
        : null) ||
      null;
    const compDocClean = String(
      compSlot?.cpf || compSlot?.document || compFnrh?.guestCpf || compFnrh?.cpf || compFnrh?.document || ""
    ).replace(/\D/g, "");
    const compPhoneClean = String(
      compSlot?.phone || compSlot?.whatsapp || compFnrh?.guestPhone || compFnrh?.phone || ""
    ).replace(/\D/g, "");
    const compCrm = crmGuests.find(cg =>
      (compSlot?.guestId && Number(cg.id) === Number(compSlot.guestId)) ||
      (compDocClean.length >= 8 && String(cg.document || cg.documentNumber || "").replace(/\D/g, "") === compDocClean) ||
      (compPhoneClean.length >= 8 && String(cg.phone || "").replace(/\D/g, "") === compPhoneClean)
    );

    const compName = (
      compSlot?.name ||
      compFnrh?.guestFullName ||
      compFnrh?.fullName ||
      compFnrh?.name ||
      compCrm?.name ||
      `${i}º Hóspede (Acompanhante)`
    ).trim();
    const compPhone = (
      compSlot?.phone ||
      compSlot?.whatsapp ||
      compFnrh?.guestPhone ||
      compFnrh?.phone ||
      compCrm?.phone ||
      ""
    ).trim();
    const compEmail = (
      compSlot?.email ||
      compFnrh?.guestEmail ||
      compFnrh?.email ||
      compCrm?.email ||
      ""
    ).trim();
    const compDoc = (
      compSlot?.cpf ||
      compSlot?.document ||
      compFnrh?.guestCpf ||
      compFnrh?.cpf ||
      compFnrh?.document ||
      compCrm?.document ||
      compCrm?.documentNumber ||
      ""
    ).trim();

    list.push({
      index: i,
      role: "acompanhante",
      label: /^h[óo]spede\s*\d+/i.test(compName) || /^\d+º\s*h[óo]spede/i.test(compName)
        ? `${i}º Hóspede (Acompanhante)`
        : `${compName.split(" ")[0]} (${i}º Hóspede)`,
      guestId: compSlot?.guestId || compCrm?.id || null,
      name: compName,
      firstName:
        /^h[óo]spede\s*\d+/i.test(compName) || /^\d+º\s*h[óo]spede/i.test(compName)
          ? `${i}º Hóspede`
          : compName.split(" ")[0] || `Hóspede ${i}`,
      phone: compPhone,
      email: compEmail,
      cpf: compDoc,
      document: compDoc
    });
  }

  return list;
}

function normalizeMinibarSplitMode(rawMode) {
  const m = String(rawMode || "").trim().toLowerCase();
  if (m === "half_and_half" || m === "equal_split" || m === "meio_a_meio" || m === "50_50") {
    return "half_and_half";
  }
  if (m === "by_item" || m === "items" || m === "por_item") {
    return "by_item";
  }
  return "titular";
}

function computeReservationMinibarSplit(
  reservation,
  pendingLaunchedItems = [],
  pendingBalance = 0,
  reservationGuests = [],
  options = {}
) {
  const paidOrders = Array.isArray(options?.paidOrders) ? options.paidOrders : [];
  const rawConfig = (reservation && typeof reservation.minibarSplitConfig === "object" && reservation.minibarSplitConfig)
    ? reservation.minibarSplitConfig
    : {};
  const mode = normalizeMinibarSplitMode(rawConfig.mode);
  const itemAssignments = (rawConfig.itemAssignments && typeof rawConfig.itemAssignments === "object")
    ? rawConfig.itemAssignments
    : {};

  // Lista base de hóspedes do flat
  const guests = Array.isArray(reservationGuests) && reservationGuests.length > 0
    ? reservationGuests.map(g => ({
        ...g,
        cpf: g.cpf || g.document || "",
        document: g.document || g.cpf || ""
      }))
    : [
        {
          index: 1,
          role: "titular",
          label: "1º Hóspede (Titular)",
          guestId: reservation?.guestId || null,
          name: reservation?.guestName || "Hóspede Titular",
          firstName: (reservation?.guestName || "Hóspede").trim().split(" ")[0],
          phone: reservation?.guestPhone || "",
          email: reservation?.guestEmail || "",
          cpf: reservation?.guestDocument || "",
          document: reservation?.guestDocument || ""
        }
      ];

  // Se o modo de divisão for "half_and_half" (Meio a Meio) ou "by_item" (Marcar por Item)
  // e houver apenas 1 hóspede listado, garante o 2º slot para permitir a marcação/divisão imediata
  if ((mode === "half_and_half" || mode === "by_item") && guests.length < 2) {
    guests.push({
      index: 2,
      role: "acompanhante",
      label: "2º Hóspede (Acompanhante)",
      guestId: null,
      name: "2º Hóspede (Acompanhante)",
      firstName: "2º Hóspede",
      phone: "",
      email: "",
      cpf: "",
      document: ""
    });
  }

  const enrichedGuests = guests.map(g => {
    const isPlaceholderName = !g.name || /^h[óo]spede\s*\d*/i.test(g.name) || /^\d+º\s*h[óo]spede/i.test(g.name);
    const cleanDoc = String(g.cpf || g.document || "").replace(/\D/g, "");
    const cleanPhone = String(g.phone || "").replace(/\D/g, "");
    const isMissingFiscalData = Boolean(isPlaceholderName || cleanPhone.length < 10 || cleanDoc.length < 11);
    return {
      ...g,
      isPlaceholderName,
      isMissingFiscalData
    };
  });

  const cleanPendingBalance = Number(Math.max(0, Number(pendingBalance) || 0).toFixed(2));
  const itemAllocationByKey = {};

  // Pagamentos já efetuados por índice de hóspede (abate cotas já quitadas individualmente)
  const paidAmountByGuestIndex = {};
  const paidUnitsByItemAndGuest = {};
  let totalLaunchPaidAmount = 0;

  for (const pOrd of paidOrders) {
    if (!pOrd) continue;
    const isLaunchSettlement =
      Boolean(pOrd.settlesLaunchOrders) ||
      Boolean(pOrd.isAutoSplitCheckoutOrder) ||
      pOrd.source === "restocker_launch" ||
      pOrd.source === "anserve_discrepancy" ||
      String(pOrd.id || "").startsWith("ORD-MB-DIV-") ||
      String(pOrd.id || "").startsWith("ORD-MB-LANC-") ||
      String(pOrd.id || "").startsWith("ORD-MB-SPLIT-");
    if (!isLaunchSettlement) continue;

    const pGuestIdx = Number(pOrd.guestIndex || 1);
    const pAmt = Number(pOrd.totalAmount || 0);
    paidAmountByGuestIndex[pGuestIdx] = Number(((paidAmountByGuestIndex[pGuestIdx] || 0) + pAmt).toFixed(2));
    totalLaunchPaidAmount = Number((totalLaunchPaidAmount + pAmt).toFixed(2));

    const selList =
      Array.isArray(pOrd.selectedLaunchItems) && pOrd.selectedLaunchItems.length > 0
        ? pOrd.selectedLaunchItems
        : Array.isArray(pOrd.items)
        ? pOrd.items
        : [];
    for (const sIt of selList) {
      if (!sIt || sIt.productId === "split_share" || sIt.productId === "partial_payment") continue;
      const sQty = Number(sIt.quantity) || 0;
      if (sQty <= 0) continue;
      const k = sIt.itemKey || (sIt.launchOrderId ? `${sIt.launchOrderId}::${sIt.productId}` : sIt.productId);
      if (!paidUnitsByItemAndGuest[k]) paidUnitsByItemAndGuest[k] = {};
      paidUnitsByItemAndGuest[k][pGuestIdx] = (paidUnitsByItemAndGuest[k][pGuestIdx] || 0) + sQty;
    }
  }

  const sharesMap = new Map();
  for (const g of enrichedGuests) {
    const alreadyPaidAmt = Number((paidAmountByGuestIndex[g.index] || 0).toFixed(2));
    sharesMap.set(g.index, {
      guestIndex: g.index,
      guestId: g.guestId || null,
      guestName: g.name,
      firstName: g.firstName,
      phone: g.phone || "",
      email: g.email || "",
      cpf: g.cpf || "",
      document: g.document || "",
      role: g.index === 1 ? "titular" : "acompanhante",
      isTitular: g.index === 1,
      isPlaceholderName: g.isPlaceholderName,
      isMissingFiscalData: g.isMissingFiscalData,
      amount: 0,
      grossAmount: 0,
      paidAmount: alreadyPaidAmt,
      isSharePaid: false,
      itemsCount: 0,
      items: [],
      orderItems: [],
      selectedLaunchItems: [],
      unassignedFallbackItems: []
    });
  }

  if (mode === "half_and_half") {
    const activeGuests = enrichedGuests.length >= 2 ? enrichedGuests : enrichedGuests.slice(0, 1);
    const parts = Math.max(1, activeGuests.length);
    const grossStayTotal = Number((cleanPendingBalance + totalLaunchPaidAmount).toFixed(2));
    const grossTotalCents = Math.round(grossStayTotal * 100);
    const grossBaseCents = Math.floor(grossTotalCents / parts);
    const grossRemCents = grossTotalCents - grossBaseCents * parts;
    const pendingCents = Math.round(cleanPendingBalance * 100);

    const rawRemainingCentsByGuest = [];
    let sumRawRemCents = 0;

    activeGuests.forEach((g, idx) => {
      const grossCents = grossBaseCents + (idx === 0 ? grossRemCents : 0);
      const paidCents = Math.round((paidAmountByGuestIndex[g.index] || 0) * 100);
      const remCents = Math.max(0, grossCents - paidCents);
      rawRemainingCentsByGuest.push({ guestIndex: g.index, grossCents, paidCents, remCents });
      sumRawRemCents += remCents;
    });

    // Ajusta eventual diferença residual para que a soma das cotas pendentes feche exatamente com cleanPendingBalance
    let diffCents = pendingCents - sumRawRemCents;
    if (diffCents !== 0 && rawRemainingCentsByGuest.length > 0) {
      const targetEntry =
        rawRemainingCentsByGuest.find(r => r.remCents > 0 && r.paidCents === 0) ||
        rawRemainingCentsByGuest.find(r => r.remCents + diffCents >= 0) ||
        rawRemainingCentsByGuest[0];
      if (targetEntry) {
        targetEntry.remCents = Math.max(0, targetEntry.remCents + diffCents);
      }
    }

    rawRemainingCentsByGuest.forEach(entry => {
      const shareEntry = sharesMap.get(entry.guestIndex);
      if (!shareEntry) return;
      const shareAmt = Number((entry.remCents / 100).toFixed(2));
      const grossAmt = Number((entry.grossCents / 100).toFixed(2));
      shareEntry.grossAmount = grossAmt;
      shareEntry.amount = shareAmt;
      shareEntry.isSharePaid = grossAmt > 0 && shareAmt <= 0 && shareEntry.paidAmount > 0;
      shareEntry.itemsCount = shareAmt > 0 ? 1 : 0;
      if (shareAmt > 0) {
        const desc =
          parts === 2
            ? "Divisão Meio a Meio (50% do Consumo de Frigobar)"
            : `Divisão Igualitária (1/${parts} do Consumo de Frigobar)`;
        shareEntry.items = [
          {
            itemKey: `split_${entry.guestIndex}`,
            productId: "split_share",
            productName: desc,
            quantity: 1,
            unitPrice: shareAmt,
            totalPrice: shareAmt,
            launchDateBr: "Estadia"
          }
        ];
        shareEntry.orderItems = [
          {
            productId: "split_share",
            productName: desc,
            quantity: 1,
            unitPrice: shareAmt,
            totalPrice: shareAmt,
            isCourtesy: false
          }
        ];
      }
    });

    for (const it of pendingLaunchedItems) {
      itemAllocationByKey[it.itemKey] = {
        mode: "half_and_half",
        isExplicitlyMarked: true,
        allocations: Object.fromEntries(activeGuests.map(g => [String(g.index), Number((it.remainingQuantity / parts).toFixed(2))]))
      };
    }
  } else if (mode === "by_item") {
    for (const it of pendingLaunchedItems) {
      const remQty = Number(it.remainingQuantity ?? it.quantity) || 0;
      const totalQty = Math.max(remQty, Number(it.quantity) || remQty);
      const uPrice = Number(it.unitPrice) || 0;
      if (remQty <= 0) continue;

      const rawAssign =
        itemAssignments[it.itemKey] ??
        itemAssignments[`${it.launchOrderId}::${it.productId}`] ??
        itemAssignments[it.productId];

      const isExplicitlyMarked =
        rawAssign !== undefined &&
        rawAssign !== null &&
        (typeof rawAssign !== "object" || Object.keys(rawAssign).length > 0);

      // 1. Calcula a alocação bruta sobre a quantidade original do lançamento (totalQty)
      const grossPerGuestQty = {};
      let fallbackToTitularGrossQty = 0;

      if (typeof rawAssign === "number" || typeof rawAssign === "string") {
        const targetIdx = Number(rawAssign) || 1;
        if (sharesMap.has(targetIdx)) {
          grossPerGuestQty[targetIdx] = totalQty;
        } else {
          grossPerGuestQty[1] = totalQty;
        }
      } else if (rawAssign && typeof rawAssign === "object") {
        if (rawAssign.assignedGuestIndex !== undefined || rawAssign.guestIndex !== undefined) {
          const targetIdx = Number(rawAssign.assignedGuestIndex ?? rawAssign.guestIndex) || 1;
          grossPerGuestQty[sharesMap.has(targetIdx) ? targetIdx : 1] = totalQty;
        } else {
          const allocSource =
            rawAssign.unitsByGuest && typeof rawAssign.unitsByGuest === "object"
              ? rawAssign.unitsByGuest
              : rawAssign.allocations && typeof rawAssign.allocations === "object"
              ? rawAssign.allocations
              : rawAssign;
          let remainingGross = totalQty;
          for (const g of enrichedGuests) {
            if (g.index === 1) continue;
            const wanted = Math.max(0, Math.floor(Number(allocSource[g.index] ?? allocSource[String(g.index)] ?? 0)));
            const take = Math.min(remainingGross, wanted);
            if (take > 0) {
              grossPerGuestQty[g.index] = take;
              remainingGross -= take;
            }
          }
          const explicitG1 = Math.max(0, Math.floor(Number(allocSource[1] ?? allocSource["1"] ?? 0)));
          if (remainingGross > 0) {
            grossPerGuestQty[1] = remainingGross;
            if (explicitG1 < remainingGross) {
              fallbackToTitularGrossQty = remainingGross - explicitG1;
            }
          }
        }
      } else {
        // Regra Canônica: Itens não marcados (inclusive lançados na vistoria final) vão para o Hóspede Principal (Titular)
        grossPerGuestQty[1] = totalQty;
        fallbackToTitularGrossQty = totalQty;
      }

      // 2. Desconta eventuais unidades já pagas por cada hóspede neste item específico
      const paidByGuestOnItem = {
        ...(paidUnitsByItemAndGuest[it.itemKey] ||
          paidUnitsByItemAndGuest[`${it.launchOrderId}::${it.productId}`] ||
          paidUnitsByItemAndGuest[it.productId] ||
          {}),
        ...(it.paidByGuest && typeof it.paidByGuest === "object" ? it.paidByGuest : {})
      };

      const perGuestQty = {};
      let sumUnpaidAssigned = 0;
      for (const g of enrichedGuests) {
        const grossQ = Number(grossPerGuestQty[g.index] || 0);
        const paidQ = Number(paidByGuestOnItem[g.index] || paidByGuestOnItem[String(g.index)] || 0);
        const netQ = Math.max(0, grossQ - paidQ);
        if (netQ > 0) {
          perGuestQty[g.index] = netQ;
          sumUnpaidAssigned += netQ;
        }
      }

      // Garante que a soma das unidades pendentes distribuídas feche exatamente com remQty
      if (sumUnpaidAssigned > remQty) {
        let excess = sumUnpaidAssigned - remQty;
        for (const g of enrichedGuests) {
          const cur = perGuestQty[g.index] || 0;
          if (cur <= 0 || excess <= 0) continue;
          const cut = Math.min(cur, excess);
          perGuestQty[g.index] -= cut;
          if (perGuestQty[g.index] <= 0) delete perGuestQty[g.index];
          excess -= cut;
        }
      } else if (sumUnpaidAssigned < remQty) {
        const diff = remQty - sumUnpaidAssigned;
        perGuestQty[1] = (perGuestQty[1] || 0) + diff;
      }

      itemAllocationByKey[it.itemKey] = {
        mode: "by_item",
        isExplicitlyMarked,
        allocations: perGuestQty,
        unassignedQty: isExplicitlyMarked ? 0 : remQty
      };

      for (const [gIdxStr, qVal] of Object.entries(perGuestQty)) {
        const gIdx = Number(gIdxStr) || 1;
        const qty = Number(qVal) || 0;
        if (qty <= 0) continue;
        const shareEntry = sharesMap.get(gIdx) || sharesMap.get(1);
        if (!shareEntry) continue;

        const subTotal = Number((qty * uPrice).toFixed(2));
        shareEntry.amount = Number((shareEntry.amount + subTotal).toFixed(2));
        shareEntry.itemsCount += qty;

        const itemEntry = {
          itemKey: it.itemKey,
          orderId: it.launchOrderId,
          launchOrderId: it.launchOrderId,
          productId: it.productId,
          productName: it.productName,
          quantity: qty,
          unitPrice: uPrice,
          totalPrice: subTotal,
          launchDate: it.launchDate,
          launchDateYmd: it.launchDate,
          launchDateBr: it.launchDateBr,
          isExplicitlyMarked
        };
        shareEntry.items.push(itemEntry);
        if (gIdx === 1 && (!isExplicitlyMarked || fallbackToTitularGrossQty > 0)) {
          shareEntry.unassignedFallbackItems.push(itemEntry);
        }
        shareEntry.orderItems.push({
          productId: it.productId,
          productName: it.productName,
          quantity: qty,
          unitPrice: uPrice,
          totalPrice: subTotal,
          isCourtesy: false,
          launchOrderId: it.launchOrderId,
          launchDate: it.launchDate,
          launchDateBr: it.launchDateBr
        });
        shareEntry.selectedLaunchItems.push(itemEntry);
      }
    }

    for (const shareEntry of sharesMap.values()) {
      shareEntry.grossAmount = Number((shareEntry.amount + shareEntry.paidAmount).toFixed(2));
      shareEntry.isSharePaid = shareEntry.paidAmount > 0 && shareEntry.amount <= 0;
    }
  } else {
    // Modo padrão: "titular" -> 100% para o Hóspede Principal (Titular) como pagador e tomador da Nota Fiscal
    const titularShare = sharesMap.get(1);
    if (titularShare) {
      titularShare.amount = cleanPendingBalance;
      titularShare.grossAmount = Number((cleanPendingBalance + titularShare.paidAmount).toFixed(2));
      titularShare.isSharePaid = titularShare.paidAmount > 0 && cleanPendingBalance <= 0;
      for (const it of pendingLaunchedItems) {
        const remQty = Number(it.remainingQuantity ?? it.quantity) || 0;
        const uPrice = Number(it.unitPrice) || 0;
        if (remQty <= 0) continue;
        const subTotal = Number((remQty * uPrice).toFixed(2));
        titularShare.itemsCount += remQty;
        const itemEntry = {
          itemKey: it.itemKey,
          orderId: it.launchOrderId,
          launchOrderId: it.launchOrderId,
          productId: it.productId,
          productName: it.productName,
          quantity: remQty,
          unitPrice: uPrice,
          totalPrice: subTotal,
          launchDate: it.launchDate,
          launchDateYmd: it.launchDate,
          launchDateBr: it.launchDateBr
        };
        titularShare.items.push(itemEntry);
        titularShare.orderItems.push({
          productId: it.productId,
          productName: it.productName,
          quantity: remQty,
          unitPrice: uPrice,
          totalPrice: subTotal,
          isCourtesy: false,
          launchOrderId: it.launchOrderId,
          launchDate: it.launchDate,
          launchDateBr: it.launchDateBr
        });
        titularShare.selectedLaunchItems.push(itemEntry);
        itemAllocationByKey[it.itemKey] = {
          mode: "titular",
          isExplicitlyMarked: true,
          allocations: { "1": remQty }
        };
      }
    }
  }

  // Vincula eventuais ordens individuais pré-configuradas no pós-checkout (ORD-MB-SPLIT-...)
  const resCode = reservation?.code || (reservation?.id ? `RES-${reservation.id}` : "");
  const existingSplitOrders = reservation
    ? (db.minibarOrders || []).filter(
        o =>
          o &&
          o.isAutoSplitCheckoutOrder &&
          o.paymentStatus !== "cancelado" &&
          ((resCode && o.reservationCode === resCode) || String(o.reservationId) === String(reservation.id))
      )
    : [];

  for (const share of sharesMap.values()) {
    const matchedOrd = existingSplitOrders.find(
      o => Number(o.guestIndex || 1) === share.guestIndex && o.paymentStatus === "pendente"
    );
    share.pendingOrderId = matchedOrd ? matchedOrd.id : null;
  }

  return {
    mode,
    itemAssignments,
    updatedAt: rawConfig.updatedAt || null,
    guests: enrichedGuests,
    shares: Array.from(sharesMap.values()),
    itemAllocationByKey
  };
}

function syncReservationAutoSplitOrders(reservation, flatStr, statement) {
  if (!reservation || !statement) return [];
  if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];

  const resCode = reservation.code || `RES-${reservation.id}`;
  const splitBreakdown = statement.splitBreakdown;
  if (!splitBreakdown) return [];

  const existingAutoSplitOrders = db.minibarOrders.filter(
    o =>
      o &&
      o.isAutoSplitCheckoutOrder &&
      o.paymentStatus === "pendente" &&
      ((resCode && o.reservationCode === resCode) || String(o.reservationId) === String(reservation.id))
  );

  // Se não há saldo pendente, cancela eventuais ordens auto-split pendentes obsoletas
  if (statement.pendingBalance <= 0) {
    for (const oldOrd of existingAutoSplitOrders) {
      oldOrd.paymentStatus = "cancelado";
      oldOrd.updatedAt = new Date().toISOString();
    }
    return [];
  }

  // Sempre sincroniza os dados fiscais do titular na ordem de lançamento principal caso exista
  const titularShare = splitBreakdown.shares.find(s => s.guestIndex === 1) || splitBreakdown.shares[0];
  if (titularShare && statement.primaryPendingOrder) {
    const pOrd = statement.primaryPendingOrder;
    const cleanDoc = String(titularShare.document || titularShare.cpf || reservation.guestDocument || "").replace(/\D/g, "");
    pOrd.guestIndex = 1;
    pOrd.guestRole = "titular";
    pOrd.guestId = titularShare.guestId || reservation.guestId || null;
    pOrd.guestName = titularShare.guestName || reservation.guestName || "Hóspede Titular";
    pOrd.guestPhone = titularShare.phone || reservation.guestPhone || "";
    pOrd.guestDocument = cleanDoc;
    pOrd.guestEmail = titularShare.email || reservation.guestEmail || "";
    pOrd.fiscalPreferences = {
      invoiceDescriptionType: pOrd.fiscalPreferences?.invoiceDescriptionType || "detailed",
      documentType: cleanDoc.length === 14 ? "cnpj" : "cpf",
      documentNumber: cleanDoc,
      companyName: pOrd.fiscalPreferences?.companyName || "",
      email: pOrd.guestEmail,
      phone: pOrd.guestPhone
    };
  }

  // Para qualquer modo ("titular", "half_and_half" ou "by_item"), cria/atualiza a cobrança
  // e pré-configuração de Nota Fiscal individual para cada hóspede consumidor com saldo > 0
  const activeShares = splitBreakdown.shares.filter(s => s.amount > 0);
  const syncedOrders = [];
  const activeGuestIndices = new Set(activeShares.map(s => s.guestIndex));

  for (const oldOrd of existingAutoSplitOrders) {
    if (!activeGuestIndices.has(Number(oldOrd.guestIndex || 1))) {
      oldOrd.paymentStatus = "cancelado";
      oldOrd.updatedAt = new Date().toISOString();
    }
  }

  for (const share of activeShares) {
    const cleanDoc = String(share.document || share.cpf || "").replace(/\D/g, "");
    const baseSplitOrdId = `ORD-MB-SPLIT-${resCode}-G${share.guestIndex}`;
    let splitOrd = existingAutoSplitOrders.find(
      o => Number(o.guestIndex) === share.guestIndex || o.id === baseSplitOrdId
    );
    const alreadyPaidWithBaseId = db.minibarOrders.some(
      o => o && o.id === baseSplitOrdId && o.paymentStatus === "pago"
    );
    const splitOrdId = splitOrd
      ? splitOrd.id
      : alreadyPaidWithBaseId
      ? `${baseSplitOrdId}-${Date.now()}`
      : baseSplitOrdId;

    const fiscalPreferences = {
      invoiceDescriptionType: splitOrd?.fiscalPreferences?.invoiceDescriptionType || "detailed",
      documentType: cleanDoc.length === 14 ? "cnpj" : "cpf",
      documentNumber: cleanDoc,
      companyName: splitOrd?.fiscalPreferences?.companyName || "",
      email: share.email || "",
      phone: share.phone || "",
      payerName: share.guestName
    };

    const effectiveItems =
      Array.isArray(share.orderItems) && share.orderItems.length > 0
        ? share.orderItems
        : [
            {
              productId: "split_share",
              productName: `Cota Individual de Frigobar (${share.guestName})`,
              quantity: 1,
              unitPrice: share.amount,
              totalPrice: share.amount,
              isCourtesy: false
            }
          ];

    const effectivePartialMode =
      splitBreakdown.mode === "half_and_half"
        ? "equal_split"
        : splitBreakdown.mode === "by_item"
        ? "items"
        : "full";

    if (splitOrd) {
      splitOrd.flatNumber = flatStr;
      splitOrd.guestId = share.guestId || splitOrd.guestId || null;
      splitOrd.guestIndex = share.guestIndex;
      splitOrd.guestRole = share.guestIndex > 1 ? "acompanhante" : "titular";
      splitOrd.guestName = share.guestName;
      splitOrd.guestPhone = share.phone || "";
      splitOrd.guestDocument = cleanDoc;
      splitOrd.guestEmail = share.email || "";
      splitOrd.items = effectiveItems;
      splitOrd.selectedLaunchItems = share.selectedLaunchItems || [];
      splitOrd.partialMode = effectivePartialMode;
      splitOrd.splitMode = splitBreakdown.mode;
      splitOrd.settlesLaunchOrders = true;
      splitOrd.isAutoSplitCheckoutOrder = true;
      splitOrd.totalAmount = share.amount;
      splitOrd.fiscalPreferences = fiscalPreferences;
      splitOrd.updatedAt = new Date().toISOString();
    } else {
      splitOrd = {
        id: splitOrdId,
        flatNumber: flatStr,
        reservationId: reservation.id || null,
        reservationCode: resCode,
        guestId: share.guestId || null,
        guestIndex: share.guestIndex,
        guestRole: share.guestIndex > 1 ? "acompanhante" : "titular",
        guestName: share.guestName,
        guestPhone: share.phone || "",
        guestDocument: cleanDoc,
        guestEmail: share.email || "",
        items: effectiveItems,
        selectedLaunchItems: share.selectedLaunchItems || [],
        partialMode: effectivePartialMode,
        splitMode: splitBreakdown.mode,
        settlesLaunchOrders: true,
        isAutoSplitCheckoutOrder: true,
        totalAmount: share.amount,
        paymentMethod: "pendente",
        paymentStatus: "pendente",
        source: "guest_split_checkout",
        fiscalPreferences,
        invoice: { status: "pendente" },
        notes:
          splitBreakdown.mode === "half_and_half"
            ? `Divisão Meio a Meio configurada na reserva (${share.guestName})`
            : splitBreakdown.mode === "by_item"
            ? `Consumo individual marcado por item (${share.guestName})`
            : `100% Hóspede Titular (${share.guestName})`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      db.minibarOrders.push(splitOrd);
    }

    share.pendingOrderId = splitOrd.id;
    syncedOrders.push(splitOrd);
  }

  return syncedOrders;
}

function formatMinibarDateBr(ymdOrIso) {
  if (!ymdOrIso) return "";
  const raw = String(ymdOrIso).trim();
  const m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[3]}/${m[2]}/${m[1]}`;
  try {
    const dt = new Date(raw);
    if (!isNaN(dt.getTime())) {
      const parts = new Intl.DateTimeFormat("pt-BR", {
        timeZone: "America/Sao_Paulo",
        day: "2-digit",
        month: "2-digit",
        year: "numeric"
      }).format(dt);
      return parts;
    }
  } catch (_) {}
  return raw;
}

function sanitizeMinibarInvoiceForResponse(inv) {
  if (!inv || typeof inv !== "object") return null;
  const { fileData, ...safeInv } = inv;
  if (!safeInv.invoiceFileUrl && safeInv.fileUrl) {
    safeInv.invoiceFileUrl = safeInv.fileUrl;
  }
  return safeInv;
}

function sanitizeMinibarOrderForResponse(order) {
  if (!order || typeof order !== "object") return order;
  if (!order.invoice) return order;
  return {
    ...order,
    invoice: sanitizeMinibarInvoiceForResponse(order.invoice)
  };
}

function doesMinibarOrderMatchReservation(order, reservation) {
  if (!order || !reservation) return false;
  if (order.reservationId && String(order.reservationId) === String(reservation.id)) {
    return true;
  }
  const flatStr = String(reservation.flatNumber || reservation.flatId || "").trim();
  const candidateCodes = new Set(
    [
      reservation.code,
      reservation.id ? `RES-${reservation.id}` : "",
      flatStr && reservation.id ? `RES-${flatStr}-${String(reservation.id).padStart(3, "0")}` : ""
    ].filter(Boolean)
  );
  if (order.reservationCode && candidateCodes.has(String(order.reservationCode).trim())) {
    return true;
  }
  if (!order.reservationId && !order.reservationCode && flatStr && String(order.flatNumber || "").trim() === flatStr) {
    const activeRes = findActiveOrRecentReservationForFlat(flatStr);
    if (activeRes && String(activeRes.id) === String(reservation.id)) {
      return true;
    }
  }
  return false;
}

function getVisibleReservationMinibarOrders(reservation) {
  if (!reservation) return [];
  const rawOrders = (db.minibarOrders || []).filter(
    o => o && o.paymentStatus !== "cancelado" && doesMinibarOrderMatchReservation(o, reservation)
  );
  const hasSeparatePaidOrder = rawOrders.some(
    o =>
      o.paymentStatus === "pago" &&
      !String(o.id || "").startsWith("ORD-MB-LANC-") &&
      !String(o.id || "").startsWith("ORD-MB-DIV-")
  );
  return rawOrders
    .filter(o => {
      const hasDirectInvoice = Boolean(
        o.invoice?.invoiceFileUrl || o.invoice?.fileUrl || o.invoice?.status === "anexada"
      );
      if (
        o.paymentStatus === "lancamento_quitado" &&
        !hasDirectInvoice &&
        (o.settledByOrderId || hasSeparatePaidOrder)
      ) {
        return false;
      }
      return true;
    })
    .map(o => ({
      id: o.id,
      source: o.source || "",
      guestName: o.guestName || reservation.guestName,
      guestIndex: o.guestIndex || 1,
      createdAt: o.createdAt,
      paidAt: o.paidAt || null,
      totalAmount: o.totalAmount,
      remainingAmount: o.remainingAmount,
      paymentStatus: o.paymentStatus,
      paymentMethod: o.paymentMethod,
      items: o.items || [],
      invoice: sanitizeMinibarInvoiceForResponse(o.invoice),
      invoiceFileUrl: o.invoice?.invoiceFileUrl || o.invoice?.fileUrl || null,
      invoiceFileName: o.invoice?.invoiceFileName || null,
      invoiceNumber: o.invoice?.invoiceNumber || null,
      invoiceStatus: o.invoice?.status || null
    }));
}

function buildReservationMinibarStatement(reservation, flatStrOverride = "") {
  const flatStr = String(flatStrOverride || reservation?.flatNumber || reservation?.flatId || "").trim();
  const resCode = reservation?.code || (reservation?.id ? `RES-${reservation.id}` : "");
  const todayStr = getBrasiliaNow().date;

  const hasFinalCheckoutInspection = Boolean(
    reservation &&
      (reservation.finalMinibarInspectionAt ||
        (db.minibarInspections || []).some(
          i =>
            i &&
            (i.isFinalCheckoutInspection || i.status === "divergencia") &&
            ((resCode && i.reservationCode === resCode) ||
              (reservation.id && String(i.reservationId) === String(reservation.id)))
        ))
  );

  // 1. Verifica status canônico de check-out
  const isCheckedOut = Boolean(
    reservation &&
      (isReservationOrFlatCheckedOut(db, reservation, reservation.flatId, flatStr) ||
        hasFinalCheckoutInspection ||
        reservation.checkoutDone ||
        reservation.status === "completed" ||
        reservation.status === "checked_out" ||
        reservation.actualCheckoutAt ||
        reservation.earlyCheckoutReleasedAt ||
        reservation.checkedOutAt ||
        reservation.digitalCheckoutAt ||
        (reservation.checkoutDate && reservation.checkoutDate < todayStr))
  );

  let checkoutTime = reservation?.actualCheckoutTime || "";
  if (!checkoutTime && reservation) {
    const rawOutIso =
      reservation.actualCheckoutAt ||
      reservation.earlyCheckoutReleasedAt ||
      reservation.checkedOutAt ||
      reservation.digitalCheckoutAt ||
      reservation.finalMinibarInspectionAt ||
      "";
    if (rawOutIso) {
      try {
        const dt = new Date(rawOutIso);
        if (!isNaN(dt.getTime())) {
          checkoutTime = new Intl.DateTimeFormat("pt-BR", {
            timeZone: "America/Sao_Paulo",
            hour: "2-digit",
            minute: "2-digit",
            hour12: false
          }).format(dt);
        }
      } catch (_) {}
    }
  }

  // 2. Pedidos da reserva
  const allResOrders = reservation
    ? (db.minibarOrders || []).filter(
        o =>
          o &&
          doesMinibarOrderMatchReservation(o, reservation) &&
          o.paymentStatus !== "cancelado"
      )
    : [];

  const isLaunchOrder = o =>
    o.source === "restocker_launch" ||
    o.source === "anserve_discrepancy" ||
    String(o.id || "").startsWith("ORD-MB-DIV-") ||
    String(o.id || "").startsWith("ORD-MB-LANC-");

  const launchOrders = allResOrders.filter(isLaunchOrder);
  const paidOrders = allResOrders.filter(o => o.paymentStatus === "pago" || o.invoice?.status === "anexada" || Boolean(o.invoice?.invoiceFileUrl));

  // 3. Agrupa lançamentos por data (somente o dia DD/MM/AAAA, sem hora)
  const byDateMap = new Map();
  const pendingLaunchedItems = [];
  let totalLaunchedAmount = 0;
  let pendingBalance = 0;

  for (const lOrd of launchOrders) {
    const rawDate = String(lOrd.launchDate || lOrd.createdAt || todayStr).slice(0, 10);
    const dateBr = formatMinibarDateBr(rawDate);
    const ordTotal = Number(lOrd.totalAmount || 0);
    const isOrdPaid =
      lOrd.paymentStatus === "pago" ||
      lOrd.paymentStatus === "lancamento_quitado" ||
      (lOrd.remainingAmount !== undefined && Number(lOrd.remainingAmount) <= 0.01);
    const ordRem = isOrdPaid
      ? 0
      : lOrd.remainingAmount !== undefined
      ? Math.max(0, Number(lOrd.remainingAmount))
      : ordTotal;

    totalLaunchedAmount += ordTotal;
    pendingBalance += ordRem;

    if (!byDateMap.has(rawDate)) {
      byDateMap.set(rawDate, {
        date: rawDate,
        dateYmd: rawDate,
        dateBr,
        totalDayAmount: 0,
        pendingDayAmount: 0,
        items: []
      });
    }
    const dayEntry = byDateMap.get(rawDate);
    dayEntry.totalDayAmount = Number((dayEntry.totalDayAmount + ordTotal).toFixed(2));
    dayEntry.pendingDayAmount = Number((dayEntry.pendingDayAmount + ordRem).toFixed(2));

    for (const [idx, it] of (lOrd.items || []).entries()) {
      const qty = Number(it.quantity) || 0;
      if (qty <= 0) continue;
      const uPrice = Number(it.unitPrice) || 0;
      const tPrice = Number(it.totalPrice) || Number((qty * uPrice).toFixed(2));
      const paidQty = isOrdPaid
        ? qty
        : Math.min(qty, Number(it.paidQuantity) || 0);
      const remQty = isOrdPaid
        ? 0
        : it.remainingQuantity !== undefined
        ? Math.max(0, Number(it.remainingQuantity))
        : Math.max(0, qty - paidQty);

      const itemKey = `${lOrd.id}::${it.productId}::${idx}`;
      const isItemPaid = isOrdPaid || remQty === 0;
      const enrichedItem = {
        itemKey,
        orderId: lOrd.id,
        launchOrderId: lOrd.id,
        launchDate: rawDate,
        launchDateYmd: rawDate,
        launchDateBr: dateBr,
        inspectorName: lOrd.inspectorName || "Repositora Anserve",
        launchedByName: lOrd.inspectorName || "Repositora Anserve",
        productId: it.productId,
        productName: it.productName || it.name || it.productId,
        quantity: qty,
        paidQuantity: paidQty,
        remainingQuantity: remQty,
        paidByGuest: it.paidByGuest && typeof it.paidByGuest === "object" ? { ...it.paidByGuest } : {},
        unitPrice: uPrice,
        totalPrice: tPrice,
        remainingTotalPrice: Number((remQty * uPrice).toFixed(2)),
        isCourtesy: Boolean(it.isCourtesy),
        isPaid: isItemPaid,
        paymentStatus: isItemPaid ? "pago" : "pendente"
      };

      dayEntry.items.push(enrichedItem);
      if (!enrichedItem.isCourtesy && remQty > 0 && ordRem > 0.01) {
        pendingLaunchedItems.push(enrichedItem);
      }
    }
  }

  // Se houver pedidos pagos diretos antigos (guest_mobile sem vínculo com launchOrder), exibe também no histórico por dia
  for (const pOrd of paidOrders) {
    if (isLaunchOrder(pOrd) || pOrd.settlesLaunchOrders) continue;
    const rawDate = String(pOrd.launchDate || pOrd.paidAt || pOrd.createdAt || todayStr).slice(0, 10);
    const dateBr = formatMinibarDateBr(rawDate);
    const ordTotal = Number(pOrd.totalAmount || 0);
    totalLaunchedAmount += ordTotal;

    if (!byDateMap.has(rawDate)) {
      byDateMap.set(rawDate, {
        date: rawDate,
        dateYmd: rawDate,
        dateBr,
        totalDayAmount: 0,
        pendingDayAmount: 0,
        items: []
      });
    }
    const dayEntry = byDateMap.get(rawDate);
    dayEntry.totalDayAmount = Number((dayEntry.totalDayAmount + ordTotal).toFixed(2));

    for (const [idx, it] of (pOrd.items || []).entries()) {
      const qty = Number(it.quantity) || 0;
      if (qty <= 0) continue;
      const uPrice = Number(it.unitPrice) || 0;
      const tPrice = Number(it.totalPrice) || Number((qty * uPrice).toFixed(2));
      dayEntry.items.push({
        itemKey: `${pOrd.id}::${it.productId}::${idx}`,
        orderId: pOrd.id,
        launchOrderId: pOrd.id,
        launchDate: rawDate,
        launchDateYmd: rawDate,
        launchDateBr: dateBr,
        inspectorName: pOrd.guestName || "Consumo Registrado",
        launchedByName: pOrd.guestName || "Consumo Registrado",
        productId: it.productId,
        productName: it.productName || it.name || it.productId,
        quantity: qty,
        paidQuantity: qty,
        remainingQuantity: 0,
        unitPrice: uPrice,
        totalPrice: tPrice,
        remainingTotalPrice: 0,
        isCourtesy: Boolean(it.isCourtesy),
        isPaid: true,
        paymentStatus: "pago"
      });
    }
  }

  const dailyLaunches = Array.from(byDateMap.values()).sort((a, b) => a.date.localeCompare(b.date));
  const totalPaidAmount = Number(
    paidOrders.reduce((sum, o) => sum + (Number(o.totalAmount) || 0), 0).toFixed(2)
  );

  // Garante consistência entre o saldo pendente de lançamentos e eventuais pagamentos parciais
  pendingBalance = Number(Math.max(0, pendingBalance).toFixed(2));

  const primaryPendingOrder =
    launchOrders.find(
      o =>
        o.paymentStatus === "pendente" &&
        (o.remainingAmount === undefined ? Number(o.totalAmount) > 0 : Number(o.remainingAmount) > 0.01)
    ) || null;

  // 4. Computa a divisão em tempo real ("titular", "half_and_half" ou "by_item")
  const reservationGuests = reservation ? getReservationAllGuests(reservation) : [];
  const splitBreakdown = computeReservationMinibarSplit(
    reservation,
    pendingLaunchedItems,
    pendingBalance,
    reservationGuests,
    { paidOrders, totalLaunchedAmount }
  );

  // Anota cada item pendente com sua alocação atual
  for (const day of dailyLaunches) {
    for (const item of day.items) {
      if (splitBreakdown.itemAllocationByKey[item.itemKey]) {
        item.allocation = splitBreakdown.itemAllocationByKey[item.itemKey];
      }
    }
  }

  // 5. R5: Apuração Segregada dos Itens Consumidos do Kit de Boas-Vindas (Cortesia da Casa — Valor R$ 0,00)
  const resCandidateCodes = new Set(
    [
      resCode,
      reservation?.code,
      reservation?.id ? `RES-${reservation.id}` : "",
      flatStr && reservation?.id ? `RES-${flatStr}-${String(reservation.id).padStart(3, "0")}` : ""
    ].filter(Boolean)
  );

  const resInspections = (db.minibarInspections || []).filter(i => {
    if (!i) return false;
    if (resCode && i.reservationCode && resCandidateCodes.has(String(i.reservationCode).trim())) return true;
    if (reservation?.id && String(i.reservationId) === String(reservation.id)) return true;
    if (flatStr && String(i.flatNumber).trim() === flatStr) {
      if (reservation?.checkinDate && reservation?.checkoutDate) {
        const inspDate = String(i.launchDate || i.inspectedAt || "").slice(0, 10);
        if (inspDate >= reservation.checkinDate && inspDate <= reservation.checkoutDate) {
          return true;
        }
      }
    }
    return false;
  });

  let waterCups = Number(reservation?.welcomeKitConsumption?.waterCups ?? reservation?.welcomeKitConsumption?.waterCupsConsumed) || 0;
  let peanuts = Number(reservation?.welcomeKitConsumption?.mendoratoPeanuts ?? reservation?.welcomeKitConsumption?.peanutsConsumed) || 0;

  for (const insp of resInspections) {
    if (insp.welcomeKitConsumption) {
      const w = Number(insp.welcomeKitConsumption.waterCups ?? insp.welcomeKitConsumption.waterCupsConsumed) || 0;
      const p = Number(insp.welcomeKitConsumption.mendoratoPeanuts ?? insp.welcomeKitConsumption.peanutsConsumed) || 0;
      waterCups = Math.max(waterCups, w);
      peanuts = Math.max(peanuts, p);
    }
  }

  const consumedCourtesyItems = [];
  if (waterCups > 0) {
    consumedCourtesyItems.push({
      productId: "prod_agua_mineral_copo",
      productName: "Copo d'Água Mineral 200ml",
      quantity: Math.min(2, waterCups),
      unitPrice: 0.00,
      totalPrice: 0.00,
      isCourtesy: true,
      supplierOrigin: "anserve"
    });
  }
  if (peanuts > 0) {
    consumedCourtesyItems.push({
      productId: "prod_amendoim_mendorato",
      productName: "Amendoim Mendorato 27g",
      quantity: Math.min(2, peanuts),
      unitPrice: 0.00,
      totalPrice: 0.00,
      isCourtesy: true,
      supplierOrigin: "hotel_proprio"
    });
  }

  return {
    isCheckedOut,
    hasFinalCheckoutInspection,
    checkoutTime: checkoutTime || null,
    dailyLaunches,
    pendingLaunchedItems,
    pendingBalance,
    totalLaunchedAmount: Number(totalLaunchedAmount.toFixed(2)),
    totalPaidAmount,
    consumedCourtesyItems,
    welcomeKitSummary: {
      waterCupsConsumed: waterCups,
      peanutsConsumed: peanuts,
      totalCourtesyValue: 0.00
    },
    primaryPendingOrder,
    reservationGuests: splitBreakdown.guests || reservationGuests,
    splitConfig: {
      mode: splitBreakdown.mode,
      itemAssignments: splitBreakdown.itemAssignments,
      updatedAt: splitBreakdown.updatedAt
    },
    splitBreakdown
  };
}

function settleMinibarOrder(order, paymentDetails = {}) {
  if (!order) return null;
  const nowIso = paymentDetails.paidAt || new Date().toISOString();

  order.paymentStatus = "pago";
  order.paidAt = nowIso;
  if (paymentDetails.paymentMethod) {
    order.paymentMethod = paymentDetails.paymentMethod;
  }
  if (paymentDetails.mpPaymentId) {
    order.mpPaymentId = String(paymentDetails.mpPaymentId);
  }
  if (paymentDetails.pixEndToEndId) {
    order.pixEndToEndId = String(paymentDetails.pixEndToEndId);
  }
  if (paymentDetails.amount && Number(paymentDetails.amount) > 0) {
    order.paidAmount = Number(paymentDetails.amount);
  }
  order.updatedAt = new Date().toISOString();

  const isDirectLaunchOrder =
    order.source === "restocker_launch" ||
    order.source === "anserve_discrepancy" ||
    String(order.id || "").startsWith("ORD-MB-DIV-") ||
    String(order.id || "").startsWith("ORD-MB-LANC-");

  // 1. Se o próprio pedido quitado era um lançamento direto (pagamento integral in-place), zera seu saldo pendente
  if (isDirectLaunchOrder) {
    order.remainingAmount = 0;
    order.discrepancyResolvedAt = nowIso;
    if (Array.isArray(order.items)) {
      for (const it of order.items) {
        it.paidQuantity = Number(it.quantity) || 0;
        it.remainingQuantity = 0;
      }
    }
  } else {
    // 1.B Se foi um pedido de pagamento (integral ou parcial: por itens, divisão igual ou valor customizado) da reserva,
    // abate automaticamente o valor e as quantidades dos lançamentos pendentes da reserva!
    const pendingLaunchOrders = (db.minibarOrders || []).filter(
      o =>
        o &&
        o.id !== order.id &&
        o.paymentStatus === "pendente" &&
        (o.source === "restocker_launch" ||
          o.source === "anserve_discrepancy" ||
          String(o.id || "").startsWith("ORD-MB-DIV-") ||
          String(o.id || "").startsWith("ORD-MB-LANC-")) &&
        ((order.reservationCode && o.reservationCode === order.reservationCode) ||
          (order.reservationId && String(o.reservationId) === String(order.reservationId)) ||
          (!order.reservationCode && String(o.flatNumber) === String(order.flatNumber)))
    );

    if (pendingLaunchOrders.length > 0) {
      let amountToDeduct = Number(order.totalAmount || 0);
      const payerGuestIdx = Number(order.guestIndex || 1);

      // Abate quantidades e valores diretamente nos lançamentos dos itens selecionados quando aplicável
      const selectedItems = Array.isArray(order.selectedLaunchItems) && order.selectedLaunchItems.length > 0
        ? order.selectedLaunchItems
        : (order.partialMode === "items" || order.partialMode === "full" || !order.partialMode)
        ? (order.items || [])
        : [];

      for (const sel of selectedItems) {
        if (!sel || sel.productId === "split_share" || sel.productId === "partial_payment") continue;
        let qtyToMark = Number(sel.quantity) || 0;
        if (qtyToMark <= 0) continue;

        for (const lOrd of pendingLaunchOrders) {
          if (sel.launchOrderId && lOrd.id !== sel.launchOrderId) continue;
          for (const lIt of lOrd.items || []) {
            if (lIt.productId !== sel.productId) continue;
            const totalQ = Number(lIt.quantity) || 0;
            const curPaid = Number(lIt.paidQuantity) || 0;
            const curRem = lIt.remainingQuantity !== undefined ? Number(lIt.remainingQuantity) : Math.max(0, totalQ - curPaid);
            if (curRem <= 0) continue;
            const take = Math.min(curRem, qtyToMark);
            lIt.paidQuantity = curPaid + take;
            lIt.remainingQuantity = Math.max(0, totalQ - lIt.paidQuantity);
            if (!lIt.paidByGuest || typeof lIt.paidByGuest !== "object") {
              lIt.paidByGuest = {};
            }
            lIt.paidByGuest[payerGuestIdx] = (lIt.paidByGuest[payerGuestIdx] || 0) + take;
            qtyToMark -= take;

            const itemValue = Number((take * Number(lIt.unitPrice || 0)).toFixed(2));
            const curOrdRem =
              lOrd.remainingAmount !== undefined
                ? Number(lOrd.remainingAmount)
                : Number(lOrd.totalAmount || 0);
            const deductOnThisOrd = Math.min(curOrdRem, amountToDeduct, itemValue);
            if (deductOnThisOrd > 0) {
              lOrd.remainingAmount = Number(Math.max(0, curOrdRem - deductOnThisOrd).toFixed(2));
              lOrd.updatedAt = nowIso;
              amountToDeduct = Number(Math.max(0, amountToDeduct - deductOnThisOrd).toFixed(2));
            }
            if (qtyToMark <= 0) break;
          }
          if (qtyToMark <= 0) break;
        }
      }

      // Abate eventual saldo residual em R$ (ex: modo half_and_half ou custom_amount) em ordem cronológica (FIFO)
      for (const lOrd of pendingLaunchOrders) {
        if (amountToDeduct <= 0.009) break;
        const curRem =
          lOrd.remainingAmount !== undefined
            ? Number(lOrd.remainingAmount)
            : Number(lOrd.totalAmount || 0);
        if (curRem <= 0) continue;

        const deductHere = Math.min(curRem, amountToDeduct);
        const nextRem = Number(Math.max(0, curRem - deductHere).toFixed(2));
        lOrd.remainingAmount = nextRem;
        lOrd.updatedAt = nowIso;
        amountToDeduct = Number(Math.max(0, amountToDeduct - deductHere).toFixed(2));
      }

      // Verifica lançamentos integralmente quitados
      for (const lOrd of pendingLaunchOrders) {
        const curRem =
          lOrd.remainingAmount !== undefined
            ? Number(lOrd.remainingAmount)
            : Number(lOrd.totalAmount || 0);
        if (curRem <= 0.01) {
          lOrd.remainingAmount = 0;
          lOrd.paymentStatus = "lancamento_quitado";
          lOrd.discrepancyResolvedAt = nowIso;
          lOrd.settledByOrderId = order.id;
          for (const lIt of lOrd.items || []) {
            lIt.paidQuantity = Number(lIt.quantity) || 0;
            lIt.remainingQuantity = 0;
          }
        }
      }
    }
  }

  // Verifica se todos os lançamentos da reserva foram quitados para dar baixa nas inspeções vinculadas
  const hasAnyRemainingLaunch = (db.minibarOrders || []).some(
    o =>
      o &&
      o.paymentStatus === "pendente" &&
      (o.source === "restocker_launch" ||
        o.source === "anserve_discrepancy" ||
        String(o.id || "").startsWith("ORD-MB-DIV-") ||
        String(o.id || "").startsWith("ORD-MB-LANC-")) &&
      ((order.reservationCode && o.reservationCode === order.reservationCode) ||
        String(o.flatNumber) === String(order.flatNumber)) &&
      Number(o.remainingAmount ?? o.totalAmount ?? 0) > 0.01
  );

  // Se não há mais saldo nos lançamentos (ou se o pedido pago corresponde à cota daquele hóspede),
  // limpa eventuais ordens auto-split pendentes daquele hóspede ou da reserva quitada
  for (const sOrd of db.minibarOrders || []) {
    if (
      sOrd &&
      sOrd.id !== order.id &&
      sOrd.isAutoSplitCheckoutOrder &&
      sOrd.paymentStatus === "pendente" &&
      ((order.reservationCode && sOrd.reservationCode === order.reservationCode) ||
        (order.reservationId && String(sOrd.reservationId) === String(order.reservationId)))
    ) {
      if (!hasAnyRemainingLaunch || Number(sOrd.guestIndex || 1) === Number(order.guestIndex || 1)) {
        sOrd.paymentStatus = "cancelado";
        sOrd.updatedAt = nowIso;
      }
    }
  }

  const isDiscrepancyOrder =
    isDirectLaunchOrder || Boolean(order.settlesLaunchOrders);

  if (Array.isArray(db.minibarInspections)) {
    for (const insp of db.minibarInspections) {
      if (!insp) continue;
      const matchesOrder = insp.chargeOrderId === order.id;
      const matchesResCleared =
        !hasAnyRemainingLaunch &&
        insp.hasDiscrepancy &&
        !insp.discrepancyPaid &&
        ((order.reservationCode && insp.reservationCode === order.reservationCode) ||
          String(insp.flatNumber) === String(order.flatNumber));

      if (matchesOrder || matchesResCleared) {
        insp.discrepancyPaid = true;
        insp.discrepancyPaidAt = nowIso;
        insp.discrepancyPaidBy = order.guestName || "Hóspede";
        insp.discrepancyResolved = true;
        insp.updatedAt = new Date().toISOString();
      }
    }
  }

  // 2. Computa no histórico de pagamentos e consumo da Reserva
  const reservation = (db.reservations || []).find(
    r =>
      (order.reservationCode && r.code === order.reservationCode) ||
      (order.reservationId && String(r.id) === String(order.reservationId))
  );

  if (reservation) {
    // Re-sincroniza eventuais ordens auto-split remanescentes da reserva
    const flatStr = String(order.flatNumber || reservation.flatNumber || reservation.flatId || "").trim();
    const hasPendingSplits = (db.minibarOrders || []).some(
      o =>
        o &&
        o.isAutoSplitCheckoutOrder &&
        o.paymentStatus === "pendente" &&
        (o.reservationCode === reservation.code || String(o.reservationId) === String(reservation.id))
    );
    if (hasPendingSplits) {
      const updatedStmt = buildReservationMinibarStatement(reservation, flatStr);
      syncReservationAutoSplitOrders(reservation, flatStr, updatedStmt);
    }
    if (!Array.isArray(reservation.minibarPayments)) {
      reservation.minibarPayments = [];
    }
    const alreadyLogged = reservation.minibarPayments.some(mp => mp.orderId === order.id);
    if (!alreadyLogged) {
      reservation.minibarPayments.push({
        orderId: order.id,
        amount: Number(order.totalAmount || 0),
        paidAt: nowIso,
        paymentMethod: order.paymentMethod || "pix",
        partialMode: order.partialMode || "full",
        guestName: order.guestName || reservation.guestName,
        guestPhone: order.guestPhone || reservation.guestPhone || "",
        guestEmail: order.fiscalPreferences?.email || order.guestEmail || "",
        guestDocument: order.fiscalPreferences?.documentNumber || order.guestDocument || "",
        guestIndex: order.guestIndex || 1,
        guestRole: order.guestRole || "titular",
        isDiscrepancySettlement: isDiscrepancyOrder,
        items: (order.items || []).map(it => ({
          productId: it.productId,
          productName: it.productName || it.name,
          quantity: Number(it.quantity) || 0,
          totalPrice: Number(it.totalPrice) || 0
        }))
      });
    }

    if (Array.isArray(reservation.timeline)) {
      reservation.timeline.unshift({
        id: `tl_mb_${order.id}`,
        type: "minibar_payment",
        title: `🧊 Consumo de Frigobar Pago (${order.guestName})`,
        description: `Pedido ${order.id} no valor de R$ ${Number(order.totalAmount || 0).toFixed(2)} pago via ${
          order.paymentMethod === "pix" ? "PIX" : "Cartão"
        }.`,
        timestamp: nowIso
      });
    }
  }

  // 3. Atualiza ficha do hóspede consumidor no CRM (db.guests)
  if (Array.isArray(db.guests)) {
    const cleanDoc = String(order.fiscalPreferences?.documentNumber || order.guestDocument || "").replace(/\D/g, "");
    const cleanPhone = String(order.guestPhone || "").replace(/\D/g, "");
    const crmGuest = db.guests.find(
      g =>
        (order.guestId && Number(g.id) === Number(order.guestId)) ||
        (cleanDoc.length >= 11 && String(g.document || g.documentNumber || "").replace(/\D/g, "") === cleanDoc) ||
        (cleanPhone.length >= 10 && String(g.phone || "").replace(/\D/g, "") === cleanPhone)
    );
    if (crmGuest) {
      crmGuest.lastMinibarConsumptionAt = nowIso;
    }
  }

  // 4. Cria notificação operacional
  if (typeof createNotification === "function") {
    createNotification({
      category: "checkout",
      title: `🧊 Frigobar Pago: R$ ${Number(order.totalAmount || 0).toFixed(2)} (Flat ${order.flatNumber})`,
      message: `Pedido ${order.id} pago por ${order.guestName} (${
        order.paymentMethod === "pix" ? "PIX" : "Cartão"
      }). Disponível na Fila de Notas Fiscais da Anserve.`,
      severity: "success",
      metadata: { orderId: order.id, flatNumber: order.flatNumber, amount: order.totalAmount, isDiscrepancyOrder },
      targetUrl: `/anserve`
    });
  }

  saveDatabase("minibar_order_settled");
  return order;
}

async function notifyAdminMinibarInvoiceFailure(order, channelLabel, errorReason) {
  try {
    const msgTitle = `⚠️ Falha no Envio de NF do Frigobar — Flat ${order.flatNumber}`;
    const msgBody = `A Nota Fiscal do pedido ${order.id} (Hóspede: ${order.guestName}, R$ ${Number(order.totalAmount || 0).toFixed(2)}) falhou ao enviar via ${channelLabel}. Motivo: ${errorReason}. O sistema fará retentativa automática ou você pode corrigir/reenviar no painel.`;

    if (typeof createNotification === "function") {
      createNotification({
        category: "financial",
        title: msgTitle,
        message: msgBody,
        severity: "error",
        metadata: {
          orderId: order.id,
          flatNumber: order.flatNumber,
          guestName: order.guestName,
          channel: channelLabel,
          error: errorReason
        },
        targetUrl: `/frigobar`
      });
    }

    const zapiConfig = db.zapiConfig || db.settings?.zapiConfig || {};
    const adminPhone =
      db.settings?.adminPhone ||
      db.settings?.ownerPhone ||
      db.settings?.notificationPhone ||
      zapiConfig?.adminAlertPhone ||
      db.settings?.zapiConfig?.adminAlertPhone ||
      "";
    if (adminPhone && typeof sendZapiMessage === "function") {
      await sendZapiMessage(zapiConfig, {
        phone: adminPhone,
        message: `${msgTitle}\n\n${msgBody}\n\n🔗 Acesse https://corpflats.com.br/frigobar para verificar ou corrigir o contato do hóspede.`,
        channelId: "internal_ops",
        triggerEvent: "minibar_invoice_failure_alert",
        db
      });
    }
  } catch (e) {
    console.warn("[Minibar Invoice Monitor] Erro ao notificar admin:", e.message);
  }
}

async function dispatchMinibarInvoiceWithMonitoring(order, { channels = ["whatsapp", "email"], isRetry = false } = {}) {
  if (!order || !order.invoice || !(order.invoice.invoiceFileUrl || order.invoice.fileUrl)) {
    return null;
  }

  const invoiceFileUrl = order.invoice.invoiceFileUrl || order.invoice.fileUrl;
  order.invoice.invoiceFileUrl = invoiceFileUrl;
  const safeFileName = order.invoice.invoiceFileName || `NF_Frigobar_${order.flatNumber}_${order.id}.pdf`;

  const hasValidPhone = (p) => cleanWhatsAppPhone(String(p || "")).length >= 10;
  const hasValidEmail = (e) => {
    const s = String(e || "").trim();
    return s.includes("@") && s.includes(".");
  };

  // Fallback para telefone/e-mail na reserva vinculada, FNRH/preCheckin e CRM se ausente ou inválido no pedido
  const linkedRes = (db.reservations || []).find(r => doesMinibarOrderMatchReservation(order, r)) ||
    (order.flatNumber ? findActiveOrRecentReservationForFlat(String(order.flatNumber)) : null);
  let resolvedPhone = [order.fiscalPreferences?.phone, order.guestPhone].find(hasValidPhone) || "";
  let resolvedEmail = [order.fiscalPreferences?.email, order.guestEmail].find(hasValidEmail) || "";

  if (linkedRes && (!hasValidPhone(resolvedPhone) || !hasValidEmail(resolvedEmail))) {
    const resGuests = getReservationAllGuests(linkedRes);
    const consumerSlot =
      resGuests.find(g => Number(g.index) === Number(order.guestIndex || 1)) ||
      resGuests[0] ||
      null;
    if (!hasValidPhone(resolvedPhone)) {
      const candidatePhone = [consumerSlot?.phone, linkedRes.guestPhone, ...(resGuests.map(g => g.phone))].find(hasValidPhone) || "";
      if (candidatePhone) {
        resolvedPhone = String(candidatePhone).trim();
        order.guestPhone = resolvedPhone;
      }
    }
    if (!hasValidEmail(resolvedEmail)) {
      const candidateEmail = [consumerSlot?.email, linkedRes.guestEmail, ...(resGuests.map(g => g.email))].find(hasValidEmail) || "";
      if (candidateEmail) {
        resolvedEmail = String(candidateEmail).trim();
        order.guestEmail = resolvedEmail;
      }
    }
  }

  if (!hasValidPhone(resolvedPhone) || !hasValidEmail(resolvedEmail)) {
    const cleanDoc = String(order.fiscalPreferences?.documentNumber || order.guestDocument || linkedRes?.guestDocument || "").replace(/\D/g, "");
    const crmGuest = (db.guests || []).find(g =>
      (order.guestId && Number(g.id) === Number(order.guestId)) ||
      (linkedRes?.guestId && Number(g.id) === Number(linkedRes.guestId)) ||
      (cleanDoc.length >= 11 && String(g.document || g.documentNumber || "").replace(/\D/g, "") === cleanDoc)
    );
    if (crmGuest) {
      if (!hasValidPhone(resolvedPhone) && hasValidPhone(crmGuest.phone)) {
        resolvedPhone = String(crmGuest.phone).trim();
        order.guestPhone = resolvedPhone;
      }
      if (!hasValidEmail(resolvedEmail) && hasValidEmail(crmGuest.email)) {
        resolvedEmail = String(crmGuest.email).trim();
        order.guestEmail = resolvedEmail;
      }
    }
  }

  const targetPhone = String(resolvedPhone || "").trim();
  const targetEmail = String(resolvedEmail || "").trim();
  const serverBaseUrl = (process.env.SERVER_BASE_URL || db.settings?.baseUrl || "https://corpflats.com.br").replace(/\/+$/, "");
  const fullDownloadUrl = invoiceFileUrl.startsWith("http") ? invoiceFileUrl : `${serverBaseUrl}${invoiceFileUrl}`;
  const zapiConfig = (db.zapiConfig && db.zapiConfig.instanceId && db.zapiConfig.token)
    ? db.zapiConfig
    : (db.settings?.zapiConfig || db.zapiConfig || {});

  if (!order.invoice.deliveryMonitor) {
    order.invoice.deliveryMonitor = {
      whatsapp: {
        target: targetPhone,
        status: targetPhone ? "pendente" : "sem_numero",
        sentAt: null,
        attempts: 0,
        lastAttemptAt: null,
        lastError: targetPhone ? null : "WhatsApp não cadastrado para este hóspede."
      },
      email: {
        target: targetEmail,
        status: targetEmail ? "pendente" : "sem_email",
        sentAt: null,
        attempts: 0,
        lastAttemptAt: null,
        lastError: targetEmail ? null : "E-mail não cadastrado para este hóspede."
      },
      overallStatus: "processando",
      nextRetryAt: null,
      lastCheckedAt: new Date().toISOString()
    };
  }

  const monitor = order.invoice.deliveryMonitor;
  monitor.whatsapp.target = targetPhone;
  monitor.email.target = targetEmail;
  monitor.lastCheckedAt = new Date().toISOString();

  // 1. Disparo via WhatsApp (Z-API)
  if (channels.includes("whatsapp")) {
    if (!targetPhone) {
      monitor.whatsapp.status = "falha";
      monitor.whatsapp.lastError = "Número de WhatsApp ausente no cadastro do hóspede.";
      await notifyAdminMinibarInvoiceFailure(order, "WhatsApp", monitor.whatsapp.lastError);
    } else if (typeof sendZapiDocument === "function") {
      monitor.whatsapp.attempts = (monitor.whatsapp.attempts || 0) + 1;
      monitor.whatsapp.lastAttemptAt = new Date().toISOString();
      try {
        const caption = `Olá, ${order.guestName}! Segue em anexo a Nota Fiscal referente ao seu consumo de frigobar no Flat ${order.flatNumber} da CorpFlats (R$ ${Number(order.totalAmount || 0).toFixed(2)}).\n\n📄 Link direto do documento: ${fullDownloadUrl}\n\nAgradecemos a sua preferência! ✨`;
        let zapiRes = await sendZapiDocument(zapiConfig, {
          phone: targetPhone,
          document: invoiceFileUrl,
          fileName: safeFileName,
          caption,
          recipientRole: "guest",
          channelId: "transactional_chat",
          bypassTestMode: true,
          triggerEvent: "minibar_invoice",
          db
        });

        // Se o envio como documento falhar (ex: limite/rejeição de formato na Z-API), envia mensagem de texto com o link direto da Nota Fiscal
        if ((!zapiRes || zapiRes.success === false) && typeof sendZapiMessage === "function") {
          const textFallbackRes = await sendZapiMessage(zapiConfig, {
            phone: targetPhone,
            message: caption,
            sendMode: "text",
            recipientRole: "guest",
            channelId: "transactional_chat",
            bypassTestMode: true,
            triggerEvent: "minibar_invoice_fallback",
            db
          });
          if (textFallbackRes && textFallbackRes.success !== false) {
            zapiRes = { ...textFallbackRes, fallbackToTextLink: true };
          }
        }

        if (zapiRes && zapiRes.success !== false) {
          const sentIso = new Date().toISOString();
          order.invoice.whatsappSentAt = sentIso;
          monitor.whatsapp.status = "enviado";
          monitor.whatsapp.sentAt = sentIso;
          monitor.whatsapp.lastError = null;

          if (typeof appendMessageToConversation === "function") {
            appendMessageToConversation(db, {
              phone: targetPhone,
              text: caption,
              type: "document",
              mediaUrl: invoiceFileUrl,
              fileName: safeFileName,
              sender: "CorpFlats (Financeiro)"
            });
          }
        } else {
          const errStr = zapiRes?.error || "Falha reportada pela Z-API ao enviar documento.";
          monitor.whatsapp.status = monitor.whatsapp.attempts < 3 ? "retentando" : "falha";
          monitor.whatsapp.lastError = errStr;
          await notifyAdminMinibarInvoiceFailure(order, "WhatsApp", errStr);
        }
      } catch (wErr) {
        const errStr = wErr.message || "Exceção no envio via Z-API.";
        monitor.whatsapp.status = monitor.whatsapp.attempts < 3 ? "retentando" : "falha";
        monitor.whatsapp.lastError = errStr;
        await notifyAdminMinibarInvoiceFailure(order, "WhatsApp", errStr);
      }
    }
  }

  // 2. Disparo via E-mail (SMTP)
  if (channels.includes("email")) {
    if (!targetEmail) {
      monitor.email.status = "falha";
      monitor.email.lastError = "Endereço de e-mail ausente no cadastro do hóspede.";
      await notifyAdminMinibarInvoiceFailure(order, "E-mail", monitor.email.lastError);
    } else if (typeof sendEmailAsync === "function") {
      monitor.email.attempts = (monitor.email.attempts || 0) + 1;
      monitor.email.lastAttemptAt = new Date().toISOString();
      monitor.email.status = "enviando";

      let diskFilePath = null;
      if (invoiceFileUrl.startsWith("/api/storage/files/")) {
        const rel = invoiceFileUrl.replace(/^\/api\/storage\/files\//, "");
        const candidate = path.join(UPLOADS_DIR, rel);
        if (fs.existsSync(candidate)) {
          diskFilePath = candidate;
        } else if (order.invoice?.fileData && !String(order.invoice.fileData).trim().startsWith("/") && !String(order.invoice.fileData).trim().startsWith("http")) {
          try {
            const rawB64 = String(order.invoice.fileData).replace(/^data:.*?;base64,/i, "").trim();
            const dir = path.dirname(candidate);
            if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
            fs.writeFileSync(candidate, Buffer.from(rawB64, "base64"));
            diskFilePath = candidate;
          } catch (_) {}
        }
      }

      try {
        sendEmailAsync({
          db,
          saveDatabase,
          reservationId: order.reservationId || 0,
          recipient: targetEmail,
          subject: `Nota Fiscal — Consumo de Frigobar Flat ${order.flatNumber} (CorpFlats)`,
          bodyHtml: `<p>Olá, <strong>${order.guestName}</strong>!</p>
<p>Segue em anexo a sua Nota Fiscal referente ao consumo de frigobar no <strong>Flat ${order.flatNumber}</strong>.</p>
<p>Valor total pago: <strong>R$ ${Number(order.totalAmount || 0).toFixed(2)}</strong></p>
<p>Você também pode baixar o arquivo diretamente pelo link: <a href="${fullDownloadUrl}">${safeFileName}</a></p>
<p>Agradecemos imensamente a sua estadia!</p>
<br/><p>Atenciosamente,<br/><strong>Equipe CorpFlats & Anserve</strong></p>`,
          attachments: diskFilePath ? [{ filename: safeFileName, path: diskFilePath }] : [],
          onDeliveryResult: async (resMail) => {
            if (resMail.success) {
              order.invoice.emailSentAt = resMail.sentAt || new Date().toISOString();
              monitor.email.status = "enviado";
              monitor.email.sentAt = order.invoice.emailSentAt;
              monitor.email.lastError = null;
            } else {
              const mailErr = resMail.error || "Falha no envio SMTP.";
              monitor.email.status = monitor.email.attempts < 3 ? "retentando" : "falha";
              monitor.email.lastError = mailErr;
              monitor.nextRetryAt =
                monitor.email.attempts < 3 ? new Date(Date.now() + 120000).toISOString() : null;
              await notifyAdminMinibarInvoiceFailure(order, "E-mail", mailErr);
            }
            updateInvoiceOverallMonitorStatus(order);
            saveDatabase("minibar_invoice_email_callback");
          }
        });
        // Optimistic timestamp for synchronous callers while callback monitors actual SMTP delivery
        order.invoice.emailSentAt = new Date().toISOString();
      } catch (mErr) {
        const errStr = mErr.message || "Falha ao enfileirar e-mail.";
        monitor.email.status = monitor.email.attempts < 3 ? "retentando" : "falha";
        monitor.email.lastError = errStr;
        await notifyAdminMinibarInvoiceFailure(order, "E-mail", errStr);
      }
    }
  }

  updateInvoiceOverallMonitorStatus(order);
  saveDatabase(isRetry ? "minibar_invoice_retried" : "minibar_invoice_dispatched");
  return monitor;
}

function updateInvoiceOverallMonitorStatus(order) {
  const m = order?.invoice?.deliveryMonitor;
  if (!m) return;
  const wOk = m.whatsapp?.status === "enviado";
  const eOk = m.email?.status === "enviado" || (order.invoice?.emailSentAt && m.email?.status === "enviando");
  const hasRetrying = m.whatsapp?.status === "retentando" || m.email?.status === "retentando";
  const hasFailed = m.whatsapp?.status === "falha" || m.email?.status === "falha";

  if (wOk && eOk) {
    m.overallStatus = "entregue";
    m.nextRetryAt = null;
  } else if (hasRetrying) {
    m.overallStatus = "retentando";
    if (!m.nextRetryAt) {
      m.nextRetryAt = new Date(Date.now() + 120000).toISOString();
    }
  } else if (hasFailed && (wOk || eOk)) {
    m.overallStatus = "parcial";
  } else if (hasFailed) {
    m.overallStatus = "falha";
  } else {
    m.overallStatus = "processando";
  }
}

// Worker em background para retentar automaticamente envios de Nota Fiscal que falharam temporariamente
if (!global.__minibarInvoiceRetryWorkerStarted) {
  global.__minibarInvoiceRetryWorkerStarted = true;
  setInterval(async () => {
    try {
      if (!Array.isArray(db.minibarOrders)) return;
      const nowMs = Date.now();
      for (const ord of db.minibarOrders) {
        const mon = ord?.invoice?.deliveryMonitor;
        if (!mon || !mon.nextRetryAt) continue;
        if (new Date(mon.nextRetryAt).getTime() > nowMs) continue;

        const retryChannels = [];
        if (mon.whatsapp?.status === "retentando" && (mon.whatsapp?.attempts || 0) < 3 && mon.whatsapp?.target) {
          retryChannels.push("whatsapp");
        }
        if (mon.email?.status === "retentando" && (mon.email?.attempts || 0) < 3 && mon.email?.target) {
          retryChannels.push("email");
        }

        mon.nextRetryAt = null;
        if (retryChannels.length > 0) {
          await dispatchMinibarInvoiceWithMonitoring(ord, { channels: retryChannels, isRetry: true });
        }
      }
    } catch (_) {}
  }, 60000);
}

// ── F03 & F04: Contexto Mobile (Acesso Direto por Reserva ou Flat) ──────────
app.post("/api/minibar/flat-context", (req, res) => {
  try {
    const { flatNumber, last4Digits, guestIndex } = req.body || {};
    const flatStr = String(flatNumber || "").trim();
    const digits = String(last4Digits || "").replace(/\D/g, "");

    if (!flatStr) {
      return res.status(400).json({
        success: false,
        error: "Número do flat é obrigatório."
      });
    }

    const reservation = findActiveOrRecentReservationForFlat(flatStr);
    if (!reservation) {
      return res.status(404).json({
        success: false,
        error: "Nenhuma reserva ativa ou recente encontrada para este flat."
      });
    }

    const reservationGuests = getReservationAllGuests(reservation);
    let matchedGuest = null;

    if (digits.length === 4) {
      // Se 4 dígitos foram enviados (retrocompatibilidade), localiza o hóspede correspondente
      for (const g of reservationGuests) {
        const gPhoneDigits = String(g.phone || "").replace(/\D/g, "");
        const gDocDigits = String(g.document || "").replace(/\D/g, "");
        if (
          (gPhoneDigits.length >= 4 && gPhoneDigits.endsWith(digits)) ||
          (gDocDigits.length >= 4 && gDocDigits.endsWith(digits))
        ) {
          matchedGuest = g;
          break;
        }
      }

      if (!matchedGuest) {
        const phoneDigits = String(reservation.guestPhone || "").replace(/\D/g, "");
        const docDigits = String(reservation.guestDocument || "").replace(/\D/g, "");
        if (phoneDigits.endsWith(digits) || docDigits.endsWith(digits)) {
          matchedGuest = reservationGuests[0] || {
            index: 1,
            role: "titular",
            guestId: reservation.guestId || null,
            name: reservation.guestName || "Hóspede",
            firstName: (reservation.guestName || "Hóspede").trim().split(" ")[0],
            phone: reservation.guestPhone || "",
            email: reservation.guestEmail || "",
            document: reservation.guestDocument || ""
          };
        }
      }

      if (!matchedGuest) {
        return res.status(401).json({
          success: false,
          error: "Dígitos incorretos ou nenhuma reserva ativa no flat"
        });
      }
    } else {
      // Acesso direto sem necessidade de digitar 4 dígitos de CPF ou telefone
      const reqIdx = Number(guestIndex || 0);
      matchedGuest =
        (reqIdx > 0 && reservationGuests.find(g => g.index === reqIdx)) ||
        reservationGuests[0] || {
          index: 1,
          role: "titular",
          guestId: reservation.guestId || null,
          name: reservation.guestName || "Hóspede",
          firstName: (reservation.guestName || "Hóspede").trim().split(" ")[0],
          phone: reservation.guestPhone || "",
          email: reservation.guestEmail || "",
          document: reservation.guestDocument || ""
        };
    }

    const guestName = matchedGuest.name || reservation.guestName || "Hóspede";
    const firstName = matchedGuest.firstName || guestName.trim().split(" ")[0];
    const resCode = reservation.code || `RES-${reservation.id}`;

    // Pedidos da reserva (pagos e pendentes)
    const allResOrders = (db.minibarOrders || []).filter(o =>
      doesMinibarOrderMatchReservation(o, reservation) &&
      o.paymentStatus !== "cancelado"
    );
    const paidOrders = allResOrders.filter(o => o.paymentStatus === "pago" || o.invoice?.status === "anexada" || Boolean(o.invoice?.invoiceFileUrl || o.invoice?.fileUrl));
    const statement = buildReservationMinibarStatement(reservation, flatStr);
    const pendingDiscrepancyOrder = sanitizeMinibarOrderForResponse(statement.primaryPendingOrder);

    const paidItemsMap = {};
    for (const ord of paidOrders) {
      if (Array.isArray(ord.items)) {
        for (const it of ord.items) {
          if (!paidItemsMap[it.productId]) {
            paidItemsMap[it.productId] = {
              productId: it.productId,
              productName: it.productName || it.name,
              quantity: 0,
              isCourtesy: Boolean(it.isCourtesy)
            };
          }
          paidItemsMap[it.productId].quantity += Number(it.quantity) || 0;
        }
      }
    }
    const paidItems = Object.values(paidItemsMap);
    const courtesyConsumed =
      paidItems.some(i => i.isCourtesy) ||
      statement.dailyLaunches.some(dl => (dl.items || []).some(i => i.isCourtesy));

    const paidOrdersHistory = paidOrders.map(ord => ({
      id: ord.id,
      guestName: ord.guestName || reservation.guestName,
      guestIndex: ord.guestIndex || 1,
      partialMode: ord.partialMode || "full",
      totalAmount: ord.totalAmount,
      paidAt: ord.paidAt || ord.createdAt,
      paymentMethod: ord.paymentMethod,
      items: ord.items || [],
      invoice: sanitizeMinibarInvoiceForResponse(ord.invoice),
      invoiceFileUrl: ord.invoice?.invoiceFileUrl || ord.invoice?.fileUrl || null,
      invoiceFileName: ord.invoice?.invoiceFileName || null,
      invoiceNumber: ord.invoice?.invoiceNumber || null,
      invoiceStatus: ord.invoice?.status || null
    }));

    // Gabarito padrão do flat
    const defaultTemplate = db.minibarDefaultStock?.flatOverrides?.[flatStr] || db.minibarDefaultStock?.globalTemplate || [];
    const defaultStock = {};
    for (const item of defaultTemplate) {
      defaultStock[item.productId] = item.defaultQuantity ?? item.quantity ?? 0;
    }

    const catalog = (db.minibarProducts || [])
      .filter(p => p.active !== false)
      .map(p => {
        const { cost, ...safe } = p;
        return safe;
      })
      .sort((a, b) => (Number(a.sortOrder) || 99) - (Number(b.sortOrder) || 99));

    res.json({
      success: true,
      operationMode: db.minibarSettings?.operationMode || "restocker_daily_launch",
      isCheckedOut: statement.isCheckedOut,
      hasFinalCheckoutInspection: statement.hasFinalCheckoutInspection,
      checkoutTime: statement.checkoutTime,
      dailyLaunches: statement.dailyLaunches,
      pendingLaunchedItems: statement.pendingLaunchedItems,
      pendingBalance: statement.pendingBalance,
      totalLaunchedAmount: statement.totalLaunchedAmount,
      totalPaidAmount: statement.totalPaidAmount,
      splitConfig: statement.splitConfig,
      splitBreakdown: statement.splitBreakdown,
      statement,
      guestName,
      firstName,
      phone: matchedGuest.phone || reservation.guestPhone || "",
      email: matchedGuest.email || reservation.guestEmail || "",
      document: matchedGuest.document || reservation.guestDocument || "",
      matchedGuestIndex: matchedGuest.index || 1,
      matchedGuestRole: matchedGuest.role || "titular",
      matchedGuestId: matchedGuest.guestId || null,
      reservationGuests,
      allGuests: reservationGuests,
      numGuests: Math.max(Number(reservation.numGuests || 1), reservationGuests.length),
      reservationCode: resCode,
      reservationId: reservation.id,
      flatNumber: flatStr,
      checkIn: reservation.checkinDate || reservation.checkIn,
      checkOut: reservation.checkoutDate || reservation.checkOut,
      catalog,
      defaultStock,
      paidItems,
      paidOrdersHistory,
      minibarOrders: getVisibleReservationMinibarOrders(reservation),
      pendingDiscrepancyOrder,
      courtesyConsumed
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

