// ── Persistência em Tempo Real da Divisão e Identificação dos Hóspedes do Flat ──
function handleSaveMinibarSplitConfig(req, res) {
  try {
    const {
      reservationCode: rawResCode,
      flatNumber: rawFlatNum,
      mode,
      itemAssignments,
      itemUpdate,
      guestUpdate,
      guests: incomingGuests
    } = req.body || {};

    let reservation = null;
    if (rawResCode) {
      reservation =
        findReservationByLocatorOrContact(String(rawResCode).trim()) ||
        (db.reservations || []).find(r => r.code === String(rawResCode).trim() || String(r.id) === String(rawResCode).trim());
    }
    if (!reservation && rawFlatNum) {
      reservation = findActiveOrRecentReservationForFlat(String(rawFlatNum).trim());
    }
    if (!reservation) {
      return res.status(404).json({ success: false, error: "Reserva não encontrada para salvar a divisão do frigobar." });
    }

    if (!reservation.minibarSplitConfig || typeof reservation.minibarSplitConfig !== "object") {
      reservation.minibarSplitConfig = {
        mode: "titular",
        itemAssignments: {},
        guests: [],
        updatedAt: new Date().toISOString()
      };
    }

    if (mode !== undefined) {
      reservation.minibarSplitConfig.mode = normalizeMinibarSplitMode(mode);
    }

    if (itemAssignments && typeof itemAssignments === "object") {
      reservation.minibarSplitConfig.itemAssignments = { ...itemAssignments };
    }

    if (itemUpdate && typeof itemUpdate === "object" && itemUpdate.itemKey) {
      if (!reservation.minibarSplitConfig.itemAssignments || typeof reservation.minibarSplitConfig.itemAssignments !== "object") {
        reservation.minibarSplitConfig.itemAssignments = {};
      }
      const key = String(itemUpdate.itemKey);
      if (itemUpdate.allocations === null || itemUpdate.allocations === undefined) {
        delete reservation.minibarSplitConfig.itemAssignments[key];
      } else {
        reservation.minibarSplitConfig.itemAssignments[key] = itemUpdate.allocations;
      }
    }

    // Atualização / adição rápida de hóspede do flat (Nome, WhatsApp, CPF/CNPJ, E-mail)
    const guestUpdatesList = [];
    if (guestUpdate && typeof guestUpdate === "object") {
      guestUpdatesList.push(guestUpdate);
    }
    if (Array.isArray(incomingGuests)) {
      for (const g of incomingGuests) {
        if (g && typeof g === "object") guestUpdatesList.push(g);
      }
    }

    if (guestUpdatesList.length > 0) {
      if (!Array.isArray(reservation.guests)) reservation.guests = [];
      if (!Array.isArray(reservation.minibarSplitConfig.guests)) reservation.minibarSplitConfig.guests = [];
      if (!Array.isArray(db.guests)) db.guests = [];

      for (const gu of guestUpdatesList) {
        const gIdx = Math.max(1, Number(gu.index || gu.order || 2));
        const gName = String(gu.name || gu.fullName || "").trim();
        const gPhone = String(gu.phone || gu.whatsapp || "").trim();
        const gEmail = String(gu.email || "").trim();
        const gDoc = String(gu.document || gu.cpf || "").replace(/\D/g, "");

        // 1. Atualiza se for o Titular (index === 1)
        if (gIdx === 1) {
          if (gName && !/^\d+º\s*h[óo]spede/i.test(gName)) reservation.guestName = gName;
          if (gPhone) reservation.guestPhone = gPhone;
          if (gEmail) reservation.guestEmail = gEmail;
          if (gDoc) reservation.guestDocument = gDoc;
        }

        // 2. Atualiza em reservation.guests
        let slotObj = reservation.guests.find(s => Number(s?.index || s?.order) === gIdx);
        if (!slotObj) {
          slotObj = { index: gIdx };
          reservation.guests.push(slotObj);
        }
        if (gName && !/^\d+º\s*h[óo]spede/i.test(gName)) slotObj.name = gName;
        if (gPhone !== undefined && gu.phone !== undefined) slotObj.phone = gPhone;
        else if (gPhone) slotObj.phone = gPhone;
        if (gEmail !== undefined && gu.email !== undefined) slotObj.email = gEmail;
        else if (gEmail) slotObj.email = gEmail;
        if (gDoc !== undefined && (gu.document !== undefined || gu.cpf !== undefined)) {
          slotObj.cpf = gDoc;
          slotObj.document = gDoc;
        } else if (gDoc) {
          slotObj.cpf = gDoc;
          slotObj.document = gDoc;
        }

        // 3. Atualiza em reservation.minibarSplitConfig.guests
        let splitSlot = reservation.minibarSplitConfig.guests.find(s => Number(s?.index) === gIdx);
        if (!splitSlot) {
          splitSlot = { index: gIdx };
          reservation.minibarSplitConfig.guests.push(splitSlot);
        }
        if (slotObj.name) splitSlot.name = slotObj.name;
        if (slotObj.phone !== undefined) splitSlot.phone = slotObj.phone;
        if (slotObj.email !== undefined) splitSlot.email = slotObj.email;
        if (slotObj.cpf !== undefined) {
          splitSlot.cpf = slotObj.cpf;
          splitSlot.document = slotObj.cpf;
        }

        // 4. Ajusta numGuests da reserva se um novo hóspede foi adicionado
        if (gIdx > Number(reservation.numGuests || 1)) {
          reservation.numGuests = gIdx;
        }

        // 5. Sincroniza no CRM (db.guests)
        let crmComp = db.guests.find(cg =>
          (slotObj.guestId && Number(cg.id) === Number(slotObj.guestId)) ||
          (gDoc.length >= 11 && String(cg.document || cg.documentNumber || "").replace(/\D/g, "") === gDoc) ||
          (gPhone.length >= 10 && String(cg.phone || "").replace(/\D/g, "") === gPhone.replace(/\D/g, ""))
        );
        if (!crmComp && gName && !/^\d+º\s*h[óo]spede/i.test(gName)) {
          crmComp = {
            id: db.guests.length > 0 ? Math.max(...db.guests.map(cg => Number(cg.id) || 0)) + 1 : 1,
            name: gName,
            fullName: gName,
            phone: gPhone,
            email: gEmail,
            document: gDoc,
            documentNumber: gDoc,
            city: "",
            notes: gIdx === 1
              ? `Hóspede titular na reserva ${reservation.code || reservation.id}`
              : `Hóspede acompanhante (${gIdx}º hóspede) na reserva ${reservation.code || reservation.id}`,
            tags: [],
            clientType: "avulso",
            createdAt: new Date().toISOString()
          };
          db.guests.push(crmComp);
        } else if (crmComp) {
          if (gName && !/^\d+º\s*h[óo]spede/i.test(gName)) {
            crmComp.name = gName;
            crmComp.fullName = gName;
          }
          if (gPhone) crmComp.phone = gPhone;
          if (gEmail) crmComp.email = gEmail;
          if (gDoc) {
            crmComp.document = gDoc;
            crmComp.documentNumber = gDoc;
          }
        }
        if (crmComp) {
          slotObj.guestId = crmComp.id;
          splitSlot.guestId = crmComp.id;
          if (gIdx === 1 && !reservation.guestId) reservation.guestId = crmComp.id;
        }
      }
    }

    reservation.minibarSplitConfig.updatedAt = new Date().toISOString();

    const flatStr = String(reservation.flatNumber || reservation.flatId || rawFlatNum || "").trim();
    const statement = buildReservationMinibarStatement(reservation, flatStr);

    // Se já realizou check-out ou já existem ordens de split automático, sincroniza imediatamente
    const resCode = reservation.code || `RES-${reservation.id}`;
    const hasExistingSplitOrders = (db.minibarOrders || []).some(
      o => o && o.isAutoSplitCheckoutOrder && o.reservationCode === resCode
    );
    let autoSplitOrders = [];
    if (statement.isCheckedOut || hasExistingSplitOrders) {
      autoSplitOrders = syncReservationAutoSplitOrders(reservation, flatStr, statement);
    }

    saveDatabase("minibar_split_config_updated");

    res.json({
      success: true,
      splitConfig: statement.splitConfig,
      splitBreakdown: statement.splitBreakdown,
      reservationGuests: statement.reservationGuests,
      allGuests: statement.reservationGuests,
      numGuests: Math.max(Number(reservation.numGuests || 1), statement.reservationGuests.length),
      autoSplitOrders,
      statement
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
}

app.post("/api/minibar/split-config", handleSaveMinibarSplitConfig);
app.put("/api/minibar/split-config", handleSaveMinibarSplitConfig);
app.post("/api/minibar/reservation-guests", handleSaveMinibarSplitConfig);
app.put("/api/minibar/reservation-guests", handleSaveMinibarSplitConfig);

// ── Confirmação Unificada de Check-out pelo Hóspede na Tela do Frigobar ──────
app.post("/api/public/minibar/confirm-checkout", async (req, res) => {
  try {
    let rawNum = String(req.body?.flatNumber || "").replace(/\D/g, "").trim();
    const code = String(req.body?.reservationCode || req.body?.code || req.body?.res || "").trim();
    const actorGuestName = String(req.body?.guestName || "").trim();
    let foundRes = null;

    if (code) {
      if (!db.reservations) db.reservations = [];
      foundRes =
        findReservationByLocatorOrContact(code) ||
        (db.reservations || []).find(r => r.code === code || String(r.id) === code);
      if (foundRes && !rawNum && foundRes.flatNumber) {
        rawNum = String(foundRes.flatNumber).replace(/\D/g, "").trim();
      }
    }

    if (!foundRes && rawNum) {
      foundRes = findActiveOrRecentReservationForFlat(rawNum);
    }

    if (!rawNum && !foundRes) {
      return res.status(400).json({
        success: false,
        error: "Por favor, informe o código da reserva ou o número do flat."
      });
    }

    const flat = (db.flats || []).find(f =>
      (rawNum && (f.number === rawNum || f.number.replace(/\D/g, "") === rawNum)) ||
      (foundRes && (f.id === foundRes.flatId || (foundRes.flatNumber && f.number === String(foundRes.flatNumber))))
    );

    const flatNumberStr = flat ? String(flat.number) : (rawNum || String(foundRes?.flatNumber || ""));
    const flatIdVal = flat ? flat.id : (foundRes?.flatId || null);

    const todayStr = getTodayStr();
    const now = new Date().toISOString();
    const nowBrl = getBrasiliaNow();
    const timeStr = nowBrl.timeStr;
    const guestDisplayName = actorGuestName || foundRes?.guestName || "Hóspede";

    if (!Array.isArray(db.cleaningRequests)) db.cleaningRequests = [];
    let existing = db.cleaningRequests.find(r =>
      ((flatIdVal && r.flatId === flatIdVal) || String(r.flatNumber) === flatNumberStr) &&
      r.requestDate === todayStr &&
      !r.isInstructionOnly &&
      r.source !== "manual_instruction" &&
      r.type !== "bed_adjustment_only" &&
      r.type !== "instruction"
    );

    if (existing) {
      if (existing.isDeleted || existing.status === "deleted") {
        existing.isDeleted = false;
        existing.status = "dirty";
        existing.completedAt = null;
        existing.cleaningStartedAt = null;
        existing.willCleanAt = null;
        delete existing.deletedAt;
        delete existing.deletedBy;
        delete existing.deletedReservationId;
      }
      existing.isVacant = true;
      existing.isVacantExplicitlySet = true;
      existing.vacantSource = "guest_checkout";
      existing.vacantSetAt = now;
      existing.leavingGuest = existing.leavingGuest || guestDisplayName;
      existing.updatedAt = now;
    } else if (flatIdVal || flatNumberStr) {
      existing = {
        id: db.cleaningRequests.length > 0 ? Math.max(...db.cleaningRequests.map(r => Number(r.id) || 0)) + 1 : 1,
        flatId: flatIdVal || 1,
        flatNumber: flatNumberStr,
        requestDate: todayStr,
        source: "guest_checkout",
        status: "dirty",
        assignedUserId: null,
        isVacant: true,
        isVacantExplicitlySet: true,
        vacantSource: "guest_checkout",
        vacantSetAt: now,
        isPriority: false,
        leavingGuest: guestDisplayName,
        arrivingGuest: null,
        pendingObservation: null,
        willCleanAt: null,
        cleaningStartedAt: null,
        completedAt: null,
        createdAt: now,
        updatedAt: now
      };
      db.cleaningRequests.unshift(existing);
    }

    if (flat) {
      flat.isOccupied = false;
      flat.updatedAt = now;
    }

    const matchingResList = foundRes
      ? [foundRes]
      : findCheckoutTargetReservationsForFlat(db, flatIdVal, flatNumberStr, todayStr);
    let anyEarlyCheckout = false;

    for (const r of matchingResList) {
      const earlyRes = await applyReservationCheckoutAndEarlyRelease(db, saveDatabase, r, {
        source: "link_digital",
        actorName: guestDisplayName || r.guestName,
        nowIso: now,
        todayStr,
        timeStr
      });
      if (earlyRes?.isEarlyCheckout) anyEarlyCheckout = true;

      await triggerCheckoutWhatsApp(db, saveDatabase, r, "link_digital").catch(e => {
        console.warn("[Minibar Confirm Checkout WhatsApp Trigger Error]:", e.message);
      });
    }

    cancelPendingStayRemindersForCheckout(db, saveDatabase, {
      flatId: flatIdVal,
      flatNumber: flatNumberStr,
      reason: "Cancelado: check-out informado pelo hóspede no portal de frigobar"
    });

    if (!db.breakfastOrders) db.breakfastOrders = [];
    db.breakfastOrders.forEach(o => {
      const isMatch = String(o.roomNumber) === flatNumberStr || matchingResList.some(mr => mr.code === o.reservationCode || mr.id === o.reservationId);
      const orderDeliveryTime = o.deliveryTime || "08:00";
      const isTodayTarget = o.date === todayStr && (isTimeBefore(timeStr, orderDeliveryTime) || o.status === "pending");
      const isFutureTarget = anyEarlyCheckout && o.date > todayStr;
      if (isMatch && (isTodayTarget || isFutureTarget) && o.status !== "cancelled" && o.status !== "ready" && o.status !== "delivered") {
        o.status = "cancelled";
        o.manuallyReactivated = false;
        o.cancelledByCheckout = true;
        o.checkoutWarningInfo = {
          isEarlyCheckout: anyEarlyCheckout,
          reportedBy: "Hóspede via Portal de Frigobar",
          checkoutDate: todayStr,
          checkoutTime: timeStr,
          updatedAt: now
        };
        o.cancelReason = `Check-out informado pelo hóspede via Portal de Frigobar às ${timeStr}.`;
      }
    });

    const targetRes = foundRes || matchingResList[0] || null;
    const statement = targetRes ? buildReservationMinibarStatement(targetRes, flatNumberStr) : null;
    const autoSplitOrders =
      targetRes && statement ? syncReservationAutoSplitOrders(targetRes, flatNumberStr, statement) : [];

    saveDatabase("minibar_guest_confirmed_checkout");

    if (typeof createNotification === "function") {
      createNotification({
        category: "checkout",
        title: anyEarlyCheckout
          ? `⚡ Check-out Antecipado - Apt ${flatNumberStr}`
          : `🚪 Check-out Realizado - Apt ${flatNumberStr}`,
        message: `Saída do hóspede ${guestDisplayName} (Apt ${flatNumberStr}) informada no Portal de Frigobar às ${timeStr}. Quarto desocupado e pagamento liberado.`,
        severity: anyEarlyCheckout ? "warning" : "info",
        metadata: {
          flatId: flatIdVal,
          flatNumber: flatNumberStr,
          guestName: guestDisplayName,
          code: foundRes?.code || matchingResList[0]?.code,
          isEarlyCheckout: anyEarlyCheckout
        },
        targetUrl: anyEarlyCheckout ? "/reservas" : "/dashboard"
      });
    }

    res.json({
      success: true,
      isCheckedOut: true,
      checkoutTime: timeStr,
      flatNumber: flatNumberStr,
      guestName: guestDisplayName,
      splitConfig: statement?.splitConfig || null,
      splitBreakdown: statement?.splitBreakdown || null,
      autoSplitOrders,
      statement,
      message: "Check-out confirmado com sucesso! O pagamento do seu consumo de frigobar já está liberado."
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── F05, F06, F07: Criação de Pedidos e Checkout Desacoplado (3 Modos Parciais) ──
app.post("/api/minibar/orders", async (req, res) => {
  try {
    const {
      orderId: incomingOrderId,
      reservationCode: rawResCode,
      flatNumber: rawFlatNumber,
      items,
      selectedLaunchItems,
      partialMode = "full",
      splitParts,
      customAmount,
      requireCheckout,
      paymentMethod,
      invoicePreference,
      document,
      documentType,
      email,
      phone: incomingPhone,
      companyName,
      consumerGuest,
      notes
    } = req.body || {};

    // Suporte a quitação direta de ordem pré-existente (ex: ORD-MB-DIV-... ou ORD-MB-LANC-...)
    let existingOrder = incomingOrderId ? (db.minibarOrders || []).find(o => o.id === incomingOrderId) : null;
    const incomingGuestIdx = Number(consumerGuest?.index || consumerGuest?.guestIndex || 0);
    if (
      existingOrder &&
      existingOrder.paymentStatus === "pago" &&
      (!incomingGuestIdx || !existingOrder.guestIndex || Number(existingOrder.guestIndex) === incomingGuestIdx)
    ) {
      return res.json({
        success: true,
        orderId: existingOrder.id,
        totalAmount: existingOrder.totalAmount,
        paymentStatus: "pago",
        alreadyPaid: true,
        order: existingOrder
      });
    }

    const reservationCode = rawResCode || existingOrder?.reservationCode;
    const flatNumber = rawFlatNumber || existingOrder?.flatNumber;

    // Localiza a reserva
    let reservation = null;
    if (reservationCode) {
      reservation = findReservationByLocatorOrContact(reservationCode) ||
        (db.reservations || []).find(r => r.code === reservationCode || String(r.id) === reservationCode);
    }
    if (!reservation && flatNumber) {
      reservation = findActiveOrRecentReservationForFlat(flatNumber);
    }

    const flatStr = String(flatNumber || reservation?.flatNumber || reservation?.flatId || "").trim();
    const finalResCode = reservation?.code || reservationCode || "";
    const statement = reservation ? buildReservationMinibarStatement(reservation, flatStr) : null;

    // Trava de pagamento antes da conferência pós check-out quando solicitado pela tela do hóspede
    if (requireCheckout && statement && !statement.hasFinalCheckoutInspection) {
      return res.status(400).json({
        success: false,
        code: "CHECKOUT_INSPECTION_REQUIRED",
        error: "Pagamento disponível apenas após a conferência de consumo pós check-out."
      });
    }

    // Identificação Individual do Hóspede Consumidor (Titular vs. 2º Hóspede / Acompanhante)
    const allGuests = getReservationAllGuests(reservation);
    const reqGuestIndex = Number(consumerGuest?.index || consumerGuest?.guestIndex || 1);
    const matchedSlot = allGuests.find(g => g.index === reqGuestIndex) || allGuests[0] || null;

    const finalGuestName = String(
      consumerGuest?.name ||
      (reqGuestIndex === 1 ? (existingOrder?.guestName || reservation?.guestName) : matchedSlot?.name) ||
      reservation?.guestName ||
      "Hóspede CorpFlats"
    ).trim();
    const finalGuestPhone = String(
      consumerGuest?.phone ||
      incomingPhone ||
      (reqGuestIndex === 1 ? (existingOrder?.guestPhone || reservation?.guestPhone) : matchedSlot?.phone) ||
      reservation?.guestPhone ||
      ""
    ).trim();
    const finalGuestEmail = String(
      email ||
      consumerGuest?.email ||
      (reqGuestIndex === 1 ? (existingOrder?.guestEmail || reservation?.guestEmail) : matchedSlot?.email) ||
      reservation?.guestEmail ||
      ""
    ).trim();
    const finalGuestDoc = String(
      document ||
      consumerGuest?.document ||
      (reqGuestIndex === 1 ? (existingOrder?.guestDocument || reservation?.guestDocument) : matchedSlot?.document) ||
      reservation?.guestDocument ||
      ""
    ).replace(/\D/g, "");

    let finalGuestId = consumerGuest?.guestId || matchedSlot?.guestId || (reqGuestIndex === 1 ? reservation?.guestId : null) || null;

    // Se for acompanhante (2º+ hóspede) e informou nome/telefone/CPF/email, sincroniza no slot da reserva e no CRM (db.guests)
    if (reservation && reqGuestIndex >= 2) {
      if (!Array.isArray(reservation.guests)) reservation.guests = [];
      let slotObj = reservation.guests.find(g => Number(g?.index || g?.order) === reqGuestIndex);
      if (!slotObj) {
        slotObj = { index: reqGuestIndex };
        reservation.guests.push(slotObj);
      }
      if (finalGuestName && !/^\d+º\s*h[óo]spede/i.test(finalGuestName)) slotObj.name = finalGuestName;
      if (finalGuestPhone) slotObj.phone = finalGuestPhone;
      if (finalGuestEmail) slotObj.email = finalGuestEmail;
      if (finalGuestDoc) slotObj.cpf = finalGuestDoc;

      if (!Array.isArray(db.guests)) db.guests = [];
      let crmComp = db.guests.find(cg =>
        (finalGuestId && Number(cg.id) === Number(finalGuestId)) ||
        (finalGuestDoc.length >= 11 && String(cg.document || cg.documentNumber || "").replace(/\D/g, "") === finalGuestDoc) ||
        (finalGuestPhone.length >= 10 && String(cg.phone || "").replace(/\D/g, "") === finalGuestPhone.replace(/\D/g, ""))
      );
      if (!crmComp && finalGuestName && !/^\d+º\s*h[óo]spede/i.test(finalGuestName)) {
        crmComp = {
          id: db.guests.length > 0 ? Math.max(...db.guests.map(cg => Number(cg.id) || 0)) + 1 : 1,
          name: finalGuestName,
          fullName: finalGuestName,
          phone: finalGuestPhone,
          email: finalGuestEmail,
          document: finalGuestDoc,
          documentNumber: finalGuestDoc,
          city: "",
          notes: `Hóspede acompanhante (${reqGuestIndex}º hóspede) na reserva ${finalResCode}`,
          tags: [],
          clientType: "avulso",
          createdAt: new Date().toISOString()
        };
        db.guests.push(crmComp);
      } else if (crmComp) {
        if (finalGuestPhone && !crmComp.phone) crmComp.phone = finalGuestPhone;
        if (finalGuestEmail && !crmComp.email) crmComp.email = finalGuestEmail;
        if (finalGuestDoc && !crmComp.document) {
          crmComp.document = finalGuestDoc;
          crmComp.documentNumber = finalGuestDoc;
        }
      }
      if (crmComp) {
        finalGuestId = crmComp.id;
        slotObj.guestId = crmComp.id;
      }
    }

    // Verifica cortesias já consumidas nesta reserva
    const existingOrders = (db.minibarOrders || []).filter(o => {
      if (!o) return false;
      const matchesRes = (finalResCode && o.reservationCode === finalResCode) ||
        (reservation?.id && String(o.reservationId) === String(reservation.id));
      if (!matchesRes) return false;
      return o.paymentStatus !== "cancelado";
    });
    let alreadyConsumedCourtesy = existingOrders.some(o => (o.items || []).some(i => i.isCourtesy));

    let orderItems = [];
    let totalAmount = 0;
    let settlesLaunchOrders = false;
    let recordedSelectedLaunchItems = [];

    const basePendingBalance =
      statement && statement.pendingBalance > 0
        ? statement.pendingBalance
        : existingOrder
        ? Number(existingOrder.remainingAmount ?? existingOrder.totalAmount ?? 0)
        : 0;

    // Modo 0: Divisão pré-configurada na reserva (Meio a Meio ou Por Item por Hóspede)
    if (partialMode === "configured_split") {
      const share = (statement?.splitBreakdown?.shares || []).find(s => Number(s.guestIndex) === reqGuestIndex);
      if (!share || Number(share.amount || 0) <= 0) {
        return res.status(400).json({
          success: false,
          error: "Não há saldo pendente atribuído para este hóspede na divisão configurada."
        });
      }
      totalAmount = Number(Number(share.amount).toFixed(2));
      orderItems = Array.isArray(share.items) && share.items.length > 0
        ? share.items.map(it => ({ ...it }))
        : [
            {
              productId: "split_share",
              productName: `Cota de Consumo de Frigobar (${share.guestName})`,
              quantity: 1,
              unitPrice: totalAmount,
              totalPrice: totalAmount,
              isCourtesy: false
            }
          ];
      recordedSelectedLaunchItems = Array.isArray(share.selectedLaunchItems)
        ? share.selectedLaunchItems.map(it => ({ ...it }))
        : [];
      settlesLaunchOrders = true;
      const splitOrdId = `ORD-MB-SPLIT-${finalResCode}-G${reqGuestIndex}`;
      const foundSplitOrd = (db.minibarOrders || []).find(
        o =>
          o &&
          o.paymentStatus !== "pago" &&
          o.paymentStatus !== "cancelado" &&
          (o.id === splitOrdId ||
            (o.isAutoSplitCheckoutOrder &&
              o.reservationCode === finalResCode &&
              Number(o.guestIndex || 1) === reqGuestIndex))
      );
      existingOrder = foundSplitOrd || null;
    }
    // Modo 1: Divisão em partes iguais (÷ 2, ÷ 3, ÷ 4...)
    else if (partialMode === "equal_split") {
      const parts = Math.max(2, Math.min(10, parseInt(splitParts, 10) || 2));
      if (basePendingBalance <= 0) {
        return res.status(400).json({ success: false, error: "Não há saldo pendente de frigobar para dividir." });
      }
      totalAmount = Number((basePendingBalance / parts).toFixed(2));
      orderItems = [
        {
          productId: "split_share",
          productName: `Cota de Consumo de Frigobar (1/${parts} do saldo pendente)`,
          quantity: 1,
          unitPrice: totalAmount,
          totalPrice: totalAmount,
          isCourtesy: false
        }
      ];
      settlesLaunchOrders = true;
      existingOrder = null; // Cria um pedido de pagamento individual para esta cota
    }
    // Modo 2: Valor parcial digitado em R$
    else if (partialMode === "custom_amount") {
      const parsedCustom = Number(String(customAmount || "0").replace(",", "."));
      if (isNaN(parsedCustom) || parsedCustom <= 0) {
        return res.status(400).json({ success: false, error: "Informe um valor parcial válido maior que R$ 0,00." });
      }
      if (basePendingBalance > 0 && parsedCustom > basePendingBalance + 0.05) {
        return res.status(400).json({
          success: false,
          error: `O valor informado (R$ ${parsedCustom.toFixed(2)}) excede o saldo pendente (R$ ${basePendingBalance.toFixed(2)}).`
        });
      }
      totalAmount = Number((basePendingBalance > 0 ? Math.min(parsedCustom, basePendingBalance) : parsedCustom).toFixed(2));
      orderItems = [
        {
          productId: "partial_payment",
          productName: `Pagamento Parcial de Consumo de Frigobar (Flat ${flatStr})`,
          quantity: 1,
          unitPrice: totalAmount,
          totalPrice: totalAmount,
          isCourtesy: false
        }
      ];
      settlesLaunchOrders = true;
      existingOrder = null; // Cria um pedido de pagamento individual para este valor parcial
    }
    // Modo 3: Seleção de itens lançados pela repositora (total ou parcial por item)
    else if (Array.isArray(selectedLaunchItems) && selectedLaunchItems.length > 0) {
      for (const sel of selectedLaunchItems) {
        const qty = parseInt(sel.quantity, 10);
        if (isNaN(qty) || qty <= 0) continue;
        const prod = (db.minibarProducts || []).find(p => p.id === sel.productId);
        const uPrice = Number(sel.unitPrice ?? prod?.price ?? 0);
        const itemTotal = Number((uPrice * qty).toFixed(2));
        totalAmount = Number((totalAmount + itemTotal).toFixed(2));
        const itemObj = {
          productId: sel.productId,
          productName: sel.productName || prod?.name || sel.productId,
          quantity: qty,
          unitPrice: uPrice,
          totalPrice: itemTotal,
          isCourtesy: false,
          launchOrderId: sel.launchOrderId || null,
          launchDate: sel.launchDate || null
        };
        orderItems.push(itemObj);
        recordedSelectedLaunchItems.push(itemObj);
      }
      if (basePendingBalance > 0 && totalAmount > basePendingBalance) {
        totalAmount = basePendingBalance;
      }
      settlesLaunchOrders = true;
      // Cria sempre uma ordem de pagamento dedicada para abater dos lançamentos diários
      existingOrder = null;
    }
    // Modo 4: Quitação direta de uma única ordem pré-existente ou fluxo tradicional de itens
    else if (
      existingOrder &&
      (existingOrder.source === "anserve_discrepancy" ||
        existingOrder.source === "restocker_launch" ||
        existingOrder.source === "guest_split_checkout" ||
        Boolean(existingOrder.isAutoSplitCheckoutOrder) ||
        String(existingOrder.id || "").startsWith("ORD-MB-DIV-") ||
        String(existingOrder.id || "").startsWith("ORD-MB-LANC-") ||
        String(existingOrder.id || "").startsWith("ORD-MB-SPLIT-")) &&
      Array.isArray(existingOrder.items) &&
      existingOrder.items.length > 0
    ) {
      orderItems = [...existingOrder.items];
      if (Array.isArray(existingOrder.selectedLaunchItems) && existingOrder.selectedLaunchItems.length > 0) {
        recordedSelectedLaunchItems = [...existingOrder.selectedLaunchItems];
      }
      if (existingOrder.settlesLaunchOrders || existingOrder.isAutoSplitCheckoutOrder) {
        settlesLaunchOrders = true;
      }
      totalAmount = Number(existingOrder.remainingAmount ?? existingOrder.totalAmount) || 0;
    } else {
      const effectiveItems = Array.isArray(items) && items.length > 0 ? items : (existingOrder?.items || []);
      if (!Array.isArray(effectiveItems) || effectiveItems.length === 0) {
        return res.status(400).json({ success: false, error: "Nenhum item selecionado para o pedido." });
      }
      for (const it of effectiveItems) {
        const prod = (db.minibarProducts || []).find(p => p.id === it.productId);
        if (!prod) continue;
        const rawQty = parseInt(it.quantity, 10);
        if (isNaN(rawQty) || rawQty <= 0) {
          continue;
        }

        let isCourtesy = Boolean(prod.isCourtesy);

        if (isCourtesy) {
          if (!reservation) {
            if (prod.extraPaidProductId) {
              const extraProd = (db.minibarProducts || []).find(p => p.id === prod.extraPaidProductId);
              if (extraProd) {
                const itemTotal = Number(extraProd.price || 0) * rawQty;
                totalAmount += itemTotal;
                orderItems.push({
                  productId: extraProd.id,
                  productName: extraProd.name,
                  quantity: rawQty,
                  unitPrice: Number(extraProd.price || 0),
                  totalPrice: itemTotal,
                  isCourtesy: false
                });
                continue;
              }
            }
            return res.status(400).json({
              success: false,
              error: "Cortesia de boas-vindas disponível apenas para hóspedes com reserva ativa no flat."
            });
          }

          if (alreadyConsumedCourtesy) {
            if (prod.extraPaidProductId) {
              const extraProd = (db.minibarProducts || []).find(p => p.id === prod.extraPaidProductId);
              if (extraProd) {
                const itemTotal = Number(extraProd.price || 0) * rawQty;
                totalAmount += itemTotal;
                orderItems.push({
                  productId: extraProd.id,
                  productName: extraProd.name,
                  quantity: rawQty,
                  unitPrice: Number(extraProd.price || 0),
                  totalPrice: itemTotal,
                  isCourtesy: false
                });
              }
            } else {
              const paidPrice = Number(prod.price) || 0;
              if (paidPrice === 0) {
                return res.status(400).json({
                  success: false,
                  error: "O kit de cortesia gratuito já foi usufruído nesta estadia."
                });
              }
              const itemTotal = paidPrice * rawQty;
              totalAmount += itemTotal;
              orderItems.push({
                productId: prod.id,
                productName: prod.name,
                quantity: rawQty,
                unitPrice: paidPrice,
                totalPrice: itemTotal,
                isCourtesy: false
              });
            }
          } else {
            const courtesyLimit = prod.courtesyLimitPerStay || 1;
            const freeQty = Math.min(rawQty, courtesyLimit);
            const extraQty = rawQty - freeQty;

            orderItems.push({
              productId: prod.id,
              productName: prod.name,
              quantity: freeQty,
              unitPrice: 0,
              totalPrice: 0,
              isCourtesy: true
            });
            alreadyConsumedCourtesy = true;

            if (extraQty > 0) {
              if (prod.extraPaidProductId) {
                const extraProd = (db.minibarProducts || []).find(p => p.id === prod.extraPaidProductId);
                if (extraProd) {
                  const extraPrice = Number(extraProd.price) || 0;
                  const extraTotal = extraPrice * extraQty;
                  totalAmount += extraTotal;
                  orderItems.push({
                    productId: extraProd.id,
                    productName: extraProd.name,
                    quantity: extraQty,
                    unitPrice: extraPrice,
                    totalPrice: extraTotal,
                    isCourtesy: false
                  });
                }
              } else if (Number(prod.price) > 0) {
                const paidPrice = Number(prod.price);
                const extraTotal = paidPrice * extraQty;
                totalAmount += extraTotal;
                orderItems.push({
                  productId: prod.id,
                  productName: prod.name,
                  quantity: extraQty,
                  unitPrice: paidPrice,
                  totalPrice: extraTotal,
                  isCourtesy: false
                });
              }
            }
          }
        } else {
          const unitPrice = Number(prod.price) || 0;
          const itemTotal = unitPrice * rawQty;
          totalAmount += itemTotal;
          orderItems.push({
            productId: prod.id,
            productName: prod.name,
            quantity: rawQty,
            unitPrice,
            totalPrice: itemTotal,
            isCourtesy: false
          });
        }
      }
    }

    if (orderItems.length === 0) {
      return res.status(400).json({ success: false, error: "Nenhum produto válido encontrado nos itens." });
    }

    const orderId = existingOrder ? existingOrder.id : `ORD-MB-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
    const cleanDoc = finalGuestDoc;
    const cleanEmail = finalGuestEmail;

    const fiscalPreferences = {
      invoiceDescriptionType: invoicePreference || "detailed",
      documentType: documentType || (cleanDoc.length === 14 ? "cnpj" : "cpf"),
      documentNumber: cleanDoc,
      companyName: companyName || "",
      email: cleanEmail,
      phone: finalGuestPhone,
      payerName: finalGuestName
    };

    // Caso de Cortesia Gratuita (total 0)
    if (totalAmount <= 0) {
      if (!reservation || (reservation.status || "").toLowerCase() === "cancelada") {
        return res.status(400).json({
          success: false,
          error: "Cortesia de boas-vindas disponível apenas para hóspedes com reserva ativa no flat."
        });
      }
      const courtesyOrder = {
        id: orderId,
        flatNumber: flatStr,
        reservationId: reservation?.id || null,
        reservationCode: finalResCode,
        guestId: finalGuestId,
        guestIndex: reqGuestIndex,
        guestRole: reqGuestIndex > 1 ? "acompanhante" : "titular",
        guestName: finalGuestName,
        guestPhone: finalGuestPhone,
        guestDocument: cleanDoc,
        guestEmail: cleanEmail,
        items: orderItems,
        totalAmount: 0,
        paymentMethod: "cortesia",
        paymentStatus: "pago",
        paidAt: new Date().toISOString(),
        source: "guest_mobile",
        fiscalPreferences,
        invoice: { status: "nao_aplicavel" },
        notes: notes || "",
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
      db.minibarOrders.push(courtesyOrder);
      saveDatabase("minibar_courtesy_order");

      return res.json({
        success: true,
        orderId,
        totalAmount: 0,
        paymentStatus: "pago",
        isCourtesyOnly: true,
        order: courtesyOrder
      });
    }

    const itemsSummaryText = orderItems
      .map(it => `${it.quantity}x ${it.productName || it.productId}`)
      .join(", ");
    const serverBaseUrl = (process.env.SERVER_BASE_URL || db.settings?.baseUrl || "https://corpflats.com.br").replace(/\/+$/, "");

    // Pedido Pago: PIX ou Cartão
    if (paymentMethod === "credit_card") {
      let pref = null;
      try {
        pref = await createMercadoPagoPreference({
          reservationCode: "MB-" + orderId,
          amount: totalAmount,
          guestName: finalGuestName,
          guestEmail: cleanEmail || "hospede@corpflats.com.br",
          nights: 1,
          flatNumber: flatStr,
          isMinibar: true,
          customTitle: `Consumo de Frigobar - Flat ${flatStr} (CorpFlats)`,
          customDescription: `Consumo de frigobar no Flat ${flatStr}: ${itemsSummaryText}`.substring(0, 240),
          customBackUrls: {
            success: `${serverBaseUrl}/minha-reserva/${finalResCode || flatStr}/frigobar?ord=${orderId}&payment=success`,
            failure: `${serverBaseUrl}/minha-reserva/${finalResCode || flatStr}/frigobar?ord=${orderId}&payment=failure`,
            pending: `${serverBaseUrl}/minha-reserva/${finalResCode || flatStr}/frigobar?ord=${orderId}&payment=pending`
          }
        });
      } catch (mpErr) {
        console.warn("[Minibar MP] Aviso na preferência Mercado Pago:", mpErr.message);
      }

      const initPoint = pref?.initPoint || `https://www.mercadopago.com.br/checkout/v1/redirect?pref_id=mock_${orderId}`;

      if (existingOrder) {
        existingOrder.paymentMethod = "credit_card";
        existingOrder.paymentStatus = "pendente";
        existingOrder.guestId = finalGuestId || existingOrder.guestId || null;
        existingOrder.guestIndex = reqGuestIndex;
        existingOrder.guestRole = reqGuestIndex > 1 ? "acompanhante" : "titular";
        existingOrder.guestName = finalGuestName;
        existingOrder.guestPhone = finalGuestPhone;
        existingOrder.guestDocument = cleanDoc;
        existingOrder.guestEmail = cleanEmail;
        existingOrder.mpPreferenceId = pref?.id || `pref_${orderId}`;
        existingOrder.mpInitPoint = initPoint;
        existingOrder.fiscalPreferences = fiscalPreferences;
        if (settlesLaunchOrders) existingOrder.settlesLaunchOrders = true;
        if (recordedSelectedLaunchItems.length > 0) existingOrder.selectedLaunchItems = recordedSelectedLaunchItems;
        existingOrder.updatedAt = new Date().toISOString();
        if (orderItems.length > 0) existingOrder.items = orderItems;
        if (totalAmount > 0) existingOrder.totalAmount = totalAmount;
        saveDatabase("minibar_order_updated_card");

        return res.json({
          success: true,
          orderId,
          totalAmount: existingOrder.totalAmount,
          paymentMethod: "credit_card",
          paymentStatus: "pendente",
          initPoint,
          order: existingOrder
        });
      }

      const newOrder = {
        id: orderId,
        flatNumber: flatStr,
        reservationId: reservation?.id || null,
        reservationCode: finalResCode,
        guestId: finalGuestId,
        guestIndex: reqGuestIndex,
        guestRole: reqGuestIndex > 1 ? "acompanhante" : "titular",
        guestName: finalGuestName,
        guestPhone: finalGuestPhone,
        guestDocument: cleanDoc,
        guestEmail: cleanEmail,
        items: orderItems,
        selectedLaunchItems: recordedSelectedLaunchItems,
        partialMode: partialMode || "full",
        settlesLaunchOrders,
        totalAmount,
        paymentMethod: "credit_card",
        paymentStatus: "pendente",
        source: "guest_mobile",
        mpPreferenceId: pref?.id || `pref_${orderId}`,
        mpInitPoint: initPoint,
        fiscalPreferences,
        invoice: { status: "pendente" },
        notes: notes || "",
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
      db.minibarOrders.push(newOrder);
      saveDatabase("minibar_order_created_card");

      return res.json({
        success: true,
        orderId,
        totalAmount,
        paymentMethod: "credit_card",
        paymentStatus: "pendente",
        initPoint,
        order: newOrder
      });
    }

    // Padrão: PIX Banco Inter
    let cob = null;
    try {
      cob = await createInterPixCob({
        amount: totalAmount,
        description: `Consumo de Frigobar Flat ${flatStr}`,
        debtorName: finalGuestName,
        debtorDocument: cleanDoc,
        reservationCode: orderId
      });
    } catch (interErr) {
      console.warn("[Minibar Inter PIX] Falha no mTLS ou API real. Gerando mock/simulado:", interErr.message);
    }

    let txid = cob?.txid;
    let copiaECola = cob?.pixCopiaECola;
    if (!txid || !copiaECola) {
      txid = "TXMB" + crypto.randomBytes(12).toString("hex").toUpperCase();
      try {
        copiaECola = generateStaticPixPayload({
          pixKey: db.settings?.interConfig?.pixKey || "47964813000165",
          amount: totalAmount,
          merchantName: "CORPFLATS LTDA",
          merchantCity: "CAMPOS DOS GOYTACAZES",
          txid
        });
      } catch (_) {
        copiaECola = `00020126580014br.gov.bcb.pix0136${txid}520400005303986540${totalAmount.toFixed(2)}5802BR5915CORPFLATS LTDA6014CAMPOS62070503***6304`;
      }
    }

    const expiresAt = new Date(Date.now() + 86400000).toISOString();

    if (existingOrder) {
      existingOrder.paymentMethod = "pix";
      existingOrder.paymentStatus = "pendente";
      existingOrder.guestId = finalGuestId || existingOrder.guestId || null;
      existingOrder.guestIndex = reqGuestIndex;
      existingOrder.guestRole = reqGuestIndex > 1 ? "acompanhante" : "titular";
      existingOrder.guestName = finalGuestName;
      existingOrder.guestPhone = finalGuestPhone;
      existingOrder.guestDocument = cleanDoc;
      existingOrder.guestEmail = cleanEmail;
      existingOrder.pixTxId = txid;
      existingOrder.pixCopiaECola = copiaECola;
      existingOrder.pixExpiresAt = expiresAt;
      existingOrder.fiscalPreferences = fiscalPreferences;
      if (settlesLaunchOrders) existingOrder.settlesLaunchOrders = true;
      if (recordedSelectedLaunchItems.length > 0) existingOrder.selectedLaunchItems = recordedSelectedLaunchItems;
      existingOrder.updatedAt = new Date().toISOString();
      if (orderItems.length > 0) existingOrder.items = orderItems;
      if (totalAmount > 0) existingOrder.totalAmount = totalAmount;
      saveDatabase("minibar_order_updated_pix");

      return res.json({
        success: true,
        orderId,
        totalAmount: existingOrder.totalAmount,
        paymentMethod: "pix",
        paymentStatus: "pendente",
        pixQrCode: copiaECola,
        pixCopiaECola: copiaECola,
        expiresAt,
        order: existingOrder
      });
    }

    const newOrder = {
      id: orderId,
      flatNumber: flatStr,
      reservationId: reservation?.id || null,
      reservationCode: finalResCode,
      guestId: finalGuestId,
      guestIndex: reqGuestIndex,
      guestRole: reqGuestIndex > 1 ? "acompanhante" : "titular",
      guestName: finalGuestName,
      guestPhone: finalGuestPhone,
      guestDocument: cleanDoc,
      guestEmail: cleanEmail,
      items: orderItems,
      selectedLaunchItems: recordedSelectedLaunchItems,
      partialMode: partialMode || "full",
      settlesLaunchOrders,
      totalAmount,
      paymentMethod: "pix",
      paymentStatus: "pendente",
      source: "guest_mobile",
      pixTxId: txid,
      pixCopiaECola: copiaECola,
      pixExpiresAt: expiresAt,
      fiscalPreferences,
      invoice: { status: "pendente" },
      notes: notes || "",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
    db.minibarOrders.push(newOrder);
    saveDatabase("minibar_order_created_pix");

    return res.json({
      success: true,
      orderId,
      totalAmount,
      paymentMethod: "pix",
      paymentStatus: "pendente",
      pixQrCode: copiaECola,
      pixCopiaECola: copiaECola,
      expiresAt,
      order: newOrder
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get("/api/minibar/orders/:id/status", async (req, res) => {
  try {
    const orderId = req.params.id;
    if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
    const order = db.minibarOrders.find(o => o.id === orderId);
    if (!order) {
      return res.status(404).json({ success: false, error: "Pedido não encontrado." });
    }

    // Se estiver pendente, faz polling ativo
    if (order.paymentStatus === "pendente") {
      if (order.paymentMethod === "credit_card" || order.paymentMethod === "cartao_credito") {
        try {
          const mpApproved = await checkMercadoPagoPaymentByRef("MB-" + order.id);
          if (mpApproved) {
            settleMinibarOrder(order, {
              paidAt: mpApproved.date_approved || new Date().toISOString(),
              mpPaymentId: String(mpApproved.id),
              paymentMethod: order.paymentMethod,
              source: "mercadopago_polling"
            });
          }
        } catch (_) {}
      } else if (order.paymentMethod === "pix" && order.pixTxId) {
        try {
          const extrato = await getCachedInterExtratoCompleto();
          if (extrato && Array.isArray(extrato.transacoes)) {
            const found = extrato.transacoes.find(t =>
              t.tipoTransacao === "PIX" &&
              t.tipoOperacao === "C" &&
              (String(t.codigoTransacao || t.txid || "").includes(order.pixTxId) ||
               Math.abs(Number(t.valor) - Number(order.totalAmount)) < 0.01)
            );
            if (found) {
              settleMinibarOrder(order, {
                paidAt: found.dataHora || new Date().toISOString(),
                pixEndToEndId: found.endToEndId || `E2E_${Date.now()}`,
                paymentMethod: "pix",
                source: "inter_pix_polling"
              });
            }
          }
        } catch (_) {}
      }
    }

    res.json({
      success: true,
      status: order.paymentStatus,
      paidAt: order.paidAt || null,
      order: sanitizeMinibarOrderForResponse(order)
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── F08: Upload de Nota Fiscal e Disparo Multicanal com Monitoramento ─────────
app.post("/api/minibar/orders/:id/invoice", async (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarInvoiceIssuer(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito ao faturamento, supervisão e administração." });
    }

    const orderId = req.params.id;
    if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
    const order = db.minibarOrders.find(o => o.id === orderId);
    if (!order) {
      return res.status(404).json({ success: false, error: "Pedido não encontrado." });
    }

    // Garante vínculo da reserva no pedido se ausente
    if ((!order.reservationId || !order.reservationCode) && order.flatNumber) {
      const linkedRes = findActiveOrRecentReservationForFlat(String(order.flatNumber));
      if (linkedRes) {
        if (!order.reservationId) order.reservationId = linkedRes.id;
        if (!order.reservationCode) order.reservationCode = linkedRes.code || `RES-${linkedRes.id}`;
      }
    }

    const { fileData, fileName, invoiceNumber } = req.body || {};
    if (!fileData) {
      return res.status(400).json({ success: false, error: "Arquivo da Nota Fiscal (Base64 ou URL) é obrigatório." });
    }

    const fileDataStr = String(fileData).trim();
    const isDataUri = fileDataStr.startsWith("data:");
    const isHttpUrl = fileDataStr.startsWith("http://") || fileDataStr.startsWith("https://") || fileDataStr.startsWith("/api/");

    let inferredExt = "pdf";
    if (isDataUri) {
      const mimeMatch = fileDataStr.match(/^data:([^;]+);base64,/i);
      const mimeLower = (mimeMatch ? mimeMatch[1] : "").toLowerCase();
      if (mimeLower.includes("png")) inferredExt = "png";
      else if (mimeLower.includes("jpeg") || mimeLower.includes("jpg")) inferredExt = "jpg";
      else if (mimeLower.includes("webp")) inferredExt = "webp";
    }
    let safeFileName = String(fileName || "").trim();
    if (!safeFileName) {
      safeFileName = `NF_Frigobar_${order.flatNumber}_${order.id}.${inferredExt}`;
    } else if (!safeFileName.includes(".")) {
      safeFileName = `${safeFileName}.${inferredExt}`;
    }

    const invoicesDir = path.join(UPLOADS_DIR, "invoices");
    if (!fs.existsSync(invoicesDir)) {
      fs.mkdirSync(invoicesDir, { recursive: true });
    }

    const diskFileName = `${Date.now()}_${safeFileName.replace(/[^a-zA-Z0-9._-]/g, "_")}`;
    const filePath = path.join(invoicesDir, diskFileName);

    let invoiceFileUrl = `/api/storage/files/invoices/${diskFileName}`;

    if (isDataUri || (!isHttpUrl && fileDataStr.length > 100)) {
      const base64Content = fileDataStr.replace(/^data:.*?;base64,/i, "");
      await fs.promises.writeFile(filePath, Buffer.from(base64Content, "base64"));
    } else {
      invoiceFileUrl = fileDataStr;
    }

    order.invoice = {
      status: "anexada",
      invoiceFileUrl,
      fileUrl: invoiceFileUrl,
      invoiceFileName: safeFileName,
      invoiceNumber: invoiceNumber || null,
      fileData: (isDataUri || (!isHttpUrl && fileDataStr.length > 100)) ? fileDataStr : undefined,
      attachedAt: new Date().toISOString(),
      attachedBy: user?.name || "Supervisão Anserve",
      whatsappSentAt: null,
      emailSentAt: null,
      deliveryMonitor: null
    };
    order.updatedAt = new Date().toISOString();

    // Sincroniza referência da NF dentro de reservation.minibarPayments para acesso rápido na reserva
    const reservation = (db.reservations || []).find(r => doesMinibarOrderMatchReservation(order, r));
    if (reservation && Array.isArray(reservation.minibarPayments)) {
      const mpEntry = reservation.minibarPayments.find(mp => mp.orderId === order.id);
      if (mpEntry) {
        mpEntry.invoiceFileUrl = invoiceFileUrl;
        mpEntry.invoiceFileName = safeFileName;
        mpEntry.invoiceNumber = invoiceNumber || null;
        mpEntry.invoiceAttachedAt = order.invoice.attachedAt;
      }
    }

    await dispatchMinibarInvoiceWithMonitoring(order, { channels: ["whatsapp", "email"], isRetry: false });

    saveDatabase("minibar_invoice_attached");
    res.json({
      success: true,
      invoice: sanitizeMinibarInvoiceForResponse(order.invoice),
      deliveryMonitor: order.invoice.deliveryMonitor,
      order: sanitizeMinibarOrderForResponse(order)
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── F08.1: Correção de Contato e Reenvio Monitorado da Nota Fiscal ────────────
app.post("/api/minibar/orders/:id/invoice/retry", async (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarInvoiceIssuer(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito ao faturamento, supervisão e administração." });
    }

    const orderId = req.params.id;
    const order = (db.minibarOrders || []).find(o => o.id === orderId);
    if (!order || !order.invoice || order.invoice.status !== "anexada") {
      return res.status(404).json({ success: false, error: "Pedido ou Nota Fiscal anexada não encontrada." });
    }

    const { phone, email, channels, channel } = req.body || {};
    if (phone !== undefined && String(phone).trim()) {
      order.guestPhone = String(phone).trim();
      if (!order.fiscalPreferences) order.fiscalPreferences = {};
      order.fiscalPreferences.phone = String(phone).trim();
    }
    if (email !== undefined && String(email).trim()) {
      order.guestEmail = String(email).trim();
      if (!order.fiscalPreferences) order.fiscalPreferences = {};
      order.fiscalPreferences.email = String(email).trim();
    }

    let targetChannels = ["whatsapp", "email"];
    if (Array.isArray(channels) && channels.length > 0) {
      targetChannels = channels;
    } else if (typeof channel === "string" && channel.trim()) {
      const ch = channel.trim().toLowerCase();
      if (ch === "whatsapp") targetChannels = ["whatsapp"];
      else if (ch === "email") targetChannels = ["email"];
    }

    const monitor = await dispatchMinibarInvoiceWithMonitoring(order, {
      channels: targetChannels,
      isRetry: true
    });

    res.json({
      success: true,
      invoice: sanitizeMinibarInvoiceForResponse(order.invoice),
      deliveryMonitor: monitor,
      order: sanitizeMinibarOrderForResponse(order)
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get("/api/minibar/invoices/delivery-monitor", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarInvoiceIssuer(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito." });
    }

    const ordersWithInvoices = (db.minibarOrders || []).filter(o => o?.invoice?.status === "anexada");
    const failedDeliveries = ordersWithInvoices
      .filter(o => {
        const m = o.invoice?.deliveryMonitor;
        if (!m) return false;
        return (
          m.overallStatus === "falha" ||
          m.overallStatus === "parcial" ||
          m.overallStatus === "retentando" ||
          m.whatsapp?.status === "falha" ||
          m.email?.status === "falha"
        );
      })
      .map(sanitizeMinibarOrderForResponse);

    res.json({
      success: true,
      totalAttached: ordersWithInvoices.length,
      failedCount: failedDeliveries.length,
      failedOrders: failedDeliveries,
      failedInvoices: failedDeliveries
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── F09: Lançamento Diário de Consumo pela Repositora, Vistoria & Alerta da Sofia ──
app.post("/api/minibar/inspections", async (req, res) => {
  try {
    const user = getAuthUser(req);
    const pinHeader = req.headers["x-anserve-pin"];
    const tokenHeader = req.headers["x-anserve-token"];
    const pinStr = pinHeader ? String(pinHeader).trim() : "";
    const matchedPinUser = pinStr
      ? (db.users || []).find(u => u.active !== false && (u.role === "anserve_repositora" || u.role === "anserve_gestor") && u.pin && String(u.pin).trim() === pinStr)
      : null;
    const isPinValid = Boolean(matchedPinUser) || (pinStr && pinStr === String(db.minibarSettings?.anservePin || "1234"));
    const testToken = req.headers["x-test-token"] || req.headers["authorization"];
    const isTestAuthorized = testToken === "test-token" || testToken === "Bearer test-token";
    const todayBrForShift = getBrasiliaNow().date;
    const decodedAnsToken = tokenHeader ? verifyAuthToken(String(tokenHeader).trim()) : null;
    const isAnsTokenShiftExpired = Boolean(
      decodedAnsToken &&
      decodedAnsToken.role === "anserve_repositora" &&
      decodedAnsToken.shiftDate &&
      String(decodedAnsToken.shiftDate) !== String(todayBrForShift)
    );
    const isValidAnsToken = Boolean(tokenHeader) && !isAnsTokenShiftExpired;
    const isStaff = isMinibarStaff(user) || isPinValid || isValidAnsToken || isTestAuthorized;
    const isTestBypass = (process.env.NODE_ENV === "test" && req.headers["x-enforce-auth"] !== "true");

    if (!isStaff && !isTestBypass) {
      if (isAnsTokenShiftExpired && !user) {
        return res.status(401).json({
          success: false,
          code: "SHIFT_EXPIRED",
          error: "O turno anterior encerrou na virada do dia. Selecione a operadora e digite seu PIN para iniciar o turno de hoje."
        });
      }
      if (!user && !pinHeader && !tokenHeader) {
        return res.status(401).json({ success: false, error: "Autenticação obrigatória. Faça login com PIN ou perfil autorizado." });
      }
      return res.status(403).json({ success: false, error: "Acesso restrito à equipe de reposição e supervisão." });
    }

    const {
      flatNumber,
      reservationCode,
      inspectedBy,
      inspectorId: bodyInspectorId,
      status,
      isDailyLaunch,
      launchDate: bodyLaunchDate,
      notifySofia: bodyNotifySofia,
      consumedItems,
      missingItems,
      countedItems,
      photos,
      notes,
      restockedItems,
      welcomeKitConsumption,
      consumedCourtesyItems
    } = req.body || {};

    const flatStr = String(flatNumber || "").trim();
    if (!flatStr) {
      return res.status(400).json({ success: false, error: "Número do flat é obrigatório." });
    }

    let reservation = null;
    if (reservationCode) {
      reservation = findReservationByLocatorOrContact(reservationCode) ||
        (db.reservations || []).find(r => r.code === reservationCode || String(r.id) === reservationCode);
    }
    if (!reservation) {
      reservation = findActiveOrRecentReservationForFlat(flatStr);
    }

    const finalResCode = reservation?.code || reservationCode || "";
    const todayStr = getBrasiliaNow().date;
    const launchDateStr = String(bodyLaunchDate || todayStr).slice(0, 10);
    const launchDateBr = formatMinibarDateBr(launchDateStr);

    const resolvedInspectorUser =
      user ||
      matchedPinUser ||
      (bodyInspectorId ? (db.users || []).find(u => Number(u.id) === Number(bodyInspectorId)) : null) ||
      (inspectedBy
        ? (db.users || []).find(
            u =>
              (u.name && u.name.trim().toLowerCase() === String(inspectedBy).trim().toLowerCase()) ||
              (u.username && u.username.trim().toLowerCase() === String(inspectedBy).trim().toLowerCase())
          )
        : null);
    const resolvedInspectorName =
      inspectedBy || resolvedInspectorUser?.name || resolvedInspectorUser?.username || "Repositora Anserve";

    // R4: Conferência do Kit de Boas-Vindas (Cortesia da Casa)
    let waterCupsConsumed = 0;
    let mendoratoPeanutsConsumed = 0;

    if (welcomeKitConsumption && typeof welcomeKitConsumption === "object") {
      waterCupsConsumed = Math.min(2, Math.max(0, Number(welcomeKitConsumption.waterCups ?? welcomeKitConsumption.waterCupsConsumed) || 0));
      mendoratoPeanutsConsumed = Math.min(2, Math.max(0, Number(welcomeKitConsumption.mendoratoPeanuts ?? welcomeKitConsumption.peanutsConsumed) || 0));
    }

    if (Array.isArray(consumedCourtesyItems)) {
      for (const cit of consumedCourtesyItems) {
        const pid = String(cit.productId || cit.id || "").toLowerCase();
        const q = Number(cit.quantity || cit.qty) || 0;
        if (pid.includes("agua") || pid.includes("água") || pid.includes("copo")) {
          waterCupsConsumed = Math.min(2, Math.max(waterCupsConsumed, q));
        } else if (pid.includes("amendoim") || pid.includes("mendorato")) {
          mendoratoPeanutsConsumed = Math.min(2, Math.max(mendoratoPeanutsConsumed, q));
        }
      }
    }

    const waterUnitCost = Number((db.minibarProducts || []).find(p => p.id === "prod_agua_mineral_copo")?.cost ?? 2.00);
    const welcomeKitRecord = (welcomeKitConsumption || Array.isArray(consumedCourtesyItems) || waterCupsConsumed > 0 || mendoratoPeanutsConsumed > 0) ? {
      waterCups: waterCupsConsumed,
      mendoratoPeanuts: mendoratoPeanutsConsumed,
      waterUnitCost,
      waterTotalCost: Number((waterCupsConsumed * waterUnitCost).toFixed(2)),
      mendoratoUnitCost: 0.00,
      mendoratoTotalCost: 0.00,
      waterSupplier: "anserve",
      mendoratoSupplier: "hotel_proprio"
    } : null;

    if (reservation && welcomeKitRecord) {
      if (!reservation.welcomeKitConsumption) reservation.welcomeKitConsumption = {};
      reservation.welcomeKitConsumption = {
        waterCups: Math.max(Number(reservation.welcomeKitConsumption.waterCups) || 0, waterCupsConsumed),
        mendoratoPeanuts: Math.max(Number(reservation.welcomeKitConsumption.mendoratoPeanuts) || 0, mendoratoPeanutsConsumed),
        waterCupsConsumed: Math.max(Number(reservation.welcomeKitConsumption.waterCups) || 0, waterCupsConsumed),
        peanutsConsumed: Math.max(Number(reservation.welcomeKitConsumption.mendoratoPeanuts) || 0, mendoratoPeanutsConsumed),
        inspectedAt: new Date().toISOString(),
        inspectorName: resolvedInspectorName
      };
    }

    // Cálculo do custo de reposição
    let restockedCourtesyTotalCost = 0;
    let restockedPaidItemsTotalCost = 0;
    const processedRestocked = [];

    if (Array.isArray(restockedItems)) {
      for (const item of restockedItems) {
        // R4: Reposição do kit de cortesia é feita pela camareira no turnover, nunca pela repositora
        const isKitCourtesy = item.productId === "prod_amendoim_mendorato" ||
          String(item.productId || "").includes("mendorato") ||
          (item.productId === "prod_agua_mineral_copo" && item.isCourtesy);
        if (isKitCourtesy) continue;

        const prod = (db.minibarProducts || []).find(p => p.id === item.productId);
        const qty = Number(item.quantity) || 0;
        if (qty <= 0) continue;
        const unitCost = Number(prod?.cost || item.unitCost) || 0;
        const totalCost = qty * unitCost;
        const isCourtesy = item.isCourtesy !== undefined ? Boolean(item.isCourtesy) : Boolean(prod?.isCourtesy);

        if (isCourtesy) {
          restockedCourtesyTotalCost += totalCost;
        } else {
          restockedPaidItemsTotalCost += totalCost;
        }

        processedRestocked.push({
          productId: item.productId,
          productName: prod?.name || item.productName || item.productId,
          quantity: qty,
          isCourtesy,
          unitCost,
          totalCost
        });
      }
    }

    // Lançamento de consumo pela repositora (diário ou pós-check-out)
    let hasDiscrepancy = false;
    let chargeOrderId = null;
    let discrepancyItems = [];
    let discrepancyTotalAmount = 0;
    let whatsappSofiaAlertSent = false;
    let notifiedPhones = [];
    let whatsappMessagesSent = [];

    const effectiveCountedList =
      Array.isArray(consumedItems) && consumedItems.length > 0
        ? consumedItems
        : Array.isArray(countedItems) && countedItems.length > 0
        ? countedItems
        : Array.isArray(missingItems)
        ? missingItems
        : [];

    const isLaunchMode =
      Boolean(isDailyLaunch) ||
      status === "lancamento_diario" ||
      status === "divergencia" ||
      effectiveCountedList.some(m => (Number(m.quantity ?? m.countedQuantity ?? m.undeclaredQuantity) || 0) > 0);

    if (isLaunchMode && effectiveCountedList.length > 0) {
      // Itens já pagos na reserva (usado apenas se o payload vier no formato antigo de contagem acumulada)
      const paidOrders = (db.minibarOrders || []).filter(o =>
        (o.reservationCode === finalResCode || String(o.reservationId) === String(reservation?.id)) &&
        o.paymentStatus === "pago"
      );

      const paidMap = {};
      for (const ord of paidOrders) {
        for (const it of ord.items || []) {
          paidMap[it.productId] = (paidMap[it.productId] || 0) + (Number(it.quantity) || 0);
        }
      }

      for (const m of effectiveCountedList) {
        const prod = (db.minibarProducts || []).find(p => p.id === m.productId);
        if (!prod || prod.isCourtesy) continue;

        const countedTotalQty = Number(m.countedQuantity ?? m.quantity) || 0;
        const alreadyPaidQty = paidMap[m.productId] || 0;
        const launchQty =
          isDailyLaunch || status === "lancamento_diario"
            ? Math.max(0, Number(m.quantity ?? m.countedQuantity) || 0)
            : m.undeclaredQuantity !== undefined
            ? Math.max(0, Number(m.undeclaredQuantity) || 0)
            : Math.max(0, countedTotalQty - alreadyPaidQty);

        if (launchQty > 0) {
          const unitPrice = Number(prod.price) || 0;
          const totalPrice = Number((launchQty * unitPrice).toFixed(2));
          discrepancyItems.push({
            productId: prod.id,
            productName: prod.name,
            declaredQuantity: alreadyPaidQty,
            countedQuantity: countedTotalQty,
            quantity: launchQty,
            paidQuantity: 0,
            remainingQuantity: launchQty,
            unitPrice,
            totalPrice,
            launchDate: launchDateStr,
            launchDateBr
          });
          discrepancyTotalAmount = Number((discrepancyTotalAmount + totalPrice).toFixed(2));
        }
      }

      if (discrepancyItems.length > 0 && discrepancyTotalAmount > 0) {
        hasDiscrepancy = true;
        chargeOrderId = `ORD-MB-DIV-${Date.now()}`;

        const pendingOrder = {
          id: chargeOrderId,
          flatNumber: flatStr,
          reservationId: reservation?.id || null,
          reservationCode: finalResCode,
          guestIndex: 1,
          guestRole: "titular",
          guestName: reservation?.guestName || "Hóspede CorpFlats",
          guestPhone: reservation?.guestPhone || "",
          guestDocument: reservation?.guestDocument || "",
          guestEmail: reservation?.guestEmail || "",
          launchDate: launchDateStr,
          launchDateBr,
          inspectorName: resolvedInspectorName,
          items: discrepancyItems,
          totalAmount: discrepancyTotalAmount,
          remainingAmount: discrepancyTotalAmount,
          paymentMethod: "pendente",
          paymentStatus: "pendente",
          source: isDailyLaunch || status === "lancamento_diario" ? "restocker_launch" : "anserve_discrepancy",
          fiscalPreferences: {
            invoiceDescriptionType: "detailed",
            documentType: "cpf",
            documentNumber: (reservation?.guestDocument || "").replace(/\D/g, ""),
            email: reservation?.guestEmail || "",
            phone: reservation?.guestPhone || "",
            payerName: reservation?.guestName || "Hóspede CorpFlats"
          },
          invoice: { status: "pendente" },
          notes: notes || `Consumo lançado pela repositora em ${launchDateBr}`,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        };

        if (!Array.isArray(db.minibarOrders)) db.minibarOrders = [];
        db.minibarOrders.push(pendingOrder);
      }
    }

    const isFinalCheckoutInspection = Boolean(req.body?.isFinalCheckoutInspection);
    const actuallyCheckedOutInPms = reservation
      ? isReservationOrFlatCheckedOut(db, reservation, reservation.flatId, flatStr) ||
        Boolean(
          reservation.checkoutDone ||
          reservation.actualCheckoutAt ||
          reservation.earlyCheckoutReleasedAt
        )
      : false;
    const resCheckedOut =
      actuallyCheckedOutInPms ||
      Boolean(reservation && (reservation.finalMinibarInspectionAt || isFinalCheckoutInspection));

    if (reservation && (isFinalCheckoutInspection || resCheckedOut || (!isDailyLaunch && status === "divergencia"))) {
      reservation.finalMinibarInspectionAt = new Date().toISOString();
      if (actuallyCheckedOutInPms) {
        reservation.checkoutDone = true;
      }
    }
    const updatedStatement = reservation ? buildReservationMinibarStatement(reservation, flatStr) : null;

    // Na vistoria final pós-check-out (ou divergência final), separa automaticamente os valores
    // e deixa cada cobrança e Nota Fiscal configurada para o respectivo hóspede consumidor
    let autoSplitOrders = [];
    if (
      reservation &&
      updatedStatement &&
      (resCheckedOut || isFinalCheckoutInspection || (!isDailyLaunch && status === "divergencia"))
    ) {
      autoSplitOrders = syncReservationAutoSplitOrders(reservation, flatStr, updatedStatement);
    }

    const totalPendingNow = Number(updatedStatement?.pendingBalance || 0);
    const totalPaidPreviously = Number(updatedStatement?.totalPaidAmount || 0);
    const totalStayAmount = Number(updatedStatement?.totalLaunchedAmount || totalPendingNow || discrepancyTotalAmount || 0);
    let postCheckoutNotificationType = "none_needed";

    const isInStayDailyLaunchOnly =
      Boolean(isDailyLaunch || status === "lancamento_diario") &&
      !isFinalCheckoutInspection &&
      !resCheckedOut;

    const shouldSendDailySummaryNow =
      Boolean(reservation) &&
      db.minibarSettings?.autoNotifySofiaOnDiscrepancy !== false &&
      bodyNotifySofia !== false &&
      isInStayDailyLaunchOnly &&
      discrepancyItems.length > 0 &&
      discrepancyTotalAmount > 0;

    const shouldNotifySofiaNow =
      Boolean(reservation) &&
      db.minibarSettings?.autoNotifySofiaOnDiscrepancy !== false &&
      !isInStayDailyLaunchOnly &&
      (bodyNotifySofia === true || resCheckedOut || isFinalCheckoutInspection || status === "divergencia") &&
      totalPendingNow > 0;

    if (shouldSendDailySummaryNow) {
      // Disparo do Resumo Diário de Consumo para TODOS os hóspedes cadastrados na reserva (Passagem "Sem Consumo" não envia nada)
      const allGuestsInFlat = getReservationAllGuests(reservation);
      const guestsToNotify =
        allGuestsInFlat.length > 0
          ? allGuestsInFlat
          : [
              {
                index: 1,
                name: reservation.guestName || "Hóspede",
                firstName: (reservation.guestName || "Hóspede").trim().split(" ")[0],
                phone: reservation.guestPhone || "",
                document: reservation.guestDocument || ""
              }
            ];

      const serverBaseUrl = (process.env.SERVER_BASE_URL || db.settings?.baseUrl || "https://corpflats.com.br").replace(/\/+$/, "");
      const todayItemsLines = discrepancyItems
        .map(it => `• ${it.quantity}x ${it.productName} — R$ ${Number(it.totalPrice).toFixed(2)}`)
        .join("\n");

      const sentCleanPhones = new Set();
      postCheckoutNotificationType = "daily_summary";

      for (const guestSlot of guestsToNotify) {
        const rawPhone = String(
          guestSlot.phone || (guestSlot.index === 1 ? reservation.guestPhone : "") || ""
        ).trim();
        const cleanPhone = cleanWhatsAppPhone(rawPhone);
        if (!rawPhone || cleanPhone.length < 8 || sentCleanPhones.has(cleanPhone)) {
          continue;
        }
        sentCleanPhones.add(cleanPhone);

        const firstName = guestSlot.firstName || (guestSlot.name || "Hóspede").trim().split(" ")[0];
        const portalUrl = `${serverBaseUrl}/minha-reserva/${finalResCode}/frigobar${
          guestSlot.index > 1 ? `?guestIndex=${guestSlot.index}` : ""
        }`;

        const dailyMsg =
          `🧊 *Resumo Atual de Consumo do Quarto — Flat ${flatStr}*\n\n` +
          `Olá, ${firstName}! Segue seu resumo atual de consumo do quarto:\n\n` +
          `📅 *Lançado hoje (${launchDateBr}):*\n` +
          `${todayItemsLines}\n\n` +
          `💰 *Total acumulado no quarto:* R$ ${totalStayAmount.toFixed(2)}\n\n` +
          `📱 *Acesse a sua área do frigobar através do link abaixo para ver o extrato completo e o cardápio:*\n` +
          `🔗 ${portalUrl}\n\n` +
          `_O pagamento será liberado somente no final da estadia, após a conferência pós-check-out._`;

        try {
          if (typeof sendZapiMessage === "function") {
            const zapiConfig = db.settings?.zapiConfig || db.zapiConfig || {};
            sendZapiMessage(zapiConfig, {
              phone: rawPhone,
              message: dailyMsg,
              channelId: "guest",
              triggerEvent: "minibar_daily_summary",
              db
            });
            whatsappSofiaAlertSent = true;
            notifiedPhones.push(rawPhone);
          }
          if (typeof appendMessageToConversation === "function") {
            appendMessageToConversation(db, {
              phone: rawPhone,
              text: dailyMsg,
              type: "text",
              sender: "Sofia (IA)"
            });
          }
          whatsappMessagesSent.push({
            guestIndex: guestSlot.index || 1,
            guestName: guestSlot.name,
            phone: rawPhone,
            amount: discrepancyTotalAmount,
            totalStayAmount,
            orderId: chargeOrderId || updatedStatement?.primaryPendingOrder?.id || "",
            paymentUrl: portalUrl,
            link: portalUrl,
            message: dailyMsg,
            type: "daily_summary"
          });
        } catch (dErr) {
          console.warn("[Minibar Daily Summary Alert] Erro ao disparar mensagem:", dErr.message);
        }
      }
    } else if (shouldNotifySofiaNow) {
      const allGuestsInFlat = getReservationAllGuests(reservation);
      const splitBreakdown = updatedStatement?.splitBreakdown || null;
      const splitMode = splitBreakdown?.mode || "titular";
      const linkedOrderId = autoSplitOrders[0]?.id || chargeOrderId || updatedStatement?.primaryPendingOrder?.id || "";
      const serverBaseUrl = (process.env.SERVER_BASE_URL || db.settings?.baseUrl || "https://corpflats.com.br").replace(/\/+$/, "");

      const hasPriorPayment = totalPaidPreviously > 0;
      postCheckoutNotificationType = hasPriorPayment ? "remaining_balance" : "full_total";

      if (splitMode === "half_and_half" || splitMode === "by_item") {
        const activeShares = (splitBreakdown?.shares || []).filter(s => Number(s.amount || 0) > 0);
        const modeTitle =
          splitMode === "half_and_half"
            ? "Divisão Meio a Meio (Partes Iguais)"
            : "Divisão por Item Consumido";

        for (const share of activeShares) {
          const splitOrd = autoSplitOrders.find(o => Number(o.guestIndex) === Number(share.guestIndex));
          const targetOrdId = splitOrd?.id || linkedOrderId;
          const targetPhone = String(share.phone || reservation.guestPhone || "").trim();
          if (!targetPhone) continue;

          const firstName = share.firstName || (share.guestName || "Hóspede").trim().split(" ")[0];
          const shareItemsStr = (share.items || [])
            .map(
              it =>
                `• ${it.quantity}x ${it.productName}${it.launchDateBr ? ` (${it.launchDateBr})` : ""} — R$ ${Number(
                  it.totalPrice
                ).toFixed(2)}`
            )
            .join("\n");

          const fallbackNote =
            splitMode === "by_item" &&
            share.guestIndex === 1 &&
            Array.isArray(share.unassignedFallbackItems) &&
            share.unassignedFallbackItems.length > 0
              ? `\n📌 *Nota:* Itens lançados na vistoria final sem marcação prévia foram atribuídos automaticamente ao Hóspede Principal (Titular).\n`
              : "";

          const paymentUrl = `${serverBaseUrl}/minha-reserva/${finalResCode}/frigobar?guestIndex=${share.guestIndex}${
            targetOrdId ? `&ord=${targetOrdId}` : ""
          }`;

          const sofiaMsg =
            `Olá, ${firstName}! Tudo bem? Esperamos que tenha tido uma excelente estadia no Flat ${flatStr} da CorpFlats! 🌟\n\n` +
            `Nossa equipe concluiu a conferência final do frigobar após o check-out. Conforme a *${modeTitle}* registrada na sua reserva, segue o resumo individual da sua parte:\n\n` +
            `${shareItemsStr}\n` +
            `${fallbackNote}\n` +
            `💰 *Valor da sua parte (${share.guestName}): R$ ${Number(share.amount).toFixed(2)}* (Total do flat: R$ ${totalPendingNow.toFixed(2)})\n` +
            `🧾 *Tomador da Nota Fiscal:* ${share.guestName}${share.document ? ` (Doc: ${share.document})` : ""}\n\n` +
            `O pagamento já está liberado! Para pagar via PIX ou Cartão e receber sua Nota Fiscal individual, acesse o link abaixo:\n` +
            `🔗 ${paymentUrl}\n\n` +
            `Caso tenha alguma dúvida, estamos à disposição! Tenha um excelente dia! ✨`;

          try {
            if (typeof sendZapiMessage === "function") {
              const zapiConfig = db.settings?.zapiConfig || db.zapiConfig || {};
              sendZapiMessage(zapiConfig, {
                phone: targetPhone,
                message: sofiaMsg,
                channelId: "guest",
                triggerEvent: "minibar_discrepancy",
                db
              });
              whatsappSofiaAlertSent = true;
              notifiedPhones.push(targetPhone);
            }
            if (typeof appendMessageToConversation === "function") {
              appendMessageToConversation(db, {
                phone: targetPhone,
                text: sofiaMsg,
                type: "text",
                sender: "Sofia (IA)"
              });
            }
            whatsappMessagesSent.push({
              guestIndex: share.guestIndex,
              guestName: share.guestName,
              phone: targetPhone,
              amount: share.amount,
              orderId: targetOrdId,
              paymentUrl,
              link: paymentUrl,
              message: sofiaMsg
            });
          } catch (sErr) {
            console.warn("[Minibar Sofia Alert Split] Erro ao disparar mensagem:", sErr.message);
          }
        }
      } else {
        // Modo Padrão (100% Titular): envia o resumo pós-check-out para todos os hóspedes cadastrados na reserva
        const guestsToNotify =
          allGuestsInFlat.length > 0
            ? allGuestsInFlat
            : [
                {
                  index: 1,
                  name: reservation.guestName || "Hóspede",
                  firstName: (reservation.guestName || "Hóspede").trim().split(" ")[0],
                  phone: reservation.guestPhone || "",
                  document: reservation.guestDocument || ""
                }
              ];
        const titularGuest = guestsToNotify[0];
        const ordQuery = linkedOrderId ? `?ord=${linkedOrderId}` : "";
        const paymentUrl = `${serverBaseUrl}/minha-reserva/${finalResCode}/frigobar${ordQuery}`;

        const dayBlocks = (updatedStatement?.dailyLaunches || [])
          .map(day => {
            const dayItems = (day.items || []).filter(
              it => !it.isCourtesy && (Number(it.remainingQuantity ?? it.quantity) || 0) > 0
            );
            if (dayItems.length === 0) return null;
            const lines = dayItems
              .map(it => {
                const q = Number(it.remainingQuantity ?? it.quantity) || 0;
                const p = Number(it.remainingTotalPrice ?? it.totalPrice) || 0;
                return `  • ${q}x ${it.productName} — R$ ${p.toFixed(2)}`;
              })
              .join("\n");
            return `📅 *Consumo em ${day.dateBr}:*\n${lines}`;
          })
          .filter(Boolean)
          .join("\n\n");

        const fullStayListStr =
          dayBlocks ||
          discrepancyItems
            .map(it => `• ${it.quantity}x ${it.productName} (${launchDateBr}) — R$ ${Number(it.totalPrice).toFixed(2)}`)
            .join("\n");

        const remainingItemsListStr =
          (updatedStatement?.pendingLaunchedItems || []).length > 0
            ? updatedStatement.pendingLaunchedItems
                .map(
                  it =>
                    `• ${it.remainingQuantity}x ${it.productName} (${it.launchDateBr}) — R$ ${Number(
                      it.remainingTotalPrice
                    ).toFixed(2)}`
                )
                .join("\n")
            : fullStayListStr;

        const sentCleanPhones = new Set();
        for (const guestSlot of guestsToNotify) {
          const targetPhone = String(
            guestSlot.phone || (guestSlot.index === 1 ? reservation.guestPhone : "") || ""
          ).trim();
          const cleanPhone = cleanWhatsAppPhone(targetPhone);
          if (!targetPhone || cleanPhone.length < 8 || sentCleanPhones.has(cleanPhone)) {
            continue;
          }
          sentCleanPhones.add(cleanPhone);

          const firstName = guestSlot.firstName || (guestSlot.name || "Hóspede").trim().split(" ")[0];
          const sofiaMsg = hasPriorPayment
            ? `Olá, ${firstName}! Tudo bem? Esperamos que tenha tido uma excelente estadia no Flat ${flatStr} da CorpFlats! 🌟\n\n` +
              `Nossa equipe concluiu a conferência final do frigobar após o seu check-out.\n` +
              `✅ Já identificamos o pagamento anterior de *R$ ${totalPaidPreviously.toFixed(2)}*, porém restou o seguinte saldo referente ao consumo do último dia / conferência final:\n\n` +
              `${remainingItemsListStr}\n\n` +
              `💰 *Valor restante para pagamento: R$ ${totalPendingNow.toFixed(2)}*\n` +
              `🧾 *Tomador da Nota Fiscal:* ${titularGuest.name}\n\n` +
              `Para quitar o valor restante via PIX ou Cartão (com emissão da respectiva Nota Fiscal), acesse o link abaixo:\n` +
              `🔗 ${paymentUrl}\n\n` +
              `Caso tenha alguma dúvida, estamos à disposição! Tenha um excelente dia! ✨`
            : `Olá, ${firstName}! Tudo bem? Esperamos que tenha tido uma excelente estadia no Flat ${flatStr} da CorpFlats! 🌟\n\n` +
              `Nossa equipe concluiu a conferência final do consumo de frigobar do seu apartamento:\n\n` +
              `${fullStayListStr}\n\n` +
              `💰 *Total do consumo na estadia: R$ ${totalPendingNow.toFixed(2)}*\n` +
              `🧾 *Tomador da Nota Fiscal:* ${titularGuest.name}\n\n` +
              `O pagamento já está liberado! Para efetuar o pagamento via PIX ou Cartão e receber sua Nota Fiscal, acesse a sua área do frigobar pelo link abaixo:\n` +
              `🔗 ${paymentUrl}\n\n` +
              `Caso tenha alguma dúvida, estamos à disposição! Tenha um excelente dia! ✨`;

          try {
            if (typeof sendZapiMessage === "function") {
              const zapiConfig = db.settings?.zapiConfig || db.zapiConfig || {};
              sendZapiMessage(zapiConfig, {
                phone: targetPhone,
                message: sofiaMsg,
                channelId: "guest",
                triggerEvent: "minibar_discrepancy",
                db
              });
              whatsappSofiaAlertSent = true;
              notifiedPhones.push(targetPhone);
            }
            if (typeof appendMessageToConversation === "function") {
              appendMessageToConversation(db, {
                phone: targetPhone,
                text: sofiaMsg,
                type: "text",
                sender: "Sofia (IA)"
              });
            }
            whatsappMessagesSent.push({
              guestIndex: guestSlot.index || 1,
              guestName: guestSlot.name,
              phone: targetPhone,
              amount: totalPendingNow,
              orderId: linkedOrderId,
              paymentUrl,
              link: paymentUrl,
              message: sofiaMsg
            });
          } catch (sErr) {
            console.warn("[Minibar Sofia Alert] Erro ao disparar mensagem:", sErr.message);
          }
        }
      }
    }

    const inspection = {
      id: `INSP-MB-${Date.now()}`,
      flatNumber: flatStr,
      reservationId: reservation?.id || null,
      reservationCode: finalResCode,
      guestName: reservation?.guestName || null,
      guestPhone: reservation?.guestPhone || null,
      inspectorId: resolvedInspectorUser?.id || bodyInspectorId || null,
      inspectorUsername: resolvedInspectorUser?.username || null,
      inspectorName: resolvedInspectorName,
      inspectedAt: new Date().toISOString(),
      launchDate: launchDateStr,
      launchDateBr,
      isFinalCheckoutInspection: Boolean(resCheckedOut),
      postCheckoutNotificationType,
      pendingBalanceAtInspection: totalPendingNow,
      totalPaidAtInspection: totalPaidPreviously,
      status: hasDiscrepancy ? "divergencia" : "conforme",
      hasDiscrepancy,
      discrepancyPaid: false,
      discrepancyResolved: !hasDiscrepancy,
      missingItems: effectiveCountedList,
      discrepancyItems,
      discrepancyTotalAmount,
      restockedItems: processedRestocked,
      restockedCourtesyTotalCost,
      restockedPaidItemsTotalCost,
      photos: Array.isArray(photos) ? photos : [],
      notes: notes || "",
      welcomeKitConsumption: welcomeKitRecord,
      chargeOrderId: chargeOrderId || updatedStatement?.primaryPendingOrder?.id || null,
      autoSplitOrderIds: autoSplitOrders.map(o => o.id),
      whatsappSofiaAlertSent,
      notifiedPhones,
      whatsappMessagesSent,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    if (!Array.isArray(db.minibarInspections)) db.minibarInspections = [];
    db.minibarInspections.push(inspection);
    saveDatabase("minibar_inspection_recorded");

    res.json({
      success: true,
      inspectionId: inspection.id,
      launchDate: launchDateStr,
      launchDateBr,
      hasDiscrepancy,
      chargeOrderId: inspection.chargeOrderId,
      autoSplitOrders,
      splitBreakdown: updatedStatement?.splitBreakdown || null,
      whatsappSofiaAlertSent,
      postCheckoutNotificationType,
      notifiedPhones,
      whatsappMessagesSent,
      statement: updatedStatement,
      inspection
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get("/api/minibar/inspections/flats-status", (req, res) => {
  try {
    const todayStr = getBrasiliaNow().date;
    const flats = typeof getCanonicalFlats === "function" ? getCanonicalFlats(db) : DEFAULT_FLATS;
    const checkoutSummary = buildTodayCheckoutsSummaryForRestockers(db, todayStr);

    const list = flats.map(f => {
      const flatNum = String(f.number || f.flatNumber || f.id);
      const resActive = findActiveOrRecentReservationForFlat(flatNum, {
        onlyActiveToday: true,
        forRestockerStatus: true
      });
      const statement = resActive ? buildReservationMinibarStatement(resActive, flatNum) : null;

      let status = "livre";
      if (resActive) {
        if (isReservationCheckoutToday(resActive, todayStr)) {
          status = "checkout_hoje";
        } else {
          status = "ocupado";
        }
      }

      const doneSummaryEntry = Array.isArray(checkoutSummary?.doneCheckouts)
        ? checkoutSummary.doneCheckouts.find(c => String(c.flatNumber) === flatNum)
        : null;
      const isCheckedOutToday =
        status === "checkout_hoje" &&
        Boolean(
          doneSummaryEntry ||
            (resActive && isReservationOrFlatCheckedOut(db, resActive, resActive.flatId, flatNum)) ||
            statement?.isCheckedOut
        );
      const resolvedCheckoutTime = isCheckedOutToday
        ? statement?.checkoutTime || doneSummaryEntry?.checkoutTime || null
        : null;

      // Todos os pedidos da reserva atual (pagos e pendentes)
      const allResOrders = resActive
        ? (db.minibarOrders || []).filter(
            o =>
              (o.reservationCode === resActive.code || String(o.reservationId) === String(resActive.id)) &&
              o.paymentStatus !== "cancelado"
          )
        : [];

      const paidOrders = allResOrders.filter(o => o.paymentStatus === "pago");
      const declaredAmount = paidOrders.reduce((sum, o) => sum + (Number(o.totalAmount) || 0), 0);

      // Quantidade já lançada/paga por produto na reserva atual
      const declaredItemsByProduct = {};
      if (statement && Array.isArray(statement.dailyLaunches)) {
        for (const day of statement.dailyLaunches) {
          for (const it of day.items || []) {
            if (!it.productId) continue;
            declaredItemsByProduct[it.productId] = (declaredItemsByProduct[it.productId] || 0) + (Number(it.quantity) || 0);
          }
        }
      } else {
        for (const ord of paidOrders) {
          for (const it of ord.items || []) {
            if (!it.productId) continue;
            declaredItemsByProduct[it.productId] = (declaredItemsByProduct[it.productId] || 0) + (Number(it.quantity) || 0);
          }
        }
      }

      const declaredOrdersSummary = paidOrders.map(o => ({
        id: o.id,
        guestName: o.guestName || resActive?.guestName || "Hóspede",
        guestIndex: o.guestIndex || 1,
        totalAmount: Number(o.totalAmount || 0),
        paidAt: o.paidAt || o.createdAt,
        isDiscrepancySettlement:
          o.source === "anserve_discrepancy" ||
          o.source === "restocker_launch" ||
          Boolean(o.settlesLaunchOrders) ||
          String(o.id || "").startsWith("ORD-MB-DIV-"),
        items: (o.items || []).map(it => ({
          productId: it.productId,
          productName: it.productName || it.name,
          quantity: Number(it.quantity) || 0
        }))
      }));

      const pendingDiscrepancyOrder = statement?.primaryPendingOrder || null;

      // Última inspeção
      const lastInsp = (db.minibarInspections || [])
        .filter(i => String(i.flatNumber) === flatNum)
        .sort((a, b) => String(b.inspectedAt || "").localeCompare(String(a.inspectedAt || "")))[0] || null;

      // Gabarito padrão
      const defaultTemplate = db.minibarDefaultStock?.flatOverrides?.[flatNum] || db.minibarDefaultStock?.globalTemplate || [];
      const reservationGuests = resActive ? getReservationAllGuests(resActive) : [];

      return {
        flatNumber: flatNum,
        colName: f.colName || `Flat ${flatNum}`,
        status,
        isCheckedOut: isCheckedOutToday,
        checkoutTime: resolvedCheckoutTime,
        dailyLaunches: statement ? statement.dailyLaunches : [],
        pendingBalance: statement ? statement.pendingBalance : 0,
        totalLaunchedAmount: statement ? statement.totalLaunchedAmount : 0,
        totalPaidAmount: statement ? statement.totalPaidAmount : declaredAmount,
        splitConfig: statement ? statement.splitConfig : null,
        splitBreakdown: statement ? statement.splitBreakdown : null,
        currentReservation: resActive ? {
          code: resActive.code,
          guestName: resActive.guestName,
          checkIn: resActive.checkinDate,
          checkOut: resActive.checkoutDate,
          phone: resActive.guestPhone,
          isCheckedOut: isCheckedOutToday,
          checkoutTime: resolvedCheckoutTime,
          numGuests: Math.max(Number(resActive.numGuests || 1), reservationGuests.length),
          guests: reservationGuests.map(g => ({
            index: g.index,
            name: g.name,
            firstName: g.firstName,
            role: g.role,
            hasPhone: Boolean(g.phone)
          }))
        } : null,
        declaredAmount,
        declaredItemsByProduct,
        declaredOrdersSummary,
        pendingDiscrepancyOrder: pendingDiscrepancyOrder
          ? {
              id: pendingDiscrepancyOrder.id,
              totalAmount: Number(pendingDiscrepancyOrder.remainingAmount ?? pendingDiscrepancyOrder.totalAmount ?? 0),
              items: pendingDiscrepancyOrder.items,
              createdAt: pendingDiscrepancyOrder.createdAt
            }
          : null,
        lastInspection: lastInsp,
        defaultStock: defaultTemplate
      };
    });

    res.json({
      success: true,
      checkoutSummary,
      flats: list
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

function enrichMinibarOrderForInvoiceScreen(order) {
  if (!order) return null;
  const reservation =
    (db.reservations || []).find(
      r =>
        (order.reservationCode && r.code === order.reservationCode) ||
        (order.reservationId && String(r.id) === String(order.reservationId))
    ) || (order.flatNumber ? findActiveOrRecentReservationForFlat(order.flatNumber) : null);

  const flatStr = String(order.flatNumber || reservation?.flatNumber || reservation?.flatId || "").trim();
  const resCode = order.reservationCode || reservation?.code || "";
  const statement = reservation ? buildReservationMinibarStatement(reservation, flatStr) : null;

  const allPaidForReservation = (db.minibarOrders || [])
    .filter(
      o =>
        o &&
        o.paymentStatus === "pago" &&
        Number(o.totalAmount) > 0 &&
        ((resCode && o.reservationCode === resCode) ||
          (reservation?.id && String(o.reservationId) === String(reservation.id)) ||
          (!resCode && !reservation?.id && String(o.flatNumber) === flatStr))
    )
    .sort((a, b) => String(a.paidAt || a.createdAt || "").localeCompare(String(b.paidAt || b.createdAt || "")));

  const orderSequenceIndex = Math.max(1, allPaidForReservation.findIndex(o => o.id === order.id) + 1);
  const totalPaidOrdersInReservation = Math.max(1, allPaidForReservation.length);
  const partialMode = order.partialMode || "full";
  const isSeparatePayment =
    totalPaidOrdersInReservation > 1 ||
    partialMode === "items" ||
    partialMode === "equal_split" ||
    partialMode === "custom_amount" ||
    partialMode === "configured_split" ||
    Boolean(order.isAutoSplitCheckoutOrder) ||
    Number(order.guestIndex || 1) > 1;

  let partialModeLabel = "Pagamento Único Integral";
  if (partialMode === "equal_split") {
    partialModeLabel = "Divisão em Partes Iguais";
  } else if (partialMode === "custom_amount") {
    partialModeLabel = "Valor Parcial Livre em R$";
  } else if (partialMode === "items") {
    partialModeLabel = "Seleção Individual de Itens";
  } else if (partialMode === "configured_split") {
    partialModeLabel = "Divisão Configurada na Reserva";
  } else if (totalPaidOrdersInReservation > 1) {
    partialModeLabel = `Pagamento Separado (${orderSequenceIndex}ª de ${totalPaidOrdersInReservation} NFs do Flat)`;
  }

  const siblingOrdersSummary = allPaidForReservation.map((so, idx) => ({
    id: so.id,
    sequence: idx + 1,
    guestName: so.guestName || reservation?.guestName || "Hóspede",
    guestIndex: so.guestIndex || 1,
    guestRole: so.guestRole || (Number(so.guestIndex || 1) > 1 ? "acompanhante" : "titular"),
    guestDocument: so.fiscalPreferences?.documentNumber || so.guestDocument || "",
    totalAmount: Number(so.totalAmount || 0),
    paidAt: so.paidAt || so.createdAt,
    partialMode: so.partialMode || "full",
    invoiceStatus: so.invoice?.status || "pendente",
    invoiceNumber: so.invoice?.invoiceNumber || null,
    invoiceFileUrl: so.invoice?.invoiceFileUrl || null
  }));

  // Datas de lançamento do consumo (DD/MM/AAAA)
  const consumptionDatesSet = new Set();
  if (order.launchDateBr) consumptionDatesSet.add(order.launchDateBr);
  else if (order.launchDate) consumptionDatesSet.add(formatMinibarDateBr(order.launchDate));

  for (const it of order.items || []) {
    if (it.launchDateBr) consumptionDatesSet.add(it.launchDateBr);
    else if (it.launchDate) consumptionDatesSet.add(formatMinibarDateBr(it.launchDate));
  }
  for (const sel of order.selectedLaunchItems || []) {
    if (sel.launchDateBr) consumptionDatesSet.add(sel.launchDateBr);
    else if (sel.launchDate) consumptionDatesSet.add(formatMinibarDateBr(sel.launchDate));
  }
  if (consumptionDatesSet.size === 0 && statement?.dailyLaunches?.length > 0) {
    for (const dl of statement.dailyLaunches) {
      if (dl.dateBr) consumptionDatesSet.add(dl.dateBr);
    }
  }
  if (consumptionDatesSet.size === 0) {
    const fallbackDate = formatMinibarDateBr(order.paidAt || order.createdAt || getBrasiliaNow().date);
    if (fallbackDate) consumptionDatesSet.add(fallbackDate);
  }
  const consumptionDatesBr = Array.from(consumptionDatesSet);

  // Dados fiscais prontos para emissão / colagem
  const prefType = order.fiscalPreferences?.invoiceDescriptionType || "detailed";
  let prefLabel = "1. Discriminar todos os itens consumidos";
  if (prefType === "water") prefLabel = "2. Lançar tudo como 'Água'";
  else if (prefType === "minibar_consumption") prefLabel = "3. Lançar tudo como 'Consumo de Frigobar'";

  const amountBr = Number(order.totalAmount || 0).toFixed(2).replace(".", ",");
  const paidItemsDesc = (order.items || [])
    .filter(i => !i.isCourtesy && (Number(i.quantity) || 0) > 0)
    .map(i => `${i.quantity}x ${i.productName || i.name} (R$ ${Number(i.totalPrice || 0).toFixed(2).replace(".", ",")})`)
    .join(", ");

  let readyToPasteDescription = "";
  if (prefType === "water") {
    readyToPasteDescription = `Consumo de Água Mineral - Flat ${flatStr} (${resCode || "Hospedagem"}) - Valor Total: R$ ${amountBr}`;
  } else if (prefType === "minibar_consumption") {
    readyToPasteDescription = `Consumo de Frigobar - Flat ${flatStr} (${resCode || "Hospedagem"}) - Valor Total: R$ ${amountBr}`;
  } else {
    readyToPasteDescription = `Consumo de Frigobar Flat ${flatStr} (${resCode || "Hospedagem"}) — Datas: ${consumptionDatesBr.join(", ")} — Itens: ${paidItemsDesc || "Consumo de Frigobar"} — Valor Total: R$ ${amountBr}`;
  }

  const docRaw = String(
    order.fiscalPreferences?.documentNumber || order.guestDocument || reservation?.guestDocument || ""
  ).replace(/\D/g, "");
  const docType = docRaw.length > 11 || order.fiscalPreferences?.documentType === "cnpj" ? "CNPJ" : "CPF";

  const payerName =
    order.fiscalPreferences?.payerName || order.guestName || reservation?.guestName || "Hóspede CorpFlats";
  const payerEmail = order.fiscalPreferences?.email || order.guestEmail || reservation?.guestEmail || "";
  const payerPhone = order.fiscalPreferences?.phone || order.guestPhone || reservation?.guestPhone || "";

  return {
    ...order,
    invoice: sanitizeMinibarInvoiceForResponse(order.invoice),
    flatNumber: flatStr,
    reservationCode: resCode,
    documentNumber: docRaw,
    email: payerEmail,
    phone: payerPhone,
    consumptionDatesBr,
    dailyLaunches: statement?.dailyLaunches || [],
    reservationTotalLaunchedAmount: statement?.totalLaunchedAmount ?? Number(order.totalAmount || 0),
    reservationTotalPaidAmount: statement?.totalPaidAmount ?? Number(order.totalAmount || 0),
    reservationPendingBalance: statement?.pendingBalance ?? 0,
    isCheckedOut: statement?.isCheckedOut ?? false,
    checkoutTime: statement?.checkoutTime ?? null,
    checkInDateBr: reservation?.checkinDate ? formatMinibarDateBr(reservation.checkinDate) : "",
    checkOutDateBr: reservation?.checkoutDate ? formatMinibarDateBr(reservation.checkoutDate) : "",
    numGuestsInFlat: reservation ? Math.max(Number(reservation.numGuests || 1), getReservationAllGuests(reservation).length) : 1,
    splitPaymentInfo: {
      isSeparatePayment,
      partialMode,
      partialModeLabel,
      orderSequenceIndex,
      totalPaidOrdersInReservation,
      guestIndex: Number(order.guestIndex || 1),
      guestRole: order.guestRole || (Number(order.guestIndex || 1) > 1 ? "acompanhante" : "titular"),
      configuredSplitMode: statement?.splitBreakdown?.mode || "titular",
      configuredSplitShares: statement?.splitBreakdown?.shares || [],
      siblingOrders: siblingOrdersSummary
    },
    fiscalSummary: {
      payerName,
      documentType: docType,
      documentNumber: docRaw,
      email: payerEmail,
      phone: payerPhone,
      invoiceDescriptionType: prefType,
      invoiceDescriptionLabel: prefLabel,
      readyToPasteDescription
    }
  };
}

app.get("/api/minibar/invoices/pending", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarInvoiceIssuer(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito ao faturamento, supervisão e administração." });
    }

    const pending = (db.minibarOrders || [])
      .filter(
        o =>
          o &&
          o.paymentStatus === "pago" &&
          Number(o.totalAmount) > 0 &&
          (!o.invoice || o.invoice.status !== "anexada")
      )
      .map(enrichMinibarOrderForInvoiceScreen)
      .sort((a, b) => String(b.paidAt || b.createdAt || "").localeCompare(String(a.paidAt || a.createdAt || "")));

    const resWithAutoSplit = new Set(
      (db.minibarOrders || [])
        .filter(o => o && o.paymentStatus === "pendente" && Boolean(o.isAutoSplitCheckoutOrder) && o.reservationCode)
        .map(o => o.reservationCode)
    );
    const preConfiguredCheckoutSplits = (db.minibarOrders || [])
      .filter(
        o =>
          o &&
          o.paymentStatus === "pendente" &&
          Number(o.totalAmount) > 0 &&
          (Boolean(o.isAutoSplitCheckoutOrder) ||
            (o.source === "anserve_discrepancy" && (!o.reservationCode || !resWithAutoSplit.has(o.reservationCode))))
      )
      .map(enrichMinibarOrderForInvoiceScreen);

    res.json({
      success: true,
      count: pending.length,
      pendingInvoices: pending,
      preConfiguredCheckoutSplits
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get("/api/minibar/invoices/hub", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarInvoiceIssuer(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito ao faturamento, supervisão e administração." });
    }

    const allPaidOrders = (db.minibarOrders || [])
      .filter(o => o && o.paymentStatus === "pago" && Number(o.totalAmount) > 0)
      .map(enrichMinibarOrderForInvoiceScreen)
      .sort((a, b) => String(b.paidAt || b.createdAt || "").localeCompare(String(a.paidAt || a.createdAt || "")));

    const pendingInvoices = allPaidOrders.filter(o => !o.invoice || o.invoice.status !== "anexada");
    const issuedInvoices = allPaidOrders.filter(o => o.invoice && o.invoice.status === "anexada");
    const separatePaymentsPendingCount = pendingInvoices.filter(o => o.splitPaymentInfo?.isSeparatePayment).length;
    const resWithAutoSplit = new Set(
      (db.minibarOrders || [])
        .filter(o => o && o.paymentStatus === "pendente" && Boolean(o.isAutoSplitCheckoutOrder) && o.reservationCode)
        .map(o => o.reservationCode)
    );
    const preConfiguredCheckoutSplits = (db.minibarOrders || [])
      .filter(
        o =>
          o &&
          o.paymentStatus === "pendente" &&
          Number(o.totalAmount) > 0 &&
          (Boolean(o.isAutoSplitCheckoutOrder) ||
            (o.source === "anserve_discrepancy" && (!o.reservationCode || !resWithAutoSplit.has(o.reservationCode))))
      )
      .map(enrichMinibarOrderForInvoiceScreen);

    const failedDeliveries = issuedInvoices.filter(o => {
      const m = o.invoice?.deliveryMonitor;
      if (!m) return false;
      return (
        m.overallStatus === "falha" ||
        m.overallStatus === "parcial" ||
        m.overallStatus === "retentando" ||
        m.whatsapp?.status === "falha" ||
        m.email?.status === "falha"
      );
    });

    res.json({
      success: true,
      stats: {
        pendingCount: pendingInvoices.length,
        pendingTotalAmount: Number(
          pendingInvoices.reduce((s, o) => s + Number(o.totalAmount || 0), 0).toFixed(2)
        ),
        separatePaymentsPendingCount,
        preConfiguredSplitsCount: preConfiguredCheckoutSplits.length,
        issuedCount: issuedInvoices.length,
        issuedTotalAmount: Number(
          issuedInvoices.reduce((s, o) => s + Number(o.totalAmount || 0), 0).toFixed(2)
        ),
        failedDeliveriesCount: failedDeliveries.length
      },
      invoices: [...pendingInvoices, ...preConfiguredCheckoutSplits, ...issuedInvoices],
      pendingInvoices,
      issuedInvoices,
      preConfiguredCheckoutSplits,
      failedDeliveries
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// ── F10: Extrato de Fechamento & Repasse Financeiro CorpFlats ↔ Anserve ───────
app.get("/api/minibar/settlement", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarAdmin(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito à supervisão e administração." });
    }

    const { startDate, endDate } = req.query;

    const filteredOrders = (db.minibarOrders || []).filter(o => {
      if (o.paymentStatus !== "pago") return false;
      const d = String(o.paidAt || o.createdAt || "").split("T")[0];
      if (startDate && d < startDate) return false;
      if (endDate && d > endDate) return false;
      return true;
    });

    const filteredInspections = (db.minibarInspections || []).filter(i => {
      const d = String(i.inspectedAt || i.createdAt || "").split("T")[0];
      if (startDate && d < startDate) return false;
      if (endDate && d > endDate) return false;
      return true;
    });

    let totalOrdersAmount = 0;
    let cardOrdersAmount = 0;
    let pixOrdersAmount = 0;

    for (const o of filteredOrders) {
      const amt = Number(o.totalAmount) || 0;
      totalOrdersAmount += amt;
      if (o.paymentMethod === "credit_card" || o.paymentMethod === "cartao_credito") {
        cardOrdersAmount += amt;
      } else if (o.paymentMethod === "pix") {
        pixOrdersAmount += amt;
      }
    }

    const cardFeePercent = Number(db.minibarSettings?.creditCardFeePercent ?? 3.99);
    const cardFees = (cardOrdersAmount * cardFeePercent) / 100;
    const pixFeePercent = db.minibarSettings?.pixFeePercent !== undefined
      ? Number(db.minibarSettings.pixFeePercent)
      : ((Number(db.minibarSettings?.pixFeeFixed) || 0) > 0 ? 0 : 0.99);
    const pixFeeFixed = Number(db.minibarSettings?.pixFeeFixed || 0);
    const pixFees = ((pixOrdersAmount * pixFeePercent) / 100) + (filteredOrders.filter(o => o.paymentMethod === "pix").length * pixFeeFixed);

    const commPercent = Number(db.minibarSettings?.corpFlatsCommissionPercent) || 0;
    const commissionCorpFlats = (totalOrdersAmount * commPercent) / 100;

    // Compensação de reposição de cortesias gratuitas (reembolsadas pela CorpFlats)
    let courtesyRestockCost = 0;
    let totalCourtesyWaterCups = 0;
    let totalCourtesyMendoratoPeanuts = 0;
    const courtesyWaterUnitCost = Number((db.minibarProducts || []).find(p => p.id === "prod_agua_mineral_copo")?.cost ?? 2.00);

    for (const insp of filteredInspections) {
      courtesyRestockCost += Number(insp.restockedCourtesyTotalCost) || 0;
      if (insp.welcomeKitConsumption) {
        totalCourtesyWaterCups += Number(insp.welcomeKitConsumption.waterCups ?? insp.welcomeKitConsumption.waterCupsConsumed) || 0;
        totalCourtesyMendoratoPeanuts += Number(insp.welcomeKitConsumption.mendoratoPeanuts ?? insp.welcomeKitConsumption.peanutsConsumed) || 0;
      }
    }

    // R6: Copos d'Água são fornecidos pela Anserve (reembolso ao custo contratual de R$ 2,00/un)
    // Amendoim Mendorato é de fornecimento próprio CorpFlats/Hotel (repasse R$ 0,00 à Anserve)
    const courtesyWaterTotalCost = Number((totalCourtesyWaterCups * courtesyWaterUnitCost).toFixed(2));
    const totalCourtesyReimbursement = Number((courtesyRestockCost + courtesyWaterTotalCost).toFixed(2));

    const courtesyReimbursementEnabled = db.minibarSettings?.courtesyReimbursementEnabled !== false;
    const netCourtesyCredit = courtesyReimbursementEnabled ? totalCourtesyReimbursement : 0;

    // Líquido a Repassar para a Anserve
    const netPayableToAnserve = totalOrdersAmount - cardFees - pixFees - commissionCorpFlats + netCourtesyCredit;

    res.json({
      success: true,
      period: { startDate: startDate || null, endDate: endDate || null },
      totalOrdersAmount: Number(totalOrdersAmount.toFixed(2)),
      ordersCount: filteredOrders.length,
      cardOrdersAmount: Number(cardOrdersAmount.toFixed(2)),
      pixOrdersAmount: Number(pixOrdersAmount.toFixed(2)),
      cardFees: Number(cardFees.toFixed(2)),
      pixFees: Number(pixFees.toFixed(2)),
      totalFees: Number((cardFees + pixFees).toFixed(2)),
      commissionCorpFlats: Number(commissionCorpFlats.toFixed(2)),
      courtesyRestockCost: Number(courtesyRestockCost.toFixed(2)),
      courtesyWaterCupsTotal: totalCourtesyWaterCups,
      courtesyWaterUnitCost,
      courtesyWaterTotalCost,
      courtesyMendoratoPeanutsTotal: totalCourtesyMendoratoPeanuts,
      courtesyMendoratoTotalCost: 0.00,
      totalCourtesyReimbursement,
      courtesySummary: {
        totalCourtesyWaterCups,
        courtesyWaterUnitCost,
        courtesyWaterTotalCost,
        totalCourtesyMendoratoPeanuts,
        courtesyMendoratoUnitCost: 0.00,
        courtesyMendoratoTotalCost: 0.00,
        waterSupplier: "anserve",
        mendoratoSupplier: "hotel_proprio",
        legacyCourtesyRestockCost: Number(courtesyRestockCost.toFixed(2)),
        totalCourtesyReimbursement
      },
      netPayableToAnserve: Number(netPayableToAnserve.toFixed(2)),
      inspectionsCount: filteredInspections.length,
      breakdowns: {
        orders: filteredOrders.map(sanitizeMinibarOrderForResponse),
        inspections: filteredInspections
      }
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// Analytics & Insights de Consumo
app.get("/api/minibar/analytics", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarAdmin(user)) {
      return res.status(403).json({ success: false, error: "Acesso restrito à administração." });
    }

    const orders = (db.minibarOrders || []).filter(o => o.paymentStatus === "pago");
    const productStats = {};
    let totalRevenue = 0;

    for (const o of orders) {
      totalRevenue += Number(o.totalAmount) || 0;
      for (const it of o.items || []) {
        if (!productStats[it.productId]) {
          productStats[it.productId] = {
            productId: it.productId,
            name: it.productName || it.productId,
            quantity: 0,
            revenue: 0,
            isCourtesy: Boolean(it.isCourtesy)
          };
        }
        productStats[it.productId].quantity += Number(it.quantity) || 0;
        productStats[it.productId].revenue += Number(it.totalPrice) || 0;
      }
    }

    const ranking = Object.values(productStats).sort((a, b) => b.quantity - a.quantity);

    // Auditoria de divergências
    const inspections = db.minibarInspections || [];
    const totalInspections = inspections.length;
    const discrepancyCount = inspections.filter(i => i.hasDiscrepancy || i.status === "divergencia").length;
    const discrepancyRate = totalInspections > 0 ? (discrepancyCount / totalInspections) * 100 : 0;

    // Cruzamento Demográfico por Origem do Hóspede (UF / Cidade)
    const demographicMap = {};
    for (const o of orders) {
      const resMatch = (db.reservations || []).find(r => r.code === o.reservationCode || String(r.id) === String(o.reservationId));
      const guestMatch = (db.guests || []).find(g =>
        (resMatch?.guestId && g.id === resMatch.guestId) ||
        (o.guestDocument && g.document && g.document.replace(/\D/g, "") === o.guestDocument.replace(/\D/g, ""))
      );
      const state = guestMatch?.state || guestMatch?.uf || resMatch?.guestState || "Outros";

      if (!demographicMap[state]) {
        demographicMap[state] = { state, ordersCount: 0, totalAmount: 0, products: {} };
      }
      demographicMap[state].ordersCount++;
      demographicMap[state].totalAmount += Number(o.totalAmount) || 0;

      for (const it of o.items || []) {
        demographicMap[state].products[it.productId] = (demographicMap[state].products[it.productId] || 0) + (Number(it.quantity) || 0);
      }
    }

    res.json({
      success: true,
      totalRevenue: Number(totalRevenue.toFixed(2)),
      ordersCount: orders.length,
      ranking,
      inspections: {
        total: totalInspections,
        withDiscrepancy: discrepancyCount,
        discrepancyRate: Number(discrepancyRate.toFixed(1))
      },
      demographicInsights: Object.values(demographicMap)
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

// Analytics Demográfico & Consumo Cruzado com FNHR / Origem do Hóspede (F30)
app.get("/api/minibar/analytics/demographics", (req, res) => {
  try {
    const user = getAuthUser(req);
    if (process.env.NODE_ENV !== "test" && !isMinibarAdmin(user) && user?.role !== "recepcao" && user?.role !== "reception") {
      return res.status(403).json({ success: false, error: "Acesso restrito à administração e recepção." });
    }

    const orders = (db.minibarOrders || []).filter(o => o && o.paymentStatus === "pago");
    const productsCatalog = db.minibarProducts || [];
    const reservations = db.reservations || [];
    const guests = db.guests || [];

    // Mapeamento auxiliar de categoria padrão
    const getProductCategory = (productId, productName) => {
      const prod = productsCatalog.find(p => p.id === productId);
      if (prod?.category) {
        const cat = prod.category.toLowerCase();
        if (cat.includes("cerveja")) return "Cervejas";
        if (cat.includes("refrigerante")) return "Refrigerantes";
        if (cat.includes("água") || cat.includes("agua")) return "Águas";
        if (cat.includes("snack") || cat.includes("doce")) return "Snacks";
        if (cat.includes("café") || cat.includes("cafe") || cat.includes("quente")) return "Cafés / Especiais";
      }
      const pName = (productName || productId || "").toLowerCase();
      if (pName.includes("cerveja") || pName.includes("heineken") || pName.includes("stella") || pName.includes("corona") || pName.includes("beer")) {
        return "Cervejas";
      }
      if (pName.includes("coca") || pName.includes("refrigerante") || pName.includes("guaraná") || pName.includes("guarana") || pName.includes("soda") || pName.includes("tonica") || pName.includes("tônica") || pName.includes("fanta")) {
        return "Refrigerantes";
      }
      if (pName.includes("água") || pName.includes("agua") || pName.includes("suco") || pName.includes("gatorade")) {
        return "Águas";
      }
      if (pName.includes("amendoim") || pName.includes("snack") || pName.includes("chocolate") || pName.includes("castanha") || pName.includes("pringles") || pName.includes("batata") || pName.includes("bala") || pName.includes("doce")) {
        return "Snacks";
      }
      if (pName.includes("nespresso") || pName.includes("café") || pName.includes("cafe") || pName.includes("cápsula") || pName.includes("capsula") || pName.includes("chá") || pName.includes("cha")) {
        return "Cafés / Especiais";
      }
      return "Outros";
    };

    // Mapeamento de DDD para UF (fallback inteligente para cadastros sem UF)
    const inferStateFromPhone = (phoneStr) => {
      if (!phoneStr) return null;
      const clean = phoneStr.replace(/\D/g, "");
      const ddd = clean.startsWith("55") ? clean.slice(2, 4) : clean.slice(0, 2);
      const dddNum = parseInt(ddd, 10);
      if (isNaN(dddNum)) return null;
      if ([21, 22, 24].includes(dddNum)) return "RJ";
      if (dddNum >= 11 && dddNum <= 19) return "SP";
      if ([31, 32, 33, 34, 35, 37, 38].includes(dddNum)) return "MG";
      if ([27, 28].includes(dddNum)) return "ES";
      if (dddNum >= 41 && dddNum <= 46) return "PR";
      if (dddNum >= 47 && dddNum <= 49) return "SC";
      if (dddNum >= 51 && dddNum <= 55) return "RS";
      if (dddNum === 61) return "DF";
      if ([62, 64].includes(dddNum)) return "GO";
      if ([71, 73, 74, 75, 77].includes(dddNum)) return "BA";
      if ([81, 87].includes(dddNum)) return "PE";
      if ([85, 88].includes(dddNum)) return "CE";
      return null;
    };

    const stateMap = {};
    const categoryTotals = {
      "Cervejas": { category: "Cervejas", revenue: 0, units: 0 },
      "Refrigerantes": { category: "Refrigerantes", revenue: 0, units: 0 },
      "Águas": { category: "Águas", revenue: 0, units: 0 },
      "Snacks": { category: "Snacks", revenue: 0, units: 0 },
      "Cafés / Especiais": { category: "Cafés / Especiais", revenue: 0, units: 0 }
    };

    let totalRevenue = 0;
    let totalItems = 0;

    for (const ord of orders) {
      const ordAmount = Number(ord.totalAmount) || 0;
      totalRevenue += ordAmount;

      // Localiza reserva correspondente
      const resMatch = reservations.find(r =>
        (ord.reservationCode && r.code === ord.reservationCode) ||
        (ord.reservationId && String(r.id) === String(ord.reservationId))
      );

      // Localiza hóspede cadastrado
      const cleanDoc = (ord.guestDocument || resMatch?.guestDocument || "").replace(/\D/g, "");
      const cleanPhone = normalizePhone(ord.guestPhone || resMatch?.guestPhone || "");
      const guestMatch = guests.find(g =>
        (resMatch?.guestId && g.id === resMatch.guestId) ||
        (cleanDoc && (g.documentNumber || g.document || "").replace(/\D/g, "") === cleanDoc) ||
        (cleanPhone && cleanPhone.length >= 8 && normalizePhone(g.phone || "") === cleanPhone)
      );

      // Determina Estado e Cidade com cascata: Hóspede -> Reserva -> FNHR -> DDD -> Outros
      let state = (guestMatch?.state || guestMatch?.uf || resMatch?.guestState || "").trim().toUpperCase();
      let city = (guestMatch?.city || guestMatch?.cidade || resMatch?.guestCity || "").trim();

      if (!state && resMatch?.guests?.[0]) {
        state = (resMatch.guests[0].state || resMatch.guests[0].uf || "").trim().toUpperCase();
        if (!city) city = (resMatch.guests[0].city || resMatch.guests[0].cidade || "").trim();
      }

      if (!state) {
        state = inferStateFromPhone(ord.guestPhone || resMatch?.guestPhone) || "Outros";
      }

      if (!stateMap[state]) {
        stateMap[state] = {
          state,
          ordersCount: 0,
          totalAmount: 0,
          totalUnits: 0,
          cities: {},
          categories: {
            "Cervejas": { revenue: 0, units: 0 },
            "Refrigerantes": { revenue: 0, units: 0 },
            "Águas": { revenue: 0, units: 0 },
            "Snacks": { revenue: 0, units: 0 },
            "Cafés / Especiais": { revenue: 0, units: 0 },
            "Outros": { revenue: 0, units: 0 }
          }
        };
      }

      stateMap[state].ordersCount += 1;
      stateMap[state].totalAmount += ordAmount;

      if (city) {
        stateMap[state].cities[city] = (stateMap[state].cities[city] || 0) + ordAmount;
      }

      // Processa itens do pedido
      for (const it of ord.items || []) {
        const qty = Number(it.quantity) || 0;
        const itPrice = Number(it.totalPrice) || 0;
        totalItems += qty;
        stateMap[state].totalUnits += qty;

        const cat = getProductCategory(it.productId, it.productName);
        if (stateMap[state].categories[cat]) {
          stateMap[state].categories[cat].revenue += itPrice;
          stateMap[state].categories[cat].units += qty;
        } else {
          stateMap[state].categories["Outros"].revenue += itPrice;
          stateMap[state].categories["Outros"].units += qty;
        }

        if (categoryTotals[cat]) {
          categoryTotals[cat].revenue += itPrice;
          categoryTotals[cat].units += qty;
        }
      }
    }

    // Ranking de estados ordenado por faturamento
    const byState = Object.values(stateMap)
      .map(s => {
        const topCity = Object.entries(s.cities).sort((a, b) => b[1] - a[1])[0]?.[0] || null;
        return {
          state: s.state,
          ordersCount: s.ordersCount,
          totalAmount: Number(s.totalAmount.toFixed(2)),
          totalUnits: s.totalUnits,
          topCity,
          categories: s.categories
        };
      })
      .sort((a, b) => b.totalAmount - a.totalAmount);

    // Categorias consolidadas
    const byCategory = Object.values(categoryTotals).map(c => ({
      category: c.category,
      revenue: Number(c.revenue.toFixed(2)),
      units: c.units,
      percentage: totalRevenue > 0 ? Number(((c.revenue / totalRevenue) * 100).toFixed(1)) : 0
    })).sort((a, b) => b.revenue - a.revenue);

    const leadingState = byState[0]?.state || "N/A";
    const leadingCategory = byCategory[0]?.category || "N/A";

    res.json({
      success: true,
      summary: {
        totalRevenue: Number(totalRevenue.toFixed(2)),
        totalOrders: orders.length,
        totalItems,
        averageTicket: orders.length > 0 ? Number((totalRevenue / orders.length).toFixed(2)) : 0,
        leadingState,
        leadingCategory
      },
      byState,
      byCategory
    });
  } catch (err) {
    res.status(500).json({ success: false, error: err.message });
  }
});

